window.__SUMMARY_PARTS__=window.__SUMMARY_PARTS__||[];window.__SUMMARY_PARTS__.push([{"i":42000,"as":"研究发现杯状细胞在肠道稳态下会机械性地破坏上皮屏障。杯状细胞肥大加剧了这一效应，并导致肠道通透性增加。结合体内外模型、药理学与基因干扰及理论模型，研究证明这些紧密连接断裂源于细胞间的机械力失衡。形态异质性（如杯状细胞圆形顶端与柱状肠上皮细胞的差异）是引发组织屏障物理断裂的核心因素。","scd":null,"kp":[]},{"i":42001,"as":"研究首次展示了基于4H-碳化硅中硅空位（VSi）的半导体室温微波激射器。通过主动反馈回路提升谐振器品质因数，实现了高于室温的连续波激射。在110 K下测得增益超过10 dB，仿真显示潜在放大可超30 dB。该激射器具有超窄线宽，支持高灵敏度磁力测量，使对比度与线宽的比值提升了九个数量级，并可作为微波光子吸收器降低模温度。","scd":null,"kp":[]},{"i":42002,"as":"研究在锰氧化物Sm1-xSrxMnO₃的外延薄膜中实现了电驱动的可逆反变磁转变。当施加的电流超过临界阈值时，系统会从低电阻的铁磁态突然切换至高电阻的反铁磁态；移除电流后系统恢复至铁磁态。这一发现通过实验证实了利用电流控制不同磁相（铁磁至反铁磁）之间的直接转变，为自旋电子学和高密度信息存储技术提供了新途径。","scd":null,"kp":[]},{"i":42003,"as":"研究利用机械互锁分子架构实现了对圆偏振发光（CPL）的力学控制。研发的轮烷基机械力敏团包含一个带有CPL活性螺烯发光体的环和一个匹配的淬灭剂轴。将该机械力敏团共价引入双网络凝胶的交联点后，通过施加机械力可逆地使发光体与淬灭剂分离或结合，从而实现CPL信号的开启和关闭切换。","scd":null,"kp":[]},{"i":42004,"as":"研究利用共晶锂化学构建了一种高压无膜锂-有机混合液流电池。该电池采用双相电解液：底相阳极液由六氟磷酸锂和三氟乙酰胺形成的深共晶溶剂构成，具有4.81 V的电化学稳定窗口、13.8 cP的低粘度和8.59 mS·cm⁻¹的高离子浓度；顶相阴极液为含长烷基链吩噻嗪衍生物的二氯甲烷。这种无膜设计兼具优异的氧化还原可逆性和相间稳定性。","scd":null,"kp":[]},{"i":42005,"as":"研究通过在二氧化铈（CeO₂）晶格中掺入钆（Gd），显著提高了钌（Ru）和铑等过渡金属在萤石氧化物中的固溶度。这种方法促进了高度分散的金属纳米颗粒（约3 nm）的析出，并牢固嵌入氧化物载体中。该析出机制赋予了纳米催化剂极高的抗烧结稳定性，在氨裂解制氢反应中表现出增强的催化活性和耐久性。","scd":null,"kp":[]},{"i":42006,"as":"研究通过在单相中红外非线性光学晶体[Hg₃Se₂][ZnCl₄]中进行层次有序编辑，打破了二次谐波产生（SHG）效率、双折射率和激光损伤阈值（LIDT）之间的传统权衡限制。与改变化学成分的传统方法不同，该研究在固定化学组成下调整结构的层次排列，从根本上优化了材料的非线性光学性能，为开发高性能红外光学晶体提供了新范式。","scd":null,"kp":[]},{"i":42007,"as":"研究表明高疏水性石墨二炔（GDY）框架可在高湿度环境下稳定捕获挥发性有机物。动态穿透实验显示，在50%相对湿度下，GDY仍保留了大于98%的甲苯吸附量（102.5 mg/g），并具有优异的循环稳定性，克服了传统碳基吸附剂在潮湿条件下容量流失的弱点。分子模拟揭示其sp-C键引起的电子密度重分布促进了不受水分干扰的π-甲基静电相互作用。","scd":null,"kp":[]},{"i":42008,"as":"研究开发了一种基于钌(II)的舒尼替尼酰肼络合物，能够引发不依赖活性氧（ROS）的免疫原性细胞死亡（ICD）。该络合物通过多管齐下的蛋白质结合机制，抑制了NF-κB信号传导（降低p65磷酸化并阻止其核转位），抑制VEGFR2磷酸化，并降低端粒酶活性。这种独立于ROS机制的ICD诱导策略，突破了传统金属药物依赖ROS引发内质网应激的致癌信号级联问题。","scd":null,"kp":[]},{"i":42009,"as":"研究评估了果蝇中35种带有不同启动子的Cas9构建体，并分析了启动子相关基因的单细胞RNA表达模式与归巢基因驱动性能的关联。结果表明，较高的驱动转化率与生殖细胞中启动子的高表达相关；而胚胎抗性等位基因的形成与雌性生殖系过度表达有关。早期雄性生殖系表达能产生更佳的驱动性能。这为寻找最佳Cas9启动子以优化基因驱动系统提供了明确标准。","scd":null,"kp":[]},{"i":42010,"as":"研究系统分析了广泛存在于细菌、古菌和真核生物中的dGTPase同源物，鉴定出一类能组装成稳定的八聚体及更高级寡聚结构的细菌dGTPase。通过冷冻电子显微镜解析了代表性弧菌dGTPase（Vdg）的八聚体、16聚体及丝状结构。功能实验证明，这些特殊的寡聚组装结构在细菌中负责介导广泛的抗噬菌体防御机制。","scd":null,"kp":[]},{"i":42011,"as":"研究在内源性DICER1基因的RNase IIIa（S1344L）和RNase IIIb（D1709N）催化结构域中引入热点突变。实验表明，这两种突变均导致5p miRNA广泛缺失，并使3p passenger链更多地载入AGO2蛋白。由于S1344残基在结构上靠近RNase IIIb催化中心，导致两者突变产生相似的病理效应。此外，这些miRNA组的改变进一步增加了HERVH逆转录转座子的活性。","scd":null,"kp":[]},{"i":42012,"as":"研究解析了钩端螺旋体内鞭毛丝的完整原子结构，揭示了由9到12种不同非对称排列的蛋白质组成的精密外鞘。构成丝状体核心的鞭毛蛋白变体决定了外鞘的组成，进而产生从~3.5 µm⁻¹到~5.6 µm⁻¹不等的曲率。这种核心-外鞘耦合机制控制着鞭毛的曲率与机械特性，从而决定了病原菌入侵运动所需的独特运动波和穿透能力。","scd":null,"kp":[]},{"i":42013,"as":"研究发现，状态依赖性物种形成与灭绝（SSE）模型中普遍存在不可识别性问题。由于常用于校正未观测因素的隐藏状态，每一个与性状无关的场景均与无限组与性状相关的场景同构，导致无法进行可靠的假设检验。为此，研究提出了一种解析解决方案，以解决同构类别内的这一不可识别性问题。","scd":null,"kp":[]},{"i":42014,"as":"针对现有局部血统推断（LAI）方法在生物库级数据、远期历史及大量血统分析中扩展性差的问题，研究推出了Gnomix软件套件。该套件包含多种独立的LAI方法，在准确性和计算速度上均优于现有方法，且模型具有可移植性，能够在不暴露个人训练数据的前提下进行共享。此外，Gnomix还配备了Gnofix组件。","scd":null,"kp":[]},{"i":42015,"as":"研究在果蝇的导航中枢发现了一小群局部神经元，在虚拟羽流导航过程中同时具备工作记忆和证据整合功能。这群神经元的活动随着连续的气味遭遇而增强，并在气味消失后可持续一段时间，维持果蝇的既定航向。抑制这些神经元会破坏航向的维持。模拟显示，这种神经元持续时间的恒定值能够优化导航。","scd":null,"kp":[]},{"i":42016,"as":"研究揭示了肝酶ACSS2在代谢功能障碍相关脂肪性肝炎（MASH）进展中的表观遗传调控作用，且该作用独立于其传统的脂肪生成功能。在机制上，ACSS2与赖氨酸乙酰转移酶5（KAT5）形成复合物，驱动组蛋白巴豆酸化，进而上调同种异体移植物炎症因子-1（AIF1）的转录，激活促炎程序，从而推动肝脏炎症的发生和持续。","scd":null,"kp":[]},{"i":42017,"as":"研究发现，长链非编码RNA TRDN-AS的减少会导致心肌和骨骼肌中的TRDN亚型发生异常切换。TRDN-AS的顺式转录对于停滞3'端的RNA聚合酶II、促进心脏TRDN/TRISK32亚型的形成至关重要。m6A甲基转移酶METTL3在此过程中起关键作用，通过促使RNA聚合酶II停滞来实现转录终止和近端多聚腺苷酸化，从而防止心肌疾病。","scd":null,"kp":[]},{"i":42018,"as":"通过结合小鼠纤维的基因靶向技术和人类观察，研究证明了快传导A类伤害感受器在机械伤害性屈曲反射和情感性疼痛中的核心参与。小鼠中光遗传学刺激引发了快速精确的缩回反射及厌恶情绪，而抑制该神经则严重损害了机械伤害性反射。A类伤害感受器的持续激活还会诱导机械性痛觉过敏。","scd":null,"kp":[]},{"i":42019,"as":"","scd":null,"kp":[]},{"i":42020,"as":"针对镁锂混合电池（MLHBs）中正极材料难以协同储存电荷密度和离子半径差异大的离子这一挑战，研究提出了一种双阴离子（Se、O）空位工程策略。该策略构建了量子点Ti3C2 MXene异质结构，成功解锁了量子限域、电荷补偿和屏蔽效应，从而实现了超稳定的Mg2+和Li+离子存储，克服了传统单空位策略无法平衡容量和反应动力学的缺陷。","scd":null,"kp":[]},{"i":42021,"as":"在锂二氧化碳电池的放电过程中，二氧化碳发生双电子部分还原生成热力学活泼的Li2C2O4。该物质在随后的充电过程中容易分解，为降低充电过电位和提高电池循环稳定性提供了机会。然而，作为中间体的Li2C2O4容易转化为惰性物质。本研究通过诱导二氧化碳的部分还原机制，成功实现了Li-CO2电池正极运行超过一年的突破。","scd":null,"kp":[]},{"i":42022,"as":"针对质子交换膜燃料电池（PEMFCs）中传统致密离聚物封装会毒化铂催化剂并阻碍氧气传输的问题，研究提出了一种开放式骨架三相界面（TPI）。该架构通过在铂-离聚物基质中引入磺化共价有机框架（SCOF）纳米片作为物理间隔，抑制了离聚物的直接吸附，同时其有序纳米通道和固有孔隙率分别作为专用质子通道和氧气扩散路径，成功实现了脱钩。","scd":null,"kp":[]},{"i":42023,"as":"针对电泳胶体晶体显示器（ECCDs）在低温下开关动力学迟缓的问题，研究开发了一种基于改性深共熔溶剂（MDES）介质和碳壳包裹聚苯乙烯纳米球（PS@C）的宽温低功耗电泳全色显示器。在电场作用下，具有窄尺寸分布和高折射率（约1.67）的PS@C纳米球形成高度有序的3D胶体晶体，模仿孔雀羽毛中的黑色素光子结构，实现了高色彩饱和度的理想阻带。","scd":null,"kp":[]},{"i":42024,"as":"为实现紧凑器件架构下的快速响应和准确光谱解码，研究开发了一种用于计算光谱成像的垂直带隙级联钙钛矿单晶薄膜异质结。该单块MAPbCl3/MAPbBr3/MAPbI3单晶薄膜异质结（约200µm）通过连续溶液外延法制备，集成了波长依赖的吸收深度与阶梯状I型能带排列，实现了片上光谱成像。","scd":null,"kp":[]},{"i":42025,"as":"为解决物理接触分离带来的界面摩擦损耗，研究提出了一种大面积可变形的高熵陶瓷（HEC）增强非接触式摩擦纳米发电机（HEC-TENG）。通过将HEC掺杂的硅胶摩擦层与储电石墨织物和可拉伸碳黑电极集成，建立了一套全面的摩擦电荷调节机制（包括产生、捕获、传输和保留）。该器件实现了90V的非接触式电压输出和450 µA m−2的电流输出，可用于非接触生物力学和雨滴能量收集。","scd":null,"kp":[]},{"i":42026,"as":"生物集成电池不仅可作为医疗设备的电源，还能通过产生局部电场（EFs）和释放治疗性有益产物主动参与治疗。这种基于电池的电化学药物在电刺激、电化学产物介导的治疗和药物输送中具有广泛应用，包括组织再生、癌症治疗、心脏起搏等。该综述概述了生物集成电池的最新进展及其工作机制。","scd":null,"kp":[]},{"i":42027,"as":"研究提出了一种简便的化学气相沉积（CVD）合成路线，利用过渡金属盐液体前驱体，成功合成了由单层MoSe2和WSe2组成的两种异质结构：纯横向异质结构（HS I）和混合横向/垂直异质结构（HS II）。该研究克服了横向尺寸调控及与其他二维材料集成的挑战，展现出强烈的层间激子发射特性。","scd":null,"kp":[]},{"i":42028,"as":"为解决室温钠硫电池中的多硫化物穿梭效应和钠负极不稳定性问题，研究提出了一种双阳离子电解液工程策略。通过将K+引入常规NaPF6电解液，利用K+较大的离子半径和较低的酸性，竞争性地改变了Na+的溶剂化结构，削弱了Na-溶剂间的相互作用并重组了溶剂化外壳。该策略不仅实现了催化多硫化物的转化，还稳定了金属钠负极，从而显著延长了电池寿命。","scd":null,"kp":[]},{"i":42029,"as":"研究证明了微孔退火粒子（MAP）水凝胶内的分子手性在皮肤移植中控制先天性和适应性免疫反应。由L-或D-肽交联的微凝胶组成的MAP支架，能够引导早期抗原呈递细胞（APC）的激活和引流淋巴结中的运输，从而产生不同的T细胞极化特征。混合手性配方（R-MAP）能够降低APC的共刺激信号（MHC II、CD80、CD86），有效调节局部和全身免疫反应。","scd":null,"kp":[]},{"i":42030,"as":"针对固态锂电池（SSLB）在极低温（<-60°C）下运行的挑战，研究设计并制备了电子云均分布的金属有机框架（ECH-MOF）作为固态电解质材料。该材料的金属节点锚定富电子的ClO4-阴离子作为Li+传导位点，带有强吸电子基团的有机配体则促进电子云分布，实现了对温度依赖性较弱的Li+传输，确保了电池在极低温下的稳定运行。","scd":null,"kp":[]},{"i":42031,"as":"针对水系锌碘电池聚合物凝胶电解质界面不稳定及机械强度与离子电导率之间固有权衡的问题，研究提出了一种拓扑调控的交联剂策略。将四臂聚(2-乙基-2-恶唑啉)（4-PEtOx）交联剂整合到两性离子网络中构建了水凝胶电解质。该分子拓扑结构建立了密集且动态的氢键网络，实现了界面和活性物质传输的调控，保障了Zn2+的连续传输。","scd":null,"kp":[]},{"i":42032,"as":"研究提出了一种通用的胶体化学合成策略，通过调节金属与硫族元素前驱体的比例，成功在MoS2、MoSe2、WS2和WSe2四种代表性过渡金属二硫化物（TMDs）中实现了2H和1T'晶相的按需选择性合成。该单一合成策略克服了传统方法在尺寸、厚度和晶相均匀性上的限制，填补了TMD相工程领域的空白。","scd":null,"kp":[]},{"i":42033,"as":"针对液态金属（LM）本征绝缘氧化物外壳的限制，研究开发了一种无需激活的液态金属复合弹性体（ALCE）。利用声空化效应诱导原位合金化，在液态金属纳米颗粒和银纳米线之间建立了坚固的冶金界面。随着溶剂蒸发，焊接组分优先沉降，形成由聚合物富集上层保护的宏观梯度连续导电底层网络，实现了2.4 × 10^4 S cm-1的导电率，适用于对应变不敏感的电子器件。","scd":null,"kp":[]},{"i":42034,"as":"研究提出一种阴离子极性驱动的界面调控策略，以实现高度可逆的锡金属电池。通过在电镀和剥离过程中，利用三氟甲磺酸根离子（CF3SO3-）在锡表面发生强且具有晶面选择性的吸附，有效调控沉积行为。得益于其巨大的本征偶极，该阴离子建立了显著的表面法向界面偶极场，促使Sn(211)晶面优先暴露，从而获得了均匀且致密的锡沉积形貌。","scd":null,"kp":[]},{"i":42035,"as":"研究结合扫描探针测量与第一性原理计算，证实了石墨烯纳米褶皱中存在巨大的本征量子轨道挠曲电效应。在具有纳米级曲率的纳米结构中，弯曲会扰动面外π轨道，从而在经典晶格畸变之外产生量子力学极化和静电调制。研究测得该石墨烯纳米褶皱的极化密度估计高达约4 C m-2，揭示了二维材料中由曲率和应变梯度诱导的量子极化机制。","scd":null,"kp":[]},{"i":42036,"as":"针对神经血管-免疫耦合受损阻碍慢性伤口愈合的问题，研究开发了一种三阶段自适应吸热水凝胶（HMCG），实现近红外照射下程序化、局部化的TRPV1通道激活。该水凝胶通过PVA和TSPBA之间的可逆硼酸酯键结合，具备溶液-气溶胶-凝胶的转变适应能力，支持喷涂操作并可自适应贴合复杂伤口拓扑结构。这种动态行为确保了紧密的生物界面接触，并在刺激过程中实现可控的热调节。","scd":null,"kp":[]},{"i":42037,"as":"研究展示了一种用于二维电子器件的理想范德华介电材料——单晶铍硼酸盐（NH4Be2BO3F2, 简称ABBF）。该材料克服了现有介电材料无法同时兼顾高介电常数和宽带隙的局限，展现出高达39的介电常数和8.1 eV的宽带隙。介电性能测试表明，该材料具有超低泄漏电流，为提升二维晶体管的综合性能提供了理想的介电解决方案。","scd":null,"kp":[]},{"i":42038,"as":"电化学还原NOx反应（eNOxRR）是在温和条件下将NOx转化为无害N2的有效途径，有助于解决氨燃烧排放NOx的问题，实现可持续闭环氨能源系统。然而，在实际排气流的低NOx浓度下，N2的选择性受限于竞争性加氢、析氢反应及低效的中间体转化过程。该研究针对这些局限性，致力于提升低浓度NOx条件下的电化学还原效率与N2选择性。","scd":null,"kp":[]},{"i":42039,"as":"细胞外囊泡作为所有细胞类型分泌的膜结合纳米颗粒，在病理生理过程中发挥关键作用，是生物标志物、组织工程和药物递送的重要载体。囊泡的表面化学决定了其与环境的相互作用。研究总结了工程化改造细胞外囊泡生物界面的化学框架，重点阐述通过遗传和代谢操纵等表面修饰方法，在不破坏囊泡稳定性和功能完整性的前提下，增强其货物递送、靶点特异性、免疫逃逸和示踪能力。","scd":null,"kp":[]},{"i":42040,"as":"可拉伸有机光伏器件的发展受到高光电性能与机械耐久性之间权衡的阻碍，这主要源于共轭聚合物及其共混物复杂的微结构。本综述系统研究了从溶液态聚集到固态形貌以及应变下的动态响应等多尺度微结构演变。研究强调了利用先进的X射线和中子散射技术阐明决定最终固态形貌的溶液聚集结构，为合理控制和表征新兴可拉伸有机光伏材料的微结构提供了指导。","scd":null,"kp":[]},{"i":42041,"as":"研究通过设计手性R/S准二维钙钛矿微腔（R/S-2DPMs），建立了一种手性放大机制，实现了圆偏振激光发射和超快光学螺旋度切换。该平台克服了分子发射体内在手性扰动过小而难以打破对称性并维持螺旋度选择的难题。所得的R/S二维钙钛矿微腔支持单模激光发射，具有极高的品质因数，为太赫兹光子开关和手性敏感量子器件的发展提供了新机遇。","scd":null,"kp":[]},{"i":42042,"as":"受灯塔水母启发，研究通过将人脂肪组织脱细胞直接制备仿生皮肤基质（BSM），并掺入氨基功能化凋亡小体构建了仿生皮肤（BSM@FABs）。该仿生皮肤能够有效逆转细胞衰老、加速细胞迁移并刺激老化伤口的新生血管形成，表现出对成纤维细胞的高亲和力。机制上，该设计通过DAZAP1相分离相关的线粒体代谢重编程，从底层病理生理学角度解决衰老相关的损伤修复障碍。","scd":null,"kp":[]},{"i":42043,"as":"研究提出了一种超薄、无电池的单片集成传感系统，用于无线追踪压力相关生物标志物并实现人机交互。该系统印刷在厚度约36 µm的柔性多孔热塑性聚氨酯（TPU）膜上，展现出162 mm/s的透气率和1230 g/m²/天的透湿率。系统能够对体液中的多巴胺和皮质醇进行分析，检测限低，为实现最小化干扰的个性化情绪管理提供了可行的设备方案。","scd":null,"kp":[]},{"i":42044,"as":"共价有机框架在固态储氢领域的应用需要在孔隙结构、功能化和结构稳定性之间实现精确的合成调节，并确保可扩展性。综述深入探讨了COF合成中的关键瓶颈，如孔隙率与功能化之间的权衡、精确控制多级孔隙结构的难度，以及在保持高氢结合亲和力的同时维持结晶性的挑战。研究强调了将实验室规模进展转化为实际大规模储氢应用所面临的困难。","scd":null,"kp":[]},{"i":42045,"as":"研究从头设计了一种基于多刺花粉的钒人工酶颗粒（VAE-Pollen），通过结合高效的活性氧（ROS）催化活性和免疫启动功能，预防伤口的初次和二次细菌感染。实验与理论证实，花粉的微结构表面能高效捕获细菌，且氧空位的引入调节了钒催化位点的电子构型，显著增强了其多效ROS催化性能。同时，该人工酶能进一步增强细菌清除与免疫防御能力。","scd":null,"kp":[]},{"i":42046,"as":"研究提出了一种新的MOF-玻璃体复合材料设计原理，将UiO-66-NH2纳米颗粒作为线性聚亚胺的动态共价交联剂。通过MOF结合的胺基与聚合物醛基之间形成亚胺键，MOF成为聚合物网络的基本结构节点，从而制备出独立、具有高耐溶剂性的复合薄膜，同时MOF保持了其结晶度。这种结构使材料具备超越传统MOF-聚合物复合材料的可修复和后可编程特性。","scd":null,"kp":[]},{"i":42047,"as":"针对钠离子电池快充过程中金属钠析出和界面退化带来的安全挑战，研究建立了一个定量机械-电化学耦合框架，将宏观压力信号与微观电极反应联系起来，实现了对钠析出的实时无损诊断。基于此，开发了集诊断-修复-利用于一体的管理策略（DRUMS），使电池管理从被动预警转向主动干预。该策略不仅能早期识别危险金属钠析出，还能进一步进行界面自平整修复。","scd":null,"kp":[]},{"i":42048,"as":"研究开发了一种“受限拓扑转化”策略，直接制备出多组分纳米线气凝胶（MNWAs）。研究揭示了受限界面键合演化竞争机制在贵金属与碲模板相互作用转化中的关键作用。该气凝胶实现了聚对苯二甲酸乙二醇酯（PET）的高效增值转化，其中PdPtRuRhIrTe纳米线气凝胶表现出高达91.7%的法拉第效率和12.05 mmol h-1的产率，展示了其实际应用潜力。","scd":null,"kp":[]},{"i":42049,"as":"无铅介电电容器的发展受到高可恢复储能密度与高击穿强度难以兼顾的制约，传统铁电体过早的极化饱和限制了储能密度的提升。研究展示了一种基于机理引导的协同设计策略，针对铋酸钠钛酸钡等无铅介电材料打破了这一基本限制。该策略有效克服了材料在强电场下的极化饱和问题，实现了储能性能的突破。","scd":null,"kp":[]},{"i":42050,"as":"针对椎间盘退变（IVDD）早期过度氧化应激与晚期细胞衰老及铁死亡的问题，研究开发了一种病理响应型自组装水凝胶。该水凝胶利用退变过程中动态变化的分解代谢酶活性，在识别到病理升高的MMP13时发生响应，实现抗氧化分子和生物活性细胞外囊泡的按需递送。该系统能够进行时空控制的囊泡释放与氧化还原调节，有效恢复髓核细胞的细胞外基质修复能力。","scd":null,"kp":[]},{"i":42051,"as":"研究提出了一种计算驱动的多模态水凝胶平台，用于脑缺血卒中后的组织修复。该系统整合了经计算筛选的全新促血管生成肽支架和表面工程化修饰的炎症响应型导电MXene纳米片。这种合理的表面工程解决了MXene材料不稳定的关键瓶颈，使其胶体稳定性保持超过2个月，并维持1.2 mS/cm的高电导率。该平台能够整合机械、电和生化信号，精确调节多条信号通路以引导组织再生。","scd":null,"kp":[]},{"i":42052,"as":"研究通过分析大量铜基超导体（铜酸盐）的光学电导率和电阻率数据，揭示了“奇异金属”态下线性温度依赖电阻率背后的普朗克弛豫速率（1/τ）的普适性。结果表明，要实现普适的1/τ，只需方形光学等离子体频率在整个空穴掺杂范围内与掺杂浓度成线性比例。这一发现解决了普适弛豫速率与强掺杂依赖电阻率之间的实验矛盾，阐明了高Tc超导态的耗散机制。","scd":null,"kp":[]},{"i":42053,"as":"","scd":null,"kp":[]},{"i":42054,"as":"","scd":null,"kp":[]},{"i":42055,"as":"","scd":null,"kp":[]},{"i":42056,"as":"","scd":null,"kp":[]},{"i":42057,"as":"","scd":null,"kp":[]},{"i":42058,"as":"","scd":null,"kp":[]},{"i":42059,"as":"","scd":null,"kp":[]},{"i":42060,"as":"","scd":null,"kp":[]},{"i":42061,"as":"","scd":null,"kp":[]},{"i":42062,"as":"","scd":null,"kp":[]},{"i":42063,"as":"","scd":null,"kp":[]},{"i":42064,"as":"","scd":null,"kp":[]},{"i":42065,"as":"","scd":null,"kp":[]},{"i":42066,"as":"","scd":null,"kp":[]},{"i":42067,"as":"","scd":null,"kp":[]},{"i":42068,"as":"","scd":null,"kp":[]},{"i":42069,"as":"无钒钠超离子导体型Na3MnTi(PO4)3（NMTP）因其原料丰富且环保，被视为极具前景的钠离子电池正极材料。然而，Mn2+占据钠空位所产生的本征反位缺陷会严重恶化锰的氧化还原动力学，导致电压滞后和倍率性能不佳。研究通过合理设计靶向锂离子占位，有效抑制了该反位缺陷的形成，成功解锁了无钒NASICON正极的超高倍率性能。","scd":null,"kp":[]},{"i":42070,"as":"固氮酶和类固氮系统在氮、碳、硫和能量代谢中扮演不同角色，其根本区别在于结构和金属辅基。新发现的类固氮系统使用了从简单的[4Fe-4S]簇到类似于FeMo-co的复杂簇等金属辅因子。该综述详细描述了类固氮系统在三个生命域中的功能、结构、催化机制和调控机制，并总结了固氮酶光谱技术的最新进展。","scd":null,"kp":[]},{"i":42071,"as":"立体化学结构复杂且富含sp3杂化的环丙烷因其独特的三维结构和抗代谢特性在药物发现中极具吸引力。现有的不对称环丙烷化反应多使用高能试剂且受限于特定卡宾。该研究报道了一种以氯仿作为碳宾（甲基川）等价物、锌作为化学计量还原剂的催化不对称环丙烷化反应，成功合成可进一步功能化的金属环丙烷化合物。","scd":null,"kp":[]},{"i":42072,"as":"研究报道了一种由手性瞬态导向基团和钌η-芳烃催化剂实现的对映选择性C-H活化/氢芳基化反应。该方法能高效合成苯并稠合六元杂环，如色满和氧杂蒽等手性骨架。与传统的钯催化体系不同，该方法在d区金属催化中实现了独特的连续氢芳基化，为生物活性的氧杂蒽和色满衍生物提供了精简的合成路径。","scd":null,"kp":[]},{"i":42073,"as":"光不稳定保护基团在光照下能无试剂恢复官能团活性，但离子对扩散不利时易发生重组反应降低效率。为解决此问题，研究设计了一种能生成三重态基态阳离子（T-PMI+）的新型光保护基团。该设计使重组过程成为自旋禁阻反应，有效提升了去保护效率。这成功证明了利用三重态基态阳离子控制自旋可增强光致去保护作用。","scd":null,"kp":[]},{"i":42074,"as":"为延长铁基光敏剂的激发态寿命以替代贵金属，研究设计了一种引入芘能量受体的铁(III)-多环芳烃偶联物[Fe(LPhPy)2]+。飞秒至纳秒光谱分析表明，该偶联物通过自旋中心分离的电荷分离态（CSS）中间体，依次实现了3*PhPy的布居。这一发现为调节铁配合物的激发态平衡和寿命控制提供了新机制。","scd":null,"kp":[]},{"i":42075,"as":"共价有机框架（COF）结晶过程中，单体的构象偏倚对其结构分化起关键作用。研究提出利用分子构象自由度来同步和传递构象偏倚的策略，成功实现了COF的结构分化。具有高构象自由度的构建基块在晶体成核和生长过程中表现出特定的构象选择和积累效应，这为控制COF的最终结构提供了明确的指导。","scd":null,"kp":[]},{"i":42076,"as":"为应对抗生素耐药性，研究开发了一种无需靶点预设的负选择高通量筛选平台。该平台结合包含320万个环肽的胞内文库与下一代测序技术，通过序列耗竭鉴定抗菌环肽。利用该方法，成功发现了一种能抑制全新必需靶点——铁硫簇载体蛋白ErpA的环肽骨架。该研究为胞内抗菌靶点及相关抑制剂的发现建立了可扩展的框架。","scd":null,"kp":[]},{"i":42077,"as":"熔盐中的拓扑微晶转换（TMC）是制备各向异性钙钛矿颗粒的常用方法，但对颗粒尺寸和长径比的控制仍然不足。为探明反应机制，本研究采用原位监测技术全面审查了整个反应过程。研究表明，对颗粒形貌的精准控制是决定最终材料晶体学织构和力学性能的关键，该工作为高长径比钙钛矿的可控制备提供了机理基础。","scd":null,"kp":[]},{"i":42078,"as":"类沸石金属有机框架（ZMOFs）结合了沸石的结构有序性和网状化学的可设计性，但其可预测构建仍具挑战。研究提出了一种以金属有机螺旋（MOHs）为通用蓝图的构建策略，用于组装类沸石超分子组装体。在分析了具备MOH特征的网络并确立结构先决条件后，成功实验合成了一系列代表性框架（如ZSA-14）。该策略为ZMOFs和金属氢键有机框架的设计提供了新路径。","scd":null,"kp":[]},{"i":42079,"as":"为提升酸性电解液中的析氧反应（OER）催化性能，研究在二氧化锰载体上构建了氧化的钌覆盖层。该材料中还原态的Ru-O-Ru配位实现了氢键的动态切换，使*OH中间体与表面氧形成氢键，而*OOH结合在突出的RuOx簇上。测试表明，该催化剂在10 mA cm-2电流密度下的过电位仅为218.9 ± 0.3 mV，其钌质量活性较商业RuO2提高了2425%。","scd":null,"kp":[]},{"i":42080,"as":"以钯节点为基础的金属有机笼在超分子配位化学中地位重要，但开发新型钯基构建单元十分关键。本研究将具有易接近金属活性位点的{Pd3}簇作为独特构建单元，使其与Cu2单元进行一锅法共组装，成功制备出Pd24Cu12笼状结构。该笼具备开放的三钯节点，在选择性催化加氢反应中展现出优异的性能，拓展了金属有机笼的应用潜力。","scd":null,"kp":[]},{"i":42081,"as":"机械化学活化在软聚合物中研究广泛，但在高模量玻璃态热固性聚合物中的行为尚不明确。研究考察了直接聚合制备的聚双环戊二烯网络中的螺吡喃（SP）机械力响应基团。定量分析表明，在弹性区域内不发生机械力活化，活化现象仅在超过屈服点后出现。该研究系统量化了材料环境对机械力响应基团活化的影响，揭示了聚合物网络中的分子运动和连接性机制。","scd":null,"kp":[]},{"i":42082,"as":"三维共价有机框架（3D COFs）中的互穿现象通常被视为组装的被动结果。研究通过构建一系列具有不同取代基（-OMe、-OEt、-OiPr）的同网状3D COFs，证明了互穿网络是可以调控的设计参数。实验显示，降低互穿度（从5倍到2倍）能重塑孔隙结构，显著增大孔径并提高可及表面积。最小互穿的框架还表现出独特的顺式亚胺构象和动态结构变化。","scd":null,"kp":[]},{"i":42083,"as":"传统聚哌嗪酰胺纳滤膜在分离一价/二价阳离子时受限于强负电性和筛分精度不足。研究提出一种协同表面活性剂调控与溶剂处理的策略来工程化聚酰胺网络。表面活性剂辅助界面聚合形成了均匀致密的初生网络，随后的溶剂处理选择性地去除了网络内截留的低聚物，优化了网络结构，从而实现了高效的一价与二价离子分离。","scd":null,"kp":[]},{"i":42084,"as":"研究报道了一种基于聚对二氧环己酮-co-聚乙二醇（PPDO-co-PEG）共聚物的组织贴片材料，用于湿润组织的快速闭合。该共聚物被设计为具有刚柔转变特性，骨架上接枝了N-羟基琥珀酰亚胺（NHS）作为粘附官能团。PPPD链段的半结晶结构增强了内聚强度，而PEG链段在生理条件下提供链段移动性，使NHS能穿透不规则组织界面并与表面官能团反应，实现可靠密封。","scd":null,"kp":[]},{"i":42085,"as":"不饱和醛的选择性氧化制酸因产物选择性难控而极具挑战。研究提出在经吡啶修饰的Keggin型磷钼钒杂多酸催化剂上，利用电热催化过程实现（甲基）丙烯醛的选择性氧化。研究发现，施加在催化剂床上的电场方向显著影响催化选择性（最高差异达14%），这归因于电场改变了材料的氧化还原性质、表面吸附/脱附行为及活性位点取向。分析表明Mo6+和V5+的还原是关键因素。","scd":null,"kp":[]},{"i":42086,"as":"19F磁共振成像（19F MRI）能实现无背景信号的靶向成像，含液态氟代分子的纳米乳剂可增强信号，但稳定性有限且表面弹性难以控制。此外，响应型探针常依赖顺磁性过渡金属。本研究通过调节乳液纳米颗粒核心的流动性，开发出稳定且无过渡金属的响应型19F MRI探针，克服了传统依赖氧化硅或聚合物表面涂层稳定化的缺陷。","scd":null,"kp":[]},{"i":42087,"as":"碳到氮的原子嬗变反应为直接进行氮扫描提供了可能，但传统的叠氮前体存在毒性和爆炸隐患。本研究报道将亚磺酰亚胺作为可光激活的氮宾前体，应用于三种机理不同的C-to-N嬗变反应中。与叠氮化合物相比，亚磺酰亚胺介导的反应效率相当或更高，且反应时间缩短、可扩展性提升。这些前体可通过多种官能团（包括C-H官能化）制备，实现了更安全的C-to-N置换。","scd":null,"kp":[]},{"i":42088,"as":"基于超极化水的溶解动态核极化技术能大幅增强生物分子核磁共振信号，但极强的水信号会掩盖大部分1H光谱，导致非同位素富集的核酸等目标难以应用。本研究引入了一种基于奇异值分解的后处理策略，能选择性地去除掩盖信号的超极化水贡献，同时完整保留生物分子的核磁共振信号。该方法成功揭示了DNA的共振信号，拓展了dDNP在生物大分子中的应用。","scd":null,"kp":[]},{"i":42089,"as":"胆甾相液晶（CLCs）作为光子材料具有可调的布拉格反射，但平面膜的视角依赖性和乳液的加工限制阻碍了其实际应用。本研究开发了基于多响应CLC乳液的材料，通过放射状螺旋组织生成各向同性（视角独立）的结构色。优化后的活性液晶配方包含响应温度、化学分析和光的官能团。最终制备的液晶液滴嵌入聚合物基质中，形成了机械稳固的薄膜和可打印油墨。","scd":null,"kp":[]},{"i":42090,"as":"研究提出了一种金属催化的环状氨基甲酸酯（CCs）配位-插入开环聚合（CI-ROP）新方法。该方法克服了传统离子型开环聚合中单体范围有限、聚合物摩尔质量低及缺乏化学选择性的挑战。通过结合单体设计与催化体系，该方法能够可控且具化学选择性地合成具有特定结构的聚氨酯（PU），包括仅由单一单体制备的线性、环状、共聚和交联结构，实现了对聚氨酯结构的精确控制。","scd":null,"kp":[]},{"i":42091,"as":"本文综述了用于牙科、骨科和支架等人工假体应用的氧化锆基光聚合3D打印技术。该技术凭借氧化锆出色的机械性能和生物相容性，在患者个性化定制方面极具潜力。文章探讨了相关的功能要求、关键加工参数、后处理步骤及质量关键变量，并指出了从实验室工艺优化到临床性能验证、可重复性和长期可靠性之间的差距是当前面临的主要瓶颈。","scd":null,"kp":[]},{"i":42092,"as":"","scd":null,"kp":[]},{"i":42093,"as":"研究描述了一种利用钯催化[2.2.1]桥联双环反布雷特烯烃（ABO）的成环反应。反布雷特烯烃因处于小环系统中而极不稳定，难以用于化学合成。该反应通过钯催化将原位瞬时生成且浓度极低的ABO与吲哚类捕捉试剂结合，成功合成了不寻常的杂环产物。研究还报道了该反应的底物适用范围，并对推测的钯结合中间体进行了计算化学分析。","scd":null,"kp":[]},{"i":42094,"as":"为精确控制聚(3-羟基丁酸酯)的立体结构，研究提出了一种利用对映体纯催化剂的立体控制策略。该策略基于对映体位点控制（ESC）机制和催化剂对映体间的聚合物交换，克服了传统调节单体过量或合成不同催化剂等方法的复杂性。研究使用了手性纯的DiMeBiPh-BINOL-salen催化剂，实现了对聚合物立构规整度（直接影响结晶、热学和机械性能）的精确调控。","scd":null,"kp":[]},{"i":42095,"as":"研究开发了一种配体启用的邻近策略，通过双核Cp*Ir(III)配合物催化二氧化碳加氢生成N,N-二甲基甲酰胺（DMF）。传统的单核催化剂需克服高能垒进行分步反应，而该双核催化剂通过空间限制两个金属中心，促进了三种不同底物的协同活化。优化后的双核结构带有 strategically positioned -OH pendant groups，成功将决速步的三分子碰撞转化为动力学上更有利的反应路径。","scd":null,"kp":[]},{"i":42096,"as":"研究报道了两种基于四氮杂环芳烷的大环双硼和四硼多共振热活化延迟荧光（MR-TADF）材料（DPN2B和DPN4B）。通过合理选择硼源和反应条件，实现了一锅法双重和四重硼化反应。在甲苯中，DPN2B和DPN4B表现出峰值在451 nm和442 nm的深蓝色窄带发射，半峰宽分别为22 nm和25 nm。基于这两种材料的溶液加工型有机发光二极管（OLED）展现出纯蓝光电致发光特性。","scd":null,"kp":[]},{"i":42097,"as":"研究提出了一种通过配体调节A位阳离子反应性来稳定锡卤化物钙钛矿纳米晶体的新策略。传统的增强Sn2+稳定性的策略不可避免地面临晶格Sn空位形成和表面Sn2+暴露之间的权衡。通过选择性抑制A位阳离子反应性，在结晶过程中高效掺入Sn2+。这一超越了单纯围绕Sn2+的策略，有效解决了锡基钙钛矿在无铅光电应用中因快速氧化降解而受到严重阻碍的问题。","scd":null,"kp":[]},{"i":42098,"as":"研究揭示了在甲醇水蒸气重整反应中，水的作用并非总是起促进作用，而是存在依赖于金属尺寸的效应反转现象。在富含羟基的CeO2负载的Pt纳米颗粒上，水活化产生的表面羟基会吸取Pt的电子密度，削弱CO吸附并缓解CO中毒，从而提高催化活性。相反，在羟基贫乏的Al2O3负载的Pt或Pt单原子催化剂上，水的促进作用消失。这一发现打破了水在该反应中具有普遍促进作用的假设。","scd":null,"kp":[]},{"i":42099,"as":"研究开发了一种高效、实用且廉价的方法，将稳定同位素（氘或13C）引入有机分子中。该方法使用同位素标记的甲醇衍生O-烷基异脲作为试剂，可用于药物分子的d3-甲基化、13C-甲基化和13CD3-甲基化。引入同位素标记可以在不改变药物分子结构和功能的情况下直接对其进行追踪，有效解决了制药工业中缺乏高效、实用甲基化试剂的问题。","scd":null,"kp":[]},{"i":42100,"as":"研究采用同源分子构建策略，开发出无需加工添加剂的高效稳定全聚合物太阳能电池。通过使用共享相同联噻吩酰亚胺结构单元的给体和受体聚合物，增强了分子间相互作用，提高了分子有序度并抑制了能量损失。该设计解决了全聚合物太阳能电池形貌无序和给体-受体相容性差的问题。最终器件实现了0.94V的开路电压和12%的能量转换效率，可直接与储能和转换系统匹配。","scd":null,"kp":[]},{"i":42101,"as":"研究提出了一种基于激发态构象动力学的新型分子设计策略，实现了可见光激发的近红外超长有机磷光（NIR-UOP）。优化的分子py-2mNO2在635 nm和700 nm处表现出NIR-UOP发射，磷光强度高达12 cd/m2，寿命为268 ms。机理研究揭示，动态构象电荷转移机制是实现可见光（λex = 450 nm）激发和高效近红外磷光发射的关键，该纳米组装体在生物成像领域具有应用潜力。","scd":null,"kp":[]},{"i":42102,"as":"研究结合环境透射电子显微镜（ETEM）测量与催化数据，定量描述了Pt/CeO2催化剂中Pt纳米颗粒重新分散为单原子的结构动力学。通过监测特定CeO2纳米立方体上Pt纳米颗粒的衰减过程，并结合密度泛函理论（DFT）建模，深入揭示了其动态行为和动力学机制。这一突破使得利用动力学数据预测纳米颗粒的催化性能成为可能，代表了催化剂结构动力学研究的重大进展。","scd":null,"kp":[]},{"i":42103,"as":"研究提出了一种模块化合成策略，设计了六种带有磺酸基 headgroup 的新型生物功能表面活性剂（SupraVir）。这些两亲分子旨在与病毒包膜蛋白产生强相互作用以抑制病毒，并与水溶性苯-1,3,5-三甲酰胺衍生物（BTAs）共组装，生成表面活性剂接枝的超分子聚合物。光谱和显微镜系统研究表明，共组装策略有效调控了分子的形貌和功能，实现了针对HSV-1的多价抑制。","scd":null,"kp":[]},{"i":42104,"as":"研究合成了首个基于氢键的莫比乌斯环状芳纶结构。设计与传统全共轭骨架的莫比乌斯分子不同，该合成大环利用对位连接芳香片段内的分子内氢键来稳定构象，将大环锁定为单扭曲拓扑结构。晶体学分析明确证实了其单扭曲的莫比乌斯几何构型，LOL-π计算支持了大环主链上持续的电子离域。此外，主客体相互作用可诱导该大环发生拓扑异构化现象。","scd":null,"kp":[]},{"i":42105,"as":"研究报道了一种名为“错配交换”的新设计原理，用于高灵敏度和稳健地区分单核苷酸突变（SNP）。该原理通过简单操纵探针和反应产物中错配的数量和位置，驱动链交换并微调特异性，克服了传统Watson-Crick碱基互补配对探针对单核苷酸突变序列选择性低的问题。该策略特别适用于分析含有多个附近SNP的复杂核酸靶标，包括同义SNP的耐受性和簇集驱动基因的或门检测。","scd":null,"kp":[]},{"i":42106,"as":"研究开发了一种在室温下活化非活化芳基氟化物C-F键进行烯醇交叉偶联的催化体系。该反应使用甲基萘基（MeNAP）钯三氟乙酸盐/叔丁基BrettPhos作为催化剂，双(三甲基硅基)氨基锂（LiHMDS）作为碱，实现了原位生成烯醇酯的α-芳基化反应。该反应底物适用范围广，涵盖酮、酯、腈和酰胺烯醇酯。密度泛函理论（DFT）计算表明，锂盐与氟原子的配位在C-F键活化中起到了决定性作用。","scd":null,"kp":[]},{"i":42107,"as":"针对中国聚变工程实验堆（CFETR）的超临界二氧化碳（S-CO2）冷却锂铅包层第一壁（FW）设计，研究开发了一个基于代理模型的热-机械耦合优化框架。该框架集成了第一壁几何形状、热载荷和边界条件作为参数输入，结合热平衡理论、经验关联式和1D/2D混合解析热传导模型，实现了对关键热工水力响应的快速预测。这有效降低了在广阔设计空间内进行高保真模拟的巨大计算成本。","scd":null,"kp":[]},{"i":42108,"as":"研究揭示了肥胖导致的微生物GABA缺乏促进结直肠癌（CRC）进展的机制。肥胖相关肠菌失调耗竭了产GABA的普通拟杆菌，导致肠道内GABA水平降低。微生物GABA通过PI3K-HIF1α途径诱导TPI1表达，其衍生的3-磷酸甘油醛抑制PPP1CA，维持YAP磷酸化，从而限制戊糖磷酸途径并抑制肿瘤生长。肥胖相关CRC患者表现出粪便GABA减少、TPI1表达降低以及代谢重编程现象。","scd":null,"kp":[]},{"i":42109,"as":"基于人群的妊娠队列研究发现，母体血液中异常的免疫适应先于自发性早产（sPTB）数周至数月发生，并能将sPTB病例与足月对照区分开来（AUROC: 0.7）。主要特征包括在孕早期和孕中期对肾上腺素能刺激的免疫细胞反应增强，随后在孕晚期促炎细胞因子产生增加。转录组分析进一步揭示了早产前的母体免疫动力学变化，表明免疫适应不良是导致特发性早产的关键因素。","scd":null,"kp":[]},{"i":42110,"as":"为了解决多共振热活化延迟荧光（MR-TADF）材料因反向系间窜越（RISC）缓慢导致的效率滚降问题，研究开发了三种聚集诱导发光TADF发射体。其中，32PclCBP由吲哚咔唑给体和二苯甲酮受体构建，在掺杂薄膜中展现出极小的单三重态能级差（ΔEST = 0.01 eV）和高达0.88的光致发光量子产率（PLQY）。基于此的高性能天蓝色超荧光OLED实现了最大外部量子效率（EQEmax）的显著提升。","scd":null,"kp":[]},{"i":42111,"as":"通过绿色多组分反应合成了烷基尾长度分别为8、12和16碳的基于3,4-二氢嘧啶-2(1H)-酮(DHPM)的阳离子表面活性剂。通过电导率、表面张力和荧光法确定了其自组装行为，并计算了表面张力降低效率、临界胶束浓度等热力学参数。结果表明，表面活性随疏水性增加而增强，在298.15K下临界胶束浓度从0.067降至0.040 mM。","scd":null,"kp":[]},{"i":42112,"as":"提出了一种基于测深学习的分类框架，利用低分辨率光学图像实时监测喷墨打印薄膜的干燥动力学。该框架通过关联3D表面轮廓与视觉纹理，定义了双组分混合溶剂墨水的三个干燥阶段和单组分溶剂的两个阶段。基于轻量级卷积神经网络，在降采样至115×40像素的灰度图像上实现了99.4%的测试准确率。","scd":null,"kp":[]},{"i":42113,"as":"为解决半导体制造中微量Fe3+污染检测耗时且成本高的问题，开发了一种功能化硅纳米线场效应晶体管(SiNW-FET)。该器件利用混合PEG自组装单分子层，通过醛胺偶联修饰去铁胺B(DFO-B)，形成稳定且高亲和力的螯合界面。此传感器专为半导体级化学品中超灵敏、无标记的Fe3+检测而设计，以替代传统的电感耦合等离子体质谱法。","scd":null,"kp":[]},{"i":42114,"as":"针对SARS-CoV-2的巨噬结构域Mac1进行了抑制剂的设计与结构优化。通过测试ADP/ADP-核糖类似物并共结晶解析结合模式，发现用小烷基取代远端核糖或将腺嘌呤N7替换为碳可显著提升抑制效力。研究最终展示了β-甲基-GS-441524-二磷酸盐作为一种纳摩尔级抑制剂，对人类靶点具有超过1000倍的选择性。","scd":null,"kp":[]},{"i":42115,"as":"研究解析了溶质转运蛋白SLC26A11的结构，结合生化实验和分子动力学模拟，证实其是一种具有双重功能的非典型蛋白，既能作为硫酸盐转运蛋白，也能作为氯离子通道。这种选择性离子转运的机制明确了SLC26A11是难以捉摸的溶酶体硫酸盐外排蛋白。此外，SLC26A11还表现出解耦的离子传输特性。","scd":null,"kp":[]},{"i":42116,"as":"开展了一项II期多中心随机试验(AZTEC)，评估单次(20 Gy)与多次(分3次共24 Gy)立体定向消融体部放疗(SABR)联合抗PD-L1药物阿替利珠单抗治疗晚期三阴性乳腺癌(TNBC)的疗效。54名女性患者参与，主要终点为无进展生存期。结果显示，两种放疗剂量分割方案联合免疫治疗均展现出疗效与可控的安全性。","scd":null,"kp":[]},{"i":42117,"as":"针对住院患者急性肾损伤(AKI)预测假阳性率高的问题，开发了一个双模型大语言模型框架：包含24小时AKI发生预测模型(AKI-PM)和可解释风险归因模型(AKI-RAM)。基于四家中国医院的140,637份住院记录进行训练，AKI-PM在内部验证中表现出优异的预测性能，曲线下面积(AUC)达到0.95。","scd":null,"kp":[]},{"i":42118,"as":"开发了一套集成表面力仪、光学干涉测量和拉曼光谱的多模态原位测量系统，用于研究良溶剂中浓聚合物刷(CPB)界面的分层、分子状态演变和磨损。原位压缩测量揭示了CPB具有包含稀疏、半稀疏、中间和浓缩层的分层结构，每层在力学响应和分子浓度分布上具有不同的转变间隙。拉曼光谱进一步分析了CPB的特征变化。","scd":null,"kp":[]},{"i":42119,"as":"研究发现，使用MRTX1133或Daraxonrasib靶向抑制致癌基因Kras，能招募包括调节性T细胞在内的多种T细胞浸润至胰腺导管腺癌(PDAC)微环境。这种抑制作用提供了一个治疗窗口，使得PDAC对抗CTLA4免疫检查点阻断疗法特别敏感。机制上，抗CTLA4联合疗法能将效应Tregs转录重编程为初始表型，逆转CD8+ T细胞耗竭。","scd":null,"kp":[]},{"i":42120,"as":"提出了一种通过增强电容耦合来促进界面电荷转移的通用策略，以提升生物电子信号的检测。研究设计合成了一种水凝胶生物界面(HBI)，其粘附强度达到约40 kPa，杨氏模量低于50 kPa，且拉伸率超过400%。该HBI能够与多种生物电子器件和组织形成牢固且顺应性的接触，显著增强了界面的电荷转移效率。","scd":null,"kp":[]},{"i":42121,"as":"报道了一种“扭曲-扩展-封闭”策略，用于合成具有轴向手性和构象限制的环状联芳基化合物。该方法以双功能手性N-杂环卡宾(NHC)催化剂介导“平面”联芳基内酰胺的对映选择性开环(扭曲)，引入不同链长的醇扩链(扩展)，最后完成闭环。该法成功合成了9至14元环状联芳基，产率和对映选择性最高均达99%(49个实例)。","scd":null,"kp":[]},{"i":42122,"as":"提出了一种基于光学传感器内计算的无相位依赖型无线数据聚合范式，以缓解物联网数据密集型传输压力。该系统利用由缺陷主导的持久光电导传感器中的光载流子捕获机制，降低了对同步的依赖。在单一通信窗口内，系统能够可靠地聚合相对定时偏移超过信号持续时间120%的非相干光信号，且归一化均方误差低于1.5%。","scd":null,"kp":[]},{"i":42123,"as":"设计了一种原子级工程双位点催化剂(Ni-SA/Cu-NCs)，用于二氧化碳和硝酸根高效电化学共还原合成乙酰胺。该催化剂在掺氮碳基质上具有邻近铜纳米簇的镍单原子。镍位点将CO2转化为CO，铜纳米簇促进C-C偶联形成*CCO中间体并还原硝酸根生成*NH2中间体。这种协同作用实现了快速中间体转移和C-N偶联，高效产出乙酰胺。","scd":null,"kp":[]},{"i":42124,"as":"受榫卯结构启发，通过结构记忆效应和超临界干燥技术，开发了一系列具有互锁框架的Ca2+增强型氨基酸插层层状双氢氧化物气凝胶。该气凝胶抗压强度达40.1-45.5 MPa，克服了传统无机气凝胶的脆性。它能高效去除水中的四环素、甲基橙等多种有机污染物，去除率达95.4-99.9%，并在多次循环后仍保留87%的初始效率。","scd":null,"kp":[]},{"i":42125,"as":"针对笼目金属AV3Sb5中复杂的超导对称性破缺现象，研究证明了环电流序能够诱导出向列性手性d波超导态。环电流诱导的轨道磁化(OM)稳定了一个手性超导通道，这种OM-手性耦合机制适用于由吸引或排斥相互作用驱动的配对。此外，共存的环电流和键序会产生显著的向列性，微量杂质则会导致该状态转变为各向同性s波态。","scd":null,"kp":[]},{"i":42126,"as":"利用小鼠模型探讨了基于抗MARCO和抗PD-L1抗体靶向肿瘤相关巨噬细胞(TAM)的免疫疗法。研究表明，有效的免疫治疗依赖于功能性内体模式识别机制。内体Toll样受体(特别是TLR9)通过调节炎症小体组分的转录，使巨噬细胞对后续靶向治疗产生预条件反应。缺乏TLRs会导致相关巨噬细胞无法响应治疗。","scd":null,"kp":[]},{"i":42127,"as":"开发了一种受布雷菲德菌素A(BFA)控制的系统，能够可逆地阻断和重启高尔基体后运输。利用活细胞成像和电子显微镜等技术，成功可视化了糖基磷脂酰肌醇锚定蛋白(GPI-AP)从高尔基体反面网络(TGN)到高尔基体相关循环内体(GA-REs)的运输过程。观察到GA-REs在摄取GPI-AP时发生扩张，表明其从TGN成熟为REs。","scd":null,"kp":[]},{"i":42128,"as":"提出了一种电驱动连续化学循环工艺，在固体氧化物电解池中通过电化学CO2体系实现丙烷的选择性氧化脱氢。在10 mA cm−2的电流密度下，采用Co3O4修饰的LSCF阳极实现了92.6%的烯烃选择性和14.2%的单程丙烷转化率。这种电流驱动配置将丙烯产率提升至5.11 mmol gtotal−1 h−1，是开路基准的18.5倍。","scd":null,"kp":[]},{"i":42129,"as":"开发了一种名为smACGs的三重碱基编辑器，能够在同一等位基因上同时诱发腺嘌呤、胞嘧啶和鸟嘌呤的突变。通过将工程化脱氨酶和烷基腺嘌呤DNA糖基化酶变体嵌入Cas9结构中生成的smACGmax，在各种序列背景下实现了高达41%的三重碱基转换效率，且保持了较低的RNA脱靶效应。该技术已成功应用于高覆盖度的内源性HBEGF诱变筛选。","scd":null,"kp":[]},{"i":42130,"as":"引入了一种名为PROTEXI的树突状细胞(DC)疫苗平台，通过将肿瘤特异性CD8+ T细胞表位与SARS-CoV-2刺突蛋白的CD4+ T辅助细胞表位共同呈递，利用广泛的抗病毒免疫力来优化肿瘤免疫。在黑色素瘤和乳腺癌小鼠模型中，PROTEXI显著减缓了肿瘤生长，通过促进T细胞浸润冷肿瘤、增加表位扩散，显著提升了细胞毒性T细胞反应和生存率。","scd":null,"kp":[]},{"i":42131,"as":"研究整合了全球120个猪品种的60个长读长和2445个短读长测序样本，构建了包含158,288个缺失、137,493个插入、660个倒位和10,063个重复的结构变异图谱。通过对F6杂交猪家庭的四种组织进行eQTL映射，发现49.01%的表达基因与顺式区域结构变异显著相关。","scd":null,"kp":[]},{"i":42132,"as":"电压门控钠通道SCN2A基因编码Nav1.2并调节突触发育，其变异与自闭症和癫痫相关。利用模拟SCN2A功能丧失的人类前脑类器官研究发现，SCN2A在突触传递开始前的胚胎期皮层发育中，通过独立于突触传递的机制损害了兴奋性和抑制性神经的发生。","scd":null,"kp":[]},{"i":42133,"as":"利用冷冻电镜技术解析了人内向整流钾通道Kir7.1的结构。Kir7.1功能缺陷会导致多种眼部疾病，同时在下丘脑能量稳态相关神经元中受黑皮质素-4受体（MC4R）以G蛋白非依赖性方式直接调控。研究展示了Kir7.1及其与MC4R复合物的结构和功能特性。","scd":null,"kp":[]},{"i":42134,"as":"开发了一种名为CAPO的解耦转录平台，用于在酵母中可预测地控制基因表达。该平台利用合成的CRISPR激活启动子，在向导RNA招募dCas9-VPR前保持沉默。通过改变向导RNA丰度来调节基因，实现了与天然强启动子相当的表达水平、低背景活性，并应用于荧光编程。","scd":null,"kp":[]},{"i":42135,"as":"研究跨越960万平方公里的干旱梯度发现，土壤微生物的高产（Y）、资源获取（A）和抗逆（S）策略对干旱呈非线性阈值响应。当干旱超过临界水平时，S和A策略激增而Y策略锐减。微生物在资源获取和抗逆性上增加的碳分配以牺牲生长为代价，从而影响土壤碳流失。","scd":null,"kp":[]},{"i":42136,"as":"研究评估了黄河流域水电-光伏-风电-抽水蓄能可再生能源基地（HPWP）的潜力。结果表明，该基地每年可替代23.8%的煤电（249.4太瓦时），使能源相关排放减少28.0%，电力行业用水量降低31.5%，并恢复9.0%的生态系统碳储量，实现了能源、水资源与生态的协同平衡。","scd":null,"kp":[]},{"i":42137,"as":"通过机载电磁调查发现，路易斯安那州三角洲平原下方隐藏着一个面积超过10,000平方公里的晚更新世古河口遗迹，其遗留的咸水导致了地下水盐度升高。该地区地下水三维盐度模式与现代特拉华湾河口附近含水层相似，这为过去地质过程留下的盐度印记提供了证据。","scd":null,"kp":[]},{"i":42138,"as":"研究鉴定出清道夫受体BI（SR-BI）是清除细胞毒性游离血红素的关键介质。在急性溶血时，SR-BI能结合血红素并促进肝脏摄取。缺乏肝脏SR-BI的小鼠清除血红素能力受损且致死率增加；通过药物伊马替尼或腺病毒递送上调SR-BI，可有效保护机体免受血红素毒性及溶血损伤。","scd":null,"kp":[]},{"i":42139,"as":"疟原虫在红细胞内繁殖时，其细胞核在共享细胞质中的分裂周期会迅速失去同步性。结合活细胞成像与生物物理模型发现，这种不同步现象是由细胞核对有限细胞资源库的竞争性分配驱动的。标准的自主核周期模型无法解释这一现象，表明这种竞争机制加速了疟原虫的增殖。","scd":null,"kp":[]},{"i":42140,"as":"研究探索了非生物条件下羟基酸与脂肪酸之间的合作相互作用。实验发现，将羟基酸与脂肪酸偶联形成酯类低聚物，不仅降低了脂肪酸的临界聚集浓度，还增加了脂质膜结构的水解稳定性。这证明了在非生物系统中，聚合作用与细胞区室化之间存在互利共生关系。","scd":null,"kp":[]},{"i":42141,"as":"研究使用银(I)交换的Y型沸石作为吸附剂，分离气态氢同位素体混合物。对于初始等比例的三元同位素混合气体，热脱附光谱实现了1:41:175（H2:D2:T2）的富集。该沸石对氚相对于氕的选择性高达244，在液氮温度下表现出极高的分离效率，是核聚变尾气循环的理想候选材料。","scd":null,"kp":[]},{"i":42142,"as":"为提高口服药物的长期依从性，研究人员开发了一种受折纸启发的口服给药剂型。该系统通过几何设计折叠在标准胶囊内，易被吞咽；胶囊在胃中溶解后，该剂型迅速展开为特定构型，从而延长在胃腔内的滞留时间，实现药物的长期持续释放。","scd":null,"kp":[]},{"i":42143,"as":"研究在量子计算机上采用多尺度纠缠重整化拟设（MERA），实施了子系统纠缠熵的全息测量方案。该方案克服了连续量子相变附近有限尺寸效应及测量协议限制的挑战，成功探测了跨越量子相变的强相关量子物质纠缠标度。","scd":null,"kp":[]},{"i":42144,"as":"研究发现，胰腺β细胞可通过黄素单加氧酶3（FMO3）合成氧化三甲胺（TMAO）作为自分泌代谢物。在衰老和糖尿病条件下该机制衰退。敲除FMO3会耗尽细胞内TMAO，激活NF-κB并引发细胞衰老和炎症，导致葡萄糖刺激的胰岛素分泌缺陷及小鼠出现年龄依赖性葡萄糖不耐受。","scd":null,"kp":[]},{"i":42145,"as":"研究构建了一种双向量子模数转换器（QADC/QDAC），实现了离散变量（DV）与连续变量（CV）量子系统之间确定且可逆的量子信息传递。该转换器具有硬件高效的特点，有效克服了单一变量系统在可扩展性和鲁棒性方面的固有挑战，将光子波前与量子比特进行了双向连接。","scd":null,"kp":[]},{"i":42146,"as":"鲍曼不动杆菌的VI型分泌系统效应蛋白VgrG2通过双管齐下的策略逃避宿主免疫。首先，VgrG2在转录水平抑制Csu菌毛的组装，减少细菌被吞噬和识别；其次，它直接激活吞噬细胞内的GTPase Rac1，导致细胞骨架紊乱和过度巨胞饮作用，引发吞噬细胞发生非凋亡性的空泡依赖性死亡。","scd":null,"kp":[]},{"i":42147,"as":"研究开发了一种名为ViscoClamp的多肽水胶生物稳定剂，通过细胞微环境力学稳态重置策略限制细胞周围的粘弹性漂移。该材料能螯合钙离子和晚期糖基化终产物，有效缓冲慢性糖基化带来的力学漂移，同时允许间充质干细胞重塑基质，改善了由于糖基化导致的再生效果受损。","scd":null,"kp":[]},{"i":42148,"as":"提出了一种双曲自适应空间感知多元时间序列异常检测方法。该方法构建自适应双曲预训练框架来提取时空层次特征；通过动态稀疏模块发现图结构并去除拓扑限制，自主定位异常的时空位置进行因果解释；有效提升了工业应用中异常检测的准确性、鲁棒性和可解释性。","scd":null,"kp":[]},{"i":42149,"as":"研究揭示了微量氯离子在驱动过渡金属催化剂结构演变中的积极作用。在NiFe-MOF纳米片上负载NiS2纳米颗粒，利用氯离子的邻近效应促使催化剂原位重建成短Ni-Fe键的致密γ-NiFeOOH相。该机制使析氧反应路径从晶格氧介导转变为氧化物路径，实现了高效耐用的海水直接电解产氢。","scd":null,"kp":[]},{"i":42150,"as":"通过在狄拉克半金属砷化镉（Cd3As2）中掺杂磁性元素锰（Mn），实现了强烈的红外光学非互易性。锰掺杂剂的集体磁序打破了时间反演对称性，消除了狄拉克锥的简并态并形成了磁性韦尔锥。这种方法有效克服了传统材料固有的非互易光学响应较弱的限制。","scd":null,"kp":[]},{"i":42151,"as":"研究利用低温等离子体增强原子层沉积和旋涂技术制备了无机-有机异质介电层(Al2O3/PAA)，成功开发出集传感、存储和处理功能于一体的柔性有机薄膜晶体管。该器件在感存算一体化视网膜形态加速方面展现出优异性能。器件平均迁移率为22.65 cm2 V−1 s−1，对450 nm光的光学响应时间为30 µs，电荷保持时间超过十年，写入/擦除循环超过104次，电响应低至130 ns，并在10 µs下实现稳定的多级编程。","scd":null,"kp":[]},{"i":42152,"as":"面对全球防伪挑战，现有光学标签易复制，而传统物理不可克隆函数(PUFs)制造复杂且读取系统专业化，限制了基于智能手机认证的实际应用。研究提出一种基于材料驱动的新策略，将发光与物理不可克隆性统一于断裂工程聚合物PUFs中。通过无掩模光刻技术打印带有定制图案的多孔聚合物骨架，并利用表面引发的原子转移自由基聚合(ATRP)技术，用铱基配合物进行功能化，实现防伪技术的创新。","scd":null,"kp":[]},{"i":42153,"as":"针对现有微流控振荡器局限于固定多层结构、缺乏灵活性、可重构性和快速响应特性的问题，研究开发了一种基于可变形液态金属(LM)电容的单层微流控脉冲振荡器。该振荡器用于实时控制振荡流，利用液态金属电容能量存储与周围马兰戈尼流之间的相互作用，将存储的界面能转化为流体脉冲。这项技术为芯片实验室平台带来了高级的流体控制功能。","scd":null,"kp":[]},{"i":42154,"as":"在药物设计中，生物电子等排替换是一种在不破坏靶标结合的情况下微调分子性质的有效策略。针对现有计算方法依赖专家定义修饰位点或难以同时调节多种分子性质的局限，研究提出了深度生成模型DeepBioisostere。该模型通过捕获分子图中复杂的关联关系，能够自主选择并替换分子片段，执行端到端的生物电子等排替换，以满足多个目标属性的优化需求。","scd":null,"kp":[]},{"i":42155,"as":"植物的周年生长调节是多年生植物适应越冬的关键性状。研究表明，在菊花中，长期 chilling 主要在茎尖发挥作用，赋予其伸长生长和开花的能力。chilling 伴随茎尖 rib 区基因表达的变化，其中 CmDREBa 基因的表达与从伸长生长到莲座状生长的转变密切相关。chilling 诱导 CmDREBa 表达，进而抑制伸长生长和开花；当温度改变时，该机制协同调控这两个不同的发育程序，实现越冬适应。","scd":null,"kp":[]},{"i":42156,"as":"I型干扰素(IFNs)在临床中面临治疗窗口窄、活性不佳和严重不良反应等障碍。研究指出，IFNs仅在感染前给药提供抗病毒保护，感染建立后无效且诱发明显不良反应。宿主来源的乳酸(LAC)是关键介质，通过膜受体介导的SIRT1上调抑制IFN活性，并与IFNs协同过度激活NF，促进病毒免疫逃逸、削弱IFN疗效并引发炎症风暴和不良反应。","scd":null,"kp":[]},{"i":42157,"as":"人类冠状病毒HKU1在过表达TMPRSS2受体的Caco2细胞中具有高感染性。该病毒在33°C（鼻腔温度）下能够高效复制、形成合胞体并释放感染性子代，但在37°C下毒力减弱。尽管病毒在这两种温度下进入细胞的方式相似，但在33°C下随后的病毒RNA合成增强，释放的病毒颗粒稳定性更高。此外，HKU1对干扰素(IFN)敏感，但其诱导的IFN刺激基因（如IFITMs）的表达受到抑制。","scd":null,"kp":[]},{"i":42158,"as":"气孔关闭是提高植物抗旱性的关键，由离子转运系统调控。研究鉴定了两种质膜电压依赖性钾(K+)通道抑制剂NS5806和UA49。它们能诱导拟南芥气孔关闭，降低保卫细胞K+水平，从而增强抗旱性。这种化学诱导的气孔关闭途径与脱落酸(ABA)不同。K+通道抑制会导致细胞质Ca2+增加，而在K+内向通道突变体中则没有这种现象，揭示了K+通道活性与细胞质Ca2+升高之间的联系。","scd":null,"kp":[]},{"i":42159,"as":"单分子电子器件是超越摩尔定律极限的重要途径，但经典输运模型无法解释包含强共价和弱非共价相互作用的复杂混合界面，限制了分子二极管的发展。研究建立了一个统一的理论模型，能够精确预测高度不对称金属/分子/金属接触的电子输运。通过筛选144种分子结点，研究发现不对称锚定基团引起显著的电子极化，动态吸附态变化决定空间耦合，这种相互作用是驱动电荷整流的微观机制。","scd":null,"kp":[]},{"i":42160,"as":"研究证明层状反铁磁体CoTa3S6表现出可切换的向列序，其标志是电阻率各向异性和光学双折射的出现。该向列态出现的温度T*与系统中的反铁磁转变温度不同，表明其具有独立的对称性破缺机制。这种向列序可以通过面内旋转对称性破缺应变或面内磁场进行调控，并且后者表现出显著的非易失性记忆效应。研究还发现，破缺的三重旋转对称性对这一过程具有关键作用。","scd":null,"kp":[]},{"i":42161,"as":"铁取代的多金属氧酸盐(Fe-POM)因其光敏和电子缓冲能力在光电催化氮还原方面极具潜力，但受限于簇构型及溶解导致的脱落。研究以Fe-POM为“超原子”结构单元，制备了一系列由不同阳离子配体驱动的一维亚纳米线和二维纳米片。这种合成策略具有普适性，可使用三种Keggin型簇作为结构单元。其中，一维亚纳米线在光电催化氮还原中展现出极高的催化活性。","scd":null,"kp":[]},{"i":42162,"as":"这则情报是对恩斯特·海克尔(Ernst Haeckel)从微观到宏伟的各种生命形式素描作品的赞颂和展示。","scd":null,"kp":[]},{"i":42163,"as":"闭环电池回收依赖于将可变的黑粉转化为能媲美商业材料的正极前驱体。这篇综述将浸出液化学、前驱体杂质、化学计量比和形态学与重新合成的正极性能联系起来，概述了湿法冶金正极重合成过程的设计原则，为闭环电池回收提供了理论指导和技术支持。","scd":null,"kp":[]},{"i":42164,"as":"近期，高温下的初步磁场重返超导现象在无限层镍酸盐中得到了显现，该研究探讨了一种通过化学途径来操纵这种磁场重返超导竞争现象的方法。","scd":null,"kp":[]},{"i":42165,"as":"缺陷在理解材料科学中的结构-性能关系中起着至关重要的作用。研究报道了在半哈斯勒化合物中存在一种新型的平面缺陷——填充断层。","scd":null,"kp":[]},{"i":42166,"as":"","scd":null,"kp":[]},{"i":42167,"as":"通过对生长中的寡核苷酸链进行直接的载体重磷酰化，建立了一种精简的寡核苷酸功能化方法。该方法能够实现与双官能醇和核苷的偶联，提供多种末端和内部修饰，改善了官能团的耐受性，促进了试剂回收，并提供了超越现有亚磷酰胺策略的更高灵活性。","scd":null,"kp":[]},{"i":42168,"as":"传统上，水合质子的性质主要通过Zundel和Eigen阳离子两种极限结构基元来解释，但实验红外光谱显示出更动态的特征。研究通过全维量子动力学模拟，深入探讨了H2O⋯H+⋯OH2基元周围溶剂化引起的结构不对称性的作用，揭示了这种不对称性对特征连续吸收带内强度调制的决定性影响，从而解析了水合质子的红外光谱。","scd":null,"kp":[]},{"i":42169,"as":"研究人员正在开发基于大脑类器官的生物计算机，但在此过程中忽略了一个重大的伦理问题：提供生物医学研究组织样本的捐赠者可能并不知道他们的细胞正在被用于制造生物计算机。","scd":null,"kp":[]},{"i":42170,"as":"高容量负极在充放电循环中因体积变化大而寿命受限，而形成富LiF的固态电解质界面(SEI)虽能提升稳定性，但需阴离子进入Li+溶剂化鞘，从而降低离子电导率，影响快充和低温性能。为此，研究开发了一种由LiPF6溶解在共溶剂体系（包含桥接环状醚和结构线性醚）中组成的溶剂桥接电解液，有效缓解了Li+与阴离子的直接相互作用，维持了高离子电导率。","scd":null,"kp":[]},{"i":42171,"as":"手性磷酸与仿生氢源(汉斯酯)结合可用于不饱和化合物的不对称还原，但C-O单键的不对称氢解由于键能高和亲和力弱仍具挑战。研究利用手性磷酸/汉斯酯系统，提出了一种由芳香化驱动的氢键活化策略，用于C-O键的不对称氢解。该方案实现了邻醌单缩酮的动力学拆分，选择因子高达1773，为合成轴手性化合物（如轴手性大麻二酚衍生物）和手性螺环提供了高效途径。","scd":null,"kp":[]},{"i":42172,"as":"研究提出了一种动态配位介导策略，构建了高度稳定的双酰腙连接共价有机框架（COF-LIFM20-Zn），其具有可调的U形五齿锌配位中心。锌离子的动态配位行为通过去金属化和重新金属化实现了U型和W型结构间的可逆转换。实验表明，锌离子去除率达96.2%，重新金属化率高达97.9%，并在三个U-W切换循环中保持可逆性。此外，引入具有不同配位偏好的铜离子可将骨架重编程为J型结构。","scd":null,"kp":[]},{"i":42173,"as":"通过定向进化非血红素铁酶，实现了羧酸衍生物区域发散性和对映选择性的氮迁移，用于合成非典型α-和β-氨基酸。研究对矮牵牛中的酶进行系统评估和迭代工程改造，开发了两种互补的氮迁移酶（ACCONimα和ACCONimβ）。这两种酶能实现优异区域选择性的1,3-和1,4-氮迁移。其中ACCONimα通过酰胺化反应催化了α-氨基酸的高效对映选择性合成。","scd":null,"kp":[]},{"i":42174,"as":"提出了一种基于膜的策略，通过界面静电异质性控制直链淀粉基凝聚物中的多相分离，从而在膜界面附近形成亚室结构。该策略将表面装饰有带负电金纳米颗粒的碗状聚合物囊泡整合到三嵌段聚合物膜中。这一机制成功在人工细胞中再现了生物分子凝聚物中的多相分离特征，弥补了以往研究中对膜相互作用探索不足的缺陷。","scd":null,"kp":[]},{"i":42175,"as":"研究证实，最小投影直径超过分子筛孔径约两倍的庞大荧光分子可通过“向内卷曲”机制，使其尺寸缩小约18-27%，从而进入多种分子筛骨架的亚纳米通道。时间分辨荧光技术、X射线衍射精修和原位电子显微镜观察证实了这一过程。该发现突破了传统的尺寸排阻分子筛分法则，揭示了客体分子进入微孔时的结构适应性。","scd":null,"kp":[]},{"i":42176,"as":"在范德华异质结构中实现了磁振子-激子耦合，揭示了激子发射对抗铁磁自旋序的独特依赖性。研究指出，尽管反铁磁体因零净磁化强度而无法产生调制场，但激子能够选择性地与尼尔型反铁磁磁振子耦合，实现激子发射的调控。该技术利用了反铁磁体无杂散场和自旋动力学快的优势，为通过反铁磁磁振子操控激子提供了有效途径。","scd":null,"kp":[]},{"i":42177,"as":"六氟磷酸锂（LiPF6）在乙二醇二甲醚（DME）等醚类溶剂中表现出异常低的溶解度，其机制源于“解离-溶剂化-再沉淀”过程。虽然LiPF6在高压下具有优异的铝兼容性，克服了双氟磺酰亚胺锂（LiFSI）严重腐蚀铝的缺点，但由于弱介电特性导致的溶解度限制，阻碍了其在锂电池中的应用。这一机制阐明了LiPF6在醚类溶剂中异常溶解反转行为的根本原因。","scd":null,"kp":[]},{"i":42178,"as":"两亲性柱[5]芳烃和柱[6]芳烃在相对的边缘分别带有阳离子甲基铵和烷基取代基，可自组装成孔径和通道长度可调的二维人工水通道。研究表明，大孔隙与高亲脂性的协同效应使得AP-P6A-C10（带十烷基链）通道实现了最高的水渗透率（每秒每个通道约1×10^8个水分子）以及良好的离子排斥效果。这展示了通道结构在脂质双分子层中的构效关系。","scd":null,"kp":[]},{"i":42179,"as":"报道了一种通过二铑氮宾中间体实现的亚磺酰亚胺（SIAs）分子内环化反应，生成了具有手性硫中心的多种芳香杂环化合物。计算与光谱技术被用于探究立体化学与芳香性之间的复杂关系，并揭示了产物独特的电子与几何特征。该反应利用带有N-酰基取代基的SIAs作为氮宾前体构建了新的N-杂原子键，为开发具有药物潜力的手性杂环提供了方法。","scd":null,"kp":[]},{"i":42180,"as":"数学家需要认识到人工智能对该领域产生的影响，并必须迅速采取行动以减轻这些潜在威胁。","scd":null,"kp":[]},{"i":42181,"as":"小鼠研究表明，蛋白质上的化学标签可以作为睡眠剥夺的生物标志物。大脑中存在一种类似“计时器”的机制，能够追踪睡眠状态并预测觉醒时间。","scd":null,"kp":[]},{"i":42182,"as":"采用与CMOS兼容的制造工艺，将发光胶体量子点（QDs）与氮化硅（SiNx）平台结合，成功研制出蓝色ZnSe/ZnS量子点激光器。通过优化量子点设计规则，获得的蓝色量子点的增益指标与成熟的红色及绿色量子点相当。在采用有机/无机双层封装量子点薄膜后，该器件在不同泵浦条件下实现了稳定的激光发射，克服了传统GaN器件需要晶格匹配衬底及光学损耗高的限制。","scd":null,"kp":[]},{"i":42183,"as":"研究发现，约10纳米的上转换纳米颗粒在单次近红外激发下，无需光学或化学调制即可表现出持续的自发闪烁。通过调整敏化剂与发射离子的比例，实现了内在的ON-OFF切换和极低的工作周期（约0.9%）。该纳米颗粒不发生光漂白或统计老化，允许进行88,000次重复定位，从而实现了0.62埃的超高定位精度。这克服了传统荧光团易快速光漂白的限制，实现了多色超分辨率成像。","scd":null,"kp":[]},{"i":42184,"as":"在二维有机-无机杂化钙钛矿中，通过隐藏的自旋-谷锁定效应成功在室温下实现了自旋稳定。研究使用非伯铵阳离子诱导金属卤化物层发生对称性破缺畸变，在保持全局反转对称性的同时产生了巨大的局部自旋劈裂。该实验验证了在没有全局对称性破缺的情况下，利用隐藏自旋极化实现稳定自旋调控的策略。","scd":null,"kp":[]},{"i":42185,"as":"新研究证明，基于在氧化物载体上原子级分散的钌原子的催化剂，能够在温和条件下将废塑料快速转化为喷气燃料成分。该上循环方法有效避免了传统工艺需要高压和长反应时间的缺点，为通过转化塑料废物来助力航空业脱碳提供了新途径。","scd":null,"kp":[]},{"i":42186,"as":"蒸发驱动发电机常受限于非定向流体流动导致效率低下。Wu等人在机器学习的指导下，开发了一种垂直微棒发电机。这种设计显著改善了离子传输（实现准弹道离子传输），从而大幅提高了发电效率和功率密度。","scd":null,"kp":[]},{"i":42187,"as":"人为制造物质的无控制生产和释放对环境造成了巨大影响。作者提出了一个评估这些新型实体长期安全性和环境影响的框架，该框架充分考虑了这些物质庞大的数量、多样性以及它们之间复杂的相互作用。","scd":null,"kp":[]},{"i":42188,"as":"针对藻华对水质安全的严重威胁，本研究开发了一种零价铜微孔过滤系统。该过滤系统能够在不输入任何化学物质的情况下，有效去除水产养殖水中的藻细胞及其他有害污染物，从而推进了可持续的水产养殖发展。","scd":null,"kp":[]},{"i":42189,"as":"理解自然选择有助于改善医疗方案、社会政策和农作物产量。了解进化的原理能够解答诸如“何时应该治疗发烧”等医学问题。","scd":null,"kp":[]},{"i":42190,"as":"结合树种丰富度与卫星衍生的光合作用代理数据，研究发现树种丰富度与当前更高的光合作用水平及长期的光合作用增长密切相关。据预测，到2050年生物多样性的丧失可能导致森林累计损失4.4至35.7 PgC的碳光合量。","scd":null,"kp":[]},{"i":42191,"as":"尽管氢动力能源系统逐渐兴起，但金属材料在高温下与氢的相互作用仍知之甚少。多尺度损伤分析表明，镍基高温合金在高温氢气环境中测试时，表现出的退化机制与近室温条件下完全不同，揭示了高温下氢如何破坏材料的机制。","scd":null,"kp":[]},{"i":42192,"as":"传统上实现光学非互易性需要复杂的超材料、奇异介质或强场。研究人员通过斯托克斯-穆勒形式体系，预测了在常规材料中实现正交线偏振非互易吸收和发射的途径。通过使用具有相当圆和线二向色性的CdS、CdSe和CdTe魔尺寸簇溶液处理薄膜进行测试，成功证明了线性偏振光的非互易吸收和发射现象。","scd":null,"kp":[]},{"i":42193,"as":"本研究开发了一种利用细胞牵引力作为内在触发机制的生物材料递送策略。该材料将适配体构建体附着在生物材料支架上，能够在体内和离体条件下，以远低于现有疗法的剂量，选择性地捕获、浓缩并重新激活来自细胞、损伤部位和血液裂解物的多种内源性生长因子。这种策略无需重组蛋白的超生理剂量或外部刺激，能够安全且经济有效地调节伤口修复。","scd":null,"kp":[]},{"i":42194,"as":"针对能源和交通领域脱碳需求，燃气轮机安全关键部件暴露于高温含氢环境中。现有研究通常基于氢与微观结构缺陷的物理相互作用来解释室温氢脆。本研究指出该理解无法完全涵盖高温下的行为，在典型面心立方镍基高温合金中，空位驱动的氢与特定微观结构成分间的化学反应会显著加剧高温下的材料脆化。","scd":null,"kp":[]},{"i":42195,"as":"非天然光酶能够实现小分子催化难以完成的非对称成键反应，但目前主要依赖于黄素和烟酰胺等可见光吸收能力强且激发态寿命长的辅因子。为探索未被表征的生色团辅因子“暗区”，本研究将吡哆醛5'-磷酸（PLP）确立为一种光酶辅因子。通过解析该辅因子在“暗区”的光物理特性，利用具有不同反应性和选择性的酶类获取新的激发态中间体，从而扩展了光酶可形成的化学键类型。","scd":null,"kp":[]},{"i":42196,"as":"混合卤化物宽禁带钙钛矿在初始成膜时易发生相分离，这是由于富碘和富溴相的不对称成核所致。现有的均质化策略调节所有Pb2+的配位强度，但无法特异性解决溴化铅成核快于碘化铅的问题。本研究引入了选择性配位原理，通过分子偶极子调节路易斯碱硬度，利用硬氧供体优先配位更硬的溴化铅Pb2+，选择性地减缓富溴相的成核并使其与富碘相同步，从而实现相均匀的钙钛矿用于稳定的叠层光伏器件。","scd":null,"kp":[]},{"i":42197,"as":"英国国家同步辐射光源、激光设施和粒子加速器等重要物理设施正面临关闭威胁，除非能够获得新的资金支持，这些设施当前正处于必须商业化或被迫关闭的生存抉择关头。","scd":null,"kp":[]},{"i":42198,"as":"北方森林覆盖了约四分之一的连续永久冻土带，其林冠层为庞大的土壤有机碳（SOC）库提供了热保护。通过基于过程的模型对比发现，林冠缓冲作用维持了约59 Pg的冻结碳，占总森林冻土碳库的32%，远超北方生物量储备。林冠变化可能通过逐渐解冻（40 Pg）和迅速热喀斯特崩塌（19 Pg）调动这些冻结的有机碳。不同树种的林冠具有不同的热绝缘能力，直接影响永久冻土的热动力学。","scd":null,"kp":[]},{"i":42199,"as":"本研究提出了一种基于能源消耗的指标“能源恩格尔系数”，用于衡量家庭用于食物制备的能源占能源总消耗的比例。基于中国全国范围内的家庭调查数据，该指标与地区和家庭特征表现出一致性。与传统的恩格尔系数相比，该指标不仅更准确地反映了低收入家庭在基本需求上花费更高比例的恩格尔定律，而且在与非货币指标（如主观体验）的比较中表现出更强的相关性，为揭示中国农村家庭贫困提供了新方法。","scd":null,"kp":[]},{"i":42200,"as":"氟化醚已被广泛用于提升锂硫电池的比能量和循环寿命等关键性能，但目前缺乏关于不同氟化醚性能提升效果的共识和筛选标准。本研究系统研究了九种氟化醚在代表商业应用条件的锂硫电池中的效果。研究通过电化学测量结合非原位和原位核磁共振（NMR）表征，深入探究了氟化醚化学结构与其在锂硫电池反应中的作用之间的基本构效关系，为锂硫电池电解液的选择提供了基础理论依据。","scd":null,"kp":[]},{"i":42201,"as":"本研究利用电氧化木质素构建了木质素-金属超分子框架复合材料，经碳化制备出 confined 在富氧、氮掺杂木质素碳微环境中的富镍RuNi合金（RuNi@NOLC）。在无膜流动电解槽中，以RuNi@NOLC作为阴极和阳极催化剂，偶联醛氧化与析氢反应。该过程实现了0.76 kWh Nm-3 H2的比能耗和99.5%的甲酸盐法拉第效率，通过界面唐南水化漏斗成功协调了RuNi双金属协同作用，实现了高效的双氢电合成。","scd":null,"kp":[]},{"i":42202,"as":"一名40岁男性ICU患者因耐多药（MDR）病原体引发连续肺部感染，包括鲍曼不动杆菌、肺炎克雷伯菌和嗜麦芽窄食单胞菌。作为抗生素的辅助治疗，患者接受了七轮针对单一或双重病原体的定制噬菌体治疗。结果显示，鲍曼不动杆菌被完全根除，但另外两种病原体因菌株替换和噬菌体抗性出现周期性清除和复发。噬菌体疗法与细菌载量、发热、降钙素原及IL-6水平的降低具有相关性。","scd":null,"kp":[]},{"i":42203,"as":"本研究开发了一种利用具有可调 bulky 构型的三维纳米石墨烯自适应制备非共价多孔晶体的策略。通过带有不同取代基的四咔唑前驱体的Scholl环化反应，获得了含有单侧或双侧弯曲[1,4]二氮辛环结构域的立体纳米石墨烯。利用刚性八元环和柔性咔唑基团构建的多重内在凹面，这些纳米石墨烯能够自组装成具有优异加工性能的非共价多孔晶体，实现了对材料结构的精细控制。","scd":null,"kp":[]},{"i":42204,"as":"针对非氧化物电催化剂在海水电解中因强阳极电位而发生不可避免的表面重构和腐蚀问题，本研究提出了一种阴离子配体钝化策略。利用路易斯酸碱相互作用，在FeNiP载体上生长了一层超薄的欠配位TiOx覆盖层。该覆盖层从晶格磷中提取电子，使P p带中心下移，从热力学上稳定了整个阴离子亚晶格，防止其发生氧化性浸出。这种抗氧化支架成功稳定了磷化物晶格，同时保持了固有的电催化活性，实现了无重构的海水电解。","scd":null,"kp":[]},{"i":42205,"as":"现代物理学的基石之一——洛伦兹不变性，在量子引力理论及包含新矢量或张量场的广义相对论扩展模型中被预言存在违反现象。在弱场极限下，这种违反主要表现为后牛顿参数的一个非零值。研究人员通过LAGEOS和LAGEOS II卫星的激光追踪数据，对局域洛伦兹不变性进行了高精度测试，为检验基本物理定律提供了实验依据。","scd":null,"kp":[]},{"i":42206,"as":"为了探索介子可能在核介质中发生的性质变化，研究人员通过衰变通道测量了介子的不变质量。通过拟合现实光谱函数对测量的不变质量谱进行分析，在低质量区域观察到增强现象，直接测量了介质内的质量谱。","scd":null,"kp":[]},{"i":42207,"as":"研究人员在自旋1型自旋旋量玻色-爱因斯坦凝聚体（BEC）中，利用稳健且可重复的局域相位压印方案，实验生成了类似正弦-戈登的孤子。研究发现，孤子的速度可以通过有效二次塞曼位移进行调节。这一成果使得研究人员能够进一步研究受控的孤子相互作用。","scd":null,"kp":[]},{"i":42208,"as":"共振移相器在旋转复光场时通常会因损耗和耦合而改变光场强度。本研究引入了一种极点-零点合成规则，能够在选定的散射幅值下产生完整的2π相位卷绕，从而实现了在任意振幅下产生恒定振幅的2π相位调制，解决了共振相位调制的振幅波动难题。","scd":null,"kp":[]},{"i":42209,"as":"实验表明Weyl半金属PtBi2的拓扑表面态存在非常规超导性，使其成为本征拓扑超导的候选材料，测量显示费米弧中心存在节点能隙。研究人员推导出一种理论机制，解释了PtBi2表面节点拓扑超导性的形成原理。","scd":null,"kp":[]},{"i":42210,"as":"材料性质的突变会产生时间界面，迫使传播波改变频率同时保持波数不变。与仅具有单一频率-波数对的单原子晶格不同，多原子晶格支持每个波数对应多个频率。本研究探讨了在具有时间界面的多原子声子晶体中的模式守恒与转换机制。","scd":null,"kp":[]},{"i":42211,"as":"在交变磁体中，磁振子能带在没有相对论或偶极自旋相互作用的情况下于倒易空间发生各向异性自旋劈裂。本研究通过理论分析了二维方形晶格d波交变磁体中由自旋-晶格相互作用耦合的磁振子和声子。研究表明，通过磁振子-声子杂化，交变磁体中产生了d波声子角动量纹理。","scd":null,"kp":[]},{"i":42212,"as":"作者Shu Yang等人提出利用光纤环路可实现并模拟源于高能物理领域的现象，具体研究了光子频率链上的非阿贝尔电场与颤振现象。该成果发表于《Physical Review Letters》。","scd":null,"kp":[]},{"i":42213,"as":"作者Tianzhe Zhou等人提出了一种扩展且更完善的量子色动力学（QCD）成核模型。该新模型显式引入了跃迁平衡，并在宏观和微观层面进行了数学表述。该微观表述进一步完善了原成核模型，发表于《Physical Review C》。","scd":null,"kp":[]},{"i":42214,"as":"研究人员利用HYDJET++模型框架，分析了质心系能量从11.5到200 GeV的金金碰撞中多奇异数子的产生过程。研究将这些粒子的产生作为横动量和中心度的函数进行了详细计算，发表于《Physical Review C》。","scd":null,"kp":[]},{"i":42215,"as":"该研究在扩展线性σ模型的框架下，采用平均场近似研究了介子态的手征相结构。研究系统对比了SU(3)和SU(4)对称性下，赝标量、标量、矢量和轴矢量介子态的质量随温度的变化关系，成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":42216,"as":"作者提出了一种用于计算一阶不透明度辐射能量损失的理论体系。该公式体系考虑了具有动态（即移动）成分的有限尺寸量子色动力学介质中，夸克胶子等离子体的空间与时间温度演化，成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":42217,"as":"该研究利用基于手征有效场论的Hartree-Fock模拟器研究了原子核结构，并应用于计算钙同位素（48Ca和52Ca）的电荷半径。该模拟器有效降低了大规模多体计算的成本，解决了低能耦合常数的大规模敏感性分析问题，发表于《Physical Review C》。","scd":null,"kp":[]},{"i":42218,"as":"研究人员利用映射的sdg-IBM模型系统研究了十六极关联对钍、铀和钚原子核（质量数232至240）低能光谱性质的影响。研究的费米子输入数据通过基于四极-十六极约束的Hartree-Fock-Bogoliubov平均场理论获得，成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":42219,"as":"该研究利用机器学习回归方法系统分析了双阿尔法衰变半衰期。双阿尔法衰变是一种敏感探测量子隧穿、核结团和势垒贯穿现象的奇特核衰变模式。尽管该模式在能量上被允许，但仍未被完全实验观测证实，成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":42220,"as":"该研究基于实验数据分析了原子核结合能与电荷半径的比值，发现具有特定质子数和中子数的原子核比值与中子数少2的同位素之间存在线性关系。结合径向基函数方法，该线性关系被用于从结合能中提取原子核电荷半径，成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":42221,"as":"作者研究了重离子碰撞中超子的全局自旋极化现象，通过引入组成夸克之间的自旋关联效应，得出了新的理论结果。现有的超子全局自旋极化和矢量介子自旋排列实验数据为相空间函数提供了约束条件，成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":42222,"as":"该研究展示了可编程机器人通过瓶颈通道的流动实验结果。由于机器人的速度和力可以解耦，实验证实了在没有物理接触和后方推力的情况下，即使发生堵塞，移动速度越快反而会导致整体流速越慢的现象，成果发表于《Physical Review Letters》。","scd":null,"kp":[]},{"i":42223,"as":"作者调查了混合态的非唯一分解对能量转移的影响。在量子理论中，混合态向纯态的分解通常是非唯一的。研究探讨了在构成确定性能量转移的过程中，这种非唯一分解特性所产生的具体作用，成果发表于《Physical Review Letters》。","scd":null,"kp":[]},{"i":42224,"as":"","scd":null,"kp":[]},{"i":42225,"as":"","scd":null,"kp":[]},{"i":42226,"as":"","scd":null,"kp":[]},{"i":42227,"as":"","scd":null,"kp":[]},{"i":42228,"as":"生物记录数据显示，须鲸在进食冲刺时心率会重复性急剧上升以完成杂技般的冲刺吞食，而在过滤阶段心率仅缓慢下降，这与其他潜水动物的心率-活动耦合机制不同。这种极端的屏气运动特征表明其肌肉运动依赖于糖酵解代谢底物。","scd":null,"kp":[]},{"i":42229,"as":"","scd":null,"kp":[]},{"i":42230,"as":"","scd":null,"kp":[]},{"i":42231,"as":"研究在核糖体肽基转移酶中心的序列中发现了一个回文序列，覆盖了大部分核糖体衍生的单体序列。这一发现反驳了早先被认为是“幻觉”的AlphaFold3原核糖体预测结果，并为一条70个碱基的RNA链能够作为单体序列随机出现并自组装成原核糖体提供了简单且可实验验证的分子机制。","scd":null,"kp":[]},{"i":42232,"as":"研究利用2016至2022年高分辨率的地表形变和地下水位测量数据，分析了萨克拉门托谷地含水层系统。结果表明在2020至2022年加州极端干旱期间，含水层大面积区域从可逆的孔隙弹性变形阶段发生了临界转变，进入了不可逆的非弹性变形阶段，造成了永久性的地表沉降破坏。","scd":null,"kp":[]},{"i":42233,"as":"研究结合了日本的大规模多季节鸟类实地调查和跨越四个大洲的全球荟萃分析。通过对比荒废农田、传统农田和集约化农田的鸟类物种丰富度，研究发现主要功能群可以解释全球鸟类多样性对农田荒废的响应差异，为设计农业景观和制定保护策略提供了可预测的通用框架。","scd":null,"kp":[]},{"i":42234,"as":"报道了在肯尼亚北部库比福拉组发现的一处距今约143万年的更新世早期古人类脚印化石群。这些化石遗迹中不同形态的脚印证明了直立人和鲍氏傍人曾同时在相同的湖泊边缘栖息，为了解早期古人类的体型、运动方式和古生物学行为提供了见解。","scd":null,"kp":[]},{"i":42235,"as":"在哥斯达黎加一座热带火山的海拔梯度上，对隐翅虫科昆虫群落的研究发现，随着海拔升高，昆虫的耐热性下降，耐寒性增强，这证实了理论预测。高海拔群落缺乏对气候变暖的耐受力，而低海拔群落已经处于环境温度极限。","scd":null,"kp":[]},{"i":42236,"as":"评估了全球超过16,000个岛屿在2050年前面临的累积威胁。结果显示，气候变化是影响65%岛屿的主导威胁，其次是土地利用变化（22%）和生物入侵（13%）。最容易受到累积威胁影响的岛屿往往更加孤立，凸显了岛屿在全球环境变化前沿的脆弱性。","scd":null,"kp":[]},{"i":42237,"as":"探讨了甲硫氨酸氧化对TDP-43蛋白（肌萎缩侧索硬化症关键蛋白）C端结构域液-液相分离的影响。该区域包含十个甲硫氨酸残基，均匀分布在介导螺旋自组装的保守区和介导相分离的无序区。研究明确了不同区域甲硫氨酸氧化破坏TDP-43相分离的具体分子机制。","scd":null,"kp":[]},{"i":42238,"as":"海洋微生物一直被视为补充海洋难降解溶解有机物（RDOM）的关键。本研究利用基于极性的液相色谱与超高分辨率质谱技术，成功区分了RDOM的异构体簇。研究结果显示，海洋微生物群落能够在不到90天的短时间内，将多种有机底物迅速转化为具有广泛结构异构性的RDOM。这种人工合成的RDOM结构特征与天然海水中的RDOM高度相似，在分子层面上揭示了微生物在快速补充海洋RDOM储库中的核心作用。","scd":null,"kp":[]},{"i":42239,"as":"针对亚洲经济体总生育率（TFR）下降的问题，本研究评估了住房干预政策对刺激生育的有效性。研究探讨了通过信贷援助等方式降低购房门槛，使年轻家庭更容易获得住房所有权的干预措施。研究分析了这些住房干预方法在逆转生育率下降和解决极低生育率问题方面的实际效果。研究结果表明，住房可及性与生育率之间存在关联，为亚洲及欧洲国家制定刺激生育的政策提供了基于住房干预视角的实证参考。","scd":null,"kp":[]},{"i":42240,"as":"PLCβ酶在质膜上裂解PIP2生成IP3和DAG，以调节细胞内钙离子和蛋白激酶C活性。这种水溶性酶通过G蛋白Gβγ和Gαq受GPCR信号调控，充当双刺激的符合检测器。研究阐明了PLCβ酶在水相中合成后，如何分配到膜表面以接触其脂质底物的机制。研究表明，Gβγ依赖性对PLCβ酶的调节，建立在酶被招募到细胞膜及其催化核心在膜表面的空间定向基础之上。","scd":null,"kp":[]},{"i":42241,"as":"在果蝇胚胎发育中，生殖细胞与躯体细胞的命运决定需要空间上的精确协调。研究发现，原始生殖细胞（PGC）的形成依赖于生殖颗粒，其通过促进质膜上PIP2的局部生成来调节肌动蛋白动力学。而后部内胚层决定因子Torso（一种受体酪氨酸激酶）通过激活PI3K将PIP2转化为PIP3，从而拮抗生殖颗粒的活性。PIP3阻止PGC的形成，通过PIP2的双向控制，解决了生殖系与体细胞命运在重叠区域的冲突。","scd":null,"kp":[]},{"i":42242,"as":"为了探究固氮共生的进化起源，研究重点分析了Bradyrhizobium（慢生根瘤菌）。该细菌属包含依赖Nod因子信号通路形成根瘤的经典共生谱系，以及在自由生活状态下固氮的近缘物种。研究人员从非豆科环境中分离出88株带有nif固氮关键基因的菌株，并结合586个公开的Bradyrhizobium基因组数据重构了nif基因的稳健系统发育树。基因分析结果揭示了固氮共生细菌在进化上的最早分歧点与起源机制。","scd":null,"kp":[]},{"i":42243,"as":"植物性饮食通过改变肠道微生物组的代谢产物促进健康。研究发现，难以被宿主消化的植物蛋白与膳食纤维协同作用，改变了肠道微生物的营养供应。同位素示踪实验表明，这种协同作用使微生物代谢谱发生转变：显著增加了苯丙氨酸衍生的有益酚类物质（马尿酸和3-苯基丙酸盐），同时降低了酪氨酸衍生的有害尿毒症毒素（苯酚硫酸盐和对甲酚硫酸盐），揭示了植物饮食改善代谢的具体机制。","scd":null,"kp":[]},{"i":42244,"as":"大脑因极高的能量需求，在营养缺乏时具有能量分配优先权。研究测量了蚂蚁在离体状态下的脑代谢率、脑质量、体重及全身代谢率。结果显示，当蚂蚁面临营养压力时，其分配给大脑的能量比例近乎翻倍，达到全身能量的45%。在全身代谢率显著下降的情况下，大脑代谢率并未出现同等幅度的降低。这表明中枢神经系统能够在营养受限的条件下维持其能量消耗，保障关键的生理功能。","scd":null,"kp":[]},{"i":42245,"as":"缺氧诱导因子（HIF）信号通路对细胞适应低氧环境至关重要。研究鉴定出MORC2是HIF-α的负调控因子。机制研究表明，MORC2与HIF-1α竞争性结合，从而拮抗组蛋白去乙酰化酶4（HDAC4）。当MORC2缺失时，HDAC4被大量招募至HIF-1α，导致HIF-1α在第629位赖氨酸的乙酰化水平降低，阻止了其蛋白酶体降解。利用CRISPR/Cas9技术敲除斑马鱼的morc2基因后，突变体表现出红细胞增多症和HIF通路的组成型激活，证实MORC2在红细胞生成中的调控作用。","scd":null,"kp":[]},{"i":42246,"as":"集约化家禽养殖从根本上重塑了病原体的生态空间。研究分析了来自鸡和野鸟的2,747个空肠弯曲菌基因组。系统发育重建表明，自1900年以来，家禽集约化养殖打破了历史上的宿主-菌株关联，从鸡向野鸟的宿主转移估计增加了100倍。特别是20世纪60年代后，特定克隆分支出现急剧扩张。研究证实，人类农业工业化活动显著加速了空肠弯曲菌这种人畜共患病原体的传播与跨物种演化。","scd":null,"kp":[]},{"i":42247,"as":"帕金森病（PD）的精准管理需要频繁调整左旋多巴（L-dopa）剂量。研究开发了一种佩戴在指尖的柔性可穿戴贴片，用于无创、连续监测汗液中的L-dopa浓度。该平台结合了渗透收集的被动汗液、柔性水凝胶和电位传感技术，并采用个性化校准，无需外部电源或离子导入即可工作。实验证实，汗液中的L-dopa浓度与高效液相色谱法（HPLC）测量的血液浓度之间存在强相关性，实现了无需体力消耗的药效学评估。","scd":null,"kp":[]},{"i":42248,"as":"","scd":null,"kp":[]},{"i":42249,"as":"南极半岛是全球变暖最快且冰川融化最显著的区域。研究通过分析南极半岛陆架16个沉积物岩心的地球化学和同位素记录，结合多媒体汞收支模型，重建了过去200年的汞源-汇动力学。结果显示，尽管南极远离人为排放源，现代南极半岛陆架的汞积累率达到每年93 ± 58 µg m⁻²。研究表明，人为大气沉降与气候变暖的共同作用显著加速了南极地区“大气-冰川-陆地-海洋”的汞循环过程。","scd":null,"kp":[]},{"i":42250,"as":"本研究分析了2015年10月至2026年3月期间美国移民与海关执法局（ICE）的160万份逮捕记录。结果显示，尽管逮捕人数在特朗普两次任期初期激增，但被捕者中有刑事定罪的比例显著下降，尤其是2025年降幅最为明显。战术转变部分解释了这一现象，但在既定战术下，定罪率比例依然随逮捕量上升而下降。研究还发现，尽管犯罪率普遍下降，但ICE执法手段在不同地理区域存在巨大的异质性。","scd":null,"kp":[]},{"i":42251,"as":"晚期前列腺癌中高表达的Polo-like kinase 1（PLK1）能够驱动癌细胞丝氨酸代谢的转变。研究表明，PLK1直接磷酸化丝氨酸合成途径（SSP）的限速酶——磷酸甘油酸脱氢酶（PHGDH）的S512、S513和S517位点。这一翻译后修饰显著降低了PHGDH的催化活性。PLK1介导的磷酸化重编程了丝氨酸和鞘脂代谢，揭示了肿瘤细胞通过调节关键代谢酶的活性来满足其过度增殖所需的生物合成机制。","scd":null,"kp":[]},{"i":42252,"as":"","scd":null,"kp":[]},{"i":42253,"as":"在多智能体AI系统等组织中，任务协调成本极高。分布式系统理论指出，当任务规范具有非单调性（新信息能使先前的结论失效）时，必须进行协调。研究证明了Thompson经典的相互依赖分类法与此准则存在映射关系，形成了一个判断任务正确性是否需要协调的决策规则。研究在桥定理中形式化了这一对应关系，将该规则应用于美国生产力与质量中心（APQC）的65个工作流程中，为组织任务分配与协调机制提供了量化依据。","scd":null,"kp":[]},{"i":42254,"as":"","scd":null,"kp":[]},{"i":42255,"as":"","scd":null,"kp":[]},{"i":42256,"as":"","scd":null,"kp":[]},{"i":42257,"as":"","scd":null,"kp":[]},{"i":42258,"as":"","scd":null,"kp":[]},{"i":42259,"as":"","scd":null,"kp":[]},{"i":42260,"as":"双相高熵异质结构的可控合成仍是一项重大挑战。研究提出了一种由动态转变驱动的原位化学还原策略，成功将钙钛矿前驱体转化为一系列锚定的高熵异质结。在还原条件下，熵稳定的钙钛矿晶格同时充当结构支架和成分库。其中，B位过渡金属阳离子析出形成均匀分散的高熵合金（HEA）纳米颗粒，而A位稀土阳离子则保留在母钙钛矿晶格中。该策略为定制和调控多功能协同的高熵材料提供了理想平台。","scd":null,"kp":[]},{"i":42261,"as":"针对纳米级脂质颗粒的高维设计空间（包括脂质组成、化学计量、尺寸、形貌等）极难优化的瓶颈，研究引入了一个高通量微流控平台。该平台能够实现精准且高效的低成本自动化操作，专门用于快速筛选脂质纳米颗粒的最佳配方。这一连续微流控自动化技术的应用，打破了传统优化方法速度慢、局限性大的问题，极大加速了生物医学递送、合成膜工程和生物物理探索领域的脂质纳米结构理性设计。","scd":null,"kp":[]},{"i":42262,"as":"研究开发了一种单晶双梯度纤维，用于全面感知和解码复杂的人体运动与生理信号。通过协同调控炭黑/碳纳米管填充的SEBS复合材料的渗透行为和流变拉丝性，研究人员确定了两种适用于同轴共拉丝的配方。该纤维通过耦合材料与工艺设计，在单一纤维内编程了互补的传感模式，克服了传统应变传感纤维仅受单一机电响应模式主导的局限，从而能够准确捕捉从微弱的生理波动到大幅度的肢体变形等多种不同形变。","scd":null,"kp":[]},{"i":42263,"as":"宽带隙（WBG）钙钛矿在运行中易发生光致卤化物相分离。研究证实，运行过程中陷阱电荷的积累是触发相分离的关键因素。基于时间分辨光致发光和深度剖析X射线光电子能谱分析，陷阱电荷的积累会加速光照下的离子重排和卤化物分离。为此，研究提出了一种最大稳定性点跟踪（MSPT）运行策略，通过定期释放积累的电荷，有效缓解了相分离过程，从而显著提升了宽带隙混合卤化物钙钛矿太阳能电池的运行稳定性。","scd":null,"kp":[]},{"i":42264,"as":"针对钙钛矿太阳能电池（PSCs）在高温及类似太空环境下因热机械应力和缺陷导致的降解问题，研究提出了一种双功能界面钝化策略。该策略将氧化铈纳米颗粒与苯乙基碘化铵（PEAI）结合形成混合表面处理（PC）。在此架构中，缺陷钝化与氧化还原耦合及增强的热应力稳定作用相互补充。经过优化的PC处理器件在快速热循环条件下表现出极佳的抗热机械降解性能，有效拓展了钙钛矿电池在极端环境中的应用前景。","scd":null,"kp":[]},{"i":42265,"as":"针对固态聚合物电解质在碱金属电池中面临的厚度、界面接触和枝晶问题，研究提出一种可扩展的原位聚合策略，制备出超薄（约10 µm）且坚固的类固态聚合物电解质。其离子传输主要通过富含溶剂的快速通道完成，聚合物基体则提供机械完整性。通过引入全氟丁磺酸钾，K⁺在金属电极表面提供动态静电屏蔽，有效稳定了金属电极。该策略成功实现了锂/钠金属电池在零下温度环境中的高效稳定运行。","scd":null,"kp":[]},{"i":42266,"as":"针对二硫化钼（MoS2）因电导率低和基面惰性导致的赝电容性能受限问题，提出了一种双限域策略。该策略通过晶格限域的锰掺杂与层间限域的乙二醇（EG）进行共工程化改性，构建出Mn-EG-MoS2结构。显微表征与理论计算表明，锰的取代重构了材料的结构。该策略有效调节了Mo 4d与S 3p轨道的弱杂化问题，从而实现高效的赝电容存储。","scd":null,"kp":[]},{"i":42267,"as":"双氮（N2）的活化与转化是一项重大科学挑战，特别是利用钛等3d过渡金属实现N-N键断裂的案例极为罕见。该研究报告了在PCP配体（2,6-(tBu2PCH2)2-C6H3）配位的钛中心上，通过辅助配体对N2活化路径实现前所未有的控制。这一成果为金属氮化物中间体实现双氮断裂与转化提供了新方法。","scd":null,"kp":[]},{"i":42268,"as":"稠环三聚体受体兼具小分子的高对称性与平面性，以及聚合物的高玻璃化转变温度，在实现兼具高光电转换效率与长期稳定性的有机太阳能电池方面极具潜力。针对其结构复杂导致光电性能难以调控的挑战，研究构建了首个光学和静电学可调的稠环三聚体受体家族（CH34、CH35和CH36）。该系列材料分别采用给电子的三氮杂蒽、电中性的三亚苯和吸电子的三环喹唑啉作为中心平面进行结构构建。","scd":null,"kp":[]},{"i":42269,"as":"针对过渡金属硫族化合物在质子交换膜水电解槽（PEMWE）中难以兼顾高催化活性与长期稳定性的挑战，研究人员开发出一种功能化介导的合成方法，制备了含有桥连配位铁原子的硫化钼。详细的表征表明，半胱氨酸功能化促进了铁原子在特定位置的锚定。该催化剂显著提升了析氢反应（HER）的催化性能，是极具前景的无铂族金属催化剂。","scd":null,"kp":[]},{"i":42270,"as":"现有的碳碳骨架塑料中链解聚技术普遍面临产率低或严重依赖过量氯化溶剂并产生腐蚀性副产物的问题。该研究提出了一种无氯光热中链解聚方法，通过独特的氧中心自由基路径进行反应。在ppm级浓度的高效光催化剂蒽醌作用下，商业聚甲基丙烯酸甲酯（PMMA）成功实现了高达97%的单体再生。该方法在温和条件下实现了传统塑料的高纯度化学回收。","scd":null,"kp":[]},{"i":42271,"as":"多共振热活化延迟荧光（MR-TADF）发射体能够实现具有极高色彩纯度的窄带电致发光。针对发光波长向红光区域延伸时难以保持光谱清晰度的难题，研究人员开发出一种发散型一锅法硼化策略。该策略以单一的5,11-二氢吲哚[3,2-b]咔唑为分子平台，利用反应条件下的竞争性单硼化和双硼化路径，在单次操作中合成了三种结构不同的有机硼MR-TADF发射体，发光颜色覆盖从绿光到红光区域。","scd":null,"kp":[]},{"i":42272,"as":"手性多烯是天然产物和生物活性分子中的重要构建模块。面对利用简单原料合成具有立体控制多烯的挑战，该研究开发了一种钴催化的1,3-烯烃炔还原不对称二聚反应。该方法利用简单易得的起始原料，实现了首次快速合成对映体富集的跳跃式1,3,6-三烯。此外，该方案通过1,3-烯烃炔的不对称还原交叉加氢二聚化，同样适用于合成对映体富集的跳跃式二烯。","scd":null,"kp":[]},{"i":42273,"as":"包裹在人类和微生物细胞外的动态聚糖层在维持免疫耐受、抗击病原体和癌症中发挥着关键作用。内源性抗聚糖抗体是免疫监视的重要组成部分，能够识别异常的微生物聚糖和肿瘤相关糖抗原，使其成为人类疾病免疫治疗的重要靶点。针对聚糖结构极其复杂多样的难题，近期在聚糖合成领域取得了一系列进展，包括自动化固相组装、化学酶促策略和一锅法合成技术，为解锁其医学潜力提供了技术支持。","scd":null,"kp":[]},{"i":42274,"as":"为了满足治疗性核酸在临床转化中对吸收、分布、代谢和排泄（ADME）研究的需要，含氚放射性标记的寡核苷酸至关重要。现有标记方法存在成本高昂、交付周期长、比活度低及放射性废料多等局限。为此，研究人员开发了一种利用甲基转移酶对寡核苷酸进行后期（放射性）同位素标记的生物催化平台。该平台成功实现了寡核苷酸后期的氚放射性标记。","scd":null,"kp":[]},{"i":42275,"as":"镧系掺杂的氟化物纳米闪烁体在X射线成像中极具潜力，但其性能受限于三价镧系离子4f-4f跃迁的禁戒特性导致的低辐射效率。该研究开发了一种由F中心介导的价态工程策略，成功实现了氟化物纳米闪烁体中Eu3+向Eu2+的可控转化。密度泛函理论计算揭示了该价态转变的内在机理，为实现多样化光学传感提供了新途径。","scd":null,"kp":[]},{"i":42276,"as":"电催化NOx还原制氨（NOxRR）面临加氢动力学缓慢和活性物种不稳定的问题。研究人员开发了一种由单原子镓修饰的CuOx/Cu催化剂（GaSA-CuOx/Cu）。该催化剂具有强耦合的Ga-O-Cu配位结构，通过引入高亲电性的Ga3+调节了Cu的电子结构。该催化设计有效提升了空气等离子体衍生氨的电合成效率。","scd":null,"kp":[]},{"i":42277,"as":"多孔有机笼（POCs）的分子间堆积产生外在孔隙，在连接笼腔、产生尺寸选择性约束和定制吸附微环境方面发挥关键作用。针对当前合成策略主要集中于内在孔隙工程的局限，该研究基于结构修饰开发了一种外在孔隙工程策略。该方法成功设计并利用了堆积衍生的孔隙，实现了乙炔与乙烯的高精度分离。","scd":null,"kp":[]},{"i":42278,"as":"共价有机框架（COFs）的多晶型现象为揭示结构-性能关系提供了独特平台。该研究构建了两种化学组成相同但拓扑结构不同的1D和2D COF多晶型物，以关联框架结构与光催化性能。在耦合糠醇增值化的H2O2光催化合成实验中，1D-TBPP-COF展现出卓越的性能，其H2O2生成速率高达18.75 mmol g−1 h−1。","scd":null,"kp":[]},{"i":42279,"as":"针对液晶弹性体（LCEs）作为软体致动器时无法兼顾防火安全与可逆驱动的问题，研究人员提出了一种自由基介导的P-H/烯烃逐步增长聚合策略。该策略利用次磷酸和二烯封端的介晶单体，合成了本质阻燃的有机磷LCPs和LCEs。这种在主链中引入P-C键的方法避免了刚性芳香磷单元的使用，成功实现了由火焰触发的致动功能。","scd":null,"kp":[]},{"i":42280,"as":"受生物离子通道动态自适应组装行为的启发，该研究提出了一类带有三肽的大环离子通道。在低浓度下，带有芳香族三肽功能化的大环类似物作为独立高效的氯离子通道发挥作用。随着浓度增加，三肽侧链之间的协同芳香相互作用促使大环结构发生自适应转化，从单分子氯离子通道转变为更高阶的纳米孔。","scd":null,"kp":[]},{"i":42281,"as":"局部静电环境对催化反应活性具有重要影响，但在合成催化剂中的系统性应用仍然有限。该研究探讨了碱金属阳离子在钴卟啉笼状络合物中的动态结合，以此作为调节其氧化还原特性和二氧化碳还原（CO2RR）催化活性的策略。电化学研究表明，Co1+到Co0的氧化还原电位对电解质阳离子的种类高度敏感，尤其是K+的存在显著影响了催化过程。","scd":null,"kp":[]},{"i":42282,"as":"信使RNA（mRNA）半衰期短的问题严重限制了其医学应用。环状RNA因缺乏易降解的末端而具备解决此问题的潜力，但其翻译效率较低。该研究提出利用点击化学，通过生物正交官能团修饰5'帽和3'聚(A)尾，实现mRNA的共价环化。生成的环状mRNA被光裂解保护基团抑制翻译，在光照条件下，保护基团被移除从而实现光诱导的翻译后期激活。","scd":null,"kp":[]},{"i":42283,"as":"空气环境中复杂的湿氧条件对钙钛矿太阳能电池的表面钝化提出了严苛要求。传统的铵配体钝化容易引发配体嵌入，增加界面电阻并降低稳定性。该研究利用一系列胆碱衍生物，提出了一种基于中间位点锚定的非层状界面钝化策略。其硫代酰基硫与未配位的Pb2+位点发生强配位，有效提升了空气环境中器件的效率与稳定性。","scd":null,"kp":[]},{"i":42284,"as":"该文概述了在TJ-II仿星器上开展的高性能等离子体输运研究，旨在通过第一性原理模拟和功率平衡分析理解输运机制。研究任务包括使用stella和EUTERPE进行回旋动力学模拟，使用SFINCS进行新经典模拟，以及使用HPI2和ASCOT5进行粒子沉积和热源估算。各项数值模拟与输运分析结果共同解释了通过弹丸注入实现约束改善的等离子体输运机制。","scd":null,"kp":[]},{"i":42285,"as":"传统荧光团易发生快速光漂白，限制了在埃米级定位精度下对蛋白质组织进行可视化。研究人员对上转换纳米颗粒进行成分工程改造，使其能够自发且无限地闪烁。通过使用单一近红外激发源，成功实现了亚埃米级定位精度的双色生物成像。","scd":null,"kp":[]},{"i":42286,"as":"原住民土地对保护亚马逊雨林和原住民至关重要。然而，这些地区正日益暴露在社会环境前沿地带，面临暴力、非法资源开采和森林砍伐等严重威胁。必须立即采取紧急行动，以防止对原住民和森林造成不可逆转的伤害，其中巴西的Vale do Javari原住民土地面临的形势尤为严峻。","scd":null,"kp":[]},{"i":42287,"as":"传统的城市极端天气应对规划侧重于强化市政边界和内部基础设施。最新研究表明，城市与外部城市网络之间的社会经济和物理联系，在极端降雨期间充当了城市内部交通恢复力的关键催化剂。该发现证明了外部城市网络连接对维持城市内部交通韧性的核心作用。","scd":null,"kp":[]},{"i":42288,"as":"","scd":null,"kp":[]},{"i":42289,"as":"","scd":null,"kp":[]},{"i":42290,"as":"","scd":null,"kp":[]},{"i":42291,"as":"","scd":null,"kp":[]},{"i":42292,"as":"","scd":null,"kp":[]},{"i":42293,"as":"","scd":null,"kp":[]},{"i":42294,"as":"","scd":null,"kp":[]},{"i":42295,"as":"全钙钛矿叠层太阳能电池的效率受限于窄带隙锡铅（Sn-Pb）子电池。在刮涂工艺中，富含Sn²⁺的前驱体结晶速度快且难以调控，同时Sn²⁺在环境条件下极易被氧化为有害的Sn⁴⁺。传统单一添加剂只能解决其中一个缺陷。为此，研究提出一种双添加剂策略，结合了路易斯碱氨基硫脲（FATU）和两性离子盐酸甘氨酸（GlyHCl），实现两项核心协同功能以同时解决上述两大结晶与氧化瓶颈。","scd":null,"kp":[]},{"i":42296,"as":"氯离子电池兼具高理论能量密度与元素可持续性，但全固态氯离子电池（ASS-CIBs）受限于离子传输受限和界面不稳定。研究展示了一种高性能的VOCl/CsSn0.9In0.067Cl3 (CSIC)/In电池系统。通过对正极复合材料架构进行系统优化，确定了30:60:10（VOCl/CSIC/C）的最佳质量比例，使电池的初始比容量达到169 mAh g⁻¹。","scd":null,"kp":[]},{"i":42297,"as":"多孔碳基硬碳因具有高平台容量而成为钠离子电池负极材料的研究热点，但其面临增加闭孔以提升容量与阻碍电荷传输、破坏结构稳定性之间的固有矛盾。研究引入一种溶剂介导的液相空间限域策略解决此问题。通过向水热系统中加入不混溶的非极性溶剂，使碳前驱体的沉积和成核在受限的高张力液相界面处受到精确调控，从而成功制备出富含sp²杂化的闭孔硬碳。","scd":null,"kp":[]},{"i":42298,"as":"海马体模式分离通过将神经输入正交化为非重叠表征，支持对高度相似记忆的区分。近期研究表明人类海马体能处理语义信息。本研究通过高分辨率功能磁共振成像和记忆辨别任务，利用词向量技术在多维概念空间中操纵语义相似性，对30名年轻受试者进行了多种神经和行为特征的模式分离测试，以此探究海马体是否能够对高度相似的语义表征进行模式分离。","scd":null,"kp":[]},{"i":42299,"as":"","scd":null,"kp":[]},{"i":42300,"as":"生物学家常通过研究相似性状演化中的同源基因重复使用，来证明分子水平的演化可重复性，但基因组水平分子趋同的频率和原因（尤其在深度时间尺度上）尚未解决。研究利用系统转录组学和序列进化分析发现，适应性分子趋同（同源基因间非同义替换的过度趋同且符合正向选择）在刺胞动物中广泛存在。这种分子趋同虽随时间推移略有下降，但在谱系中持续存在，且在很大程度上与表型趋同相脱钩。","scd":null,"kp":[]},{"i":42301,"as":"研究利用海洋浮游植物Bigelowiella natans的突变积累实验，发现其核基因组突变率存在超过1000倍的极端局部差异。其基准单核苷酸突变率约为每代每个位点3.5 × 10⁻¹⁰。然而，有两个源于整合病毒的基因组区域展现出极高的突变率，约为6 × 10⁻⁷。这些区域表现出独特的突变特征，几乎全为T/A→C/G的转换。","scd":null,"kp":[]},{"i":42302,"as":"APOBEC3A (A3A) 和 APOBEC3B (A3B) 会诱导单碱基替换特征SBS2和SBS13（主要引起TCW序列上的C>T和C>G突变），广泛存在于肿瘤中。然而，APOBEC对非SBS突变（非典型APOBEC突变）的贡献及产生机制尚不明确。研究表明，A3A表达会产生非SBS突变，包括TTC基序中的C缺失、CC>TT以及TC>AT/CT/GT双核苷酸变体等。这些不同的突变类型是由不同的修复过程产生的。","scd":null,"kp":[]},{"i":42303,"as":"社交网络上充斥着极端渲染气候变化的“气候厄运”信息，这可能会让人们感到被操纵或产生绝望感。该研究测试了心理接种是否能帮助识别气候厄运并影响用户的参与度。通过社交媒体模拟器收集的行为数据表明，心理接种能显著提高对气候厄运信息的辨别力，其内在原因是这类末日信息的操纵感被受众明确感知。","scd":null,"kp":[]},{"i":42304,"as":"班图语家族是撒哈拉以南非洲最大的语言家族之一，其扩张是人类历史上大规模语言家族扩张的重要案例。为了解其早期史前史，必须将最初分化与后续强烈的语言接触信号区分开来。研究引入了凝聚理论模型进行计算研究，将语言接触视为常态而非罕见例外。通过应用近似贝叶斯计算，该模型成功还原了班图语家族的早期演化轨迹。","scd":null,"kp":[]},{"i":42305,"as":"牛油果及部分野生近缘种具有高度同步的日常花卉性别节奏，从而促进两种雌雄同体花型之间的异花授粉。A型植物在早晨开雌花，下午开雄花；B型则相反。研究将这种二态性定位至R2R3 MYB转录因子亚组的SDMYB基因上，该基因具有显性和隐性单倍型对。SDMYB的节律性表达与双相开花相关，显性等位基因包含影响该过程非同义突变。","scd":null,"kp":[]},{"i":42306,"as":"有毒的欧洲起疱甲虫幼虫寄生多种独居蜜蜂，但其吸引宿主的机制此前一直未被破解。研究发现，这些甲虫幼虫通过释放一簇与花朵气味高度相似的挥发性化合物来引诱蜜蜂。化学分析表明，这是一种源自常见花卉挥发物(S)-芳樟醇的复杂单萜类化合物混合物。行为学测试证明，这些化合物充当了花香模拟物，能够吸引蜜蜂并作为异种信息素发挥作用。","scd":null,"kp":[]},{"i":42307,"as":"SLC34A2是介导肠道无机磷酸盐吸收的跨膜蛋白，其功能失调与代谢疾病、肺泡微结石病及多种肿瘤密切相关。该钠离子耦合的磷酸盐转运蛋白具有独特的蛋白质空间结构与门控机制。研究表明，SLC34A2在大多数卵巢癌和子宫肿瘤中过度表达，这使其成为极具潜力的抗体-药物偶联物（ADC）治疗靶点。","scd":null,"kp":[]},{"i":42308,"as":"全球生育率正持续下降，传统经济和性别因素已难以充分解释这一趋势。此项跨国研究收集了来自意大利、阿根廷、美国和德国的数据，重点考察了气候变化、民主倒退、经济危机和地区冲突等宏观不确定性因素如何影响个人的生育意愿。这四个国家具有截然不同的生育轨迹，面临独特的社会政治和环境挑战。","scd":null,"kp":[]},{"i":42309,"as":"自我中心到他人中心的空间坐标转换是神经空间计算的关键过程，压后皮质（RSC）是其核心枢纽。研究利用双光子钙成像技术对自由导航小鼠的RSC空间编码进行解剖。结果发现RSC沿前后轴具有功能差异：前部压后皮质主要表现为自我中心边界向量编码；而后部压后皮质则表现出增强的他人中心边界编码特征。","scd":null,"kp":[]},{"i":42310,"as":"维生素D缺乏同异常的免疫反应相关，但其活性代谢物骨化三醇如何塑造先天淋巴细胞发育尚不完全清楚。研究利用小鼠模型、多组学分析及临床样本证明，骨化三醇通过结合维生素D受体（VDR），选择性地促进骨髓ILC祖细胞增殖并分化为分泌IL-10和IL-22的双重细胞因子抗炎性ILC3细胞群。该过程由骨化三醇-PKM2轴驱动的转录和代谢重编程实现。","scd":null,"kp":[]},{"i":42311,"as":"针对具有高耐药性的淋病奈瑟菌，研究者开发了一种靶向致病菌的抗体-药物偶联物（ADC）。该ADC将强效抗革兰氏阴性菌的抗菌肽Tridecaptin A1类似物偶联到单克隆抗体上。这克服了原抗菌肽对人体细胞具有显著毒性而难以临床应用的局限，为应对抗生素耐药性感染提供了新型治疗策略。","scd":null,"kp":[]},{"i":42312,"as":"传统观点假设最早的胎盘哺乳动物是独居的。研究汇编了超5390种胎盘哺乳动物的社会组织数据，涵盖726个物种的1473个种群。分析发现，51%的物种和40%的种群存在种内社会组织变异。利用贝叶斯系统发育框架分析表明，早期胎盘哺乳动物的祖先主要但不完全以独居为主，且成对生活这种社会模式在胎盘哺乳动物早期就已经出现了。","scd":null,"kp":[]},{"i":42313,"as":"H3K79甲基转移酶DOT1L与c-MYC在多种人类癌症中存在功能上的协同作用。研究表明，DOT1L与c-MYC在多种模型中共同调节相关基因的表达。令人意外的是，DOT1L促进了c-MYC和线虫MML-1的蛋白水解过程。DOT1蛋白序列中存在与DDI家族蛋白酶催化基序相似的保守序列。研究证实c-MYC DNA结合域前方的序列是核内蛋白水解的切割位点。","scd":null,"kp":[]},{"i":42314,"as":"研究开发了一种多尺度传播模型，结合异质的就医行为和抗病毒药物降低传播风险的临床估计，评估了186个国家在四种大流行情景下对抗病毒药物的需求和死亡率影响。研究指出，由于玛巴洛沙韦（BXM）的特性，在应对新型流感大流行期间的抗病毒药物储备是一项关键的防范措施。","scd":null,"kp":[]},{"i":42315,"as":"研究提出了一个统一的统计学习模型——长程联想学习。该模型能够跨越多种时间尺度的时间依赖性，包括相邻与非相邻转换以及复杂的网络结构。该模型弥补了以往孤立设计模型且依赖狭义统计测量的局限性，能够揭示感觉输入中丰富的模式，有效预测未来事件。","scd":null,"kp":[]},{"i":42316,"as":"研究通过生态瞬时评估法测量了婴儿在出生后头几个月经历的向前自运动和主动导航时间。结果显示，5个月大的婴儿累计经历了约340小时的向前自运动，且几乎完全是被动的。这一发现旨在探究大脑皮层场景处理网络的发展是依赖于场景低级视觉统计的被动暴露，还是依赖利用场景信息进行导航的主动经验。","scd":null,"kp":[]},{"i":42317,"as":"研究利用自旋分辨和角分辨光电子能谱技术，全面研究了Bi(110)表面态的三维自旋结构。观察到的复杂面内自旋织构与以往的实验报告及第一性原理计算基本吻合，并成功揭示了先前未被发现的隐藏自旋极化表面态。","scd":null,"kp":[]},{"i":42318,"as":"芯损电子能量损失谱（EELS）的空间分辨率通常受到长程库仑相互作用引起的非弹性散射离域效应的限制，特别是在低能量损失下的轻元素边缘。该研究通过实验展示了硅的Si L边缘的原子级分辨率成像，成功突破了传统离域效应的分辨率极限。","scd":null,"kp":[]},{"i":42319,"as":"交变磁体是一种具有空间旋转对称性的非常规共线磁性材料，其基础序为完全补偿的反铁磁序，但能产生强烈的自旋分裂能带。该研究针对交变磁性莫特绝缘体，发展了角分辨光电子能谱（ARPES）的理论，以描述和解析其独特的电子结构特性。","scd":null,"kp":[]},{"i":42320,"as":"许多强关联状态（如分数量子霍尔效应和自旋液体）的波函数需要通过将粒子划分为多个簇并构造波函数后再进行对称化或反对称化来描述。该研究提出了一种蒙特卡洛抽样方法，专门用于处理这类需要对多簇波函数进行对称化或反对称化操作的量子系统。","scd":null,"kp":[]},{"i":42321,"as":"研究成功实现了热力学Haldane晶格。该系统是Haldane模型的热学类比，通过将Chern绝缘体的物理框架扩展到热扩散系统中，成功支持了热的单向手性边缘态，为热能的定向传输和调控提供了新途径。","scd":null,"kp":[]},{"i":42322,"as":"该研究通过莫尔工程化声子平带实现了无缺陷孤子状的能量传输。局域声子模式能够空间限制振动能量并抑制扩散散射，从而在混合量子计算、热物理和材料科学等前沿领域实现了低损耗、方向性的能量传输和热局域化。","scd":null,"kp":[]},{"i":42323,"as":"当材料内部多个自由度发生相互作用时，会自发产生纳米尺度的调制。研究表明，铁电体Sr1-xCaxTiO3非常接近一种与特定有限q趋势相关的晶格不稳定性状态。这种状态证明了该材料中存在初始调制相。","scd":null,"kp":[]},{"i":42324,"as":"宇宙射线中的镍是铁之外最丰富的重元素。DAMPE太空任务利用其优异的电荷分辨率和宽广的能谱范围，测量了宇宙射线中镍的能量谱（能量范围从10 GeV/n到2 TeV/n）。该高精度能谱数据为研究重核加速源及其宇宙传播机制提供了重要参考。","scd":null,"kp":[]},{"i":42325,"as":"传统的约瑟夫森隧穿结具有固有的互易性，限制了非耗散超导二极管元件的开发。该研究提出利用卡皮察摆钟机制构建超导隧道二极管，解决了支持非互易超导电流流动的根本挑战，为超导电子学提供了新的非耗散电路元件实现路径。","scd":null,"kp":[]},{"i":42326,"as":"通过相对论电子束与强激光相互作用产生高能辐射时，实现相干辐射需要精确控制辐射电子的相位匹配。该研究证明，让相对论电子束以掠射角与强激光相互作用，可以成功克服相位匹配难题，产生相干的阿秒级短脉冲。","scd":null,"kp":[]},{"i":42327,"as":"物理学家一直在探索从经典到量子系统中的隐藏对称性。该研究提出了一种名为“潜在几何对应”的新框架，利用图论纯代数方法来优雅地揭示系统内部隐藏的对称群，为寻找非直观的广义几何对称性（潜在对称性）提供了全新的理论与工具支撑。","scd":null,"kp":[]},{"i":42328,"as":"研究团队开发了一种关于不完全里德堡阻塞的理论，并进行了实验验证。这一研究成果打破了以往完全阻塞的理想化假设，更准确地描述了里德堡超原子的物理机制，有望为量子技术领域构建更高质量的量子元件提供理论和实验基础。","scd":null,"kp":[]},{"i":42329,"as":"当电子物质波穿过由两束相干光波干涉形成的周期性光栅结构时，会通过受激康普顿散射吸收和发射光子，导致电子动量发生相干衍射，这被称为卡皮察-狄拉克效应。该研究在相干区域内成功实现了电子的这种光致衍射效应。","scd":null,"kp":[]},{"i":42330,"as":"双光子迪克模型在量子应用中展现出如谱坍缩等独特性质，并被报道存在超辐射相。但该研究通过分析证明，双光子过程中的这种超辐射相并非真正的热力学相，而仅仅是一种有限尺寸效应，随着系统尺寸增大该现象将消失。","scd":null,"kp":[]},{"i":42331,"as":"在经典流体力学中，钝体尾流中的卡门涡街由局部霍普夫分岔驱动。该研究将这一概念扩展到超流体系统，研究了量子流体中涡旋脱落的动力学行为，证实了在量子流体中同样存在涡旋脱落的普适临界动力学机制。","scd":null,"kp":[]},{"i":42332,"as":"研究表明，一阶相变可能发生在晚期宇宙中真空能量开始主导能量密度的时期（红移z≲0.3）。在这个过程中，部分潜热会被转化为如不可见辐射等其他形式的能量。这一现象不仅在广义上成立，还在引入特定机制的粒子物理模型中具有具体动机。","scd":null,"kp":[]},{"i":42333,"as":"研究探讨了整数量子霍尔效应晶格模型在零温下霍尔电导率在不同无序分布下的统计特性。研究发现，在量子霍尔平台跃迁附近，电导率分布呈现重幂律尾部，指数α≈2.2至2.5，这意味着其均值有限但方差发散，证明了在量子霍尔跃迁处存在自平均性质的破缺。","scd":null,"kp":[]},{"i":42334,"as":"研究通过对候选交替磁体MnF2施加对称应变和磁场调节，结合高灵敏度弹性热测量与第一性原理理论，首次实现了对MnF2材料中交替磁性（altermagnetism）的确切宏观确认，揭示了其多极子序。","scd":null,"kp":[]},{"i":42335,"as":"研究探讨了欧拉三十六军官问题的量子力学扩展。该问题等同于寻找正交拉丁方，已知在阶数为2和6时无解。本项工作证明了正交拉丁方在三十六阶（n=36）下存在的具体量子纠缠配对形式。","scd":null,"kp":[]},{"i":42336,"as":"研究针对开放量子系统动力学中的反馈控制提出了一种统一的理论框架。现有的反馈主方程数量有限且局限于特定反馈类型，该框架引入了一组确定性的方程，推进了相干平台中量子反馈控制的发展。","scd":null,"kp":[]},{"i":42337,"as":"研究证明了马尔可夫量子信道中存在经典马尔可夫链“瓶颈定理”的类似定理。结果表明，如果希尔伯特空间的两个区域被一个在信道稳态中权重极低的区域隔开，那么在这两个区域之间初始化的量子态演化将受到显著的传输阻碍。","scd":null,"kp":[]},{"i":42338,"as":"研究探讨了踢击伊辛模型在自对偶点作为量子电池的充电机制。研究发现，在该模型中最大纠缠增长能够实现最大的能量注入。最大纠缠被证实是提升量子电池充电性能的关键资源，并确立了相关的Floquet动力学机制。","scd":null,"kp":[]},{"i":42339,"as":"研究利用现有的低能实验数据，对12C+12C聚变反应的天体物理S因子进行了贝叶斯平滑拟合外推分析。该工作基于碳-碳相对能量信息，构建了数据驱动的模型，为天体物理环境下的核聚变反应率提供了约束。","scd":null,"kp":[]},{"i":42340,"as":"研究分析了K1(1270)介子在热强子介质中衰变为π+π-K+的衰变道的热修正效应。该衰变振幅由以ρ和K*极点贡献为主的有效强子相互作用构建，实现了达利兹图级别的分析，揭示了介质温度对衰变性质的具体影响。","scd":null,"kp":[]},{"i":42341,"as":"研究测量了与中子俘获截面相关的59Fe核的核能级密度。实验通过57Fe(7Li,α)反应布居60Co，并测量其衰变产生的59Fe+质子发射谱。通过对符合质子谱的统计模型分析，成功提取了59Fe的核能级密度数据。","scd":null,"kp":[]},{"i":42342,"as":"研究对倾斜的、自引力黑洞盘系统进行了完全相对论性的广义相对论磁流体动力学模拟。系统中的黑洞自旋与盘角动量存在错位，模拟聚焦于围绕快速旋转黑洞的大质量盘（盘与黑洞质量比为16%–28%），揭示了此类系统的多信使引力波特征。","scd":null,"kp":[]},{"i":42343,"as":"研究对实验测量的Bi同位素（204,206,207,208Bi）和209Po核的核能级密度进行了系统的贝叶斯分析。分析旨在探究随激发能增加时壳效应的阻尼现象，结果证实了这些铋原子核中存在极高的壳阻尼率。","scd":null,"kp":[]},{"i":42344,"as":"研究基于八极核芯-准粒子耦合模型，系统探究了不同八极关联单粒子组态对奇A八极形变核摆动运动的影响。具体分析了多种不同的轨道组态，揭示了自旋相干性在八极形变核摆动运动动力学中所起的关键作用。","scd":null,"kp":[]},{"i":42345,"as":"研究利用具有密度依赖点耦合参数的协变密度泛函理论，考察了98-106Ru偶偶同位素链的形变特性。结果表明，这些原子核具有非常浅的长椭球和三轴基态势，证实了该同位素区存在形状相变、共存与混合的复杂现象。","scd":null,"kp":[]},{"i":42346,"as":"研究基于非平衡格林函数方法，对236U光致裂变（γ,f）的阈下反应进行了微观分析。通过沿裂变路径叠加Skyrme-Hartree-Fock波函数以允许粒子-空穴激发，构建了裂变过程的模型空间，揭示了阈下光致裂变的微观动力学。","scd":null,"kp":[]},{"i":42347,"as":"研究重新评估了随机量子电路中近似2-设计与反集中现象之间的关系。过去学界普遍认为近似2-设计性质比反集中现象要求更高，因为前者通常需要线性深度的电路，而后者在指数级深度即可实现。本研究表明，反集中现象几乎包含了所需的全部核心要求。","scd":null,"kp":[]},{"i":42348,"as":"研究证明了轨道角动量（OAM）纠缠在存在扰动的随机噪声信道中具有拓扑鲁棒性。尽管OAM纠缠态在现实噪声信道中容易发生衰减，但源于OAM纠缠的底层拓扑结构能够有效抵御信道干扰，从而保持量子纠缠的核心特性。","scd":null,"kp":[]},{"i":42349,"as":"研究通过超导玻色-哈伯德量子模拟器实验观测了量子关联动力学。实验利用Floquet技术实现了可调的 onsite 相互作用，在超导量子三能级阵列中模拟双粒子量子行走，从而成功研究了量子系统中关联动力学的演化过程。","scd":null,"kp":[]},{"i":42350,"as":"研究利用悬浮在接近基态的纳米颗粒，通过捕获势的量子猝灭（突变）引发的动力学行为，实现了一种纳米级加速度计。研究发现，快速猝灭能够提供一个特定的读出时间，在该时间点其灵敏度相比常规情况可提高2个数量级。","scd":null,"kp":[]},{"i":42351,"as":"研究推广了用于包容性破裂反应的Ichimura-Austern-Vincent (IAV) 求和规则。传统IAV形式将探测碎片视为旁观者，当该碎片为弱结合成分时该假设受到质疑。该工作去除了旁观者假设，为包含非旁观者碎片的包容性破裂反应提供了广义的理论框架。","scd":null,"kp":[]},{"i":42352,"as":"研究在声子晶体中发现，在同一精确能量带内可以同时存在传输边缘态和局域角态。这一发现打破了长期以来认为这两种拓扑状态相互排斥的物理法则，成功在第一阶拓扑能带中嵌入了高阶拓扑态。","scd":null,"kp":[]},{"i":42353,"as":"研究分析了弯曲时空中量子场论的能动张量期望值及其量子涨落。半经典引力在概念上保持自洽的一个普遍接受的条件是，量子能动张量的涨落必须远小于其期望值。该工作对张量涨落进行了重整化处理，并探讨了半经典引力理论的适用界限。","scd":null,"kp":[]},{"i":42354,"as":"本文实验展示了一种成功制备于量子运动基态的光机械盘式谐振器。尽管此类谐振器曾推动了光机械学领域的多项进展，但在本研究之前，它们尚未能在量子运动机制下获得运行资格。研究通过实验成功验证了该器件在量子基态下的运行能力。","scd":null,"kp":[]},{"i":42355,"as":"本文利用动力学密度矩阵重整化群方法，研究了S=1/2三角晶格J1-J2海森堡模型中的竞争态。以往研究表明该反铁磁体在J2的中间范围内存在非磁性基态相，但对于其究竟是有间隙的Z2量子自旋液体（QSL）还是无间隙态存在分歧。本研究通过计算进一步解析了该量子自旋系统在中间耦合区域的基态物理特性。","scd":null,"kp":[]},{"i":42356,"as":"本文在取向生长的IrMn/FeNi双层膜中观测到了反常的单向自旋霍尔磁阻（USMR）。单向自旋霍尔磁阻源于非平衡自旋积累与磁化强度的相互作用，此前被提作为一种检测重金属/铁磁体双层膜中磁态的电学方法。本研究突破了传统自旋极化方式的限制，揭示了外延双层膜系统中新的磁阻特性。","scd":null,"kp":[]},{"i":42357,"as":"本文实现了对CrSBr材料中双曲激子极化激元的全景观测。双曲极化激元具有非闭合的双曲等频轮廓，因其超大的动量和定向传播特性在集成光子学中极具应用前景。然而，由于存在巨大的动量失配，对其进行直接的远场观测极具挑战性。本研究成功克服了这一观测障碍，直接观察到了该现象。","scd":null,"kp":[]},{"i":42358,"as":"本文展示了一种可调谐的双结Transmon量子比特，并证实了高阶约瑟夫森谐波的存在。研究构建了一个由隧道结与超导量子干涉器件（SQUID）环路串联而成的超导电路元件。该架构通过磁场可以对约瑟夫森势的谐波成分进行强烈调谐。这种可调约瑟夫森谐波特性为量子比特的设计提供了新的途径。","scd":null,"kp":[]},{"i":42359,"as":"本文提出了一种利用位置重置来增强活性粒子空间探索的最优协议。寻找高效的空间探索策略对于动物觅食和机器人搜索过程均至关重要。研究表明，在活性粒子系统中引入位置重置机制，能够有效最大化已探索的区域面积，从而确立了一种优化空间探索的新方法。","scd":null,"kp":[]},{"i":42360,"as":"本文探讨了生长中的弹性薄片中的等距不兼容现象。几何不兼容（即材料的静止状态无法在欧几里得空间中实现）是天然和人工薄膜形状形成的物理基础。经典的Gauss和Mainardi-Codazzi-Peterson不兼容理论虽能解释许多自然图案，但无法涵盖所有机制。本文研究揭示了一种在生长弹性片中存在的全新不兼容机制。","scd":null,"kp":[]},{"i":42361,"as":"本文结合生物实验与活性聚合物模拟，研究了限制空间和刚度对聚合物易位过程的影响。研究受加州黑虫在受限环境中穿行的生物现象启发，发现活性聚合物的易位速度受限于空间与刚度的共同调控。研究明确得出结论：活性聚合物在受限空间中的易位（穿行）速度更快。","scd":null,"kp":[]},{"i":42362,"as":"本文证明了在二维O(N)非线性西格玛模型（NLSM）中渐近自由性的丧失。已知当N>2时，该模型是渐近自由的，既没有非平凡的固定点，也没有自发对称性破缺。本研究发现，在复耦合平面内确实普遍存在非平凡的固定点，该点可以用复共形场理论来描述，并在海森堡自旋链中得到了具体实现。","scd":null,"kp":[]},{"i":42363,"as":"本文对生物系统中估计策略的资源诱导相变进行了理论分析。生物体通过整合感官信息与内部记忆来适应环境，但其信息处理过程受到资源限制的严格约束。本研究指出，这种资源限制会从根本上改变生物系统的最优估计策略，并从理论上解析了在有限资源条件下估计策略发生相变（转变）的物理机制。","scd":null,"kp":[]},{"i":42364,"as":"本文开发了一种基于Fano效应的核空穴时钟（FCHC）方法，用于测量超快电荷转移（CT）时间。该方法在共振俄歇散射中，能够捕获局域激子与直接布居的扩展电荷转移连续态之间的相干耦合。研究将此方法成功应用于硫基分子体系，突破了传统核空穴时钟方法的限制，实现了对超快电荷转移过程的精确定时。","scd":null,"kp":[]},{"i":42365,"as":"本文通过在彭宁阱中测量氦-4离子（4He+）与碳-12离子（12C3+）的回旋频率比，精确测定了氦-4的质量。测量结果显示，氦-4原子的质量为4.002603254665(36) u，相应的阿尔法粒子质量为4.001506179662(36) u。这一高精度测量结果为未来的质量测定开辟了新的可能性。","scd":null,"kp":[]},{"i":42366,"as":"本文利用N=82壳闭合附近的从头算（ab initio）核质量，研究了r过程（快中子捕获过程）的核合成。宇宙中约一半的铁以上重元素源自r过程，但该过程所需的极端富中子条件涉及大量尚未被实验测量的原子核。本研究引入从头计算方法获取核质量数据，深入解析了在壳层闭合区域r过程核合成的物理机制。","scd":null,"kp":[]},{"i":42367,"as":"LHCb合作组利用大型强子对撞机收集的质子-质子碰撞数据，在双轻子不变质量大于ψ(2S)共振态的区域，对B0→K*0ℓ+ℓ-衰变中的轻子风味普遍性进行了测试。实验测量了特定衰变通道中μ子和电子行为的差异，旨在检验粒子物理标准模型中关于μ子-电子普遍性的基本假设。","scd":null,"kp":[]},{"i":42368,"as":"保罗谢尔研究所（PSI）的研究团队利用超冷中子源，开展了一项针对中子向镜像中子振荡的高灵敏度搜索实验。为了探究现有异常现象所声称的剩余参数空间，研究人员使用了专用的高灵敏度设备。通过详尽的磁场映射分析，实验对中子-镜像中子振荡现象进行了高精度的探测。","scd":null,"kp":[]},{"i":42369,"as":"LHCb合作组利用质心能量为13 TeV的质子-质子碰撞数据，对罕见衰变B+→Λ̄pμ+μ-进行了搜寻。实验数据对应5.4 fb⁻¹的积分亮度。通过对该衰变道的细致分析，研究提供了关于该罕见衰变过程存在的实验证据，有助于深化对重味强子稀有衰变机制的理解。","scd":null,"kp":[]},{"i":42370,"as":"本文研究了非极大混沌系统中的极点跳跃现象，以探测弦论中的视界物理。研究以Rindler共形场论和large-q的Sachdev-Ye-Kitaev（SYK）链为例证，论证了少体算符的极点跳跃点在复频率-动量平面中会形成特定的轨迹。这一发现揭示了非极大混沌系统中极点跳跃现象的物理特征。","scd":null,"kp":[]},{"i":42371,"as":"本文计算了在离子-原子费什巴赫共振附近的由两个中性原子和一个离子组成的三体系统的束缚与散射特性。研究结果表明，长程离子-原子相互作用会导致系统行为显著偏离由接触势或范德华势推导出的普适行为。研究发现了该三体系统在特定相互作用区间表现出的独特散射和束缚特征。","scd":null,"kp":[]},{"i":42372,"as":"本文实验研究了两能级系统在混合声光双修饰下的共振荧光特性。在该实验构型中，一束强激光驱动光学拉比振荡，同时一个声学场对两能级系统的频率进行参数调制。实验观察到，该系统产生的发射光谱与传统修饰态理论预期的结果存在显著偏离。研究揭示了声光共同作用下两能级系统的独特发光机制。","scd":null,"kp":[]},{"i":42373,"as":"研究人员利用活体真菌菌丝成功研发出一种可用于可持续时尚产业的纺织材料。该材料完全由天然真菌细丝制成，具备两大核心特性：一是具有自我修复功能，二是能够在自然环境中完全生物降解，为环保纺织品的开发提供了新方案。","scd":null,"kp":[]},{"i":42374,"as":"本期内容选自《自然》杂志档案，主要探讨了绵羊等动物毛发中弯曲形状（卷曲）是如何形成的机制，并回顾了“电离层”一词的历史渊源。","scd":null,"kp":[]},{"i":42375,"as":"在三叠纪末期陆地和海洋动物发生大规模灭绝期间，大规模的野火肆虐了欧洲大陆，无情地摧毁了大面积覆盖该地区的蕨类植物平原。","scd":null,"kp":[]},{"i":42376,"as":"全球各地的生育诊所正在推广一种提供年轻线粒体的生育技术。由于该手术尚未经过严格的科学研究与论证，研究人员对其被广泛商业宣传的现象表示高度警惕和担忧。","scd":null,"kp":[]},{"i":42377,"as":"科学家在一种淡水湖鲶鱼中发现了具有传染性的黑色素瘤（皮肤癌）。这一跨物种传播病例的发现，引发了对该传染性疾病的起源、传播方式以及对整个鲶鱼物种广泛影响的科学质疑。","scd":null,"kp":[]},{"i":42378,"as":"针对医生与人工智能（AI）协同诊疗时出现的医疗责任归属问题，提出了一种基于AI在患者护理中参与程度大小的阶段划分系统。该系统能够帮助明确在医疗护理失败时各方应承担的具体责任。","scd":null,"kp":[]},{"i":42379,"as":"在埃博拉疫情爆发三个月后，牛津大学已完成首例志愿者的临床试验疫苗接种。研究负责人Teresa Lambe介绍了其团队在疫苗研发上得以快速推进的具体过程。","scd":null,"kp":[]},{"i":42380,"as":"所有活细胞都会发出一种微弱的“生物光子”光芒，这可能是细胞之间相互交流的通讯方式。此外，大脑中存在一种能追踪睡眠的“计时器”，同时探讨了医生与AI合作时的责任归属问题。","scd":null,"kp":[]},{"i":42381,"as":"一项旨在穿越巨大“火云”的飞行任务即将启动。这种高耸的云层结构通常出现在法国和俄勒冈州的严重野火上空，能将烟雾推至极高的高空，从而对全球气候和环境产生影响。","scd":null,"kp":[]},{"i":42382,"as":"两款医疗人工智能助手的研发过程凸显了一个挑战：随着AI技术的飞速发展，目前缺乏有效的方法来评估这些医疗AI工具的实际效用与工作表现。文章探讨了如何最好地衡量和评估医疗AI技术。","scd":null,"kp":[]},{"i":42383,"as":"所有生物活细胞都会发出极其微弱的“生物光子”。研究指出，这种超微弱的光线不仅有望被开发用于疾病诊断，还可能代表着一种全新的细胞内信号传导机制。","scd":null,"kp":[]},{"i":42384,"as":"裸鼹鼠群体具有典型的单雌繁殖特征，即整个族群只有一只具有繁殖能力的蚁后。研究发现，蚁后会分泌一种特定的化学物质，通过嗅觉机制帮助维持群体内的这种生殖等级制度。","scd":null,"kp":[]},{"i":42385,"as":"关于人工智能具备感知能力的概念，正在吸引更多资源与关注投入到意识科学领域的研究中。然而，部分研究人员对这种由AI炒作带来的热度是否真正有利于该科学领域的长远发展持保留态度。","scd":null,"kp":[]},{"i":42386,"as":"迁移反应是一种基础的化学转化过程。研究提出了一种全新的“纠缠双位点迁移”概念策略，实现了沿着碳链的两个远距离位点的同步迁移。该过程通过“硼杂环重排”实现，即硼杂环沿碳链以“引导-跟随”模式移动，克服了双迁移中心在化学、区域和立体选择性控制上的复杂难题。","scd":null,"kp":[]},{"i":42387,"as":"研究人员利用β-环糊精衍生的离散共价有机纳米管，构建了人工跨膜通道。这些具有明确纳米级孔径的通道能够高选择性地高效跨膜运输抗坏血酸（维生素C），并能在仿生膜系统中驱动生物正交级联反应，将外部化学输入转化为荧光信号，实现分子运输与信号转导。","scd":null,"kp":[]},{"i":42388,"as":"研究分离出一种低价态的15电子单配体铬络合物Cp*Cr(CNDipp2)2。该络合物可作为不稳定单体CpCr(CO)2片段的等瓣类似物，并展示了基于氧化还原状态的分子态氮结合特性。","scd":null,"kp":[]},{"i":42389,"as":"为解决仿细胞外基质蛋白水凝胶机械强度不足和结构无序的问题，研究提出了一种协同的“拓扑工程/金属配位”策略来设计新型类胶原蛋白水凝胶。通过基因编码将金属结合域（Zn2+, Ag+, Cu2+）、细胞粘附RGD基序和稳定结构域整合在一起，以满足糖尿病伤口修复的临床需求。","scd":null,"kp":[]},{"i":42390,"as":"锂金属电池具有高能量密度潜力，但受限于锂枝晶生长、SEI不稳定和体积膨胀等问题。纤维素作为一种储量丰富且可生物降解的生物质聚合物，凭借其出色的机械稳健性、丰富的表面羟基和可设计的微纳米结构，在解决上述关键瓶颈方面展现出独特优势。文章综述了纤维素基复合材料在提升锂金属电池性能方面的功能与机制。","scd":null,"kp":[]},{"i":42391,"as":"报道了一种可见-近红外宽频带有机主动适应晶体管（VN-OAAT），能够实现全天候的昼夜视觉感知。该器件采用嵌有三元本体异质结的介电层，将光谱响应拓宽至400-1200 nm，并通过调控电荷陷阱活化能，在强光下实现明视觉适应，在弱光环境下实现高效光电探测。","scd":null,"kp":[]},{"i":42392,"as":"高熵氧化物（HEOs）因包含多价态阳离子和高度无序的局部环境，在催化性能调优上具有广阔空间，但合理的理性设计极具挑战性。人工智能（AI）预测技术能够处理复杂的构型熵、混合焓、氧空位和动态活性位点等多重变量，为高熵氧化物催化剂的相稳定性和高效设计提供了关键方法。","scd":null,"kp":[]},{"i":42393,"as":"为解决柔性锂金属电池中厚锂负极和铜集流体导致的枝晶和体积膨胀问题，研发出一种多孔、具有自调节电场特性的三维复合集流体。该集流体采用金属/铁电聚合物/金属3D结构，能够促进形成极其致密、无枝晶且具备机械柔性的锂金属负极，使柔性电池体积能量密度达到1100 Wh L−1以上。","scd":null,"kp":[]},{"i":42394,"as":"研究构建了一种由原子级分散的高熵金属位点组成的PANoptosis纳米诱导剂（HENA@PEG），用于时空可控的近红外（NIR）增强癌症免疫治疗。该纳米酶独特的高熵金属位点配置通过原子级协同作用提升了催化效率，实现了精确的pH响应，有效解决现有策略中时空控制不足和活性氧（ROS）生成受限的挑战。","scd":null,"kp":[]},{"i":42395,"as":"为解决无负极锂金属电池中铜集流体上锂沉积和剥离可逆性差的问题，研究构建了一种结合共价有机框架（COF）膜与氧化钴纳米颗粒的复合集流体（TCMS@Cu）。TCMS@Cu通过外延生长在铜箔上形成致密的COF膜并掺入亲锂的CoO纳米颗粒。COF与CoO之间的主客体协同效应有效引导了锂离子的沉积行为。","scd":null,"kp":[]},{"i":42396,"as":"为解决胶体量子点（CQD）光电二极管中存在的界面缺陷和机械鲁棒性差的问题，研究引入双功能有机硅烷MDMS作为倒置PbS CQD光电二极管的界面层。MDMS分子通过硫醇配位和水解缩合形成交联硅氧烷网络，在CQDs与电子传输层界面构建稳固共价桥接。该界面工程显著增强了机械附着力，并为理想成核提供了条件。","scd":null,"kp":[]},{"i":42397,"as":"针对液态金属因高表面张力和润湿性差而难以附着在纺织品上的问题，研究开发了一种生物粘液介导的液态金属墨水。该墨水可直接打印在多种纺织品上，并在干燥后自主发生自烧结，形成高导电性且坚固的电路。生物粘液使墨水与纺织品形成强化学键，从而在柔软可变形的织物表面实现稳固的电子器件集成。","scd":null,"kp":[]},{"i":42398,"as":"研究展示了一种结合高色纯度和高度定向横电（TE）极化发射的蓝光OLED。该器件通过强光子-光子模式耦合的微腔架构实现。具体而言，通过将二阶法布里-珀罗模式与一阶光栅微腔模式进行杂化，实现了对OLED色纯度、方向性、偏振和光电效率等多个关键参数的同时精确控制。","scd":null,"kp":[]},{"i":42399,"as":"研究报道了一类同时实现高活性和高耐久性的低价态RuIr氧化物纳米催化剂，用于析氧反应（OER）。通过乙二醇介导的还原方法，传统四价RuIr氧化物转化为扭曲单斜结构，其中Ru和Ir被稳定在低于+4的还原价态。实验表明，该催化剂在OER过程中表现出动态但结构坚固的价态变化行为，满足了质子交换膜电解水制氢对阳极催化剂的高要求。","scd":null,"kp":[]},{"i":42400,"as":"吸湿盐嵌入复合材料（HSCMs）是吸附式空气取水（SAWH）的重要材料。然而，盐泄漏成为限制其在SAWH中长期应用的关键挑战。文章重点评估了盐泄漏对材料本身、系统、环境以及人类健康的多尺度潜在影响，并强调了在提升材料效率的同时，必须高度重视并解决材料的热力学稳定边界与盐泄漏问题。","scd":null,"kp":[]},{"i":42401,"as":"研究提出了一种结合原位极化的单步电流体动力学（EHD）直写策略，无需后处理即可同时制造和极化自支撑的超薄压电微结构。通过耦合热塑性聚氨酯（TPU）和压电材料P(VDF-TrFE)的机制引导设计，精确控制EHD沉积和聚合物结晶过程以调节晶粒尺寸，成功开发出适用于器官贴合的柔性可拉伸生物界面。","scd":null,"kp":[]},{"i":42402,"as":"为了实现兼具高能量密度和优异安全性的锂硫电池（LSBs），研究提出了一种新型电解液设计策略。该策略通过加入对称离子塑化剂构建了双界面调控机制，从而形成了“瘦身”的溶剂化结构。这种独特的电解液设计有效提升了锂硫电池的界面稳定性、离子环境调控能力和电催化活性，成功解决了高能量密度、高循环稳定性和高安全性难以同时兼顾的挑战。","scd":null,"kp":[]},{"i":42403,"as":"针对压电声动力疗法（SDT）中催化效率受限的问题，研究构建了一种钕单原子电子调节器。通过在富含空位的Bi2O3载体上负载钕单原子，利用钕的引入调节电子转移，有效提升了压电催化效率。该材料利用超声敏感特性产生活性物质，从而显著增强了抗肿瘤治疗的效果。","scd":null,"kp":[]},{"i":42404,"as":"研究开发了三种具有氧气再生能力的近红外aza-BODIPY光敏剂，在808纳米激发下实现高效的耐缺氧光动力疗法（PDT）。机制研究表明，光敏剂自由基离子对是关键中间体，通过水氧化驱动原位生成氧气和质子，有效克服了长波长激发光子能量低和肿瘤微环境缺氧对活性氧（ROS）生成的限制。","scd":null,"kp":[]},{"i":42405,"as":"研究开发了一种基于激光诱导石墨烯（LIG）阵列和有机电化学晶体管（OECT）的生物电子传感器平台。结合交流电介导的LIG快速孵育系统，该平台能在约6分钟内直接从临床样本中完成多重蛋白质分析，检测限达阿摩尔级别。研究确定GPNMB与GRN的比值是帕金森病神经炎症失调的敏感复合生物标志物，实现了血液样本的快速早期诊断。","scd":null,"kp":[]},{"i":42406,"as":"研究提出了一种基于微通道内弯月面引导界面聚合的光流体增材制造方法。利用表面张力形成稳定的油-水凝胶界面，紫外线照射选择性地将水凝胶前驱体聚合成环状结构。通过沿着通道顺序形成圆环，实现了内径在50微米至1毫米之间的中空管状结构的原位精密组装，成功克服了水凝胶固有的柔软性难题。","scd":null,"kp":[]},{"i":42407,"as":"为提升高温质子交换膜电解水（HT-PEMWE）的性能，研究设计制备了一种磺化金属有机框架（MOF）增强的Nafion复合膜（S/N-Nafion）。将磺化MOF引入Nafion基质中，使S/N-Nafion复合膜的质子电导率达到154.7 mS cm⁻¹。该膜材料成功满足了高温环境下同时对高质子电导率和长期稳定性的严格要求。","scd":null,"kp":[]},{"i":42408,"as":"研究提出了一种可编程的光响应颗粒水凝胶平台。通过点击化学合成含有光不稳定烯丙基硫醚基团的聚乙二醇微凝胶，并将其组装成支架。利用光介导的自由基加成-断裂链转移反应，仅需单一微凝胶配方即可在组装后对支架的机械性能和细胞微环境进行时空控制与重塑，实现了异质性结构的灵活构建。","scd":null,"kp":[]},{"i":42409,"as":"为解决光催化产过氧化氢（H2O2）过程中表面氧中间体导致的O-O键断裂和H2O2分解问题，研究通过协调微环境控制将增强的内建电场与调节的电荷离域相耦合。以磺化共价有机框架为载体锚定单镍原子，该单原子催化剂成功抑制了副反应，显著提升了光催化产H2O2的效率。","scd":null,"kp":[]},{"i":42410,"as":"受天然蜘蛛丝中刚性结晶体与可拉伸β折叠域协同机制的启发，研究开发了一种基于仿生类胶体纳米颗粒交联的超韧人造丝纤维。将GNP交联剂集成到共价网络中，使纳米颗粒表面吸附的聚合物链形成具有隐藏长度的动态环。拉伸时这些环展开并通过界面键的断裂大量耗散能量，显著提升了材料的韧性。","scd":null,"kp":[]},{"i":42411,"as":"针对钠离子电池层状过渡金属氧化物在相变过程中引起微应变和结构退化的问题，研究引入相变电位（Φ_phase）作为描述符来预测和控制正极材料的相演变。较低的相变电位能够实现更平滑的钠离子迁移和更慢的层间滑动，促进连续相变，有效降低了材料应变，实现了具有优异循环稳定性的高比能钠离子电池。","scd":null,"kp":[]},{"i":42412,"as":"研究在结构手性、非极性系统中引入了一类新型手性交变磁性磁电材料，并确定金属有机框架K[Co(HCOO)]为实现该机制的理想平台。该材料表现出手性锁定的g波交变磁性自旋劈裂特性。其电极化可通过Néel矢量重定向和结构手性进行双模式开关切换：Néel矢量翻转改变极化符号，手性对映体切换可再次实现极化反转。","scd":null,"kp":[]},{"i":42413,"as":"为解决电子受体型底物厌氧生物转化的电子传递瓶颈，研究在合成微生物群落中开发了半胱氨酸脱硫酶（CSD）相关的周质FeS生物矿化策略。该策略在非硫酸盐还原菌内快速形成周质导电FeS界面，显著降低了界面电荷转移阻抗并增加了电容性电子存储。电化学分析证实该机制提升了电子接受能力，显著增强了三溴环十二烷的还原脱卤呼吸作用。","scd":null,"kp":[]},{"i":42414,"as":"该研究提出“阴离子调节”策略，向Zn(OTf)2电解质中引入两亲性苯甲醇（BA）以调节电解质微观结构并形成双重溶剂化结构。BA与Zn2+的溶剂化能力较弱，通过阴离子-溶剂相互作用诱导形成Zn2+-OTf-BA双重溶剂化结构。这缩小了溶剂化簇尺寸并提高了微观均匀性，从而改善了离子传输特性，解决了锌负极因迟缓离子传输导致的倍率性能差的问题。","scd":null,"kp":[]},{"i":42415,"as":"该研究报告了一种锰催化系统，能够对环状和非环状烯烃进行高对映选择性的不对称转移氢化反应，生成多种手性产物。反应产率高达99%，对映体过量（ee）大于99%。密度泛函理论（DFT）研究表明，该反应主要通过涉及六元环过渡态的协同氢转移途径进行。此项工作突破了地球上储量丰富的金属在催化非环状烯烃不对称氢化反应中的限制。","scd":null,"kp":[]},{"i":42416,"as":"为解决无氢条件下丙烷脱氢（PDH）催化剂失活的难题，该研究开发了一种无氟合成后硅烷化策略。该策略利用六甲基二硅氮烷（HMDS）选择性钝化silicalite-1沸石表面的硅羟基，从而增强了被包裹的Pt1Sn1合金簇的稳定性。测试结果表明，在无氢条件下连续运行2160小时的测试中，该催化剂维持了稳定的丙烷脱氢性能，成功抑制了活性位点在长期高温运行中的聚集。","scd":null,"kp":[]},{"i":42417,"as":"该研究报道了一种基于嵌入共价有机框架（COF）的单原子钌（Ru）的新型光诱导交替催化机制。该材料被用作高性能光辅助非水系锂-氧（Li-O2）电池的阴极催化剂。该体系利用太阳能降低驱动氧还原和析氧过程的过电位，并通过多步转化途径调节复杂活性位点与活性氧相关中间体之间的相互作用，从而提升电池性能。","scd":null,"kp":[]},{"i":42418,"as":"该研究发现了首个高选择性、依赖CRBN的分子胶降解剂dWBP4-1，用于降解剪接体相关支架蛋白WBP4。通过对CRBN结合文库进行蛋白质组学分析和结构-活性关系优化，发现dWBP4-1能通过经典的G环介导机制诱导WBP4快速降解（纳摩尔级别）。其具有极高的全蛋白质组选择性，对转录组或可变剪接的干扰微乎其微。研究还将最小WBP4降解子定位为41个氨基酸的序列。","scd":null,"kp":[]},{"i":42419,"as":"研究成功合成了一种持久的C-磷鎓基-硼杂乙烯基阴离子1。这种含硼的乙烯基锂化合物中，带有负电荷的乙烯基碳的电荷为-1.59，显著高于其碳类似物（-0.76）。实验证明该阴离子具有强亲核性和碱性，能够与H2（10 bar，15分钟）和六氟苯（C6F6，1当量，-80°C，15分钟）发生快速反应。","scd":null,"kp":[]},{"i":42420,"as":"该研究利用单分子粘附力成像策略，实现了在实际液相条件下对局部结合力的高空间分辨率定量测绘。通过将多巴胺等功能分子共价系在原子力显微镜（AFM）探针上，直接测量了位点特异性的分子与活性位点相互作用力。这种方法克服了传统光谱和显微技术仅能提供宏观平均信息的局限性，在分子水平上直接量化了反应物分子与缺陷位点之间的结合力。","scd":null,"kp":[]},{"i":42421,"as":"","scd":null,"kp":[]},{"i":42422,"as":"","scd":null,"kp":[]},{"i":42423,"as":"","scd":null,"kp":[]},{"i":42424,"as":"","scd":null,"kp":[]},{"i":42425,"as":"","scd":null,"kp":[]},{"i":42426,"as":"","scd":null,"kp":[]},{"i":42427,"as":"","scd":null,"kp":[]},{"i":42428,"as":"","scd":null,"kp":[]},{"i":42429,"as":"","scd":null,"kp":[]},{"i":42430,"as":"该研究探讨了利用酶促糖基化和酰胺化反应重塑多烯类天然产物生物活性的方法。多烯是广泛使用的广谱抗真菌剂，但存在严重毒性和溶解性差等临床限制。研究利用酶促技术对多烯分子进行改造，克服了传统化学合成成本高、步骤和原子效率低的缺点，旨在寻找更安全、更有效的多烯类抗真菌替代药物。","scd":null,"kp":[]},{"i":42431,"as":"机载激光雷达扫描数据显示，在公元100年至300年期间，占大亚马逊地区不到3%的面积上，可能居住着125万至300万人口，并包含超过20,000个人造土方工程。这些发现要求重新评估前殖民时代亚马逊地区的人口密度，以及这些古代文明对当今热带土壤和森林的影响。","scd":null,"kp":[]},{"i":42432,"as":"现代头足类动物（如鱿鱼和墨鱼）的运动依赖于一种特殊的体管结构来实现浮力控制。最新发现的Eoceras化石是一种仅有毫米大小且包含体管的头足类动物。这一发现表明，头足类动物群落在约5.2亿年前的早寒武世就已经出现。","scd":null,"kp":[]},{"i":42433,"as":"对38个美国州新数字化的抵押贷款记录分析显示，1930年代和1940年代由联邦住房管理局（FHA）和退伍军人管理局（VA）支持的抵押贷款计划存在严重的种族不平等。黑人和家庭被系统性地排除在获得这些贷款之外，而移民获得的抵押贷款比例与其人口数量成正比。这些贷款计划对美国崇尚拥有住房的社会形态起到了主要作用。","scd":null,"kp":[]},{"i":42434,"as":"向海洋中添加铁以刺激吸收碳的浮游植物生长（人工藻华），可以达到去除大气碳的目的。然而，这种做法产生的生态后果可能会远远超出干预地点的范围，带来不可控的环境影响。","scd":null,"kp":[]},{"i":42435,"as":"对数百个儿童肿瘤样本（富含预处理、复发和转移样本）进行的全基因组测序研究表明，癌症治疗方法（特别是基于铂类的化疗）与快速获得独特的DNA损伤模式直接相关。这些突变特征与较差的治疗结果相关联，可用于跟踪癌症复发并指导后续的治疗决策。","scd":null,"kp":[]},{"i":42436,"as":"四个独立的研究团队报告了基于自旋量子比特（spin qubits）构建的量子计算设备取得的重大进展。这项曾被低估的技术在设备研发中实现了更低的错误率，在迈向实用化量子计算机的竞赛中实现了重大飞跃。","scd":null,"kp":[]},{"i":42437,"as":"利根川进是日本首位获得生理学或医学诺贝尔奖的科学家。作为一名无畏的分子生物学家，他的研究揭示了抗体运作机制以及记忆的分子基础，为现代免疫学和神经科学做出了杰出贡献。","scd":null,"kp":[]},{"i":42438,"as":"最新发现的具有40,000年历史的鸟类雕刻小雕像为冰河时代人类的繁荣提供了新线索。这些雕像反映了早期人类具备高超的工艺技能，这些技能可能帮助他们成功在欧洲大陆扩张。","scd":null,"kp":[]},{"i":42439,"as":"科学家正在利用RNA折叠、切换和自我重组的能力，开发新一代细胞技术。RNA凭借其高度的结构可塑性和生物功能，正逐渐成为纳米工具制造领域的理想材料。","scd":null,"kp":[]},{"i":42440,"as":"通过将重建金融公司抵押贷款公司（RFCMC）中包含的29,921笔贷款记录（1935年至1947年）与人口普查数据相关联，证实了联邦住房管理局（FHA）和退伍军人管理局（VA）早期的抵押贷款计划受益者不成比例地以白人为主。1940年美国黑人口占总人口的9.9%，但黑人借款人仅获得2.1%的FHA保险贷款和5.1%的VA担保贷款。同时，移民借款人获得的贷款比例与其人口数量相符。","scd":null,"kp":[]},{"i":42441,"as":"铁电材料具有可通过电场反转的自发极化，是非易失性存储器和传感器的核心。大多数常规铁电体的极化源于极性模式的软化。针对主要具有面内极化的铁电体在标准器件几何结构中难以应用的现状，该研究发现了一种三层铁电材料，实现了利用面外电场操控面内极化分量的新途径，为器件设计和功能开发提供了新机遇。","scd":null,"kp":[]},{"i":42442,"as":"研究提出了一种名为瞬时孔分析物环化（tPAL）的纳米孔策略，用于准确解码多肽序列。研究开发了经过双重修饰（结合镍离子的NTA适配器和目标多肽）的工程化耻垢分枝杆菌孔蛋白A（MspA）纳米孔。这种独特的传感配置能够在连续的纳米孔读取过程中，生成分布狭窄、一致且依赖序列的信号事件，实现了对固定在纳米孔上的逐步缩短多肽的精确序列读取。","scd":null,"kp":[]},{"i":42443,"as":"纳米颗粒技术在为患有罕见病且治疗选择有限的儿童提供基因疗法方面具有广阔前景。解决药物递送问题是帮助罕见病儿童的关键。","scd":null,"kp":[]},{"i":42444,"as":"研究展示了一种硅自旋量子比特器件，包含用于相干传输量子比特的穿梭总线，可在四个隔离位置（总线站）进行交互。该器件利用穿梭和量子非破坏性自旋测量来动态填充阵列并调谐所有单量子比特和双量子比特操作。在自旋穿梭架构中实现了权重为4的奇偶校验，为量子处理器和纠错方案提供了动态和长程连接。","scd":null,"kp":[]},{"i":42445,"as":"研究提出一种闭环CO2基聚酯平台，通过简单有机催化剂引发CO2与双环丁烷（BCB）及双环戊烷（BCP）等双环烷烃单体的交替共聚，成功合成高性能且可回收的聚酯。该方法克服了CO2固定与结合过程中的热力学限制和高动力学屏障，实现了完美的交替共聚。","scd":null,"kp":[]},{"i":42446,"as":"衰老细胞通过衰老相关分泌表型（SASP）促进组织功能障碍。研究发现，线粒体代谢为炎症程序的执行提供了第二层控制。在衰老细胞中，线粒体丙酮酸-柠檬酸-乙酰辅酶A轴表达上调，增加了乙酰辅酶A的可用性以支持SASP基因的组蛋白乙酰化。虽然线粒体DNA驱动的信号能激活炎症转录因子，但乙酰辅酶A是炎症反应执行所必需的。","scd":null,"kp":[]},{"i":42447,"as":"研究对原核生物STAND NTPases进行了系统发育分析，发现了至少90个与抗病毒防御相关的结构不同的家族。研究发现Avs7家族能够识别有尾噬菌体的主要衣壳蛋白。通过冷冻电子显微镜解析了鼠伤寒沙门氏菌Avs7的结构，揭示了一个不对称的蝴蝶状四聚体，该四聚体通过配体结合逐步组装。这表明多样化的细菌模式识别受体能够感知核心噬菌体蛋白质组。","scd":null,"kp":[]},{"i":42448,"as":"研究引入了压手性效应，通过机械应变实现了对固体系统手性的控制。手性是物理学、化学和生物学中许多重要现象的基础。此前由于缺乏与这种结构秩序呈线性耦合的通用共轭场，实现连续且双向的手性控制一直难以实现。压手性效应为固态系统中手性的合理调控提供了新途径。","scd":null,"kp":[]},{"i":42449,"as":"著名考古遗址霍勒菲尔斯洞穴的新发现增加了古代人类文化的神秘感。这些新发现表明，艺术可能在古代人类的成功中扮演了关键角色。","scd":null,"kp":[]},{"i":42450,"as":"纳米技术领域正处于重大突破的边缘，但要实现其真正的潜力，需要各方协同努力并提供持续支持。","scd":null,"kp":[]},{"i":42451,"as":"在亚马逊地区发现了近400个土方工程结构，这一发现有望重新定义阿基里文明的真正规模，表明当地曾存在庞大的古代文明。此外，报道中还提及了已知最早的化石化鱿鱼祖先的微小化石。","scd":null,"kp":[]},{"i":42452,"as":"","scd":null,"kp":[]},{"i":42453,"as":"","scd":null,"kp":[]},{"i":42454,"as":"为了解决极端温度事件预测的难题，研究提出了Hankelformer深度学习架构。该模型结合了基于Hankel矩阵的结构化数据增强与对比学习，通过构造Hankel矩阵来捕捉局部的时空动态而不破坏时间连贯性，生成受延迟嵌入启发的原始数据视图。这显著提升了模型捕捉快速转变和偏离历史行为的异常模式的能力，从而有效改进极端天气事件的预测。","scd":null,"kp":[]},{"i":42455,"as":"","scd":null,"kp":[]},{"i":42456,"as":"使用原位光学显微镜观察了石墨插层过程中稀阶段的离子插层动力学，提供了一个统一的图景。研究观察到石墨颗粒经历了快速、局部的脱插层-插层步进事件，导致微米级区域在几秒钟内完成脱插层和插层过程。这种雪崩般的插层现象类似于晶界运动，揭示了对称性破缺相变在操作条件下持续发生的内在机制。","scd":null,"kp":[]},{"i":42457,"as":"在果蝇肠道中，干细胞通过特定的分裂次数来维持不同细胞类型的平衡。干细胞会进行八轮细胞分裂以形成吸收细胞，随后进行一轮分裂以形成分泌细胞，以此维持细胞比例。","scd":null,"kp":[]},{"i":42458,"as":"气候变化及其他人类活动的影响促使蚊子扩大了其栖息范围，导致蚊媒疾病感染人数创下新纪录。通过四张数据图表展示了蚊子是如何在全球范围内扩张并征服世界的。","scd":null,"kp":[]},{"i":42459,"as":"有胎盘哺乳动物在古新世演化出高度多样的臼齿以适应肉食和草食等特化饮食。此前发现的晚白垩世类动物具有类似有胎盘类有蹄动物的 低丘齿臼齿，暗示了白垩纪存在更接近有胎盘类的辐射演化。然而，由于一直未发现单个类动物的完整齿骨和骨骼标本，其在物理学和系统发育学上的确切分类位置至今仍未解开。","scd":null,"kp":[]},{"i":42460,"as":"研究利用冷冻电子断层扫描、子断层图平均和结构预测技术，确定了原型痘病毒——痘苗病毒中门户复合物的结构和组成。该复合物是一个跨越病毒核心壁的孔隙，呈六聚体结构，由E8等蛋白构成。这一发现有助于加深对痘病毒生物学的理解，对应对猴痘疫情具有重要意义。","scd":null,"kp":[]},{"i":42461,"as":"研究展示了在太赫兹频率下，利用表面等离激元腔超材料实现了光子时间晶体（PTC）的全光学制备。光子时间晶体通过在时间上周期性调制光学性质来实现，但通常需要强烈且超快的调制。这是首个全光学方式实现PTC的实验，克服了在极短时间尺度上实现调制的实验挑战。","scd":null,"kp":[]},{"i":42462,"as":"现代头足类动物通过体管调节气液混合以控制浮力。此前最早公认的头足类动物是晚寒武世的Plectronoceras cambria，但其与分子钟预测的早寒武世起源之间存在巨大空白。研究在中国南方水井沱组发现了早寒武世毫米级直角壳头足类动物Eoceras shaanxiense gen. et sp. nov.，其内部具有体管结构。该发现为头足类动物关键创新的起源提供了重要化石证据。","scd":null,"kp":[]},{"i":42463,"as":"研究通过真空介导的熔融碱机械化学法合成了新型三方相Co3O4（Tri-Co3O4）。该材料具有空间群为P-3m1(164)的边共享[CoO6]八面体配位结构，其三层致密结构使得Co2+和Co3+均以1:2的比例位于八面体配位中。在酸性析氧反应中，Tri-Co3O4在10 mA cm-2的电流密度下实现了仅269毫伏的低过电位，展现出替代铱基材料的优异催化活性和稳定性。","scd":null,"kp":[]},{"i":42464,"as":"研究利用原位冷冻电子显微镜技术，直接对水稻叶绿体进行了成像，确定了光合系统超复合物在其天然膜环境中的结构。研究成功解析出了C2S2M2L4等天然组织状态下的光系统超复合物结构，揭示了光系统I（PSI）和光系统II（PSII）在类囊体膜中的原始组织形式，加深了对光合作用机制的理解。","scd":null,"kp":[]},{"i":42465,"as":"二维π共轭聚合物因其低成本和光电可调性成为光催化分解水产氢的理想材料，但其光激发态被限制在平面内，易发生载流子复合。为解决这一问题并最大化电荷利用率，研究提出诱导面外载流子迁移的机制，即促进载流子通过范德华键合层流动。这种通过垂直载流子流动进行光催化分解水的新策略，有效突破了二维聚合物面内电荷分离的量子效率瓶颈。","scd":null,"kp":[]},{"i":42466,"as":"研究利用包含海洋生物多样性和生物地球化学表示的模型，评估了海洋铁 fertilization 作为二氧化碳去除策略的潜力及其生态影响。在十年内对十个海洋生物群系的分析表明，不同地区在气候效益与生态成本之间存在显著权衡。南大洋和赤道太平洋通过不同途径实现了最高碳去除效率，但受精藻华的消长过程各不相同。","scd":null,"kp":[]},{"i":42467,"as":"研究人员利用激光雷达技术穿透树冠，对亚马逊西南部进行了超过4430公里的飞行探测，以确定前殖民时期几何土方工程的地理分布。这些土方工程是纪念性建筑文明的证据，研究为揭示亚马逊地区深层历史、前殖民时期城市化及其环境遗产提供了关键数据，克服了以往探测仅限于森林砍伐区域的局限。","scd":null,"kp":[]},{"i":42468,"as":"研究团队推出了名为 Raygun 的生成式人工智能框架，能够对蛋白质进行微型化、修改和扩充。该框架基于语言模型嵌入构建的蛋白质序列概率编码，将蛋白质表示为概率分布而非高维空间中的变长序列。这一概念性突破使得利用蛋白质语言模型进行大规模、保留功能的序列修饰成为可能。","scd":null,"kp":[]},{"i":42469,"as":"名为 Raygun 的人工智能模型采用概率方法，能够对现有的天然蛋白质进行缩小或放大等编辑操作。该技术的出现降低了蛋白质编辑的门槛，为蛋白质的修改与功能设计提供了全新的便捷途径。","scd":null,"kp":[]},{"i":42470,"as":"研究利用果蝇肠道干细胞发现，干细胞通过表观遗传机制内在计数其自我更新分裂次数，从而控制多能性切换。在产生肠内分泌母细胞（EMC）后，果蝇肠道干细胞会精准执行八次分裂产生肠细胞（EC），并在第九次分裂时切换回EMC的生产。这种计数机制解释了在快速组织更新中如何维持特定子细胞类型的稳定比例。","scd":null,"kp":[]},{"i":42471,"as":"研究利用超过一个世纪的临床数据分析了气候变化对撒哈拉以南非洲儿童疟疾负担的影响。结果显示，气温升高可能增加了东非和南部非洲的疟疾病例，但在西非减少了数量相近的病例。总体净影响为每1000名儿童增加1例疟疾。极端降水与温度对疟疾患病率具有显著作用。","scd":null,"kp":[]},{"i":42472,"as":"两项关于硅基量子处理器的最新展示，成功应对了构建可扩展量子计算机过程中的工程挑战，展示了硅芯片技术在量子计算领域的再工程化应用与进展。","scd":null,"kp":[]},{"i":42473,"as":"量子计算的发展得益于政府资助的长期高风险投资，而要将其推向商业化落地，则需要资本主义市场力量的介入。只要科学家能够获得相应支持，商业化速度将推动量子技术走完后续发展之路。","scd":null,"kp":[]},{"i":42474,"as":"研究人员指出，采用开放同行评审报告的论文被撤稿的概率更低。这种透明的出版实践通常与更高的研究质量存在关联，但仍需要更多证据来进一步证实这一联系。","scd":null,"kp":[]},{"i":42475,"as":"消除脊髓灰质炎的目标已经触手可及，但前提是各国必须将其视为至关重要的公共卫生优先事项。如果彻底根除该病毒的任务未能尽快完成，脊髓灰质炎将面临大规模卷土重来的风险。","scd":null,"kp":[]},{"i":42476,"as":"文章介绍了一场名为“激发记忆的展览”，正文中提到了“失落的世界”。","scd":null,"kp":[]},{"i":42477,"as":"在薄铁电薄膜材料中，水平电偶极子与垂直电极化之间存在耦合效应。这种机制使得研究人员能够利用标准的器件几何结构来控制非常规的铁电材料，突破了传统控制方式的限制。","scd":null,"kp":[]},{"i":42478,"as":"两项严谨的临床试验表明，特定的两种药物在预防长新冠（Long COVID）方面显示出初步希望。试验结果证明，这些药物能够有效降低人们在感染新冠病毒后发展为长期疾病的风险。","scd":null,"kp":[]},{"i":42479,"as":"研究团队开发了一款数字控制的硅量子处理单元。该处理器由定制的低温互补金属氧化物半导体（CMOS）控制器、高密度超导带状电缆以及低噪声纯交换量子比特设备构成。硅基量子比特凭借其控制信号简单以及与先进半导体制造工艺兼容的特点，被视为实现大规模量子计算的有力候选方案。","scd":null,"kp":[]},{"i":42480,"as":"纳米科学和纳米技术领域的三位新星正在利用最小的结构单元，致力于开发下一代解决方案，推动纳米尺度材料与技术在实际前沿应用中的发展。","scd":null,"kp":[]},{"i":42481,"as":"通过虚拟现实实验观察果蝇追踪虚拟气味羽流的行为，研究发现果蝇具备与蚂蚁和蜜蜂类似的空间记忆能力。它们利用这种受记忆引导的导航工具包来追踪气味羽流的边缘，从而精确定位并寻找气味源。","scd":null,"kp":[]},{"i":42482,"as":"研究团队开发了名为 GOOSE 的计算框架，专门用于合理设计缺乏稳定三维结构的天然无序蛋白区（IDR）。该框架具备高通量和强通用性，能够设计并测试数千种IDR序列，从而揭示特定的序列与功能关系，探索序列特性如何影响细胞内IDR的结构集合，并设计出响应细胞体积等变化的IDR序列。","scd":null,"kp":[]},{"i":42483,"as":"研究团队对代表5个大洲和28个人群群体的多样化人类样本进行了组装和特征分析，成功表征了2110个着丝粒。研究鉴定出了226种着丝粒单倍型和1870种α-卫星高阶重复变异，为解析细胞分裂中确保染色体准确分离的关键区域（着丝粒）在个体与演化中的多样性全貌填补了知识空白。","scd":null,"kp":[]},{"i":42484,"as":"聚合物电解质是先进储能和电光设备的关键材料，能在单一平台内实现离子传输、机械柔顺性和操作安全性。除了在电池和超级电容器中的应用，最新进展将其扩展至多功能电致变色系统（如智能窗户、电致变色电池）。这类系统要求在设计上同时对离子电导率、电化学稳定性、光学透明度及加工性等参数进行严格控制。","scd":null,"kp":[]},{"i":42485,"as":"针对二氧化钌在质子交换膜水电解槽（PEMWE）中作为阳极催化剂在安培级电流密度下快速降解的问题，研究引入等价金属（Ti4+/Hf4+）调节Ru-O键强度。密度泛函理论计算表明，Hf4+的强诱导效应能优化Ru(4d)-O(2p)轨道重叠，从而减弱Ru-O共价性，有效抑制晶格氧活化，大幅提升催化剂的耐久性。","scd":null,"kp":[]},{"i":42486,"as":"研究通过喷涂法制备了一种增强磷光的氢键有机骨架棉花纤维膜，并结合机械驱动平台构建了荧光-磷光双通道传感系统。受昆虫触角启发的该仿生传感系统能够将宏观物理运动与发光响应机制直接相连，实现高速、高灵敏度和高精度的位移与角旋转双模态监测。","scd":null,"kp":[]},{"i":42487,"as":"研究制造了在930纳米波长下g因子为0.008的手性二氧化钛纳米颗粒，并研究了其对乳腺癌转移的影响。细胞实验表明，左旋二氧化钛纳米颗粒（L-TiO2 NPs）通过Toll样受体4进入MODE-K肠上皮细胞，触发细胞内活性氧（ROS）的产生。这激活了NF-κB和NLRP3信号通路，驱动炎症介质的释放，进而诱导乳腺癌的肺部转移。","scd":null,"kp":[]},{"i":42488,"as":"研究人员提出了一种生物质细胞质重构策略，用于全固态水系电池。该水凝胶电解质展现出优异的综合性能，机械强度达到11.6 MPa，离子电导率为20.27 mS cm⁻¹，扩散系数高达1.4 × 10⁻⁵ cm² s⁻¹。通过高效节能的盐析技术构建该凝胶，处理过程保留了天然生物质的自支撑结构，使其成为具有高机械强度和高离子传输性能的可持续电解质材料。","scd":null,"kp":[]},{"i":42489,"as":"研究开发了一种用于PET塑料升级回收的非贵金属电催化剂，由原位集成在CuCo合金骨架上的Co3O4-CuO异质结构组成。该催化剂能选择性介导PET水解液中的乙二醇发生电氧化反应，生成甲酸和氢气，从而简化并降低单体分离的成本。测试表明，该催化剂在1.5V（相对于可逆氢电极）下展现出约930 mA cm⁻²的高活性，大幅提升了电催化效率与选择性。","scd":null,"kp":[]},{"i":42490,"as":"针对电化学析氯反应（CER）中原子级Ru-O活性位点存在的不稳定性和OH*毒化问题，研究构建了一种层间工程电极。该电极利用MnO2纳米中间层外延包裹纳米锥阵列，有效限制并调节原子级Ru-O团簇。通过Ru-O-Mn-O-Ti链接产生的强电子耦合作用，不仅抑制了团簇溶解，还促进了界面电子重排，优化了*Cl吸附，显著提升了CER过程的稳定性与催化效率。","scd":null,"kp":[]},{"i":42491,"as":"为解决锂金属负极存在的不稳定性和过量锂等问题，研究设计并合成了由掺氮碳壳封装的焦磷酸亚铁空心纳米棒（Fe2P2O7@NC），作为高性能的锂金属负极宿主材料。这种基于Fe2P2O7@NC涂层的电极有效改善了锂金属电池在低负/正极容量比（N/P比）条件下的循环稳定性与电化学性能。","scd":null,"kp":[]},{"i":42492,"as":"研究确定清道夫受体CD36是人类札如病毒（HuSaV）引发感染的关键受体。CRISPR基因敲除实验证实，去除CD36会完全消除病毒复制，而过量表达则恢复易感性，两者间具有纳摩尔级的亲和力。此外，病毒入侵还需要胆汁酸（甘胆酸）的协助以促进CD36的内化。在人肠道类器官实验中，敲除CD36同样彻底阻断了感染，确认了其生理相关性。","scd":null,"kp":[]},{"i":42493,"as":"研究通过二维石墨纳米狭缝成功构建了具有力敏特性的离子传输系统。其力敏响应机制源于对通道单侧入口的选择性充电，使其成为可移动电荷载体的可逆来源。在压力驱动的水流作用下，离子被带入或带出通道，从而调节离子电导率。这一过程不涉及纳米通道本身的结构变形，为设计无形变的双极压力敏感流体器件提供了电流体力学新机制。","scd":null,"kp":[]},{"i":42494,"as":"研究探讨了在陌生或经验有限的环境中，人类决策者如何利用情景采样策略评估选项价值。通过对比儿童、青少年与成人，发现记忆的精度和情境敏感性是影响情景采样有效性的关键因素。由于记忆结构在发育过程中不断成熟，这些认知属性的年龄差异直接改变了个体在基于奖励的决策中，对提取的过去经验片段的使用方式及评估策略。","scd":null,"kp":[]},{"i":42495,"as":"研究揭示了成熟橡树林在高二氧化碳浓度（eCO2）下实现生物量增加的土壤氮机制。六年的自由空气二氧化碳富集实验表明，增强的氮矿化和生态系统氮保持维持了高CO2下的森林生产力。特别是在橡树发芽期，原位净氨化和总氨化速率显著提高了约30%。这种更快速、更紧凑的氮循环机制为森林在富碳环境下的固碳能力提供了关键支持。","scd":null,"kp":[]},{"i":42496,"as":"研究揭示了神经胶质细胞的异质性在中枢神经系统（CNS）区域特异性血管生成中的调控机制。星形胶质细胞缺失选择性地破坏了灰质血管生成，而少突胶质细胞谱系缺失则导致白质血管化不全。灰质星形胶质细胞通过富集缺氧诱导因子HIF1α及VEGF信号通路促进血管生长；少突胶质细胞则通过富含的染色质重塑因子CHD8直接调控白质的血管新生。","scd":null,"kp":[]},{"i":42497,"as":"研究结合单分子荧光共振能量转移与全内反射荧光显微镜，实时观察了萤火虫荧光素酶与分子伴侣Hsp70（DnaK）和Hsp90（HtpG）的相互作用过程。结果显示，HtpG通过结合和水解ATP，降低了DnaK对折叠中间体的重结合频率，同时保留了对错误折叠底物的识别能力。这一协调机制克服了通常情况下高浓度DnaK带来的抑制效应，成功促进了目标蛋白质的有效重折叠。","scd":null,"kp":[]},{"i":42498,"as":"为提升氢气提纯和天然气升级的气体分离效率，研究以商业聚合物Matrimid为基质，引入具有选择性空腔的葫芦脲（CB）作为短路径气体传输通道。这种改性的Matrimid-CB-5%膜增加了气体传输路径，提升了膜结构内部气体传输网络的连通性。相比纯基质膜，该膜材料改变了气体微孔传输机制，有效调节了微孔结构，从而在渗透性与选择性之间实现了优异的平衡。","scd":null,"kp":[]},{"i":42499,"as":"研究在26种蝙蝠物种中鉴定出位于不同染色体上的双重免疫球蛋白重链（IgH）基因座，打破了已知哺乳动物仅有单一IgH基因座的共识。以大棕蝠为模型，单细胞转录组数据证实了这两个基因座均可进行功能性重排与表达。蝙蝠通过这种独特的双基因座遗传架构，能够利用不同的抗体多样性生成机制增强免疫功能，这为研究蝙蝠作为病毒宿主的免疫逃逸提供了重要基础。","scd":null,"kp":[]},{"i":42500,"as":"研究开发了一种受蒲公英启发的超轻型（1.2毫克）无人机。该六边形聚合物装置能够通过被动方式在空中飞行，并利用光信号实现轨迹的精确控制。其核心机制依赖于由六个独立软致动器驱动的光机械形变，动态控制六个径向排列的丝状结构形态。这种基于涡流稳定性的设计，成功解决了无系留厘米级微型飞行器在空中缺乏主动可控机动性的技术难题。","scd":null,"kp":[]},{"i":42501,"as":"基于214项全球田间增温实验数据集，研究发现高温和极端高温（>35°C）暴露是导致气候变暖下水稻减产的主导因素，主要通过降低收获指数造成损失。在生殖阶段，高于30°C的暴露每增加一天，水稻产量便会下降1.1%至1.8%。目前的全球网格化作物模型严重低估了这一敏感性，模拟的减产仅为0.1%至1.3%。校正此偏差有助于更精准地评估气候变暖对粮食安全的真实影响。","scd":null,"kp":[]},{"i":42502,"as":"研究利用细胞尺寸的脂质体体外重组肌动蛋白网络，结合计算模型，揭示了细胞膜起泡与对称性破坏的物理机制。研究发现，肌动蛋白与细胞膜之间的耦合强度决定了膜形变的大小；而这种耦合与肌动蛋白网络连通性之间的平衡，决定了膜起泡的起始方式，即通过皮层脱离膜或皮层自身破裂来实现。这一平衡机制精确调控了细胞单一起泡或多重起泡的形成过程。","scd":null,"kp":[]},{"i":42503,"as":"利用自旋分辨角分辨光电子能谱及第一性原理计算，研究对2纳米厚的超薄外延应变二氧化钌（RuO2）薄膜的电子结构进行了探测。结果观察到在超薄极限下，基板施加的外延应变诱发了独特的电子态，显现出镜像奇偶交替分布的自旋纹理结构。这一发现揭示了在体相及厚膜中未表现出的新物理现象，为探索新型交变磁性材料及其自旋电子学应用提供了实验依据。","scd":null,"kp":[]},{"i":42504,"as":"针对心血管植入物的内皮愈合难题，研究开发了一种具备动态刚度特性的仿生涂层。该涂层通过重组人源化III型胶原蛋白与胱胺改性透明质酸的逐层组装及交联制成。涂层能够响应微环境中的谷胱甘肽和活性氧等刺激，展现出阶段性功能：初期有效抑制急性血栓形成并引导细胞黏附；随后刚度动态降低，促进形成融合且功能完整的内皮单层，从而显著提升血管植入物的修复效果。","scd":null,"kp":[]},{"i":42505,"as":"基于20年的卫星观测数据分析，研究发现2003年至2022年间北大西洋和巴伦支海的颗石藻水华发生了显著衰退，水华面积减少了36.1%，频率下降了51.2%。温带北大西洋和西巴伦支海的衰退最为严重，而东巴伦支海则呈增加趋势。北大西洋海表温度（SST）下降与东巴伦支海变暖是驱动这些变化趋势的关键因素。然而，单一的温度变化无法完全解释巴伦支海两岸呈现出的不对称演变模式。","scd":null,"kp":[]},{"i":42506,"as":"为解决倒置钙钛矿太阳能电池中自组装单分子层（SAMs）易脱附和团聚导致的界面损耗问题，研究设计了一种具有非共面分子构型和多官能团的分子TTA。其非共面结构有效抑制了π-π堆积引起的分子聚集，实现了更规则的分子排布。同时，结合噻吩官能团与三齿羧酸锚定基团，该分子大幅增强了与基底及上方钙钛ite层的结合力，有效强化了钙钛矿/硅叠层太阳能电池的埋底界面稳定性与器件性能。","scd":null,"kp":[]},{"i":42507,"as":"衰老大脑中的神经干细胞（NSC）再生能力会下降。研究人员利用质谱技术进行脂质组学分析，发现静止期NSCs在体内外均存在与年龄相关的复杂脂质变化，且各类脂质中的多不饱和脂肪酸在衰老过程中显著增加。空间脂质组学证实这些变化同样存在于原位组织中。通过对分离的质膜囊泡进行检测，证实上述复杂脂质及侧链组成的年龄相关变化主要发生在细胞质膜上。","scd":null,"kp":[]},{"i":42508,"as":"为解决深度学习对低能耗、高计算速度硬件的需求，研究提出一种并行非线性神经形态处理器。该处理器利用时空超表面的时间编码，实现了多维通道中信息状态的任意叠加。实验表明，基于分布式时空方法，该技术克服了传统非线性材料和光电转换在功率效率和可操控性上的局限，成功解决了同时实现高线性和非线性表达能力的难题。","scd":null,"kp":[]},{"i":42509,"as":"研究人员利用纸喷雾电离质谱技术实现了对催化反应过程中分子定义纳米团簇的机制可视化。该技术成功在4-硝基苯酚还原和铃木-宫浦交叉偶联反应中识别出关键反应中间体并追踪其演化过程。研究获取了反应决速步骤、活性位点动态变化以及催化剂演化的关键信息，克服了传统工具难以在原子分辨率下关联催化剂结构与活性的挑战。","scd":null,"kp":[]},{"i":42510,"as":"受生物肌肉骨骼系统启发，研究人员开发出一种具备形态和动力学双重可编程性的微型柔性人工肌肉骨骼致动器。该致动器由串联的可变形骨架模块和基于多层PDMS介电弹性体与电热驱动形状记忆聚合物的刚度可调肌肉模块构建而成。这项技术克服了小型化无系绳可变形机器人的发展瓶颈，推动了具身智能机器人在多模态和跨域运动中的应用。","scd":null,"kp":[]},{"i":42511,"as":"GABAA受体是中枢神经系统抑制性神经传递的主要介质，其α2和α3亚型与焦虑、疼痛、癫痫等症状相关。传统选择性小分子药物为避免脱靶效应不得不牺牲药效。为打破这一僵局，研究开发并测试了一组针对α2和α3亚型的纳米抗体，确定了这些纳米抗体的分子作用机制及其生理学效应，为精准靶向治疗提供了新方案。","scd":null,"kp":[]},{"i":42512,"as":"辅酶Q的生物合成需要COQ8A和COQ8B两种非典型激酶样蛋白。研究发现这两种蛋白具有ATP酶活性，通过松散的蛋白质相互作用促进辅酶Q合成代谢体的活性，并递送不溶性合成中间体。结构生物信息学和X射线晶体学表明，ATP水解控制的长程构象变化像一个“门”，调控着一个新发现的口袋，该口袋通过头部基团选择性识别辅酶Q合成中间体。过量的辅酶Q会抑制早期中间体的结合。","scd":null,"kp":[]},{"i":42513,"as":"研究提出一种结合结构定义的DNA-碳纳米管传感器阵列和机器学习（ML）模型的人工感知系统（APS），用于非侵入性癌症液体活检。该系统通过多通道荧光指纹解码血清疾病状态。在涵盖肝癌、肺癌、卵巢癌及非癌对照的253份样本中，APS平均敏感度为89%，特异性为96%。对早期肺癌的检测敏感度达92%，特异性为95%，单次测试成本仅约4美元。","scd":null,"kp":[]},{"i":42514,"as":"针对癫痫精神症状是否与发作具有相同病理机制的问题，研究调查了由ALDH7A1突变引起的单基因癫痫。在ALDH7A1全局敲除小鼠中，发作表型由肝细胞缺失引起，而适应不良的情感行为则由星形胶质细胞缺失引起。星形胶质细胞缺失破坏了其氧化还原稳态，削弱了对细胞外离子浓度的调节，并降低了前边缘皮层的神经元活动，揭示了两者具有独立的病理学机制。","scd":null,"kp":[]},{"i":42515,"as":"研究开发了一种适用于太空光伏的单片宽带隙钙钛矿/p型异质结硅串联太阳能电池。通过多功能离子液体添加剂稳定了1.72电子伏特宽带隙钙钛矿吸收层，提高了结晶度和稳定性。该电池的功率转换效率达24.0%（认证值23.58%），零空气质量认证效率达27.49%（面积12.56平方厘米）。在1兆电子伏特电子辐照下展现出极强的辐射耐受性。","scd":null,"kp":[]},{"i":42516,"as":"研究提出了一种名为TEMPi的扭曲编码磁等离子体干涉测量技术，实现了无标记、方向分辨的单分子成像。该技术将金属薄膜附近纳米棒的扭转转化为相位编码的取向光学信号，利用金纳米棒与其镜像的近场耦合激发局域磁等离子体，将探针扭转定量映射为干涉相位。该技术能在天然缓冲液中实时追踪单分子旋转动力学和构象变化，解析出三种依赖限制的旋转状态。","scd":null,"kp":[]},{"i":42517,"as":"视紫红质（RHO）错义突变是常染色体显性视网膜色素变性的主要原因。研究利用深度突变扫描技术，结合表面丰度免疫分析和膜邻近检测，绘制了涵盖全部6612种可能的RHO错义变体的高分辨率蛋白质运输图谱。数据具有高度可重复性，发现超过700个变体具有致病性运输评分，大幅扩展了已知致病RHO变体的数量，为理解疾病机制和开发治疗方法提供了重要基础。","scd":null,"kp":[]},{"i":42518,"as":"研究开发了一种名为RAPIDO的无线可编程植入式神经设备，用于慢性神经药理学和光遗传学实验。该系统集成了可替换、可充注且防回流的流体模块，以及微型无机发光二极管探针。带有单向阀的可替换墨盒实现了药物溶液的快速充注。结合物联网技术，RAPIDO允许实验人员远程控制药物递送和光学刺激，避免了传统设备剂量不准、易污染及实验人员在场对神经和行为的干扰。","scd":null,"kp":[]},{"i":42519,"as":"研究结合热岩石学建模、火山脱气和弧地球化学数据，对比了极寒的汤加俯冲带和炎热的哥伦比亚俯冲带的脱碳特征。研究识别出两种截然相反的模式：炎热俯冲带发生高效率（>15%）的“聚焦”脱碳，碳释放集中在75-115公里深度；而寒冷俯冲带则发生缓慢的“弥漫”脱碳。这表明俯冲带的温度条件直接决定了其深层碳循环的效率。","scd":null,"kp":[]},{"i":42520,"as":"研究探究了大脑如何支持外部线索驱动和内部驱动的运动。在小鼠执行自发或线索触发的按压杠杆任务时，利用双光子钙成像记录背外侧纹状体活动。无监督聚类识别出在提示、运动或动作后阶段被调节的神经元。关键发现是，相同的纹状体神经元在不同启动环境下编码运动，但其群体动态呈现显著的上下文特异性差异。这表明不同运动模式由共享神经元群体通过动态切换来实现。","scd":null,"kp":[]},{"i":42521,"as":"受生物机械敏感离子通道启发，研究开发出一种机械离子晶体管。该器件通过石墨烯纳米通道在静电门控下，展现出阶跃式的流动电流-压力响应。其亚阈值摆幅极低，约为4.8毫巴/十倍频（定义为将流动电流增加10倍所需的最小压力），比人工仿生系统低几个数量级。这种基于离子-电子耦合的晶体管成功实现了在明显开关状态之间的急剧切换。","scd":null,"kp":[]},{"i":42522,"as":"研究证实SWI/SNF染色质重塑复合物中的PBRM1亚基对乳腺癌的上皮-间充质转化（EMT）和转移至关重要。表观基因组学分析表明，PBRM1对于将PBAF复合物靶向结合到带有H3K14ac标记的诱导型启动子上是必需的。PBRM1促进了靶点处的DNA可及性，从而在体外介导乳腺细胞完成TGFβ1诱导的EMT过程，并在体内促进小鼠乳腺癌的转移。","scd":null,"kp":[]},{"i":42523,"as":"研究利用价中心策略，将八聚体酶与八条自互补单链DNA结合，构建出具有非凡机械性能的DNA键合蛋白质单晶。八价分子键使偶联物组装成体心四方晶体，衍射分辨率达1.42至2.61埃。晶体接触由跨度17至25埃的B型DNA螺旋介导。增加寡核苷酸长度会引发各向异性晶格膨胀，同时保持原子周期性。该技术解决了传统DNA胶体纳米颗粒组装难以达到原子级结构有序度的问题。","scd":null,"kp":[]},{"i":42524,"as":"针对太阳系早期冷凝物中保存有太阳系前恒星尘埃的争议，研究通过分离原始细粒富钙铝包体的原生相锶元素进行分析。研究证实极端的锶-84异常主要存在于一部分CAI氧化物中。原始非载体相的异常虽然减弱，但与太阳系前体物质的丰度相关。这表明太阳系前恒星尘埃作为成核种子，参与了太阳系最早固体矿物的凝结，并对随后的凝结过程产生重要影响。","scd":null,"kp":[]},{"i":42525,"as":"为克服以往马立克氏病病毒（MDV）毒力研究的局限，研究对65种经过标准化表型鉴定的MDV毒株进行了全基因组测序。除了系统发育和重组分析外，该研究对该病原体进行了全基因组关联分析（GWAS）。结果共鉴定出10个与毒力显著相关的全基因组位点，这些位点与MDV的致瘤性和疫苗逃逸密切相关，为理解毒力历史演变提供了重要数据。","scd":null,"kp":[]},{"i":42526,"as":"人类视觉无法感知红外线。研究开发了一种基于胶体量子点的红外至可见光的上转换器件，实现了多光谱红外光辐射向全彩视觉的超灵敏转换。量子限域态中的光子能量选择性激子跃迁决定了红外波长，光子通量决定了光生载流子数量。通过精心设计的空穴注入势垒，双发射层有机结构能将这些载流子路由到不同的颜色发射通道，成功将不可见的红外光转化为全彩图像。","scd":null,"kp":[]},{"i":42527,"as":"树突状细胞（DCs）中的非典型RelB NF-κB通路能够抑制肠道中的调节性T细胞。研究发现，在DCs中敲除RelB基因会损害肠道内依赖白细胞介素-23（IL-23）的免疫反应，导致小鼠对肠道病原体啮齿柠檬酸杆菌感染表现出易感性。机制研究表明，RelB支持了RBP-J的表达，从而调控Notch2信号传导，这对于肠道内单个孤立淋巴样组织驻留DCs分泌IL-23至关重要。","scd":null,"kp":[]},{"i":42528,"as":"膜成珠现象是指管状结构转变为念珠状的过程。研究利用光控线粒体特异性力学刺激器对活细胞线粒体施加拉力，发现拉伸会触发整个管状线粒体的成珠现象。机制表明，线粒体内膜（IMM）在拉伸诱导的成珠过程中发挥关键作用，因为单层膜管无法发生此现象。该过程介导了线粒体腔内物质的分离和膜分裂。","scd":null,"kp":[]},{"i":42529,"as":"植物免疫依赖于丝裂原活化蛋白激酶（MAPK）级联反应。研究发现，大丽轮枝菌分泌的效应蛋白VdHCE1直接靶向宿主的MAPK信号传导，并与MKK5发生相互作用。VdHCE1在植物体内被磷酸化，它通过与MPK3和MPK6竞争作为MKK5的底物，削弱下游的MAPK激活。VdHCE1能够抑制免疫反应，其缺失会导致病原菌致病力下降。","scd":null,"kp":[]},{"i":42530,"as":"自噬过程中，脂质转移蛋白Atg2将自噬体前体与内质网（ER）结合，介导脂质供应以驱动自噬体扩张。在酵母中研究表明，Atg2通过与内质网驻留蛋白Scs2相互作用实现其在内质网上的锚定。这种结合依赖于Atg2中的磷酸化FFAT基序和Scs2的主要精子蛋白（MSP）结构域。Atg2的磷酸化作用进一步增强了这种结合，从而实现对自噬体形成的时空调控。","scd":null,"kp":[]},{"i":42531,"as":"材料的界面迁移通常被视为无质量的过程。研究通过施加高频振荡驱动，证明了晶界在此时表现出可测量的惯性特征。研究团队通过测量施加力与界面速度之间的相位滞后，开发了一种提取有效界面质量的方法，并发现该质量与参与边界迁移的原子数量成比例。这一发现为理解界面动力学提供了新的定量框架。","scd":null,"kp":[]},{"i":42532,"as":"研究利用冷冻电子断层扫描技术，解析了原代人CD8+ T细胞中线粒体核糖体的结构和空间组织。对比分析显示，老年人T细胞中的线粒体核糖体丰度和高阶组织结构出现与年龄相关的下降，而高阶结构对于协作翻译至关重要。线粒体翻译的缺陷会抑制细胞质核糖体蛋白的表达，从而限制线粒体的生物发生，导致T细胞功能障碍。","scd":null,"kp":[]},{"i":42533,"as":"二斑叶螨通过吸食叶肉细胞为生。研究发现，当叶螨转移到不同宿主植物上时，载脂蛋白D（ApoD）基因的表达会发生显著变化。该基因家族出现了极度扩张，包含64个旁系同源物，是所有生物中报道的最大基因家族。这种扩张的ApoD家族为叶螨提供了双层保护机制，使其能够有效抵抗由不同植物宿主带来的饮食氧化应激。","scd":null,"kp":[]},{"i":42534,"as":"","scd":null,"kp":[]},{"i":42535,"as":"早期复杂社会的社会动态存在巨大差异。研究通过对63个社会变化轨迹在五个分化轴上进行整体排序，多维视角地分析了其发展。分析揭示了大多数轨迹符合六条通过“复杂化”的重复路径之一，这些路径在不同轨迹中表现出相似的发展过程。这些模式为理解不同形式的复杂性出现（或未能出现）的条件提供了框架。","scd":null,"kp":[]},{"i":42536,"as":"耐碳青霉烯肺炎克雷伯菌是全球多重耐药（MDR）感染的主要原因，其主要序列类型为ST258。临床菌株的基因组分析发现，双组分调控系统CrrAB是ST258的基因组特征。研究表明，肺炎克雷伯菌菌毛的翻译后修饰驱动了其致病性，这一机制可能有助于解释ST258在全球范围内的流行优势。","scd":null,"kp":[]},{"i":42537,"as":"传统的抗蛇毒血清疗效和安全性差异较大。研究受蝰蛇自身进化出血清毒素抑制剂的启发，设计了一种新型抗蛇毒策略。团队研究了一组源自祖先血清糖蛋白Fetuin-A的四种响尾蛇金属蛋白酶（MP）抑制剂（FETUAs）的效力。结果证实，这些保守的血清金属蛋白酶抑制剂组合能够有效阻断蝰蛇毒液的致死性酶促作用。","scd":null,"kp":[]},{"i":42538,"as":"大分子拥挤环境通过耗竭相互作用等熵力调控蛋白质动力学。研究利用欧洲X射线自由电子激光器的兆赫兹X射线光子相关谱（MHz-XPCS），探测了含有聚合物拥挤剂的溶液中铁蛋白的动力学。研究发现，聚合物拥挤剂引起了蛋白质集体动力学的显著变化，揭示了由耗竭驱动的短程吸引力与长程排斥力结合，产生了中程尺度的组织结构。","scd":null,"kp":[]},{"i":42539,"as":"时间平均（TA）决定了古生物学数据的分辨率。研究利用氨基酸和放射性碳测年法，对晚第四纪海洋钙化生物化石组合中的样本进行了年代测定。估算的TA范围从几十年到数千年不等。数据表明，时间平均与沉积物积累时间（SAT）呈正比例关系（r2 = 0.77）。研究结果证明了沉积物积累速率可以直接预测海洋化石组合的时间分辨率。","scd":null,"kp":[]},{"i":42540,"as":"基因共享二分网络连接了基因与包含它们的基因组，能够展示病毒和移动遗传元素的进化。该网络表现出无标度的基因度分布和指数级的基因组度分布。研究提出了一个机制模型，通过水平基因转移、新基因捕获、新基因组出现和基因丢失等基本进化过程来解释这些模式。通过均场近似推导出的解析表达式与数值模拟结果一致。","scd":null,"kp":[]},{"i":42541,"as":"","scd":null,"kp":[]},{"i":42542,"as":"苯甲醛合酶（BS）催化植物挥发性化合物苯甲醛生物合成的最后一步。研究报道了矮牵牛BS的晶体结构，揭示了其α2β2异四聚体的排列方式。生化和结构分析表明，α亚基包含典型的催化位点，而β亚基虽失去催化活性，但对异四聚体的组装至关重要。β亚基的C端延伸至对角的α亚基中，对酶的结构稳定性和催化功能发挥起关键作用。","scd":null,"kp":[]},{"i":42543,"as":"针对传统压电超声波技术在电池状态监测中的局限，研究提出了一种空气耦合、非接触式的激光激发超声传感（LEUS）结合Transformer网络的操作状态评估方法。该系统采用双激光设计，通过环形脉冲激光和连续激光产生并检测高质量超声波。与传统配置相比，超声波振幅增加了10倍，信噪比达到30分贝（提高了16分贝），能够精确追踪电池在不同速率操作下的内部状态变化。","scd":null,"kp":[]},{"i":42544,"as":"气溶胶光学厚度（AOD）的卫星反演与地面网络验证之间的吻合度已得到改善，但研究指出全球验证框架存在关键失衡。地面验证站点不成比例地集中在城市和植被覆盖区，而干旱区由于具有亮地表和粗模态气溶胶，其站点数量几乎少了一半。这种采样偏差导致全球验证结果出现系统性扭曲，凸显了在干旱地区进行气溶胶遥感研究的紧迫需求。","scd":null,"kp":[]},{"i":42545,"as":"葡萄糖依赖性促胰岛素多肽（GIP）是促进餐后胰岛素释放的肠促胰岛素。研究通过分析特异性刺激或缺失肠内分泌K细胞中Gi信号的突变小鼠，探讨了异三聚体Gi蛋白在体内的调节作用。结果显示，在体内改变K细胞中的Gi信号会引起葡萄糖稳态的显著变化，揭示了Gi信号在调节K细胞功能及释放GIP过程中的直接机制。","scd":null,"kp":[]},{"i":42546,"as":"莫里斯·莫斯科维奇五十年的研究重塑了对大脑记忆的理解。他提出的“多重痕迹理论”挑战了海马体仅作为临时存储库的传统观点，证明了详细的情景记忆会无限期地依赖海马体。他的研究还证明海马体不仅参与记忆，还与想象、解决问题和社交认知有关。近期工作发现，人们能通过情景记忆的丰富度来感知他人，并以此指导社交偏好。","scd":null,"kp":[]},{"i":42547,"as":"研究报道了一种保存完好的三叠纪爬行动物化石，它是已知最早进化出明确水生适应性的基干主龙类。该标本展现出一系列主龙类中未知的适应水生特征，包括多指（趾）骨、增强的桨状前肢以及荐骨与骨盆失去连接。化石中还保存了爬行动物已知最古老的胃、肝脏和肠道软组织，为主龙形下纲在海洋生态系统恢复时期的早期水生多样化提供了新见解。","scd":null,"kp":[]},{"i":42548,"as":"研究设计了一种用于海水电解的图灵型高熵氧化物纳米片，其尖石结构分子式为(Co0.19Mn0.21Cu0.20Ni0.20Zn0.20)3O4。将图灵型纳米结构与高熵设计相结合，通过成分灵活性和高熵效应提升了催化活性。该纳米片中高密度的孪晶界引发了严重的晶格畸变和压缩应变，从而显著提高了海水电解的催化效率。","scd":null,"kp":[]},{"i":42549,"as":"病毒诱导小肽1（VISP1）作为自噬受体，正向调控植物根部发育过程中的细胞分裂素反应。研究表明，VISP1通过调节拟南芥A型和B型响应调节因子（ARR）之间的反馈环路发挥作用。与野生型相比，VISP1过表达转基因株系表现出主根变短、侧根减少和根毛变长，同时伴随细胞分裂素反应的诱导。这揭示了VISP1在植物激素响应中的关键作用。","scd":null,"kp":[]},{"i":42550,"as":"詹姆斯·韦伯空间望远镜观测海王星及其卫星和星环的光谱数据显示，内层卫星拉里萨、加拉蒂亚、普罗透斯及星环缺乏水冰证据，但具有深层3微米OH吸收带。这些天体具有独特的2.72微米吸收带，指示存在富镁层状硅酸盐，这是广泛含水蚀变的标志。这些矿物可能形成于海卫一被剧烈捕获期间被潮汐撕裂的原始卫星内部。","scd":null,"kp":[]},{"i":42551,"as":"研究提出了一种基于遥感的新框架来分析热带湿地甲烷（CH4）排放的季节性变化。该框架整合了卫星甲烷反演与高分辨率湿地淹没测绘，能够区分开放水域和淹没植被。以非洲乍得湖为证据，研究揭示了该系统具有强烈的季节性振幅（每年4.75太克），并在降水与甲烷排放之间存在显著的季节性滞后效应。","scd":null,"kp":[]},{"i":42552,"as":"TONSL蛋白通过同源重组促进DNA损伤修复以维持基因组稳定，其突变会导致SPONASTRIME骨骼发育不良。1.9埃分辨率的晶体结构显示，野生型UBL结构域形成结构互换的二聚体并组装成环状八聚体。致病变异R934W消除了关键氢键并引入空间位阻，迫使蛋白质形成单体；G973R则破坏了构象受限的β转角中保守残基的稳定性，从而彻底破坏了TONSL的同源二聚化及DNA修复功能。","scd":null,"kp":[]},{"i":42553,"as":"人脑对呼吸阻断的感知由特定的皮层通路介导。颅内皮层记录显示，在短暂呼吸挑战期间，前岛叶的早期反应预测了对呼吸阻断的意识检测。随后，信号被传递至眶额叶皮层和运动前皮层，分别用于评估和代偿。这些皮层区域优先编码吸气努力或气流，揭示了岛叶至眶额叶皮层的通路在呼吸感知及应对过程中的关键机制。","scd":null,"kp":[]},{"i":42554,"as":"对2020年Facebook和Instagram上所有美国活跃成年人的数据分析显示，普通用户在信息流中看到不可信来源的内容相对较少，且曝光高度集中。一项为期数月的现场实验将用户对这些不可信来源的曝光率降低了约70%。然而，即使在高度曝光的群体中，减少曝光对多项预先注册的立场和态度结果均未产生任何可测量的影响。","scd":null,"kp":[]},{"i":42555,"as":"研究开发了一种名为PSDT的活体生物电子平台，用于放疗（RT）激活的肿瘤干预和免疫激活。PSDT由钯/铂修饰的希瓦氏菌核心（SDT）和活性氧（ROS）响应聚合物外壳（PEI-Se-Se-PEG）组成。该外壳使其在全身循环时保持惰性，仅在受照射的肿瘤部位释放活性。释放的SDT核心利用肿瘤微环境的厌氧特性特异性发挥作作用，结合生物电消融与放疗协同治疗肿瘤。","scd":null,"kp":[]},{"i":42556,"as":"","scd":null,"kp":[]},{"i":42557,"as":"研究开发了一种完全基于生物质的胶粘剂，主要成分来源于半寄生植物槲寄生的浆果（多糖）提取物。该提取物仅添加单宁酸和苹果酸，无需任何进一步的化学功能化修饰。通过热处理与快速固化结合，该生物胶水在包括多种类型的多种基材上均展现出卓越的粘合强度，提供了一种可持续且高性能的替代方案。","scd":null,"kp":[]},{"i":42558,"as":"为提高木质纤维素中己糖和戊糖的共利用效率，研究利用经工程改造可代谢木糖和阿拉伯酸的恶臭假单胞菌，在自动化适应性实验室进化（ALE）平台下进行演化。在简单单底物和复杂多底物选择压力下，细菌分化为代谢特化种和广谱种。进化结果显示，对木糖较弱的筛选压力常导致木糖代谢能力丧失，而碳受限的混合糖环境则能促进稳定维持。","scd":null,"kp":[]},{"i":42559,"as":"V2a中间神经元存在于后脑和脊髓中，源于不同的胚胎祖细胞。通过单核多组学测序分析经两种不同路径分化的人干细胞V2a神经元发现，这两个谱系具有截然不同的转录因子基序富集，以及在调控轴突生长和钙处理方面的差异表达基因。直接诱导V2a转录因子（绕过发育模式）产生的群体与两种自然谱系均不同，证实了分化轨迹对基因调控和功能的持久影响。","scd":null,"kp":[]},{"i":42560,"as":"研究测定了完整细胞内霍乱弧菌带鞘鞭毛马达的近原子结构。马达通过脂质化的HL环锚定在外膜上，不形成膜孔，使鞭毛组装能够驱动鞭毛鞘形成。保守的LP环作为滑动旋转衬套，允许在细菌包膜内高速旋转，并在鞭毛排出时收缩并密封内腔。此外，定子激活依赖于特定的蛋白质-蛋白质相互作用，而非与肽聚糖的结合。","scd":null,"kp":[]},{"i":42561,"as":"研究利用纳米孔长读长测序技术对7,284个全血样本进行测序，分析了近1800万个高质量CpG位点。超过20%的位点发生年龄相关的甲基化变化，主要表现为低甲基化。基于1,373个CpG位点构建的甲基化衰老时钟预测误差中位数为2.43年。通过将甲基化状态与亲本单倍型进行定相分析，发现了702个具有亲本特异性年龄关联的CpG位点。","scd":null,"kp":[]},{"i":42562,"as":"通过整合单细胞RNA测序、空间转录组学、蛋白质组学和代谢组学，对63个自然杀伤/T细胞淋巴瘤（NKTCL）样本进行分析，识别出四种元程序（MP）。MP1为免疫响应型，处于免疫耗竭微环境且高表达PD-L1，适宜免疫检查点阻断疗法；MP2为增殖型，表现出免疫荒漠特征且HDAC2和MKI67升高；MP3和MP4分别为炎症型和代谢型。揭示了肿瘤内异质性及潜在治疗策略。","scd":null,"kp":[]},{"i":42563,"as":"研究提出了一种依赖RNaseH1且无需扩增的microRNA（miRNA）检测方法，用于癌症精准诊断。该方法基于供体（掺入单链DNA探针的绿色荧光纳米笼）和受体（连接RNaseH1的橙色荧光蛋白）之间的荧光共振能量转移（FRET）。该技术克服了传统PCR、微阵列等方法多步扩增导致的不准确问题，在人类肺癌和胃癌诊断中实现了高准确度。","scd":null,"kp":[]},{"i":42564,"as":"利用综合排放-空气质量-健康建模框架评估全球航运能源向氢能转型的健康与经济影响。结果显示，采用氢能每年可避免约129,500例过早死亡，其中75%归因于臭氧浓度降低，25%归因于细颗粒物（PM2.5）减少。最大的臭氧相关健康收益在南亚，PM2.5相关收益在东亚。这些健康收益预计每年可节省巨额经济成本。","scd":null,"kp":[]},{"i":42565,"as":"提出了一种名为BayFlood的细粒度城市洪水检测方法，利用视觉-语言模型在大规模行车记录仪数据中识别被淹没的街道场景。该方法利用现代视觉-语言模型的能力，在缺乏大量标注数据的情况下也能有效识别洪水。使用144万余张图像进行的全面验证显示，该模型能跨多个城市和时间段提供强有效的洪水检测信号，且检测结果与已知的外部因素高度相关。","scd":null,"kp":[]},{"i":42566,"as":"提出一种以混合生物电化学组件（HBA）为核心的净化-发电-栽培工艺，实现污水中碳（C）、氮（N）、磷（P）的梯级利用和负碳排放处理。HBA结合非生物和生物阴极生物电化学系统，实现碳梯级代谢，使出水COD直接达到III类地表水标准。定制透水生物膜分离器依次形成厌氧-缺氧-好氧区，实现完全脱氮。富含磷的尾水随后被导入水培灌溉系统进行资源回收。","scd":null,"kp":[]},{"i":42567,"as":"通过元素化学计量学、碳和汞同位素分析以及全球森林综合研究发现，森林在水相和固相连续体中对汞和碳的循环表现出耦合与解耦机制。在水相连续体中，汞碳比保持紧密保守（0.5-0.9 × 10-6），表明溶解性有机碳对汞的比例运输；而在固相连续体中，从大气到土壤的汞碳比增加了近三个数量级（0.007-3.6 × 10-6），反映了凋落物分解过程中的汞富集。","scd":null,"kp":[]},{"i":42568,"as":"通过对中国301个站点的标准化实地调查，研究发现主要农作物（小麦、水稻和玉米）每年同化25.59兆克汞，其中约53%来自大气，47%来自土壤。预测华北平原、江南丘陵和东北平原为作物汞积累的热点区域。收获后，36.4%的汞作为残留物归还土壤，而43.4%通过谷物消费和秸秆饲料转移到食物链中。这表明粮食作物是生物地球化学汞循环的关键枢纽。","scd":null,"kp":[]},{"i":42569,"as":"研究利用冷冻电镜技术测定了广泛表达的人源α1β1FXYD1和神经元特异性α3β1FXYD1的Na+,K+-ATPase异构体复合物在活性状态下的结构。数据提供了ATP激活酶在四种不同构象状态下运输钠离子的深入见解，包括一种钠结合的磷酸化酶中间体[Na3]E2P。该构象揭示了在磷酸化后和钠离子释放前发生的关键结构变化。","scd":null,"kp":[]},{"i":42570,"as":"研究量化了国家公园预订系统中提前购买窗口和许可证竞争这两个特征对游客收入的影响。结果显示，这两种机制均显著偏向高收入用户。在竞争最激烈的市场中，预订者的家庭中位数收入高出3%至5%；将提前购买窗口延长至六个月，会使预订转移至收入高出5%地区的用户。这些事实凸显了预订系统在公平性方面存在的影响。","scd":null,"kp":[]},{"i":42571,"as":"研究展示了通过充当人工规范势的空间相位工程，可以在受限的光子系统中实现具有均匀非零包络的平顶态。通过连续调节累积相位，特征值光谱经历谱流变化，重塑特征态轮廓，形成具有均匀且非平凡包络的平顶态。这一成果在光子系统中得以实现，为量子发射器、光学天线和激光器提供了新的机遇。","scd":null,"kp":[]},{"i":42572,"as":"研究提出了一种高熵硫化物光催化剂（NiSnCaZnInS），集成了多功能位点，用于将生物质衍生的醇与氨气偶联以可持续地生产亚胺。以苯甲醇为例，该光催化剂在5小时内实现了1240 μmol gcat⁻¹的亚胺产率，选择性高达91.7%。其优异性能归因于催化剂中多活性位点的协同级联作用，有效克服了C–N偶联复杂串联过程的挑战。","scd":null,"kp":[]},{"i":42573,"as":"研究阐述并理论上验证了通过最小化周围电磁连续体的零点能来稳定材料中涨落相的机制。利用双折射晶体的各向异性电磁环境，研究成功稳定了涨落的量子霍尔条纹。结果表明，在实验可行的装置中，会出现方向依赖的卡西米尔能量，从而实现对涨落电子向列序的稳定控制。","scd":null,"kp":[]},{"i":42574,"as":"研究开发了一种由CMOS技术制造的毫瓦级微波神经网络（MNN），通过利用输入数据重新编程微波波导集合中频率模式之间的耦合，实现了跨数吉赫兹的频谱特征编码。这种扩频表达方式使得连续数据标记之间的关系更易被检测，从而通过轻量级数字处理实现更快的下游决策。此外，该系统能够支持每秒吉比特级别的概率比特生成。","scd":null,"kp":[]},{"i":42575,"as":"研究提出了一种原子级分散的稀土替代策略，构建了空间分隔的反应机制，实现了吸附质演化机制（AEM）和晶格氧机制（LOM）的双重激活。稀土中5s/5p电子的强屏蔽效应显著降低了外部环境对4f轨道的影响，从而增强了反应途径的可控性。这一双机制途径成功打破了析氧反应（OER）中活性与稳定性之间的权衡，实现了持久的海水电解。","scd":null,"kp":[]},{"i":42576,"as":"为解决水系锌金属电池高电流密度下界面场演变导致的性能问题，研究利用磺基丁二酸开发了强化的界面场化学策略。该策略精确调节了亥姆霍兹内平面的物理化学和电化学性质，实现了界面离子和电场的均匀分布。这种调控促进了快速的Zn²⁺去溶剂化和均匀的界面传输，有效抑制了副反应，实现了水系锌金属电池的深度快充。","scd":null,"kp":[]},{"i":42577,"as":"研究通过卫星雷达数据和冰盖建模，揭示了松岛冰川自2009年以来中心冰架的广泛重新搁浅（regrounding）历史。结果显示，重新搁浅对冰架底部几乎没有产生额外的拖曳力，未能如假设般减缓冰川流动或阻止其退缩。相反，这一过程促进了冰山崩解，进而影响了冰层的动态行为。","scd":null,"kp":[]},{"i":42578,"as":"","scd":null,"kp":[]},{"i":42579,"as":"研究在范德华异质双层结构中观察到由晶格重组驱动的快速层间激子漂移。激子的传输距离超过10微米，仅受限于异质结构的有限尺寸。研究发现，激子势能斜坡的存在导致了长距离的快速激子漂移，实现了初始激子群体的快速稀释。这一机制为基于电荷中性准粒子的节能光电信息传输提供了有效途径。","scd":null,"kp":[]},{"i":42580,"as":"研究揭示了多巴胺在植物-微生物组互作中的关键作用。实验表明，多巴胺是不同短柄草品系根分泌物中具有自然变异的最丰富外代谢物之一，与根际微生物群落组装显著相关。通过合成群落定植、代谢组学和16S rRNA测序分析，证实了根分泌物中的多巴胺水平显著影响根际微生物组的组装。","scd":null,"kp":[]},{"i":42581,"as":"研究发现了RNA结合蛋白CELF2通过基于聚集的机制促进微管相关蛋白tau外显子10的4R剪接，进而驱动tau蛋白病模型中的认知功能障碍。CELF2铰链结构域内的固有无序区（IDR）介导了多价组装，并与NOVA2和SFPQ协同调节tau外显子10的剪接。保守的负电荷残基D388对于CELF2的组装和改变4R:3R比例的活性至关重要。","scd":null,"kp":[]},{"i":42582,"as":"研究对940个大豆品系进行了深度重测序，结合公开数据共鉴定出602,281个结构变异（SVs），并通过图基因组发现了58,760个存在/缺失变异（PAVs）。群体基因组分析表明，SVs是大豆驯化和改良的核心驱动力。通过全基因组关联分析（GWAS），研究明确了影响种子皮色、油分和蛋白质含量等农艺性状的关键功能性SVs。","scd":null,"kp":[]},{"i":42583,"as":"研究解析了铜绿假单胞菌响应调节蛋白PaBqsR的结构特征，包含(βα)5响应调节因子组装接收结构域和螺旋-转角-螺旋基序DNA结合结构域。研究发现PaBqsR与胞外Fe²⁺的刺激有关，能够直接结合编码细菌Fe²⁺转运系统FeoABC的feo操纵子启动子区域。体外和体内实验结果均证实，BqsR/CarR响应调节因子控制着铜绿假单胞菌的Fe²⁺获取过程。","scd":null,"kp":[]},{"i":42584,"as":"在范德华界面的插层技术实现了二维材料的原子或分子级工程。这种机制为二维材料的合成与功能化提供了全新途径，不仅改变了材料的原有属性，还扩展了其在各种物理和化学领域的应用潜力。","scd":null,"kp":[]},{"i":42585,"as":"研究探讨了具有特定功能的化学可编程超晶格的模块化合成。二维原子晶体（2DACs）的非范德华间隙允许特定原子或分子插层。这些插层剂在受限空间内自组装，形成具有明确结构的插层超晶格。这种结构将固体二维材料的固有性质与自组装层的可编程电子、光学和磁学功能相结合，实现了超越传统异质结构的量子与集体现象集成及器件功能。","scd":null,"kp":[]},{"i":42586,"as":"研究通过受控的氧退火处理，在含有挥发性元素的扭曲NaNbO3薄膜中实现了原子级相干且化学键合的界面。原子分辨率成像和光谱学显示，该处理克服了传统氧化物异质结构中无定形界面“死层”的阻碍，实现了界面的有序结构。该方法避免了高温引起的元素流失，为探索莫尔物理和新兴量子现象提供了极具前景的平台。","scd":null,"kp":[]},{"i":42587,"as":"研究展示了一种双模式电致变色器件，能够实现太阳能加热和亚环境温度被动式辐射制冷之间的可逆且非易失性的切换。通过协同利用太阳和外层空间作为热力学资源，该器件在美国特定气候区实现了73.7 MBtu的年节能和4063千克二氧化碳的减排。该器件能够实现真正的亚环境温度制冷，为建筑节能提供了高效方案。","scd":null,"kp":[]},{"i":42588,"as":"研究利用表面活性剂介导的多级界面聚合法，制备了具有结构异质性的三层聚酰胺纳滤薄膜。该结构克服了传统单界面聚合膜的限制，实现了对平均孔径、孔均匀性和表面电荷的严格控制。这种高通量复合膜能够精确区分溶剂中大小相似的分子，解决了分子水平精确分离的技术瓶颈，实现了可持续的分离过程。","scd":null,"kp":[]},{"i":42589,"as":"研究开发了一种基于金的化学工程双功能抗体仿生材料（AuriFAB），实现了针对多重耐药ESKAPE病原体的通用抗菌治疗。通过二硫代氨基甲酸酯连接，AuriFAB在严苛生物条件下具有出色的胶体稳定性和超过一年的长期储存稳定性。化学表位筛选赋予了其广谱的抗菌能力，为克服生物抗体不稳定和功能多样性受限的问题提供了新策略。","scd":null,"kp":[]},{"i":42590,"as":"研究利用简单的反射镜几何结构，通过调控光子环境（局部光学态密度，LDOS），在范德华铁电材料NbOI2中实现了对太赫兹（THz）声子辐射的显著且可逆的调控。这种方法成功调节了声子的Q因子、峰值频率、线宽和发射强度。该工作填补了利用光子环境工程调控声子辐射性质的研究空白。","scd":null,"kp":[]},{"i":42591,"as":"KOTO实验利用2021年采集的数据，首次搜寻了K_L→π^0π^0γγ衰变过程，并搜寻了K_L→π^0π^0X衰变。其中X粒子被假设为一种会立即衰变为两个光子的类轴子粒子，搜索的质量范围设定在160至220 MeV之间。","scd":null,"kp":[]},{"i":42592,"as":"量子电池在充电过程中与充电器相互作用会产生量子关联，从而减少可从电池中提取的功。研究证明，通过将量子电池系统与一个可进行连续监测的环境耦合，能够有效减轻这种由量子关联造成的负面影响，进而提升从量子电池中提取的功。","scd":null,"kp":[]},{"i":42593,"as":"研究重新审视了具有欧姆谱密度的Caldeira-Leggett量子布朗运动模型，并在任意大截止频率的新高温极限下，推导出退相干核的一个额外贡献项。这一新贡献揭示了一种通过惩罚高频量子涨落来实现量子系统经典化的新机制。","scd":null,"kp":[]},{"i":42594,"as":"在随机量子散射系统中，低能区的共振通常是孤立的，而在高能区共振会发生重叠，最终进入截面表现为随机函数的Ericson区间。研究推导了随机量子散射中Ericson相变的普适性规律，并通过实验进行了验证。","scd":null,"kp":[]},{"i":42595,"as":"针对多体量子非局域性难以构造量子贝尔不等式的问题，研究引入了“紧致连接器”的张量概念。通过重整化群方法，按照特定规则收缩这些张量，可以为包含大量独立部分的系统构建出紧致且可自检验的多体量子贝尔不等式。","scd":null,"kp":[]},{"i":42596,"as":"研究揭示了恒星秩（Stellar rank）物理上源自超选择定则，并为量子态的非高斯性提供了一种物理解释。该研究将量子非高斯性明确解释为系统内在的多模纠缠现象。","scd":null,"kp":[]},{"i":42597,"as":"研究提出了一种在量子气体中产生非互易和长程三体相互作用的新机制。该方案将准二维玻色-爱因斯坦凝聚体置于两面反射镜前，并使用双色激光束照射。泵浦场两次穿过凝聚体产生反馈效应，从而成功诱导出原子间的三体相互作用。","scd":null,"kp":[]},{"i":42598,"as":"由于维度降低、量子涨落增强和复杂的电声子相互作用，二维范德华材料常出现渗滤超导电性，这使得正常电子与库珀对共存。研究在二维超导体中观察到了第三阶非线性输运现象，为研究共存态下的奇异输运特性提供了平台。","scd":null,"kp":[]},{"i":42599,"as":"传统二维二阶拓扑绝缘体的零维边界态通常局域在尖锐的角落处。研究提出了一种操控拓扑边界态的方法，成功将局限在角落的拓扑态转化为可任意定位的扩展态，为拓扑态的动态控制提供了新途径。","scd":null,"kp":[]},{"i":42600,"as":"多极矩序（如八极矩序）是理解凝聚态物理中隐藏序的关键，但由于其无法与常规外部刺激发生直接耦合，实验识别极具挑战。研究提出利用双圆偏振拉曼旋光活性技术，实现对轴向多极矩序的直接实验检测与识别。","scd":null,"kp":[]},{"i":42601,"as":"激子-声子相互作用决定了六方氮化硼的光学响应，但其定量测定一直不完备。研究利用低温阴极荧光谱技术，揭示了在硼-10同位素富集的六方氮化硼中的弗洛里希型激子-声子耦合机制。","scd":null,"kp":[]},{"i":42602,"as":"研究提出了一种新型的光陷阱架构，利用该技术能够显著提升碲超掺杂硅光电探测器在短波红外波段的量子效率。这一突破为开发与CMOS工艺兼容的夜视技术提供了切实可行的方案。","scd":null,"kp":[]},{"i":42603,"as":"根据量子色动力学，高能强子内部存在胶子分裂与胶子重组的动态平衡（即饱和现象）。ALICE合作组通过非相干光核产生J/ψ矢量介子的衍射过程，直接观测到了J/ψ产率抑制的实验证据，为强子结构的饱和态研究提供了重要见解。","scd":null,"kp":[]},{"i":42604,"as":"理解由障碍粒子组成的无序系统中的扩散现象，对阐明生物组织到工程多孔材料的输运过程至关重要。现有研究多采用随机顺序吸附方法且仅通过单一参数来表征介质。研究深入探讨了二维超均匀介质中的扩散行为，超越了传统表征方法的局限。","scd":null,"kp":[]},{"i":42605,"as":"验证核心塌缩超新星的核合成模型，需要将放射性同位素的观测丰度预测与遗迹发射的伽马射线进行对比。研究深入探究了关键的57Ni(p,γ)58Cu共振反应，以准确理解超新星中44Ti同位素的核合成过程。","scd":null,"kp":[]},{"i":42606,"as":"识别纳米级点缺陷（NPDs）对于生产高质量的二维晶体至关重要，但现有技术在空间分辨率和检测通量之间存在难以调和的矛盾。研究提出一种高灵敏度的无损检测策略，利用氯化铒形成富铒纳米颗粒作为荧光标记，附着在NPDs位点，实现了对二维晶体表面大面积区域内点缺陷的快速、精准定位与映射。","scd":null,"kp":[]},{"i":42607,"as":"大环有机金属分子在加速锂硫电池反应动力学方面极具潜力，但精确调控金属位点微环境以增强其本征反应活性仍面临挑战。受单原子编辑技术启发，研究制备了一系列等瓣镍基大环有机金属分子。通过在原子尺度调节第一配位壳层，优化了镍位点的空间构型和d轨道状态，原位X射线吸收光谱证实其显著加速了氧化还原动力学。","scd":null,"kp":[]},{"i":42608,"as":"细胞焦亡作为一种强炎症性的程序性细胞死亡方式，在激活抗肿瘤免疫方面潜力巨大，但实现精准的肿瘤选择性诱导仍是转化的主要障碍。研究系统阐述了通过合理设计纳米材料，将超声波的能量在肿瘤部位特异性转化为局部生化信号，从而在时空上可控地触发细胞焦亡，强力刺激抗肿瘤免疫反应，应用于癌症免疫治疗。","scd":null,"kp":[]},{"i":42609,"as":"高价镍络合物是促进碳-杂原子还原消除反应的关键中间体。尽管光化学或电化学策略已被用于获取Ni(III)物种，但通过Ni(III)介导两个亲核试剂的氧化交叉偶联仍难以实现。研究提出了一种通用的氧自由基捕获策略，有效加速了Ni(II)的单电子氧化及随后的还原消除过程，成功实现了两个亲核试剂之间的碳-杂原子偶联。","scd":null,"kp":[]},{"i":42610,"as":"功能分子的吸附几何结构极大决定了其在催化和分子电子学等领域的界面行为，但缺乏合适的原位方法来理解吸附物的取向。研究结合针尖增强拉曼光谱、密度泛函理论和分子动力学模拟，阐明了铜表面均苯三甲酸的吸附几何争议。结果表明，在固/液界面和固/气界面下，约0.25 eV的微小能量差异决定了溶剂氢键作用对分子吸附取向的决定性影响。","scd":null,"kp":[]},{"i":42611,"as":"研究开发了一种光诱导铜催化技术，利用预组织的多重非共价相互作用，实现了饱和环胺的高对映选择性α-C(sp3)-H胺化反应。该技术使用具有高药用价值的芳香族和α,β-不饱和酰胺作为氮源，成功合成了手性α-氨基环胺生物活性骨架，解决了此前难以用常规氮源进行不对称C-H胺化的技术难题。","scd":null,"kp":[]},{"i":42612,"as":"针对水系锌电池低温下电解液易结冰和界面动力学迟缓的问题，研究开发了一种基于网络锚定氟化锆基金属有机多面体的弱溶剂化水凝胶电解质。其刚性疏水纳米笼通过配位锚定锌离子并空间排阻水分子，有效降低了去溶剂化能垒并破坏氢键网络抑制结冰。测试表明，锌对称电池在低温下稳定循环超过3700小时。","scd":null,"kp":[]},{"i":42613,"as":"评估了科学文献中光诱导过程实验描述的可重复性危机。研究从高分子科学、化学和物理学领域的高影响力期刊中随机抽取了150篇相关论文，依据复现光诱导反应所需的最低信息要求（如光源发射光谱、入射辐照度等暴露条件）进行评估。结果显示，许多文献因实验条件记录不严谨，掩盖了可靠结果对精密控制的依赖，面临可重复性挑战。","scd":null,"kp":[]},{"i":42614,"as":"针对钠离子电池硬碳负极中传统NaPF6基电解液存在的首效低、倍率性能差和低温传输受限等问题，研究在醚类局部高浓度电解液中引入“界面构象熵”概念。该概念作为机制描述符，用于揭示溶剂化鞘层的重构能力及其对钠离子去溶剂化和界面迁移的影响，从而有效解锁硬碳材料的高倍率钠存储性能。","scd":null,"kp":[]},{"i":42615,"as":"针对高并苯（7环以上）材料存在不稳定、溶解性差且难以合成的痛点，研究人员利用恶嗪和苯环单元，通过化学溶液法成功合成了含9环的新型高并苯类似物——五苯并四恶嗪。该化合物在常规有机溶剂中表现出高溶解性，并在环境条件下具备高稳定性及极深的最低未占分子轨道（LUMO）能级，是目前首次获得的稳定n型高并苯类似物。","scd":null,"kp":[]},{"i":42616,"as":"研究实现了一种在白光照射下、由咪唑催化且无需传统光引发剂的环保型热固性聚合物固化技术。该技术利用柠檬烯和香芹酮衍生的双环氧化物与戊二酸酐反应，成功制备出全生物基热固性塑料。核磁共振分析证实，白光固化路径改变了开环选择性，使其从热固化中的外型环氧开环转变为内型环氧优先激活，展现出独特的光响应机制。","scd":null,"kp":[]},{"i":42617,"as":"研究合成了一系列化学式相同且均结晶于单斜空间群P21/n的零维有机同分异构Cu(I)碘化物α-/β-/γ-/δ-/ε-(ITPP)2Cu2I4。该材料家族突破了现有设计的局限，首次在有机同分异构卤化亚铜多晶型物中，同时实现了全光谱可调谐发射、单相白光发射以及热和化学刺激的光学响应。","scd":null,"kp":[]},{"i":42618,"as":"针对末端脱氧核苷酸转移酶因催化效率低和聚集失活导致的DNA合成可扩展性受限问题，研究提出了一种结构导向的酶设计框架。该框架在持续性聚合酶中将溶解度与催化性能解耦，通过计算手段克服了酶的固有局限性，成功实现了用于数据存储的可扩展酶促DNA合成。","scd":null,"kp":[]},{"i":42619,"as":"研究开发了四种新型四齿Pt(II)配合物发射体，成功填补了窄带深红/近红外重金属磷光配合物的空白。这些高性能OLED材料表现出高达715纳米的发射峰，且器件的外量子效率（EQE）突破20%，展示了极佳的发光性能与应用潜力。","scd":null,"kp":[]},{"i":42620,"as":"研究设计合成了(R/S)-4LC手性有机小分子，其超分子组装体表现出瑞利散射行为和圆偏振散射（CPS）特性。这种特性可选择性地放大左旋或右旋圆偏振发光（CPL）信号，使体系的发光不对称因子实现了前所未有的200倍提升。该成果将CPL材料的优化重点从内在属性转向利用协同光物理过程提升系统性能。","scd":null,"kp":[]},{"i":42621,"as":"研究发现，接枝在五重孪晶金纳米棒表面的聚合物分子刷并非惰性的空间位阻屏障，而是控制缺陷选择性氧化刻蚀的活性界面调节剂。实验和模拟表明，聚合物刷能在金纳米棒表面富集刻蚀剂离子，降低富缺陷区域金原子移除的能垒。这种缺陷与配体的相互作用导致纳米棒纵向晶面产生表面波纹，其刻蚀行为与单晶颗粒截然不同。","scd":null,"kp":[]},{"i":42622,"as":"研究揭示了热电材料中化学不均匀性的空间连通性通过寄生传输途径影响热电性能的机制。在Mg3(Sb, Bi)2中，多尺度Bi相关的化学不均匀性会形成空间连通的渗流途径，导致塞贝克系数和热导率恶化。通过循环加压烧结技术破坏该渗滤网络，成功抑制了寄生传输并增强了声子散射，从而显著提升了材料的热电优值zT。","scd":null,"kp":[]},{"i":42623,"as":"为解决强金属-载体相互作用(SMSI)诱导的氧化物覆盖层难以预测最优结构的问题，研究引入反应中激发态CO2分子弛豫产生的CO2*发光作为“导航工具”。通过测量CO氧化过程中的CO2*发光强度，发现其与催化活性呈火山型曲线关系，从而成功确定并优化了金纳米颗粒表面的理想氧化物覆盖层结构，提升了CO催化氧化活性。","scd":null,"kp":[]},{"i":42624,"as":"通过邻位双硼官能团化对多重共振骨架进行增强，研究成功构建了四硼酸化的B,N嵌入型[9]螺烯分子B4ONA。结构与理论分析证实，邻位双硼构型增强了分子的螺旋刚性和激发态限制，成功解决了放大螺旋度通常会破坏光谱窄化所需局域电子结构的矛盾。该材料实现了兼具大不对称因子和高器件效率的窄带蓝光圆偏振发射。","scd":null,"kp":[]},{"i":42625,"as":"研究通过1,3,5-三甲基-2,4,6-三(4-氨基苯基)苯与1,3,5-三乙基-2,4,6-三(4-甲酰苯基)苯的[3+3]亚胺缩合反应，成功构建了由hcb网络组成的单晶共价有机框架。三维电子衍射技术解析出其AB堆积、双层和三层交叉互穿结构，实现了原子分辨率的三重骨架同分异构。其中脱溶剂后的GZU-4a表现出高达100.7 cm³/g的乙烷吸附量，具备高效的乙烷/乙烯分离能力。","scd":null,"kp":[]},{"i":42626,"as":"研究开发了一种动力学捕获策略，利用氟介导的“分子锁”在环境条件下永久保存压力诱导的高压非中心对称亚稳相。以二维钙钛矿(3-CF3py)2SnBr4为模型，该分子锁机制有效解决了压力驱动相变（特别是产生非线性光学活性的对称性破缺相变）的可逆性难题，成功在常压下保留了具有特殊功能的高压相材料。","scd":null,"kp":[]},{"i":42627,"as":"在悬浮偶极子装置RT-1中，实验观测到了由低频电场涨落引起的粒子向内输运现象。在伴随形成高强度空间结构的低频涨落期间，多点静电探针测量到了具有环向分量的电场涨落。电子密度与电场涨落的同步测量证实，这些低频涨落驱动了稳态的向内粒子通量，促使粒子向强磁场侧迁移。","scd":null,"kp":[]},{"i":42628,"as":"激光驱动的核反应在产生非麦克斯韦分布离子的非平衡等离子体条件下进行。研究开发了解析框架评估由靶后鞘层加速（TNSA）机制加速的非热离子核反应速率。利用自相似等离子体膨胀模型，推导出了有效反应能量窗口和聚变反应率的闭合表达式，结果证明有效能量与传统热模型的预测存在系统性差异，揭示了基于传统Gamow窗口解释的局限性。","scd":null,"kp":[]},{"i":42629,"as":"针对高性能纤维网络材料难以兼顾可制造性的问题，研究提出了一种融合数字拓扑、力学预测与物理实现的AI导向制造设计框架。该框架包含保持单纤维连续性的拓扑算法，可将数字结构转化为适配针织或3D打印的架构，结合自动有限元分析管线和物理启发图神经网络，能够准确捕捉并设计复杂纤维材料的拓扑与力学性能。","scd":null,"kp":[]},{"i":42630,"as":"基于1986至2023年的卫星观测及气候和表面能量数据，研究发现在气候变暖导致加拿大北方针叶林-苔原带木本植物扩张的背景下，约70%的生态区表现出净表面冷却趋势。植被变化与环境的相互作用降低了用于加热地表的能量（-0.003至-0.009W m-2 yr-1）。这种冷却效应在正向混交林和乔木湿地演变的景观中尤为显著，相比灌木扩张区，变暖速率降低了约0.015-0.028°C yr-1。","scd":null,"kp":[]},{"i":42631,"as":"低强度脉冲超声（LIPUS）被用于可逆性地破坏紧密连接蛋白，从而打开鼻黏膜屏障（NMB），提升绕过血脑屏障的鼻脑递送效率。研究设计了一种仿生纳米囊泡，共递送β受体阻滞剂和抗PD-L1药物。在原位胶质母细胞瘤小鼠模型中，该系统利用两小时的NMB开放窗口，通过阻断β受体减少T细胞耗竭，并增强T细胞的抗肿瘤活性。","scd":null,"kp":[]},{"i":42632,"as":"传统热辐射系统依赖全向热辐射，导致非目标方向的能量耗散。研究提出发射器与吸收器之间完美匹配的定向热发射，在平行板配置中，可将理论传热效率从29%提升至100%。实验表明，定向辐射传热在真空和非真空条件下分别实现了67.8%和28.7%的显著节能效果。","scd":null,"kp":[]},{"i":42633,"as":"本研究以拓扑手性[2]索烃为核心骨架，首次成功构建了基于供体-受体型中性自由基的圆偏振有机发光二极管（CP-OLED）。该拓扑手性骨架及其可控动态特性使系统展现出高达7.1×10^-3的发光不对称因子，并实现了可调谐的深红色发光以及可逆的圆偏振发光特性。","scd":null,"kp":[]},{"i":42634,"as":"针对电荷密度波材料1T-TiSe2中光激发破坏混合激子-声子有序态的悖论，研究揭示了一种仅在有序状态下出现的低频模式（约0.13 THz）。该模式代表锁相子，是激子和晶格自由度共享耦合势能景观时产生的集体激发。在临界光激发阈值下，该低频模式消失，标志着混合激子-声子有序态的崩溃。","scd":null,"kp":[]},{"i":42635,"as":"研究通过分析大量航天器测量数据，揭示了地球外辐射带低频 chorus 和 exohiss 波的时空特征。波幅分布呈现出随地磁活动和位置变化的宽对数正态核和不规则重尾。波探测时间间隔服从幂律分布，表明存在时间成簇现象。在地方正午前后，通常可探测到直至高纬度地区的波。","scd":null,"kp":[]},{"i":42636,"as":"为持续监测运动疲劳并应对汗液变化的干扰，研究开发了集成自适应排汗混合电子织物和人工智能分析的系统。其核心创新在于精确调节织物电极微孔和排汗区域的突破压力以实现准确的汗液管理。该设计能够在极低排汗率下实现高效富集，确保在运动-休息不同场景下持续稳定地获取生物化学与电生理信号。","scd":null,"kp":[]},{"i":42637,"as":"研究提出了一种基于动态空间共轭（TSC）调控席夫碱晶体光开关的策略。在光激发下，系统经历激发态分子内质子转移及随后的顺反式酮异构化，氮原子附近的电子与相邻π供体发生动态耦合。飞秒瞬态吸收光谱证实了这种瞬态氮基TSC过程，它有效调控了过渡态能垒和稳定性，实现了精确的光控荧光开关。","scd":null,"kp":[]},{"i":42638,"as":"研究通过结合含氮核心与面外空间位阻及氯化，设计了一系列小分子受体。该方法有效抑制了不利的核心聚集并促进了多维电子耦合。单晶分析和瞬态吸收光谱表明，该设计实现了低于0.20 eV的低非辐射能量损失，同时增强了分子排列的相干性和激子离域，加速了界面电荷转移，从而构建了高效的二元有机太阳能电池。","scd":null,"kp":[]},{"i":42639,"as":"通过纵向单细胞RNA测序分析感染小鼠后0至100天的脑免疫细胞，研究揭示了髓系细胞在神经PASC发病机制中的协调作用。浸润和常驻髓系细胞共同引发并维持了神经炎症。具体而言，小胶质细胞表现出具有炎症特征的特定亚群的持续扩展，这为理解新冠病毒感染引起的长期神经和精神症状提供了机制见解。","scd":null,"kp":[]},{"i":42640,"as":"为克服传统金属增材制造能耗高、成本大和耗时长的局限，研究提出了一种源自摩擦堆焊的固态增材制造技术。该方法通过旋转金属棒与基材之间的直接摩擦形成均匀层。其最大构建速率达到8,000 cm³/h，远高于传统熔融（800 cm³/h）和固态（2,400 cm³/h）方法，显著提升了米级金属层压板制造的成本效益和生产率。","scd":null,"kp":[]},{"i":42641,"as":"研究利用飞秒泵浦-探针光谱，观察了在0.37 K氦纳米液滴中核量子效应对光诱导双分子反应的催化作用。这种量子相宿主环境创造的低温条件显著加速了反应动力学。与气相环境相比，限制在液滴中的H2-H2二聚体形成H3+离子的时间从152±17飞秒大幅加速至59±10飞秒，实现了对成键超快动力学的直接时间分辨观测。","scd":null,"kp":[]},{"i":42642,"as":"研究开发了全自动微滴数字PCR工作流程，用于快速定量测量噬菌体的感染力。该方法通过靶向保守的16S rRNA区域量化噬菌体诱导的DNA释放作为裂解的分子特征。测试在3小时内即可完成，在涉及6个物种19个菌株的122种噬菌体-宿主组合中，与传统斑点试验的一致性达到95.9%，并能准确分辨出传统表型难以区分的微弱裂解活性。","scd":null,"kp":[]},{"i":42643,"as":"通过随机对照试验和鸟枪法宏基因组学测序，研究评估了食用富铁锌珍珠小米（FeZnPM）对儿童肠道微生物群的影响。结果显示，在长达9个月的试验中，与食用对照组小米相比，FeZnPM的日常摄入与儿童肠道微生物组的可检测变化没有显著相关性。这表明基于食物的生物强化方法不会引起常规铁补充剂可能导致的肠道微生物不良偏移。","scd":null,"kp":[]},{"i":42644,"as":"利用人类、猕猴、狨猴和小鼠小脑的单细胞多组学数据，研究发现灵长类小脑发育过程中转座子（TE）在不同细胞类型中的贡献受特定细胞状态的限制和偏好性选择。基于序列的深度学习模型系统评估了TE被招募进小脑基因调控网络的潜力，确定了12个具有复杂调控序列的TE亚家族，证明了TE在灵长类大脑细胞水平上驱动了基因调控创新。","scd":null,"kp":[]},{"i":42645,"as":"研究确定了小鼠基底外侧杏仁核（BLA）中分别特异性响应内脏痛和瘙痒的两个不同神经元群。这两群细胞分别投射到腹内侧下丘脑（VMH）和背内侧纹状体（DMS），形成独立调节内脏痛和瘙痒的神经回路。单细胞测序揭示，Fgf2和Notch2分别在内脏痛和瘙痒标记的神经元中高度选择性表达，敲低这些分子可特异性阻断相应的厌恶感觉行为。","scd":null,"kp":[]},{"i":42646,"as":"研究揭示了缺氧通过抑制含JmjC的组蛋白赖氨酸去甲基化酶KDM8促进胰腺癌转移的机制。在胰腺导管腺癌小鼠模型中，靶向敲除Kdm8会导致上皮形态丧失和广泛的转移性疾病。常氧下抑制Kdm8能够重现缺氧诱导的全局表观遗传改变、转录组重排以及有丝分裂纺锤体缺陷，破坏其去甲基化功能直接模拟了缺氧适应过程，推动了转移。","scd":null,"kp":[]},{"i":42647,"as":"N6-甲基腺苷（m6A）是真核mRNA内部最常见的化学修饰。研究发现，在发育的神经元中消除m6A甲基转移酶Metttl14会导致mRNA运输和轴突生长缺陷。m6A阅读蛋白YTHDF2在发育中的神经元内负责调控mRNA转运。该研究证实了METTL14介导的m6A修饰及其阅读蛋白在神经极性建立和mRNA向远端轴突转运过程中的关键调节作用。","scd":null,"kp":[]},{"i":42648,"as":"研究开发了一种以内质网相关降解（ERAD）为核心的触发诱导型基因开关，用于按需控制蛋白质分泌。通过在目的蛋白（POI）上暂时连接条件降解子基序，口服特定的临床许可小分子药物即可在雄性小鼠体内实现原代POI分泌的诱导、可调和可逆控制。该设计策略与腺相关病毒（AAV）介导的基因递送高度兼容，能够实现长期远程控制的转基因表达和快速调节的基因治疗。","scd":null,"kp":[]},{"i":42649,"as":"通过结合一阶携带模型、地质测绘、矿化与地球化学数据以及矿场级贸易记录，研究证实刚果民主共和国（DRC）的钴供应链中存在天然铀的提取、浓缩和出口。由于钴和铀在湿法冶金回路中的相似行为，超过95%的DRC钴以粗氢氧化钴形式出口，铀随之发生分配。研究估算，2000至2024年间有2000至5000吨天然铀通过此途径输出。","scd":null,"kp":[]},{"i":42650,"as":"为了对大型语言模型（LLM）推断出的基因功能假设进行严格的统计验证，研究开发了一种基于嵌入的统计框架。该框架将基因和功能描述转化为向量表示，从而能够定量测试基因间及基因与功能间的关系，并对LLM提出的新功能假设进行优先级排序。基准测试显示，OpenAI和Google的最先进嵌入模型在捕捉生物学上下文和实现零样本功能预测方面表现最佳。","scd":null,"kp":[]},{"i":42651,"as":"研究揭示了哺乳动物细胞中吞噬泡形成的分子机制。膜偶联的GABARAP蛋白通过两个结合位点结合并强烈激活脂质激酶PtdIns3K-C1。通过冷冻电子显微镜等技术证实，PtdIns3K-C1产生的PtdIns3P负责招募WIPI2并促进ATG8蛋白脂化。GABARAP与PtdIns3K-C1之间存在正反馈调节回路，共同驱动吞噬泡的核化与自噬体膜的快速合成。","scd":null,"kp":[]},{"i":42652,"as":"研究阐明了有丝分裂过程中染色体聚集的机制。微管相关酪氨酸羧肽酶（MATCAP）通过其内在无序区（IDR）在微管上发生液-液相分离（LLPS），形成微管蛋白去酪氨酸化机器。这些生物分子凝聚物能够选择性富集微管蛋白和驱动蛋白CENP-E，从而稳定着丝粒与微管的结合。表达缺乏LLPS能力突变体的细胞实时成像证实了相分离在确保染色体准确排列中的关键作用。","scd":null,"kp":[]},{"i":42653,"as":"研究开发出一种名为VIPbodies的工程化纳米抗体技术，用于在活细胞中精确控制蛋白质功能。该技术将自切割病毒蛋白酶嵌入纳米抗体中，将蛋白酶的抑制转化为药物依赖性的抗原识别。以抗mCherry纳米抗体为原型，构建了响应不同正交病毒蛋白酶-抑制剂对的变体，并扩展至多种纳米抗体骨架。各个VIPbody在同一细胞内独立运作，实现多靶点的多重调控，并成功整合到转录回路中。","scd":null,"kp":[]},{"i":42654,"as":"研究通过基于图像的筛选，确定了介导内核膜（INM）结合的两亲性螺旋（AHs）的特征。定位于内质网/高尔基体的AHs在进入细胞核后会与INM结合，而线粒体定位的AHs则主要存在于核质中。增加线粒体AH对脂质堆积缺陷的偏好性可使其在核靶向后结合INM。TMEM214中的INM结合AH在结合脂质堆积缺陷时发生折叠，且全长TMEM214定位于核孔，揭示了脂质缺陷在INM结合中的关键作用。","scd":null,"kp":[]},{"i":42655,"as":"研究利用多源卫星观测和概率深度学习模型，重建了1988至2021年间空间分辨率为0.25度的全球森林地上碳（AGC）记录。结果显示，全球森林在此期间封存了6.2 PgC碳，但湿润热带和北方森林自21世纪初起已逐渐转变为碳源。热带森林AGC的变率与大气CO2增长率呈日益显著的负相关（2011-2021年相关系数r=-0.63），表明热带森林对全球碳循环的调节作用不断增强。在巴西亚马逊地区，完整森林对AGC损失年度变化的贡献显著。","scd":null,"kp":[]},{"i":42656,"as":"研究通过整合卫星约束的湖泊温度估算值与气候模型模拟数据，量化了人类活动对全球湖泊表面变暖的影响。1950年至2020年间，观测到的湖泊表面温度升高了0.47°C。其中，温室气体排放是主导驱动因素，导致了0.95°C的升温；而气溶胶引发的冷却效应部分抵消了这一影响，为-0.28°C。在研究的44个区域中，有23个区域均检测到了显著的温室气体指纹，证实了人类活动对湖泊升温的直接归因。","scd":null,"kp":[]},{"i":42657,"as":"研究调查了全球人口最多的十个国家的公众对户外空气质量的反应。基于覆盖1372个地区的10618名受访者的配额样本，评估了细颗粒物（PM2.5）暴露水平与公众认知、态度及行为之间的关系。结果表明，空气污染暴露程度与空气质量知识呈负相关，而与公众的应对实践、态度和担忧程度呈正相关。","scd":null,"kp":[]},{"i":42658,"as":"研究探讨了温室效应变暖对厄尔尼诺与印度夏季风关系的影响。分析表明，20世纪80年代初观测到的两者关系减弱是由1983年和1997年的两次异常事件引起的。事实上，温室变暖在1902至2023年间持续加强了厄尔尼诺与印度季风之间的联系，且预计未来将继续增强。模型差异主要源于厄尔尼诺引起的沃克环流异常变化，观测约束显示温室变暖加剧了厄尔尼诺引发的印度季风干旱。","scd":null,"kp":[]},{"i":42659,"as":"研究发现Enhancer of Rudimentary Homolog (ERH)蛋白在哺乳动物发育和多能性分化中通过H3K9me3异染色质限制细胞谱系。在成纤维细胞中耗竭ERH可将体细胞的H3K9me3大范围结构域恢复至类似胚胎干细胞状态，从而在重编程过程中激活全能性和多能性基因。在胚胎植入前发育中，ERH负责抑制全能性和其他谱系发育程序，以确保内细胞团和滋养外胚层细胞谱系的正确分离。在人类胚胎干细胞分化期间，ERH同样发挥着关键的谱系限制作用。","scd":null,"kp":[]},{"i":42660,"as":"研究展示了一种简单的混合超导量子比特“谐波宇称量子比特”，实现了对库珀对隧穿宇称的控制。超导量子电路的非线性通常源于约瑟夫森能量-相位关系，多重隧穿会产生高阶傅里叶谐波。该器件突破了以往需要复杂多结或全混合架构的限制，成功实现了由偶数库珀对隧穿主导的区域。精确控制隧穿过程的宇称（奇数或偶数），为超导技术在更广泛领域的应用开辟了新途径。","scd":null,"kp":[]},{"i":42661,"as":"尽管企业的净零排放承诺日益普及，但证据表明这些承诺缺乏科学基础以确保可信度，未能产生实质性的现实影响。本文提出了一个科学框架，旨在解决企业净零承诺中缺乏完整性和科学依据的问题，帮助企业将承诺转化为可信且有效的气候行动。","scd":null,"kp":[]},{"i":42662,"as":"研究开发了一系列基于分子马达的光响应单元，通过调节刚性和取代基实现了对液晶聚合物网络（LCPNs）机械性能和光响应行为的精确调控。通过与常规偶氮苯及第二代分子马达的对比，研究建立了分子设计与宏观致动效率及网络刚度之间的清晰构效关系。这种整合了分子马达的LCPNs还表现出本征荧光特性，无需添加额外荧光分子即可实现形状编码的图案可视化，成功将荧光与大尺寸光机械效应相集成。","scd":null,"kp":[]},{"i":42663,"as":"","scd":null,"kp":[]},{"i":42664,"as":"","scd":null,"kp":[]},{"i":42665,"as":"","scd":null,"kp":[]},{"i":42666,"as":"","scd":null,"kp":[]},{"i":42667,"as":"","scd":null,"kp":[]},{"i":42668,"as":"","scd":null,"kp":[]},{"i":42669,"as":"","scd":null,"kp":[]},{"i":42670,"as":"","scd":null,"kp":[]},{"i":42671,"as":"研究提出了一种界面相分离聚合策略，实现了高性能3D打印手性发光材料的快速稳健制备。通过逐层固化构建的立体结构在20秒内即可完成，并表现出360°全方位手性光发射。该材料的不对称因子达到0.6，有效解决了3D打印快速固化过程中手性分子排列和层间结构完整性难以保持的挑战，为先进光学应用中动态可调的圆偏振光发射提供了空间控制方案。","scd":null,"kp":[]},{"i":42672,"as":"","scd":null,"kp":[]},{"i":42673,"as":"研究提出了一种新的“累积五重键”键合模型，并成功合成与表征了三核物种[Co–U–Co]。传统多重键主要在双原子分子中发现，而三核体系中的累积多重键鲜有探索。通过高级量子化学计算证实，这种全金属铀酰类似物中的累积多重键包含一个独特的相互作用结构，使其表现出接近累积五重键的特性。这是累积三重以上化学键首次在实验中被分离和在理论上被预测。","scd":null,"kp":[]},{"i":42674,"as":"研究基于211538个植被样本和322个垂直植被带谱，采用分层和区域制图策略，绘制了比例尺为1:500000的青藏高原植被图。该地图在植物群落水平上准确描绘了青藏高原561种植被类型（包含52种特定分类）的分布模式。这一大尺度植被地图为阐明气候变化、人类干扰和自然演替影响下的植被分布格局提供了关键的生态学数据基础。","scd":null,"kp":[]},{"i":42675,"as":"研究探讨了超越自然生物转化的太阳能驱动人工混合系统。自然过程如光合作用和微生物代谢在资源利用上存在效率低、反应速率慢和产物受限等问题。结合物理、化学和生物科学的最新进展，自然与人工策略相融合的混合系统及人工光合作用技术，已成功应用于二氧化碳还原、固氮和可持续化学品的生产，从而拓宽了传统生物转化的应用边界。","scd":null,"kp":[]},{"i":42676,"as":"气候变化传播在不同地区表现出显著差异，这受当地独特的政治、经济、社会和环境条件影响，决定了气候信息的构建、接收和公众采取的行动。本文通过与全球各地学者的交流，探讨了不同地区气候变化传播的模式、面临的挑战及优先事项，以展现气候传播在区域层面的多样性。","scd":null,"kp":[]},{"i":42677,"as":"","scd":null,"kp":[]},{"i":42678,"as":"研究开发了一种仿生PD-1功能化免疫刺激性纳米药物，用于治疗肝细胞癌（HCC）。临床分析表明STING通路活性与患者生存率呈正相关。该纳米药物整合了光热治疗（PTT）、STING通路激活和免疫检查点阻断，通过配位作用合成。它能够有效克服HCC免疫抑制性“冷”肿瘤微环境，增强抗原呈递，激活细胞毒性T细胞，从而实现强效且持久的抗肿瘤免疫反应。","scd":null,"kp":[]},{"i":42679,"as":"研究开发了一种序列调控的肺靶向杂多肽接枝纳米粒子（NPs）。该纳米粒子的靶向能力依赖于通过其共聚物序列介导的原位红细胞“搭便车”效应。在聚L谷氨酸中引入缬氨酸和异亮氨酸等β-支链氨基酸残基，形成了具有末端疏水片段的梯度共聚物序列。这些带有疏水冠的杂多肽纳米粒子与红细胞膜表现出高亲和力，能够在体内高效积累于肺部组织，实现高达30%的靶向递送效率。","scd":null,"kp":[]},{"i":42680,"as":"研究采用氢键调节的质子转移策略，机械化学合成了一种带正电、各向同性无序的氢氧化钙前驱体（CHP_H+）。该前驱体作为加速生长的核，触发了氢氧化钙（CH）和硅酸钙水化物（C-S-H）的双重异相成核，原位形成CH@C-S-H复合材料。自由能计算表明，CH表面的羟基空位驱动水自发吸附生成≡Ca−OH2+位点，从而稳定硅酸盐团簇并促进复合材料生长。该方法解决了硅酸盐水泥各向异性成核限制宏观性能的问题。","scd":null,"kp":[]},{"i":42681,"as":"研究提出了一种无催化剂的光诱导氧删除策略，实现了氧丁环的高度化学和区域选择性重构。该反应在光照下利用碘仿进行脱氧开环，生成无环二碘化物中间体，随后发生分子内还原偶联或环化/官能化。该方法能够实现氧丁环的高效环收缩或骨架重塑，为复杂分子合成提供了新途径。","scd":null,"kp":[]},{"i":42682,"as":"全氟立方烷是一种非传统的电子受体，其最低未占分子轨道完全由σ*轨道组成。与传统的π*轨道离域不同，全氟立方烷通过其紧凑的立方笼状结构限制电子，形成类似点电荷的电子结构。研究结合二甲基芴与全氟立方烷构建了给体-受体分子，利用皮秒时间分辨瞬态吸收光谱揭示了极性溶剂中的电荷分离与复合过程，证实其电子转移行为突破了传统模型。","scd":null,"kp":[]},{"i":42683,"as":"研究针对水系锌碘电池中的多碘化物穿梭和活性位中毒问题，对杂原子掺杂剂进行了筛选，确定磷(P)为最佳候选元素。以植酸为磷源和刻蚀剂，开发了一种制备核壳结构单原子催化剂(M2-P-CSNC)的通用原位方法。该结构实现了多碘化物的稳定限域、快速离子传输和活性位保护，同时原位磷掺杂有效平衡了碘吸附与催化活性。","scd":null,"kp":[]},{"i":42684,"as":"为解决离子凝胶机械强度与自修复性之间的权衡难题，研究开发了一种两性离子侧链工程化的坚韧离子凝胶(ZESTI)。通过将亲水性两性离子共价接枝到疏水性聚氨酯骨架上，利用离子-偶极相互作用调节离子液体的分布。这种分子级设计在增强机械强度的同时，促进了动态键的重构，实现了离子凝胶在电子器件应用中的机械韧性与自发愈合能力。","scd":null,"kp":[]},{"i":42685,"as":"研究开发了一种流变学工程设计的直写3D打印策略，用于制造高负载量的磁介电吸波复合材料。通过引入石墨烯重构颗粒负载网络，协同提升了油墨的屈服行为和剪切变薄特性；结合羰基铁粉(CIP)构建了磁介电协同损耗体系。研究确定了CIP的临界含量约为84.06 wt%，获得了可调控的复合油墨，实现了器件级电磁兼容的几何控制。","scd":null,"kp":[]},{"i":42686,"as":"研究通过界面相互作用介导组装技术，构建了一种基于卟啉(PP)配体稳定磷酸铁锂(LFP)纳米颗粒的高性能纺织物电池正极。19 nm的LFP纳米颗粒与胺官能化卟啉共价结合实现多电子氧化还原活性，并包覆多层碳纳米管(MWCNT)。热退火使MWCNT转化为共价交联导电网络。该正极展现出约260 mAh/g的极高比容量和长期循环稳定性。","scd":null,"kp":[]},{"i":42687,"as":"","scd":null,"kp":[]},{"i":42688,"as":"研究提出利用金属介导的弱吸附策略，在水中实现硝基苯高选择性电催化加氢生成N-苯基羟胺。基于吸附能火山图确定金属银(Ag)为最佳高活性催化剂。原位电化学红外光谱证实，Ag对N-苯基羟胺的弱吸附有效阻止了其过度加氢。通过电化学合成纳米银催化剂(CV-Ag)，成功实现了该高附加值工业过程的高效电合成。","scd":null,"kp":[]},{"i":42689,"as":"","scd":null,"kp":[]},{"i":42690,"as":"研究提出一种磁场辅助策略调控化学置换反应动力学，在锌负极表面制备出均匀致密的铜保护层。磁流体动力学效应控制了置换过程中Cu²⁺的传输，促进铜均匀成核并抑制了“原电池”主导的置换途径。该策略实现了铜层的快速溶解-再沉积动力学，显著提升了锌金属负极的结构均匀性和电化学稳定性。","scd":null,"kp":[]},{"i":42691,"as":"研究开发了一种无需粘结剂的双功能导电纺织物电极(NiP@Ni/NiB-CC)，用于柔性储能器件。该电极通过化学镀和电沉积工艺在棉布上构建，兼具活性材料与集流体功能。该柔性电极表现出优异的导电性(1.07×10⁴ S m⁻¹)，在电池-超级电容器混合系统中实现了超高比容量，并具备长达40,000次的循环稳定性。","scd":null,"kp":[]},{"i":42692,"as":"","scd":null,"kp":[]},{"i":42693,"as":"本文强调接受而非排斥不确定性正是科学之所以强大的原因。文章探讨了怀疑主义与科学探索之间的辩证关系，指出在科学研究过程中拥抱未知能够激发出更为深刻的科学洞察与发现。","scd":null,"kp":[]},{"i":42694,"as":"研究报道了一种非富勒烯共轭聚合物2PB-T作为倒置钙钛矿太阳能电池的电子传输层(ETL)。该聚合物骨架引入共平面的苝二酰亚胺(PBI)单元，优化了电子传输性能、薄膜均匀性和界面结合力，解决了小分子ETL的不稳定性问题。小面积器件实现了27.8%的光电转换效率(PCE)，认证最大功率点跟踪效率为27.3%，并在大面积组件中表现出优异的热稳定性。","scd":null,"kp":[]},{"i":42695,"as":"研究利用钙同位素比率(δ44/40Ca)揭示了海洋酸化与早白垩世阿普特期-阿尔布期界线浮游有孔虫大规模灭绝事件的联系。通过对南大西洋有孔虫和碳酸盐岩的δ44/40Ca记录分析，发现其呈现出与海洋酸化事件相似的明显负向和正向偏移序列。这些地球化学证据表明，海洋酸化导致的生物钙化速率下降是引发该灭绝事件的关键因素。","scd":null,"kp":[]},{"i":42696,"as":"基于墨西哥低纬度化石新数据，研究揭示了大美洲生物互换(GABI)是一个长达千万年、分三阶段进行的长期过程。第一阶段始于约1000万年前，北方高纬度哺乳动物在墨西哥形成一个“中转围栏”并开始积累；第二阶段开始向南方扩散；这一发现将生物互换的启动时间大幅提前，修正了以往认为互换仅在约280万年前脉冲式发生的传统观点。","scd":null,"kp":[]},{"i":42697,"as":"研究报道了一种基于等离子体的钝化策略，通过原位化学反应在大面积钙钛矿薄膜上形成保形、均匀且强键合的异质结构，有效解决了薄膜软晶格导致的界面缺陷演化问题。该策略还减轻了激光划线互连区的局部损伤缺陷积累。小面积器件实现了27.2%的光电转换效率，100平方厘米大面积组件达到了24.0%（认证效率23.5%）。","scd":null,"kp":[]},{"i":42698,"as":"研究引入稳定的新戊氧基鏻盐，克服了传统Appel反应难以制备烷基氟化物的挑战，实现了使用氟化钾对醇进行催化氟化。反应生成新戊氧基氟化鏻中间体，该中间体优先与醇发生可逆交换，避免了二氟化鏻的生成。催化剂促进了氟化钾溶解和磷-氟键断裂。这一氢键相转移催化体系成功应用于多种醇的氟化，并具有对映选择性氟化的潜力。","scd":null,"kp":[]},{"i":42699,"as":"利用冷冻电子显微镜技术，研究解析了猪玻璃体原生胶原纤维的高分辨率结构（局部分辨率2.6至7埃）。67纳米的周期单元包含II型、V/XI型和IX型胶原蛋白三螺旋及视蛋白，化学计量比为8:4:4:4。结构显示，丰富的半乳糖-葡萄糖二糖修饰了保守序列中的羟赖氨酸残基，介导纤维堆积并维持结构稳定。","scd":null,"kp":[]},{"i":42700,"as":"研究从智利北部两名印加-殖民时期个体中恢复了首批美洲古代天花基因组（约公元1492-1631年）。这些基因组构成一个已灭绝谱系，于公元1296年左右分化，晚于早期欧洲毒株，早于现代天花变异。研究提供了欧洲殖民引入天花的分子证据，并发现其基因失活速率在16世纪末前保持恒定，随后经历了基因约束期与替换率反弹期。","scd":null,"kp":[]},{"i":42701,"as":"本文综述了海洋考古基因组学在渔业保护与恢复中的应用。结合古DNA和全基因组测序技术，研究人员能够评估过去鱼类种群动态、迁徙模式、历史贸易路线以及长期人类和环境压力的影响。文章汇编了2020至2025年间基于全基因组的考古鱼类遗骸研究，指出利用古DNA可建立更准确的生态基线，从而优化海洋生态保护策略。","scd":null,"kp":[]},{"i":42702,"as":"研究提出了一种系统性的第一性原理方法，实现了对磁性杂质中Kondo关联的精确零温度电子态描述。通过在一系列3d过渡金属中的计算，提取出的Kondo温度与精细的实验趋势高度吻合，准确性超越了标准模型。研究不仅提供了Kondo物理趋势的微观机制，还证明了从完整材料特异性出发进行精确量子多体计算的可行性。","scd":null,"kp":[]},{"i":42703,"as":"文章指出溶酶体代谢物的变化与器官衰老及溶酶体贮积症密切相关。通过对单个细胞器进行分析，揭示了特定细胞器层面存在的生物学年龄增长及病理状态标志物，为理解细胞衰老机制与相关代谢疾病提供了重要视角。","scd":null,"kp":[]},{"i":42704,"as":"“大美洲生物交流”历史事件为研究现代物种入侵的动态机制提供了重要参考。该交流揭示了哺乳动物跨越大陆迁移的过程，为理解当今生态系统中外来物种如何扩散、适应并重塑环境提供了科学依据。","scd":null,"kp":[]},{"i":42705,"as":"“政策证据准备度水平”（PERL）框架被提出用于基于证据制定政策。该框架的核心作用是协助政策制定者准确评估当前科学证据的成熟度及其存在的不确定性，从而提升政策决策的科学性和可靠性。","scd":null,"kp":[]},{"i":42706,"as":"硬膜外电神经调控技术能够有效逆转瘫痪患者体内由于神经系统错误信号引发的“假警报”——即自主神经功能异常。该技术为治疗瘫痪相关的自主神经并发症提供了直接的干预手段。","scd":null,"kp":[]},{"i":42707,"as":"大脑功能回路可以用于指导精准的大脑表面刺激技术。通过利用这些功能回路，研究人员能够更精确地定位靶向区域，从而提升无创或微创脑刺激技术的治疗精度与效果。","scd":null,"kp":[]},{"i":42708,"as":"英国新任首相上台后废除科学、创新与技术部，将其并入新成立的超级部委。科学部长同日辞职。这并非政治动荡对科学基础的侵蚀，而是英国科学政策机制的重组。该举措旨在通过调整政策架构，进一步强化科学对相关领域的贡献。","scd":null,"kp":[]},{"i":42709,"as":"人口普查中引入的隐私保护工具遭到禁止。批评人士指出，禁止使用该工具的真正目的在于压低移民数据人口统计量，进而为共和党在国会中增加席位。","scd":null,"kp":[]},{"i":42710,"as":"","scd":null,"kp":[]},{"i":42711,"as":"一项具有里程碑意义的古DNA研究表明，天花病毒是通过欧洲人的接触传入美洲大陆的。古代基因证据清晰揭示了该致命传染病在美洲爆发的历史起源与传播路径。","scd":null,"kp":[]},{"i":42712,"as":"人工智能领域的顶级初创企业在学术共享方面极度保守。数据显示，超过一半的AI独角兽公司从未发表过任何学术论文或预印本，其技术进展和研发成果完全处于封闭的商业保密状态。","scd":null,"kp":[]},{"i":42713,"as":"美国公布首批旨在推动人工智能研究应用的“创世纪任务”资助项目，共有278名获奖者入选。这些获胜者将面临为期9个月的激烈角逐，以证明其项目的实际价值从而获取后续的额外研究资金。","scd":null,"kp":[]},{"i":42714,"as":"批评人士指出，“黄金时代”报告错失了重要契机。专家担忧该报告中试图彻底颠覆当前僵化科研体系的尝试缺乏周密考量，反而可能对现有科学生态系统造成弊大于利的破坏性影响。","scd":null,"kp":[]},{"i":42715,"as":"人类X染色体中富含L1转座元件。其根本原因在于X染色体失活过程。L1元件优先插入晚期复制的失活X染色体中，这一机制直接解释了L1转座子在该特定染色体上大量积累的现象。","scd":null,"kp":[]},{"i":42716,"as":"通过对数百起碰撞事件进行深入分析，天体物理学家发现黑洞配对结合成双星系统的途径至少有三种。这一结论揭示了宇宙中孤立黑洞互相捕获并“结合”的多样化形成机制。","scd":null,"kp":[]},{"i":42717,"as":"一种强效的新型HIV预防药物本有潜力助力终结艾滋病 epidemic（流行），但其实际推广面临巨大障碍。目前该药物的供应链和产能远远无法满足全球巨大的预防与治疗需求。","scd":null,"kp":[]},{"i":42718,"as":"钙质海洋浮游生物具备指示过去和当前海洋酸化程度的能力。由于其外壳对水质酸碱度高度敏感，这些浮游生物的化石及现存样本可以作为监测和评估海洋酸化演变过程的直接生物学标志物。","scd":null,"kp":[]},{"i":42719,"as":"","scd":null,"kp":[]},{"i":42720,"as":"","scd":null,"kp":[]},{"i":42721,"as":"","scd":null,"kp":[]},{"i":42722,"as":"美国国立卫生研究院（NIH）再次终止了具有政治敏感性的科研拨款。随着健康差异相关项目的被取消，该机构正在测试一种新的法律途径，以顺应当局偏好并终止其不喜欢的科研项目。","scd":null,"kp":[]},{"i":42723,"as":"研究发现锂离子电池富镍复合正极存在一种由荷电状态（SOC）不匹配驱动的全新降解路径。在双峰NCM811模型中，反应动力学差异导致颗粒间SOC不匹配，产生电化学势梯度并引发自发的内部锂离子转移，这是导致电池长期退化的关键机制。","scd":null,"kp":[]},{"i":42724,"as":"人类X染色体的X染色体失活（XCI）过程吸引了大量L1逆转录转座子的插入。利用长读长测序分析表明，L1整合强烈倾向于失活X染色体（Xi）及S期晚期复制区域。这证实X染色体富含L1元件是由XCI机制驱动的。","scd":null,"kp":[]},{"i":42725,"as":"蝴蝶花花等镜像花朵的雌雄器官手性发育由超基因控制。研究发现，半合子超基因内的MIR156-R和YUCCA-R两个候选因果位点分别决定了雌雄器官在重力响应下的相反取向，从而促进高效的异花授粉。","scd":null,"kp":[]},{"i":42726,"as":"","scd":null,"kp":[]},{"i":42727,"as":"研究揭示了一种类逆转录酶抗病毒酶DRT4的作用机制。该酶通过整合DNA聚合酶、核酸外切酶和RNA内切酶活性进行抗噬菌体防御。噬菌体感染引起的dNTP水平升高会触发其DNA合成，随后激活特异性RNA内切酶活性以切割RNA。","scd":null,"kp":[]},{"i":42728,"as":"研究引入了“敏感度”这一无量纲描述符，用于量化稀释相对溶质扰动的响应，从而分析生物分子凝聚体的相行为。实验证明，氨基酸、核苷酸等细胞内小分子代谢物普遍能够动态调节由不同机制组装的凝聚体的相平衡。","scd":null,"kp":[]},{"i":42729,"as":"研究揭示了泛素化在烟粉虱（Bemisia tabaci）杀虫剂抗性及其适应性代价中的关键作用。鉴定了RING型E3泛素连接酶TRIM37，证实其能在体内和体外促进泛素化。该连接酶与其他泛素酶结合，形成E1-1/E2-3/TRIM37泛素化级联反应，通过标记转录因子CREB对其产生负调控作用，从而影响昆虫的抗药性及相关适应性。","scd":null,"kp":[]},{"i":42730,"as":"研究发现X染色体连锁的SYTL4基因错义变异与自闭症谱系障碍（ASD）相关。SYTL4作为哺乳动物大脑中RAB27A的效应因子，能够调节突触前功能。在四名无血缘关系的男性患者中鉴定出位于SYTL4 Rab结合域的复发半合子错义变异R126H，符合X连锁隐性ASD遗传模式。该变异会破坏RAB27A依赖性囊泡运输和突触传递。","scd":null,"kp":[]},{"i":42731,"as":"凝聚体调节蛋白PDS5B在卵母细胞中的表达水平会随年龄增长而下降，导致高龄产妇减数分裂失败和染色体非整倍性。PDS5B在卵母细胞减数分裂期间表达，并在中期定位于纺锤体极。除了传统的凝聚功能外，PDS5B还在卵母细胞减数分裂成熟过程中发挥纺锤体极形成的非典型作用，其丰度降低是导致生殖老化期卵母细胞质量下降的重要原因。","scd":null,"kp":[]},{"i":42732,"as":"研究提出了一种关于“相似性偏向”社会学习的群体动力学理论。构建了一个进化模型，探讨个体在包含不同比例的组内和组外成员的示范池中独立学习或模仿他人的策略。结果表明，当群体标签与本地知识呈负相关时，选择机制倾向于模仿具有信息优势的群体，这甚至可能产生一种反相似性偏向。","scd":null,"kp":[]},{"i":42733,"as":"研究证实Guk1酶是导致哺乳动物细胞内RNA积累肌苷的原因。在缺乏肌苷三磷酸酶（ITPA）的细胞中，ITP会发生积累并引发发育性癫痫性脑病35。通过敲除Itpa的小鼠细胞系进行实验，发现鸟苷酸激酶1（Guk1）是负责通过两步磷酸化反应将肌苷一磷酸（IMP）转化为ITP的关键酶，从而揭示了哺乳动物体内ITP生物合成的机制。","scd":null,"kp":[]},{"i":42734,"as":"研究揭示了细菌retron Ec78抗噬菌体防御系统的双重抑制机制。该系统利用双组分效应复合物PtuAB执行防御。PtuAB受到ATP/ADP和RT-msDNA抗毒素的双重抑制调节：ATP/ADP结合PtuAB的核苷酸结合域并诱导组装成无活性的四聚体复合物；而RT-msDNA能够稳定Ec78复合物的抑制构象，并刺激ATP周转，使PtuAB准备快速激活。","scd":null,"kp":[]},{"i":42735,"as":"通过鉴定关键糖基转移酶并执行涉及45种异源酶的60多次基因编辑，研究在酵母中成功重构了鬼臼毒素型木脂素的复杂生物合成途径。鬼臼毒素是合成抗癌药物依托泊苷和替尼泊苷的关键前体。该技术突破了传统方法严重依赖濒危植物桃儿七提取前体的限制，为在酵母中可持续供应这些基本抗癌药物提供了新方法。","scd":null,"kp":[]},{"i":42736,"as":"研究发现POLDIP2是一种血红素感应接头蛋白，能够促使CLPXP（线粒体酪蛋白水解蛋白酶复合物）对血红素生物合成酶5-氨基乙酰丙酸合酶（ALAS）进行负反馈降解。POLDIP2直接识别并募集结合血红素的ALAS至CLPXP。这一降解过程需要ALAS的羧基末端元件参与，且在红细胞生成过程中对调节血红素生成具有不可或缺的作用。","scd":null,"kp":[]},{"i":42737,"as":"研究构建了衰老过程中溶酶体代谢变化的多组织图谱。发现大脑、心脏、肌肉和白色脂肪组织中的衰老溶酶体会积累甘油磷酸二酯和胱氨酸，这些代谢物与青少年溶酶体贮积症直接相关。这些代谢物的水平随年龄呈线性增加，且早于机体整体衰退。热量限制这种延长寿命的干预措施能缓解心脏和肌肉中的这些变化，但无法改善大脑中的积累。","scd":null,"kp":[]},{"i":42738,"as":"研究确立了生物分子凝聚物通过液-液相分离（LLPS）进行浓度缓冲的动态原理。发现凝聚物充当频率选择性过滤器：受扰动的稀相表现为高通量滤波器，而密相则对低频和高频扰动均有衰减作用。研究建立并量化了LLPS参数与浓度缓冲动力学之间的关系，解释了生物系统如何在不同时间尺度的波动中维持稳健的生化功能。","scd":null,"kp":[]},{"i":42739,"as":"研究揭示了叶酸（FA）预防神经管缺陷（NTDs）依赖于ALDH1L1产生的视黄酸（RA）。通过pax3敲低的非洲爪蟾模型证实，FA通过代谢联系作用于RA信号传导。RA或其前体同样能够挽救这些缺陷。此外，研究鉴定出叶酸代谢酶甲酰四氢叶酸脱氢酶（ALDH1L1），证实FA也是通过此途径挽救酒精诱发的NTDs。","scd":null,"kp":[]},{"i":42740,"as":"本文综述了基于脑电图（EEG）的情绪识别技术，并发布了开源Python工具包EEGEmoLib。与现有单纯依赖数据驱动的编码库不同，该工具包明确将心理学和神经科学的先验知识融入到算法设计及计算流程中，填补了神经生理学理论与计算流水线设计之间的关键空白，为机器情感智能领域提供了结构化定量化参考。","scd":null,"kp":[]},{"i":42741,"as":"一款名为“Raygun”的AI工具能够利用类似于自然进化的步骤，对蛋白质亚基进行添加、删除或替换操作，从而实现缩小或放大蛋白质。此外，自旋量子比特重新回到量子计算竞赛行列，研究人员也在积极探索可用于预防长新冠的药物。","scd":null,"kp":[]},{"i":42742,"as":"统计学家兼社会正义活动家Mary Gray结合统计学方法与法律学位，积极投身于维护社会正义和打击侵犯人权行为的行动。早在约50年前，她便成功揭露并挑战了美国学术界退休福利中的性别歧视问题，并一直致力于相关的人权保护事业。","scd":null,"kp":[]},{"i":42743,"as":"受气候变化导致的炎热干燥条件影响，欧洲地区的火灾频发并打破历史记录。科学家指出，西班牙和法国等欧洲国家未来的火灾发生模式，预计将变得越来越像美国加利福尼亚州所面临的严峻火灾形势。","scd":null,"kp":[]},{"i":42744,"as":"随着全球对锂金属需求的激增，研究人员正致力于探索使锂矿开采更加可持续的方法，重点关注如何从地下储层中提取锂资源的技术，以大幅减少提取过程中的水资源消耗和环境破坏。","scd":null,"kp":[]},{"i":42745,"as":"在当前的学术就业市场中，研究人员面临着严重的工作不安全感。学术成就不再是保障职业发展的充分条件，作者Daniella Watson指出，这一现象既是个体面临的困境，也深刻反映了当前整体经济环境的严峻状态。","scd":null,"kp":[]},{"i":42746,"as":"《生物衰老时钟在中晚年时期的睡眠图表》一文发布作者更正声明。作者表示，在原发表的文章中遗漏了两项相关的既往研究（Li等人2022年发表的研究1，以及Li等人2025年发表的研究2），特此补充列出这两篇文献以作完善。","scd":null,"kp":[]},{"i":42747,"as":"研究开发了一种利用积累的体细胞突变追踪骨髓衍生细胞浸润的方法，揭示了人类衰老过程中小胶质细胞的发育起源。对20名高龄个体的分析表明，所有被检个体的大脑中均有骨髓衍生细胞流入的证据。这证实了在人类衰老过程中，骨髓衍生细胞持续贡献于大脑的小胶质细胞池。","scd":null,"kp":[]},{"i":42748,"as":"研究提出了一种顺序亚胺交换策略，用于制造高结晶度、无缺陷的共价有机框架（COF）膜以实现精确的分子分离。该策略利用具有不同能隙的芳香族和脂肪族胺分别进行结晶和缺陷修复。芳香胺作为框架构建单元实现高结晶度，而超支化脂肪胺则用于后续修补晶间缺陷，从而大幅提升膜的分子分离性能。","scd":null,"kp":[]},{"i":42749,"as":"共价有机框架因其出色的分子可设计性和结构可调性，在氧电催化领域展现出巨大潜力。本文综述了基于活性位点性质对COF电催化剂进行的分类，并深入探讨了其在燃料电池和金属-空气电池等能量转换与存储技术中的应用策略与机理。","scd":null,"kp":[]},{"i":42750,"as":"本文提出一种非常规的1,3-二醇立体化学合成方法。通过使用金鸡纳生物碱衍生的手性氢原子提取催化剂，能够从多种非选择性的立体异构体混合物中实现特定的氢原子选择性提取，从而以“解扰”的方式精确合成具有特定相对和绝对立体化学结构的1,3-二醇单元。","scd":null,"kp":[]},{"i":42751,"as":"本文开发了一种由手性路易斯酸（COBI）催化的烯丙基硅烷形式上的[3+2]环加成反应，用于对映选择性合成顺式-2,5-二取代四氢呋喃-3-酮。该方法产率高达88%，具有极佳的立体选择性（高达99% ee，>20:1 dr），且能在单次转化中同时控制四个立体中心。","scd":null,"kp":[]},{"i":42752,"as":"本文指出抗体偶联药物(ADCs)的偶联过程会侵蚀单克隆抗体原有的药理学作用，导致“抗体暴露缺陷”。分析表明，有效载荷类型、药物抗体比(DAR)、连接子疏水性及偶联架构共同驱动了该缺陷。与高DAR构建体相比，位点特异性的DAR为1的格式能够有效缓解这一暴露缺陷。","scd":null,"kp":[]},{"i":42753,"as":"本文提出一种零静态功耗的机械可编程电磁超材料。该材料结合了3D打印的形状记忆聚合物压扭耦合结构与三重对称的三臂超原子。压扭耦合结构能够在垂直压缩下实现每个晶胞的确定性和独立的面内旋转，从而实现广义相位裁剪，克服了传统设计可编程性受限和高静态功耗的局限。","scd":null,"kp":[]},{"i":42754,"as":"本文开发了一种本征可拉伸的压电纳米复合材料(IS-PNC)，用于人工超声感觉突触。该材料由P(VDF-TrFE)-PEG基质与硅烷功能化的钛酸钡纳米颗粒组成。填料与基体之间形成的强氢键界面促进了铁电相的形成，显著提升了材料的铁电相比例和压电性能。","scd":null,"kp":[]},{"i":42755,"as":"固体电解质LLZTO在制造高容量锂金属电池方面极具潜力，但易受锂枝晶影响。本文通过多步离子交换工艺引入300 MPa至1 GPa的面内残余压应力，并量化了合适厚度压缩表层的有效性。结果表明，施加压应力可以有效抑制LLZTO中的锂丝生长及枝晶断裂。","scd":null,"kp":[]},{"i":42756,"as":"精确预测涉及强子的弱过程需要将短程贡献与强子矩阵元进行一致性匹配。本文重点研究了包含两个π介子的带电流过程，具体针对π介子的β衰变（π±→π0e±νe）以及τ→ππντ过程，探讨了超越首阶对数近似的物理机制计算。","scd":null,"kp":[]},{"i":42757,"as":"本文利用波包连续离散化(WPCD)方法和不同手性阶下的Epelbaum-Krebs-Meißner(EKM)手性核力，重新审视了中子-氘核散射过程。研究直接求解了Faddeev-AGS方程并重新推导了排列算符，无需重写初始状态即可完成计算分析。","scd":null,"kp":[]},{"i":42758,"as":"本文利用超快非线性显微技术，揭示了单个等离子体纳米腔内激子-极化激元的崩溃与复苏动力学。单个等离子体纳米腔具有约10^-6 λ^3的极端模式限制体积，能够实现少激子强耦合和极化激元的强非线性，该研究成功实现了对极化激元瞬态演变的直接探测。","scd":null,"kp":[]},{"i":42759,"as":"Kardar-Parisi-Zhang(KPZ)标度通常在离散极化激元晶格中被观察到。本文研究了在具有天然噪声正则化的本征连续系统中是否仍存在该普适类规律。研究提出并数值分析了一种光学限制的连续极化激元凝聚体，探讨了其中的KPZ物理标度行为。","scd":null,"kp":[]},{"i":42760,"as":"本文研究了一类广义的Rokhsar-Kivelson(RK)哈密顿量，在RK点处，该哈密顿量经过逆向工程处理，使其精确的基态为任意边缘加权的二聚体覆盖叠加态。研究重点聚焦于在双周期边缘权重下三角晶格上的量子二聚体模型，展示了精确可解的拓扑相变过程。","scd":null,"kp":[]},{"i":42761,"as":"精确预测载流子迁移率对于下一代电子材料的设计至关重要。现有的密度泛函理论方法在处理电声子相互作用时存在近似局限。本文采用GW微扰理论进行第一性原理计算，实现了创纪录精度的载流子迁移率预测，突破了现有方法的准确性瓶颈。","scd":null,"kp":[]},{"i":42762,"as":"本文利用二氧化钒(VO2)热致单斜到四方相变的特性，来促进水裂解过程中异质界面处的电子转移。这种热驱动的结构相变提供了一种有效手段来调控界面电子态，通过切换界面处的电子转移状态，成功实现了对析氧反应(OER)的加速。","scd":null,"kp":[]},{"i":42763,"as":"本文利用超级计算机模拟揭示了湍流如何支持聚变等离子体中“金发姑娘”状态（准连续排气区域）的运行。研究详细分析了该排气机制下等离子体湍流的本质特性，为聚变反应堆的实际运行与操作提供了重要的理论依据和见解。","scd":null,"kp":[]},{"i":42764,"as":"液态弹珠是覆盖着颗粒层的液滴，因其能够防止与基底发生毛细粘附而具有高移动性。然而，其颗粒涂层会产生静摩擦。本文对这种静态滚动摩擦进行了测量和建模，发现其运动需要在壳层内产生剪切，且主要由颗粒壳层的密度决定。","scd":null,"kp":[]},{"i":42765,"as":"本文利用Belle和Belle II实验收集的近阈值电子-正电子对撞产生的12亿个Υ(4S)介子数据，寻找罕见衰变B+→K+τ+τ-。实验通过对产生的其中一个B介子的强子衰变进行完整重建，针对该衰变通道进行了详细的探索与搜索分析。","scd":null,"kp":[]},{"i":42766,"as":"银河系宇宙射线到达方向偏离各向同性的微小差异，是探测局部磁场环境的独特探针。本文利用LHAASO-KM2A阵列，报告了能量在10 TeV以上的宇宙射线中尺度各向异性的观测结果，分析识别出了四个具有能量依赖性偏移的各向异性区域。","scd":null,"kp":[]},{"i":42767,"as":"本文利用XENONnT液氙探测器的纯电离数据（累积曝光量为7.8吨·年），对亚keV量级的轴子-like粒子和暗光子暗物质进行了搜寻。基于这些高质量探测数据，研究对轻质量暗物质粒子的相互作用截面设定了世界领先的限制范围。","scd":null,"kp":[]},{"i":42768,"as":"本文提出并验证了一种在囚禁离子系统中为其运动模式设计热浴的实验方案。该方案能够独立调节温度和耗散率，从而实现可靠的量子态制备。这一成果为开展玻色子开放系统动力学的量子模拟提供了可控的实验平台。","scd":null,"kp":[]},{"i":42769,"as":"量子处理器在周期性驱动的多体系统中研究了福克空间预热化和时间晶体序。周期性驱动系统展现出非平衡现象，为量子应用提供了途径。研究指出，系统因吸收能量而产生的加热现象是稳定和利用这些高度纠缠物质态的基础挑战。该成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":42770,"as":"研究通过35 MeV/u下40Ca+40Ca碰撞中的关联函数，调查了氚核(t)与3He在发射动力学和时间学上的差异。重点探讨了多碎裂过程中3He的每核子动能异常高于t和α粒子的“3He谜题”。该分析为解决重离子碰撞领域的现有争议提供了新见解。成果发表于《物理评论C辑》。","scd":null,"kp":[]},{"i":42771,"as":"研究在壳模型框架下微观分析了偶偶106-120Sn同位素的形状共存系统行为。结果表明，跨过Z=50闭壳能隙的双粒子双空穴(2p-2h)质子激发是描述这一形状共存现象的必要条件。该成果揭示了同位素微观结构特征，发表于《物理评论C辑》。","scd":null,"kp":[]},{"i":42772,"as":"在ISOLDE设施上，研究人员对216,218Rn和220,222Ra的对称双α衰变进行了实验探索。实验通过产生能量为30 keV的放射性分子220,222RaF离子束（强度约为10^3至10^5离子/秒）开展研究，旨在深入探究对称双α衰变的物理机制。成果发表于《物理评论C辑》。","scd":null,"kp":[]},{"i":42773,"as":"开发了一种稳定的四元vdW半导体材料PdPS0.55Se0.45，用于制造宽频带光电探测器。该单一器件能够实现从日盲紫外波段(266 nm)到短波红外波段(1550 nm)的宽带感知，同时支持对遥感图像进行传感器内卷积处理。该技术有效解决了火后遥感精确评估所需的多频段感知与预处理难题。","scd":null,"kp":[]},{"i":42774,"as":"提出了一种基于频分电感-电容(LC)谐振器阵列的无线无源多模态可穿戴传感器。该传感器能够同时解耦并检测叠加的多重刺激，包括压力、气味和湿度。利用三维全波电磁仿真验证了系统性能。该器件具备超快响应和恢复的压力传感能力，突破了电子皮肤多刺激识别、外部电源依赖等限制。","scd":null,"kp":[]},{"i":42775,"as":"受肥皂泡启发，开发了一种能够构建动态呼吸肺模型的超薄可拉伸水凝胶薄膜。通过将丙烯酰胺引入凝胶中，克服了传统水凝胶膜因几何形状超薄而导致的应力集中和疲劳失效问题。这种超薄水凝胶薄膜可在水合环境中承受长时间循环载荷，精准模拟由跨肺压驱动的肺泡组织的面外变形。","scd":null,"kp":[]},{"i":42776,"as":"开发了一种“从簇合物到簇合物”的合成策略，成功构建了目前核数最高的钍簇合物(Th38)。该簇合物在高γ射线辐照下（最高达690 kGy）表现出显著的稳定性，并在测试中展现出前所未有的分散性和稳定性。该成果为放射性废料管理和核反应堆发展中的锕系元素化学行为提供了重要见解。","scd":null,"kp":[]},{"i":42777,"as":"针对锂硫电池中多硫化物的转化问题，通过硫配位构建了不对称的钴同核双原子催化剂(CoDAC-S1N5)。理论计算表明，这种对称破缺结构诱导了温和的电子离域和电荷重新分布，打破了传统同核催化剂的内在限制，实现了多硫化物吸附-脱附的平衡，从而有效加速催化转化并抑制穿梭效应。","scd":null,"kp":[]},{"i":42778,"as":"提出了一种协同界面工程策略，引入基于膦的分子TFMP，与Me-4PACz和4PABCz构成共吸附自组装单层，构建了三元协同界面。解决了传统咔唑基单分子层在FTO基板上覆盖不全的问题。该策略有效减少了界面缺陷和结晶应力，成功实现了高效且稳定的倒置钙钛矿太阳能电池。","scd":null,"kp":[]},{"i":42779,"as":"报道了一种在SrO界面处实现的室温下可重构的类铁电二维电子气(2DEG)。通过显微镜和多种宏观测量证实了其稳健的铁电性。铁电极化实现了对界面输运的非易失性控制，并在室温下成功构建了任意几何形状的可重构导电通道。该成果为非易失性和可重构电子器件提供了新路径。","scd":null,"kp":[]},{"i":42780,"as":"通过采用基于离子型共轭聚电解质的电子阻挡层(EBL)，成功克服了光倍增型有机光电探测器(PM OPD)中高增益伴随高暗电流的难题。该EBL具有由芴和三苯胺交替构成的主链。器件在高达-10V的反向偏压下保持稳定的暗电流，同时外量子效率(EQE)超过2000%。","scd":null,"kp":[]},{"i":42781,"as":"针对钠离子电池NASICON型磷酸铁钠(NFPP)正极材料因合成过程中生成电化学惰性磷铁钠矿(m-NFP)而损害性能的问题，提出了一种Na-Fe-P化学计量比驱动的异质结构设计。该设计通过构建富含P2O7的缓冲相，有效提升了正极材料的稳定性，改善了电池电化学性能。","scd":null,"kp":[]},{"i":42782,"as":"报道了一种由硼酸盐促进的铜催化铃木-宫浦交叉偶联方法，成功实现吡啶基硼试剂与非活化烷基溴的C(sp2)-C(sp3)偶联。该方法有效克服了氮杂环引起的催化剂中毒以及硼试剂不稳定的难题，提供了一种高效获取广泛应用于医药和材料科学的烷基吡啶支架的途径。","scd":null,"kp":[]},{"i":42783,"as":"受石斑鱼和海鳗协同捕食行为启发，提出了一种“识别-捕获”仿生离子管理策略。设计了带有有序纳米通道的共价有机框架(COF)作为“海鳗”识别并引导TFSI-阴离子，同时以具有密集胺基的超支化聚酰胺胺(PAMAM)作为“石斑鱼”锁定阴离子。该策略有效解决了固体聚合物电解质中离子传输差及界面不稳定的问题。","scd":null,"kp":[]},{"i":42784,"as":"报道了一种使用双功能分子4-巯基苯硼酸(MPBA)修饰CuO以增强二氧化碳(CO2)电还原为C2+产物的策略。MPBA修饰使得催化剂在表面同时优化了*CO吸附和*H供应，突破了传统修饰分子无法兼顾两者的限制，大幅提升了多碳(C2+)产物生成的电催化选择性和效率。","scd":null,"kp":[]},{"i":42785,"as":"提出了一种基于机制引导的组合编码策略，用于多重病原体变异体鉴别。通过将多个等温扩增反应与多通道链置换探针结合，建立了一个理论上的n维编码框架。该系统利用单突变响应探针，以最少的平行反应实现了单核苷酸分辨率的高准确度遗传变异组合识别。","scd":null,"kp":[]},{"i":42786,"as":"通过单晶X射线衍射分析，表征了八种源自吡啶N-氧化物的[O─I─O]+卤代键合络合物。在这些3中心-4电子卤键系统中，最简单形式的碘(I)作为双齿电子受体，对称结合两个单齿N-氧化物氧原子。其I+─O键长在2.172(17)至2.227(6)埃之间，代表了已知最短的卤键。","scd":null,"kp":[]},{"i":42787,"as":"报道了通过亚硅烷 equivalents 与 CpCo(CO)2 的反应，利用瞬态亚氨基(金属膦基)亚硅烷实现环戊二烯的芳香性C─C键断裂，将其转化为硅桥联同环戊二烯基化物。NICS和ACID分析证实了该物质中的同芳香性，量子化学计算支持该反应通过金属辅助的Büchner扩环途径进行。","scd":null,"kp":[]},{"i":42788,"as":"提出了一种超临界二氧化碳(SC CO2)调制策略，协同构建了斜方CaSnO3的表面非晶化和氧空位(OV)缺陷。在16 MPa的最佳SC CO2压力下处理的CaSnO3表现出优异的电催化性能。该策略有效提升了双电子水氧化反应(2e-WOR)的效率，为电化学生产过氧化氢(H2O2)提供了高性能催化剂。","scd":null,"kp":[]},{"i":42789,"as":"本文提出了一种通过[2+2]环加成反应重塑自组装手性纳米材料的策略。研究利用接枝大π共轭体系的氨基酸作为主要构建单元，正交引入缺电子的四氰基对醌二甲烷（TCNQ）和乙炔苯胺（EDA）。这些组分通过电荷转移相互作用和氢键形成三元共组装体。在聚集相中，TCNQ和EDA发生高效、自发的[2+2]环加成反应，实现了手性自组装纳米材料的原位重塑，为智能材料和纳米加工技术提供了新途径。","scd":null,"kp":[]},{"i":42790,"as":"本研究开发了一种新型的水平取向主体材料4CzTPS，用于制造外量子效率（EQE）超过40%的深蓝色窄带有机发光二极管（OLED）。该器件采用磷光敏化蓝色多共振热激活延迟荧光（MR-TADF）技术。针对发射体水平偶极比低导致的光耦合效率受限问题，4CzTPS通过将两个双咔唑单元对称连接到四苯基硅烷核心上形成线性几何结构，从而诱导水平取向，成功实现了高效率与高色纯度的同步提升。","scd":null,"kp":[]},{"i":42791,"as":"本摘要概述了利用低能光子（深红光到近红外光，NIR）驱动自由基化学的最新进展。高活性自由基中间体能够实现传统离子过程无法完成的成键反应。与短波长光驱动过程相比，近红外光介导的反应具有显著优势，包括对生物组织具有更强的穿透能力和减少不必要的副反应。文章重点关注了能够捕获低能光子的新型发色团和催化系统的开发及其在有机合成中的应用。","scd":null,"kp":[]},{"i":42792,"as":"为解决大面积钙钛矿太阳能电池界面缺陷钝化与电子提取不均匀的问题，研究团队引入富π电子的间隔阳分子碘化3-吲哚基乙基铵（Ind），在钙钛矿/C60结处进行不对称层状模板化。杂原子极化的吲哚框架在芳香平面内产生横向静电各向异性，促进了间隔分子的面对面缔合及层状结构的排列。该策略有效抑制了表面复合，消除了传输势垒，实现了可扩展的倒置钙钛矿光伏器件的均匀界面工程。","scd":null,"kp":[]},{"i":42793,"as":"本文提出了一种在铌酸锂晶体中刻写光谱响应像素的单步制备方法，应用于微型光谱系统。通过在双折射基板上利用超快激光诱导像素化的非晶相变，实现了局部频率控制。该技术克服了传统光谱编码单元在微型化过程中面临的制造性、稳定性和工作带宽恶化的问题，使其更加兼容现场部署、可穿戴和消费级平台，为计算增强光谱学提供了高稳定性的微型化光谱编码方案。","scd":null,"kp":[]},{"i":42794,"as":"本研究探讨了N-甲基亚氨基二乙酸（MIDA）硼酸酯中硼-杂原子键的动力学稳定性。配体的半易变性使得原本极易水解的分子的合成成为可能。研究发现，在酸的促进下，硼酰基取代基发生迁移，生成了硼与不同氧化态氮结合的分子。其中，动力学稳定作用导致叠氮硼酸酯优先于氨基硼酸酯生成，这与预期的低能量氮路径相矛盾，为水解不稳定键的稳定化提供了新机制。","scd":null,"kp":[]},{"i":42795,"as":"","scd":null,"kp":[]},{"i":42796,"as":"本文报道了一种绿色高效的苯酚合成级联催化策略，结合了原位电化学过氧化氢（H2O2）生成与分子氧存在下芳基硼酸的化学氧化。该反应在温和条件下进行，无需有毒溶剂，具有优异的官能团耐受性和广泛的底物适用性（20个实例），实现了高转化率和选择性。研究采用三维六氮杂三萘基共价有机框架作为电催化剂，为化学和制药工业中重要中间体苯酚的合成提供了新路径。","scd":null,"kp":[]},{"i":42797,"as":"为解决锂富含锰基（LRM）正极材料在4.8V高工作电压下循环稳定性差的问题，本研究提出了一种基于热力学参数的电解质“焓-熵调节”策略。通过弱化离子-溶剂相互作用增强阴离子参与（焓调节），同时放大无序性增加构型多样性（熵调节），将溶剂化鞘层从溶剂主导状态重构为阴离子参与的多样化构型。这种重构有效稳定了高能电池中的LRM正极材料，提升了其循环寿命。","scd":null,"kp":[]},{"i":42798,"as":"本文提出了一种精确的分子工程策略，通过合成后连接体交换，调控基于苯并双噻唑的共价有机框架（BBT-COFs）的激发态能量流。通过合理引入空间位阻（BBT-TAPB），促进了分子内运动和非辐射衰变，实现了优异的光热加热效果；相反，引入强供体-受体结构则优化了光催化路径。该策略成功解决了光热转换与光催化产H2O2之间的竞争关系，实现了太阳能水蒸发与H2O2生成的协同高效利用。","scd":null,"kp":[]},{"i":42799,"as":"本文研究了通过消除氢重组瓶颈实现无铂丙烷脱氢（PDH）的新方法。氧化镓-氧化铝通过Ga-O对激活C-H键实现丙烷脱氢，但受限于缓慢的氢重组为H2的速率。虽然铂能缓解此瓶颈，但存在成本高和烧结等缺点。研究表明，通过将Mg掺杂到氧化镓-氧化铝中，激活了晶格氧，成功消除了氢重组的动力学限制，从而在无贵金属铂的条件下实现了高效的丙烷脱氢反应。","scd":null,"kp":[]},{"i":42800,"as":"本研究利用DNA折纸的高特异性位点结合高磁化和高磁各向异性的磁性纳米立方体，在高纵横比DNA折纸束上组装，构建了磁性DNA折纸纳米旋转器（纳米致动器）。研究人员在单转子水平上追踪并控制了数百个纳米旋转器，在均匀和旋转磁场下实现了磁钳位和受控旋转。通过改变磁性纳米颗粒的数量和排布，实现了对旋转的精准控制，为纳米机器人和功能材料提供了强大的磁驱动机制。","scd":null,"kp":[]},{"i":42801,"as":"本研究受分子机器中定点调节穿梭机制的启发，在滑环（SR）聚氨酯网络中引入了机械门控的“减速带”。在该网络（PU-DP-TED-a）中，基于紫柱[5]芳烃的大环化合物（DP）作为滑动交联剂，而 strategically 定位的Diels-Alder加合物（TED）则充当机械响应的减速带。这种设计克服了传统SR网络中大环滑动被动且无调节能力的缺陷，实现了对能量耗散的时间和空间编程，从而赋予材料可编程的力学性能。","scd":null,"kp":[]},{"i":42802,"as":"本文基于大环酮前手性索烃，开发了一种立体选择性方法，用于合成机械平面手性（MPC）和机械几何异构体（MGI）索烃。针对这类机械互锁分子立体异构体难以通过催化对映选择性方法合成的挑战，研究通过有机催化不对称缩合反应，成功从同一个分子平台获取了这两种索烃立体异构体。该研究为复杂机械立体化学体系的便捷、高立体选择性合成提供了有效途径。","scd":null,"kp":[]},{"i":42803,"as":"本文设计并合成了一类基于硼簇的高效有机X射线闪烁体。该材料采用供体-受体架构，通过将咔唑供体共价整合到碘代苯基碳硼烷簇受体中构建。这些闪烁体表现出高达95.8%的绝对量子产率和76 nGy s⁻¹的超低X射线检测限，展现出与传统无机闪烁体相媲美的卓越闪烁性能，克服了传统有机闪烁体X射线吸收弱和激子利用率低的应用瓶颈。","scd":null,"kp":[]},{"i":42804,"as":"本文报道了一种双光子活性发光空穴受体（TQAC），用于苯和吡啶蒸气的客体响应传感。TQAC通过将缺电子的喹喔啉面板整合到富电子的吖啶基大环骨架中构建，形成了分子内供体-σ-受体框架，展现出显著的电荷转移发光特性。这种将精确分子识别与非线性光学功能相结合的超分子传感策略，实现了芳香族蒸气的选择性光学读出检测。","scd":null,"kp":[]},{"i":42805,"as":"本文报道了一种基于空间位阻介导的策略，通过合理设计金属有机功能化磷钒钼酸盐[PMo8V4O40(VO)2][(VO)(IM)4]，实现了炔烃羟基磷酰化可切换的Z/E选择性。针对立体发散性炔烃羟基磷酰化难以实现选择性调谐的挑战，该单原子Mo─V簇催化剂通过改变空间位阻，有效控制了(Z)-和(E)-链烯基膦氧化物异构体的生成，为合成化学提供了高选择性的新方法。","scd":null,"kp":[]},{"i":42806,"as":"本研究合成了具有不同官能团的网状金属有机框架（MOF），并负载了尺寸和载量相似的铂纳米颗粒，用于氨硼烷甲醇解反应。针对化学微环境对金属纳米颗粒电子结构影响的定量研究缺乏描述符的问题，研究利用X射线吸收近边结构（XANES）测定了Pt的d轨道占据情况，并将来自MOF的电子贡献量化为实验可测的描述符。该工作成功实现了微环境对金属催化剂电子结构调控效应的定量解析。","scd":null,"kp":[]},{"i":42807,"as":"本文报道了一种基于主客体策略的高效有机X射线闪烁体系统，成功实现了单一客体发射体在辐射发光（RL）中荧光与磷光的切换。通过简便有效的方法，系统的荧光和磷光分别表现出4.28 ns（450 nm发射）和1140.41 ms（520 nm发射）的衰减寿命。该技术能够有效调控辐射发光的寿命和发射波长，满足医学诊断、无损检测等多样化X射线成像应用的需求。","scd":null,"kp":[]},{"i":42808,"as":"本文提出了一种位置工程策略，通过调控一维卟啉共价有机框架（CPOF-13-M1-M2）中单原子活性位点的空间分布，实现光催化CO2还原选择性的可调谐。针对光催化CO2还原为甲烷（CH4）的八电子耦合还原过程挑战，通过选择性地将Cu原子定位在边缘或中心位置，改变了催化剂的电子结构和活性中心分布，从而有效调控了还原产物的选择性，为高效光催化CO2还原提供了新思路。","scd":null,"kp":[]},{"i":42809,"as":"本文通过在主体-客体掺杂材料中引入氨基-羧酸型强相互作用氢键，成功实现了在430 K以上高温下的全色（蓝至红）有机余辉发射。受氨基酸特殊结构启发，该体系将含氨基的客体分子掺杂到富含羧基的丁烷-1,2,3,4-四羧酸主体中。这种强相互作用有效限制了高温下激子的非辐射跃迁，解决了激发态激子在高温下易猝灭的难题，在高温防伪和信息存储领域展现出重要应用价值。","scd":null,"kp":[]},{"i":42810,"as":"水系锌金属电池在极端温度下性能受限。研究将三醋酸甘油酯（GT）作为多氢键受体共溶剂，构建含6 mol% GT的混合电解质。GT的氢键位点与水分子中的氢原子结合，破坏水分子间的氢键网络，大幅降低电解质冰点。此外，GT的引入优化了Zn²⁺的溶剂化结构，减少了活性水分子的数量，从而实现了锌金属电池的超宽温域运行。","scd":null,"kp":[]},{"i":42811,"as":"研究提出一种基于自旋调制策略的新型钌-碳键合金属有机框架，并将其与Cu₂O纳米颗粒构建异质结，用于光催化还原CO₂。在水蒸气参与下，优化的RuC-MOF/10%Cu₂O异质结在可见光照射下表现出优异的催化性能，CH₄生成速率高达663.6 µmol g⁻¹ h⁻¹，选择性达到96.7%，有效解决了光催化过程中的选择性挑战。","scd":null,"kp":[]},{"i":42812,"as":"研究报道了一种由双(二苯基膦)甲烷二氧化物配体连接的八面体Mn(II)配合物的显著磁发光行为。有别于传统基于自旋亚能级简单塞曼分裂的开壳层发光分子系统机制，该配合物展现出新型磁场效应。这一发现深化了对自旋与发光相互关联的基础理解，为未来功能性磁光器件的设计与开发提供了新路径。","scd":null,"kp":[]},{"i":42813,"as":"为解决传统析氯阳极贵金属利用率低和本征活性受限的问题，研究采用分子级精确策略，将原子级分散的铱双原子对锚定在MnO₂纳米 rods上，构建了Ir₂-MnO₂双原子催化剂。通过球差校正显微镜和X射线吸收光谱验证了Ir₂的双原子特征。该催化剂成功应用于高效的氯气电合成，显著提升了析氯反应的综合性能。","scd":null,"kp":[]},{"i":42814,"as":"成功实现了稳定态的茚并[1,2-a]芴衍生物的溶液合成，这是五种茚并芴区域异构体中唯一被预测为三重态双自由基的成员。通过同时引入大空间位阻基团和强吸电子取代基，该衍生物在常温空气中表现出较长的持久性（溶液半衰期约29小时，固态约30天）。单晶X射线衍射证实了其平面多环骨架，磁学特征证实了其自由基特性。","scd":null,"kp":[]},{"i":42815,"as":"针对弯曲共轭分子合成与修饰的难题，研究引入嵌入咔唑的环对苯撑（CPPs）作为多功能结构单元。通过Suzuki偶联和区域选择性溴化反应，制备出可功能化的宏观合成子。该策略实现了受控的多组分偶联，成功构建了三环和五环弯曲π体系。结构分析表明，三环体系呈现出定义明确的C形结构，可自适应包结富勒烯客体。","scd":null,"kp":[]},{"i":42816,"as":"研究报道了在锰单原子位点引入轴向氯“自旋环”以优化氧还原反应（ORR）催化性能的策略。该轴向氯配位能够对Mn(II)中心进行精确的自旋态编程，使其从中自旋态转变为低自旋态。这种靶向调节金属中心自旋态的方法，为提升过渡金属电催化氧还原反应效率提供了关键的设计思路与途径。","scd":null,"kp":[]},{"i":42817,"as":"研究发现中性硼酸盐缓冲液能够在无需酸、金属或光照的条件下，触发重氮化合物生成卡宾，从而实现快速蛋白质标记。这种硼-重氮介导的共价修饰在生理条件下数秒内即可完成，并优先靶向含羧酸的氨基酸残基。基于此化学机制，研究成功设计了二氢叶酸还原酶的亲和共价抑制剂，并在应激细胞中实现了对细胞聚集体的特异性捕获。","scd":null,"kp":[]},{"i":42818,"as":"研究通过多酶级联途径，在大肠杆菌中成功以易得的氟代酪氨酸为底物，合成了一系列非天然的氟代芳香族聚酮类化合物，如白藜芦醇、柚皮素查尔酮等。结合代谢调控、双蛋白融合（4CL::III型聚酮合成酶）和定向进化等组合优化策略，有效拓展了芳香族聚酮化合物核心结构中氟原子的引入途径，提升了多酚分子的药理潜力。","scd":null,"kp":[]},{"i":42819,"as":"针对倒置钙钛矿太阳能电池中自组装分子（SAM）界面聚集导致能量损耗和稳定性差的问题，研究提出一种原位界面重构策略。通过构建坚固的埋底空穴选择性异质结，改善了界面能级并促进了电荷提取，有效抑制了界面空洞和缺陷的形成。热激活聚合网络在异质结处致密覆盖SAM，减少了底层电极暴露并阻挡了钙钛矿的降解，从而提升了电池的效率和耐久性。","scd":null,"kp":[]},{"i":42820,"as":"可充电Na/Cl₂电池因钠资源丰富和高理论能量密度极具潜力，但高NaCl晶格能阻碍了其快速稳定的氧化还原动力学。尽管含胺有机催化剂可加速该过程，但持续极化导致严重的能量损耗。研究首次识别出在AlCl₃体系中，亲核胺基有机催化剂存在一种此前未被认知的催化剂“中毒”失活过程。该发现为合理设计长效耐用的胺类催化剂以推进Na/Cl₂电池实用化提供了理论依据。","scd":null,"kp":[]},{"i":42821,"as":"电催化氘代反应在合成药物骨架方面极具潜力，但金属位点与氮原子孤对电子间的强轨道作用常导致催化剂不可逆失活（中毒）。为此，研究提出一种Mn₃Co₇合金电催化剂，通过触发钴从高自旋向低自旋态翻转，促进电子占据反键轨道，从而削弱Co-N键合作用。这种翻转的自旋态使催化剂成功抵御了氮杂环化合物的毒化，实现了持久高效的电催化氘代反应。","scd":null,"kp":[]},{"i":42822,"as":"研究开发了一种无需光催化剂、条件温和的自由基氟烷基化新方法。该方法以廉价的碘离子作为电子供体，稳定的氟烷基砜作为电子受体，两者形成电子供体-受体（EDA）复合物。在可见光照射下，EDA复合物发生单电子转移（SET），高效生成氟烷基自由基，进而与多种底物发生直接氟烷基化反应，避免了外部金属光催化剂或有机染料的使用。","scd":null,"kp":[]},{"i":42823,"as":"受肌肉启发的软致动器常受限于化学均匀锚定环境，难以实现复杂形变。研究提出一种图案化纳米组件工程化的分层梯度取向策略，通过精确编程物理化学锚定环境，引导液晶空间梯度排列，成功制造出无缝集成的拮抗型液晶致动器。该致动器由于增强了取向有序度和动态可调的应变，克服了传统液晶致动器在多维可编程形变与运动上的技术瓶颈。","scd":null,"kp":[]},{"i":42824,"as":"研究探讨了四唑在聚合物科学中的“双重特性”，即其兼具芳香族的结构持久性与潜在的化学反应活性。这种特性源于由取代基极化电子结构控制的电子开关机制。四唑不仅具备极性和离子结合能力，其作为电子可编程基元在聚合物体系中的应用长期未被充分开发。研究总结了四唑分子在构建兼具稳定性与刺激响应性的先进大分子功能材料中的核心潜力。","scd":null,"kp":[]},{"i":42825,"as":"金属有机框架膜在气体分离中极具潜力，但固有的脆性阻碍了其实际应用。研究提出一种对称不匹配策略，通过两种具有相同金属节点但连接体和空间群不同的MOF进行电驱动共组装，成功将脆性晶体MOF转化为非晶态膜。这种非晶膜打破了长程周期性，但保留了局部的结构有序性，从而兼具类似聚合物的柔韧性和类似晶体的超微孔性，在气体分离中表现出优异性能。","scd":null,"kp":[]},{"i":42826,"as":"研究开发了首个用于食欲素受体亚型1（OX1R）和2（OX2R）的光可切换双配体小分子工具“Photorexant”。基于结构设计，通过新型片段化和偶氮苯融合策略，对已获FDA批准的双食欲素受体拮抗剂苏沃雷生进行改造生成偶氮苯衍生物。分子对接确保了其特征结合模式的保留。该配体实现了在体外和小鼠大脑中对食欲素信号传导的光学精准调控，为精神疾病的研究与治疗提供了新手段。","scd":null,"kp":[]},{"i":42827,"as":"提出了一种用于计算数值轴对称托卡马克平衡中导向中心（GC）频率的快速几何方法。该方法能经济高效地识别共振轨道，并直观解释平衡在轨道频率谱和共振条件中的作用。将其应用于ASDEX Upgrade（AUG）和Divertor Tokamak Test（DTT）装置的平衡分析，成功预测了扰动下共振岛的位置和传输垒的存在。该工作为开发离子传输的降阶模型奠定了基础。","scd":null,"kp":[]},{"i":42828,"as":"HL-3托卡马克项目致力于应对高性能等离子体与功率排气兼容性的挑战。通过将辅助加热升级至19.5兆瓦并应用实现95.5%破裂避免率的AI控制系统，HL-3在兆安级等离子体电流下实现了核心离子温度超10 keV、聚变三重积达0.69×10²⁰ m⁻³·keV·s的反应堆级热离子状态，并成功建立了具内/双输运垒的高归一化比压模式，验证了高性能运行和功率排气方案。","scd":null,"kp":[]},{"i":42829,"as":"研究揭示了肠道菌群通过胆汁酸途径调控纳米药物体内分布的机制。研究发现，甲硝唑可重塑肠道微生态，通过胆汁酸相关的重编程作用，使肝脏库普弗细胞转变为低摄取状态。单细胞RNA测序证实库普弗细胞从吞噬态向静息态的转变。这一内源性机制显著抑制了纳米药物的肝脏截留，增强了其在多种制剂和肿瘤模型中的肿瘤内富集，从而改善纳米药物的药代动力学与治疗反应。","scd":null,"kp":[]},{"i":42830,"as":"研究团队基于电荷分离缓冲自适应发光机制，开发了线性可编程的有机全光子突触。通过对客体分子结构的系统工程设计来调节电荷分离动力学，实现了对突触线性的精确控制。研发的器件表现出极优的线性参数（v值低至0.009）。该技术克服了传统有机光电突触中光化学和光异构化引起的非线性问题，为神经形态计算提供了新方案。","scd":null,"kp":[]},{"i":42831,"as":"针对水凝胶生物电子设备在湿态生理环境中易发生溶胀导致机械降解和导电网络失效的问题，研究人员开发了基于胶束自组装方法的抗溶胀水凝胶。该材料柔软、可拉伸，在长期植入中引发的异物反应显著低于传统溶胀水凝胶和硅胶。研究采用微凝胶策略，将其构建为支撑基质和双相导电网络，成为可3D打印植入式生物电子器件的基础构件。","scd":null,"kp":[]},{"i":42832,"as":"针对基于反常能斯特效应（ANE）的磁性系统在热电应用中受限于低热功率和杂散场干扰的问题，研究提出利用极性（依赖于轴的载流子极性）在kagome晶格金属中实现高零场横向热电响应。通过利用平带和范霍夫奇点驱动的电子态，在LuCo6Ge6材料中发现了极大的横向热电响应，其横向热功率达到18.4 μV K^-1。","scd":null,"kp":[]},{"i":42833,"as":"","scd":null,"kp":[]},{"i":42834,"as":"《自然》杂志员工在文中讨论了近期两项科学研究：一是针对亚马逊地区昆虫开展的大规模调查工作；二是视频中捕捉到的虎鲸将一条翻车鱼咬碎的异常捕食行为。研究人员目前尚未完全明确虎鲸这种异常行为的具体原因。","scd":null,"kp":[]},{"i":42835,"as":"科学家借助高速摄像机和水下麦克风技术，对气泡发声的物理学现象进行了专门研究。研究旨在探索并解答不同气泡在水下破裂时，为何会产生音量大小不一的物理学谜题。","scd":null,"kp":[]},{"i":42836,"as":"Andrew Robinson对近期出版的五本精选科学书籍进行了点评。这些书籍的内容涵盖了关于“无知的力量”的哲学探讨，以及对银河系深处的天文观测与科学洞察。","scd":null,"kp":[]},{"i":42837,"as":"最新的基因组证据揭示了天花病毒是如何传入美洲的。研究人员从智利的木乃伊体内提取并分析了病毒基因序列，结果确凿地证明，天花病毒是由欧洲人携带并引入美洲大陆的。","scd":null,"kp":[]},{"i":42838,"as":"一项模型研究预测，在现行学术发表激励机制下，科研人员对大型语言模型（LLM）的广泛使用将导致论文产出数量显著增加。然而，这种结合同时也会降低论文的整体精细度和质量，最终导致科研效率提升但成果质量下降的结果。","scd":null,"kp":[]},{"i":42839,"as":"为探究大型低剪切波速省（LLVPs）在地球下地幔底部长期保存的机制，研究人员进行了高压实验。结果表明，水元素的引入显著促进了下地幔主要矿物布里奇曼石的晶粒生长。LLVPs内部相对富水的条件促使其矿物粗化，从而产生高黏度，这解释了其作为地幔柱源头和地幔对流屏障能在地幔中长期存在并影响地球动力学的现象。","scd":null,"kp":[]},{"i":42840,"as":"Patricia O’Hara探讨了油酸的分子结构如何决定橄榄油的具体特性。分析表明，油酸的分子构成直接塑造了橄榄油的物理属性、烹饪表现及其带来的健康益处，将古代象征意义与现代化学原理相联系。","scd":null,"kp":[]},{"i":42841,"as":"Bruce Gibb探讨了植物与真菌之间的化学相互作用，以验证树木与真菌之间是否存在真正的“地下通讯网络”。分析表明，植物与真菌的相互作用是一个复杂且尚未被充分了解的化学世界，目前大众文化中关于该网络的讨论与实际科学证据之间存在脱节。","scd":null,"kp":[]},{"i":42842,"as":"","scd":null,"kp":[]},{"i":42843,"as":"研究指出，中国报废的电动汽车可作为电池和电机的“城市矿山”。模型显示，其蕴含巨大的资源再供应潜力，特别是锂、钴、钕和镝。然而，镍和锰的供应仍存在持续性缺口。这突显了制定废旧产品收集、闭环回收以及稀土元素回收政策的必要性。","scd":null,"kp":[]},{"i":42844,"as":"为解决传统电解质材料设计面临成分空间庞大、开发成本高的问题，研究提出了一种融合物理机制与人工智能的设计框架。该框架能够同时提升高维电解质设计的效率、可靠性和可解释性。它大幅减少了设计资源消耗，从统计数据中提取关键机理，为电动垂直起降飞机（eVTOL）等苛刻运行环境制定了更严谨的电解质设计原则。","scd":null,"kp":[]},{"i":42845,"as":"为提升MoOX基硅太阳能电池的商业化可行性，研究针对氢化非晶硅/MoOX界面处氧空位缺陷降低功函数及范德华力相互作用削弱电荷传输的问题，引入了超薄磷钼酸（PMA）夹层。PMA钝化了氧空位缺陷并优化了界面接触，最终使该硅太阳能电池的光电转换效率达到24.9%。","scd":null,"kp":[]},{"i":42846,"as":"未来聚变反应堆依赖锂-6来增殖氚，但过高的富集度会引发核扩散担忧，并带来巨大的经济和工程代价。研究主张，聚变堆的规模化发展应结合国际公认的富集度限制和安全保障，并采用避开最高风险锂-6水平的增殖剂设计方案。这有助于实现更严密的材料衡算、供应链监控，从而在全球部署中降低核扩散风险。","scd":null,"kp":[]},{"i":42847,"as":"肉类过敏症的发病率正在上升。科学界已知该过敏症状主要由蜱虫叮咬引起，但研究人员指出，目前对于这种疾病的发病机制及相关免疫反应仍有许多待解之谜需要进一步深入探索。","scd":null,"kp":[]},{"i":42848,"as":"","scd":null,"kp":[]},{"i":42849,"as":"","scd":null,"kp":[]},{"i":42850,"as":"","scd":null,"kp":[]},{"i":42851,"as":"","scd":null,"kp":[]},{"i":42852,"as":"","scd":null,"kp":[]},{"i":42853,"as":"","scd":null,"kp":[]},{"i":42854,"as":"","scd":null,"kp":[]},{"i":42855,"as":"","scd":null,"kp":[]},{"i":42856,"as":"肠道微生物群通过调节肝脏清除率，在决定纳米药物的体内归宿方面发挥着关键作用。这一调节机制直接影响了纳米药物向肿瘤部位的递送效率，凸显了微生物群在纳米医学和肿瘤靶向治疗中的重要作用。","scd":null,"kp":[]},{"i":42857,"as":"针对水系多硫化物液流电池中多硫化物转化动力学缓慢和中间产物积累的问题，研究提出了一种基于d电子互补的轨道调控逐步催化策略。构建的NiS/MnS异质结构利用Ni（3d8）的强供电子能力加速短链多硫化物还原，以及Mn（3d5）提供空间分布的电子态，实现了多硫化物的高效转化。","scd":null,"kp":[]},{"i":42858,"as":"针对儿童失神癫痫（CAE），研究开发了模拟人类多基因遗传特征的工程化小鼠模型（DiG stg+Ca1A）。该双突变小鼠表现出失神癫痫发作和社交新奇偏好受损。实验证实，激活小白蛋白（Parvalbumin）中间神经元能够同时挽救模型小鼠的癫痫发作和社交障碍，为开发同时治疗癫痫及其神经认知合并症的方法提供了靶点。","scd":null,"kp":[]},{"i":42859,"as":"为解决相干拉曼成像（CRI）在低丰度生物分子检测中灵敏度低的问题，研究开发了宽带电子共振相干反斯托克斯/斯托克斯拉曼散射（BER-CARS/CSRS）显微镜技术。该技术结合了宽带光谱覆盖与电子共振增强，实现了对整个指纹区的覆盖，能够对内源性生色团进行高灵敏度、无标记的化学成像。","scd":null,"kp":[]},{"i":42860,"as":"范可尼贫血的特征是DNA修复缺陷和p53慢性激活。研究发现，p53响应的RNA结合蛋白ZMAT3在FA缺陷细胞中高表达，起到促进细胞适应和存活的作用。通过对FA患者成纤维细胞和Fancg敲除小鼠模型进行转录组学和脂质组学分析，发现消耗ZMAT3会意外改变鞘脂代谢，导致神经酰胺积累和酸性神经酰胺酶（ASAH1）下调。","scd":null,"kp":[]},{"i":42861,"as":"抑制控制能力对行为至关重要，其失调与多种神经精神症状相关。研究利用小鼠执行听觉Go/No-Go任务，探究纹状体尾部（TS）这一基底神经节主要感觉枢纽如何调节感觉驱动行为。结果显示，非目标声音会独特地引起间接通路神经元的持续性活动，暂时沉默该活动会增加对非目标刺激的错误反应。在Neurexin1α基因缺陷小鼠中，TS间接通路功能存在缺陷。","scd":null,"kp":[]},{"i":42862,"as":"细胞毒性T淋巴细胞（CTLs）通过诱导癌细胞凋亡在抗肿瘤免疫中发挥关键作用。研究利用具有可调刚度和均匀孔隙率的3D生物打印 ECM 模拟物，探究了细胞外基质（ECM）硬度对CTL介导反应的影响。结果表明，在较硬的ECM中，CTL的迁移速度降低，抗原特异性细胞毒性受损。机制分析显示，较硬的ECM并非通过减少CTL与靶细胞的接触频率，而是通过破坏突触形成来削弱CTL的功效。","scd":null,"kp":[]},{"i":42863,"as":"细胞外囊泡通过转移细胞质 material 介导细胞间通讯。研究通过对300个表面动力学基因进行基因筛选，发现囊泡摄取与Wnt途径之间存在未知联系。不含WNT的囊泡主要被运输到溶酶体，而携带WNT5A的囊泡则滞留在早期内吞结构中。这种重 routing 依赖于WNT5A的已知辅助受体RYK的表达，揭示了决定细胞外囊泡命运的具体分子机制。","scd":null,"kp":[]},{"i":42864,"as":"中性粒细胞迁移涉及趋化因子和抑制信号的动态平衡。研究揭示了趋化因子HxA3利用瞬时受体电位香草酸亚型2（TRPV2）阳离子通道促进中性粒细胞的跨膜迁移。这一过程由TRPV2与大麻素2型受体（CB2R）的物理相互作用精细调控。在静息中性粒细胞中，位于细胞表面的CB2R介导了对迁移的抑制作用。","scd":null,"kp":[]},{"i":42865,"as":"约7.4万年前印尼多巴火山的“超级喷发”对全球气候和古人类生态的影响一直存在争议。研究展示了来自东非热带地区的亚年度分辨率代用数据，将多巴喷发时间限定在北半球冬季。数据表明，该喷发仅引发了持续不到两年的轻微降温和严重干旱。这一短暂的气候扰动叠加于与北半球冰期阶段同期的数十年降温和变干趋势之上，说明该事件对东非气候的影响有限。","scd":null,"kp":[]},{"i":42866,"as":"转录对细胞应激反应至关重要。研究发现，在多种细胞应激期间RNA聚合酶II（RNAPII）会发生降解。在渗透压应激下，激活的TNFα-p38通路促进了CUL1 E3连接酶复合体的类泛素化修饰，通过FBXO11与RPB1相互作用使RNAPII泛素化并降解。这导致全基因组范围内的RNAPII结合减少，但阻止了启动子GC含量较低的基因丢失RNAPII。这种重分布保护了参与细胞黏附、MAPK和GPCR通路的应激反应基因，对细胞存活至关重要。","scd":null,"kp":[]},{"i":42867,"as":"将脑刺激与大脑自然节律相匹配可以驱动神经可塑性。研究对年轻健康成年人的小脑采用了节律调节方案，将θ频率经颅交流电刺激与间歇性θ脉冲刺激相结合。这种配对增强了精细运动控制和手部灵巧度，其改善程度与小脑驱动的可塑性生理标志物密切相关。在慢性中风幸存者中应用相同方法，也产生了平行的行为和神经增益，证明了尽管存在损伤，节律与可塑性之间的耦合依然得以保留。","scd":null,"kp":[]},{"i":42868,"as":"基因组结构与表观遗传调节因子的相互作用决定了神经元的细胞命运。研究发现，凝集素复合体在秀丽隐杆线虫中促进部分神经元的GABA能命运决定，该过程由人类早幼粒细胞白血病锌指（PLZF）转录因子的同源物EOR-1协助。核小体重塑和脱乙酰酶复合体与另一种PLZF同源物TRA-4则起到拮抗作用，共同驱动神经元的替代性命运选择。","scd":null,"kp":[]},{"i":42869,"as":"时间边界是材料折射率的瞬时突变，它能在保持波矢不变的同时改变光频率。研究在空气与激光诱导等离子体的界面处，实验实现了太赫兹波的超快时间边界。该等离子体通过局域表面等离激元模式表现出洛伦兹共振响应。通过在100飞秒内将空气转化为圆柱形等离子体柱，实现了强烈的亚周期折射率调制。实验观察到了非常规的双向（同时红移和蓝移）频率转换的时间折射现象。","scd":null,"kp":[]},{"i":42870,"as":"高效分离一价和二价离子是海水淡化和离子资源回收的核心挑战。研究提出一种电化学限域策略，将EDTA空间组织成TFP-Tag膜一维传输通道内的排列阵列（孔径1.1纳米）。这种仿生梯度功能化的锥形纳米通道结构中，带负电的上部区域捕获并阻挡二价离子，而孔径较大且具有阴离子亲和力的下部区域促进一价离子传输。该膜在多离子混合溶液中表现出卓越的一价/二价离子分离性能。","scd":null,"kp":[]},{"i":42871,"as":"太阳风驱动的大气离子逃逸是控制火星大气长期流失的关键过程。基于MAVEN和天问一号任务的联合观测，提供了直接证据表明这些局地等离子体云是由开尔文-亥姆霍兹不稳定性（KHI）产生的非线性波包。首次通过两点测量确定了KH波的空间尺度。等离子体云内的离子通量比典型的稳态逃逸通道高出1到2个数量级，代表了火星大气的批量逃逸事件。","scd":null,"kp":[]},{"i":42872,"as":"结合多模态传感器的电子皮肤在机器人与医疗设备领域潜力巨大。研究提出一种自适应学习框架的多模态电子皮肤，能够利用最少的标记数据快速泛化到未见过的任务。该端到端框架利用谱变分自编码器将多频率生物信号去噪并压缩到统一的秒级潜在空间中，保留了频谱-时间结构，随后利用Transformer架构进行时间序列健康评估与动作识别。","scd":null,"kp":[]},{"i":42873,"as":"聚(A)结合蛋白（PABPs）通常被认知为通过结合mRNA的poly(A)尾巴发挥作用。研究揭示了拟南芥中PAB2和PAB8在开花时间控制中的未知功能。PAB2和PAB8与RNA结合蛋白45C（RBP45C）相互作用，决定其在细胞质中的滞留。这阻止了RBP45C进入细胞核发挥其促进关键开花抑制因子基因转录和剪接的功能，从而发挥温度感应开关的作用以控制植物开花。","scd":null,"kp":[]},{"i":42874,"as":"脊柱侧凸的保守治疗缺乏定量、实时监测矫正力的工具。研究引入了一种半球形纬度梯度（HS-LG）传感器，作为软体弯曲界面全新的传感范式。利用非零高斯曲率几何结构，该器件可作为时空机械滤波器，将法向压力转化为可测量的信号。这项技术为脊柱侧凸矫正的闭环监测和管理提供了创新的硬件基础。","scd":null,"kp":[]},{"i":42875,"as":"骨骼肌的组织修复高度依赖于肌肉干细胞在再生过程中精确的命运转变。研究鉴定了TRF2在肌肉干细胞生物学中的非经典作用。TRF2在肌肉损伤后受到动态调节，对于维持干细胞特性、支持修复性肌生成和自我更新必不可少。肌肉干细胞特异性破坏TRF2会加重小鼠肌肉营养不良病理，重现人类疾病特征。机制上，TRF2与富含DNA G-四联体形成序列的调控区域结合，发挥关键调控作用。","scd":null,"kp":[]},{"i":42876,"as":"染色质重塑复合物催化核小体组蛋白H2A与H2A.Z的交换，但其具体机制尚不明确。研究解析了SRCAP-CFDP1全酶的9个冷冻电镜结构，证明了CFDP1是组蛋白交换所需的瞬时激活因子。CFDP1通过直接接触ATP酶结构域识别完全结合的SRCAP-核小体复合物构象，引发广泛的DNA解旋、H2A-H2B二聚体排出和H2A.Z-H2B二聚体插入的构象转变，且该过程不依赖结合ATP的水解。","scd":null,"kp":[]},{"i":42877,"as":"电气化脱盐受电场驱动，能够克服高盐水废水高渗透压带来的限制，但跨离子交换膜的渗透和电渗透水流严重制约了其效率。基于不可逆热力学框架，研究通过流动电位测量确定了离子的水运移数，建立了量化电渗透的理论基础。研究证实，通过解耦渗透和电渗透机制，可以深入理解电气化脱盐系统中的水运移过程，为提升脱盐效率提供了明确的优化方向。","scd":null,"kp":[]},{"i":42878,"as":"针对视觉搜索中目标特征与干扰物混合的挑战，研究报道了一种在硬件层面集成语义和几何“双重注意力”机制的特征注意力视觉传感器。该传感器具有从可见光到近红外波段的可重构光谱响应度，实现光谱抑制比高达2×10^4的可调谐颜色注意力。此外，通过强度-响应度矩阵实现了可调谐的方向注意力。在自动驾驶应用中，该传感器显著提升了目标识别的效率。","scd":null,"kp":[]},{"i":42879,"as":"在薄膜生长中，通常认为高台阶会导致生长终止和薄膜不连续。然而研究展示了在C面蓝宝石上生长的单层二硫化钼能够跨越高达约10纳米的尖锐台阶。理论模拟表明，这种跨越台阶的生长源于其变形能耗与吸附能增益之间的竞争。值得注意的是，跨越台阶生长在转移后的目标基板上形成了一维波纹，导致了对称性破缺和应变工程，为新型纳米器件的制备提供了途径。","scd":null,"kp":[]},{"i":42880,"as":"非洲和中东的化石燃料开采碳排放报告存在延误且难以核实。研究利用TROPOMI卫星观测数据，提取一氧化氮（NOx）排放量，以此间接推断并绘制人为二氧化碳（CO2）排放量。结果表明，当前的全球碳排放清单低估了这些地区的CO2总排放量约30%。","scd":null,"kp":[]},{"i":42881,"as":"针对中枢神经系统（CNS）鞘内治疗缺乏时空控制的问题，研究开发了一种自适应磁性纳米机器人平台。该平台能在小鼠和非人灵长类动物体内进行多模式群体移动，其中涡流群体被证明是最佳导航策略。在机械臂磁场驱动下，机器人可在脊髓腔内实现厘米级导航，增强其在靶点的磁积累并延长体内滞留时间，从而显著提升治疗效果。","scd":null,"kp":[]},{"i":42882,"as":"为阐明异四聚体红藻氨酸受体（KARs，主要为GluK2/GluK5）的构象转变，研究利用冷冻电子显微镜（cryo-EM）解析了其apo状态及结合激动剂或拮抗剂状态的结构。apo结构显示出紧凑的配体结合域（LBD）排列；结合谷氨酸的结构则通过增加亚基间接触，稳定了受体的脱敏构象。","scd":null,"kp":[]},{"i":42883,"as":"神经技术正通过整合实时传感、计算和刺激来重塑脑机交互与生理控制，具备广泛的临床与非临床应用潜力。为实现该技术的转化，研究提出了跨越神经科学、材料学、工程和监管伦理等多学科的战略发展路线图，并明确指出了在技术发展过程中塑造其转化的五个核心权衡因素。","scd":null,"kp":[]},{"i":42884,"as":"研究荟萃分析了过去六十年关于游行和示威活动参与动机的实证文献。通过聚焦这两类常见的抗议形式并结合问卷调查数据，研究对比了参与者与非参与者的特征，准确识别出了决定参与抗议的稳定核心变量、非关键变量以及尚需深入研究的变量。","scd":null,"kp":[]},{"i":42885,"as":"针对脓毒症、急性呼吸窘迫综合征（ARDS）和COVID-19相关的细胞因子风暴综合征，研究开发了一种由分泌型磷脂酶A2（sPLA2）反应的细胞外囊泡（SPLEVs）疗法。SPLEVs能够结合II型肺泡上皮细胞并增加细胞膜流动性，在ARDS等疾病中展现出极高的治疗效力。","scd":null,"kp":[]},{"i":42886,"as":"针对动脉粥样硬化（AS）及伴发的肝脂肪变性，研究开发了一种智能纳米平台。该平台以硫化铁纳米片为核心，接枝牛骨髓抗菌肽27（BMAP-27），并包裹红细胞-巨噬细胞杂合仿生膜。该纳米平台能够靶向动脉粥样硬化斑块，结合低强度聚焦超声，协同调节AS与肝脂肪变性，实现自噬激活和系统性代谢重编程。","scd":null,"kp":[]},{"i":42887,"as":"准确定位月球水冰资源对支持长期探月至关重要。研究结合同步辐射X射线显微断层扫描实验与高级岩石物理建模及热模型，量化了含有冰的月壤风化层的地球物理特征变化。该研究确立了月球冰的地震特征，为利用地震技术勘探月球极地地下冰资源提供了理论依据。","scd":null,"kp":[]},{"i":42888,"as":"研究发现，抗原遭遇的昼夜时间点决定了CD8+ T细胞的命运与抗病毒免疫能力。在动物活跃期进行免疫接种可促进祖细胞样记忆CD8+ T细胞的生成并增强保护效力。其核心机制在于树突状细胞的内在生物钟调节共刺激配体CD70的表达，进而主导T细胞的分化方向。","scd":null,"kp":[]},{"i":42889,"as":"为探究人类种系突变率变异的遗传基础，研究基于父母-子代全基因组测序数据进行全基因组关联分析（GWAS）。结果发现种系突变率在同胞之间具有强相关性，受遗传因素影响。研究识别出14个与突变率显著相关的基因座，其中NHEJ1基因上的一个单核苷酸多态性（SNP）突变等位基因以性别特异性方式影响了种系突变率。","scd":null,"kp":[]},{"i":42890,"as":"为探究硫在俯冲带的循环行为，研究对比分析了不同俯冲带玄武质弧熔体包裹体中的34S/32S同位素比值。校正去气效应后，发现弧岩浆的δ34S值范围较窄（+3 ± 2‰），高于上地幔背景值（-1‰）。这证实了板片来源的硫发生了氧化，揭示了下伏地幔楔的硫含量与同位素组成特征。","scd":null,"kp":[]},{"i":42891,"as":"为解决传统抗生素药敏试验（AST）耗时过长的问题，研究开发了一种“硅基芯片实验室”（LOSC）系统。该系统集成了硅纳米线场效应晶体管（SiNWFET）传感器与高通量微流控技术，能在几分钟内将细菌浓缩至皮升级腔室，无需预培养即可通过SiNWFET灵敏追踪抗生素诱导的代谢pH值变化，实现20分钟内得出结果的快速AST。","scd":null,"kp":[]},{"i":42892,"as":"为探究高分化（WD）与去分化（DD）脂肪肉瘤的进化关系，研究进行了单核RNA测序。结果显示两类肿瘤区域共享未分化的间充质细胞，但仅WD区域含有表达脂肪细胞分化标志物和PPARG靶基因的细胞。PPARG在协调脂质代谢中起核心作用，其调控程序的缺失可能是导致肿瘤细胞分化不良与高增殖性的原因。","scd":null,"kp":[]},{"i":42893,"as":"研究揭示了氯胺酮麻醉复苏过程中的一种雌性特异性机制：由皮质酮介导的小胶质细胞-神经元相互作用。该相互作用通过上调雌性小胶质细胞中的Fkbp5 mRNA及其蛋白Fkcp51，引起微型兴奋性突触后电流（mEPSC）频率增加，进而诱导神经可塑性改变。这一现象在雄性中不存在，且在小胶质细胞耗竭后消失。","scd":null,"kp":[]},{"i":42894,"as":"为实现假肢的灵巧控制，研究提出了一种运动神经元放电驱动接口。该系统集成了高密度表面肌电无线记录、实时运动神经元尖峰序列分解，以及连续多自由度（DoF）运动解码，实现了假肢的同步和按比例肌电控制。在六名前臂截肢者中进行的功能性多自由度任务验证表明，该系统在真实环境中具有实用性。","scd":null,"kp":[]},{"i":42895,"as":"SARS-CoV-2的Orf9b蛋白通过结合Tom70来破坏Tom70-Hsp90的相互作用，从而抑制干扰素（IFN）的产生以实现免疫逃逸。研究通过冷冻电镜和19F NMR波谱分析发现，Orf9b通过双相机制抑制Tom70-Hsp90相互作用。这一发现解析了Orf9b介导的IFN拮抗作用的分子机制。","scd":null,"kp":[]},{"i":42896,"as":"为构建适用于高通量药物筛选的4R tau蛋白病模型，研究开发了由诱导多能干细胞分化而来的i3神经元系。携带FTD剪接突变（S305N）的神经元表达超过75%的4R tau，会产生内源性种子竞争性tau蛋白，发生过度磷酸化并在胞体树突错位，同时呈现五聚体甲酰基噻吩乙酸（pFTAA）阳性特征。","scd":null,"kp":[]},{"i":42897,"as":"针对治疗性血管生成难以精细调控的问题，研究开发了一种超分子多肽系统。该系统将模拟血管内皮生长因子（VEGF）的双亲分子与机械强度高的β折叠多肽结合，形成硬度可调（100至1000帕斯卡）且保持VEGFR2亲和力的可注射水凝胶。分子动力学与核磁共振表明，这种组装缓解了结构域间的空间位阻，在保持致密组装的同时维持了最佳的受体可及性。","scd":null,"kp":[]},{"i":42898,"as":"为实现蓝氢和合成气生产中的高效碳捕集，研究通过分子级混合聚合策略，制备了一种基于锆基金属有机多面体的刺激响应性聚合物水凝胶膜。Zr-MOP笼增强了水凝胶的氢键网络。该膜能够通过改变刺激条件，克服单一机制的物理限制，实现CO2和H2分离模式的可逆切换。","scd":null,"kp":[]},{"i":42899,"as":"研究发现SLC25A34是一种在氧化型骨骼肌中高度表达的、由禁食诱导的线粒体载体蛋白。实验表明，SLC25A34介导磷酸烯醇式丙酮酸（PEP）输入线粒体基质。敲除SLC25A34会损害营养缺乏条件下由谷氨酰胺支持的回补反应，导致禁食诱导的代谢受损，但不影响葡萄糖和丙酮酸的利用。","scd":null,"kp":[]},{"i":42900,"as":"自主剖面仪在拉布拉多和伊尔明格海观测发现，2014至2017年冬季强对流期间，1000米深处反复出现叶绿素a荧光峰值。颗粒生物光学性质表明，富含不稳定表层浮游植物颗粒有机碳（POC）被混合至深海，其特征与背景悬浮颗粒及沉降聚集物不同。模型显示，由混合驱动的深海（500至2000米）POC供应量与对流体积成正比，揭示了深海对流对POC垂直通量的关键作用。","scd":null,"kp":[]},{"i":42901,"as":"研究人员通过静电纺丝-碳化-热磷化策略，制备了由Ru2P纳米颗粒修饰的Ru/N和P掺杂碳纳米纤维（Ru2P@Ru/NPCNFs）。该材料是一种优异的双功能电催化剂，在肼氧化反应（HzOR）中表现出色，达到100 mA cm⁻²电流密度仅需-0.013 V的电位，性能显著优于Ru/N掺杂碳纳米纤维样品。该催化剂可应用于高效制氢及锌-空气-肼电池等先进储能领域。","scd":null,"kp":[]},{"i":42902,"as":"为解决无负极锂金属电池中不可控的锂枝晶生长和固体电解质界面（SEI）不稳定问题，研究提出一种界面工程策略。在铜箔表面构建由亲锂纳米片组成的三维薄膜（CAC@Cu）。其中，单原子Ag被锚定在CeO₂晶格的氧空位中，诱导了促进氧空位高度有序分布的独特原子重排。这种集流体表现出卓越的亲锂性，有效改善了电池性能。","scd":null,"kp":[]},{"i":42903,"as":"研究引入了一种等效于M1算子长波形式的有效算子，用于分析和计算⁴He(d,γ)⁶Li反应中M1辐射俘获过程的贡献。该算子能够对同标量M1跃迁等过程进行精确的解析和数值计算。这项研究为理解⁴He与氘核发生辐射俘获生成⁶Li的核反应机制提供了重要的理论与计算支持。","scd":null,"kp":[]},{"i":42904,"as":"通过外延界面工程技术，研究人员成功制备了单层二硫化钼顶栅场效应晶体管。该器件采用外延衍生的氧化铝作为界面层，在约1纳米的等效氧化层厚度下，实现了0.45 mS μm⁻¹的高跨导率。这一成果突破了二维材料晶体管的界面限制，大幅提升了器件的电学性能。","scd":null,"kp":[]},{"i":42905,"as":"Nazmul Haque展示了一项利用力敏团实现聚合物复合材料内部应力 concentrations 映射与量化的技术。该方法通过力敏团对机械力的响应，能够精确观测并量化材料内部的应力分布，为评估和设计先进聚合物复合材料的力学可靠性提供了有效手段。","scd":null,"kp":[]},{"i":42906,"as":"马约拉纳零模（MZMs）的非阿贝尔编织统计是实现容错拓扑量子计算的核心。研究在人工晶格中直接观察到了类马约拉纳零模（MLZMs）的编织过程。通过控制Kekulé相位，研究人员成功将边界束缚且空间分离的MLZMs沿样品边界进行绝热传输，实现了实空间编织过程的直接观测，填补了理论预测与实验实现之间的空白。","scd":null,"kp":[]},{"i":42907,"as":"硫化物固态电解质Li₆PS₅Cl（LPSC）在干燥室温下仍会因微量水分降解。结合第一性原理计算和深度分辨X射线光电子能谱分析，研究揭示了其五步降解机制：H₂O在富硫表面吸附，P-S键弱化并伴随S-O置换，后续引发结构相变。该机制解释了即使在露点-60至-70°C的工业干燥室中，LPSC表面离子传输性能也会迅速受损的原因。","scd":null,"kp":[]},{"i":42908,"as":"针对光子上转换（UC）效率低、响应慢的问题，研究提出一种基于机器学习指导的级联泵浦单光子上转换策略。该机制使镧系离子中间态成为“虚拟基态”进行光子堆积。NaYS₂:Ho³⁺概念验证显示，其上转换发射选择性增强了2-3个数量级，光谱响应扩展至约2100纳米，响应时间从30毫秒缩短至54微秒。该策略适用于Tm³⁺/Pr³⁺/Er³⁺等多种镧系离子。","scd":null,"kp":[]},{"i":42909,"as":"为从废水中提取低浓度铀，研究利用离子配位方法将共价有机框架（COF）纳米线水平排列在聚酰胺肟（PAO）纤维表面。PAO的酰胺肟基团与COF的光催化位点产生协同作用，实现可溶性铀的化学结合与光催化还原，将其转化为(UO₂)O₂·4H₂O沉淀。该材料在约10 ppm浓度下12小时内实现了1259 mg g⁻¹的超高铀吸附容量，提取时间缩短至原来的十分之一。","scd":null,"kp":[]},{"i":42910,"as":"针对微腔中傅里叶互易性导致无法同时产生多波长泵浦和大规模信号广播的瓶颈，研究构建了频率域具有等距异常点的宇称-时间对称耦合腔系统。该设计将频率梳产生与全光信号广播集成于一体，在200纳米的光谱范围内实现了超过100个可用的高通量通信通道。该芯片级技术突破了光学非线性的局限，对光通信和计算系统具有重要意义。","scd":null,"kp":[]},{"i":42911,"as":"针对扭曲范德华材料的巨大莫尔域结构难以预测的问题，研究提出一种分离层内与层间相互作用的分离式机器学习原子间势函数（MLIP）及数据集构建方法。该方法显著提升了模型精度，使能量和力的预测误差较传统模型降低了约十倍。研究还开发了基于莫尔畴分布的物理动机指标，证明了传统力与能量误差度量不适用于莫尔结构的评估。","scd":null,"kp":[]},{"i":42912,"as":"为实现信息的时空程序化加密，研究开发了一种无需催化剂的单分子系统（4BT-Py-PTC）。该分子通过硫代碳酸酯水解、烯烃断裂和醛光氧化的顺序光反应，实现了时间门控的分级多色荧光。在光照下，初始黄色发射体随时间（5分钟、20分钟、80分钟）分别转变为红、黄、蓝发光产物。该系统为构建动态安全平台提供了集成化分子机制。","scd":null,"kp":[]},{"i":42913,"as":"利用朱诺号航天飞船的高分辨率观测数据，研究揭示了木星弓激波处的等离子体波现象。由于远离太阳处太阳风的超阿尔芬特性增强，需要更高的能量耗散。研究证实，离子声波、电子回旋漂移不稳定性驱动的波、静电孤立波以及哨声波等等离子体波，在将太阳风的动能转化为热能的过程中发挥了关键作用。","scd":null,"kp":[]},{"i":42914,"as":"为解决透明陶瓷难以制备高曲率形状的难题，研究提出一种受力驱动烧结策略。该方法利用应力诱导蠕变，通过循环应力的积累与释放动态控制微观结构和曲率，并伴随动态曲率反转现象。成功制备了尺寸为0.5×2×22 cm³、曲率大于5.36 m⁻¹的MgAl₂O₄透明陶瓷，其透光率超过85%（接近理论极限），并保持了极佳的力学性能。","scd":null,"kp":[]},{"i":42915,"as":"研究开发了一种脱羧环氧化技术，可将广泛存在的羧酸转化为多用途的环氧乙烷衍生物。该方法利用可见光照射羧酸氧化还原活性酯与设计的烯丙基过氧化物反应，无需复杂步骤即可实现多种底物的环氧化，包括一级、二级和三级脂肪族羧酸，以及多种氨基酸、糖类药物及其衍生物。这种模块化协议大幅提升了合成灵活性。","scd":null,"kp":[]},{"i":42916,"as":"为满足边缘设备对空间和功耗的限制，研究开发了一种集成了模拟滤波和数字处理功能的电容式光电二极管。该器件在硫化锑光吸收层上原位形成氧化锑介电层。这种电容-光电二极管结构在高频下表现出增强的电荷积累能力，实现可防窃听的高通滤波功能。介电层的原位形成引入了阴离子空位，在高能光子下实现信号计算。","scd":null,"kp":[]},{"i":42917,"as":"为解决传统光电储备计算（RC）受限于单极性光响应的问题，研究开发了一种全光控RC系统。该系统采用均匀稳定的氧化物忆阻器阵列，利用氧空位的光致动态演化，表现出波长依赖的双极性光响应。通过调节双波长光的功率密度和照射模式，实现了光电流弛豫和非线性的动态控制，从而支持双极性和并行编码，提升了计算的多样性。","scd":null,"kp":[]},{"i":42918,"as":"在无限层镍酸盐薄膜中观察到了高场稳定重入超导现象，打破了磁场通常抑制超导性的常规。这种具有高临界温度（高达40K）的材料，在低场和高场下的超导态均可通过Jaccarino-Peter效应（场补偿机制）来解释。该发现证明了在镍酸盐中通过高磁场诱导并稳定超导态的可行性，为超导研究开辟了新途径。","scd":null,"kp":[]},{"i":42919,"as":"研究提出一种高吞吐量的光学处理单元（OPU），结合相干干涉、波分复用和空间并行技术，在单芯片上集成了四个光学模拟核心。该OPU支持124通道并行任务处理，计算速度达到65.04 TOPS，计算密度为5.16 TOPS/mm²。基于此平台构建的光电卷积神经网络，展现了多特征融合增强能力，为人工智能硬件提供了高效解决方案。","scd":null,"kp":[]},{"i":42920,"as":"研究提出一种受脊髓启发的人工多模态中间神经元（AMINs），通过将应变、压力和温度传感器与NbOx忆阻器神经元集成在混合平台上。该系统实现了分层神经编码，并生成高信息密度的时空脉冲模式，成功将初级感觉输入转化为高级神经处理路径，产生统一的簇状脉冲。这为人工触觉系统在智能边缘接口中的应用提供了基础。","scd":null,"kp":[]},{"i":42921,"as":"研究揭示了RNA核糖的2'-OH基团在二价阳离子存在下对RNA凝聚的关键作用。2'-脱氧核糖会抑制核酸的液-液相分离，并抑制导致凝聚物动态停滞的渗滤转变。全原子模拟表明，与RNA相比，单链DNA的溶剂化和致密化程度增加。此外，RNA常见的2'-O甲基化修饰对这一相分离和渗滤转变过程具有重要调控作用。","scd":null,"kp":[]},{"i":42922,"as":"针对分子活性预测中结构高度相似但活性差异巨大的“活性悬崖”（ACs）导致模型扭曲的问题，研究引入了AC感知（ACA）的归纳偏置。该方法结合回归与软间隔三元组对比学习构建ACA损失，在训练期间动态挖掘高价值活性悬崖三元组，纠正潜在空间中不一致的邻域，从而减少活性悬崖违规，产生更连贯的活性梯度，降低标签不连贯性。","scd":null,"kp":[]},{"i":42923,"as":"研究通过神经网络模型分析了非洲有蹄类动物过去2300万年的多样化历程，以探究非洲巨型食草动物（≥1000公斤）的衰退原因。分析表明，非洲有蹄类动物的分化率在约720万年前开始加速，但分化率在360万年前趋于平稳，而灭绝率在更新世初期（258万年前）急剧上升。结论指出，是较低的分化率而非更高的灭绝率主导了巨型食草动物多样性的崩溃。","scd":null,"kp":[]},{"i":42924,"as":"基于2007至2020年的水产资源贸易数据库，研究对188个国家的国内鲨鱼割鳍法规对鲨鱼产品贸易的影响进行了因果推断分析。结果显示，割鳍法规对整体鲨鱼贸易量的影响微弱且无统计学意义。然而，长期趋势表明，采取割鳍法规的国家倾向于减少出口、小幅增加进口，并保持相对稳定的国内消费量。","scd":null,"kp":[]},{"i":42925,"as":"活细胞被改造为微型工厂，能够生长出具有同心层的可编程蛋白质晶体。每一层同心层都可以携带不同的纳米级货物，并能够按顺序溶解，从而在细胞内实现精确计时、多阶段的有效载荷程序化释放。","scd":null,"kp":[]},{"i":42926,"as":"锂离子电池电极中的低频电化学响应通常被广泛解释为固态锂扩散的标志。研究指出，多孔阴极颗粒内的电解质渗透能够独立于体相扩散，产生与扩散机制相似的类扩散过电位行为。这揭示了电池电化学响应中存在非扩散机制的干扰因素。","scd":null,"kp":[]},{"i":42927,"as":"研究调查了85名未接种疫苗、未接受抗病毒治疗且感染新冠病毒的重症肌无力（MG）患者。结果显示，低氧性肺炎发生率为48例，其中45.8%的患者体内存在中和I型干扰素的自身抗体（AAN-I-IFN），29.2%同时中和IFN-α2和IFN-ω。存在AAN-I-IFN（中和10 ng/mL的IFN-α2和IFN-ω）的MG患者发生低氧性肺炎的风险显著更高（OR为12.7）。","scd":null,"kp":[]},{"i":42928,"as":"研究使用具有优化局部疏水性、弱蛋白结合亲和力及高内皮靶向性的水溶性金纳米团簇Au25(o-MBA)18作为探针，揭示了肝脏血窦内皮细胞介导纳米颗粒消除的新机制。研究发现，肝脏血窦内皮细胞能够通过分泌循环外泌体，实现超小金纳米颗粒的系统性清除，这为理解肝脏解毒过程和纳米颗粒的体内命运提供了重要依据。","scd":null,"kp":[]},{"i":42929,"as":"","scd":null,"kp":[]},{"i":42930,"as":"","scd":null,"kp":[]},{"i":42931,"as":"基于对美国、加拿大和英国约2000名父母的激励兼容实验，研究探讨了青少年教育中使用AI工具的社会动态。结果表明，当感知到其他青少年的使用率从20%上升到80%时，父母对AI高级订阅的支付意愿增加了60%以上。这表明竞争压力和相对优势驱动了AI技术的广泛扩散，而有关潜在下游技能风险的信息对其使用行为的改变有限。","scd":null,"kp":[]},{"i":42932,"as":"为解决可充电锂-氯气电池中Cl2保留差和转化动力学迟缓的问题，研究提出了一种空间耦合的Cl2管理阴极。该阴极在富含微孔的基底内结合了Cl2限域和短程传输机制，并在高密度、锚定在孔壁上的弯曲镍单原子位点实现自发活化。这种设计有效提升了电池在深度循环和高倍率下的可逆性和整体性能。","scd":null,"kp":[]},{"i":42933,"as":"研究结合Li°||Cu°循环数据统计、成分表征以及原子和化学模拟，探讨了锂金属电池电解液氟化添加剂的设计。结果显示，虽然库仑效率（CE）是评估不对称电池的关键指标，但实际CE值常常偏离仅基于添加剂结构的预期。以九氟丁磺酰氟作为电解液添加剂为例，其对Aurbach CE值仅有微弱的边际效应，强调了合理设计稳定锂金属电极添加剂的复杂性。","scd":null,"kp":[]},{"i":42934,"as":"研究采用阶段性竞争吸附合成策略，制备了由原子级CrOx层界面连接的二维Pt纳米板（Pt–CrOx NPs）。该结构利用强烈的Pt-CrOx电子相互作用，从根本上抑制了Pt的溶解，并大幅提升了氧还原反应（ORR）活性。所得催化剂表现出极佳的电化学稳定性，其质量活性仅下降3.3%，为高功率密度和耐用的质子交换膜燃料电池提供了新方案。","scd":null,"kp":[]},{"i":42935,"as":"针对质子交换膜水电解槽（PEMWE）中IrO2成本高和催化性能不足的问题，研究提出了基于Ir与杂原子间内聚能（ΔCE）和原子半径（ΔR）差异的双重标准。据此筛选出具有最低ΔCE和ΔR的Mo和W元素，成功合成了超细IrO2基固溶体。该固溶体结构有效提升了催化效率，为高效酸性水氧化反应提供了新型催化剂设计路径。","scd":null,"kp":[]},{"i":42936,"as":"研究利用宽频瞬态吸收光谱，探究了溶剂和配体对铈(IV)光催化中激发态动力学的影响。在乙腈中，光激发引发配体到金属的电荷转移（LMCT），生成了寿命极长（τ = 40 µs）的电荷分离态，包含游离的硝酸根自由基和还原态Ce(III)中心。而在甲醇等质子溶剂中，这种有效光化学反应被抑制，引发了超快失活过程（τ = 1.5 ps）。","scd":null,"kp":[]},{"i":42937,"as":"研究探讨了氧化物载体上的原子级分散氧化物单体的稳定性问题。研究发现，Zn1O1单体在氧化物载体（M'O'x）上的稳定性高度依赖于双界面键（Zn-O'和O-M'）的精细配对。载体的氧空位形成能是决定这种配对稳定性的关键因素，过低的氧空位形成能会破坏结构稳定性。该发现为提高合成气转化为轻质烯烃反应中的催化稳定性提供了指导。","scd":null,"kp":[]},{"i":42938,"as":"研究开发了一类用于光诱导原子转移自由基聚合的高效酸碱响应两性离子光催化剂。吸电子的甲基吡啶鎓取代基增强了苯并咪唑的酸性，使其在弱碱性或中性条件下形成强供电子阴离子。该光催化剂具有可见光吸收和高还原性激发态，其荧光被ATRP引发体以高达10^9 M^-1 s^-1的速率淬灭，在ppb级浓度下即可实现对聚合反应的精确调控。","scd":null,"kp":[]},{"i":42939,"as":"研究证明了金属纳米团簇的原子级配位工程能够调控团簇组装晶体的光子传输特性。利用双齿膦配体作为“分子手术刀”，研究构建了一系列具有相同二十面体核心但外围结构系统性变化的Pt1Agx（x = 18-37）纳米团簇。这些团簇组装成的晶体展现出了卓越的光子传输能力，成功将原子级结构与器件的光学波导性能联系了起来。","scd":null,"kp":[]},{"i":42940,"as":"研究首次制备出表现出自发取向和长程六方柱状有序排列的动态共价网络。这种自组装行为是由有机硅氧烷连接体与动态共价酰氨基脲键（诱发氢键）之间的相分离驱动的。使用离散且长度优化的硅氧烷连接体是实现这一高度有序和近乎完美的垂直取向结构的关键，该有序网络仅需简单的溶剂蒸发即可获得。","scd":null,"kp":[]},{"i":42941,"as":"研究开发了一种基于刚性、C3对称的均苯四甲酸二酰亚胺分子三角形的单分子锂离子人工通道。该结构具有2.2纳米的壁高和由富电子羰基氧排列而成的4.1埃窄孔。单通道测量表明，该通道实现了超快锂离子传输，其电导率高达57.4 pS（是短杆菌肽A介导钾离子电导的2.5倍），同时保持了创纪录的50高选择性比。","scd":null,"kp":[]},{"i":42942,"as":"本研究表明，反离子动力学控制超分子聚合物的组装途径和手性。为研究该现象，研究人员设计了带有两个四氟硼酸根（BF4−）反离子、用于氢键结合的酰胺基团以及S型或R型手性侧链的双阳离子四吡啶基钯(II)配合物。该研究揭示了单一反离子在特定系统内的动态效应，填补了不同离子物种效应对比研究的空白。","scd":null,"kp":[]},{"i":42943,"as":"本研究首次发现天然抗肿瘤剂绿原酸（CA）具有独特的超声余辉特性，并由此设计出能在水中自组装的CA前药。这种基于天然产物的原位超声余辉超分子水凝胶有效克服了实时荧光激发带来的背景干扰问题。它通过延长激发停止后的发光时间来抑制生物背景噪声，显著提高了成像的信噪比，并可用于术后胶质母细胞瘤的治疗。","scd":null,"kp":[]},{"i":42944,"as":"研究报道了一种利用n型有机光电化学突触（n-OOECS）的光学加密神经形态密码系统。该全固态突触装置基于单组分融合低聚物有机混合离子-电子导体，具备多模态可重构可塑性，实现了破纪录的10位电导态、可重编程时域脉冲波形以及可调的易失性至非易失性切换。该系统通过光电化学协同调制，实现了端到端安全通信中的类脑加密逻辑和自适应信息保护。","scd":null,"kp":[]},{"i":42945,"as":"该研究提出一种热激活界面极化策略，将钙钛矿半导体器件的光电性能热损耗转化为增益。通过将缺电子的N-杂芳族阳离子掺入碘化铅钙钛矿，在有机-无机界面引发热驱动的电子云变形，建立可逆的界面偶极子。这一过程重塑了静电分布，降低了电荷传输势垒并有效屏蔽了深能级陷阱态，最终使载流子迁移率提高了约100倍。","scd":null,"kp":[]},{"i":42946,"as":"在二维范德华晶体LiInP2S6中发现了一种水合驱动的对称性转变。水的插层将原始晶体的手性-非极性相（点群32，带隙3.0 eV）转化为手性-极性结构（点群3，带隙3.15 eV），该结构由亚埃级晶格畸变稳定。这种结构变化产生了新的对称性，使水化相在1550 nm通信波长下的非共振光学二次谐波（SHG）系数高达数pm/V，是现有材料的两倍。","scd":null,"kp":[]},{"i":42947,"as":"针对随机药物干预无法精确重置异常线粒体膜电位（MMP）的挑战，研究人员基于临床单细胞RNA测序分析，开发了一种基于超声激活的压电驱动类芬顿系统微球（PF@MS）。该系统通过超声触发的铁酸钡（Fe-BTO）压电势，与超声相关的铁价态调制相关联，缓解了Fe3+/Fe2+转化带来的催化瓶颈，消耗局部质子以上调MMP，从而缓解椎间盘退变。","scd":null,"kp":[]},{"i":42948,"as":"为解决锂锰富集层状氧化物（LMR）正极材料中严重的晶格氧不可逆损失导致的容量衰减和电压衰减问题，研究开发了一种热驱动分层（TDS）策略。该策略在材料体相中构建了均匀的La2O3表面涂层和浓度梯度分布的镧。结合先进表征和密度泛函理论（DFT）计算证实，体相镧能够稳定过渡金属和晶格氧的化学态及其局部电子结构和配位环境，实现了超稳定的富锂正极。","scd":null,"kp":[]},{"i":42949,"as":"针对混合阳离子铅混合卤化物钙钛矿对电子辐照极其敏感的表征难题，本研究开发了一种低剂量同步的四维扫描透射电子显微镜（4D-STEM）和能量色散X射线光谱（EDX）映射方法。该方法能够在纳米尺度上同时绘制材料的化学和结构构架，成功探测并揭示了钙钛矿光伏材料中与纳米级异质性相关的不稳定性起源。","scd":null,"kp":[]},{"i":42950,"as":"本研究利用β-三酮甲基丙烯酸酯单体合成了二酮胺（DKE）型玻璃体高分子，通过合理的单体设计来决定网络的加工性、粘弹性和可回收性。研究发现，通过系统改变β-三酮（TK）部分与聚合物主链之间的间隔长度，能够揭示决定玻璃体高分子特性的关键结构-性能关系。该共价适应性网络（CANs）策略成功将热固性塑料的机械鲁棒性与热塑性塑料的可重复加工性结合起来。","scd":null,"kp":[]},{"i":42951,"as":"研究观察到了单电离镱离子从亚稳态2F7/2o跃迁的三种半禁戒跃迁现象。由于跃迁过程涉及到的上能级和下能级均具有极长的寿命，使得这些跃迁的线宽非常窄，频率达到了亚赫兹级别。这些新发现的跃迁通道补充了镱离子中已被频繁使用的跃迁，为相关量子物理研究提供了新的光谱学数据。","scd":null,"kp":[]},{"i":42952,"as":"为捕捉打破详细平衡的持续性噪声作用下的活性聚合物非平衡动力学特性，研究提出了一种基于复合公式的简单且可靠的分析框架。该框架将聚合物的动力学与活性物质的非平衡特征相结合，为自然界中广泛存在的活性聚合物的动力学行为研究提供了有效的理论计算工具。","scd":null,"kp":[]},{"i":42953,"as":"动力学不确定性关系（KURs）通过将电流的信噪比与系统及其储层之间的交换事件计数（即动态活性）联系起来，为非平衡输运的精度设定了基本限制。该研究将这一理论框架扩展应用到了处于强耦合状态下的介观导体系统中，进一步确立了介观系统中量子输运和涨落的基本极限。","scd":null,"kp":[]},{"i":42954,"as":"研究对硼碳化物超导体YNi2B2C进行了德哈斯-范阿尔芬（dHvA）振荡测量和能带结构计算。改进后的能带结构成功解释了以往研究无法解释的大dHvA频率β和ζ的来源。通过对比实验与计算结果，研究详细分析了该超导体中依赖于费米面层的电声子耦合特性。","scd":null,"kp":[]},{"i":42955,"as":"多点能量关联器在重离子碰撞研究中备受关注，因为它能将实验测量与底层量子场论描述紧密联系起来。该研究超越了以往聚焦于最简单关联的理论限制，利用多点能量关联器深入剖析了夸克-胶子等离子体（QGP）中喷注修饰的详细机制。","scd":null,"kp":[]},{"i":42956,"as":"研究指出，飞行时间法（ToF）在评估厚钙钛矿晶体的载流子迁移率时，其测量结果对电极几何形状非常敏感。电极边缘电场线的集中会显著缩短载流子的渡越时间。当器件的电极直径小于晶体厚度时，扭曲的电场会使ToF迁移率被高估至10倍以上。为此，研究规定电极直径与晶体厚度的比例必须大于8，以获得准确的迁移率测量值。","scd":null,"kp":[]},{"i":42957,"as":"为克服生物蛋白压电材料难以调控压电域和机械性能脆的缺点，研究提出了一种基于多巴胺的双放大器小分子策略。通过多巴胺介导的调制作用，在丝素蛋白基薄膜中实现了高达12.7 pC N−1的压电系数。性能的大幅提升归因于双重机制：多巴胺促进了β-折叠二级结构的形成，并与分子偶极子产生了协同增效作用，实现了高性能生物有机压电材料。","scd":null,"kp":[]},{"i":42958,"as":"研究首次使用机械平面手性轮烷作为构型稳定的自由基源，成功在扭曲的苝二酰亚胺（PDI）分子生色团中诱导出单手螺旋结构。该方法有效克服了常规螺旋PDI衍生物易发生外消旋的缺陷，使材料表现出持久的圆二色性和圆偏振发光特性。此外，PDI巨大的π表面还促进了轮烷的自组装，这在机械互锁分子中十分罕见。","scd":null,"kp":[]},{"i":42959,"as":"研究开发了一个可编程的益生菌平台，利用格氏乳杆菌（LG）与肿瘤的代谢相互作用来增强膀胱癌的化学动力学免疫治疗。所选的LG菌株具有卓越的肿瘤定植能力，并能内源性合成H2O2和乳酸，从而为血红蛋白介导的化学动力学治疗创造了最佳的肿瘤微环境。该研究揭示了细菌代谢物在跨界细胞通讯中的关键介导作用，有效重塑了免疫抑制性肿瘤微环境。","scd":null,"kp":[]},{"i":42960,"as":"室温液态金属为赋予传统材料先进功能提供了一条有效途径，无需重新设计宿主材料的化学框架。通过表面、界面或受限集成策略，液态金属能够将电学、热学、机械和电化学功能直接赋予常规材料，使其能够满足复杂机械和环境条件下对软体和自适应技术的感知和响应要求。该综述系统总结了液态金属在智能材料系统构建中的最新进展和分类集成策略。","scd":null,"kp":[]},{"i":42961,"as":"金属卤化物钙钛矿凭借卓越的光电特性、可调的低维结构以及显著的离子迁移动力学，成为神经形态视觉计算的理想平台。本综述聚焦于低维钙钛矿纳米结构（零维、一维和二维）在神经形态视觉器件中的最新进展。文章总结了相关材料的合成与集成技术，并深入分析了由离子迁移驱动的光电和忆阻行为，以克服传统冯·诺依曼架构的局限，实现感存算一体化。","scd":null,"kp":[]},{"i":42962,"as":"本研究提出一种构建自体生成工程活体材料的多功能平台，结合蛋白质挖掘、计算建模和合成生物学。通过分析33,564个CsgA-like同源物，筛选新型细胞外基质蛋白纳米纤维，利用AlphaFold2和分子动力学模拟验证其结构稳定性，并重编程大肠杆菌curli机制实现材料功能化。","scd":null,"kp":[]},{"i":42963,"as":"本研究提出一种基于异质结氧化物半导体通道的超薄沟道场效应晶体管。通过采用双层氧化物通道工程降低界面缺陷密度，实现大于100 cm²/V.s的场效应迁移率。在此基础上，研制出具备低热预算、超大规模特性的存储-逻辑双模铁电晶体管，适用于单片3D集成电路系统。","scd":null,"kp":[]},{"i":42964,"as":"本综述探讨了手性超表面在亚波长尺度操控光自旋、相位和振幅的原理。通过从对称性破缺角度（包括面内、面外对称性破缺和低对称晶格工程）总结核心设计原则，阐述了最大化手性光学响应的策略，为手性传感、光发射及非线性光子学等平面光学领域提供了指导。","scd":null,"kp":[]},{"i":42965,"as":"本文研究了利用光催化技术将聚酯塑料废弃物转化为高附加值有机氮化合物的升级回收策略。聚酯（如聚乳酸PLA和聚对苯二甲酸乙二醇酯PET）水解产生的单体易于通过光催化进行升级。该策略在温和条件下利用可再生能源驱动反应，实现了废弃碳资源的可持续转化。","scd":null,"kp":[]},{"i":42966,"as":"本研究利用金刚石晶界处快速的金刚石-金属反应，构建了垂直离子迁移通道，成功在多晶金刚石中实现了非易失性电阻切换行为。所制备的金刚石忆阻器展现出约10⁴的高开关比，并在宽温度范围内具备可靠的循环和保持性能，克服了金刚石导电性调制和化学稳定性方面的挑战。","scd":null,"kp":[]},{"i":42967,"as":"本研究通过异价Sn²⁺取代层状无铅卤化物钙钛矿Cs3Bi2Br9，实现了晶体结构和电子特性的同时调控。该取代策略有效改善了材料中原本低效的电荷分离与传输过程，显著提升了可见光吸收能力，进而增强了CO2光催化还原为高附加值燃料的效率。","scd":null,"kp":[]},{"i":42968,"as":"研究将π扩展的芳香族单元整合到无封端肽中，构建了具有高度结构有序性的超分子水凝胶。芘修饰的二肽自组装成单分散螺旋纳米纤维和自修复水凝胶。冷冻电镜以1.7 Å的近原子精度解析出其紧密排列的初原纤维结构，揭示了极性端基组织水分子并形成有序水通道的机制。","scd":null,"kp":[]},{"i":42969,"as":"本文提出一种结构可泛化的大模型框架，解决电力系统在拓扑结构不确定下的运行问题。该框架将电力系统运行转化为拓扑感知学习问题，利用基于图的拓扑编码和多拓扑训练，构建统一的潜在表示空间，使模型能够捕捉不变的物理与运行规律，有效克服了固定结构模型在动态重构配电网中的性能退化问题。","scd":null,"kp":[]},{"i":42970,"as":"","scd":null,"kp":[]},{"i":42971,"as":"本文针对连续日内电力市场中的电网级电池储能系统，提出一种计算高效的滚动内在高频交易策略。该方法结合完整限价订单簿和快速动态规划近似，以毫秒级分辨率处理持续更新的买卖报价与市场规则，并综合考虑了退化线性近似等技术参数，从而实时捕捉新交易机会以实现收益最大化。","scd":null,"kp":[]},{"i":42972,"as":"","scd":null,"kp":[]},{"i":42973,"as":"","scd":null,"kp":[]},{"i":42974,"as":"研究在网络科学中建立了有效图电阻与拉普拉斯扩散动力学产生的累积散热之间的精确物理关系。研究表明，弛豫过程中耗散的总热量精确等于有效图电阻。这一动力学视角为结构如何影响有效图电阻提供了时间分辨的物理解释，并为基于流动系统的网络连通性优化提供了高效途径。","scd":null,"kp":[]},{"i":42975,"as":"","scd":null,"kp":[]},{"i":42976,"as":"","scd":null,"kp":[]},{"i":42977,"as":"","scd":null,"kp":[]},{"i":42978,"as":"本研究追踪了从森林源头到城市化河口的溶解性黑碳（DBC）和颗粒态黑碳（PBC）。结果显示，城市化区域化石燃料来源的14C游离态黑碳分别贡献了18±3%的DBC和24±6%的PBC，导致其表观14C年龄分别增加1475–1972年和1619–2877年。这一发现揭示了城市化三角洲对输出至海洋的黑碳具有显著的化石印记。","scd":null,"kp":[]},{"i":42979,"as":"","scd":null,"kp":[]},{"i":42980,"as":"本研究提出一种利用飞秒脉冲激光进行光学后处理的技术，实现了碳纳米管（CNT）薄膜排列的局部精准控制。该偏振引导方法在薄膜成型后进行加工，能够生成厚度超过200 nm、向列序参数高达0.93的亚微米级局部定向CNT结构，解决了在同一薄膜内集成异质CNT结构的空间可编程性限制。","scd":null,"kp":[]},{"i":42981,"as":"本研究提出纯无机分子笼策略，通过本征C1对称的磷-硫族元素笼的几何畸变，调控二次谐波圆二色性（SHG-CD）。通过位点选择性取代，合成了一系列具有可控畸变的手性纯分子笼晶体（如S/R-P4S5等）。这些晶体在1064 nm激发下表现出显著的SHG-CD（gSHG-CD达0.48–1.70）和宽广的红外透明度。","scd":null,"kp":[]},{"i":42982,"as":"受植物天然光保护机制启发，本研究通过一锅法组装天然多酚，开发出一系列全小分子水凝胶防晒剂。该水凝胶具备高效紫外线屏蔽能力（高SPF值）、强生物粘附性、抗氧化和抗菌活性。其可见光透过率高且皮肤渗透性低，在保持良好环境稳定性的同时，实现了安全高效的光防护。","scd":null,"kp":[]},{"i":42983,"as":"本研究发现在CO2加氢制甲醇反应中，In2O3颗粒会反应诱导转化为InOx纳米层和次表面In-Zr-O固溶体。H2还原产生的移动金属In0驱动了这一分散和扩散过程，形成In-ZrO2@InOx结构。通过精准控制反应条件，实现了三种不同In物种的最优分布，大幅提升了甲醇的合成效率。","scd":null,"kp":[]},{"i":42984,"as":"本研究开发出一种分子魔术贴自愈合水泥复合材料。该材料掺入超低浓度的聚合物，摒弃了传统依赖包埋剂或高添加剂量的自愈合方法。该设计克服了自愈合重复性、规模化生产和力学性能受限的缺陷，使水泥材料在产生裂缝时能够实现有效修复，从根本上提升其耐久性。","scd":null,"kp":[]},{"i":42985,"as":"","scd":null,"kp":[]},{"i":42986,"as":"扫描超导量子干涉器件（SQUID）显微镜通过将超导环路缩减至亚微米级别，实现了约10 nT Hz^(-1/2)的磁场灵敏度和低于50 nm的空间分辨率。与传统只能测量体相平均磁场响应的SQUID技术不同，该扫描探针技术能够对凝聚态物质中微小且空间不均匀的局部磁结构和电流分布进行实空间的直接可视化探测。","scd":null,"kp":[]},{"i":42987,"as":"本研究通过原位配体交换合成了具有可调手性的光交联亚纳米线。受甲虫表皮Bouligand结构和光学特性的启发，利用光固化3D打印技术制造了基于亚纳米线的混合凝胶。该策略成功构建了集成了光旋转（OR）和双折射（BF）特性的生物启发光学器件，实现了可编程的偏振虹彩现象。","scd":null,"kp":[]},{"i":42988,"as":"本研究通过基于脲氢键和疏水相互作用的协同交联软聚合物链，实现了兼具超强拉伸性、高机械韧性和优异抗损伤能力的可逆交联聚合物的可扩展制造。该材料结构设计有效抑制了极端变形下的裂纹扩展并防止灾难性失效，成功打破了聚合物科学中拉伸性与强度之间的固有矛盾。","scd":null,"kp":[]},{"i":42989,"as":"全固态锂硫电池结合了硫正极、锂负极和不燃性固态电解质，突破了传统液态锂离子电池的能量密度限制（<300 Wh/kg）。然而，固态电解质与锂负极及硫正极之间的界面高阻抗严重阻碍了电荷转移和锂剥离/电镀动力学，成为核心瓶颈。本综述重点分析了这些固固界面的化学机制及优化策略。","scd":null,"kp":[]},{"i":42990,"as":"研究通过聚氟芳烃分子的电子效应调节钙钛矿结晶动力学，以实现大面积基板上均匀且高质量的钙钛矿结晶。实验引入含有强吸电子氰基的3,4,5-三氟苯甲腈（TFBN），构建了缺电子共轭体系。该配置不仅增强了与碘离子（I⁻）的阴离子-π相互作用，还与铅离子（Pb²⁺）框架形成强配位。结合分子间氢键的协同作用，TFBN有效调控钙钛矿的结晶过程，为钙钛矿太阳能电池从实验室迈向工业化量产提供了技术基础。","scd":null,"kp":[]},{"i":42991,"as":"研究开发了一种基于全甲氧基化二酮吡咯并吡咯（DPP）两亲性共聚物的无膜有机电化学晶体管（OECT）平台，用于检测高氯酸盐（ClO₄⁻）。聚合物的骨架甲氧基化促进了高氯酸根离子的优先体积电化学掺杂，实现了高效的体极化子稳定。该技术克服了水环境中检测新兴污染物时受限于离子水化动力学和体积电化学掺杂迟缓的难题，为高增益电化学传感器提供了新方案。","scd":null,"kp":[]},{"i":42992,"as":"质子交换膜燃料电池（PEMFCs）的广泛应用受限于铂等贵金属的高成本。氧还原反应（ORR）受限于复杂的中间体标度关系，成为核心瓶颈。研究提出利用界面非均质性，整合跨越次表面晶格、化学吸附层和近界面溶剂化体积的对称破缺扰动，解耦ORR中间体的吸附能。该机制打破了传统的吸附能标度关系限制，为摆脱贵金属催化剂依赖提供了理论路径。","scd":null,"kp":[]},{"i":42993,"as":"真空沉积钙钛矿发光二极管（LED）能精确控制厚度和成分，但面临结晶控制不足的问题，导致近红外器件的外量子效率（EQE）仅约10%。快速成核和晶体生长不良会产生富含缺陷的薄膜。为解决此问题，研究提出利用两性离子中间层引导亚微米自组装策略。该方法有效调节薄膜结晶过程并减少缺陷，提升了光致发光量子效率（PLQE）和整体器件性能。","scd":null,"kp":[]},{"i":42994,"as":"延长三重态激发态寿命是开发高效光催化系统的关键。研究设计并合成了一系列基于紫精的环烷衍生物，引入了空间共轭（TSC）结构。与仅具有单一TSC单元的衍生物相比，具备串联TSC结构的分子显著延长了三重态激发态寿命。这种串联空间共轭设计为高效无金属光氧化还原催化提供了创新的分子结构基础。","scd":null,"kp":[]},{"i":42995,"as":"研究开发了用于便携式尿液分析的缺陷编程DNA折纸活性氧（ROS）传感器（DOSs）。以三角形DNA折纸纳米结构作为二维软晶体，通过编程相邻主链之间的不连续缺陷数量，确立了缺陷数量与ROS触发的降解动力学之间的正相关性。通过正交组装靶向和信号分子，将这种可编程降解转化为诊断功能，成功实现了局部氧化应激的非侵入性动态监测与临床读出转化。","scd":null,"kp":[]},{"i":42996,"as":"宽禁带（WBG）钙钛矿特别是混合卤化物体系是制备高效钙钛矿叠层太阳能电池的关键，但面临光致相分离、高缺陷密度和界面失配等挑战。综述指出，WBG钙钛烯的结晶过程复杂且不均匀是导致相分离、缺陷形成和稳定性问题的根本原因。文章深入描述了通过结晶调制策略稳定WBG钙钛矿太阳能电池和组件的技术路径，以突破单结器件的理论效率极限。","scd":null,"kp":[]},{"i":42997,"as":"针对分级多孔碳复杂孔拓扑结构限制能量传输的问题，研究建立了一个结合双向性能预测与物理驱动3D结构预测的研发框架。利用CatBoost和差分进化构建了R²=0.8595的高精度双向映射模型，实现逆向优化。在结构维度上，开发了结合高斯随机场（GRF）和Cahn-Hilliard相场演化的协同算法，突破了传统均一标量描述的限制，实现了孔隙演化的精确预测。","scd":null,"kp":[]},{"i":42998,"as":"钠离子电池层状氧化物正极材料在充放电循环中易发生相变、不可逆氧损失和严重的界面降解。研究以O3-NaNi₁/₃Fe₁/₃Mn₁/₃O₂正极为原型，提出了一种超越常规化学调制的集成修饰策略。通过表面重建衍生出富钇的NaYO₂（NYO）涂层，促进了位点选择性的体相缺陷工程。该策略同步增强了材料的体相、表面和界面特性，大幅提升了正极的综合性能。","scd":null,"kp":[]},{"i":42999,"as":"研究引入了一种范德华集成的非化学侵入式WS₂/h-BN/Au异质结构，实现了可调的强激子-等离极化激元。h-BN间隔层形成可控纳米间隙，调节镜像电荷效应，从而引起电磁场压缩。该设计突破了可见光频率下深度亚波长 confinement 的限制，且避免了化学修饰或图案化等离子体纳米结构的需求，明确揭示了金属镜面诱导的电磁限制在强耦合中的关键作用。","scd":null,"kp":[]},{"i":43000,"as":"研究通过使用亚胺硼酸酯动态共价交联剂替代静态共价键，开发了具备自修复和可回收性的水凝胶。对比邻位和对位亚胺硼酸酯发现，双动态共价交联剂的取代基差异与基质pH值共同影响水凝胶的强度、刚度和弹性。该研究详细阐述了分子结构的细微变化如何引发大分子固体宏观特性的显著差异，成功实现了真正闭环可回收的高性能水凝胶材料。","scd":null,"kp":[]},{"i":43001,"as":"有机半导体（OSCs）因其骨架由轻元素组成，在自旋传输方面表现出优于无机材料的潜力，成为多功能电子器件发展的关键平台。文章综述了有机自旋电子学的最新进展，涵盖自旋弛豫机制的理论框架完善、新颖的化学调制策略以及自旋输运动力学的深入理解。这些进展大幅提升了有机半导体在多功能自旋电子器件中的适用性。","scd":null,"kp":[]},{"i":43002,"as":"综述了具有可逆厚度形变能力的柔性表皮材料。与传统的通过弯曲、伸长或扭转实现运动的软致动器不同，这类系统无需刚性支撑即可实现面外变形，产生局部凸起、收缩和可编程的接触力学。厚度调节被视为一种耦合能量转换、几何形状和顺应性的材料-结构策略，在触觉交互、形态适应以及复杂受限或非结构化环境中的作业方面展现出全新应用模式。","scd":null,"kp":[]},{"i":43003,"as":"研究展示了一种势垒辅助的NH₃等离子体工艺，实现了单层二硫化钼（MoS₂）的简并n型掺杂，同时保持了其结晶度。超薄pV3D3/Al₂O₃介电叠层不仅阻挡了等离子体造成的损伤，还充当化学过滤器允许NHₓ物质选择性渗透。这种空间选择性电阻工程克服了二维晶体管中缺乏可扩展和区域选择性掺杂技术的挑战，有效降低了局部过电阻，提升了低功耗逻辑器件的技术就绪度。","scd":null,"kp":[]},{"i":43004,"as":"针对传统人工晶状体（IOL）缺乏生物适应性且焦点固定的局限，研究开发了一种基于可注射多功能水凝胶的仿生晶状体。该水凝胶通过多层动态交联和囊袋内原位微囊袋辅助凝胶化，构建了具有连续折射变化的仿生透镜。该技术不仅同时重建了晶状体的光学-机械特性，还能动态调节术后微环境，有效解决白内障术后的视觉干扰和并发症问题。","scd":null,"kp":[]},{"i":43005,"as":"研究开发了一种靶向串联激活的人工尿液生物标志物传感器（TADEI），用于胸主动脉瘤和夹层（TAAD）的早期检测与治疗干预。该传感器由近红外荧光团偶联三个关键组分构成：靶向血管细胞粘附分子-1（VCAM-1）、响应炎症介质Caspase-1和血管重塑相关蛋白酶Legumain的串联底物。该平台实现了TAAD早期标志物的实时光学成像和尿液分析，克服了临床成像仅能检测晚期结构异常的局限。","scd":null,"kp":[]},{"i":43006,"as":"研究通过机器学习辅助优化和多孔芳纶纳米纤维骨架内的原位扩散控制聚合，开发出一种具有连续电导率梯度（CCG）的全有机气凝胶。该气凝胶结合了聚吡咯（PPy）的厚度连续梯度和高度多孔结构，实现了阻抗的平滑过渡。采用常压干燥策略保证了可扩展性，该材料成功打破了超宽带电磁干扰屏蔽中难以同时实现低反射和低透射的限制，表现出优异的超低反射电磁屏蔽性能。","scd":null,"kp":[]},{"i":43007,"as":"研究受“培乐多”泥启发，开发了一种基于纤维素纳米晶体（CNC）的三重网络形状适应性可吸收生物材料iHEÄLS，用于肌肉骨骼修复。该材料的三重网络相互作用使其能够贴合不规则缺陷、在湿环境中牢固粘附并实现形状稳定与自修复。交联后的机械训练通过排列聚合物链强化网络，平衡了机械稳健性与生物降解性，有效解决了传统医疗填充物密封不稳和再生能力不足的问题。","scd":null,"kp":[]},{"i":43008,"as":"","scd":null,"kp":[]},{"i":43009,"as":"","scd":null,"kp":[]},{"i":43010,"as":"","scd":null,"kp":[]},{"i":43011,"as":"","scd":null,"kp":[]},{"i":43012,"as":"","scd":null,"kp":[]},{"i":43013,"as":"","scd":null,"kp":[]},{"i":43014,"as":"","scd":null,"kp":[]},{"i":43015,"as":"","scd":null,"kp":[]},{"i":43016,"as":"在WEST托卡马克装置的氘等离子体中，对氢少数离子回旋共振加热（ICRH）进行了系统性实验研究。在保持全局等离子体参数和天线耦合近似恒定的条件下，开展了共振层径向位置和少数离子浓度的扫描。结果表明，当共振层向高场侧偏移约7厘米且氢离子浓度在5%至8%之间时，加热性能达到最佳。共振层进一步向内位移会导致性能显著退化，而位于低场侧时性能几乎减半。","scd":null,"kp":[]},{"i":43017,"as":"准等向（QI）磁场因其对新经典径向和平行输运的优化，成为仿星器磁构型的主要选择。然而，高度准等向性往往伴随着强烈的磁通面成型和复杂的线圈几何形状。研究将准等向性与分段全向性（pwO）结合，构建了QI-pwO磁场。该磁场在磁面低场区表现为准等向性，而在高场区显著偏离准等向性，同时未牺牲QI场的输运特性。这种偏离使得在保持输运性质的同时，更容易实现线圈优化与集成。","scd":null,"kp":[]},{"i":43018,"as":"一种结合标准半导体加工与确定性坍塌策略的新平台，能够使分子形成纯净且自对准的界面。","scd":null,"kp":[]},{"i":43019,"as":"“大气河流”是维持生态系统和区域水文的长距离水汽流动优先通道。研究分析了南美洲大气河流的排水分区模式，开发出一种数学方法来识别水汽排放曲线的转折点。越过该转折点后，上风向水汽贡献强度急剧下降。该方法提供了客观划定关键上风向流域的标准，揭示了其空间范围在大陆上的显著差异，并将大陆大气河流系统划分为源头型等四种主要排水类型。","scd":null,"kp":[]},{"i":43020,"as":"“昆明-蒙特利尔全球生物多样性框架”设定了2030年保护全球30%陆地面积的目标。研究评估了不同治理机制对2005至2021年间秘鲁亚马逊地区森林砍伐及相关碳排放的影响。结果发现，全球其他有效基于区域的保护措施（OECMs）承受的人类压力高于严格保护区，而与较不严格的保护区水平相似。","scd":null,"kp":[]},{"i":43021,"as":"研究利用429个台站20年的远震P波转换为S波接收函数，绘制了加拿大西部下方410公里和660公里深度地震界面图。在由俯冲的复活/法拉龙脊系统形成的板片窗下方，发现了地幔过渡带温度存在100-300 K的异常。这一温度异常分布与板片窗几何形状一致，为下地幔通过板片窗向上涌流并向下地幔提供热量提供了地震学证据。","scd":null,"kp":[]},{"i":43022,"as":"研究结合众包开源数据和全球气候灾害模型，评估了约1700万个全球移动基站在历史及未来气候情景下面临的风险。结果显示，在2050年RCP8.5情景下，0.1%概率的热带气旋事件将影响约370万个基站，造成42.2亿美元的直接损失。到2080年，同等极端事件造成的破坏将进一步加剧。","scd":null,"kp":[]},{"i":43023,"as":"研究通过地貌测绘和暴露测年等技术，重建了罗斯海早至中全新世的风暴波浪活动。结果表明，在约8000至5000年前，海冰减少和更强的海气耦合作用引发了多次高能风暴。典型风暴的浪高为1-3米，极端事件浪高可达4-9米，这些风暴搬运了巨石并形成了最高达海拔29米的滩脊。","scd":null,"kp":[]},{"i":43024,"as":"范德华晶体MoOCl2在室温下表现出从椭圆到双曲色散的内在拓扑转变。无需经过人工制造或结构化，该材料即可实现固有的等离子体通道效应。这种内在的物理转变使得等离子体能够以无衍射的射束形式传播，实现了光在亚波长尺度的定向路由与高度限制。","scd":null,"kp":[]},{"i":43025,"as":"为解决分子与现有半导体制造工艺不兼容的挑战，研究人员提出了一种自组装触点策略。该策略首先利用标准工艺制造器件结构，随后通过表面工程相互作用，形成与分子自对准的纯净界面。基于此方法成功制造了超过1000个电活性金属-分子-金属器件，良率高达99%，并在运行中表现出高稳定性。","scd":null,"kp":[]},{"i":43026,"as":"研究探讨了启发式推理和动机推理过程与减排潜力估计的关系。基于三项共包含2924名参与者的预注册研究，结果表明低至中等影响的气候行动比高影响行动被更广泛地采纳，且人们对不同行动减排差异的认知不足。研究指出，这种“碳能力”的匮乏与心理障碍有关，并评估了相关纠正性干预措施的效果。","scd":null,"kp":[]},{"i":43027,"as":"Gasdermin D（GSDMD）孔道会引发细胞焦亡。研究描述了一类共价半胱天冬酶抑制剂，它们无法穿透健康细胞膜，但能通过GSDMD孔道进入细胞，从而选择性地阻断细胞焦亡和白介素-1β分泌，同时不影响半胱天冬酶驱动的细胞凋亡。这类抑制剂通过GSDMD介导的递送机制成功实现了对细胞膜破裂的预防。","scd":null,"kp":[]},{"i":43028,"as":"","scd":null,"kp":[]},{"i":43029,"as":"在小鼠血液疾病模型中，镰状细胞疾病被证实与干细胞过早衰老有关。研究进一步表明，使用一种药物组合能够有效恢复患有该疾病小鼠的干细胞功能。","scd":null,"kp":[]},{"i":43030,"as":"金星陡峭的裂谷谷地可能是该行星持续进行地质构造活动的证据。这一地质特征的发现为探讨金星地质动力学本质提供了新视角。","scd":null,"kp":[]},{"i":43031,"as":"核动力商船虽然具有低排放优势，但同时引入了其他形式的危险。因此，推进此类船舶计划必须制定明确的法规以应对和规避相关风险。","scd":null,"kp":[]},{"i":43032,"as":"双特异性抗体能够同时结合两个靶点，展现出了直接打击肿瘤的潜力。目前，这类抗癌抗体正大量进入临床应用，并进一步推动了更复杂抗体版本的研发。","scd":null,"kp":[]},{"i":43033,"as":"针对实验室环境中难以保持专注的普遍问题，注意力研究人员提供了一系列有科学依据的实用建议，以帮助科研人员避免分心、提高专注度。","scd":null,"kp":[]},{"i":43034,"as":"代写及胁迫引用的“评审工厂”在学术出版界引发了激烈的冲突。这一现象不仅破坏了同行评审的公正性，也使得处于事件中间环节的正当科研人员遭受负面影响。","scd":null,"kp":[]},{"i":43035,"as":"美国白宫提出了一项由政治任命人员负责管理科研资助的改革方案。目前，部分立法者正试图通过努力，暂时中止这一面临争议的科学资助全面改革计划。","scd":null,"kp":[]},{"i":43036,"as":"关于寄生和共生关系的书籍揭示了地球上生命之间奇特的联系，展现了不同物种生命交织的奇妙方式，激发人们对支配地球生命秘密关系的惊奇感。","scd":null,"kp":[]},{"i":43037,"as":"采用科学实验的方法对待每一次人工智能提示词输入，能够促使使用者将输出结果视为待验证的科学结论，从而提升结果质量。文中为此提供了十条操作建议。","scd":null,"kp":[]},{"i":43038,"as":"蛭形轮虫具有极强的抗干燥和抗冰冻能力。研究从轮虫体内鉴定出一种电压门控质子通道异构体ArHv2。与同源物ArHv1和人体Hv1不同，ArHv2在负电位下即可激活。这一独特的机制特征使其在细胞面临冷冻或代谢应激时，能够实现快速且高效的质子外排或内流，从而维持极端环境下的pH稳态。","scd":null,"kp":[]},{"i":43039,"as":"电子器件微缩化使计算能效受限于界面传输过程。研究指出，通过工程化设计电子材料界面，可有效控制开关状态、电荷与热量传输及器件可靠性。文章探讨了界面设计在逻辑器件、存储器、互连导线和热管理系统中的应用，并明确提出了界面设计在预测性建模方面的需求。","scd":null,"kp":[]},{"i":43040,"as":"研究汇编了青藏高原五个生态系统九种生境的3373个样本数据。超过94%的分类单元出现在至少两个生态系统中，气溶胶为冰川微生物群提供种子，冰川作为汇集处、过滤器和 relay 将微生物输送至河流、湖泊和土壤。年降水量对细菌丰富度和群落独特性的影响比温度更显著。","scd":null,"kp":[]},{"i":43041,"as":"研究将铜单原子与超小缺氧氧化钴簇负载在聚碳氮化物上，构建了电子相邻的氧化还原活性位点，用于耦合光催化二氧化碳还原与5-羟甲基糠醛氧化反应。该催化剂生成CO和HMFCA的速率分别达49.6和34.7 μmol g⁻¹ h⁻¹，选择性分别为91.6%和81.6%，实现了碳基燃料与高附加值化学品的协同高效生产。","scd":null,"kp":[]},{"i":43042,"as":"","scd":null,"kp":[]},{"i":43043,"as":"研究开发了一种环丙亚胺介导的铜催化自由基环化方法，成功在温和条件下合成了C3位带有全碳季碳中心的3,3-二取代羟吲哚。机理实验证实，催化过程通过平衡C-X键的氧化断裂反应，解决了叔烷基卤化物在单催化周期内难以进行多重氧化还原的挑战。","scd":null,"kp":[]},{"i":43044,"as":"","scd":null,"kp":[]},{"i":43045,"as":"","scd":null,"kp":[]},{"i":43046,"as":"研究设计并合成了带有明确负电荷空腔的原子级精确Co4簇光催化剂。该负电荷空腔能够在一锅法连续C-P偶联反应中有效稳定阳离子中间体，从而高效调节活性中间体的形成与释放，实现了多种重要磷化物的高效、高选择性环保光催化合成。","scd":null,"kp":[]},{"i":43047,"as":"研究提出了一种将促进植物-微生物有益互作（BMA）的性状育种与富集微生物的土壤管理相结合的综合框架。该框架结合了先进育种技术与微生物精准生产接种策略，旨在减少对农药和化肥的依赖，构建更具韧性和高产量的农业系统。","scd":null,"kp":[]},{"i":43048,"as":"研究报道了零维Pb-In双金属卤化物，在340 nm激发下产生518 nm的绿色发光，光致发光量子产率高达96.4%。引入Sb3+掺杂后，材料可实现多色发射与可逆热致变色。该多金属晶体平台成功克服了相分离问题，并整合了多种发光功能。","scd":null,"kp":[]},{"i":43049,"as":"研究人员采用MOF模板和静电纺丝技术，设计了嵌入CuOx/TiO2的中空八面体氮掺杂碳纳米纤维(CuOx/TiO2@NCFs)，用于室温下ppb级H2传感，以预警锂离子电池热失控。DFT计算证实异质结发生电荷转移，电子从TiO2向CuO大量迁移，降低载流子复合率并显著增强TiO2表面吸附H2的能力。","scd":null,"kp":[]},{"i":43050,"as":"研究通过溶剂模板辅助蒸发诱导相分离法，将热致变色微胶囊整合到定制醋酸纤维素多孔网络中，构建了基于纤维素的分层多孔膜。该材料不仅通过产生广泛米氏散射位点最大化太阳反射率，还集成了温度自适应和超疏水自清洁功能，有效解决了被动辐射制冷中过度制冷和户外污染难题。","scd":null,"kp":[]},{"i":43051,"as":"研究开发了一种液晶（LC）修饰石墨烯的界面工程策略来制备芳纶复合薄膜。多环芳香液晶通过强π-π相互作用锚定在石墨烯上，改善了二者的界面相容性且不破坏石墨烯晶格。该界面修饰有效抑制了界面热阻，大幅提升了材料的热导率，满足高功率电子设备对散热材料的严苛要求。","scd":null,"kp":[]},{"i":43052,"as":"研究探讨了酵母菌在含糖脂Ohmline的支持脂质双分子层上的黏附机理。结合石英晶体微天平与界面流变学表征，证实细胞黏附经历两个动力学阶段：初始阶段由静电相互作用主导，其特征时间与膜zeta电位直接相关；该发现解析了软膜界面处作用力与界面动力学之间的复杂机制。","scd":null,"kp":[]},{"i":43053,"as":"研究提出将2-氟苯-1,3-二甲酸引入钙钛矿太阳能电池自组装单分子层空穴传输层。利用该分子的高偶极矩有效对齐了能级，降低了电荷传输势垒，同时改善了表面润湿性并减少了界面电子不均匀性。该界面工程策略显著提升了钙钛矿太阳能电池的光电转换性能。","scd":null,"kp":[]},{"i":43054,"as":"研究以PM6/L8-BO体系为基础，建立了本体异质结、逐层处理和准平面异质结模型器件。通过定量对比这些结构中给受体有效界面面积对激子重组的影响，揭示了逐层处理活性层独特的电荷重组特征，为有机太阳能电池中激子分离与抑制重组的机制提供了深入理解。","scd":null,"kp":[]},{"i":43055,"as":"本文由Zi-Qiang Zhao等人撰写，发表于《Physics Letters B》（在线发布于2026年8月3日）。主要探讨了通过猝灭动力学在超临界区域发生的非平衡态交叉现象与物理机制。","scd":null,"kp":[]},{"i":43056,"as":"研究开发了一种表面修饰有pH响应性门控分子的介孔二氧化硅纳米载体。该系统在生理pH下保持封闭，在细菌糖代谢产生的酸性微环境中迅速释放广谱抗菌药物。在人类口腔微生物组模型中，该纳米颗粒被酸源性细菌的代谢酸化直接激活，实现对产酸细菌的选择性根除。","scd":null,"kp":[]},{"i":43057,"as":"研究开发了一种新型近红外发光荧光粉CaLaMgTaO6:Cr3+。在470 nm激发下，该材料在815 nm处表现出强发射峰，内量子效率高达63.1%，半峰宽为171 nm，且在378 K下发射强度保持60%。通过将其涂覆在450 nm LED芯片上制成的近红外灯已证实具有实际多场景应用潜力。","scd":null,"kp":[]},{"i":43058,"as":"研究提出一种多价Ti(III)/Ti(IV)与过渡金属离子（Cu、Fe、Co）共掺杂策略，用于改性钠离子电池P2型层状氧化物正极材料Na0.67MnO2。该协同氧化还原活性环境有效缓解了材料循环过程中的姜-泰勒效应及高压相变，同步提升了正极的结构稳定性与初始容量。","scd":null,"kp":[]},{"i":43059,"as":"研究通过透明质酸（HA）基质调节Fe3+和单宁酸（TA）的生物矿化并装载博来霉素（BLM），开发出多功能纳米平台。该纳米组件通过HA-LYVE-1相互作用特异性靶向淋巴内皮细胞，集成了光声成像引导、靶向递送与协同光热-硬化疗法，有效克服了淋巴管畸形临床治疗的局限性。","scd":null,"kp":[]},{"i":43060,"as":"研究采用Rb+/Sb3+共掺杂策略构建了高稳定性的无铅卤化物钙钛矿微晶。Sb3+取代增强了电子-声子耦合并促进自陷激子形成，而Rb+则调节自陷激子弛豫动力学并抑制辐射复合。该电子结构与激子动力学的协同耦合调控，显著提升了光催化析氢反应的效率。","scd":null,"kp":[]},{"i":43061,"as":"研究通过用甲基丙烯酸酐改性猪皮提取的明胶引入碳碳双键，结合静电纺丝与紫外辐射交联技术，制备出具有三维网络结构的超轻明胶纳米纤维。该材料结合银纳米线作为压阻应变传感器，集成了柔性、压阻效应与摩擦电自供电传感功能，为可降解可穿戴设备提供了环保解决方案。","scd":null,"kp":[]},{"i":43062,"as":"本研究提出了一种合成简单且模块化的超分子策略，将超支化双-MPA聚酯与含不同链段的咪唑碘鎓离子液体结合，制备出纳米结构的离子液晶电解质。树状边缘的羟基与咪唑阳离子间的氢键作用生成了超分子组装体。该聚合物液晶电解质能够形成有序的离子传输路径，同时保持良好的加工性和热稳定性，在电化学能量转换和存储器件中具有应用潜力。","scd":null,"kp":[]},{"i":43063,"as":"水气界面间巨大的阻抗失配严重限制了声波的高效传输。受充气包装材料启发，本研究提出一种基于封装气泡的声学超表面以增强水气界面的声传输。研究人员通过数值模拟系统分析了气泡尺寸、间距、高度及与界面的距离对声传输性能的影响。模拟结果表明，该封装气泡超表面能够有效克服传统共振气泡的稳定性限制，显著提升跨界面的透射声能峰值。","scd":null,"kp":[]},{"i":43064,"as":"针对动脉粥样硬化中活性氧(ROS)过度积累和巨噬细胞驱动的炎症问题，研究人员构建了一种多功能脂质体纳米平台。该平台具备巨噬细胞主动靶向能力及微环境响应释放特性，能够协同调节NF-κB和Nrf2信号通路。其核心在于合成了DSPE-PEG-Rhein修饰物，显著提升了药物的溶解度。该靶向纳米策略有效克服了常规药物生物利用度低和脱靶毒性的缺陷。","scd":null,"kp":[]},{"i":43065,"as":"为了提升p型Bi0.4Sb1.6Te3薄膜的热电性能，本研究结合厚度诱导织构与缺陷工程策略。采用碲补偿磁控溅射技术，随厚度从500增至800纳米，(00l)取向因子从0.17提升至0.39，为空穴传输提供了低散射通道。同时，碲补偿有效调节了载流子浓度，提高了塞贝克系数。此外，致密的网络结构也有效优化了多晶薄膜中的电热输运解耦，满足了微型热电器件的技术创新需求。","scd":null,"kp":[]},{"i":43066,"as":"本研究开发了一种在多功能氧化物-沸石催化剂上进行的精准耦合反应路径，实现二氧化碳向高附加值芳香族化合物均四甲苯(1,2,4,5-四甲苯)的高选择性转化。利用原位红外光谱、俄歇电子能谱等结合理论计算，揭示了详细的反应路径。研究开发了具有四方InZrOx固溶体结构的最佳氧化物催化剂，其热力学特性完美匹配二氧化碳转化为芳烃的反应过程。","scd":null,"kp":[]},{"i":43067,"as":"高温极易引发非辐射跃迁，导致有机磷光严重热猝灭。本研究引入脱水-收缩策略，将磷光体逐渐锚定在含水硼酸钠的离子网络中，获得了具有极端温度耐受性的掺杂有机磷光系统。该系统在室温和573 K下均展现出400至680纳米的高效磷光。其在室温下磷光量子产率高达81.2%，寿命达1.64秒，并在573 K高温下能持续稳定工作至少6个月。","scd":null,"kp":[]},{"i":43068,"as":"本研究建立了一种由辐射诱导的硫亚胺“裁剪”反应。在辐射作用下，硫亚胺被定量分解为吩噻嗪和胺类，辐射分解产率高达270.9 nM/Gy，创下纪录。该反应的高效性和高选择性归因于对水合电子和羟基自由基这两种主要辐射活性物质的近乎百分之百的利用。该裁剪反应展现出广泛的底物适用范围和极快的反应动力学。","scd":null,"kp":[]},{"i":43069,"as":"溶出技术能从金属氧化物中实现金属纳米颗粒的可控固态析出，显著提升材料的电化学催化性能。通过对特定钙钛矿体系进行系列原位电子显微镜、同步辐射X射线衍射和热重实验，研究解构了随热激活增加而出现的多个析出阶段：1) 表面锚定纳米颗粒的轻微析出；2) 体相内部颗粒析出；3) 体相及表面颗粒的扩散与聚结。这揭示了复杂的析出机制。","scd":null,"kp":[]},{"i":43070,"as":"为了提高光控药物治疗的组织选择性并克服传统紫外光穿透深度有限的缺陷，本研究开发了两种基于钌(II)多吡啶基的复合物作为光笼化激酶抑制剂。通过π共轭工程，这些复合物能够在深红光（660纳米）照射下，实现配位伊马替尼的清洁光致释放。在BCR-ABL阳性白血病细胞中，该类复合物表现出极低的暗毒性，并在光照下释放药物表现出显著的光毒性。","scd":null,"kp":[]},{"i":43071,"as":"1,2-二氧杂环丁烷的热化学发光通常由O-O键断裂引发。然而第一性原理模拟表明，1,2-二氧杂环丁烷的机械化学触发分解对传统的O-O键断裂路径并不敏感。相反，施加的机械力稳定了热力学上无法实现的C-C键断裂路径，当作用力超过临界值（约1.8-3.0 nN）时，该力诱导的C-C断裂路径在能量上变得最有利，从而激活了休眠的化学发光途径。","scd":null,"kp":[]},{"i":43072,"as":"为了定量指导肝外mRNA载体的结构设计，本研究开发了单组分主链离子化聚合物平台。通过将聚（β-氨基酯）（PβAE）上的叔胺转化为季铵盐，构建了包含90种变体的离子化PβAE（iPβAE）库。体内筛选揭示了定量构效关系（QSAR）以及差异化离子化梯度诱导的局部结构重排机制。该平台阐明了载体与mRNA的微观界面相互作用，为精准肝外表达提供了理想模型。","scd":null,"kp":[]},{"i":43073,"as":"为了克服Cr(III)光敏剂可见光吸收差的缺陷，研究人员制备了一系列在菲绕啉核的4、7位带有芳基乙炔单元的同源Cr(III)络合物。该修饰使得配体内π-π*跃迁发生超过1 eV的红移，显著增强了在UVA及蓝绿光区域的吸收（ε约25,000-100,000 M–1 cm–1），超越了传统的金属到配体电荷转移（MLCT）光敏剂，且未对2E配体场发射能量产生明显影响。","scd":null,"kp":[]},{"i":43074,"as":"组胺化是一种新兴的蛋白质翻译后修饰，由转谷氨酰胺酶2（TGM2）催化，通过形成异肽键将组胺共价结合到谷氨酰胺残基上。由于缺乏靶向组胺化谷氨酰胺的高效泛特异性抗体，细胞内组胺化蛋白质组的鉴定一直受限。本研究利用化学蛋白质组学技术成功分析了癌细胞中的组胺化蛋白质组，首次揭示了核心组蛋白上未被发现的表观遗传标记。","scd":null,"kp":[]},{"i":43075,"as":"针对聚甲基丙烯酸甲酯（PMMA）全碳骨架难以在温和条件下降解的挑战，本研究开发了一种由氢原子转移（HAT）引发的热驱动解聚策略。该策略使用简单的过氧化氢物（如TBHP和CHP）作为自由基前体，无需光激活、特殊的链端修饰或氯代溶剂。在高温下产生的氧中心自由基能促使未修饰的商业聚甲基丙烯酸酯发生解聚，极大地提升了化学回收的实用性。","scd":null,"kp":[]},{"i":43076,"as":"为了探究层状范德华磁性材料MnPSe3在实验中易于实现的半金属性，本研究合成了吡咯烷鎓插层的MnPSe3晶体。研究明确了该材料中存在倾斜的反铁磁基态，而非先前争议的单层本征铁磁性。该基态源于直接的锰-锰反铁磁竞争与插层有机离子引起的电荷转移挫败效应的联合作用。研究结果解决了关于有机离子插层MnPSe3磁态的长期争议。","scd":null,"kp":[]},{"i":43077,"as":"为了提升钙钛矿光伏电池的性能，本研究引入了长链配体与少量短链配体互补的混合配体共组装策略。该共组装结构促进了具有良好界面能带排列的纯相二维(n=2)钙钛矿层的形成，有效促进了电荷提取。这一混合配体策略实现了对钙钛矿表面及晶界缺陷的有效钝化，全面抑制了非辐射复合，为高效钙钛矿太阳能电池的界面钝伏提供了新方案。","scd":null,"kp":[]},{"i":43078,"as":"研究阐明了非共价链间相互作用如何决定范德华纳米管内pnictogen chalcogenides (Pn2Ch)单链的封装行为。由于重主族元素的孤对电子效应易引发电子的局域化或离域化及竞争性亚稳态多晶型物的形成，实现低维材料的精确控制极具挑战。本研究确立了基于Pn2Ch组成的封装行为依赖性，为理解和控制接近原子尺度的一维材料的纳米级形态和物理性质提供了基础。","scd":null,"kp":[]},{"i":43079,"as":"本研究提出了一种由硫脲和铜协同作用的绿色电催化策略，实现了在高电流密度下将硝基苯高选择性还原为苯基羟胺（PHA）。在硫脲与铜的界面上形成了动态的“质子-电子缓冲层”，有效抑制了过度还原为苯胺的热力学副反应。该工艺表现卓越，法拉第效率达到95%，PHA产率高达90%，解决了PHA由于自身不稳定而难以高选择性合成的难题。","scd":null,"kp":[]},{"i":43080,"as":"γ-NaAsSe2 (γ-NAS) 具有极高的二次谐波产生(SHG)敏感性（约590 pm/V），但极易受潮降解。为解决这一难题，研究采用稀释的软阳离子锚定策略：在As位进行Sb取代以稳定极性γ框架，并在Na位引入稀散Ag取代。Ag取代形成了更强的亲硫族Ag-Se接触，在不破坏电子结构的情况下显著增强了抗湿性，成功在保持巨大中红外非线性光学性能的同时提升了材料的长期稳定性。","scd":null,"kp":[]},{"i":43081,"as":"聚己内酯（PCL）的疏水表面易引发血栓和细菌黏附。为提升其血液相容性，本研究开发了一种多功能共载药涂层系统。该系统在PCL基材内部掺入一氧化氮（NO）供体SNAP以提供持续的血小板抑制和抗菌活性，并在表面涂覆载有抗血小板药物替格瑞洛（TIC）的亲水性聚氨酯涂层以形成抗污界面。该集成涂层系统有效改善了血液接触医疗器械表面的血液相容性。","scd":null,"kp":[]},{"i":43082,"as":"本研究开发了一种电-化学-力学相场模型，用于探究固态锂金属电池中由电子泄漏和机械应力共同驱动的锂枝晶成核与生长。该模型动态捕捉了由晶界电子泄漏及双轴压力引发的体相和界面枝晶的完整演化过程，并引入了平均成核等定量指标，系统阐明了电子泄漏与机械应力对体相锂枝晶演化的耦合调控机制。","scd":null,"kp":[]},{"i":43083,"as":"研究揭示了一种由耐药质粒编码的双功能蛋白AcrIE10在调控CRISPR-Cas免疫中维持动态平衡的机制。AcrIE10通过其Acr结构域直接结合Cas7*亚基来抑制CRISPR免疫，同时利用其N末端RHH结构域特异性识别启动子中的反向重复序列，发挥Aca蛋白作用并自抑制转录。AcrIE10的二聚化对其双功能调控至关重要，此机制介导了质粒与CRISPR-Cas系统的稳定共存。","scd":null,"kp":[]},{"i":43084,"as":"研究组装了苦皮草染色体级别的单倍型分辨参考基因组，揭示其约3430万年前发生的全基因组三倍化事件以及倍半萜合酶基因的扩增机制。研究鉴定出γ-桉叶醇合酶，并解析了苦皮素V中二氢-β-沉香呋喃骨架的生物合成途径，为该生物农药的异源生产奠定了基础。","scd":null,"kp":[]},{"i":43085,"as":"研究发现母体代谢应激通过保守的代谢途径改变后代肠道上皮细胞组成。生殖细胞代谢障碍耗尽成熟卵母细胞中的NAD+，重编程后代氧化还原代谢并损害蛋氨酸循环。该代谢变化降低了Notch配体Delta的蛋白质水平，从而破坏肠道干细胞微环境信号传导，改变后代肠道生理。在昆虫和哺乳动物模型中均证实，母体代谢状况对后代的代谢与肠道生理具有保守影响。","scd":null,"kp":[]},{"i":43086,"as":"研究利用2.3埃分辨率的冷冻电镜技术，解析了大肠杆菌免疫传感器Avs2识别噬菌体末端酶的结构基础。结构显示EcAvs2形成一个平坦的C4对称四聚体，每个原聚体结合一个末端酶单体。这种末端酶的识别是由EcAvs2中一个具有大形状互补性的结合口袋介导的，揭示了原核生物通过直接结合噬菌体蛋白以启动程序性细胞死亡的防御策略机制。","scd":null,"kp":[]},{"i":43087,"as":"研究通过结构、生化和生物信息学方法，解析了人类Paired-like同源结构域转录因子如何通过协同结合间距为3个碱基对的回文位点（P3位点）来获得DNA结合特异性。研究定义了11条规则，明确了在同源结构域中对P3位点的协同结合起关键、允许和抑制作用的特定残基，并成功利用这些规则改变了协同结合特性。","scd":null,"kp":[]},{"i":43088,"as":"研究开发了一种结合人工智能与机器人实验的闭环自动化酶工程平台（REAP）。该平台核心采用混合损失函数RankReg，联合优化排序保真度与定量准确性，直接从实验反馈中进行自适应的闭环学习。该排序回归框架使得REAP能够有效跨越催化中心和以往未充分探索的区域，精准识别功能热点，从而显著加速酶的催化工程改造。","scd":null,"kp":[]},{"i":43089,"as":"研究通过对1031名终末期肾病(ESRD)病例和704名对照进行大规模两阶段全表观基因组关联分析，鉴定出52个差异甲基化CpG位点。这些位点在多种原发性肾脏疾病中表现出一致关联，涉及144个富含炎症和免疫通路的候选基因。研究证实，其中5个位点与ESRD并发症相关，7个位点与早期慢性肾病肾功能下降有关。","scd":null,"kp":[]},{"i":43090,"as":"","scd":null,"kp":[]},{"i":43091,"as":"研究构建了Ru/WO3/NF异质结构用于节能制氢，通过调控界面OH-动力学加速碱性条件下的肼脱氢。亲水性WO3作为OH-缓冲层，重新分配羟基物种，为N2H4吸附和活化创造有利的微环境。实验与理论证实，该策略在400 mA cm-2电流密度下将肼氧化电位降至0.11 V，塔菲尔斜率为26 mV dec-1，并在200 mA cm-2下稳定运行120小时。","scd":null,"kp":[]},{"i":43092,"as":"研究利用可再生棉织物与由聚乙烯醇骨架、半导体填料及铝滑动层构建的自愈合、可回收摩擦层，制备出可持续的直流摩擦伏特纳米发电机(TVNG)。基于可逆的动态氢键，该器件展现出长达延长寿命的功能特性，其最大开路电压为1.08 V，峰值电流为0.72 mA，为解决电子废弃物问题和可持续机械能收集提供了有效方案。","scd":null,"kp":[]},{"i":43093,"as":"研究揭示了一项控制虚时纠缠动力学的普适非平衡标度规律。通过大尺度量子蒙特卡洛模拟验证，证明在二维量子临界点中，角纠缠随虚时呈现对数增长，且其系数完全由普适类决定。该理论框架成功提取并解析了二维量子物质中编码共形场论本质特征的亚主导角项纠缠，为刻画高维量子物质纠缠特性提供了关键方法。","scd":null,"kp":[]},{"i":43094,"as":"研究提出一种原子界面工程策略，在钼铜氧化物上原位组装六乙炔基苯，形成sp杂化的Mo/Cu-C≡C异质界面。该界面的双d轨道杂化使N-O键减弱36.85%、活化能垒降低0.43 eV，可逆电子缓冲促进了质子耦合电子转移，并有效抑制析氢反应。该催化剂利用可再生电力将硝酸盐废水高效、高选择性地转化为绿色氨气。","scd":null,"kp":[]},{"i":43095,"as":"研究通过金属配体法构建了含有混合价态Fe2+/Fe3+簇的氢键有机框架（HOF-FJU-200）。利用光-热-质子耦合策略，将光热转化产生的热能激活羧酸中的质子解离，解决了光催化产过氧化氢过程中的非辐射能量损失和质子-电子动力学失衡问题。该材料的光吸收拓展至近红外二区（约2500 nm），实现了高效的过氧化氢光合成。","scd":null,"kp":[]},{"i":43096,"as":"研究开发了一种由纤维素和聚甲基丙烯酸甲酯组成的水触发型超分子聚合物。在水的诱导下，可拉伸的超分子网络转化为致密交联域，使材料的拉伸强度从2.7 MPa显著提升至61.7 MPa（提升超22倍），弯曲强度达97 MPa。该聚合物在-196°C至200°C范围内保持结构完整，并可在海水及表面活性剂废水等多种介质中实现规模化成型和加固。","scd":null,"kp":[]},{"i":43097,"as":"研究揭示了单层NbTe2中晶格、电荷和自旋自由度协同表现出的手性交织现象。实空间原子结构分析表明，NbTe2的√19 × √19相表现出交替手性原子位移与电荷密度序，重构晶胞内包含两个相反手性的手性单元。自旋极化扫描隧道显微镜证实，在整个原胞中分布着由该电荷密度波诱发的自旋极化纹理。","scd":null,"kp":[]},{"i":43098,"as":"研究基于双光子Hong-Ou-Mandel干涉构建了大规模全连接量子网络。通过集成孤子微梳(SMC)和光子编码芯片，实现了大规模并行频率生成与锁定、高可见度HOM干涉以及测量设备无关(MDI)量子密钥分发。该网络架构在不信任网络提供商的情况下仍能保障用户间通信安全，实现了跨越200公里的全连接量子网络。","scd":null,"kp":[]},{"i":43099,"as":"","scd":null,"kp":[]},{"i":43100,"as":"研究提出一种匹配阴极-阳极局部pH值的偶联合成策略，实现甲酰胺的近100%碳氮选择性电化学合成。采用自支撑Cu纳米片阵列（碱性共还原）和覆盖Pt的Ti片（中性共氧化）分别作为阴极和阳极，将副产物作为另一电极的原料，从而避免了水裂解副反应，在阴极和阳极同时高效制备甲酰胺。","scd":null,"kp":[]},{"i":43101,"as":"研究提出一种集成非易失性显示-照明系统(INDIS)，基于透明氧化铟锡(ITO)浮栅存储器(FGM)器件单片集成Micro-LED架构实现双模运行。每个像素仅用一个FGM和独立栅极控制器实现像素级寻址，无需持续刷新即可保留图像图案。该架构有效解决了微显示器在大面积均匀照明与低功耗精细图像显示之间的高效切换难题。","scd":null,"kp":[]},{"i":43102,"as":"受彩色海胆棘的生长启发，研究展示了无定形碳酸钙(ACC)结晶的变色调制机制。天然红色素萘醌(NZ)在矿物形成过程中的pH变化下发生去质子化，并稳定于碳酸钙-混合色素中，在结晶时呈现薰衣草蓝至紫蓝色。去质子化的NZ对ACC的形成和结晶影响极小，通过局部溶解过程实现了生物矿化的颜色控制。","scd":null,"kp":[]},{"i":43103,"as":"研究通过高分辨率交叉分子束散射成像与量子动力学计算证实，在2.90 kcal mol-1碰撞能下，单一分波形状共振控制了F + HD → HF + D反应。该共振源于过渡态后区域中寿命约50飞秒的准束缚D-HF(v'=3, L = 21)复合物。这导致HF(v'=3, j'=1)产物通道在全散射角范围内表现出持续振荡，揭示了角动量势垒后反应物短暂捕获的量子共振效应。","scd":null,"kp":[]},{"i":43104,"as":"该研究提出了一种在大型单室囊泡中进行化学燃料驱动的分子货物主动运输策略。通过在脂质-液体支撑膜和仿生囊泡中的实验，研究展示了双酸货物的跨膜主动运输，并量化了该系统的关键性能指标。这种主动运输机制能够产生高达约0.3个pH单位的跨膜pH梯度，与驱动ATP合成所需的梯度相当。","scd":null,"kp":[]},{"i":43105,"as":"研究提出一种分子级金属有机配位调控策略，通过抑制前驱体溶液中交联网络的形成，促进溶剂去除、均匀硒化和结晶。该策略成功实现了10平方厘米面积上高度均匀的刀片涂布薄膜制备。最终，1平方厘米的太阳能电池实现了14.2%的认证效率，10.5平方厘米的太阳能组件实现了13.0%的认证效率，大幅推进了环保的CZTSSe太阳能电池规模化应用。","scd":null,"kp":[]},{"i":43106,"as":"研究探讨了晶体结构与器件性能的关系，特别是在高电流注入下蓝色准二维Ruddlesden-Popper钙钛矿发光二极管的效率下降问题。通过时间与强度依赖的光学表征以及电学和热稳定性分析，研究发现具有较少无机层的准二维钙钛矿具有更大的效率衰减，且此现象与间隔阳离子种类无关。此外，研究还考察了俄歇复合等因素对效率衰减的贡献。","scd":null,"kp":[]},{"i":43107,"as":"研究提出一种失配辅助微观结构工程策略，以改善近室温热电材料硒化银（Ag2Se）的性能。通过在Ag2Se颗粒中引入多阴离子ZnSe复合物，并在相变过程中形成ZnSe纳米析出物、界面和局部应变场。ZnSe与Ag2Se的晶格失配及离子尺寸差异放大了相变诱导的形变，产生了高密度位错，从而抑制了晶粒长大，去除了多余的银，限制了银间隙原子的形成。","scd":null,"kp":[]},{"i":43108,"as":"研究开发了一种具有分层异构结构的高熵合金。该合金结合了双峰核壳晶粒、纳米析出相以及氧化物颗粒，这些结构在高达1000°C的高温下依然保持稳定。在测试中，该合金在高应变率载荷条件下展现出2.2 GPa的屈服强度，同时未牺牲其抗冲击韧性，兼具优异的耐热与抗冲击性能。","scd":null,"kp":[]},{"i":43109,"as":"研究提出了EEG-FM-Compass，旨在对现有的脑电图（EEG）基础模型进行全面基准测试和公平比较。研究首先回顾了55个代表性模型，并将它们的设计选择（包括数据标准化、模型架构和自监督预训练策略）整理成统一的分类框架。随后，研究在跨越九项大脑任务的13个EEG数据集上，对12个开源基础模型及基线模型进行了下游任务评估。","scd":null,"kp":[]},{"i":43110,"as":"研究提出了一种对比蛋白质语言模型CLSS（Contrastive Learning Sequence–Structure）。该模型采用自监督方式进行训练，将蛋白质的序列和结构信息进行联合嵌入，以全面表示蛋白质的相关性。CLSS能够表征完整蛋白质结构域的结构和序列，有效解决了无关联序列可能具有相似结构，或相似序列呈现不同结构所带来的复杂性，为绘制已知蛋白质空间的全局关系提供了新方法。","scd":null,"kp":[]},{"i":43111,"as":"研究开发了一种深度学习架构，利用14,748名认知正常参与者的T1加权MRI数据，在体素级别估算局部脑年龄（LBA）。全局脑年龄将衰老简化为单一数值，而该深度学习模型通过映射脑衰老的空间差异，能够揭示解剖结构退化的局部模式。这种方法有助于识别在阿尔茨海默病发病前隐藏的认知脆弱区域特征。","scd":null,"kp":[]},{"i":43112,"as":"研究利用湖泊沉积物记录、历史文献和高分辨率气候再分析数据，重建了过去500年长江流域的洪水变化历史。结果表明，在小冰期（约1500-1850年）洪水频率达到峰值，这主要是由西太平洋副热带高压减弱、热带辐合带南移以及西南季风增强等气候因素驱动。研究强调了工程和土地利用在加剧气候驱动型长江洪水灾害中的重要作用。","scd":null,"kp":[]},{"i":43113,"as":"研究利用湖泊沉积物记录、历史文献和高分辨率气候再分析数据，重建了长江500年来的洪水变化史。结果显示，小冰期时期洪水频率达到峰值，这是由西太平洋副热带高压减弱、热带辐合带南移以及西南季风增强等气候因素驱动的。","scd":null,"kp":[]},{"i":43114,"as":"研究设计了一种名为HI12的TCR模拟双特异性单链双抗体，能够识别由HLA-A*02:01呈递的保守Pol衍生肽。在HLA匹配的HIV感染人源化小鼠中，早期抗逆转录病毒治疗期间给予HI12具有良好的耐受性，能激活CD8+ T细胞并加速血浆病毒衰减。该治疗使淋巴结和脾脏CD4+ T细胞中完整和总前病毒DNA减少了3至8倍，显著清除了病毒库并延缓了病毒反弹。","scd":null,"kp":[]},{"i":43115,"as":"研究开发了一个结合疾病动态模拟与最优控制的通用框架，用于确定平衡感染和缓解成本的传染病缓解策略。研究发现三个显著效应：首先，在假设基本传染数（R0）恒定的情况下，最优应对措施通常具有“全有或全无”特征，具体取决于疾病的严重程度，即采取严格的缓解措施或完全不干预。","scd":null,"kp":[]},{"i":43116,"as":"研究发现转录因子SIX1对维持成年小鼠耳蜗感觉上皮的结构和功能以及听觉功能至关重要。在年轻成年小鼠的支持细胞（SCs）或毛细胞（HCs）中条件性敲除Six1会导致严重的耳聋。SC特异性敲除会破坏上皮组织并导致HC退化，而HC特异性缺失会导致静纤毛束缺陷。这表明SIX1在出生后的听觉感觉上皮稳态中具有关键作用。","scd":null,"kp":[]},{"i":43117,"as":"研究界定了能够识别并分离抗肿瘤CD4+ T细胞的最佳细胞表面蛋白标志物。通过对人癌症中抗肿瘤新抗原特异性CD4+肿瘤浸润淋巴细胞的转录组状态及相应细胞表面标志物的分析，研究确定了细胞表面ADGRG1和CD86的表达。这些标志物可用于抗肿瘤CD4+ T细胞的活性分离和选择性富集，为过继性细胞治疗提供了优化策略。","scd":null,"kp":[]},{"i":43118,"as":"","scd":null,"kp":[]},{"i":43119,"as":"","scd":null,"kp":[]},{"i":43120,"as":"研究利用线粒体基因组、全基因组和杂交捕获数据，构建了已知夏威夷蜜旋鸟的全面系统发育树。这些鸟类是从单一祖先演化出的典型适应辐射物种。历史上曾有超过60种，但目前仅存17个类群，其中只有两种被列为“无危”。研究不仅覆盖了历史已知物种，还将已知仅存的古生物学标本纳入系统发育分析，揭示了人类介导的物种灭绝危机及系统发育组学多样性的丧失。","scd":null,"kp":[]},{"i":43121,"as":"","scd":null,"kp":[]},{"i":43122,"as":"研究揭示了CIP2A-TOPBP1复合物和PP2A在调节有丝分裂DNA双链断裂（DSB）中Polθ的招募和磷酸化的动态机制。CIP2A-TOPBP1复合物被招募至DSB位点，与Polθ直接相互作用并将其共招募至染色质。CIP2A通过抑制PP2A维持Polθ的磷酸化，延长其在染色质上的保留时间以确保修复。修复完成后，复合物解离，PP2A使Polθ去磷酸化并释放。CIP2A的缺失会损害肿瘤生长。","scd":null,"kp":[]},{"i":43123,"as":"研究分析了1,689对母婴样本中的776个母亲暴露组变量和胎粪微生物群，构建了连接母亲暴露、新生儿微生物群与10种婴儿结局的网络。研究确定母亲人体测量和临床指标是婴儿发育的关键预测因子，特定代谢和化学暴露是影响微生物群组成的主要因素。母亲体内的胆固醇、磷酸三苯酯等代谢物和环境化学物质的暴露，与婴儿生长、湿疹和神经发育相关。","scd":null,"kp":[]},{"i":43124,"as":"研究确定胸苷激酶1（TK1）是骨关节炎（OA）的致病调节因子，其将炎症应激与代谢重编程和细胞外基质降解联系起来。机制上，IL-1β通过促进TK1在Cys153位点的S-棕榈酰化，抑制其蛋白酶体降解，导致TK1积累。稳定的TK1增强JNK信号传导，驱动过度糖酵解并加速基质分解。相反，去棕榈酰化酶PPT1可去稳定化TK1，为OA治疗提供了潜在靶点。","scd":null,"kp":[]},{"i":43125,"as":"研究开发了一种进化模型，用于预测电压门控钙通道孔形成Cav1.3亚基中残基的致病潜力。该模型再现了已知的功能区域，并在单氨基酸分辨率上前瞻性地识别出新的功能位点。对预测位点的电生理分析证实了这些位点在调节通道电压依赖性门控和动力学方面的功能，为解析与神经发育疾病相关的未知功能残基提供了有效方法。","scd":null,"kp":[]},{"i":43126,"as":"研究将MasSpec Pen（MSPen）技术改进为模块化系统（Mod-MSPen），用于口腔鳞状细胞癌（OCSCC）的无创分子检测。该系统由控制器和一次性手持设备组成，通过直接接触组织并使用温和的液体提取分子进行体内分析。这为替代主观的视觉检查和耗时的有痛活检，提供了一种易于获取、非侵入性的OCSCC临床检测平台。","scd":null,"kp":[]},{"i":43127,"as":"","scd":null,"kp":[]},{"i":43128,"as":"研究证明了在退化适应度景观上的进化动力学并非随机，而是由曲率驱动的方向性漂移。利用最小模型研究表明，在最优适应度流形上，随机突变-选择动力学会诱导方向性漂移，朝向曲率减小的区域移动。这种漂移是由种群变异性与景观曲率之间的相互作用引起的，即使在适应度梯度消失时，进化探索仍然会受到偏向性影响。","scd":null,"kp":[]},{"i":43129,"as":"研究开发了一种高性能、超柔性铟镓锌氧化物（IGZO）电解质门控晶体管（EGT）。该器件采用垂直结构和纳米级沟道长度，克服了传统金属氧化物EGT中沟道缩小与双电层（EDL）电容之间的基本权衡限制。研究系统分析了IGZO与电极接触面积、IGZO厚度及半导体-电极界面等几何参数对电学性能和EDL电容的影响，揭示了垂直结构如何解耦沟道，从而显著提升器件跨导和其他电学指标，在低功耗生物传感器和神经形态电子学领域具有应用潜力。","scd":null,"kp":[]},{"i":43130,"as":"","scd":null,"kp":[]},{"i":43131,"as":"研究利用质谱技术系统鉴定了肠道病毒71型（EV-A71）感染期间与病毒基因组RNA结合的374种宿主蛋白。分析发现Matrin 3（MATR3）与肠道病毒广泛关联。功能验证实验证实MATR3是一种促病毒因子。研究进一步揭示，MATR3通过ZDHHC20介导的棕榈酰化作用来稳定病毒RNA，从而促进EV-A71的复制。该研究阐明了EV-A71与宿主因子相互作用以调控病毒复制的具体分子机制。","scd":null,"kp":[]},{"i":43132,"as":"冰川因其基岩的高效侵蚀在塑造地貌中发挥关键作用。传统测量冰川侵蚀率的方法通常依赖沉积物产量的间接测量，其中可能包含重新悬浮的沉积物和非冰川侵蚀源，难以准确反映冰川侵蚀的真实贡献。为克服这一局限，该研究采用了一种替代性指标：宇宙成因核素测量，以此来探究冰川侵蚀过程并验证控制冰川侵蚀率的因素，从而更准确地理解冰川侵蚀对地貌演化及气候、侵蚀与构造之间反馈机制的影响。","scd":null,"kp":[]},{"i":43133,"as":"膀胱由复杂的神经网络支配，负责调控尿液存储和排空。除了感知张力的牵张敏感性传入神经外，膀胱黏膜中还存在对牵张不敏感的传入神经。为明确其功能，研究人员利用膀胱内灌注树胶脂毒素建立了一种选择性膀胱黏膜传入神经去神经支配的小鼠模型。该模型评估了黏膜去神经支配对健康小鼠感觉神经活动和膀胱功能的具体影响，揭示了这类神经纤维在健康和疾病状态下对膀胱感觉、病原体清除及整体功能的作用。","scd":null,"kp":[]},{"i":43134,"as":"核仁是核糖体生物合成的主要场所，在肝细胞癌（HCC）中发挥重要作用。研究发现，核仁蛋白KRI1在HCC组织中异常过表达，并通过相分离与核磷蛋白1（NPM1）相互作用，维持核仁结构和核糖体生物合成。KRI1的相分离作用受其N端内含无序区中三个丝氨酸残基（S94、S95和S97）磷酸化的增强。下调KRI1表达会破坏核仁结构并抑制核糖体生成，从而显著削弱HCC细胞增殖并增加细胞凋亡。","scd":null,"kp":[]},{"i":43135,"as":"传统碳纳米管（CNT）的生产高度依赖高耗能的碳氢化合物化学气相沉积法。尽管将二氧化碳（CO2）作为碳源是一种可持续的替代路线，但直接将CO2转化为CNT在热力学上是不利的，且通常只能产生无定形碳。为此，研究提出了一种串联电化学-热化学（EC-TC）策略来克服这些热力学限制。该策略首先对CO2进行电化学处理，随后通过热化学反应成功将其转化为碳纳米管。","scd":null,"kp":[]},{"i":43136,"as":"","scd":null,"kp":[]},{"i":43137,"as":"","scd":null,"kp":[]},{"i":43138,"as":"","scd":null,"kp":[]},{"i":43139,"as":"","scd":null,"kp":[]},{"i":43140,"as":"","scd":null,"kp":[]},{"i":43141,"as":"","scd":null,"kp":[]},{"i":43142,"as":"","scd":null,"kp":[]},{"i":43143,"as":"在早期遗传系统中，DNA选择胸腺嘧啶而非尿嘧啶的现象在光稳定性方面存在矛盾，因为胸腺嘧啶对早期地球强烈的紫外线辐射造成的损伤更为敏感。研究在受控的265纳米紫外线照射下，利用稳态吸收、荧光和拉曼光谱对两者的光化学行为和损伤动力学进行了定量比较。结果表明，胸腺嘧啶本质上比尿嘧啶更具光反应性，其光损伤速率更快，吸收带更宽且与原始UVC光谱重叠更多。该实验结果直接揭示了胸腺嘧啶在紫外线光损伤方面的具体特性。","scd":null,"kp":[]},{"i":43144,"as":"非经典炎性小体是先天免疫系统中引发炎症级联反应的高分子量复合物，仅由脂多糖（LPS）和人类caspase-4/5（或小鼠caspase-11）两种成分组成。尽管结构相对简单，但其详细结构此前尚未被阐明。该研究测定了非经典炎性小体的化学计量，揭示了其具有高度异质性的动态结构。研究发现，该复合物主要由三种共存的组分构成。这一发现填补了非经典炎性小体结构研究的空白。","scd":null,"kp":[]},{"i":43145,"as":"传统人工肺系统严重依赖中空纤维膜（HFM）束，其气体交换受限于异质流动分布和易引发血栓的血液-材料界面。研究提出了一种基于三周期极小曲面（TPMS）的架构驱动设计框架。通过增材制造技术构建的TPMS膜形成连续的三维结构，能够同时调节灌注路径、扩散界面及血液-材料相互作用。计算流体力学和多物理场传输模拟表明，膜厚度、晶胞尺寸和三维架构的耦合效应共同决定了该系统的气体交换效率。","scd":null,"kp":[]},{"i":43146,"as":"为使机器人在危险化学品泄漏事故中快速识别泄漏液体的化学成分、温度及动态行为，研究设计了一款柔性掌状液敏电子皮肤（PSLSES）。该电子皮肤采用柔性印刷电路技术制造，包含128个金属电极并涂有氟化乙烯丙烯（FEP）薄膜。通过捕获液滴轨迹上的局部摩擦电信号，该系统能够实现多模态动态液体感知，同步完成液体成分识别、温度传感以及基于可视化轨迹图案的液滴运动追踪。","scd":null,"kp":[]},{"i":43147,"as":"针对青光眼治疗中缺乏精确眼压（IOP）管理和原位剂量验证的问题，研究开发了一种无线智能治疗隐形眼镜（SCL）。该系统集成了电压触发的快速药物递送系统和实时剂量监测传感器。其电子交织设计采用超薄（17.4微米）的三叉指结构，使电场与载药水凝胶在同一空间内相互作用。通过频率匹配策略增强电压耦合，驱动载有酒石酸溴莫尼定的水凝胶，在20分钟内实现水溶液中的高药物浓度。","scd":null,"kp":[]},{"i":43148,"as":"为克服多步电化学过程中的级联动力学瓶颈，研究定制了一种轴向取向、硫桥接的异原子结构（Ru─S─Co）以实现碱性析氢反应（HER）的全局协同调控。在该结构中，顶部的钌原子用于增强水分子的捕获能力，而晶格底部插入的钴原子激活了中间的硫原子，从而平衡了氢的吸附与解吸过程。这种定制的多位点协同作用显著降低了决速步水分解的能量壁垒，提高了界面上活性自由水的比例。","scd":null,"kp":[]},{"i":43149,"as":"嵌入硼/氮的多环骨架在有机发光二极管（OLED）中因结合了窄带发射和热活化延迟荧光而备受关注。然而，实验获取具有锯齿状硼/氮排列的高阶多共振框架仍具挑战。研究采用位点可编程的逐步硼化策略，成功构建了具有锯齿状硼/氮排列的三硼DABNA扩展框架（L-DABNA-TriB）。理论与实验结合的研究揭示了从单硼到三硼的渐进线性扩展，能够实现近简并的单重态-三重态能级，从而制备出具有低效率滚降的高性能非敏化OLEDs。","scd":null,"kp":[]},{"i":43150,"as":"高分辨率原子力显微镜（AFM）测量发现，当探针扫描被二维材料覆盖的单体台阶时，摩擦力会出现反常的双峰特征。通过高分辨率粘滑测量、纳米压痕实验和分子动力学模拟，证实这种分叉的摩擦响应源于探针在台阶前端和后端发生瞬态钉扎时，阻力与驱动力的异步演化。这种双峰摩擦机制为解决摩擦学中不可避免的台阶相关挑战提供了新视角。","scd":null,"kp":[]},{"i":43151,"as":"传统颗粒光催化系统因无序的电荷迁移和不可控的气泡产生等传质限制，严重阻碍了光催化制氢效率。为解决这一问题，研究提出了一种用于大规模光化学制氢的新型传质策略。该策略通过构建隧道结光化学二极管，利用聚结诱导跳跃机制实现了超快氢气泡脱附，有效克服了固有的传输限制。研究通过合理设计，实现了约100%验证的微型盆结构，确保了系统高效的传质能力和卓越的运行稳定性。","scd":null,"kp":[]},{"i":43152,"as":"针对将功能活性物质精准递送至特定植物器官的难题，研究提出了一种生长素功能化纳米载体策略，使工程化材料能够接入植物内源性长距离转运途径。纳米载体的尺寸被调整为约55纳米以限制内吞作用并促进细胞外定位，同时其表面引入生长素基序。这种设计建立了一个以细胞外为主的界面，劫持了极性生长素转运途径，使PIN介导的物质流增强，并伴随PIN1上调10.42倍，实现了跨越厘米级的定向叶到根运输。","scd":null,"kp":[]},{"i":43153,"as":"研究探讨了具有恒定R矩阵的相互作用副粒子链，其哈密顿量对副粒子的内部自由度（即味）求和。针对这类“味盲”哈密顿量，研究证明希尔伯特空间可以一般性地分解为占据部分和味部分，且哈密顿量具有特定的性质。该文章发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43154,"as":"通过两项实验，展示了一个用于捕获、分选和引导振动能量的极具前景的物理平台，成功实现了弹性平面朗道彩虹的可视化。该研究为微纳尺度声子或振动能量的精确操控提供了实验基础和平台支撑。该文章发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43155,"as":"密度修正密度泛函理论（DC-DFT）旨在探讨Kohn-Sham计算中自洽密度是否能产生最佳能量。在分子计算取得成功的基础上，研究将DC-DFT应用于使用Hartree-Fock（HF）密度的固态计算。该研究解决了固态计算中的关键难题，证明了DC-DFT方法在固体材料和体系中的有效性。该文章发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43156,"as":"三能级系统因具备二能级系统所没有的量子干涉效应，在量子光学中至关重要。研究探讨了Λ型三能级系统与由光学近场整形的自由电子之间的相干相互作用。通过将电子列车视为特定的量子探针，实现了对三能级系统的相干控制。该研究为利用自由电子操控量子系统提供了新途径。该文章发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43157,"as":"在具有偶极相互作用的二维Rashba自旋轨道耦合玻色-爱因斯坦凝聚体中，前期通过平均场和变分理论预测了量子准晶的存在。然而，目前科学界对这种准晶态的超流体特性及其稳定性（例如对抗热熔化等）的认知依然非常有限。本文针对该量子准晶态的热力学性质与熔化机制进行了深入探讨，填补了该量子态相关物理特性研究的空白。发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43158,"as":"通过一项基于全局量子色动力学（QCD）拟合的概念验证研究，科研人员在质子内部发现了夸克-胶子-夸克干涉现象。研究结论表明，这种干涉效应的大小与极化夸克密度的贡献相当。这一重要发现证实了质子具有比此前预设更加显著的量子力学本质特征。相关成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43159,"as":"研究人员利用射电源数据对全局宇宙双折射效应的限制进行了测量分析。该研究结合了射电基本星表（RFC）在2.7至15 GHz频段范围内的数据以及宇宙透镜全天巡天数据，精确测量了射电源在天球上的位置角（PA）与偏振位置角（PPA）之间的差异。该工作为宇宙双折射现象提供了观测界限与数据支撑。发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43160,"as":"本研究利用电信C波段单发射极光源，成功实现了一种基于诱骗态的量子密钥分发方案。该方案通过对量子发射体的光激发进行调制以改变光子数分布，从而产生所需的诱骗态。基于现有的安全分析框架，研究团队在227公里的距离上完成了量子密钥分发。该成果展示了一种扩展安全通信距离的有效技术途径。发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43161,"as":"玻色子编码是实现容错量子计算的重要途径，但现有的Floquet协议通常依赖包含数千个驱动周期的缓慢绝热爬坡来进行解析构造。为突破这一计算瓶颈，本研究引入了一种解析方法，利用量子晶格门实现了玻色子编码的单周期Floquet控制。该技术显著缩短了构建玻色子编码所需的驱动周期数。发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43162,"as":"高保真量子门是构建可扩展量子计算的核心组件。在极短的时间内，短时间尺度的波形畸变会破坏控制脉冲的时间反射对称性，导致循环演化无法精确闭合，这使得传统对称协议难以实现高保真度。本研究通过引入循环控制方法，成功克服了快速CZ门在速度与保真度之间的相互制约，实现了高速且高保真的量子门操作。发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43163,"as":"量子退火在解决组合优化问题时的性能，主要受限于系统在量子相变时遇到的最小能隙（Δ）。本研究利用投影量子蒙特卡洛方法，系统考察了两种典型的量子自旋玻璃模型（二维和三维）中Δ随系统尺寸N的标度关系。研究揭示了最小能隙随系统尺寸演化的物理规律，为评估量子退火的计算性能提供了关键的理论基准。发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43164,"as":"分数化激发是识别拓扑量子自旋液体态的关键，而其与涌现规范场的耦合使得动力学研究变得极具挑战性。本研究聚焦于量子Kagome冰模型中的自旋子激发，详细分析了自旋子与自身产生的涌现规范场之间的相互作用。研究发现，这种涌现规范场会导致显著的自旋子能带平坦化效应，深刻揭示了系统内独特的多体相互作用机制。发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43165,"as":"LHCb合作组利用质子-质子对撞数据，对B̄0→K̄*0μ+μ−衰变中的CP破坏现象进行了搜寻与分析。实验数据来自LHCb第一期和第二期运行，对应的总积分亮度为8.4 fb⁻¹。研究重点分析了该衰变道中局部和非局部振幅的CP破坏情况，为粒子物理学中的标准模型精确测试及相关对称性破缺机制提供了重要的实验测量结果。发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43166,"as":"本文开发了一个针对极化自旋1靶的半举深度非弹性散射的理论框架。在该研究的第一部分中，研究团队推导并给出了半举散射截面的普遍形式以及相关的自旋观测量表达式。该理论框架被具体应用于带有旁观者核子标记的极化氘核散射过程分析中。这项工作为极化核子靶的散射实验提供了坚实的理论基础与计算工具。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43167,"as":"本研究系统对比了质子-氘核弹性散射过程中的非相对论与相对论核子-核子（NN）势。传统NN势（如CDBonn、AV18、Nijmegen）主要基于非相对论薛定谔方程，而Kharkiv势则具有内在的相对论特性。研究通过Faddeev计算方法，详细评估了不同势能模型在描述质子-氘核散射行为时的差异与表现。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43168,"as":"在相互作用玻色子模型（IBM）框架下，本研究通过对内禀相干态进行角动量投影，对过渡核的几何特性进行了深入分析。研究结果表明，在计算过程中K混合效应通常可以忽略不计，从而验证了使用K固定投影方法的合理性与准确性。这一结论为简化过渡原子核四极形变的理论计算提供了重要依据。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43169,"as":"研究团队通过将神经网络变分蒙特卡洛框架（FeynmanNet）与连续特征向量方法相结合，开发出一种用于从头计算原子核基态性质的高效模拟器。该计算模型能够在极小的计算资源开销下，精确计算出不同哈密顿量下的各种物理可观测量。这项技术显著提升了原子核基态性质的理论计算效率。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43170,"as":"利用58Ni(64Zn, 1α3p)核反应，并结合JUROGAM 3伽马射线探测器阵列与MARA反冲质量分离器，研究人员对极缺中子的115I原子核进行了高精度的实验测量。研究不仅对原有已知的能带进行了大幅修正与扩展，还首次完整确定了该原子核中低自旋单粒子激发态的能级信息，并揭示了这些激发态向带终止态演化的物理规律。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43171,"as":"质子放射性是探索质子滴线外原子核单粒子结构的灵敏探针。然而，由于对核结构效应的近似处理，现有的全球半衰期模型精度受限。本研究基于转移矩阵方法系统分析了质子放射性，发现引入依赖于微观能量（Emic）的质子预形成因子可以显著优化对半衰期的全局描述。该成果提升了理论模型对滴线外核结构性质预测的准确性。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43172,"as":"本研究针对104,102Cd和104Sn束流开展了中子敲除反应实验，成功在剩余核103,101Cd和103Sn中激发了状态，其中包括具有νg7/2特性的低能7/2+态。这些态的半衰期约为400皮秒。该实验测量为研究100Sn同位素区附近的l禁戒M1跃迁强度提供了关键的实验数据支撑。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43173,"as":"在核子+价核子的物理图像下，研究团队运用耦合通道伽莫夫壳模型（GSM-CC），对13O(p,p)和14O(p,p)弹性散射反应进行了系统的理论计算。研究在该统一理论框架内，详细探讨了弱束缚原子核的结构特性与散射性质之间的相互关联。该工作展示了伽莫夫壳模型在处理质子 Rich 核散射问题上的应用价值。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43174,"as":"通过基于反应道选择的伽马射线能谱学技术，本研究详细调查了60Cu原子核的高自旋态。实验数据来源于三次使用相同熔合蒸发反应且束流能量相近的实验，探测系统结合了Gammasphere伽马射线谱仪与Microball探测器。研究结果不仅精确确定了60Cu的高自旋能级结构，还为深入理解其镜像核60Ga的相应状态提供了重要的物理推论依据。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43175,"as":"ALICE合作组在质子-质子对撞质心能量为5.02 TeV的条件下，对中心快度区域内的（多）奇异粒子产生率和横动量分布进行了精确测量。研究重点分析了奇异粒子产额随带电粒子多重数变化的依赖关系。该实验结果为理解小系统碰撞中奇异度增强的物理机制以及强相互作用物质的演化规律提供了重要数据。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43176,"as":"本文系统研究了重离子碰撞中粒子横动量谱的标度特性。研究涵盖了质心能量从7.7到200 GeV不等的金核-金核碰撞以及能量为193 GeV的铀核-铀核碰撞系统。通过对π介子、K介子和质子的横动量谱进行详细分析，研究团队破译了不同粒子和不同碰撞系统中横动量谱所遵循的普适标度规律，为重离子碰撞的动力学机制提供了新见解。发表于《物理评论C》。","scd":null,"kp":[]},{"i":43177,"as":"孤立量子系统的演化不可避免地会表现出回归现象，即系统状态在有限时间后会回到初始状态附近。本研究为封闭量子系统的回归时间建立了严格的上限边界，填补了该基本物理现象在定量理解上的空白。该成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43178,"as":"传统微游动物理论常忽略鞭毛和纤毛搏动的时间动力学。本研究通过显式引入粗粒化为正弦表面滑移速度的异时波，研究了空间限制对纤毛运动的影响。研究表明，引入此机制能够揭示微游动物在受限环境下的全新运动动力学特征。","scd":null,"kp":[]},{"i":43179,"as":"研究指出，在具有局部相互作用和有限在位希尔伯特空间维度的晶格系统中，任何精确的U(1)高阶对称性的存在对幺正动力学下的遍历性构成了基本阻碍。以二维系统为研究重点，论证了高阶对称性是如何从根本上破坏系统遍历性的。","scd":null,"kp":[]},{"i":43180,"as":"两项最新实验展示了利用片上声子晶体捕获、分拣和引导振动能量的极具前景的平台。该技术被形象地称为“捕获彩虹”，为在微纳尺度上实现声学/振动能量的精确操控与定向引导提供了创新的物理机制与实验依据。","scd":null,"kp":[]},{"i":43181,"as":"转化型FeF3正极在固态电池中具有超高能量密度，但面临反应动力学迟缓与界面不稳定的问题。本研究通过1,3-二氧戊环的原位开环聚合，设计了富氟NaBiF4@Bi2O3催化剂引发的聚合物电解质。NaBiF4引发聚合并作为氟库，Bi2O3调节氟环境，成功实现了首个安时级FeF3固态电池。","scd":null,"kp":[]},{"i":43182,"as":"长效发光材料在光数据存储和生物成像领域极具潜力，但实现持续时间的精确调控仍具挑战。本研究通过在Cs2NaScCl6:Sb3+中进行精细的缺陷工程，特别是通过调节合成过程中盐酸的用量来控制Na相关缺陷的形成，成功开发出由体温激活的高效三色超长长效发光策略，可用于便捷的信息加密与存储。","scd":null,"kp":[]},{"i":43183,"as":"为突破碱性水析氢中缓慢的Volmer步骤瓶颈，本研究开发了一种表面微环境工程催化剂。通过将原子级分散的铱原子选择性装饰在钌纳米颗粒上，形成电子耦合的Ir-O-Ru界面。密度泛函理论计算揭示，该界面存在协同氢溢流机制，正极化的Ir-O微环境促进了氢气的生成，实现了安培级的高效析氢。","scd":null,"kp":[]},{"i":43184,"as":"针对直接空气碳捕集(DAC)中材料再生需要近饱和湿度的问题，本研究开发了被动昼夜湿度摆动水凝胶(PDMHs)。这种季铵化工程水凝胶能够在亚饱和相对湿度条件下实现再生并释放CO2，有效拓宽了被动碳捕集的气候窗口，降低了水资源管理需求，助力净零排放。","scd":null,"kp":[]},{"i":43185,"as":"多晶型材料为调控分子传感特性提供了平台。研究证实，不同WO3多晶型体在丙酮传感中表现出差异。其核心机制在于，吸附物诱导的电荷能够有效耦合到与电子输运相关的能态中。这一发现揭示了多晶型特异性电子转导在气体传感中的关键作用。","scd":null,"kp":[]},{"i":43186,"as":"作为一种刚性压电晶体的替代方案，研究人员开发出一种基于聚合物的柔性透明介电声学谐振器贴片。该贴片能够将电共振转化为兆赫兹级别的超声波，可紧密贴合生物表面。实验表明，该贴片能够有效促进伤口愈合与组织再生。","scd":null,"kp":[]},{"i":43187,"as":"针对单组分电子传输层(ETL)难以同时实现高效率与高稳定性的问题，本研究将多金属氧酸盐(POM)掺杂入混合ETL中应用于有机太阳能电池。该策略实现了级联能级排列、提高电导率及增强电极附着力，使器件获得20.4%的出色光电转换效率，并展现出卓越的长期稳定性。","scd":null,"kp":[]},{"i":43188,"as":"利用荧光显微镜对细胞膜片的研究发现，细胞质膜在空间分布上具有高度异质性。大多数蛋白质聚集在富含蛋白质的结构域中，中间被贫蛋白质区域分隔。这些结构特征在脱离细胞骨架的质膜衍生囊泡中依然得以保留，且不同脂质和蛋白质进入富蛋白域的倾向各不相同。","scd":null,"kp":[]},{"i":43189,"as":"为应对偏远地区抗微生物药物耐药性(AMR)监测难题，研究团队在加拉帕戈斯群岛部署了移动实验室。对受生活污水污染的海洋站点进行现场宏基因组测序，结果显示其微生物群落发生显著改变，AMR基因数量远高于未污染水域，表明人类污水污染正驱动该海洋生态系统中多重耐药菌的出现。","scd":null,"kp":[]},{"i":43190,"as":"研究评估了印度农业系统的作物重组路径。结果表明，以氮元素为核心的作物重组策略能使氮素过剩量减少13.4%，用水量减少18.6%，温室气体排放降低8.7%，同时维持了基准卡路里产量。相比以水为核心的策略，该策略的协同效益高出约4.6倍，使氮污染相关的社会环境成本大幅降低。","scd":null,"kp":[]},{"i":43191,"as":"南极半岛冰架崩解的主要诱因是强烈的表面融化和融水积聚。基于1979至2023年区域气候模式数据分析，研究指出，自20世纪90年代初以来的长期融化下降趋势已经发生逆转。热力学因素主导了这一变化，近年来11月至2月期间的地表融化率以每年3%的显著速度急剧增加。","scd":null,"kp":[]},{"i":43192,"as":"针对死亡率极高的急性肺损伤(ALI)，研究人员开发了一种具有K-N4位点的钾基单原子催化剂(K-SAC)。该催化剂利用人体细胞内最丰富的金属钾构建，展现出极强的超氧化物歧化酶和过氧化氢酶样活性。它能够被巨噬细胞优先摄取并清除活性氧，抑制巨噬细胞焦亡，从而实现对小鼠急性肺损伤的有效免疫治疗。","scd":null,"kp":[]},{"i":43193,"as":"通过对圣托里尼破火山口约3500年沉积物序列的地球化学和宏基因组分析，研究揭示了一个延续约1100年的古热液系统。数据显示，在两次大喷发之间的2270年窗口期内，热液活动强烈，沉积物中的砷、汞等微量金属富集度高出背景值最高达200倍，其长期金属通量与现代大型热液系统相当。","scd":null,"kp":[]},{"i":43194,"as":"研究通过碳氧稳定同位素记录，对显生宙以来的气候-碳系统进行了基于状态演化的描述。系统演化被划分为5个持久的大气候状态，其间伴随着急剧的跃迁。分析表明，这些气候-碳状态体制的转换期，与显生宙生物圈脆弱性的显著升高在时间上高度吻合。","scd":null,"kp":[]},{"i":43195,"as":"研究提出并实验演示了一种基于里德堡系综的按需微波-光量子转换器。利用级联电磁诱导透明技术，将微波光子存储在高激发集体态中并在检索时转化为光子。在无谐振腔条件下，该转换器实现了约90%的面积归一化存储效率、2.3 MHz带宽以及26 K的噪声等效温度，成功集成量子存储与转换功能。","scd":null,"kp":[]},{"i":43196,"as":"传统环状碳酸酯工业合成依赖高耗能热催化及昂贵反应物。本研究开发了一类多功能金属有机框架光催化剂(RE-BTTD-AC)，集成了氧气活化、C-H键活化、光热转换和路易斯酸反应性。该催化剂利用乙烯/丙烯、二氧化碳和氧气，在环境条件下实现了碳酸乙烯酯和碳酸丙烯酯的高效绿色光合成。","scd":null,"kp":[]},{"i":43197,"as":"该研究提出了一种通过改变表面官能团来调节第一类多孔液体（PLs）粘度的策略。研究人员合成了一系列星形多孔液体，将软聚合物链与具有不同表面基团（无取代基、羟基、叔丁基或十二烷氧基）的铑金属有机多面体配位。研究发现，多面体表面的官能团会显著影响聚合物链的构象，从而导致不同的流变行为和孔隙可及性，为解决多孔液体粘度与孔隙体积之间的矛盾提供了方法。","scd":null,"kp":[]},{"i":43198,"as":"研究利用三维拉格朗日热量收支模型追踪了2013-2016年东北太平洋海洋热浪。三维粒子轨迹将其分为南北两个运动学起源不同的部分。量化分析表明，平流作用而非表面强迫在维持热浪的热含量方面起主导作用。北部组成部分由埃克曼热量输送的减弱来维持。该研究揭示了海气耦合相互作用在驱动和维持极端海洋变暖事件中的核心机制。","scd":null,"kp":[]},{"i":43199,"as":"针对水系锌离子电池中层状VOPO4框架在充放电循环时因晶格应力累积导致的结构退化问题，研究人员提出了部分金属取代策略。以锰取代的VOPO4为概念验证，理论和实验证明该改性缩短了沿c轴的M-O键，并形成了Mn-O-P-O-V离域结构。这种各向异性介导的应力调节有效缓解了循环引起的晶格应力，从而显著延长了电池的循环寿命。","scd":null,"kp":[]},{"i":43200,"as":"为解决传统射频信号处理依赖数字转换导致硬件复杂和功耗增加的问题，研究人员提出了一种基于时空编码超表面的可编程射频计算系统。该系统通过控制波与物质的相互作用，以可重编程的方式在电磁空间内实现射频计算。具体而言，傅里叶变换和卷积等基本信号操作直接在电磁波域中执行，避免了数字域转换的限制，为下一代电子系统提供了新组件。","scd":null,"kp":[]},{"i":43201,"as":"氟仿具有低成本、低毒性和温室气体转化潜力，是理想的三氟甲基来源。然而，直接从氟仿中获取三氟甲基自由基一直难以实现。该研究开发了一种在光照射下利用酮反应性并结合布朗斯台德碱的方法，成功实现了自由基三氟甲基化。该过程通过光激发的烷氧化物中间体，在无需外部添加剂的条件下从氟仿中产生三氟甲基自由基，为合成重要的医药化合物提供了新途径。","scd":null,"kp":[]},{"i":43202,"as":"聚合物玻璃中表面诱导的迁移率增强可以传播至纳米甚至微米尺度。研究发现了包含纳米外层和微米亚层的“双层”移动表面结构。通过动态力学分析（DMA）和粗粒度模拟，研究证实了纳米层迁移率增强与微米亚层厚度之间存在强对应关系，且两者均随聚合物玻璃的内在脆性增加而增加。表面分子速度的增强引发了长程剪切场，揭示了表面迁移率与内在脆性之间的物理联系。","scd":null,"kp":[]},{"i":43203,"as":"为实现合成气高选择性转化为乙醇，研究人员利用配位前驱体策略，在氮配位碳载体上构建了具有可调局部架构的钌双原子催化剂。钌-钌原子间距与配位环境、电子耦合共同调控了一氧化碳和氢气的活化以及碳碳键的形成。改变原子间距离可以调节几何限域和电子相互作用，从而提高乙醇生成速率。在最优反应窗口内，该催化剂展现出了优异的催化性能。","scd":null,"kp":[]},{"i":43204,"as":"该研究对美国各电力和工业部门小型模块化反应堆（SMR）的部署潜力进行了大规模定量评估。结果表明，在《通胀削减法案》氢气生产税收抵免政策到期前（2033年），将SMR部署于氨、钢铁和炼油行业的工业氢气生产最具经济吸引力。在享受税收抵免且为首次建设成本的情况下，可部署91吉瓦电力的SMR并获得高内部收益率，而单纯用于发电则不具备经济性。","scd":null,"kp":[]},{"i":43205,"as":"研究首次实现了全光纤随机克尔光频梳，这是随机激光器的光谱合成模拟器件。该光频梳基于调制不稳定性实现同时参量放大和时间幅度压缩，并在半开腔内通过瑞利散射提供的分布式随机反馈辅助下，生成孤子序列并对其进行进一步压缩。这种新型光频梳无需传统的锁模激光器或微环谐振腔，为电磁频谱的相干合成提供了一种新方法。","scd":null,"kp":[]},{"i":43206,"as":"富锂锰基层状氧化物正极材料因氧氧化还原的不可逆性和气体释放而难以应用。研究结合X射线光谱、电子显微镜和原位质谱等技术发现，外加电压窗口直接决定了氧氧化还原的可逆性。通过优化电位窗口（相对于石墨为4.3-2.0 V），可将氧化还原反应限制在可逆范围内，同时确保完全还原，最大程度减少了气体释放，从而显著提升了电池的长期稳定性。","scd":null,"kp":[]},{"i":43207,"as":"受树叶保角生长特性的启发，该研究为超材料设计建立了一种物理-几何对偶性。这种对偶性允许直接从物理等效推导出的材料参数和场中求出几何变换。由此产生的扩散超材料表现出一种独特性质：尽管热导率具有强烈的各向异性和非均匀性，但其等温线和热流线保持相互正交。这一特性有效降低了自由形态超材料在全向性能需求下对复杂制造的依赖。","scd":null,"kp":[]},{"i":43208,"as":"","scd":null,"kp":[]},{"i":43209,"as":"该研究首次将手性N-杂环卡宾（NHCs）薄膜应用于电子自旋过滤。NHCs是一类具有电子可调性的小有机分子，能共价结合金属表面形成稳定的自组装单分子层。实验制备了(S,S)-SINpEt和(R,R)-SINpEt手性NHC薄膜并沉积在Au-Ni表面上。结果显示，尽管这些分子尺寸较小，但依然表现出极高的自旋选择性，并在金属表面上保持极高的稳定性，揭示了分子结构与自旋选择性之间的联系。","scd":null,"kp":[]},{"i":43210,"as":"研究报道了三种基于葫芦脲的同网状金属有机框架（CUST-Fe, CUST-Co, CUST-Ni），由中性葫芦[6]脲轮烷配体、阴离子磺酸盐-对苯二甲酸盐配体和二价过渡金属离子构成。这些MOFs沿c轴具有一维功能性亚纳米通道，赋予了其卓越的质子传输能力，展现出作为质子交换膜燃料电池（PEMFCs）固体导体的巨大潜力，解决了大环分子基MOFs在质子导电领域应用不足的问题。","scd":null,"kp":[]},{"i":43211,"as":"研究发现在模拟太阳光照射下，由六铌酸阴离子单层络合的3.2纳米金红石型SnO2纳米晶，能够仅利用水将二氧化碳选择性还原为一氧化碳。莫特-肖特基分析表明其能带符合典型金红石SnO2特征。这种配合物产生的价带向纳米晶表面的界面电荷转移激活了无机配体，构建了类似于多组分固态光催化剂的自包含体系，在光催化中免除了牺牲试剂的使用。","scd":null,"kp":[]},{"i":43212,"as":"该研究实现了白藜芦醇二聚体laetevirenol A和异蛇葡萄素D的全合成。合成策略利用芳炔固有的反应性，将其引入亚甲基茚满/茚核中。具体通过脱氢狄尔斯-阿尔德环加成反应和芳炔-烯反应构建目标分子的碳骨架。此外，研究结合经验和计算方法，成功解释了关键苯炔反应中出人意料的区域选择性，突破了分子间周环芳炔反应的区域选择性限制。","scd":null,"kp":[]},{"i":43213,"as":"研究展示了具有不同成分和尺寸的双嵌段共聚物纳米粒子在方解石晶体生长过程中能够发生自发分拣。这种纳米粒子模拟蛋白质特性，被包裹在生长的晶体内部后，选择性地定位在不同的结晶域中，形成具有可编程成分和空间组织的仿生复合材料。结合原位监测技术和原子力显微镜分析，证实了界面化学决定了纳米颗粒在仿生物矿化结晶过程中的自分拣行为。","scd":null,"kp":[]},{"i":43214,"as":"针对气-液-固催化反应中气体溶解度低和传质受限的问题，研究表明困在疏水催化剂表面的气层（气膜）能显著富集局部气体浓度。以金-钯催化剂直接合成过氧化氢为模型，疏水有机硅上的氢气/空气气膜在无需低温、高压或醇助溶剂的条件下，使反应速率提升了20倍。结合丁硫醇在纳米颗粒上的选择性吸附，有效提高了反应效率并突破了传质限制。","scd":null,"kp":[]},{"i":43215,"as":"研究人员基于硫源缓慢释放策略，成功制备了原子级精确的硫稳定[Pd4S]²⁺纳米团簇。该团簇作为稳定的均相模型催化剂，用于炔烃的选择性加氢。实验结果表明，由于不同炔烃之间存在空间位阻和吸附能差异，该团簇中的配体会根据温度变化表现出动态的“配体门控”行为。这一发现揭示了金属纳米团簇表面配体的动态行为对催化活性和选择性的关键影响。","scd":null,"kp":[]},{"i":43216,"as":"该研究阐述了社会影响在气候行动中的研究议程，指出个人和群体能够通过社会影响塑造他人的态度与行动。文章综合了现有证据，强调了利用社会影响力来设计有效的行为干预措施，从而促进公众针对气候变化采取实际行动的现实应用价值。","scd":null,"kp":[]},{"i":43217,"as":"该综述总结了社交媒体在气候变化沟通中的作用。文章分析了社交平台上的气候相关内容，探讨了这些内容对公众气候态度、认知和行为的具体影响。研究指出，社交媒体已经成为气候变化传播的重要阵地，并正在重塑整个气候问题沟通的宏观格局。","scd":null,"kp":[]},{"i":43218,"as":"灾害沟通在保障社区免受气候灾害影响方面至关重要。当前气候灾害沟通面临五大核心挑战：错误信息的传播、反复发生灾害导致的疲劳感、信息获取不平等、两极分化的气候态度以及公众心理健康问题。","scd":null,"kp":[]},{"i":43219,"as":"气候变化沟通直接影响社会对风险的认知与响应。当前研究审视了气候沟通内容与方法的演变，重点关注紧迫性与不公带来的挑战，并探讨了构建有效且具包容性沟通渠道的具体策略。","scd":null,"kp":[]},{"i":43220,"as":"研究提出一种N-甲基咪唑鎓氯化物电解液添加剂，成功优化四电子水系锌碘电池的双界面配位。该添加剂在正极吸附多碘化物，有效稳定了具有工业级参数（碘载量≥10 mg cm–2，锌面积容量≥5 mAh cm–2）的耐用安时级电池性能。","scd":null,"kp":[]},{"i":43221,"as":"阿根廷查科等干旱森林受到地方与外国双重政策保护。然而，放宽当地森林区划法律的策略绕过了地方保护机制，加剧了森林砍伐压力，迫使跨国反森林砍伐政策向实现零总毁林目标迈进。","scd":null,"kp":[]},{"i":43222,"as":"研究将三氟甲硫基（SCF3）基团引入A-DA′D-A型非富勒烯受体的喹喔啉核心，结合烷基侧链工程构建了三种新型受体。该分子工程利用SCF3适中的吸电子能力平衡了静电势，有效抑制非辐射能量损失，使有机太阳能电池效率突破20%。","scd":null,"kp":[]},{"i":43223,"as":"针对有机硒化合物因硒-硫交换引发脱靶毒性的问题，研究开发了一种新型二硒缩酮二胺（SEK）。通过引入双甲基基团提供空间位阻，有效抑制了Se-S交换反应，使其半数抑制浓度提升至75.5 μM，较前体提高十倍，同时赋予了分子优异的抗氧化和免疫调节功能。","scd":null,"kp":[]},{"i":43224,"as":"欧洲能源系统模型分析显示，纳入充电基础设施成本后，单向智能充电每年可节省高达4.5%的系统成本。双向充电技术则在太阳能占主导的系统中产生巨大市场收益。电动汽车充电基础设施的建设目标需充分考虑各国能源系统的差异。","scd":null,"kp":[]},{"i":43225,"as":"研究提出一种利用多价抗体-聚合物嵌合体（PolyTACs）降解细胞膜蛋白的新策略。该策略证明，多价非共价结合能触发特定膜蛋白的内体摄取和溶酶体降解，且此过程不需要辅助膜蛋白天然具备溶酶体导向特性。","scd":null,"kp":[]},{"i":43226,"as":"研究通过多种光谱与滴定技术量化了催化剂组分对氢溢流的影响。实验表明，金属种类（Pt、Au）对溢流氢数量影响微乎其微；而载体表面化学性质对氢溢流高度敏感，金红石型TiO2能稳定的表面氢数量大约是锐钛矿型的5倍。","scd":null,"kp":[]},{"i":43227,"as":"为从湿烟气中捕集CO2，研究构建了包含逾11万种金属有机框架的计算高通量筛选工作流。该流程结合吸附模拟与机器学习稳定性分析，成功合成出一种顶级MOF材料，该材料在潮湿条件和高相对湿度下表现出极高的耐受性与CO2吸附能力。","scd":null,"kp":[]},{"i":43228,"as":"异常O-糖基化是癌症的显著特征，通过截短、延伸、加帽等多种糖型异质模式直接驱动恶性肿瘤转化。其中，Tn、STn和T等截短的异常O-GalNAc聚糖会扰乱上皮分化和屏障功能。研究探讨了将其作为精准肿瘤治疗靶点的策略。","scd":null,"kp":[]},{"i":43229,"as":"跨膜肽（MTPs）是一类能够无需特定转运蛋白协助且不破坏细胞膜，即可穿透脂质双分子层的多肽。它们违背了经典的膜渗透热力学模型，能够在具有高净电荷和低疏水性的条件下，将大分子极性货物（如蛋白质和肽）直接递送至细胞内部。","scd":null,"kp":[]},{"i":43230,"as":"生物材料的电学特性源于其复杂的分子结构与层级组织。晶体学研究揭示了晶格对称性在生物电分类中的关键作用。通过多学科手段研究氨基酸、蛋白质、组织及病毒等生物构建基块的电学性质，有助于阐明生物电现象的内在结构-功能关系机制。","scd":null,"kp":[]},{"i":43231,"as":"研究利用一种间隔基工程分子，成功稳定了钙钛矿太阳能电池中埋藏的空穴传输界面，并显著提高了分子的组装密度。该分子工程策略使制备出的钙钛矿太阳能电池具备出色的抗紫外线与抗热应力稳定性。","scd":null,"kp":[]},{"i":43232,"as":"研究利用硼引发的叶立德单体聚合反应，成功精准合成了带有己基侧链的α-酯-ω-羟基遥爪聚亚甲基。该方法实现了对端基保真度（>99%）和分子量的精确控制，获得了极窄的分子量分布，为构建类聚烯烃功能聚合物提供了新途径。","scd":null,"kp":[]},{"i":43233,"as":"研究利用金属有机框架开发了光催化芳香醛氢/氘交换新体系。UiO-66型材料在紫外线照射下，以重水为唯一氘源，实现了无需硫醇的甲酰基选择性氘化反应。该反应在3小时内实现了高达97%的氘掺入率，且产物选择性达到99%。","scd":null,"kp":[]},{"i":43234,"as":"通过多学科交叉证据，研究确认了高山开花植物虎耳草的食肉习性。实验表明该植物通过腺毛主动吸引并捕获昆虫，分泌酶消化猎物，并通过同位素标记证实了氮元素从猎物向植物组织的转移。基因组对比进一步揭示了其在食肉相关基因上的显著趋同进化。","scd":null,"kp":[]},{"i":43235,"as":"研究开发了一种将细胞膜力学转化为光谱光声信号的超分子策略。通过限制在脂质双分子层中的J-聚集行为，利用两亲性BODIPY探针插入细胞膜。该技术实现了对膜张力这一关键力学参数的直接、无创的深层组织光声检测。","scd":null,"kp":[]},{"i":43236,"as":"研究使用大规模并行报告分析技术探究了启动子对人类细胞可变剪接的影响。结果证实，启动子身份而非表达水平，对盒式外显子的包入产生强烈且高度依赖于上下文的效应。这一影响程度甚至超过了转录引发或延伸的药理学抑制剂的作用。","scd":null,"kp":[]},{"i":43237,"as":"","scd":null,"kp":[]},{"i":43238,"as":"Kv1.3通道高度表达于T淋巴细胞并促进T细胞活化。研究通过冷冻电镜及突变分析揭示，纳米抗体NB1.3结合至Kv1.3通道外表面，通过与S1-S4电压感应结构域和孔道结构域塔状部分的协同作用，促进离子选择滤网的缓慢C型失活，从而实现免疫抑制效果。","scd":null,"kp":[]},{"i":43239,"as":"研究利用新生小鼠脑免疫细胞的时间分辨单细胞图谱，发现一种在出生后早期发育中出现、第二周扩增随后下降的Numb富集小胶质细胞状态。该状态具有神经发育相关基因表达程序和独特的代谢特征。在此状态扩增期间，小胶质细胞的耗竭会保留正常的髓鞘形成，但会改变突触蛋白组成并破坏树突状态。","scd":null,"kp":[]},{"i":43240,"as":"某些产志贺毒素大肠杆菌通过EibG介导的链状粘附模式（CLAP）定植表面。活细胞延时成像显示，菌链源于单细胞的伸长与不分离分裂。在流体剪切力作用下，菌链表现出抗脱附性并在细胞连接处发生剪切依赖性碎裂，释放出存活的克隆单元向下游扩散。比较基因组学分析揭示了EibG相关粘附素的遗传多样性。","scd":null,"kp":[]},{"i":43241,"as":"研究发现在雌性小鼠实验性自身免疫性脑脊髓炎模型中，脊髓乳酸积累驱动小胶质细胞组蛋白发生持续的乳酸化，并与糖酵解激活相偶联。敲除乳酸脱氢酶A会减少乳酸化并加剧病情。补充外源乳酸可通过抑制炎症状态和促进修复程序来改善病理，且不改变外周免疫浸润。表观基因组分析证实，启动子区域存在直接的乳酸化富集。","scd":null,"kp":[]},{"i":43242,"as":"研究利用单核RNA测序技术构建了飞行滑翔膜（patagium）发育的单细胞图谱，识别出两种在滑翔膜中高度富集的成纤维细胞亚群（Fp2和Fr）。这些成纤维细胞上调表达Wnt5a、Fgf7和Fgf10，通过真皮与表皮基底层角质形成细胞之间的通讯参与滑翔膜的形态发生。其中，Fp2成纤维细胞伴随Wnt5a表达升高，参与远端真皮聚集和表皮增厚。","scd":null,"kp":[]},{"i":43243,"as":"研究整合了244种转录因子的保守结合位点图谱、单核染色质可及性以及细胞类型分辨率基因表达数据，探究植物中转录因子结合位点（TFBS）位置与调控功能的关系。细胞类型特异性表达与嵌入细胞类型限制性染色质中的保守TFBS高度相关，这些TFBS分布在远端启动子和内含子中。转录起始位点近端的TFBS则主要参与应激响应调控。","scd":null,"kp":[]},{"i":43244,"as":"ATP13A4是一种在星形胶质细胞中高表达的转运蛋白，负责将多胺（如亚精胺）导入细胞，从而限制其细胞外水平。ATP13A4缺失会导致星形胶质细胞形态简化，并增加神经元之间的兴奋性突触连接。外源性添加亚精胺可重现该促突触生成效应，表明细胞外亚精胺是一种促进突触生成的信号分子。小鼠体内Atp13a4缺失会导致大脑多胺分布发生改变。","scd":null,"kp":[]},{"i":43245,"as":"核糖体蛋白RPL22L1是结直肠癌细胞DNA损伤反应的关键调节因子。DNA损伤会上调RPL22L1的表达并结合入核糖体，形成特异性核糖体。这种核糖体优先翻译具有复杂5'非翻译区（5'UTR）结构的mRNA，并通过非帽子依赖机制增强ATRX的翻译。ATRX随后将DNA-PKcs招募至DNA损伤位点，增强DNA修复能力。RPL22L1的缺失会增加癌细胞对化学治疗的敏感性。","scd":null,"kp":[]},{"i":43246,"as":"研究在三阴性乳腺癌异种移植模型中进行了全基因组体内CRISPR/Cas9功能丢失筛选，鉴定出包括VPS45、CMTR2、RBSN和NF2在内的转移抑制基因（MSGs）。这些基因缺失会促进癌细胞发生上皮-间质转化、侵袭、血管生成及肺部定植。通过CRISPR介导激活这些基因可抑制癌转移。患者数据集分析显示，这些基因在肿瘤中的表达降低。","scd":null,"kp":[]},{"i":43247,"as":"研究发现了一个由干扰素γ（IFNγ）驱动的早期生命调节回路，可将饮食信号传递给脾脏1型常规树突状细胞（cDC1）。IFNγ介导的STAT1信号传导诱导脾脏cDC1发生免疫成熟，使其能够塑造抗原经验型效应记忆CD8+ T细胞的分化。这一cDC1程序在断奶期（从母乳向固体食物过渡）出现，且在无菌小鼠中依然发挥作用。","scd":null,"kp":[]},{"i":43248,"as":"研究整合了270例促肾上腺皮质激素垂体神经内分泌肿瘤的表观基因组、转录组和蛋白质组数据。通过综合分析，将这些肿瘤划分为四个具有稳健且临床病理特征截然不同的分子亚组。这四个分子亚组可以通过显微镜观察SSTR1和GATA3等标记物进行广泛区分。该研究为垂体神经内分泌肿瘤建立了基于分子的分类标准。","scd":null,"kp":[]},{"i":43249,"as":"霍乱弧菌在节肢动物肠道内合成的色氨酸被宿主肠细胞用于合成血清素。血清素通过特定的G蛋白偶联受体、Gαq、磷脂酶C和蛋白激酶C向肠内分泌细胞发出信号。该信号通路最终导致核受体ultraspiracle发生磷酸化并增强其活性，从而激活宿主定植因子Peritrophin-15a的表达，并启动TNF样免疫缺陷途径（IMD）。","scd":null,"kp":[]},{"i":43250,"as":"光遗传学激活帕金森病小鼠模型前庭神经核复合体（VNC）中由Vglut2定义的兴奋性神经元，能够增加基底神经节和脑干运动靶区的cFos活动。行为学分析表明，这种亚症状强度的刺激改善了小鼠的运动姿势和动态。VNC向纹状体-丘脑-丘脑底核以及尾侧延髓运动中枢输入大量投射，并接收来自感觉运动皮质的输入信号。","scd":null,"kp":[]},{"i":43251,"as":"研究开发了一种由二维钴金属有机框架（Co-L0-NS）衍生的钴催化剂，用于丙酮和吡啶的电催化加氢。在阴极偏压预处理下，前驱体发生结构重构，生成富含Co(OH)2、高度分散且结构无序的纳米簇材料（MD-Cat）。在优化的电位下，MD-Cat能够将丙酮高效加氢为异丙醇，且表现出接近定量的法拉第效率。","scd":null,"kp":[]},{"i":43252,"as":"这篇综述全面概述了涉及8π至18π电子的高阶环加成反应的发展、范围和基本原理。文章重点介绍了由过渡金属、路易斯酸、有机小分子和酶催化的高阶环加成反应的关键进展，强调了现代催化剂设计如何实现对周环选择性和立体选择性的精准控制。此外，还探讨了基于密度泛函理论、分子动力学和实验设计的机理见解。","scd":null,"kp":[]},{"i":43253,"as":"该论文探讨了磁化非交换启发黑洞的相关物理特性，研究内容涵盖了从带电粒子动力学到准周期振荡（QPO）的深入研究。论文计划于2026年8月4日发表在《Physics Letters B》期刊上，作者包括Abubakir Shermatov等多位学者。","scd":null,"kp":[]},{"i":43254,"as":"研究提出了一种基于鸟苷一磷酸的G-四链体超分子模板策略，用于生成嵌入水凝胶中的无定形配位聚合物纳米点。该超分子支架与没食子酸共组装，在引入Fe3+后，空间限制金属-多酚配位，引导生成超小、均匀分散的无定形配位聚合物纳米点。这种材料成功应用于光热催化CO2环加成反应，克服了结晶框架的局限性。","scd":null,"kp":[]},{"i":43255,"as":"研究提出了一种混合维度结构，通过全水相工艺将1D银纳米线、2D MXene纳米片和3D生物基海藻酸钠（SA）结合，制备出柔性透明导电电极。MXene与SA之间强大的氢键网络使该电极具有出色的机械稳定性和环境稳定性。优化的AgNWs/SA:MXene电极在550 nm波长下透光率达87.8%，方阻仅为12.3 Ω/sq，并成功应用于柔性绿光有机发光二极管。","scd":null,"kp":[]},{"i":43256,"as":"研究结合纳米球自组装和掠角沉积（GLAD）技术，制造出由高度有序的尖等离子体纳米线阵列组成的大面积、低成本表面增强拉曼散射（SERS）基板。通过精确控制纳米线的尺寸和间隙，该SERS传感器芯片能够高灵敏、高选择性地检测噻菌灵、乙基对氧磷等农药以及腺嘌呤和胸腺嘧啶核苷酸。研究还首次在柔性聚合物薄膜上成功制备了SERS基板。","scd":null,"kp":[]},{"i":43257,"as":"为解决共价有机框架层间紧密堆叠和导电性差的问题，研究通过在碳纳米管表面原位缩聚，合成了富含六氮杂三亚苯基和芳香环部分的核壳纳米复合材料。这种结构结合了COFs的延伸π电子离域和高密度氧化还原活性位点，以及碳纳米管的导电性。这些杂化材料表现出协同效应，实现了优异的负极锂离子存储性能。","scd":null,"kp":[]},{"i":43258,"as":"针对锡基钙钛矿太阳能电池结晶过快和Sn2+易氧化的问题，研究引入了4-氟苯乙基铵（FPEA）和预退火静态阶段（PASS）。低浓度的FPEA与PASS结合，有效缓解了晶体生长与薄膜致密性之间的矛盾。原位光谱证实了一种中间体介导的分步结晶过程，即在PASS期间发生从中间体到钙钛矿相的逐渐部分转变，伴随有效晶体生长，从而减少了缺陷形态。","scd":null,"kp":[]},{"i":43259,"as":"本文提出了一种受甲虫启发的外置式口罩原型，用于高效收集呼出气体冷凝物（EBC）。该原型结合了具有异质润湿性的冷凝界面与时间对齐的多通道呼吸读数系统。其冷凝界面在微柱顶部设有亲水成核位点，在侧壁和基底采用超疏水背景，实现了液滴的优先成核与快速去除，从而有效解决了传统口罩冷凝物收集效率低的问题。","scd":null,"kp":[]},{"i":43260,"as":"本文全面综述了有机半导体器件（如OFETs、OLEDs和OPVs）中先进的电极工程策略。电极在电荷注入、提取和界面传输中起决定性作用。随着器件架构向小型化、柔性和生物集成平台转变，电极设计已演变为复杂的多目标优化挑战。文章以有机场效应晶体管（OFETs）为主要模型系统，阐明了普遍适用于各类有机半导体电子器件的设计原则。","scd":null,"kp":[]},{"i":43261,"as":"本文利用超临界CO2处理ZnSn(OH)6（ZHS），成功暴露其{111}晶面并引入氧空位，从而产生自旋极化电子。这种自旋极化效应加速了激子解离和自旋依赖的电子迁移，克服了光生电子和空穴因强库仑引力快速复合的限制，最终显著提升了光催化CO2还原为CO的效率。","scd":null,"kp":[]},{"i":43262,"as":"受天然木材启发，研究人员开发出一种具有结构稳定性的仿生木材水凝胶，用于神经修复。该材料整合了机械强度高的木材衍生纤维素框架与柔软的甲基丙烯酰化明胶（GelMA）水凝胶基质。这种仿生复合材料具备优越的细胞微环境，展现出增强神经突向外定向生长的诱导能力，为长段周围神经缺损的修复提供了创新策略。","scd":null,"kp":[]},{"i":43263,"as":"针对传统碳酸乙烯酯基电解液在低温下动力学迟缓的问题，本文开发了一种基于二氟草酸硼酸锂（LiDFOB）盐和碳酸丙烯酯/二氟乙酸甲酯/氟代碳酸乙烯酯（4:4:2）的弱溶剂化三元电解液。MDFA作为弱配位组分削弱了Li+-PC结合以重构溶剂化环境，FEC则促进在两极形成坚固的无机富集界面。该策略有效提升了锂金属电池的低温性能和高压稳定性。","scd":null,"kp":[]},{"i":43264,"as":"","scd":null,"kp":[]},{"i":43265,"as":"","scd":null,"kp":[]},{"i":43266,"as":"本文提出了一种基于大语言模型（LLM）结构化事件和表示学习的反事实负荷预测方法。针对现有预测无法量化社会环境事件对电力需求扰动的问题，该方法通过比较观测新闻下的事实轨迹与替代事件条件下的反事实轨迹来量化影响。此研究解决了传统预测无法回答反事实问题以及混淆因素带来的挑战。","scd":null,"kp":[]},{"i":43267,"as":"","scd":null,"kp":[]},{"i":43268,"as":"基于对全球超过1000名受访者的国际调查，本文研究了公众对氢技术的接受度及其影响因素。结果显示，大学和研究中心是公众最信任的信息来源，凸显了科学机构在塑造公众认知中的关键作用。调查涵盖了人口统计特征、普及意识以及对特定氢应用的感知，为氢能部署过程中的信任建立、采用障碍和政策制定提供了全球性见解。","scd":null,"kp":[]},{"i":43269,"as":"本文报道了一种由吸电子配体调控的铂位共价有机框架，实现了在水相中无需牺牲剂的光催化CO2至CH4转化。该框架由三氨基苯基苯供体和联吡啶受体构建，提供可见光吸收和明确的氮配位位点以固定铂。带有含氟吸电子配体的铂配合物被引入框架中，实现了高效电荷分离和可控的中间体加氢，解决了多电子质子耦合还原过程的挑战。","scd":null,"kp":[]},{"i":43270,"as":"本文报道了一种超分子笼系统，实现了酸/碱调节下的取代基导向拓扑重排和荧光调制。通过酸碱诱导双咪唑配体发生开环和闭环反应，该配体与Zn2+自组装形成立方八面体、八面体、方棱柱和三角棱柱等多种笼结构。研究表明，取代基的空间位阻和取向能够有效调控宏观的笼形拓扑分布，解决了配位笼拓扑受空间效应控制的难题。","scd":null,"kp":[]},{"i":43271,"as":"","scd":null,"kp":[]},{"i":43272,"as":"本文介绍了一种微型结构辅助的螺旋微流控平台，能够基于细胞形变在超高通量（每分钟超过200万个细胞）下对癌细胞进行分选。该平台结合了实时图像细胞表型分析技术，探究了分选组分形变与生物学特性的三方关联，成功分离出具有高侵袭性的转移性癌症亚群，为评估细胞骨架等生物结构变化提供了关键工具。","scd":null,"kp":[]},{"i":43273,"as":"本研究发现，卵细胞在输卵管中的成功运输并不依赖于输卵管上皮皱襞的纵向排列。在缺乏核心平面细胞极性蛋白VANGL1的突变小鼠输卵管中，虽然纵向皱襞结构被破坏，但纤毛沿卵巢-子宫轴的跳动方向基本得以保留。结果表明，即使皱襞形态发生畸形，卵细胞的运输功能依然正常，从而验证了纤毛运动在其中的主导作用。","scd":null,"kp":[]},{"i":43274,"as":"本文研究了Tmc1耳聋突变体（如p.T416K等）小鼠听力毛细胞中Ca2+对PMCA2钙泵表达的调节。这些突变导致机械电换能器（MET）通道的Ca2+通透性降低，并伴随外毛细胞静纤毛中PMCA2钙泵表达量的下降。研究发现，PMCA2密度的降低与经MET通道进入细胞的Ca2+量减少直接相关，揭示了引发细胞死亡和耳聋的病理机制。","scd":null,"kp":[]},{"i":43275,"as":"为克服电化学和生化方法在CO2还原上的各自局限，本文提出一种模块化的非生物-生物平台。该平台能在4小时内通过电化学方法产生0.87M的浓缩甲酸盐，并将其独立供应给多种微生物系统进行后续生物转化。此方法突破了现有研究中微生物菌株范围狭窄的限制，解决了气体-液体向细胞传质缓慢的问题，有效拓展了多碳产物的生成路径。","scd":null,"kp":[]},{"i":43276,"as":"利用系留航空器进行空间分辨原位全息测量，本文发现浅积云中水滴的聚集现象比之前认为的要强烈且高度局部化。水滴的尺寸和空间聚集影响云的演变和辐射特性，而现有基于飞机观测的数据仅在千米尺度上显示出较弱的毫米级聚集。这一发现对当前暖云中水滴生长和降水引发机制的模型假设提出了挑战。","scd":null,"kp":[]},{"i":43277,"as":"研究发现，刺鼠相关肽神经元（AgRP）的激活对于雌性小鼠中GLP-1受体激动剂（如司美格鲁肽）发挥完整的减重作用是必需的。尽管传统上认为GLP-1RAs通过抑制或绕过AgRP神经元起作用，但多种AgRP功能丧失模型证实，破坏AgRP回路的完整性会降低GLP-1RAs的减重效果。此外，这一机制要求因性别、饮食和干预模式而异。","scd":null,"kp":[]},{"i":43278,"as":"为解决单细胞RNA测序无法准确反映低丰度蛋白的问题，本研究利用分离的脑血管片段研究血脑屏障。结合深度组学定量分析、蛋白标尺方法和scRNA-seq，研究人员估算出了跨越内皮细胞、平滑肌细胞等8种细胞类型的9940种蛋白的单细胞拷贝数，成功构建了成年小鼠脑血管参考蛋白质图谱。","scd":null,"kp":[]},{"i":43279,"as":"本文提出了一种基于语义的嗅觉混合物距离高保真调节模型。研究发现，气味混合物之间的感知距离是可以高保真预测的，且能够通过源自单分子表示的紧凑语义空间来很好地描述。在DREAM嗅觉混合物预测挑战赛中，该集成模型在隐藏测试集中成功预测了46对混合物的距离，表现优于现有的最先进模型。","scd":null,"kp":[]},{"i":43280,"as":"本文研究了酵母转录因子Cbf1在着丝粒组装中的关键作用。Cbf1直接结合于芽殖酵母着丝粒DNA，其缺失会显著增加染色体错误分离率。最新研究发现，Cbf1通过路障机制防止着丝粒外围不适时的转录读取。然而，在缺失Cbf1结合的情况下仅恢复转录路障，只能部分挽救染色体的错误分离，表明Cbf1与CCAN复合体之间的相互依赖作用对稳定动粒至关重要。","scd":null,"kp":[]},{"i":43281,"as":"酵母转录因子Cbf1直接结合着丝粒DNA，其缺失会显著增加染色体错误分离率。研究发现，Cbf1通过路障机制阻止着丝粒外围发生不合时宜的转录穿透，从而抑制染色体转录。在缺失Cbf1的情况下恢复转录路障仅能部分挽救染色体的错误分离现象。","scd":null,"kp":[]},{"i":43282,"as":"针对精准医学中对性别依赖效应的研究，本文分析了行为和大脑科学领域的200篇相关文献。结果显示，尽管神经科学领域声称存在性别依赖效应的文章数量远多于其他领域，但这些主张极少得到适当的统计学证据支持。仅有24%的文章通过适当的跨性别统计学比较并得出与主张一致的结果，另有9%的文章描述了正确的测试但结果不吻合。","scd":null,"kp":[]},{"i":43283,"as":"生命早期限制糖分摄入能从因果关系上降低成年后的癌症发病率并减缓生物衰老。基于英国1953年取消糖配给制的自然实验，对64,761名参与者分析表明，生命前1000天处于糖配给期的队列，其成年期肝癌、直肠癌、肺癌、前列腺癌和乳腺癌的发病率呈剂量依赖性显著降低。早期糖暴露主要通过行为途径和生物学途径产生贯穿一生的影响。","scd":null,"kp":[]},{"i":43284,"as":"STRA6基因（视黄醇结合蛋白的高亲和力受体）突变会导致表现为眼部畸形等严重表型变异的Matthew-Wood综合征。利用小鼠模型证实，母体的维生素A状况是决定该基因突变表型表达和外显率的主要修饰因子。母体维生素A的可获得性与胚胎STRA6基因型相互作用，共同决定了眼部发育的结果。母体维生素A限制会显著影响该综合征的表型严重程度。","scd":null,"kp":[]},{"i":43285,"as":"植物依赖细胞表面免疫受体识别微生物模式并启动防御。生菜能够识别广泛存在于细菌、真菌和卵菌中的NLP蛋白的24个氨基酸肽段（nlp24）。研究鉴定出富含亮氨酸重复序列的受体激酶LNR负责介导这一识别过程。LNR受体识别高度保守的nlp24基序，触发生菜的免疫反应，为菊科植物的免疫信号传导提供了新见解。","scd":null,"kp":[]},{"i":43286,"as":"钼辅因子（Moco）生物合成中存在复杂的GTP重排反应：鸟嘌呤碱基的C8原子被插入到核糖的C-2'和C-3'原子之间。这一复杂转化仅由单一酶MoaC催化。研究通过化学捕获、酶动力学、质谱和X射线晶体学证实，MoaC采用了一种意想不到的共价催化机制。该机制实现了精确的原子水平控制，完成了特征的吡喃蝶呤重排合成。","scd":null,"kp":[]},{"i":43287,"as":"通过对全新世早期黎凡特南部新石器时代早期谷物遗骸的分析，揭示了谷物驯化的进化时间序列。在谷穗脱落（非碎穗）这一经典遗传驯化特征出现之前，谷物的颗粒尺寸就已经发生了显著增加。这表明在人类管理的早期农业环境中，植物表现出了发育可塑性。在人类栽培选择压力下，谷粒增大先于不可逆的基因型改变发生，发育可塑性塑造了驯化前的谷物进化。","scd":null,"kp":[]},{"i":43288,"as":"研究通过比较二倍体、人工合成同源四倍体和自然同源四倍体（起源于约7000至24000代前）草本植物，评估了全基因组复制（WGD）及进化后改变的作用。结果表明，与WGD事件本身相比，WGD之后的进化过程对植物表型分歧和转录组差异的驱动作用更为显著。自然四倍体在不同温度波动条件下的表型和基因表达适应性变化，主要源于复制发生后的长期进化。","scd":null,"kp":[]},{"i":43289,"as":"血管紧张素II 1型受体（AT1R）是调节心血管系统的重要G蛋白偶联受体，也是治疗高血压的关键靶点。传统上其激动剂为肽类配体，而拮抗剂为小分子。研究重新探讨了原型非肽类AT1R激动剂L-162,313的作用机制。证实了这种具有拮抗剂类似化学骨架的分子，通过与受体特定方式结合，发挥出与肽类激动剂相似的受体激活作用。","scd":null,"kp":[]},{"i":43290,"as":"除了传统的胰岛素和mTOR营养感知途径外，细胞生物物理特性在营养响应中发挥关键作用。在果蝇肠上皮细胞中，食物中氨基酸的数量（而非质量）会改变细胞纳米级的细胞质流动性。这种细胞质流动性的变化直接决定了细胞状态，并影响一种介导肠道细胞更新的非凋亡性细胞死亡（erebosis）的发生频率。揭示了营养可用性与肠上皮细胞命运之间的生物物理偶联机制。","scd":null,"kp":[]},{"i":43291,"as":"登革热病毒（DENV-4）感染会导致宿主出现严重的DNA损伤和基因组不稳定。研究发现，DENV-4感染显著抑制了宿主细胞中DNA修复基因的转录，并下调了特定的跨损伤合成（TLS）聚合酶。这种病毒依赖的病理生物学机制会在受感染的血细胞中留下持久的生物“疤痕”，导致慢性疾病风险累积增加，解释了登革热感染后综合征和白血病等远期并发症的潜在机理。","scd":null,"kp":[]},{"i":43292,"as":"聚阴离子化合物因其坚固的结构框架和高工作电压，是钠离子电池极具前景的正极材料。然而，其本征电子电导率差以及在深度脱钠过程中的不可逆结构恶化限制了其实际应用。为解决这些问题，研究通过掺入多价阳离子（Cr3+、Mn2+、Fe等）合成了一种高熵Na3V2(PO4)2O2F正极材料。这种高熵定制策略有效调控了d-p轨道杂化，提升了电池的循环耐久性。","scd":null,"kp":[]},{"i":43293,"as":"可充电镁电池面临着沉积不稳定、枝晶生长、库仑效率低和循环寿命差等问题。研究提出了一种全氟化不对称镁盐Mg(PFBS)2来调节镁离子的沉积并改善界面稳定性。PFBS-阴离子能够定制溶剂化结构并优化双电层（EDL），促进Mg2+的去溶剂化并抑制溶剂分解。基于扩散控制理论引入Damköhler（Da）和Wagner（Wa）数，阐明了电化学反应动力学竞争机制，实现了稳定且无枝晶的镁电池。","scd":null,"kp":[]},{"i":43294,"as":"质子交换膜水电解（PEMWE）技术因阳极析氧反应（OER）涉及复杂的多步质子-电子转移过程而面临动力学限制。由于运行过程中Ru位点的过度氧化和晶格氧流失，二氧化钌基催化剂的稳定性较差。为缓解这些失活机制，研究提出一种区别于传统的机制驱动型原子级工程策略，对RuO2基催化剂进行精确改造，旨在克服内在局限性，提升PEMWE的绿氢生产效率。","scd":null,"kp":[]},{"i":43295,"as":"针对无机半导体本征脆性限制功能应用的问题，研究提出了一种利用原子级库仑剪裁对层状半导体碲化铋（Bi2Te3）进行塑性工程的策略。通过在范德华间隙进行战略性掺杂，建立了长程层间库仑引力。该策略将脆性的Bi2Te3成功转化为高度可变形的半导体，实现了室温下超过90%的压缩应变，同时保留了优异的面内电学传输性能，维持了出色的峰值zT热电优值。","scd":null,"kp":[]},{"i":43296,"as":"高温介电聚合物在恶劣工况下易受热激发电荷传输和击穿的影响。研究证明，在聚醚酰亚胺（PEI）中加入高负载的低分子量低聚芳醚脲（O-EEU）可通过网络介导的基质分区来调节电荷传输。O-EEU在PEI基体内形成富O-EEU网络，将连续的PEI相转化为局部的隔室结构。这种分区结构实现了电荷路径的分割并限制了载流子的空间运动，从而有效抑制了漏电流传导，提升了高温电容储能性能。","scd":null,"kp":[]},{"i":43297,"as":"石榴石型固态电解质Li6.5La3Zr1.5Ta0.5O12（LLZTO）具有高室温锂离子电导率，但面临高界面阻抗和晶界处锂枝晶生长的挑战。这些问题已被证明与表面的Li2CO3厚钝化层密切相关。研究开发了一种氟化物固态电解质界面层，该界面层在石榴石的诱导下发生非晶化。这种非晶化界面层有效解决了阻抗和枝晶问题，实现了高压、大容量的锂金属固态电池稳定运行。","scd":null,"kp":[]},{"i":43298,"as":"电解液设计一直受到高溶剂极性与弱Li+溶剂化之间权衡的限制。研究建立了一种空间-电子调制策略，将溶剂极性与Li+配位解耦，提出了一种通用的伪弱溶剂化电解液设计范式。基于此原理，开发了结合2,2,2-三氟-N,N-二甲基乙酰胺（DMTFA）、氟代碳酸乙烯酯（FEC）和双锂盐的空间位阻介导电解液。DMTFA虽具有强极性，但表现出对Li+的弱溶剂化能力，打破了极性与配位之间的传统耦合。","scd":null,"kp":[]},{"i":43299,"as":"富锂锰基氧化物（LRMOs）的实际应用受制于迟缓的阴离子氧化还原动力学和结构不稳定性之间的内在冲突。研究提出了一种AlPO4辅助的高温锂化策略，实现了对LRMOs的多尺度协同调控。该方法同时优化了颗粒形态、稳定了表面/界面化学并增强了晶格完整性。通过形成适度尺寸的初级颗粒，有效缩短了Li+的扩散路径，实现了动力学增强与循环稳定性的协同提升。","scd":null,"kp":[]},{"i":43300,"as":"为了研究奇质量数原子核中的动态八极关联，研究将角动量依赖的八极振动核芯引入到八极核芯-准粒子耦合模型中。以钍-233（$^{233}\\mathrm{Th}$）的原子核结构为代表例进行了计算分析。该理论模型成功描述了动态八极振动相互作用，并获得了该原子核的宇称正负性及其能级结构特征。研究结果发表在《物理评论 C》（Phys. Rev. C 114, 024308）。","scd":null,"kp":[]},{"i":43301,"as":"研究利用总吸收谱学方法对铁-71（$^{71}\\mathrm{Fe}$）到钴-71（$^{71}\\mathrm{Co}$）的β衰变进行了测量。在原子序数Z≈28和中子数N≈40附近的富中子核区，通过壳演化效应显示出对传统平均场核性质的显著偏离。这些原子核展现出形变变化和形状共存现象，并且可能位于天体物理中子俘获核合成路径上。该研究为理解核结构和天体物理过程提供了关键数据。","scd":null,"kp":[]},{"i":43302,"as":"核电子俘获激发（NEEC）是一种耦合的核-原子过程：离子捕获电子进入原子空位，导致相应的原子核被激发到更高的激发态。迄今为止，仅有一例关于核素$^{93m}$Nb的实验结果。研究在铯-127（$^{127}\\mathrm{Cs}$）中寻找NEEC存在的实验证据。该研究旨在通过测量验证这一罕见的核激发机制，探索通过电子俘获引发原子核能级跃迁的物理现象，结果发表于《物理评论 C》。","scd":null,"kp":[]},{"i":43303,"as":"研究团队调查了具有动量带隙的晶格系统中的布洛赫振荡。系统内带隙模式表现出指数级的增长或衰减。研究表明，k-gap放大、衰减与带间干涉相互作用产生了一个临界状态，控制着波包的行为。","scd":null,"kp":[]},{"i":43304,"as":"LHCb合作组首次在质子-质子碰撞中寻找轻子味破坏衰变 $B^+→π^+μ^±e^∓$。研究使用了2011至2018年间收集的、积分亮度为 $9 fb^{-1}$ 的数据。结果显示未发现该衰变的重要迹象。","scd":null,"kp":[]},{"i":43305,"as":"Double Chooz合作组首次完成了对乏核燃料中微子发射的测量。乏核燃料与停堆反应堆会发射反中微ino，核监管机构可利用这一特性对核电站进行实时监测。","scd":null,"kp":[]},{"i":43306,"as":"研究测量了三个束流能量下 $^{54}Cr+^{209}Bi$ 反应的质量-总动能（MTKE）分布。研究解决了由主导非复合过程、有限数据和不确定模型导致的重离子反应融合抑制难以精确量化的问题，为超重元素 $^{263}Bh$ 的形成机制提供了实验数据。","scd":null,"kp":[]},{"i":43307,"as":"研究人员开发了一项适用于其他原子种类的技术，成功在光镊阵列中稳定装载了2400个中性镱-174原子。这是迄今为止制备的最大类碱土原子阵列，为量子物理研究提供了新的大尺度平台。","scd":null,"kp":[]},{"i":43308,"as":"研究通过一项同时实现高浮力雷诺数和低弗劳德数（代表海洋环境特征）的大规模实验，展示了分层湍流中示踪粒子分散的拉格朗日测量结果。分层对垂直粒子运动产生显著影响，加深了对海洋条件湍流机制的理解。","scd":null,"kp":[]},{"i":43309,"as":"双层硼烯建立了一种单质超导转变温度的新上限。单质超导体成分简单，作为探查基础机制的重要模型系统，其超导转变温度通常较低。双层硼烯展现出了显著的例外，突破了传统单质超导材料的温度限制。","scd":null,"kp":[]},{"i":43310,"as":"研究提出了一种基于呼吸烧绿石晶格的最小化自旋1/2模型，仅通过对称性允许的Dzyaloshinskii–Moriya相互作用进行调节。该模型为秩为1和秩为2的U(1)库仑液体提供了稳健的量子实现，推进了对量子库仑液体的研究。","scd":null,"kp":[]},{"i":43311,"as":"研究展示了反铁磁交变磁性材料 $RuO_2$ 中轨道霍尔效应与自旋霍尔效应的共存与可调谐性。交变磁性材料在节能自旋电子学应用中备受关注。该研究解决了近期实验中关于交变磁自旋分裂相互矛盾的现象。","scd":null,"kp":[]},{"i":43312,"as":"研究发现子晶格电流是实现宇称反常交变磁性的一条可行途径。在这种机制下，非相对论共线自旋分裂在能带中以动量的奇函数形式发生。该理论从Haldane-Hubbard模型扩展至一般双部分晶格，为交变磁性提供了新机制。","scd":null,"kp":[]},{"i":43313,"as":"研究发现在金属-近零介电常数（ENZ）界面可以支持一种光学反趋肤效应。引导远低于衍射极限的电磁波通常会导致严重的传播损耗，而该效应可以显著降低因场被迫进入耗散性材料边界而产生的传播损耗，突破了金属中的限制损耗极限。","scd":null,"kp":[]},{"i":43314,"as":"研究追踪了不同细胞类型中三种囊泡的运动轨迹。研究发现，活细胞内货物运输的拉伸指数分布源自微观层面的动态非均匀性。这一发现揭示了非平衡稳态涨落在生命系统中的微观起源。","scd":null,"kp":[]},{"i":43315,"as":"研究推导出了在小于亚兆秒差距尺度下，对物质密度扰动的原初功率谱的最新约束条件。原初功率谱包含关于宇宙学暴胀等新基础物理的重要信息，但在小宇宙尺度上（$k≳3 Mpc^{-1}$）观测约束极为薄弱，此次更新有效填补了该尺度的数据空白。","scd":null,"kp":[]},{"i":43316,"as":"研究深入探讨了天体物理学相关的轻核系统 $^{12}C + ^{19}F$ 在深势垒下能区的融合阻碍现象。该研究澄清了以往难以确定的融合激发函数行为，为理解恒星演化过程中的轻核聚变机制提供了关键见解。","scd":null,"kp":[]},{"i":43317,"as":"研究报道了一种单相NiCoN固溶体金属氮化物催化剂。原子级Co的掺入破坏了对称性，产生具有电子极化活性的Ni–N–Co配位环境。这种结构调制加速了脱氢动力学并降低了C–C键断裂的能垒，引导反应向选择性步骤化方向进行，实现了安培级选择性甲酸的合成。","scd":null,"kp":[]},{"i":43318,"as":"通过多尺度计算方法（包括密度泛函理论、巨正则蒙特卡洛和分子动力学模拟），研究了基于DUT-4(Al)的金属有机框架（MOF）与疏水聚合物复合材料在潮湿环境下捕获甲苯的能力。结果揭示了聚合物在MOF孔道内渗透行为的明确层级，建立了聚合物渗透与孔隙率、吸附量之间的构效关系。","scd":null,"kp":[]},{"i":43319,"as":"结合拉波特规则引导的分子对称性控制与分子内电荷转移工程，利用强给电子的茚并二吡咯单元开发出一种受体-给体-受体型分子P1。该分子吸收光谱延伸至近红外区，理论计算表明其主要允许跃迁至第一激发态，成功实现了用于无色透明光伏的近红外选择性有机半导体材料。","scd":null,"kp":[]},{"i":43320,"as":"提出利用高熵掺杂降低LMFP正极中$Mn^{2+}$的自旋态，使其从高自旋转变为中间自旋构型。自旋态降低消除了导致姜-泰勒畸变的内驱力，增强了Mn-O键的稳定性，缩小了带隙并优化了离子传输路径，从而显著提升了LiFe0.2Mn0.8PO4正极的电化学性能和循环稳定性。","scd":null,"kp":[]},{"i":43321,"as":"引入了N2ZND（神经网络Zhu-Nakamura动力学）框架，结合分层采样与E(3)等变深度学习，克服了长时程量子化学非绝热动力学计算成本过高的瓶颈。该数据高效的机器学习框架为设计兼具高旋转速度和强单向性的光驱动分子马达提供了合理工具。","scd":null,"kp":[]},{"i":43322,"as":"展示了金属有机框架APF-40能够封装并实现超规则5（bRo5）药物分子的结构可视化。APF-40由苯环取代的六氮杂菲配体与Zn8簇形成双重互穿网络，其动态结构能有效固定分子及溶剂化壳层。成功精确解析了12种分子的结构，并识别出市售样品中的一种化合物。","scd":null,"kp":[]},{"i":43323,"as":"研究利用非天然氨基酸4-氰基色氨酸（4CN-Trp）替换天然色氨酸，重新构建极短肽组装的多相凝聚物结构。通过4CN-Trp的内源性荧光和红外报告能力，成功监测液-液相分离（LLPS）行为，证实单原子级别的替换能够精确调控和表征合成肽核心-壳层凝聚物的微观结构。","scd":null,"kp":[]},{"i":43324,"as":"针对钙钛矿光伏混合 sequential deposition 工艺中固体互扩散受限导致转换不完全的问题，研究提出一种瞬时气相沉积介质（TVM）策略。在无机前驱体共蒸发阶段引入Pb(SCN)2，改变前驱体框架的孔隙率以促进有机盐渗透，从而降低δ相到α相的相变势垒和活化能，提升钙钛矿薄膜质量。","scd":null,"kp":[]},{"i":43325,"as":"针对光热治疗（PTT）中激光剂量缺乏准确引导的问题，研究开发了一种装载BBTPPRO的聚乳酸-羟基乙酸共聚物微球（BBTPPRO MPs）作为栓塞诊疗平台。该微球平均直径为53.21 μm，载药量4.73%，包封率99.23%。结合双光声-拉曼成像技术，能够实现深部依赖性的激光剂量精准引导，用于不可切除肝细胞癌的治疗。","scd":null,"kp":[]},{"i":43326,"as":"研究揭示了BiVO4光阳极在甘油光氧化过程中的表面重构现象。在酸性和碱性介质中，钒（V）的优先溶解形成了富铋层。通过原位双工作电极测量证实，酸性介质中重构的表面不仅改善了空穴转移动力学，还充当了甘油氧化催化剂，从而有效调控光电化学性能的稳定性和活性。","scd":null,"kp":[]},{"i":43327,"as":"研究利用球差校正扫描透射电子显微镜（STEM-EDS/EELS）技术，区分了锂离子电池中富锂锰（LMR）氧化物阴极在日历老化和循环老化下的微观结构演变。两种模式均引发近表面降解（如表面重构和阳离子混合），但在阴极-电解质界面处表现出明显差异，表明在静态和动态条件下电解质具有不同的分解途径。","scd":null,"kp":[]},{"i":43328,"as":"针对高电压锂金属电池中阴离子在界面可及性受限引起的界面化学不稳定问题，研究提出级联溶剂化精细（CSR）策略。该策略利用阴离子-阴离子排斥力与平均极化率的协同作用，在分子水平控制阴离子配位锂簇的尺寸和动态。通过顺序引入BOB-和TFSI-阴离子，实现了簇的小型化和阴离子交换动力学的调控。","scd":null,"kp":[]},{"i":43329,"as":"为解决钙钛矿/有机叠层太阳能电池中原子层沉积（ALD）前驱体与自组装单分子层（SAM）锚定基团发生有害反应导致脱附和漏电的问题，研究开发了一种普适的牺牲配位（SC）策略。通过引入多功能分子，有效防止了SAM在ALD过程中的脱附，成功构建了致密无针孔的氧化物层，阻断了电流泄漏。","scd":null,"kp":[]},{"i":43330,"as":"针对由非金属原子共价配位的单原子催化剂（SACs），密度泛函理论计算表明原有的适用于单原子合金的“10电子规则”不再适用。研究提出全新的“18电子规则”以评估SACs的吸附强度，并建立了一个准原子相互作用模型，成功将其应用于设计碱金属硫属化物电池（如锂硫电池）的高效单原子催化剂。","scd":null,"kp":[]},{"i":43331,"as":"针对纯红色发光CsPbI3钙钛矿纳米晶波长控制不精确和结构不稳定的问题，研究提出一种卤素键辅助合成的卤素工程框架。该策略利用表面I⁻···I₂相互作用，同时解锁了优异的光学特性和结构稳定性，克服了波长、效率与稳定性之间的不利关系，成功制备出高效且稳定的纯红色发光二极管。","scd":null,"kp":[]},{"i":43332,"as":"","scd":null,"kp":[]},{"i":43333,"as":"为解决富镍阴极与锂金属阳极电池中阳离子串扰导致界面失稳和热失控的问题，研究开发了一种基于膦酸盐柱撑高熵MXene（TiVNbMoC₃/Tppm）的隔膜功能层。四膦酸盐配体作为分子支柱将层间距扩大至18.5 Å，实现了高达95%的功能化产率。该隔膜具备离子筛分和阻燃特性，有效抑制枝晶生长并提升电池安全性与能量密度。","scd":null,"kp":[]},{"i":43334,"as":"为克服硬碳负极在高温退火中形成不可及闭孔导致的高平台容量受限问题，研究提出一种氧化-重构策略。通过控制氧化刻蚀打开通道并连通孤立孔隙，随后热重构促使空隙融合，构建出互联的闭孔网络。该结构为准金属钠团簇的成核和存储提供了可及的内部储层，显著提升了硬碳在钠离子电池中的致密存储能力。","scd":null,"kp":[]},{"i":43335,"as":"针对氧化还原活性醌类有机阴极材料在有机电解质中易溶解且引入非活性基团会降低比容量的缺陷，研究提出全活性单元分子设计策略。通过碳-碳单键将两个醌单元连接到高容量的芘-4,5,9,10-四酮核心上，合成了BAPO等分子，同时实现了低溶解度和高比容量，显著提升了锂离子电池有机阴极的循环稳定性。","scd":null,"kp":[]},{"i":43336,"as":"研究开发了一种基于组织集成水凝胶电池的生物电子药物装置，用于心律失常管理。该装置由动态超分子水凝胶构成，实现了与生物组织的无缝免缝合集成（粘附能>200 J m⁻²）。该装置在体内提供0.90-1.17 V的稳定电压输出长达14天，下调炎症生物标志物抑制免疫反应，实现对心脏节律的快速电化学调控。","scd":null,"kp":[]},{"i":43337,"as":"为解决摩擦纳米发电机（TENG）阵列标准并联中存在功率损耗和相位失配导致输出低于线性叠加（1+1≤2）的问题，研究提出一种相位可重构开关策略。通过同步动态网络拓扑和内在电容变化诱导循环电荷复合效应，增强了局部静电感应，使转移电荷和短路电流分别提升了471%和246%，实现了超线性的输出扩展。","scd":null,"kp":[]},{"i":43338,"as":"这篇综述探讨了原子级精确的金属纳米团簇作为分子发射体的光致发光机制。文章重点分析了包括激发、跃迁和弛豫在内的载流子动力学过程，阐明了金属纳米团簇结构及其活性表面的关键作用。此外，探讨了如何基于这些基础理解来设计具有特定光学性质的金属纳米团簇，以及将其作为构建单元的潜在应用。","scd":null,"kp":[]},{"i":43339,"as":"针对水系纤维电池因预涂纤维电极空间利用率低导致体积能量密度不足（<100 Wh/L）的问题，研究开发了一种基于动态沉积化学的无电极纤维电池。该技术将氧化还原活性材料直接溶解在电解质中，消除了传统物理涂层的低效限制，成功解耦了体积能量密度与机械柔韧性，实现了600 Wh/L级别的体积能量密度。","scd":null,"kp":[]},{"i":43340,"as":"针对神经电极长期植入面临的炎症、生物污损和阻抗问题，研究引入了一种兼具生物相容性、抗菌和抗污性能的多功能聚氨基酸界面。该涂层减少了异物反应并保持了神经元的近距离接触。在啮齿动物模型中，功能化电极实现了超过300天的高保真单细胞记录，神经调节质量提升了一个数量级。","scd":null,"kp":[]},{"i":43341,"as":"针对水凝胶在复杂海洋环境中因界面水化和网络降解导致长期水下粘附困难的问题，研究开发了一种能够在天然海水中保持超过900天粘附的自强化水凝胶涂层。该涂层通过多种基底上的协同界面相互作用建立强初始粘附力，并在长期浸泡过程中维持网络完整性，从根本上克服了水引起的降解效应。","scd":null,"kp":[]},{"i":43342,"as":"针对水系氧化还原液流电池中有机二硫化物负极液S-S键断裂/形成缓慢导致严重极化和容量受限的问题，研究提出采用维生素B12（羟基钴胺）作为前催化剂的均相催化策略。通过电化学还原原位生成的分子钴胺(II)双向接受和提供电子，显著加快了硫-硫键的氧化还原反应动力学，提升了电池的长时储能性能。","scd":null,"kp":[]},{"i":43343,"as":"研究提出一种基于氧化铁（FeOx）的光存储器件，用于实时模拟信号处理。该器件能够依靠材料内部的光生电子铁还原过程（Fe³⁺还原为Fe²⁺）形成中性氧空位，从而自动将其状态从负光电导记忆（NPM）转换为正光电导记忆（PPM）。这种材料内自适应动态编码机制有效解决了传统视觉计算需电重置的局限。","scd":null,"kp":[]},{"i":43344,"as":"手性CuO/HgS异质结光催化剂能够实现无添加剂的二氧化碳光催化还原，直接合成具有高附加值的C3化学品丙酮。该技术以手性分子作为对称导向剂合成手性CuO和HgS，有效克服了二氧化碳转化过程中复杂的多电子转移和C-C耦合过程的挑战，为替代传统化石燃料路线合成丙酮提供了可持续的新方法。","scd":null,"kp":[]},{"i":43345,"as":"全固态电池的实际车载应用面临需要高堆叠压力的重大障碍，这通常依赖沉重的金属板，从而降低了模块电池的整体能量密度。文章对比了实际的固态软包电池与传统的液态电池，深入分析了堆叠压力要求的根源，旨在解决高堆叠压力对全固态电池商业化及其在超长续航电动汽车中应用造成的限制。","scd":null,"kp":[]},{"i":43346,"as":"研究人员利用多巴胺粘附的初级氢键和异质金属有机框架缠结的次级配位键，构建了具有跨尺度机械互锁的聚乳酸（CSMI-PLA）纳米纤维膜。这种分级互锁界面设计赋予了材料卓越的机械韧性，使其同时实现了选择性分子筛分、高效颗粒过滤和被动信号获取，在交互式传感防护领域表现出长期的应用潜力。","scd":null,"kp":[]},{"i":43347,"as":"研究人员提出共价界面锚定（CIA）策略，通过将碳纳米管（CNTs）和氧化石墨烯（GO）化学锚定在聚乙烯醇（PVA）网络中，制备出全水合状态下的高强度、高刚度水凝胶微纤维。在该网络中，CNTs负责轴向载荷传递，GO则通过戊二醛介导的PVA-GO缩醛键抑制变形过程中纳米填料的移动，有效解决了传统聚合物网络应力传递效率低的问题。","scd":null,"kp":[]},{"i":43348,"as":"目前高性能有机太阳能电池主要依赖氯仿制备活性层，限制了工业化规模量产。为降低加工过程中的溶剂选择性，研究人员引入固体添加剂2,6-二甲基萘（2,6-DMN）来调控不同溶剂中的成膜动力学和分子聚集。该策略实现了对成膜过程的阶段性控制，成功将有机太阳能电池的光电转换效率提升至接近21%。","scd":null,"kp":[]},{"i":43349,"as":"为解决传统聚合物摩擦层电荷保持时间短的问题，研究人员开发出一种基于三维层级结构二硫化钼（3DH-MoS2）的高功率摩擦纳米发电机。三维二硫化钼不仅具备二维材料的高比表面积和本征电荷捕获能力，还克服了原子层厚度导致发电量过低的缺陷，实现了3DH-MoS2作为耐久且高电荷保持率的摩擦层的大规模可控制备。","scd":null,"kp":[]},{"i":43350,"as":"溶液加工的锡基钙钛矿太阳能电池因活性层厚度受限导致光电转换效率低。研究发现增加厚度会引发垂直晶格应变梯度和加快结晶速度，加剧缺陷形成。为此，研究人员在两步沉积法中引入还原性4,4'-硫代双苯硫酚（TBBT），其巯基与Sn2+形成双齿配位，有效均匀化垂直应变分布，成功制备出具有较厚吸收层的高性能器件。","scd":null,"kp":[]},{"i":43351,"as":"海水中的高浓度氯离子会在电解制氢过程中与析氧反应竞争并腐蚀催化剂。为解决这一问题，研究人员设计了一种球形结构的催化剂，该催化剂由插层碳酸盐的镍铁层状双氢氧化物异质结构成。通过特定的几何设计调节催化剂表面阴离子分布，构建球状静电屏蔽以排斥氯离子，有效提升了海水电解的耐久性。","scd":null,"kp":[]},{"i":43352,"as":"研究提出了一种用于托卡马克中高环向模数环形阿尔芬本征模（TAEs）线性不稳定性分析的物理增强代理模型。该模型基于全局模拟代码GMEC和局部分析代码ETEC生成的数据库，利用局部归一化平衡参数作为输入，训练多层感知器来预测TAEs的实频和增长率，发现局部解与全局解之间存在强相关性。","scd":null,"kp":[]},{"i":43353,"as":"研究使用SOLPS-ITER代码包分析了HL-3开放X型偏滤器（OXD）中碳杂质输运和E×B漂移对脱靶悬崖的影响。研究发现，在低上游分离层密度下，E×B漂移对脱靶的抑制作用更强。OXD的开放结构和大极向磁通膨胀导致了外打击点在低密度下的脱靶悬崖现象，揭示了HL-3 OXD比标准单零偏滤器需要更高密度才能发生脱靶的机制。","scd":null,"kp":[]},{"i":43354,"as":"体积中子源（VNS）托卡马克旨在测试聚变中子对面向等离子体部件的长期影响。目前的辅助加热主要依赖中性束注入（NBI）产生束-靶反应，文章探讨了在小规模聚变反应堆中仅使用波加热来最大化聚变产量的潜力，重点研究了离子回旋共振加热（ICRH）在提升中子产额方面的作用。","scd":null,"kp":[]},{"i":43355,"as":"在燃烧等离子体中测量阿尔法粒子相空间面临重大挑战。由于传统的基于铍杂质的伽马射线光谱（GRS）诊断不适用于使用钨壁的ITER等装置，研究提出使用硼杂质作为靶材料。该工作首次对基于硼的GRS诊断在阿尔法粒子速度空间和轨道空间方面的灵敏度进行了数值评估。","scd":null,"kp":[]},{"i":43356,"as":"研究利用全局动力学-磁流体力学（MHD）代码M3D-K，研究了EAST托卡马克中高阶谐波鱼骨模的线性和非线性动力学。模拟表明，这些模式主要由捕获的高能粒子通过环向进动共振驱动。当高能粒子压力超过临界值时，模式会从鱼骨状模式转变为高能粒子模式（EPM），非线性模拟进一步揭示了不同高能粒子驱动强度下的模式特性。","scd":null,"kp":[]},{"i":43357,"as":"研究人员在粒子轨道追踪代码中实现了一个空间和方向分辨的计算框架，用于分析聚变反应率和合成中子能谱。该模型分离了热、束-热和束-束贡献。在带有中性束注入的HL-3托卡马克等离子体中，束-热反应主导了DD中子产生，占总量的70%–80%，提高束流注入能量可显著增强中子产率。","scd":null,"kp":[]},{"i":43358,"as":"通过磁控共溅射沉积掺杂难熔元素的多组分B2有序钌化铝（RuAl）金属间化合物薄膜，并在800°C快速热退火后保留了晶粒细化至10nm的B2结构。模型拟合与第一性原理计算表明，成分复杂性增加主要由于化学无序和原子势垒 landscape 而非单纯的晶格畸变缩短了电子平均自由程，从而实现了材料的低电阻率缩放。","scd":null,"kp":[]},{"i":43359,"as":"研究报道了一种无需化学试剂的策略，通过波长控制的飞秒激光诱导表面周期性结构（LIPSS）来提升镍电极的析氢反应（HER）性能。在515 nm和1030 nm激光处理下生成了有序的低空间频率波纹和纳米颗粒结构。1030 nm波长处理产生了更高的波纹幅度和表面粗糙度，深刻展示了激光诱导的表面纳米结构对电催化性能的增强作用。","scd":null,"kp":[]},{"i":43360,"as":"为解决二氧化碳加氢制轻质烯烃过程中FeCx催化剂容易被水氧化的问题，研究人员利用氟功能化碳源，制备出限制在氟掺杂介孔碳中的FeCx活性位点。构建的抗水界面有效保护了FeCx。在320°C和3.0 MPa的条件下，该催化剂实现了47.24%的二氧化碳转化率和52.43%的轻质烯烃选择性，轻质烯烃时空产率达36.5 mmol。","scd":null,"kp":[]},{"i":43361,"as":"全无机全蒸发CsPbI2Br钙钛矿光电探测器在高温下面临离子迁移引起的漏电流和界面势垒调制问题。研究揭示了氧化铟锡（ITO）和氧化铟锌（IZO）电极在玻璃和Si/TiN基底上对电荷传输和陷阱-离子相互作用的控制机制。结果表明，选择合适的透明导电氧化物电极可以有效抑制高温运行下的离子迁移，提升器件的运行稳定性。","scd":null,"kp":[]},{"i":43362,"as":"针对慢性糖尿病创口的复杂微环境，研究人员开发了一种淀粉样蛋白增强的透明质酸（HA）复合水凝胶。该材料通过蛋白质-多糖互穿网络构建，其中热诱导的牛血清白蛋白淀粉样原纤维作为增强骨架。这种结构提升了水凝胶的粘弹性和溶胀性能，实现了姜黄素的控释、抗生物膜光热治疗，从而加速了糖尿病伤口的愈合。","scd":null,"kp":[]},{"i":43363,"as":"石墨表面的原子台阶边缘是纳米级能量耗散的主要来源。研究表明，使用线性正构醇处理高度取向热解石墨表面，可以抑制与台阶相关的横向响应。原子力显微镜测量显示，随着烷基链长度的增加，与台阶相关的横向响应指数系统性地下降，证明了通过改变台阶处的局部分子环境可以有效调节并抑制石墨界面处的纳米级能量耗散。","scd":null,"kp":[]},{"i":43364,"as":"提出一种溶剂交换辅助湿退火与盐析策略，制备出PVA-明胶导电水凝胶。通过Li2SO4溶剂置换实现退火与盐析协同，从而修饰内部氢键网络、实现结构致密化并调节结晶度。制得的PGEH-ALi导电水凝胶具备优异的机械性能，抗拉强度达到9.7 MPa，同时兼具高强度、高韧性、超拉伸性和抗冻特性。","scd":null,"kp":[]},{"i":43365,"as":"报道了一种基于动态硼酸酯键的多功能自修复光子弹性体（CLCEred）。该材料具有角度依赖的选择性布拉格反射和显著的机械致变色特性，能够在机械形变下表现出连续且可逆的颜色可调性，将机械形变转化为直观的光学信号，同时克服了传统胆甾相液晶弹性体功能受限且缺乏本征损伤修复能力的缺陷。","scd":null,"kp":[]},{"i":43366,"as":"开发了一种两步法制备Co-Cu双金属ZIF-67@聚多巴胺（PDA）基织物，该工艺包含真空浸渍和PDMS喷涂涂层。制备出的CZPP织物具备快速协同抗菌活性和出色的可重复使用性。研究发现Co-Cu双金属ZIF-67@PDA纳米材料表现出增强的类酶活性，解决了传统防护纺织品杀菌慢、难以重复使用及多功能集成度不足的问题。","scd":null,"kp":[]},{"i":43367,"as":"通过简单的电解质调节策略，向水系锌金属电池中引入了由固体电解质界面（SEI）和静电屏蔽层组成的混合界面。该混合界面在锌阳极上同时建立了基于磷酸锌的SEI层和以NH4+为主的静电屏蔽层，有效诱导了均匀的锌沉积，从而抑制了枝晶生长，解决了锌阳极可逆性低和寿命短的问题。","scd":null,"kp":[]},{"i":43368,"as":"研究表明，同构非金属有机框架可作为有机反应的催化剂，并基于双功能酸/碱机制实现级联催化。缩醛脱保护可与Knoevenagel缩合或Biginelli反应耦合，以高产率生成产物。催化活性高度依赖于N-MOF的孔径尺寸，孔径越宽催化活性越高，凸显了材料的同构组织在催化反应中的关键作用。","scd":null,"kp":[]},{"i":43369,"as":"通过增强附着力，将反铁磁NdTe3原子级薄层（低至单个晶胞）剥离到金膜上，实现直接电学输运测量。磁输运测量显示，原子级薄样品中持续存在Shubnikov-de Haas振荡。尽管样品的残余电阻率比和磁阻相较于块体晶体有所降低，但线性色散载流子特性未被显著改变。","scd":null,"kp":[]},{"i":43370,"as":"研究了结合水的存在对金属有机框架光催化剂SU-101光学性质的调节作用。利用GW近似和Bethe-Salpeter方程结合有限差分法处理激子-声子耦合，发现SU-101中的激子-声子相互作用强烈且对结合水分子高度敏感。结合水的存在与更强的激子局域化相关联。","scd":null,"kp":[]},{"i":43371,"as":"探讨了结合物种多样性与碳储存的“30x30”和“50x50”多目标保护区扩展策略，量化了其有效性、连通性和成本效益。单一标准策略（基于五个分类群或仅基于碳）在当前和未来气候下分别实现了42.3%和68.8%的保护效率。研究指出，实现全球生物多样性和气候目标之间存在协同作用与权衡。","scd":null,"kp":[]},{"i":43372,"as":"研究发现营养饥饿是束毛藻垂直上升的主要触发因素。铁或磷的缺乏抑制了代谢压载，破坏了与气泡升力的平衡，驱使其上升至水面。此外，这种垂直迁移受到光依赖性代谢“安全制动”机制的保护，可防止其不可逆地沉入深海。","scd":null,"kp":[]},{"i":43373,"as":"分析卫星观测和再分析数据发现，连续发生的系列气旋群对北极海冰的长期影响显著。与孤立气旋相比，气旋群对海冰的影响时间延长约2.5倍，并导致海冰密集度（SIC）降幅增加两倍。SIC损失随集群气旋的强度和数量而增加，且2004至2024年间因气旋群导致的冰损失加剧。","scd":null,"kp":[]},{"i":43374,"as":"开发了一种用于灵敏监测植物内源性硫化氢（H2S）的比率型近红外IIb（NIR-IIb）荧光探针。该纳米探针将镧系纳米颗粒与H2S响应分子单元集成，通过吸收竞争诱导发射机制，实现了深层组织穿透和高分辨率成像，有效克服了组织自发荧光干扰，用于非破坏性追踪非生物胁迫下的生物标志物。","scd":null,"kp":[]},{"i":43375,"as":"受天然含线粒体囊泡启发，开发了间充质干细胞衍生的仿生纳米囊泡，其具有高线粒体负载能力。这些纳米囊泡能够通过囊泡表面的晚期抗原-5与病理上调的纤连蛋白相互作用，高效且选择性地将线粒体转移到受损细胞中。通过气道给药，实现对肺纤维化的有效干预。","scd":null,"kp":[]},{"i":43376,"as":"利用冷冻电镜解析了潜在TGFβ结合蛋白-1（LTBP1）与TGFβ共价结合形成的大潜伏复合物（LLC）结构，揭示了TGFβ与LTBP1之间的疏水界面。结构引导的诱变表明该界面对于复合物形成和TGFβ活性至关重要。结构支持LLC中的对侧结构域交换架构。","scd":null,"kp":[]},{"i":43377,"as":"通过对德国农场的家鼠肠道宏基因组进行分析，发现环境变量和牲畜养殖强度解释了27%的抗生素抗性基因变异，而宿主特征仅占8%。研究表明，农业土地利用和牲畜接触驱动了小鼠微生物群中ARG特征，证明了农业实践对自然种群抗性组产生了选择压力。","scd":null,"kp":[]},{"i":43378,"as":"提出“月球洞察”概念框架，旨在利用月球天然熔岩管等地下空间研究月球内部结构和火山历史，深化对月球形成与演化的理解。该框架还将评估这些地下空间对支持未来建立月球基地、实现人类长期驻留、开展科研以及利用资源的重要作用。","scd":null,"kp":[]},{"i":43379,"as":"","scd":null,"kp":[]},{"i":43380,"as":"综述了澳大利亚-印度尼西亚季风（AIM）的演化与机制，强调了第四纪的相关证据与模型研究。研究通过模型评估了海表温度（SST）模式变化和半球间能量平衡的作用，系统分析了大气CO2、北半球冰盖、轨道日照和海平面变化等边界条件的大幅协变对过去AIM降水和环流变化的驱动影响。","scd":null,"kp":[]},{"i":43381,"as":"开发了一种Ag修饰的In2O3光热催化剂，在温和条件（150°C，Xe灯照射）下利用O2将甲烷选择性氧化为甲醇和甲醛。优化后的Ag-3/In2O3催化剂实现了100%的液态含氧化合物选择性，完全抑制了CO2的生成，产率达6544 μmol·g⁻¹·h⁻¹。光生空穴活化C-H键产生·CH3自由基，而O2在富电子Ag上被选择性还原。","scd":null,"kp":[]},{"i":43382,"as":"抗磁场的颗粒铝在微波腔-磁子系统中介导非线性相互作用，实现了三方纠缠。这一研究成果在量子换能器和量子探测领域具有重要应用潜力。","scd":null,"kp":[]},{"i":43383,"as":"在含有溶解Ba产生的溶剂化电子的金属-熔盐溶液中，实现了CO2到CO的转化。不同于传统电化学还原局限于电极-电解质界面，该还原过程贯穿整个熔盐体系。该过程通过液态Ba金属的电沉积及其随后的溶解，持续再生溶剂化电子以维持反应。","scd":null,"kp":[]},{"i":43384,"as":"证明了系统化学掺杂可诱导多次塞贝克系数反转，使得单一聚合物-掺杂剂系统同时实现p型和n型热电发电。动力学蒙特卡洛模拟表明，极性跃迁源于态密度填充与费米能级附近库仑隙打开之间的相互作用，为热电极性反转建立了统一框架并确定了转变条件。","scd":null,"kp":[]},{"i":43385,"as":"研究结合超快时间分辨太赫兹光谱（TRTS）和瞬态微波光电导（TRMC）技术，测量了跨越7个数量级（10^13至10^20 cm^-3）的金属卤化物钙钛矿载流子迁移率。发现Caughey-Thomas模型适用于3D钙钛矿的输运建模，且在载流子密度接近10^19 cm^-3时迁移率开始下降，该效应可通过调整钙钛矿组分来调节。大极化子屏蔽效应延迟了迁移率的衰减。此外，由于带间多载子复合，钙钛矿的载流子寿命在更低的载流子密度下便开始下降。","scd":null,"kp":[]},{"i":43386,"as":"硬碳（HC）是钠离子电池的商业化基准负极材料，但目前基于Na||HC半电池测试得出的醚类电解质优于碳酸酯电解质的结论存在缺陷。研究证实，高反应活性的金属钠对电极产生的化学伪影干扰了测试结果。为此，研究人员构建了无伪影的对称硬碳（HC||HC）电池结构，以剥离并探究硬碳的本征电化学行为。结合核磁共振（NMR）波谱、恒电流充放电及温度依赖阻抗分析，深入揭示了Na离子在硬碳中存储的底层机制。","scd":null,"kp":[]},{"i":43387,"as":"钙钛矿/Cu(In,Ga)Se2（CIGS）串联太阳能电池的性能受限于层间界面的光学和电子损耗。研究人员通过对其中两个关键界面进行精细工程化改造，有效改善了界面介导的载流子输运特性。这一策略成功减少了能量损耗，最终实现了30.57%的认证光电转换效率，并显著提升了器件的运行稳定性。","scd":null,"kp":[]},{"i":43388,"as":"研究在由纳米多孔金属限域的单层二硒化钨（WSe2）中构建了静电激子环栏结构。该结构成功实现了对带电激子的量子限域效应，不仅生成了离散的能级，还实现了局域态与扩展态之间可调节的量子态转变。这为在二维单层半导体中精确控制带电准粒子的行为提供了有效途径。","scd":null,"kp":[]},{"i":43389,"as":"利用纳米多孔单层金属材料的物理特性，研究在单层半导体内部成功实现了对带电准粒子（如激子）的零维（0D）量子限域。该技术为在二维极限下调控和束缚带电粒子提供了全新平台。","scd":null,"kp":[]},{"i":43390,"as":"研究利用社区地球系统模型模拟和多模式集合，发现大西洋经向翻转环流（AMOC）与副极地北大西洋海表温度（SST）之间的关系是状态依赖的。研究确定了三种不同机制：强AMOC伴随典型偶极子指纹；中等AMOC引发放大的副极地SST异常；弱AMOC导致北大西洋信号减弱。这些机制主要源于大气辐射过程的变化，而海洋过程则通过海气相互作用产生间接影响。","scd":null,"kp":[]},{"i":43391,"as":"为实现1.5°C温控目标，研究采用改进的综合评估模型，探讨了人均消费收敛、气候政策严格性与公平性之间的相互作用。结果表明，与高消费未来相比，低消费未来在不同碳价轨迹下可显著降低0.3至1.1°C的升温。减少高收入地区的过度生产与消费、以人类需求为导向组织生产，能有效缓解技术驱动减排的压力。相比之下，地区间收入水平的全球收敛对升温的影响较小。","scd":null,"kp":[]},{"i":43392,"as":"研究利用热带大西洋跨越上新世温暖期的有孔虫结合氮同位素记录，揭示了这一21世纪变暖地质类似期内海洋固氮作用的变化。记录显示，热带北大西洋的固氮作用在上新世晚期减弱，并在更新世晚期显著增加。这种增加主要归因于水体脱氮作用的增强，该过程在全球范围内促成了缺氮、富磷的表层海水。自约280万年前冰川作用加剧以来，固氮强度的变化受地转倾角周期的调控。","scd":null,"kp":[]},{"i":43393,"as":"研究将美国国家海洋和大气管理局风暴事件数据库中111,252条县级事件记录与极端集中度指数（ICE）相结合，评估种族经济集中度对风暴伤亡的预测作用。ICE反映了美国各县内高收入非西班牙裔白人家庭与低收入黑人家庭的相对集中度。多层次零膨胀负二项模型表明，ICE每增加一个五分位数（即高收入白人相对于低收入黑人比例增加），风暴导致的伤亡风险显著改变，证实极端风暴造成的健康负担存在严重且不平等的空间分布。","scd":null,"kp":[]},{"i":43394,"as":"研究开发了一类用于二维电子学的非范德华宽禁带氧化物家族——神冈矿型氧化物A2Mo3O8（A=Zn, Mn, Co等）。通过双控制化学气相沉积策略，实现了面内生长的超薄单晶，厚度小于3纳米，横向尺寸超过100微米。该策略克服了晶格各向同性的内在限制，并能精确控制化学计量比。其中，二维Zn2Mo3O8展现出优异的电子特性，丰富了二维材料库。","scd":null,"kp":[]},{"i":43395,"as":"针对多环芳烃在太空中的观测丰度远超现有星化学模型预测的问题，研究提出了一种由多环芳基自由基介导的快速质量增长路径：芳基加成-脱氢环化机制。通过1-和2-萘基自由基与联苯、萘的高温反应作为概念验证，证明了在气相中可通过[3+2]锯齿边缘和[4+2]碳湾闭环反应，生成苯并[b]三亚苯等五环多环芳烃。反应产物利用可调谐真空紫外光电离技术实现了同分异构体的选择性识别。","scd":null,"kp":[]},{"i":43396,"as":"","scd":null,"kp":[]},{"i":43397,"as":"研究提出了一种实现二维高阶拓扑金属的实验方法，并在声子晶体中成功演示。不同于存在体带隙的传统拓扑绝缘体，该二维拓扑金属在没有体带隙的情况下展现出拓扑边界态。研究通过空气声学实验明确证实了金属体态、带隙反手性边缘态以及连续谱中的拓扑角态的存在，填补了高阶拓扑金属系统实验研究的空白。","scd":null,"kp":[]},{"i":43398,"as":"研究通过向列介晶相衍生出的受限各向异性分子介质，在电场驱动下引发对称性破缺转变，成功生成了微米级的手性风车结构。该方法打破了非手性分子组装空间受限和稳定性差的局限，将纳米级的无手性前驱体转化为微米级手性结构，提供了一条简单且可规模化制备宏观手性光学材料的新途径。","scd":null,"kp":[]},{"i":43399,"as":"研究在钆镓石榴石（Gd3Ga5O12）中探究了相干光模式与顺磁自旋集合（有限多能级系统）之间的超强耦合。通过磁场调节Gd3+离子的电子顺磁共振，使其与法布里-珀罗腔模式发生共振，成功产生了自旋-光子杂化态（塞曼极化激元）。这表明顺磁系统为在凝聚态中探索传统量子光学中的Dicke物理提供了新平台。","scd":null,"kp":[]},{"i":43400,"as":"研究构建了一个将对称性归约整合到物理信息神经网络（PINNs）中的计算框架，用于分析非线性偏微分方程（PDE）中的对称性驱动动力学。通过辅助网络学习时间相关变换，使解在对称性不变的缩放坐标中保持平稳，并推断波速等对称参数。该方法生成带有代数约束的微分代数方程（DAE）系统，有效解决了传统PDE/ODE求解器在处理高指标DAEs时失效的计算难题。","scd":null,"kp":[]},{"i":43401,"as":"研究提出了一种脉冲电催化策略，利用时间调制和N,O双配位的Fe单原子催化剂（FeN2O2 SAC），将4-氯苯酚（4-CP）顺序转化为对苯醌（p-BQ）。有别于传统连续电解，脉冲催化在时空上解耦了阴极脱氯和阳氧化过程，精确控制瞬态中间体。原位波谱和密度泛函理论表明，脉冲极化驱动了动态氯配位过程，实现了对卤代污染物高选择性转化为高附加值化学品的精准调控。","scd":null,"kp":[]},{"i":43402,"as":"神经流形是由大量脉冲神经元群体构成的低维几何形状。研究指出，这种大脑内在的群体几何结构可以由电子物理器件进行直接模拟。通过硬件物理实体化神经网络几何结构，能够在无需复杂训练的前提下实现高效且极低能耗的预测计算，为神经形态计算提供了新范式。","scd":null,"kp":[]},{"i":43403,"as":"研究展示了一种全范德华纳米光子平台，利用由高折射率半导体包围的空气腔形成的Mie空腔（Mie voids）来控制纳米级光发射。Mie空腔在其附近区域暴露出强电磁场以增强单层二硫化钨（WS2）激子的发光强度，同时通过干涉共振塑造定向发射。通过电磁仿真确定了空腔的几何参数，实现了兼具高发光强度和定向辐射的二维激子光源，在固态照明和量子光源领域具有应用潜力。","scd":null,"kp":[]},{"i":43404,"as":"研究开发了一种在MnOx-Fe2O3上具有原子级分散Ti的催化剂，在含湿和含硫条件下实现高效CO氧化。原子级分散的Ti接收来自O 2p轨道的电子，重新分布并稳定特定O 2p态，强化了CO吸附，并通过类Mars-van Krevelen机制促进晶格氧活化，将表观活化能降至64.59 kJ/mol。同时，Ti-O-Fe界面削弱了水/二氧化硫的吸附，赋予了催化剂出色的抗H2O/SO2中毒能力，为低成本环境催化提供了新方案。","scd":null,"kp":[]},{"i":43405,"as":"为解决传统机器视觉系统体积庞大和高延迟问题，研究开发了一种基于具有轴向缺陷梯度的氧化锌纳米线阵列的平面各向异性光电阻变存储器（AORRAM）。该器件克服了现有神经形态视觉传感器丢失深度信息、探测角度窄且缺乏3D运动处理能力的缺陷。结合宽视场和单目配置，该系统能够在传感器内部直接进行高效且低能耗的单目3D运动感知与空间定位，极大优化了动态自主系统的硬件架构。","scd":null,"kp":[]},{"i":43406,"as":"研究在室温下对具有结构各向异性的非晶合金薄带进行阶梯式拉伸蠕变测试，以探测其微观缺陷。研究发现了一种非线性应变响应：分段增加的应力会导致蠕变应变先减小后增加。在循环蠕变中，部分应变分量在应力消除后迅速恢复，而其他则不然。仅第一个循环表现出慢于蠕变的应变恢复，随后的循环则具有可逆的应变分量。这种非线性和缓慢恢复特征被证实与金属玻璃中淬火产生的剪切转变区密切相关。","scd":null,"kp":[]},{"i":43407,"as":"针对水系锌溴电池中溴物种的扩散、交叉和易水解问题，研究提出一种使用七水硫酸锌和尿素的配体辅助极低溶剂化电解质。尿素的高溶解度抑制了水分活性，且其对溴的亲和力强于水分子，从而实现优先配位。这种协同作用构建了准无溶剂微环境，限制了溴的溶剂化和扩散，形成稳健的准固态正极，并通过抑制水解稳定了Br+物种。该锌溴电池展现出优异的可逆性。","scd":null,"kp":[]},{"i":43408,"as":"传统成像系统存在厚度限制，研究通过使用直接放置在图像传感器上的12.2微米厚介电薄膜，成功突破了这一限制。该系统完全消除了透镜和自由空间。通过工程化非局部法布里-珀罗共振，使光在薄膜表面扩散并发生相长干涉，为每个物点分配独立孔径，从而绕过了传统光学中的单孔径假设。实验验证了该系统能实现确定性的、免计算的二维成像。","scd":null,"kp":[]},{"i":43409,"as":"研究通过二维材料异质结构的界面设计，开发出一种基于MoS2的光电突触器件。该器件能够在-190°C至450°C（跨度达640°C）的极端温度范围内运行，并具有可调的神经形态功能。在450°C下，该器件实现了可见光探测，填补了高温光学传感器的光谱空白。此外，该器件表现出高度可调的突触可塑性，解决了极端环境下智能视觉硬件的热生存能力瓶颈。","scd":null,"kp":[]},{"i":43410,"as":"染色体外DNA(ecDNA)常携带癌基因并在癌细胞中形成核簇以促进过表达。研究利用最小化聚合物物理模型，在单分子层面探究了ecDNA的BRD4结合位点与BRD4分子的相互作用。结果表明，BRD4诱导ecDNA凝聚体发生相分离，形成富含特定区域（如PVT1-MYC融合）调控接触的反式关联接触域(I-TADs)。该机制超越了单纯的拷贝数效应，解释了ecDNA优先转录和癌基因上调的现象。","scd":null,"kp":[]},{"i":43411,"as":"研究提出IMoveLab方法，将生物力学先验知识整合到状态估计滤波器中，利用自由度之间的耦合以及肌肉-肌腱单元的弹簧特性进行递归状态校正。与双平面X射线摄影（骨骼运动的黄金标准）对比评估发现，该方法使现代状态估计滤波器的准确度达到了基于标记的膝部追踪水平。IMoveLab进一步提高了精度，并在长时间试验中实现了无漂移的下肢运动学追踪。","scd":null,"kp":[]},{"i":43412,"as":"研究报道了一种基于水簇解离的水跨膜传输机制，并开发了具有多羟基季铵化界面的高渗透性纳滤膜。原位液相飞行时间二次离子质谱和分子动力学模拟表明，膜孔入口的羟基和季铵基团能够从热力学和动力学上促进较大的水簇(如(H2O)5H+)解离成较小的物种(如(H2O)3H+)。这种功能化设计有效调节了受限纳米通道中的水分传输过程，显著增强了水的渗透性。","scd":null,"kp":[]},{"i":43413,"as":"研究基于莫特忆阻器构建了人工神经流形，能够在减少所需样本数量的同时实现准确且稳健的预测。通过构建人工神经元电路，获得了类似于生物神经元的钟形调谐曲线。该曲线将大规模的神经元放电汇聚成紧凑的低维流形结构。这种结构满足延迟嵌入定理，从而建立时空信息表征，有效填补了现有神经形态工程中忽略集体活动流形结构的空白。","scd":null,"kp":[]},{"i":43414,"as":"研究提出了一种严谨的理论，证明单个神经元可以通过简单的局部突触可塑性规则学习提取线性序列中物品的排序。该模型解释了人类大脑从线性顺序中产生认知地图的数据，说明了传递推理中的末端项效应，并支持在新证据出现时快速重构内部表征。理论还解释了大脑中线性顺序神经表征的二维投影呈现弯曲而非线性的现象。该模型仅需局部突触相互作用。","scd":null,"kp":[]},{"i":43415,"as":"质谱成像(MSI)是绘制生物分子空间分布的关键工具，但面临着空间分辨率、化学细节和采集时间之间的权衡限制。文章综述了质谱成像与机器学习及人工智能计算方法的融合进展。研究重点介绍了MSI实验的关键步骤，总结了主要的ML/AI范式，并详细回顾了ML/AI如何加速并影响MSI工作流程中的各个环节，从而有效应对上述固有的性能权衡挑战。","scd":null,"kp":[]},{"i":43416,"as":"","scd":null,"kp":[]},{"i":43417,"as":"","scd":null,"kp":[]},{"i":43418,"as":"","scd":null,"kp":[]},{"i":43419,"as":"","scd":null,"kp":[]},{"i":43420,"as":"","scd":null,"kp":[]},{"i":43421,"as":"","scd":null,"kp":[]},{"i":43422,"as":"","scd":null,"kp":[]},{"i":43423,"as":"研究利用先进的电子显微镜和光谱技术，追踪了在H2和O2直接环氧化丙烯反应中，负载在多级孔TS-1沸石上的金纳米团簇受反应驱动的结构演变。综合表征和催化分析表明，这些结构转变是由金纳米团簇、反应物及中间体之间复杂的相互作用主动驱动的。该研究揭示了反应条件下金催化剂结构的动态变化及其对催化性能的影响，超越了传统的静态合成参数优化。","scd":null,"kp":[]},{"i":43424,"as":"糖苷键形成的立体选择性控制一直是有机合成的重大挑战。为了在不受溶剂、反离子等外部环境干扰的情况下分离出驱动立体选择性的内在因素，研究在气相条件下完全孤立地探测了半乳糖的离子-分子半乳糖基化反应。通过在质谱仪的离子阱中进行反应，并利用质谱分辨的紫外冷离子光谱直接探测产物的立体化学，研究成功阐明了糖基化反应在SN1-SN2连续机制中的内在立体选择性驱动因素。","scd":null,"kp":[]},{"i":43425,"as":"研究开发了一种铜/有机硼协同催化系统，实现了对天冬氨酸侧链的直接且选择性激活。该系统在Asp-His基序中形成Lys-Asp异肽键，反应在中性水相条件下进行。该方法克服了传统天冬氨酸侧链反应性低、易形成天冬酰亚胺以及难以在化学性质相似的其他羧基（如谷氨酸侧链和C末端）之间实现位点选择性的挑战。系统表现出对包含所有天然氨基酸的未保护多肽的广泛兼容性。","scd":null,"kp":[]},{"i":43426,"as":"研究以商品化H8-BINOL为原料，开发了一种实用且通用的D4对称手性酞菁合成路线。这种模块化方法能够系统性地构建多种手性架构，用于研究取代基如何控制超分子组装。研究发现，通过简单的结构修饰即可预测性地调控酞菁的聚集行为。结合单晶X射线衍射分析，研究人员设计了特定的非共价相互作用，促进了自发且高度选择性的聚集，从而成功实现了近红外圆偏振发光。","scd":null,"kp":[]},{"i":43427,"as":"","scd":null,"kp":[]},{"i":43428,"as":"厌氧一氧化碳脱氢酶(CODH)的活性中心C-cluster是一个[NiFe3S4]-Fe簇，尽管研究数十年，其电子结构和金属氧化态依然模糊。研究合成了具有[NiFe3S4]3+/2+/1+核心的模型簇，并结合晶体学、光谱学、磁性和计算进行了详细表征。研究发现，最高氧化态[NiFe3S4]3+最合理的描述是包含Ni2+和三个Fe3+。然而，X射线吸收光谱等证据揭示了这些簇在特定状态下存在反常的价态分布特征。","scd":null,"kp":[]},{"i":43429,"as":"冠醚的离子选择性传统上被归因于离子半径与其名义空腔大小的匹配。然而，该概念忽略了冠醚的构象灵活性。为深入理解冠醚与碱金属离子结合的内在结构，研究利用低温气相红外光谱结合非谐振CH键伸缩振动区域分析，对不同环大小的冠醚进行了系统研究。CH键伸缩区作为敏感探针，揭示了冠醚的内在结合构象，从而将冠醚的构象特征直接与离子选择性相关联，提供了包结过程的统一分子图景。","scd":null,"kp":[]},{"i":43430,"as":"研究开发了一种通过臭氧分解和铁催化将烯烃中的C(sp3)–C(sp2)键转化为C(sp3)–B键的脱烯基化硼化反应。该反应条件高效且能容忍广泛的官能团。机理研究表明，双(儿茶酚合)二硼烷(B2cat2)在此过程中兼作硼源和化学计量还原剂。研究通过将该反应直接应用于天然存在的类固醇和萜类化合物，成功实现了含硼中间体的转化，展示了其在复杂天然产物修饰中的合成实用性。","scd":null,"kp":[]},{"i":43431,"as":"基于螺烯的圆偏振多重共振热活化延迟荧光(CP-MR-TADF)发射体结合了手性和窄带发射特性，但向长波长扩展常伴随光谱变宽和构型稳定性下降。研究引入一种正交B−π−B拓扑结构的全六元环稠合BN[7]螺烯框架，成功解决了上述问题。该结构设计不仅实现了窄带发射，还赋予了分子极强的构型稳定性，非常适合用于圆偏振有机发光二极管(CP-OLEDs)，以减少对偏振组件的依赖。","scd":null,"kp":[]},{"i":43432,"as":"靶向蛋白降解(TPD)技术面临设计困难和可靶向E3泛素连接酶数量有限的挑战。研究从头设计了一种异双功能蛋白质，用于触发常见癌症靶标蛋白的降解并实现预期的表型输出。研究中开发了一种高度稳定且适应性强的螺旋-转角-螺旋支架，用于呈递多个结合位点。该人工设计的蛋白质能够有效引导目标蛋白进入降解机制，为靶向蛋白降解提供了一种全新且高效的合成分子工具。","scd":null,"kp":[]},{"i":43433,"as":"研究通过氧空位(OV)工程和单原子锚定策略，打破了氧化铟(In2O3)纳米晶体的本征中心对称性，制备出具有有效压电特性的富氧空位铜单原子锚定氧化铟(CuSA-In2O3-x)。基于声压电催化作用，该材料能够生成多种活性氧、氧气和一氧化碳，并消耗乳酸和谷胱甘胺。这种压电势驱动的能带倾斜和载流子分离有效克服了带结构限制，在多催化声动力-免疫联合治疗中展现出巨大潜力。","scd":null,"kp":[]},{"i":43434,"as":"为克服脂质纳米颗粒（LNP）递送mRNA在肿瘤治疗中存在的肝脏趋向性及内体逃逸效率低的问题，研究人员开发了一种名为SiLNP的可裂解硅基醚生物正交激活平台。该平台的可电离脂质掺入了硅基醚结构，能对苯丙氨酸三氟硼酸盐（Phe-BF3）触发剂产生响应。该系统利用肿瘤中高表达的LAT-1转运蛋白将Phe-BF3主动输入肿瘤细胞，实现肿瘤特异性的激活和胞质mRNA释放。","scd":null,"kp":[]},{"i":43435,"as":"研究开发了一种将分子水氧化催化剂与光吸收材料耦合的策略，用于太阳能驱动的水分解。该策略通过自组装在铋酸钒（BiVO4）光电极上形成双层结构，集成了基于钌配合物（Ru-tda）的分子水氧化催化剂。同时，自组装过程还整合了氧化还原介体（Ru-bpy），加速了空穴从BiVO4向分子催化剂的转移，从而显著提升了催化效率。","scd":null,"kp":[]},{"i":43436,"as":"研究提出了一种利用亚胺硼酸盐化学对DNA折纸进行可逆功能化的新策略。带有2-甲酰基苯硼酸基团的聚乙二醇和胆固醇分子，可以高效地与展示有α-效应胺基的DNA折纸结合。这种基于动态共价化学的方法结合了共价键的稳定性与温和条件下的可逆交换特性，为调控DNA纳米结构提供了具适应性且生物相容的途径。","scd":null,"kp":[]},{"i":43437,"as":"研究证明在刚性微孔阴离子交换膜中，可以通过拓扑离子节点调节局部传输能量来加速氢氧根离子的传输。在无醚聚芳基哌啶鎓骨架中引入六苯基苯（HPB），产生了互连的微孔性，并在孔壁内空间关联多个阳离子位点。密度泛函理论分析表明，HPB通过平滑局部能量分布，减弱了氢氧根的结合，并降低了离子在位点间的跃迁能垒。","scd":null,"kp":[]},{"i":43438,"as":"研究开发了一种基于氧化还原解耦策略的单池串联流动电化学反应器，实现了无金属的普遍性脱硼-氘化反应。该系统将传统的取代脱硼-氘化过程分离为连续的电化学步骤，以重水（D2O）作为高性价比的氘源，能够对包括硼酸、硼酸酯在内的100多种烷基、芳基和烯基有机硼化合物进行高效氘化标记。该设计解决了传统流动电池架构及动力学不匹配的限制。","scd":null,"kp":[]},{"i":43439,"as":"研究使用一种具有空间位阻的手性Grubbs催化剂，实现了高自聚倾向单体之间的催化交替共聚。该催化剂含有给电子型的C-Ru键，其左右两侧的空间位阻差异促使每一次有效的复分解反应交替在两侧发生。这一发现成功突破了交替共聚通常需要使用难以自聚单体的限制，实现了环丁烯与降冰片烯的交替共聚。","scd":null,"kp":[]},{"i":43440,"as":"","scd":null,"kp":[]},{"i":43441,"as":"研究首次实现了由镍(II)催化的β-亚甲基C(sp3)-H键的对映选择性炔基化反应。该反应利用空气稳定的镍盐和体积较大的手性磷酸配体(R)-TCYP，合成了多种β-炔基化酰胺，产率高达98%，对映体过量达99%。该催化系统能够在甲基存在的情况下优先活化亚甲基C-H键，克服了脂肪族C-H键官能化中位点选择性的内在限制。","scd":null,"kp":[]},{"i":43442,"as":"","scd":null,"kp":[]},{"i":43443,"as":"","scd":null,"kp":[]},{"i":43444,"as":"","scd":null,"kp":[]},{"i":43445,"as":"","scd":null,"kp":[]},{"i":43446,"as":"","scd":null,"kp":[]},{"i":43447,"as":"","scd":null,"kp":[]},{"i":43448,"as":"","scd":null,"kp":[]},{"i":43449,"as":"","scd":null,"kp":[]},{"i":43450,"as":"原位聚合技术因其与现有钠离子电池制造工艺兼容且具备可扩展生产的潜力，成为解决固态聚合物电解质室温离子传输受限及电极接触不良等问题的有效途径。文章总结了钠电池原位聚合技术的优缺点、聚合引发条件与机制、制备策略及最新进展，强调了其在解决传统液态电解质安全性隐患方面的重要作用。","scd":null,"kp":[]},{"i":43451,"as":"为降低钙钛矿太阳能电池中金电极的高成本，研究在低成本金属（铝、银、铜）下方引入5纳米的铬中间层以抑制金属间相互扩散。其中，Cr/Al电极器件实现了高达24.7%的光电转换效率，并在光热应力下表现出与金电极器件相当的运行稳定性，且原材料成本大幅降低了五个数量级。此外，研究还指出了半透明前电极中铟锡氧化物（ITO）的铟扩散是导致降解的关键因素。","scd":null,"kp":[]},{"i":43452,"as":"研究开发了一种用于宽温域锂金属电池的凝胶聚合物电解质（NSP-GPE），采用了独特的动态“释放-拉动”设计。该电解质基于碳酸丙烯酯（PC），同时具备弱Li+-聚合物和弱Li+-PC配位。由酰胺基团和磺酰基团协同离域π电子转移产生的弱Li+-聚合物配位，赋予了该凝胶聚合物电解质优异的动态锂离子传输能力。","scd":null,"kp":[]},{"i":43453,"as":"氟离子电池因其潜在的高能量密度而备受关注，但其在基础科学与实际性能之间存在较大差距。文章指出，转换型电极的严重体积膨胀、固体电解质中氟离子迁移率低以及亚稳态电极-电解质界面是限制电化学可逆性和循环寿命的关键瓶颈。此外，评估方法和机制描述符缺乏共识也阻碍了不同研究间的直接比较。综述探讨了这些核心科学挑战。","scd":null,"kp":[]},{"i":43454,"as":"研究揭示了纳米级粘附配体间距与基质硬度协同作用，通过粘着斑介导的染色质重塑调节间充质干细胞的衰老。在硬水凝胶上，较宽的配体间距（150 nm）会加速细胞衰老，而在软水凝胶上则能缓解衰老。配体间距和基质硬度通过粘着斑组装调节细胞行为，增强的粘着斑放大了应力纤维产生的牵引力，并影响核被膜及相关机制。","scd":null,"kp":[]},{"i":43455,"as":"研究通过海藻酸盐诱导的液晶组装与快速冰核驱动致密化技术，成功制备出一种超轻的MXene-石墨烯气凝胶。该气凝胶展现了从纳米尺度到宏观多孔网络的各向同性纳米片排列。这种各向同性结构框架在干燥过程中均匀化了毛细管应力，使得气凝胶能够在常压下进行制备，并具备超低密度。","scd":null,"kp":[]},{"i":43456,"as":"研究揭示了金属ns2孤对电子的立体化学在调节激子特性和实现二维金属卤化物钙钛矿激光方面的关键作用。通过研究一系列含有铅、锡或锗的二维钙钛矿材料，确定了将孤对电子活性与激子-声子耦合及激子-激子湮灭联系起来的关键结构描述符，成功在单层二维钙钛矿中实现了稳健的激光发射。","scd":null,"kp":[]},{"i":43457,"as":"研究探讨了帕金森病患者在奖励学习任务中的探索-利用权衡机制。未服药患者的学习和决策能力表现出明显缺陷，具体特征为过度探索（过度尝试新选项）和利用不足（重复选择曾获得奖励的选项）。通过应用高斯过程-上置信界（GP-UCB）模型，研究阐明了多巴胺耗竭影响定向探索而非随机探索的内在计算机制。","scd":null,"kp":[]},{"i":43458,"as":"研究发现枯草芽孢杆菌的生物膜形成与孢子形成并非线性路径，而是分支路径。首先启动孢子形成的一个亚群通过酶的顺序作用分解脂磷壁酸，释放出毫摩尔浓度的甘油。这些甘油通过破坏细胞壁合成和细胞质pH值来阻碍孢子形成。这种代谢物形态发生素协调了基因相同种群内的多细胞发育和细胞功能的多样化。","scd":null,"kp":[]},{"i":43459,"as":"研究提出了一种基于冷大气等离子体（CAP）的非药物生物物理免疫调节策略，用于重编程肿瘤相关中性粒细胞。CAP同时传递活性氧和氧化还原信号，抑制线粒体自噬，恢复中性粒细胞的线粒体膜电位和氧化代谢，使其从免疫抑制表型转变为免疫刺激表型。在同基因和人源化膀胱癌模型中，膀胱内注射CAP重塑了肿瘤微环境并恢复了抗肿瘤免疫。","scd":null,"kp":[]},{"i":43460,"as":"研究探讨了非遗传因素对遗传病发病和严重程度的影响，以达里埃病（DD）为研究对象。该病由ATP2A2变异导致内质网钙泵SERCA2单倍剂量不足引起。对DD患者表皮角质形成细胞的代谢分析显示，其负责再生抗氧化剂的戊糖磷酸途径出现异常，伴随游离谷胱甘肽减少和蛋白质谷胱甘肽化修饰增加。这表明对压力的代谢适应失败导致了细胞粘附缺陷。","scd":null,"kp":[]},{"i":43461,"as":"研究揭示了出生后肠道内γδ T细胞的时间分化程序。出生后第一周，肠道γδ T细胞上调了T细胞活化和3型免疫相关基因；断奶后则以效应功能、1型免疫和细胞毒性相关基因的诱导为主，此时期细胞保护肠道免受真菌感染。在成体肠道中，产生白介素17的γδ T细胞展现出Tbet依赖的1型免疫特征和增强的T细胞受体信号。研究还在新生儿肠道中发现了类似细胞群。","scd":null,"kp":[]},{"i":43462,"as":"研究利用原子级成像技术分析了金纳米球上铜的晶种介导生长过程，合成了由有序金属间相和无序合金组成的Janus表面双金属纳米晶体。生长初期，铜前体实现均匀沉积，随后发生相互扩散形成超薄Au1Cu1金属间壳层。之后生长演变为不对称模式，铜优先在单一活化位点沉积，最终形成特定的Au-Cu双金属结构。","scd":null,"kp":[]},{"i":43463,"as":"转录因子结合常受核小体阻碍，而先锋因子能识别被覆盖的基序并启动染色质开放。研究发现，在体外缺乏核小体结合能力的细菌转录因子LexA，在酵母中表达时能迅速侵入定位良好的核小体。这表明转录因子可利用体内的核小体动态变化来接近封闭位点。此外，这种由LexA介导的染色质开放过程不依赖于DNA复制。","scd":null,"kp":[]},{"i":43464,"as":"波形蛋白在细胞机械感知和应激反应中起关键作用，其半胱氨酸C328是氧化剂和亲电试剂重塑丝质的核心热点。研究证实，C328修饰及引发的波形蛋白重组受pH值调控。细胞内酸化会阻止该网络破坏，而碱化则会加剧由氧化和亲电子物质引起的破坏。利用化学生成和光遗传学手段调节pH，可实现对该过程的空间时间控制。","scd":null,"kp":[]},{"i":43465,"as":"研究比较了欧洲、北美和亚洲真实人群密集场景下的人机交互（HRI）与人人交互（HHI）。在所有人群密度下，两者的局部运动模式（速度、加速度和加加速度）高度一致。但在空间距离上存在差异，该差异随机器人速度呈近似线性增长，并在拥挤环境下减弱。在包含较快导航机器人的数据集中，行人会保持更大的避让距离。","scd":null,"kp":[]},{"i":43466,"as":"研究利用441个树木年轮序列重建了1625年以来准噶尔核心区的草原生产力变化。记录表明，准噶尔汗国的崩溃恰逢1751至1761年间过去四个世纪中草原生产力的最低谷。社会复原力的减弱放大了生产力急剧下降的影响，引发了饥荒、冲突和贸易崩溃。随后天花再次出现并演变成灾难性流行病，最终促成了汗国的崩溃。","scd":null,"kp":[]},{"i":43467,"as":"直流生物电信号在细胞形态发生、免疫反应和愈合中起关键作用。为解决直流电刺激设备的标准化和可重复性难题，研究提出了SCHEPHERD电生物反应器。该平台集成了八个刺激通道和模块化插件，可进行包括细胞、单细胞层和3D细胞球在内的多种电趋化分析。参数扫描证实，直流电场如同细胞迁移的“方向盘和油门”，有效控制细胞行为。","scd":null,"kp":[]},{"i":43468,"as":"","scd":null,"kp":[]},{"i":43469,"as":"为描述由三个或更多个体组成的群体交互动态系统，研究提出了一种名为“ℓ-超边近似”的分析框架，专门用于规则超图上的随机过程。该框架适用于每个个体属于k个大小为ℓ的群体的规则超图结构，能够有效解析复杂的高阶网络交互动态。","scd":null,"kp":[]},{"i":43470,"as":"研究结合双标记镶嵌分析和胼胝体追踪技术，解析了胚胎期大脑皮层放射状胶质祖细胞的谱系演变。结果显示，多能祖细胞在神经发生开始时同时产生端脑外和端脑内投射神经元的平行亚谱系。端脑外神经元仅通过消耗性小谱系产生，而端脑内神经元则通过产生大跨层输出的谱系生成。多能谱系呈现固定的群体级演变规律。","scd":null,"kp":[]},{"i":43471,"as":"SARS-CoV-2核衣壳（N）蛋白是一种免疫拮抗剂。研究表明，N蛋白以刺激特异性方式放大细胞外RNA感知并抑制细胞内RNA感知。这一特征通过不同机制存在于致病性乙型冠状病毒中。相互作用网络显示，Delta变异株的N蛋白通过与cGAS等蛋白结合驱动炎症。这揭示了N蛋白在巨噬细胞介导的细胞因子风暴中引发过度炎症和血管渗漏的作用机制。","scd":null,"kp":[]},{"i":43472,"as":"为解决肝脏组织工程中血管重建的瓶颈，研究将诱导多能干细胞（iPSC）来源的肝母细胞和内皮细胞整合到具有血管涂层剂（VCA）的去细胞支架中，构建了血管化肝脏类器官。空间转录组学证实，IGF2-IGF1R-AKT/MAPK信号轴是控制类器官空间组织和功能成熟的关键。外源性IGF2与VCA协同作用，显著增强了类器官的结构和再生潜力。","scd":null,"kp":[]},{"i":43473,"as":"传统手性光学技术通常只能测量系综平均值，掩盖了单颗粒差异。现有的单颗粒圆二色性光谱也局限于强度检测，缺失相位信息。研究提出了一种基于表面余弦波（SCWs）的双参数手性传感平台，能在单颗粒水平上同时捕捉振幅和相位不对称性。SCWs构建了振幅相等的左右圆偏振干涉场，实现了精确的纳米级手性检测。","scd":null,"kp":[]},{"i":43474,"as":"研究利用1946至2008年间内战和州际战争的详细数据，分析了武装冲突的升级动态与战争规模的关系。结果显示，冲突内部战斗强度的变化（即升级动态）是导致大规模冲突的主要机制。内战在达到极大规模后趋于降级，从而限制了其总体严重性；而州际战争则表现出持续升级的风险。简单的冲突严重性模型成功解释了这种区别。","scd":null,"kp":[]},{"i":43475,"as":"不完全免疫重建（IIR）影响10%至40%的HIV感染者。研究基于中国31个省份21862名患者的纵向数据，利用贝叶斯联合建模开发了动态预测系统DJPSIIR。该系统整合了连续的CD4+ T细胞计数、CD4/CD8比值与临床参数，用于生成实时风险预测。评估表明，DJPSIIR表现出强大的判别性能，受试者工作特征曲线下面积达到0.8以上。","scd":null,"kp":[]},{"i":43476,"as":"“食雪热浪”引发急速融雪，会导致洪水和雪旱。研究利用1850至2015年的气温数据和融雪模型，开发了识别食雪热浪的方法。结果显示，融雪季热浪通常持续3至5天，发生3至5次，使融雪率增加一倍。11次春季特大洪水中有7次与食雪热浪同时发生。自1850年代以来，美国西部的食雪热浪呈现出明显的频发趋势。","scd":null,"kp":[]},{"i":43477,"as":"研究探讨了2型糖尿病中骨骼肌与全身葡萄糖稳态之间的相互作用。高表达乳酸脱氢酶A（Ldha）的骨骼肌导致循环乳酸水平升高，这与高血糖症密切相关。出乎意料的是，敲除骨骼肌中的Ldha会通过加剧肝脏糖异生来破坏全身葡萄糖稳态。机制上，骨骼肌中的组蛋白H3K18乳酸化通过白细胞介素-6（IL-6）介导的器官间通讯，抑制了肝脏糖异生。","scd":null,"kp":[]},{"i":43478,"as":"为克服牙周屏障对药物递送和杀菌的限制，研究人员开发了一种配备金纳米刺的磁驱动离子凝胶微机器人。该微机器人通过在抗菌离子凝胶微球中包载姜黄素，并进行不对称磁性沉积和纳米刺功能化制备而成。它能在粘性介质中进行精确的磁导航，穿透模拟粘液，增强牙周滞留，并通过机械方式破坏生物膜，实现靶向牙周炎治疗。","scd":null,"kp":[]},{"i":43479,"as":"为了解效应激酶CHK1在复制叉处的局部调控机制，研究发现复制终止因子2（RTF2）对维持复制叉处的CHK1信号至关重要。RTF2与CHK1相互作用，并与复制解旋酶复合体相互作用蛋白CLASPIN协同工作，将CHK1系扎在DNA复制位点。这一精确的定位机制有效控制了复制速率，并防止了细胞过早进入有丝分裂期，确保S期正常推进。","scd":null,"kp":[]},{"i":43480,"as":"酪氨酸激酶抑制剂达沙替尼常用于白血病治疗。研究发现，达沙替ib会选择性地破坏B细胞的体外趋化性，但不影响T细胞。在体内，它会导致外周淋巴结中T细胞的细胞间运动和活化出现大幅但短暂的减少。这一发现揭示了达沙替尼在引发脾脏收缩和淋巴细胞增多之外，对淋巴结内的淋巴细胞监测和激活过程具有可逆的抑制作用。","scd":null,"kp":[]},{"i":43481,"as":"为解决植入式细胞疗法面临的宿主免疫排斥问题，研究开发了一种基于海藻酸盐包裹视网膜色素上皮细胞的免疫调节疗法。这些被包裹的细胞可持续分泌细胞因子，在植入物微环境中进行局部免疫调节。在啮齿动物模型中，局部产生白细胞介素-10（IL-10）或IL-12有效防止了针对海藻酸盐胶囊的异物反应。其机制在于降低了促纤维化基因的表达，并调节了巨噬细胞和T细胞。","scd":null,"kp":[]},{"i":43482,"as":"光调节WD（LWD）蛋白对维持拟南芥精确的生物钟至关重要。为揭示其作用机制，研究人员利用TurboID技术，在三个时间点系统性地鉴定了219个与LWD1相互作用的蛋白伴侣。这一基于LWD1相互作用组的分析，成功发现了此前未被描述的生物钟调节因子，并深入阐明了LWD蛋白调控生物钟基因表达的具体分子机制。","scd":null,"kp":[]},{"i":43483,"as":"研究通过临床试验和动物实验评估了利拉鲁肽对脑-肾轴的影响。临床发现，利拉鲁肽能降低健康人体内的精氨酸加压素（AVP）水平。通过对大鼠垂体的蛋白质组学分析，揭示了利拉鲁肽介导的突触蛋白磷酸化修饰具有时间和性别依赖性。通过体外AVP荧光素酶报告实验，研究确定了影响AVP释放的特定突触蛋白磷酸化位点，并解释了利拉鲁肽作用的性别差异。","scd":null,"kp":[]},{"i":43484,"as":"植物盐胁迫通过渗透胁迫和离子毒性阻碍生长，并激活自噬。研究发现，源自转座子的转录因子MUSTANG4 (MUG4) 能够通过相分离感知离子胁迫，进而调控植物自噬。MUG4在植物中充当协调自噬基因激活的主调节因子，填补了植物体内类似于动物TFEB转录因子机制的空白。","scd":null,"kp":[]},{"i":43485,"as":"二维范德华材料中的石墨烯等离子体和双曲声子极化激元虽能实现极强光限域，但传播长度受限。该研究在二维范德华材料中实现了长程表面极化激元，其具备更长的传播长度和更快的群速度。该极化激元由六方氮化硼薄片等构成的深亚波长异质结构支持，为中红外波段的高速片上光子应用提供了新机遇。","scd":null,"kp":[]},{"i":43486,"as":"通过高分辨率神经外科皮层脑电图和受控句子生成实验，研究揭示了语言产生过程的神经编码机制。研究发现存在编码单词级和高阶信息的不同皮层网络，并表现出混合空间组织特征：广泛分布于传统语言区，同时在典型语言区域对语义和结构对比表现出局部敏感性的集中。这揭示了语言信息幅度独立的神经编码模式。","scd":null,"kp":[]},{"i":43487,"as":"研究设计了一种各向异性变负泊松比超材料，通过像素化结构实现对结构各向异性和电磁特性的快速调控。利用一维导体的高取向性，在不同方向间实现了2.8×10^6的最高导电率，从而实现随角度变化的电磁兼容性（跨越透明、吸收和屏蔽区域）。该超材料框架可通过形变连续调节电磁波吸收率，在可调多光谱伪装和电磁能量收集领域具有应用潜力。","scd":null,"kp":[]},{"i":43488,"as":"共生细菌能够产生介导三方相互作用的生物活性次级代谢物。研究从非共生光杆菌中鉴定出一种类似darobactin的肽类天然产物aphotorhaptin A，其结构特征包含醚交联和N端乙酰基团。生物合成研究表明，该物质通过意外的引导肽切割步骤成熟，随后的N端乙酰化赋予其代谢稳定性，从而维持六肽骨架的完整性。","scd":null,"kp":[]},{"i":43489,"as":"研究编译了包含31,865种陆生脊椎动物的全球数据集，对比了岛屿特有物种、大陆特有物种与双重分布物种的灭绝风险。结果表明，岛屿特有物种面临显著更高的灭绝风险，自1500年以来已有3.1%灭绝，34%目前受到威胁。其灭绝风险分布不均且具有分类学结构，与外来物种入侵等因素紧密相关。","scd":null,"kp":[]},{"i":43490,"as":"磷酸盐调节激素FGF23由GALNT3糖基转移酶调控，GALNT3介导的糖基化能保护FGF23免受蛋白酶切割，从而调节肾脏磷酸盐重吸收。FGF23或GALNT3的突变会导致磷酸盐调节疾病，引发生长缺陷、骨骼畸形及软组织钙化等。研究深入探讨了这些引发磷酸盐失调的突变的具体分子效应。","scd":null,"kp":[]},{"i":43491,"as":"带电杂质是电子器件中载流子散射的主要来源。研究利用多探针扫描隧道电位法，直接在原子尺度上可视化了外延双层石墨烯中单个带电杂质周围几纳米范围内的偶极子电势分布。这些偶极子的取向与局部电流方向呈平行或反平行排列。该实验直观揭示了带电杂质对局部电化学电势和电子输运的具体影响。","scd":null,"kp":[]},{"i":43492,"as":"新冠病毒N端结构域（NTD）是关键抗体靶点。研究将NTD抗体分为9个空间上不同的类别（NTD-1至NTD-9），其中包括一个隐秘表位NTD-8。机制研究显示，NTD-5和NTD-9抗体通过诱导S1脱落发挥中和作用。跨原始株、Delta和17个Omicron亚变体的41种抗体分析，清晰界定了NTD抗体的表位免疫逃逸图谱。","scd":null,"kp":[]},{"i":43493,"as":"研究开发了一种名为OncoAPC的灭活人工抗原呈递细胞，基于三重信号逻辑设计：MHC-I介导抗原呈递（信号1）、具有检查点隔绝能力的CD80介导共刺激（信号2）以及白细胞介素-12（信号3）。OncoAPC通过顺式CD80:PD-L1相互作用部分隔绝PD-1抑制，直接激活T细胞，并激活内源性树突状细胞以传递肿瘤抗原，引发系统性抗肿瘤免疫反应。","scd":null,"kp":[]},{"i":43494,"as":"流行病传播与人类行为密切相关，疾病高发会引发防范意识从而抑制传播。研究通过构建双群体相互作用数学模型，探讨了异质信息来源对流行病结果的影响。研究表明，根据不同的物理接触模式，系统会从均匀的地方病平衡点发生分岔，转变为非均匀的地方病平衡，证实信息来源的选择对感染水平具有决定性作用。","scd":null,"kp":[]},{"i":43495,"as":"研究分析了涵盖48个葡萄属物种的639份全基因组重测序数据。通过重建系统发育框架和对19个物种进行群体遗传学分析，探究了整个葡萄属在多物种间的基因渗入动态。该研究将基因渗入的普遍性与景观尺度过程相整合，揭示了其在北美葡萄物种平行适应性进化中的关键作用。","scd":null,"kp":[]},{"i":43496,"as":"海洋沉积物中黄铁矿的形成和埋藏对大氧化和海水缓冲起基础控制作用。研究开发了一种新方法，用于区分由氧化还原变化驱动的沉积物活性铁影响与大陆硅酸盐风化、陆源颗粒物转移等其他控制因素。该框架被应用于跨度达12亿年的活性铁数据汇总，揭示了地球表面铁循环随地质历史的演变规律。","scd":null,"kp":[]},{"i":43497,"as":"精子鞭毛的同步性可提升生殖适应性，是研究生物协调的模型。关于流体耦合能否单独实现鞭毛同步存在争议。研究开发了一种微流控陷阱阵列，在保留精子天然鞭毛摆动的前提下固定精子对，从而在受控的流体动力学条件下实现对相位动态的高精度、长持续时间测量。这证实了流体动力学相位 entrainment 是驱动鞭毛同步的机制。","scd":null,"kp":[]},{"i":43498,"as":"研究设计了一种负载于无定形VOx上的铱锡合金析氧反应（OER）催化剂，提出了由电荷重分布诱导的氧溢出策略。该策略能有效转移有毒的含氧中间体，并在动态OER过程中维持铱的价态稳定性（+2.5），从而同时提升催化活性与稳定性。这克服了传统吸附质演化机制（AEM）和晶格氧机制（LOM）的活性-稳定性权衡问题，为质子交换膜水电解槽提供了先进催化剂。","scd":null,"kp":[]},{"i":43499,"as":"人参是一种具有药用价值的植物。研究对287份人参种质进行了重测序，通过群体遗传学分析鉴定出与地理区域和果实颜色相关的五个进化枝。选择消除分析揭示了与适应、生长以及三萜生物合成相关的基因。对169种人参皂苷的分析揭示了不同群体间由驯化驱动的丰度变化，并通过代谢物全基因组关联分析鉴定出12,676个显著位点。","scd":null,"kp":[]},{"i":43500,"as":"研究利用数字光处理和超声装饰技术，构建了一种受生物启发、含有原子级分散Mn-N4位点的微观壳基框架结构催化剂。受海星和骨骼启发的架构能最大程度减少应力集中以提升可重复使用性，并增强传质；而Mn-N4位点则促进基于羟基自由基介导的氧化反应。两者协同作用大幅提升了水净化的整体效率，超越了各组分的单一贡献。","scd":null,"kp":[]},{"i":43501,"as":"研究报道了溶酶体双孔通道TPC1的功能获得性突变（TPC1 I486T）会导致小鼠铁过载，而缺乏TPC1的小鼠则表现出缺铁的相反表型。机制上，TPC1突变体通道活性显著增强，改变内体pH值。这一过程直接决定了结合了铁的转铁蛋白的摄取，从而决定了细胞的铁状态。该研究揭示了TPC1在调控细胞铁稳态中的关键作用。","scd":null,"kp":[]},{"i":43502,"as":"传统受体靶向荧光探针在体内难以实现高肿瘤与正常组织（T/N）比率。研究提出了一种生物正交嵌合人工受体的原位组装策略，通过在肿瘤表面局部构建受体来放大荧光信号。这种快速的膜工程增加了有效受体密度，增强了荧光团结合。机制研究表明，BCAR具有出色的膜保留能力，在异质性肿瘤微环境中维持信号持续放大，从而实现肿瘤的高对比度成像。","scd":null,"kp":[]},{"i":43503,"as":"针对水系锌离子电池中锌枝晶生长的问题，研究构建了一种具有多组分梯度的原位3D限制宿主框架。该框架通过疏水性氨基功能化聚硅烷钝化层和亲锌银纳米颗粒在碳纸骨架上的自组装，形成相反的浓度梯度。这种独特的结构能够诱导可控且快速的堆叠式锌剥离/电镀行为，实现独特的“先进后出”模式，显著提高了电池的耐久性。","scd":null,"kp":[]},{"i":43504,"as":"基于中国新疆义乌侏罗纪森林的78个原位矿化针叶树树桩，定量重建了森林结构。化石森林树木随机分布，平均密度为每公顷126棵，树冠高度在10.47至43.95米之间，林分生物量达276,192。这些数据表明中侏罗世时期森林具有较高的森林生产力。","scd":null,"kp":[]},{"i":43505,"as":"提出了一种基于扫描探针的操作方案，利用纳米结构金属转子对二维晶体摩琳超晶格进行原位连续的制造后扭曲控制。在石墨烯、六方氮化硼和封装的空气敏感型MoTe2三个平台中实现了可重复的角度调节和直接的摩琳成像，克服了传统堆叠方法在组装时固定角度的限制。","scd":null,"kp":[]},{"i":43506,"as":"通过整合多组学数据，系统比较了原代人视网膜色素上皮、iPSC衍生RPE和永生化ARPE-19细胞系的三维表观基因组图谱。分析表明，iPSC-RPE表现出混合的分子状态，能够重现类似原代hRPE的转录和染色质环化特征，但其组蛋白修饰状态仍不完全成熟。","scd":null,"kp":[]},{"i":43507,"as":"开发了一种基于摩擦纳米发电机（TENG）的自供电生物传感器，用于检测临床尿液中的生物标志物。通过自充电核酸探针修饰和靶向构象变化诱导产生特定的表面电荷变化，并结合调节系统离子强度以匹配德拜长度。该方法解决了尿液复杂电荷环境中检测特异性和灵敏度不足的问题。","scd":null,"kp":[]},{"i":43508,"as":"在分子嵌入的二硒化铌（NbSe2）中发现了一种合作超结构相。嵌入分子的有序性诱导了NbSe2主晶格的超结构，由于分子和无机晶格之间的不可公度性，表现出摩琳结构特征。热淬火测量表明，这种相变是通过有序-无序动力学过程实现的。","scd":null,"kp":[]},{"i":43509,"as":"研究了具有相同核心但不同R基团的Au24(SR)20纳米团簇，揭示了由R基团调节的统一三重发射机制。通过结合低温光致发光、飞秒瞬态吸收和时间分辨电子顺磁共振技术，首次提供了室温下寿命约为350纳秒的短寿命激发三重态（T1）的直接实验“指纹”，解析了激子弛豫级联过程。","scd":null,"kp":[]},{"i":43510,"as":"利用肾小管特异性GCGR敲除和过表达小鼠模型及人类肾脏样本，证实肾小管GCGR信号传导在糖尿病肾病（DKD）中发挥重要的肾脏保护作用。在DKD中肾小管GCGR表达降低，其缺失会加剧DKD，并导致扩大的溶酶体内显著的磷脂积累。这表明GCGR激动剂可为肾病提供治疗益处。","scd":null,"kp":[]},{"i":43511,"as":"开发了一种结构独特的强效选择性TopBP1 BRCT7/8抑制剂CS18。CS18通过破坏致癌TopBP1复合物来抑制MYC转录，且不干扰DNA复制。实验表明，CS18能够增强PARP阻断效果，并有效逆转奥希替尼的耐药性，为克服癌症治疗中的耐药性提供了新策略。","scd":null,"kp":[]},{"i":43512,"as":"受自然界中海藻筏和海草“海王星球”捕获微塑料的启发，设计了一类由海藻酸盐和壳聚糖等生物聚合物制成的仿生多孔网状和球状清洁剂。生物聚合物被加工成软树枝状胶体，形成由蜂窝状内部网络和分级纤维外层组成的结构。这种仿生网络能够高效捕获并清除不同尺寸的微塑料。","scd":null,"kp":[]},{"i":43513,"as":"开发了一种可生物降解的压电气凝胶（Piezo Gel）用于脊髓损伤的程控电神经调控。该凝胶模拟脊柱力学，将生理运动转化为局部生物电信号，并通过外部超声放大输出，实现无植入电子设备的无创按需神经调控。在急性重度脊髓损伤大鼠中，超声激活的凝胶显著改善了运动恢复并促进了膀胱功能重塑。","scd":null,"kp":[]},{"i":43514,"as":"利用酶蛋白质结构鉴定了磷酸化热液喷口处原始代谢组装的中间状态。研究表明，通用共同祖先的酶代谢是不完整的，最终在细菌和古菌谱系中独立完成组装。在代谢起源时，天然过渡金属（铁、钴、镍和钯）作为催化剂的前体，亚磷酸盐通过磷酸化腺苷提供能量。","scd":null,"kp":[]},{"i":43515,"as":"探讨了氧化石墨烯（GO）氧化状态对磷酸钙石墨烯（CaPG）化学性质及聚乳酸-乙醇酸（PLGA）骨基质性能的影响。在保持5wt% CaPG负载量不变的条件下，通过改变合成温度制备了三种不同氧化状态的CaPG，结果表明氧化状态可调节氧官能团密度、磷酸钙掺入量、亲水性以及基质的力学和生物学行为。","scd":null,"kp":[]},{"i":43516,"as":"开发了一种时空可编程的超分子纳米平台（Cu-P-MSA），结合靶向溶酶体的声动力疗法与肿瘤局限的先天免疫激活来治疗前列腺癌。该平台包含PSMA靶向配体、吗啉基团和组织蛋白酶B可裂解连接物，通过时空可控的溶酶体膜透化（LMP）诱导细胞死亡并放大STING驱动的抗肿瘤免疫反应。","scd":null,"kp":[]},{"i":43517,"as":"提出了一种通过可重编程顺序变形来实现连续物理输入的数字编码和计算的力学超材料。该超材料基于支持单轴压缩下一系列快速突弹失稳的多稳态架构。利用逆向设计策略，可以通过调节变形序列在广阔的设计空间内进行调谐，从而实现连续物理输入到离散数字输出的转换。","scd":null,"kp":[]},{"i":43518,"as":"提出了一种不可逆化学范式，通过烯醇-酮互变异构将β-酮烯胺“不可逆结点”编程到柔性聚二甲基硅氧烷（PDMS）网络中，构建出橡胶有机框架（ROFs）。该方法共同编程交联密度和链刚性，生成稳定且优化的微结构，打破了传统聚合物膜中链灵活性与精确分子筛分之间的渗透性-选择性权衡限制。","scd":null,"kp":[]},{"i":43519,"as":"引入了一种干涉配合组装策略，将立体光刻3D打印微结构与定制磁像素耦合，制造出亚毫米级无系绳磁致动器。在跨越生理相关粘度范围的流体模型中的理论和实验分析表明，该致动器不仅克服了当前构建策略带来的结构简单限制，还实现了按需操作和原位粘度传感，为微创手术提供了多功能平台。","scd":null,"kp":[]},{"i":43520,"as":"设计了PFSSTKT功能化KLD-12多肽水凝胶并整合二维BiOIO3纳米片，构建出具有超分子多肽纳米纤维结构的可注射声-压电/热电水凝胶。该材料通过招募骨髓基质细胞，克服了其修复和抗肿瘤效率不足的问题，能够有效消除术后骨肉瘤并促进骨缺损修复，贴合真实临床场景需求。","scd":null,"kp":[]},{"i":43521,"as":"研究了通过中间状态形成脆弱束缚或相干结构，而非直接平衡的非平衡级联动力学过程。基于相对论重离子碰撞中的轻核产生和宇宙学中玻色-爱因斯坦凝聚，分析了从这些非平衡级联动力学中涌现出类似平衡态的产率。","scd":null,"kp":[]},{"i":43522,"as":"通过轨道相关的电子-晶格耦合，从理论上研究了手性声子驱动的轨道积累现象。推导出了由经典晶格动力学或非平衡声子诱导的轨道积累公式，强调了轨道的整流二阶响应在产生这种积累中的关键作用。","scd":null,"kp":[]},{"i":43523,"as":"证明了电子的轨道角动量（OAM）可由圆偏振声子动态诱导。这种诱导的OAM源于绝热演化过程，电子获得了以声子位移空间中编码的Berry曲率表示的Berry相位，通过内部机制实现角动量的传递。","scd":null,"kp":[]},{"i":43524,"as":"一种新算法将人工智能天气预报与基于物理的气候模型相结合，能够高效地表征罕见且危险的极端天气事件。该研究发表于《物理评论快报》。","scd":null,"kp":[]},{"i":43525,"as":"研究利用耦合通道Gamow壳模型，以自旋轨道强度作为控制参数，在轻核中定位散射矩阵的双重极点。这些双重极点与非厄米简并的异常点有关，此时两个特征值及其特征向量汇合，产生有缺陷的哈密顿量。","scd":null,"kp":[]},{"i":43526,"as":"结合拉曼光谱和输运测量发现，当原子级薄度的1T-TaS2接近二维极限时，其电荷密度波序和相关的关联绝缘态得到了显著增强。","scd":null,"kp":[]},{"i":43527,"as":"科学必须加强其社会契约，以解决公众信任问题。这些信任问题只能通过更优的沟通机制以及开展符合社会利益的科学研究来解决。","scd":null,"kp":[]},{"i":43528,"as":"一种古老的尼安德特人基因变异使得部分现代人变得更高且肌肉更发达。这种古代遗传变异在南亚和东亚血统的人群中最为常见。","scd":null,"kp":[]},{"i":43529,"as":"一项涵盖超百万人的研究表明，破坏FNIP1基因的罕见变异与良好的代谢状况相关，使心脏代谢疾病风险降低约60%。在小鼠实验中，沉默FNIP1通路基因会诱导脂肪分解，并重现了在人类中观察到的代谢益处。","scd":null,"kp":[]},{"i":43530,"as":"研究发现，COVID-19感染能够唤醒人体内通常无害的休眠病毒，特别是细环病毒的重新激活与长新冠的发生发展存在关联。","scd":null,"kp":[]},{"i":43531,"as":"研究人员开发了一种离体平台，整合了微电极阵列刺激与单核基因组学，用于研究人脑神经调节机制。结果发现，脑刺激能够增强细胞组装，并且这种作用与特定细胞类型的基因调控网络相关。","scd":null,"kp":[]},{"i":43532,"as":"人类癌症模型倡议（HCMI）开展了一项大规模国际项目，利用最新技术生成下一代患者来源的体外癌症模型（如肿瘤类器官）。该研究评估了这些模型在长期扩增期间是否保留了患者肿瘤的关键特性，为癌症治疗和机制验证提供代表性实验室模型资源。","scd":null,"kp":[]},{"i":43533,"as":"研究利用单细胞RNA测序和CRISPR-Cas9等技术证实，表达CD40和MHC-II的星形胶质细胞会促进中枢神经系统T细胞自身免疫。这些星形胶质细胞通过与CD4+ T细胞相互作用，推动多发性硬化症等中枢神经系统自身免疫疾病的病理过程。","scd":null,"kp":[]},{"i":43534,"as":"Virtual Tissues（VirTues）是一个用于空间蛋白质组学的通用基础模型。该模型直接从多重成像数据中学习蛋白质、细胞和组织的多尺度表征，支持标记物重建、细胞分割与分型、微环境注释和空间生物标志物发现，解决了不同空间蛋白质组学研究间知识迁移困难的问题。","scd":null,"kp":[]},{"i":43535,"as":"基于1154名住院COVID-19患者的多组学纵向数据，研究揭示了在急性COVID-19期间，疱疹病毒和细环病毒发生显著的重激活。不同病毒具有不同的时间动态特征，且病毒的重激活程度与COVID-19的疾病严重程度相关。","scd":null,"kp":[]},{"i":43536,"as":"研究利用冷原子量子模拟器，通过热力学和光谱学测量，在费米-哈伯德模型中观察到了从正常金属到赝能隙金属的交叠现象。在冷却过程中，系统在中等掺杂水平下表现出压缩率的最大值。","scd":null,"kp":[]},{"i":43537,"as":"研究设计了一种由合成酸响应溶膜肽（aMPC16-CA50）诱导的免疫原性溶膜细胞死亡（mLCD）模式。该肽对肿瘤细胞外环境和溶酶体的pH值递减表现出阶梯式响应，导致细胞膜破裂，激活炎症转录程序，从而增强抗肿瘤免疫并强化免疫检查点阻断疗法的效果。","scd":null,"kp":[]},{"i":43538,"as":"研究直接从结直肠癌、食管癌等五种癌症患者组织中提取并表征了256个临床标注的肿瘤类器官。通过全基因组测序和162个类器官的全基因组CRISPR-Cas9筛选，系统绘制了癌症基因依赖图谱，为癌症研究和药物发现提供了可再生且基因稳定的模型。","scd":null,"kp":[]},{"i":43539,"as":"研究开发了系统发现分子胶的平台，发现分子胶M12能够重编程E3连接酶DCAF11以降解DDX18蛋白。机制上，M12作为前体药物，需通过谷胱甘肽S-转移酶介导的谷胱甘肽化作用激活，其谷胱甘肽部分结合在进化保守的区域。","scd":null,"kp":[]},{"i":43540,"as":"研究发现，即使伏隔核中的多巴胺水平升高，阿片类药物的奖赏学习仍可被阻断。研究人员开发了细胞类型特异性纳曲酮类似物，将其递送至伏隔核胆碱能中间神经元，使这些细胞对吗啡不敏感，从而消除了吗啡条件性位置偏好的获得，且不影响运动功能。","scd":null,"kp":[]},{"i":43541,"as":"通过协调X射线和射电观测，研究团队测量了射电磁星的X射线偏振。在热主导的软X射线波段探测到高度偏振，这为量子电动力学长期预测的“真空双折射”效应（强磁场使真空产生依赖偏振的折射率）提供了观测证据。","scd":null,"kp":[]},{"i":43542,"as":"贫血影响全球四分之一人口。血红素作为血红蛋白的活性成分，其水平需受到严格控制。研究发现，胞质eIF2α激酶HRI能够监测血红素水平，并在铁缺乏或地中海贫血时通过调节翻译来对抗贫血，揭示了控制血红素水平的分子回路机制。","scd":null,"kp":[]},{"i":43543,"as":"通过对超过103万名个体进行外显子组测序分析，研究了能量代谢的遗传基础。研究确定了59个与甘油三酯和高密度脂蛋白胆固醇比值相关的独立基因，这些基因富含肝脏和脂肪组织中表达的能量平衡与代谢主调节因子，其中39%的基因是已获批或处于临床试验阶段的靶点。","scd":null,"kp":[]},{"i":43544,"as":"探讨学术出版系统在处理作者姓名顺序时的僵化问题。现有数据库和投稿系统在作者姓名格式上缺乏灵活性，呼吁出版商采取更多改进措施，以尊重不同文化背景的作者姓名排序习惯。","scd":null,"kp":[]},{"i":43545,"as":"对磁化恒星核心的观测表明，在超强磁场环境下，真空并非绝对的“虚无”。研究发现，即使是没有物质的真空（空空间），也能够与光发生相互作用，并在超强磁场作用下改变光的物理性质，使其产生偏振现象。","scd":null,"kp":[]},{"i":43546,"as":"着丝粒是细胞分裂必需的染色体区域。通过对65名多样化个体的着丝粒进行完整序列表征，研究发现其突变模式具有高度的动态性和快速性。着丝粒序列在数代之间乃至数十万年的演化过程中均发生快速变化，为理解着丝粒的进化机制与功能提供了重要信息。","scd":null,"kp":[]},{"i":43547,"as":"Nature杂志独家公布了在专利申请文件中被引用次数最多的科学研究论文榜单。该分析不仅揭示了受工业界和创新者青睐的底层基础研究成果，还深入剖析了这些特定研究被专利技术高频引用背后的原因。","scd":null,"kp":[]},{"i":43548,"as":"基于对一百万个多样化基因组的分析，研究人员发现了特定基因突变与人体代谢健康的广泛益处。这些突变与降低糖尿病、心脏病及其他心血管代谢疾病的风险直接相关，不仅有助于减少腹部脂肪，还能促进肌肉生长。","scd":null,"kp":[]},{"i":43549,"as":"针对现有食物过敏治疗手段有限的现状，首例人类粪便移植疗法取得了令人兴奋的成果。","scd":null,"kp":[]},{"i":43550,"as":"二维超导体是超导量子电路和强关联物理的重要平台。针对单层材料在空气中极易氧化的合成难题，研究提出“封装外延”机制，成功生长出面积超过1英寸、空气稳定的单层二硒化铌（NbSe2）薄膜。该技术利用石墨烯等二维封装层，为超导量子器件的制备提供了新方法。","scd":null,"kp":[]},{"i":43551,"as":"为了降低量子纠错对物理比特高门保真度的严苛要求，研究设计并实现了一种双轨擦除量子比特的双比特纠缠门。通过构建强大的误差层级，使得计算子空间之外的泄漏误差主导且最易被纠正，从而提升纠错阈值并改善码距扩展性。","scd":null,"kp":[]},{"i":43552,"as":"传统细胞系在绘制癌症依赖性图谱时存在亚型代表性不足等局限。研究对涵盖10种癌症类型的下一代癌症模型（类器官和球体）进行了147次全基因组规模CRISPR筛选及多组学特征分析，有效扩展了癌症亚型表征，加速精准肿瘤学治疗策略的发现。","scd":null,"kp":[]},{"i":43553,"as":"聚氯乙烯（PVC）废弃物的处理面临严峻挑战。为实现碳循环并降低回收成本，研究人员开发出一种PVC升级回收新方法。该技术利用三氯化铝（AlCl3）作为催化剂，在温和温度下将PVC转化为具有可控制粘度的高附加值聚α-烯烃（PAO）润滑剂。","scd":null,"kp":[]},{"i":43554,"as":"出版商更正声明：在2025年1月9日重新发布的关于“结直肠癌转移过程中渐进性可塑性”的文章中，作者Francesco Cambuli的姓氏存在拼写错误（误拼为Cambulli）。目前该错误已在HTML和PDF版本中修正。","scd":null,"kp":[]},{"i":43555,"as":"研究人员利用化学转化技术成功将废旧PVC塑料升级回收为高等级发动机润滑剂，并揭示了其背后的复杂化学机制。此外，相关研究还展示了如何利用工程酵母来协助生产抗癌药物。","scd":null,"kp":[]},{"i":43556,"as":"转录因子（TFs）通过识别特定DNA序列基序调控基因表达。该研究通过超过4000次涵盖体外和体内的独立实验，对332种推测和特征不明确的人类TFs进行了系统性序列特异性测定。实验成功为其中超过一半（177种）的TFs确定了结合基序。","scd":null,"kp":[]},{"i":43557,"as":"利用美国国家科学基金会Daniel K. Inouye太阳望远镜（首台4米级太阳望远镜）获取的高空间分辨率观测数据，研究在太阳光球层磁通量集中区域的边缘证实了普遍存在的磁化开尔文-亥姆霍兹不稳定性。这一发现从实验上证实了长期以来的理论预测，揭示了太阳大气等离子体混合的小尺度动力学。","scd":null,"kp":[]},{"i":43558,"as":"RNA结合蛋白ZFP36L2在结直肠癌（CRC）中有5-10%的突变率，被证实是驱动细胞动态去分化的关键应激响应调控因子。在肠癌转移和肠道伤口愈合模型中，ZFP36L2能够促使分化细胞重编程为肠道干细胞状态。敲除ZFP36L2会抑制细胞去分化及肠道干细胞基因表达，是细胞命运重编程的关键分子开关。","scd":null,"kp":[]},{"i":43559,"as":"研究提出一种名为“剪切-拉伸原位颗粒到纤维转化”（SHIFT）的3D打印新现象。通过可控挤出含颗粒的水凝胶，使离散颗粒与周围基质经历相反的相变，成功生成高度排列的微纤维（直径5-30微米）。该技术克服了仿生各向异性水凝胶的制造挑战。","scd":null,"kp":[]},{"i":43560,"as":"杏仁核在情绪和应激反应中起核心作用。研究发现，杏仁核中的星形胶质细胞通过其初级纤毛相关的信号传导机制参与应激行为的调控。在应激状态下，星形胶质细胞的初级纤毛形态变短，初级纤毛相关分子的表达量下降，并在基因和蛋白质表达层面发生显著改变。","scd":null,"kp":[]},{"i":43561,"as":"为解决甲脒碘化物（FAI）在热蒸发过程中因高温易发生热降解的问题，研究人员合成了一种基于甲脒的共晶（Eu）材料。该共晶使FAI的有效蒸发温度平均降低36°C至其降解阈值以下。该技术使大面积热蒸发钙钛矿/硅叠层电池成为可能，显著提升了钙钛矿薄膜的结晶度和原子级成分均匀性。","scd":null,"kp":[]},{"i":43562,"as":"高压锂金属电池的发展受限于界面副反应和锂枝晶问题。研究通过在聚丙烯隔膜上集成预吸附硝酸根的氧空位工程化钛酸钡（BTOVN）层，利用铁电偶极子选择性地降低目标阴离子的能级。该策略有效钝化了负极/电解质界面，抑制了化学腐蚀和枝晶生长，提升了电池的安全性。","scd":null,"kp":[]},{"i":43563,"as":"传统单界面电催化难以满足复杂多步分子合成的动力学耦合要求。研究提出一种耦合电化学-化学反应（CECR）系统，通过引入氧化还原介体，将电极的电子输入过程与下游的底物转化过程在空间和功能上解耦。该介体设计突破了单一界面的限制，实现了复杂电化学合成。","scd":null,"kp":[]},{"i":43564,"as":"骨关节炎（OA）软骨中高精氨酸代谢的软骨细胞亚群显著耗竭，且其关键上游调控因子FGF21严重下调。研究证实FGF21通过ASS1/ASL介导的精氨酸生物合成恢复软骨细胞功能。基于此机制，研究人员工程化开发了一种基于水凝胶的仿生代谢重编程生态位重塑系统（MetaRemod），实现精准靶向治疗。","scd":null,"kp":[]},{"i":43565,"as":"报道了一种高度结晶的掺Cr3+透明玻璃复合材料，打破了高结晶度与高光学透明度不可兼得的传统限制。该材料的光学透射率超过80%，内部量子效率高达98.5%。在X射线激发下，其辐射发光（RL）强度是Bi4Ge3O12的五倍，并表现出热增强辐射发光特性，其强度在特定高温下可达室温强度的105%，在协同成像领域极具潜力。","scd":null,"kp":[]},{"i":43566,"as":"受生物感觉细胞离子通道门控信号转导机制启发，研发了一种仿生液态传感电子皮肤（BLSE）。传统液态传感技术受限于界面电荷转移动力学缓慢和分析过程复杂，难以兼顾瞬态响应速度与识别精度。BLSE通过模拟离子通道的瞬态信号转导，在低阻抗接触时触发电子路径的瞬间重构，有效克服了传统技术中的局限性，赋予了智能机器人感知和分析复杂液体环境的能力。","scd":null,"kp":[]},{"i":43567,"as":"针对倒置钙钛矿太阳能电池（PSCs）底界面热稳定性差的问题，提出一种酸碱络合诱导的偶极工程策略。通过将4-氨基吡啶（4-AP）引入Me-4PACz基质形成稳定的静电复合物，有效抑制了分子聚集并保证了均匀覆盖和垂直分子取向。该策略将界面偶极矩从1.64德拜提升至8.34德拜，显著改善了空穴提取能力，从而提升了器件的光伏性能与热稳定性。","scd":null,"kp":[]},{"i":43568,"as":"针对传统有机光伏器件（OPVs）因热应力下顶部金属电极扩散导致过早失效的问题，提出一种PMMA金属捕获网策略。老化驱动的银（Ag）扩散是器件关键失效途径。在PDINN层自组装的PMMA不连续网状网络不仅作为物理扩散屏障，其羰基还能通过Ag-O相互作用化学锚定Ag。这种物理与化学协同的阻挡机制在不影响电荷提取的前提下，有效抑制了电极扩散，提升了器件稳定性。","scd":null,"kp":[]},{"i":43569,"as":"为解决锂金属电池中锂枝晶生长和界面不稳定的问题，采用可规模化的原位冶金策略构建了体相均匀的Li/LiZn-Li2O复合负极。在复合负极中，一维LiZn形成连续的传输与支撑网络，纳米级Li2O提供分散的极性亲锂位点。理论计算表明，LiZn表面降低了成核势垒。这种锌反向扩散诱导机制实现了均匀的锂沉积，有效提升了高性能锂金属软包电池的循环稳定性。","scd":null,"kp":[]},{"i":43570,"as":"为整合有机与水系电解质的优势，研发了一种水-有机双相凝胶电解质。通过两亲性单体、霍夫迈斯特效应和相分配的协同作用，在水相和有机相之间自发形成明显的相间。该混合溶剂区域平滑了相间溶剂化变化，使整体电导率较无双相界面的材料提升了一个数量级。同时，区室化的有机凝胶和水凝胶域解耦了阴阳极的界面化学反应，实现了锌金属电池界面稳定性与快速离子传输的兼顾。","scd":null,"kp":[]},{"i":43571,"as":"针对纯金属墨水成本高及纳米铜易氧化导致导电失效的问题，提出一种激光诱导合成与钝化技术，制备出具有本征抗氧化性的坚固纳米铜。通过选择性可控金属化，新生铜在界面处配备了由甲酸盐晶体学面和配体功能化的明确双配体屏障。在无需额外封装的情况下，该纳米铜在苛刻的湿热条件（190°C和90°C、90%相对湿度）下表现出优异的耐久性，为可持续电子器件提供了低成本的解决方案。","scd":null,"kp":[]},{"i":43572,"as":"针对多共振热激活延迟荧光（MR-TADF）材料反向系间窜越（RISC）速率慢、导致高亮度下严重效率滚降的问题，提出一种新型蓝光MR-TADF分子设计方法。通过引入起皱且不对称的七元二苯并二氮杂卓结构替代传统的平面供体，不仅促进了高效的三重态到单重态的RISC过程，还有效提升了分子的整体性能。该策略成功克服了高发光效率与快速RISC之间的矛盾，推动了高性能OLED的发展。","scd":null,"kp":[]},{"i":43573,"as":"为解决数字处理方法在提取空间频域特征时数据传输频繁导致效率低的问题，研发了一种单波长调制的傅里叶光电突触及相应的傅里叶神经形态视觉（FIVE）系统。该系统集成了傅里叶光学系统，能以近乎零时间延迟和极低的计算能耗在光学层面提取频域信号。提取的信号随后基于光电突触对光强的非线性响应进行滤波。此外，该器件表现出多级记忆可调谐性，显著增强了具身智能对环境的适应能力。","scd":null,"kp":[]},{"i":43574,"as":"针对肾功能衰竭等无症状疾病，开发了一种基于金属有机框架（MOF）包裹的热稳定微针（MOF@MN）传感贴片，用于微创检测与监测。该平台集成了微创真皮间质液（ISF）采样、针上原位检测以及MOF界面的生物稳定化功能。在抗体功能化的微针上原位生长了一层极薄的沸石咪唑酯骨架-8（ZIF-8）外壳，成功在高达50°C的热循环四周后仍保持了固定抗体的生物活性，实现了在长期无冷藏条件下的全分析性能。","scd":null,"kp":[]},{"i":43575,"as":"为解决柔性钙钛矿太阳能电池难以兼顾高光电转换效率与优异机械稳定性的问题，提出了一种调节供体-受体型自组装单分子层（SAMs）组装自由度的策略。新设计的2FMPA-BT-PPA SAMs相比此前的BA SAMs展现出更高的组装自由度。这种增强的构象适应性和强化的π-π堆积作用，促进了更高质量单分子层的形成，有效提升了器件的电荷抽取效率、光电性能及在柔性基底上的操作稳定性。","scd":null,"kp":[]},{"i":43576,"as":"提出了一种基于Ru/TaOx/Pt忆阻器的尖峰速率可编程概率神经元，该神经元利用了忆阻器的可调谐噪声特性。在这类忆阻器中，不同电阻状态表现出不同的传导机制，进而导致不同的噪声行为和信噪比。当忆阻器的可调电阻与作为熵源的内禀不稳定性耦合时，它成为了一种可调熵源。该研究将这种可编程概率神经元成功应用于频率选择性的时间序列信号编码，拓展了概率计算的应用方向。","scd":null,"kp":[]},{"i":43577,"as":"针对被动辐射冷却中寄生热量损害净冷却效率的问题，提出一种可逆黄原酸化介导策略，制备了具有协同光热调节的分级SiO2@纤维素纳米纤维气凝胶。该化学策略使得约300纳米的SiO2纳米球沿纳米纤维均匀原位锚定，形成独特的“珍珠项链”形貌。这种结构协同集成了宽带太阳能反射率、高中红外发射率和低热导率，通过最小化太阳吸收和最大化大气窗口中红外发射，实现了高性能被动辐射冷却。","scd":null,"kp":[]},{"i":43578,"as":"针对多晶钙钛矿X射线平板探测器（FPDs）因界面结合不良导致空间分辨率受限的问题，提出了一种专为其定制的离子扩散诱导多界面重构策略。在厚度达数百微米的钙钛矿层中，基于菲克定律的离子扩散促使X射线界面重新构建。通过该技术，在8.5×8.5平方厘米的大成像面积上，实现了多晶钙钛矿直接转换X射线FPDs中创纪录的调制传递函数（MTF），达到每毫米6.2线对。","scd":null,"kp":[]},{"i":43579,"as":"为解决硅基负极在充放电过程中的体积膨胀和界面副反应问题，提出一种将界面修饰与原位电解液调节相结合的协同策略，以构建坚固的固体电解质界面（SEI）。该策略首先在SiOx负极上预制备一层由LiF和Li3PO4组成的保形层。这种界面富集促进的聚合反应有效调和了SEI的均匀性与长期稳定性，显著提升了基于硅基负极的电池循环寿命和整体电化学性能。","scd":null,"kp":[]},{"i":43580,"as":"针对光催化还原CO2至C2产物面临的转化效率与选择性双重挑战，设计合成了一种双单原子光催化剂。通过将钯和铜单原子可控地嵌入TiO2基质中，构建了优化组分为Cu0.5Pd0.5/TiO2的催化体系。在该体系中，Cu和Pd双单原子活性位点协同作用，在海水介质中显著促进了CO2的高效和高选择性光还原转化为C2产物，为实现碳中和及缓解能源环境压力提供了一条有效途径。","scd":null,"kp":[]},{"i":43581,"as":"针对高指数晶面纳米材料因高表面能导致化学合成困难的问题，成功合成了带有高指数晶面的非常规相Pd20Te7纳米八面体。以乙二醇作为形貌和尺寸控制剂，该纳米晶体被{300}、{20}和{23}高指数晶面包围。这些独特的高指数晶面赋予了Pd20Te7纳米八面体卓越的碱性氧还原电催化活性，其质量活性高达1.91 A/mg，在电催化和能源转换领域展现出重要应用价值。","scd":null,"kp":[]},{"i":43582,"as":"针对在晶态多孔材料孔表面精确引入高相互作用基团易干扰骨架形成的挑战，采用了一种超分子保护-去保护策略。在多孔有机盐结晶过程中，酚羟基通过与二甲基亚砜（DMSO）的氢键被保护，促使基于电荷辅助氢键的晶体骨架形成。随后通过逐步去除DMSO，引发了单晶到单晶的两步相变，首先形成一种OH基团处于休眠状态的中间相（Form II），实现了框架构建与孔表面功能化的时间分离。","scd":null,"kp":[]},{"i":43583,"as":"提出了一种利用形状互补的DNA支架来调控对称蛋白组装体价态的通用策略，实现了精确的可寻址功能化。研究展示了链霉亲和素-DNA偶联物从环形DNA纳米结构到重组烟草花叶病毒（TMV）圆盘的受控转移。该机制确定了圆盘外围DNA基序的数量、序列同一性和空间排列，从而为DNA介导的结合实现了位点特异性的可寻址能力。这一方法为控制模式识别、协同行为和结构自组织提供了先进工具。","scd":null,"kp":[]},{"i":43584,"as":"针对招募Cereblon（CRBN）的PROTAC分子难以化学修饰以实现前药递送的问题，报道了三种正交合成策略：三唑季铵化、叔胺烷基化和安装羟基连接基。这些方法实现了CRBN招募型PROTAC前药的化学选择性和高产量合成。这些策略允许掺入自降解连接基，其裂解动力学可被预测性地调节以释放母体PROTAC。在多发性骨髓瘤模型中，代表性的PROTAC-刷状大分子前药验证了该策略的有效性。","scd":null,"kp":[]},{"i":43585,"as":"一种氯化铜催化策略实现了无保护胺的高效选择性远程δ-脱饱和反应及烷烃的C-H胺化。该机制基于“自由基极性匹配”分析，通过中断的Hofmann–Löffler–Freytag (HLF) 反应，以氮自由基阳离子为理想中间体，实现了无保护基团下的高效选择性1,5-氢原子转移 (HAT)。计算研究表明，动力学因素（自由基极性）在上述过程中比热力学因素（键能）更重要。该技术可快速将简单胺转化为药物杂环化合物。","scd":null,"kp":[]},{"i":43586,"as":"研究人员设计了一种由红外光驱动的Cu/Fe2O3催化剂，首次实现在室内红外光和自然太阳光下将生物乙醇转化为高附加值乙醛，同时副产绿氢。在室内红外光照射下，初始乙醛产率达到237 mmol g⁻¹ h⁻¹；在真实太阳光下产率达到205 mmol g⁻¹ h⁻¹，并表现出极高的选择性。该技术利用可再生生物质合成化学品，有助于减少化石燃料依赖并推动实现碳中和。","scd":null,"kp":[]},{"i":43587,"as":"水系铁金属电池 (AIBs) 的研发受限于阳极严重的寄生析氢反应 (HER) 及其引发的阴极结构退化。本研究提出了一种基于同位素工程的重水 (D2O) 电解液策略，通过动力学靶向抑制HER并提升电池整体稳定性。利用氘与氢在零点能上的固有差异，D2O具有更高的水裂解活化能垒，从而有效抑制了水分解反应的活性，解决了铁阳极面临的关键问题。","scd":null,"kp":[]},{"i":43588,"as":"有机太阳能电池 (OSCs) 的非辐射能量损失与三重态电荷转移介导的复合密切相关。本研究采用自旋操纵策略，利用具有开壳层内在特性的非富勒烯受体 (NFAs) 作为自旋活性客体受体。将两种含有巴比妥酸基团末端的开壳层NFAs（MAZ-1和MAZ-2）掺入D18:N3太阳能电池中。电子自旋共振及变温核磁共振等测量结果证实了这些材料的开壳层特征，为通过自旋调控减少能量损失提供了新途径。","scd":null,"kp":[]},{"i":43589,"as":"铁卟啉络合物是一类成熟的二氧化碳还原为CO的分子电催化剂，其传统反应机制通常涉及二氧化碳与[(卟啉)Fe0]中间体的相互作用。本研究使用水溶性络合物[(pTMA)FeIIICl]Cl4，在水相条件下对二氧化碳还原机制进行了详细研究。研究结果揭示了该水溶性铁卟啉络合物在水介质中电催化转化二氧化碳为一氧化碳的具体反应机理。","scd":null,"kp":[]},{"i":43590,"as":"光动力疗法 (PDT) 中光敏剂的表现高度依赖于其空间排列和环境相互作用。超分子组装技术通过非共价相互作用，在不改变发色团骨架的前提下精确控制分子排列和微观环境，从而有效调控光敏剂的光物理和光化学行为。本文综述了利用超分子策略调控PDT中光敏剂激发态性质的最新进展，重点聚焦于促进系间窜越以增强三重态形成，以及调控其他激发态特性。","scd":null,"kp":[]},{"i":43591,"as":"双电子氧还原反应 (2e⁻-ORR) 电催化合成过氧化氢 (H2O2) 面临H2O2还原和歧化反应的竞争，导致法拉第效率通常低于本征选择性。本研究表明，通过活性原子位点密度工程可以有效控制这种微环境中的H2O2分解损耗。调控催化剂的原子位点密度能够保障H2O2电合成的净产量，为去中心化化学品合成和水净化技术提供了优化策略。","scd":null,"kp":[]},{"i":43592,"as":"三维光打印技术长期面临光学场无法确定性转化为体积化学反应场的难题。本研究提出一种光打印策略，通过分子空间均匀性和拓扑化学控制，将光作为可编程输入来定义空间化学反应场。在基于大面积ADCA的单共晶光刻胶薄膜中，拓扑化学反应被空间限制并沿深度方向扩展，生成连续的反应梯度，成功将光学投影确定性转化为三维化学转化，实现了单次投影光打印。","scd":null,"kp":[]},{"i":43593,"as":"有机发光二极管中实现高效圆偏振发光受限于传统手性微扰策略中手性单元与发光中心间微弱的电子耦合。本研究引入局部反芳香性介导的手性给体-受体策略，将局部反芳香性手性给体与电子受体三嗪单元结合，构建了具有杂化局部和电荷转移激发态的架构，并开启了热激子通道。反芳香性手性给体直接对前沿轨道产生贡献，克服了传统设计的局限性，有效提升了圆偏振发光效率。","scd":null,"kp":[]},{"i":43594,"as":"将二氧化碳电还原选择性转化为正丙醇是低碳化学品合成的重要途径，但在工业级电流密度下实现高选择性仍具挑战。本研究开发了一种Cu2O/CeO2界面催化剂，通过构建*CO─H2O反应微区，有效克服了*CO利用率低和C2产物强竞争的限制。该催化剂设计促进了碳碳偶联反应，实现了二氧化碳向正丙醇的高效、高选择性电化学转化。","scd":null,"kp":[]},{"i":43595,"as":"本研究开发了一种“热封盖与糖基化”策略，利用糖基磺酰肼作为自由基前体，在氧化还原中性镍催化下，直接从天然糖类无保护基合成无保护的芳基碳苷。该两步法工艺无需光照射、色谱分离和外部氧化还原剂。11种无保护单糖表现出高1,2-反式选择性，且能耐受多种官能团。该技术成功实现了列净类降糖药及其类似物的两步组装，提供了可替代光诱导碳苷化反应的放大合成平台。","scd":null,"kp":[]},{"i":43596,"as":"甲脒碘化铅 (FAPbI3) 钙钛矿太阳能电池的光电性能优异，但其长期稳定性受限于晶格应力诱导的光活性α相向非光活性δ相转变。第一性原理计算表明，将Na+引入相邻FA+阳离子间的间隙位点能显著降低α相的形成能，从而促进其热力学稳定。实验结果进一步证实，引入2 mol%的钠磺酸盐有效缓解了应力诱导的非光活性相变，提升了钙钛矿太阳能电池的稳定性和效率。","scd":null,"kp":[]},{"i":43597,"as":"针对癌症进展中由脾脏促肿瘤骨髓生成引起的全身性免疫抑制，研究人员开发了一种工程化特洛伊分枝杆菌作为训练免疫介导的脾脏骨髓生成转换器 (t-SMC)。该制剂具有3.6的纵横比，通过与人血清白蛋白及酶激活的Toll样受体7/8激动剂结合，实现对脾脏的靶向递送和细胞摄取。t-SMC诱导脾脏巨噬细胞发生代谢和表观遗传重编程，将其转化为抗肿瘤骨髓生成，从而激活放大的抗肿瘤训练免疫。","scd":null,"kp":[]},{"i":43598,"as":"在纯硅沸石Silicalite-1 (MFI) 的合成过程中，低于化学计量的碱金属阳离子 (Na+和K+) 对缺陷的形成起着关键控制作用。结合密度泛函理论 (DFT) 和高分辨率显微镜观察发现，原位生成的NaOH或KOH物质能促进Si-O-Si键重排并提高Si(OH)4单元的迁移率。这一“缺陷愈合”机制有效修复了T位空位，使得煅烧后的沸石具有高度有序的骨架结构，从而获得高度疏水的表面特性，为吸附剂和催化剂的设计提供了新思路。","scd":null,"kp":[]},{"i":43599,"as":"无铅介电陶瓷在实现超高储能密度时，面临着大极化强度与高介电击穿强度之间固有的权衡限制。本研究构建了一个可解释的机器学习指导的设计框架，将离子描述符与ABO3基介电基体的极化行为定量关联，从而合理识别出具有高本征极化潜力的组合成分。基于该策略，成功设计出了具有超高压电储能性能的特定组分无铅介电陶瓷，打破了传统材料性能的瓶颈。","scd":null,"kp":[]},{"i":43600,"as":"铜-金属氧化物 (Cu-MOx) 界面对于二氧化碳选择性加氢合成甲醇至关重要。本研究利用瞬态DRIFTS-SSITKA技术，在模型Cu-M/SiO2催化剂上，详细阐明了Zn2+、Ga3+和In3+等原子级分散的M+位点在反应中的具体作用。研究结果明确了这些助剂位点在调控催化剂活性与选择性方面的核心驱动机制，解决了工业Cu/ZnO/Al2O3催化剂中长期存在的界面功能机制争议。","scd":null,"kp":[]},{"i":43601,"as":"DNA折纸纳米结构的硅化处理能够显著提升其机械稳定性和抗恶劣环境的能力。传统方法中，二氧化硅涂层仅作为被动保护层。本研究提出了两种互补且可编程的策略，直接在DNA折纸上制造功能化二氧化硅涂层。第一种方法合成了带有荧光素分子的硅前驱体，成功赋予了涂层荧光功能。该技术使二氧化硅涂层不再仅限于被动保护，而是能够携带特定功能，拓展了DNA基纳米材料的应用。","scd":null,"kp":[]},{"i":43602,"as":"单原子催化剂因其最大化的原子效率、精确的结构和独特的催化性能备受关注。除了中心金属原子作为主要活性位点外，局部配位层在调节其电子结构和反应路径中起着决定性作用，从而主导催化剂的整体活性、选择性和稳定性。本文系统综述了通过合理工程策略精确调控单原子催化剂局部配位环境的基本概念与最新研究突破，强调了配位环境工程在优化电催化性能中的核心作用。","scd":null,"kp":[]},{"i":43603,"as":"在金属基底上直接生长二维半导体能够形成原生且低缺陷的界面。针对第二层在惰性第一层表面生长存在热力学和动力学困难，本研究成功在Au(111)基底上实现了低对称性二硫化铼 (ReX2) 的可控双层生长。由于二硫族化铼具有较弱的层间耦合和多种热力学稳定的堆叠模式，直接生长出的二维双层结构展现出低矫顽力的滑移铁电性，为层间耦合功能器件的制备提供了可靠方法。","scd":null,"kp":[]},{"i":43604,"as":"化学反应通常被视为单一产物的线性优化过程，但自动化技术的进步使得系统探索反应“超空间”成为可能。研究团队利用Robowski机器人平台结合低成本NMR检测，对1,1-二苯基乙烯 (DPE) 和亚苄基丙酮 (BDA) 的溴化反应进行了近1000种条件的扫描。结果不仅绘制了多维条件图谱，还发现了此前未被认识到的主要产物、随条件变化在加成与取代路径之间的切换，以及具有生物活性衍生潜力的新型取代模式。","scd":null,"kp":[]},{"i":43605,"as":"受细菌免疫逃逸机制启发，研究团队开发了锰捕获与释放囊泡用于癌症免疫治疗。该系统基于大肠杆菌外膜囊泡构建，整合表面展示的TssS微肽以捕获内源性锰离子，并在癌细胞内释放。囊泡内载有STING佐剂MSA-2，利用锰离子激活STING通路，从而实现癌症免疫治疗效果。","scd":null,"kp":[]},{"i":43606,"as":"针对高电压准固态电池中阴极/电解质界面不稳定和阴极降解问题，研究提出竞争吸附与结构增强协同（CASR）策略。在聚合物电解质中引入以铜为中心的自吸附分子，通过竞争吸附减少阴极表面的溶剂含量并促进阴离子富集。该过程诱导形成均匀的富氟阴极/电解质界面（富含LiF的外层及内部无机物），有效提升了高电压电池的能量密度与安全性。","scd":null,"kp":[]},{"i":43607,"as":"研究描述了一种新型的萘酰亚胺融合环[8]吡咯类似物，通过硫酸根阴离子的结合实现正构酸性控制。传统的环[8]吡咯易形成全芳香族双阳离子，而该缺电子大环表现出对持久中性氧化态的异常偏好，同时在有机溶剂中展现出极高的布朗斯台德酸性。阴离子识别可极大改变质子化平衡，无需改变分子组成或溶剂即可调节质子活性。","scd":null,"kp":[]},{"i":43608,"as":"为提升无空穴传输层碳基钙钛矿太阳能电池的光电转换效率，研究设计了不对称D−A−D'−A'共轭分子2BCz-BD，并采用共沉积策略将其引入钙钛矿前驱体溶液中。2BCz-BD通过其配位能力调节钙钛矿结晶并钝化表面缺陷，抑制了界面非辐射复合，同时其优异的p型选择性促进了高效电荷提取，从而显著提高了器件性能。","scd":null,"kp":[]},{"i":43609,"as":"本综述通过跨尺度的结构-性质-功能框架探讨了偶氮苯的光学与光子学特性。偶氮苯分子将光吸收转化为可逆的E/Z异构化，嵌入软介质或有序介质后，可转化为光学、机械和生物适应性等功能。文章总结了反式-顺式异构化机制、超快弛豫路径，以及调节吸收波长、量子产率和光稳态的分子设计规则，并探讨了其在介观材料运动和自适应器件中的应用。","scd":null,"kp":[]},{"i":43610,"as":"回复指出，跨越微弱C-H···O氢键的水-油电荷转移过于微小，不足以解释水包油液滴的稳定性和电动实验现象。相内集体密度重排不应与界面电荷转移混为一谈。此外，现有光谱证据无法同时支持C-H蓝移的弱电荷转移和O-H/D红移的强电荷转移；缺乏该特定化学基序时，C-H···O电荷转移机制无法解释其他油乳液的化学行为。","scd":null,"kp":[]},{"i":43611,"as":"为解决反铁电陶瓷在储能密度和储能效率之间的相互制约平衡问题，研究开发了一种铋诱导的局部键合调节策略。该策略在Pb0.92-1.5xSr0.08BixZr陶瓷中通过Bi3+驱动原子-纳米尺度的协同作用，克服了常规弛豫行为牺牲极化强度的限制，有效提升了材料的可回收能量密度（Wrec）和能量存储效率（η）。","scd":null,"kp":[]},{"i":43612,"as":"针对人工光合作用中质子耦合电子转移（PCET）动力学解耦导致产过氧化氢效率受限的问题，研究证明了氢自由基（H•）通过加速*OOH中间体的转化，为H2O2的生成提供了一条替代动力学路径。该机制通过在铜和氧共修饰的Zn3In2S6中调节双氧化还原位点实现，显著提升了光催化合成过氧化氢的效率。","scd":null,"kp":[]},{"i":43613,"as":"研究将氧化锰作为多功能载体，整合经典铑催化中心，构建了用于光驱动甲烷干重整（DRM）的新型光热催化剂。通过结合光子-声子路径与活性晶格氧的协同作用，该系统有效缓解了温和温度下C-H/C=O键活化的动力学限制和积碳问题，实现了创纪录的高合成气产率，同时实现了二氧化碳和甲烷温室气体的减排。","scd":null,"kp":[]},{"i":43614,"as":"针对电催化亚硝酸盐还原过程中强吸附中间体导致催化剂失活的问题，研究提出并验证了一种针对Rh活性位点的电子结构与几何结构预补偿策略。该策略利用金属间化合物RhSb双金属烯，在缓解*NO毒害作用的同时，有效打破吸附能线性比例关系的限制，避免了传统削弱毒化中间体吸附方法带来的催化性能下降，实现了高效的亚硝酸盐电还原。","scd":null,"kp":[]},{"i":43615,"as":"研究开发了一类以AlPO4-5沸石为主体、多种芳香酸（对苯二甲酸、2-萘甲酸和1-芘甲酸）为客体分子的新型长余辉材料。这些主客体复合材料实现了从蓝光到绿光再到红光的可调谐余辉发射。其发光寿命分别长达919毫秒、1540毫秒和74毫秒，且发光强度高，克服了传统主体基质稳定性差的缺陷，在光生物学和光电子学中具应用潜力。","scd":null,"kp":[]},{"i":43616,"as":"研究利用单原子碳到氮（C-to-N）骨架编辑技术对半花菁染料进行改造，精确调节分子内电荷分布和分子间堆积，成功制备出明亮的近红外二区（NIR-II）J-聚集体。系统性受体工程揭示了控制其形成和发光亮度的结构-组装-性质关系。优化后的染料HZOE9形成了发光波长超过1000纳米的稳定J-聚集体，量子产率超越大多数已报道的花菁类NIR-II荧光团，可用于淋巴结转移成像。","scd":null,"kp":[]},{"i":43617,"as":"研究结合空位诱导和静电吸附构建了两种铁双原子纳米酶（pr-Fe-DA和py-Fe-DA），其配位环境分别以吡咯氮和吡啶氮为主。py-Fe-DA表现出卓越的类过氧化氢酶活性，达到100 U mg−1，是pr-Fe-DA的2.4倍。机制表明，铁双原子间的铁磁耦合使催化剂具备自旋有利的催化特性，从而显著提升了催化效率，可用于类风湿性关节炎治疗。","scd":null,"kp":[]},{"i":43618,"as":"研究提出了一种能够识别聚合物链（含有最多1000个重复单元）中单个单体突变的光学策略。该方法依赖于刚性变色荧光团，该荧光团通过极性-π相互作用与聚合物链形成电荷转移复合物（CTC），导致相对于荧光团本征荧光的红移发射。单体突变会改变链内及链间相互作用，调节聚合物主链上的空间共轭，从而改变分子轨道能级并产生可被检测的光学变化。","scd":null,"kp":[]},{"i":43619,"as":"针对废聚酯塑料电催化升级回收中选择性难以控制的问题，研究提出了一种电位门控原理，并设计了PVP-Pd-Ni(OH)2-CV/NF催化剂。该催化剂无需更换催化剂，仅通过切换施加电位即可精确控制α,ω-二醇和羟基酸等关键单体的产物分布。该策略广泛适用于七种不同的聚酯，在可再生能源驱动下实现了资源的高选择性升级回收。","scd":null,"kp":[]},{"i":43620,"as":"为了寻找具有雌激素活性的烷基酚聚氧乙烯醚的可持续替代品，研究利用分子片段重组策略和逆合成分析，开发了生物基环己基脂肪醇聚氧乙烯醚。通过构建酸碱双功能锌基单原子催化剂，实现了该替代品的高效合成。该新型表面活性剂具有广泛的工业应用前景，解决了传统化学品源自石油和对健康产生不良影响的挑战。","scd":null,"kp":[]},{"i":43621,"as":"针对光催化肿瘤疗法中光穿透不足、催化剂易失活及缺氧下催化途径受限等问题，研究开发了一种基于供体-受体共轭大环光催化剂的近红外激活平台。该光催化剂在胶束纳米结构中自组装形成J-聚集体，在808纳米光照射下，能够实现NADH的高效光催化氧化与一氧化氮（NO）释放的耦合，通过打破线粒体氧化还原稳态并释放NO，实现高效肿瘤治疗。","scd":null,"kp":[]},{"i":43622,"as":"为实现聚硅氧烷摩尔质量和结构的精确控制，研究使用阴离子化的1,3-二苯基脲（UA1）作为催化剂进行环三硅氧烷的开环聚合。在庞大的四丁基铵反离子作用下，仅需5-100 ppm的极低催化剂浓度即可在数分钟内实现近100%的单体转化（D3的转化频率高达52000 h−1）。所得聚二甲基硅氧ane具有结构明确、摩尔质量可控（2至140 kg mol−1）的特点。","scd":null,"kp":[]},{"i":43623,"as":"为解决光催化氧还原反应合成过氧化氢（H2O2）选择性低和中间体不稳定的问题，受酶“诱导契合”机制启发，研究提出利用含有非平面连接单元的柔性共轭微孔聚合物调节自适应活性位点。该聚合物能够促使氧分子转化为有利于双电子反应路径的状态，有效抑制了副反应和催化剂失活，实现了高效的光催化H2O2合成。","scd":null,"kp":[]},{"i":43624,"as":"鉴于二氟甲基在调节药物亲脂性和代谢稳定性方面的重要作用，其氘代类似物可进一步增强代谢稳定性。含相邻二氟甲基或氘代二氟甲基的分子可作为重要二醇和氨基醇的生物电子等排体。研究开发了基于2-CF2H(D)-咪唑盐试剂平台的烯烃双(氘代)二氟甲基化方法，在铜/光氧化还原双催化体系下实现了烯烃的直接高效双官能团化。","scd":null,"kp":[]},{"i":43625,"as":"研究证明了在超高真空条件下，通过热激活羟基功能化双碳半酞菁前体，可在Au(111)表面上实现碳卟啉聚合物中可调谐的氧基连接。该过程首先通过[3+3]环芳构化诱导碳-碳偶联，形成带有羟基末端的一维聚合物。通过进一步退火处理，触发相邻聚合物间羟基的脱氢偶联，生成二苯并对二恶英（O-杂环）桥键，从而在金属表面上以原子级精度实现了共价或金属有机结构的氧介导连接调控。","scd":null,"kp":[]},{"i":43626,"as":"研究展示了通过可见光激活电子受体-供体（EDA）复合物，诱导聚(9,9-二辛基芴)（PFO）进行光化学磷酰化反应。基于聚合物的EDA复合物具有扩展的π共轭体系，能够降低激子结合能并促进吸收红移，从而实现高效的可见光收集。这种策略突破了以往EDA介导功能化仅限于小分子芳香族化合物的局限，成功将共轭聚合物作为底物进行光致功能化，展现出优异的反应特性。","scd":null,"kp":[]},{"i":43627,"as":"为解决超稀释电解质（UDE）中游离溶剂过多导致的稳定性与安全性权衡问题，研究提出了一种双域耦合驱动的界面重构策略。通过整合分层溶剂化的碳酸酯、醚和氟化环磷腈，定制了体相溶剂化和界面微环境。该策略设计出的0.05 M超稀释电解质具有更灵活的溶剂化构型，有效降低了离子的运动限制，从而实现了高压稳定性、宽温适应性、长寿命和安全性的协同提升。","scd":null,"kp":[]},{"i":43628,"as":"研究提出一种爆炸驱动方法，成功构建了由铂纳米颗粒修饰的UiO-66催化剂（Pt NP/UiO-66）。通过精确控制炸药用量，原位生成了具有可调拉伸晶格应变（0.229 nm）的铂纳米颗粒，并将其锚定在富含缺陷的UiO-66上，形成界面肖特基结。该催化剂将晶格应变与载体缺陷相集成，有效调整了非均相催化剂的电子结构，并在酸性析氢反应（HER）中作为代表性模型展示了结构与性能的关联。","scd":null,"kp":[]},{"i":43629,"as":"针对有机室温磷光（RTP）材料中主体材料筛选缺乏理论指导的问题，研究提出了一种主体去芳构化策略以延长掺杂体系的余辉发光时间。通过将主体分子中的苯环转化为环己烷结构，掺杂体系的RTP寿命得到显著延长，最大增强倍数达到58.65倍。机理研究表明，主体去芳构化减小了分子间距离，增强了三重态-三重态能量转移和电子耦合，从而实现了发光寿命的大幅延长。","scd":null,"kp":[]},{"i":43630,"as":"受酶联免疫吸附测定（ELISA）中捕获与检测解耦机制的启发，研究开发了一种点击-荧光-释放（CFR）自繁殖检测系统，用于高灵敏度检测肺癌患者血浆中的CD13。该平台包含捕获探针和检测探针：捕获探针将酶生物标志物的检测转化为四嗪检测，随后检测探针通过荧光点击反应特异性识别四嗪。同时，该反应会再生四嗪分子，建立信号放大的自繁殖循环，突破了传统反应型荧光探针化学计量和动力学的限制。","scd":null,"kp":[]},{"i":43631,"as":"研究首次报道了在银催化下，双环[1.1.0]丁烷（BCBs）与原位生成的乙烯基卡宾发生的乙烯基化C(sp3)-C(sp3)交叉偶联反应。该反应在温和条件下进行，能够高收率、优异的区域选择性和非对映选择性地合成含有季碳中心的烯丙基取代环丁烯。该方法成功解决了金属乙烯基卡宾因中心高反应活性导致其乙烯基化反应难以探索的合成难题。","scd":null,"kp":[]},{"i":43632,"as":"研究提出了一种基于“立体锁定”概念的纯有机分子设计策略，仅由碳和氢组成的二芳基苯衍生物实现了窄带发射。该策略利用两个芳基之间的分子内空间相互作用，有效抑制了分子内C-C/C-H伸缩并减弱了振动耦合。在80 K下单分子发射的半峰全宽（FWHM）仅为6 nm，创下新纪录。在固态下，其聚集体通过分子间正激子耦合进一步发挥作用，为下一代显示和照明应用提供了高纯度发射材料方案。","scd":null,"kp":[]},{"i":43633,"as":"针对双电子锂碘（Li-I2）电池中碘阳离子热力学不稳定和多碘化物穿梭效应的瓶颈，研究合成了一种吡啶功能化的共价有机框架（BPY-COF-HI）阴极。该阴极具有动态双功能位点，能够有效锚定和活化碘物种，实现碘的高可逆多价态转变（I-/I0/I+）。这种设计和制备策略成功克服了碘物种不稳定的难题，显著提升了Li-I2电池的性能。","scd":null,"kp":[]},{"i":43634,"as":"研究开发了首个二维手性杂化氟锆酸盐(R/S-MBA)ZrF5。通过高价Zr-F框架实现的反向量子阱工程，该材料表现出独特的反向I型量子阱电子结构：[ZrF5]无机层作为介电屏障，能带边缘状态局域化。这种基于氟锆酸盐的体系克服了传统Ge/Sn/Pb体系带隙窄、耐湿性差的缺陷，在耐水性的同时解锁了巨大的紫外手性非线性光学响应。","scd":null,"kp":[]},{"i":43635,"as":"文章指出，学术界对粉末X射线衍射（PXRD）图谱匹配的定性依赖，导致共价有机框架（COF）的结构被系统性地过度解释。这种不严谨的做法掩盖了结构-性能关系，引发误导性的机理结论并降低性能再现性。文章通过具体案例揭示了结构模型与表征数据不匹配的常见问题，强调必须通过互补的表征技术建立更严格、基于证据的方法，以实现可靠的COF结构解析。","scd":null,"kp":[]},{"i":43636,"as":"研究针对锂离子电池在极速快充（XFC）条件下的性能提升，探讨了双阴离子电解质动力学机制。除了削弱Li+溶剂化作用外，增强的Li-阴离子配对在形成阴离子衍生、富含无机物的电极-电解质界面（EEI）中起关键作用。研究提出了利用体相电解质传输、去溶剂化能和界面动力学的阴离子筛选准则，旨在解决双阴离子电解质在碳酸酯和酯类溶剂中的界面不稳定性等核心挑战。","scd":null,"kp":[]},{"i":43637,"as":"文章探讨了利用PET水解酶研究的信息来指导蛋白质设计和表面功能化策略，从而促进功能蛋白质与PET表面稳定结合，开发功能蛋白-塑料混合材料。重点介绍了能够更精确控制蛋白质在PET材料上取向的化学生物学方法。通过借鉴蛋白质-聚合物界面化学的生物物理学见解，指导蛋白质的筛选和工程设计，以最大程度减少变性并最大化其功能，从而提升PET的生物功能化多样性。","scd":null,"kp":[]},{"i":43638,"as":"为解决水系锌电池中寄生反应和枝晶生长的限制，研究通过原位自聚合策略设计了一种聚两性离子“离子海绵”界面。在电场诱导下，两性离子单体聚合形成超薄聚两性离子层，该层在界面处静电富集阴离子（OTf-、SO42-）并排斥水分子。这种独特的微环境使得阴离子发生原位还原转化为ZnF2，从而赋予了锌电池超凡的耐久性。","scd":null,"kp":[]},{"i":43639,"as":"","scd":null,"kp":[]},{"i":43640,"as":"研究利用两性三（膦）硼烷配体，成功稳定了铝(I)卤化物，揭示了铝的前所未有的配位化学特性。结合实验与计算详细分析了这些新化合物独特的电子结构。通过路易斯碱与Al原子的配位后功能化，成功分离出处于低氧化态的Al阳离子。此外，研究还实现了将Al(I)Br转移到2,2'-联吡啶配体上，展示了该策略在稳定难以捕获的主族金属片段方面的巨大潜力。","scd":null,"kp":[]},{"i":43641,"as":"为了克服固态聚合物电解质中Li+-TFSI-强耦合导致的室温电导率低的问题，研究通过将Br-反离子交换为BF4-，调控了烯烃连接的吡啶鎓离子共价有机框架的局部路易斯酸碱环境。引入的路易斯酸性位点能够竞争性结合TFSI-阴离子，从而释放Li+。该研究揭示了局部路易斯酸碱调节与离子传输之间的内在联系，有效促进了Li+在固态体系中的传输。","scd":null,"kp":[]},{"i":43642,"as":"研究通过构建轴向N桥键和相邻的Cu-N4位点，在空心双层Fe-Cu双单原子催化剂（HFeCu-N-C DSACs）上实施了Fe 3d轨道自旋极化调控。实验与理论证据表明，轴向N桥键破坏了Fe-N4的D4h对称性，打断了不对称Fe-Cu双原子的d-π共轭。这种对称性破坏和电子结构调控策略显著增强了二氧化碳电还原反应（CO2RR）的催化性能。","scd":null,"kp":[]},{"i":43643,"as":"针对氘-氚聚变产物“氦灰”在等离子体中积累会引发燃料稀释并降低约束性能的问题，研究利用TGYRO输运求解器结合NEO和TGLF代码，模拟了中国聚变工程实验堆（CFETR）稳态场景下的氦灰输运。分析表明，CFETR中的氦灰输运主要由ITG湍流主导。此外，在低氦灰比例下，氦灰密度分布会发生重新排列，该结果揭示了聚变堆内杂质输运的关键机制。","scd":null,"kp":[]},{"i":43644,"as":"为解决耐甲氧西林金黄色葡萄球菌等病原体引起的植入物相关感染，研究开发了一种钛植入物表面的高效抗生物被膜涂层。通过电化学方法构建二氧化钛纳米管阵列（TNTA）并负载万古霉素，随后涂覆掺有功能化氧化石墨烯和L-精氨酸的聚己内酯纤维。这种分级纳米管-氧化石墨烯-精氨酸界面设计，实现了植入后前四周内可调的药物释放及显著增强的抗菌性能。","scd":null,"kp":[]},{"i":43645,"as":"该研究通过引入B-O动态键构建了具有剪切硬化效应的聚氨酯（BPUB），并结合底层快修复涂层，制备了一种双层聚合物防腐涂层。该涂层系统集成了剪切变稀、剪切增稠和转移自愈能力，能够对大于20 J/mm的高冲击损伤进行自主快速修复（针对大划痕约需5小时）。实验表明，多层防腐涂层在受损后仍能保持1.32×10^10 Ω·cm2的高阻抗，并在250天后展现出长期的耐久性和室温自愈性。","scd":null,"kp":[]},{"i":43646,"as":"","scd":null,"kp":[]},{"i":43647,"as":"研究在柔性云母基底上成功制备了高熵Pb0.9Ba0.1Ti0.25Hf0.25Zr0.25Sn0.25O3 (PBTHZS)铁电薄膜。通过熵工程引入多阳离子固溶体，在原子尺度上引发结构局部无序和晶格畸变，促使电子分布重排，并与晶格膨胀耦合从而增强宏观极化。结果表明，PBTHZS薄膜展现出优异的铁电性能（如剩余极化），满足了柔性电子对高性能非易失性存储器的需求。","scd":null,"kp":[]},{"i":43648,"as":"针对三氧化钼(MoO3)作为锂离子电池负极材料时电导率低和充放电过程中体积膨胀显著的问题，研究通过引入氧空位提升导电性并扩大晶格距离。同时，结合具有丰富活性位点、大共轭结构和高比表面积的共价有机框架作为有机负极材料，制备了MoO3-x掺入的共价有机框架纳米复合材料，协同改善了锂离子电池的比容量和循环稳定性。","scd":null,"kp":[]},{"i":43649,"as":"针对细菌性眼内炎治疗中药物释放不足和需频繁注射的问题，研究开发了一种可注射的双效捕获细菌纳米酶复合水凝胶。该水凝胶基质通过季铵化壳聚糖与氧化葡聚糖之间的动态席夫碱交联构建，具备优异的可注射性和生物相容性。网络中集成了硼酸修饰的铈金属有机框架，实现了“捕获-杀灭”细菌与免疫调节的协同抗菌和抗炎治疗。","scd":null,"kp":[]},{"i":43650,"as":"研究采用密度泛函理论(DFT)计算，系统探究了包含锰、铬、铁等过渡金属的单、双及三元NASICON结构钠离子电池正极材料。计算结果表明，单过渡金属体系在中等钠含量下表现出明确的稳定化相行为，而双元和三元过渡金属体系则展现出不同的相变特征。该研究揭示了多种过渡金属对NASICON正极性能的影响机制。","scd":null,"kp":[]},{"i":43651,"as":"为解决二维导电金属-有机框架因层间堆叠导致活性位点暴露不足的问题，研究利用ZIF前驱体通过原位配体交换和溶解-扩散-重结晶动力学机制，首次合成了具有空心结构的二维c-MOF@MXene异质结。在室温条件下引入Ti3C2Tx，实现了对空心形貌的精确控制，显著提升了该材料作为新一代高能量密度器件负极的储锂性能。","scd":null,"kp":[]},{"i":43652,"as":"为提升1.5T手腕磁共振成像(MRI)的信噪比(SNR)和图像质量，研究开发了一种高性能保形超材料。传统增加线圈通道的方法已遇物理极限，而无线无源超材料可通过射频场调制增强局部磁场。该研究克服了常规超材料难以贴合解剖轮廓的缺陷，设计出能提升空间填充因子的保形结构，为MRI信噪比增强提供了新路径。","scd":null,"kp":[]},{"i":43653,"as":"多金属氧酸盐(POMs)具有框架稳定、氧化还原性质可调及制备成本低等优势。将POMs引入钙钛矿基器件中，可精确调制钙钛矿的光电特性，并通过优化电荷传输层等功能层提升器件整体性能。两者在功能和结构上互补协同，在下一代光电器件的能量转换与环境管理中展现出重要应用价值。","scd":null,"kp":[]},{"i":43654,"as":"","scd":null,"kp":[]},{"i":43655,"as":"研究采用含有有序径向纳米通道阵列的空心纳米碳球作为载体，设计出高性能金属间化合物纳米颗粒燃料电池催化剂。该载体结构成功克服了金属间相有序度与纳米颗粒分散度之间的权衡问题，有效提升了催化剂的综合性能。","scd":null,"kp":[]},{"i":43656,"as":"研究开发了光谱生物物理流式细胞术(SBC)高通量平台，结合环境敏感型纳米传感器与光谱流式细胞术，实现单细胞分辨率下免疫细胞多参数生物物理特性的同步定量。利用荧光纳米传感器报告细胞膜序、线粒体电位和膜电位，SBC技术揭示了动脉粥样硬化中免疫细胞的物理状态重塑现象。","scd":null,"kp":[]},{"i":43657,"as":"英国物理和天文领域面临科研经费削减，多个重要项目的资金被终止，其中包括未来在欧洲核子研究中心(CERN)开展的实验项目，以及标志性的洛弗尔射电望远镜的运营资金受到影响。","scd":null,"kp":[]},{"i":43658,"as":"人工智能代理技术正被用于审查科学文献，并成功在几十年前发表的旧论文以及参考数据库中发现错误。该技术在核查历史学术记录和数据库准确性方面展现出卓越能力。","scd":null,"kp":[]},{"i":43659,"as":"研究通过配体调制策略，利用两种含有不同有机间隔物的零维锰锌溴化物体系，探究无铅金属卤化物在X射线成像中的放射发光效率与稳定性机制。尽管两种体系均具有接近1的光致发光量子产率(PLQY)，但通过改变有机间隔物长度和金属间距，可实现截然不同的闪烁响应，揭示了结构与放射发光性能之间的关系。","scd":null,"kp":[]},{"i":43660,"as":"研究利用联苯胺的三种同分异构体作为碳源，通过溶剂热法合成碳量子点，探究前驱体空间构型对其性能的调控机制。异构体诱导的聚合差异导致碳点的尺寸分布和能带结构产生显著区别。其中，由间苯二胺合成的MPD-CDs表现出最优的综合性能，在食品中亚硝酸盐的高选择性荧光传感及体内成像中展现出应用潜力。","scd":null,"kp":[]},{"i":43661,"as":"研究利用分子束外延(MBE)两步法，在超高真空环境下于高定向热解石墨(HOPG)和碳化硅外延双层石墨烯上成功外延生长二硫化钨(WS2)。扫描隧道显微镜/谱揭示了3度和19.1度扭转角下的显著莫尔周期，以及台阶介导的生长机制对WS2晶格取向和晶界形成的关键影响。","scd":null,"kp":[]},{"i":43662,"as":"为解决可充电镁离子电池的电化学窗口窄和界面不稳定等问题，研究设计了由高氯酸镁、乙酰胺、己内酰胺和水组成的多元水合低共熔电解质(DM11)。该电解质重构氢键网络并将水活性降低，使电化学稳定窗口拓宽至4V。其在镁表面形成有机-无机杂化层隔离水分子并减少腐蚀，显著提升了镁电池的输出电压性能。","scd":null,"kp":[]},{"i":43663,"as":"","scd":null,"kp":[]},{"i":43664,"as":"","scd":null,"kp":[]},{"i":43665,"as":"本文基于系统动力学模型评估了意大利电力市场在长期差价合约和纯商业投资两种政策配置下的演化路径。通过2024至2035年的蒙特卡洛模拟，研究对比分析了可再生能源、储能采购机制、容量补偿工具及电网升级对系统成本的影响，探讨了意大利在确保电价可负担的前提下实现脱碳和能源安全的政策目标。","scd":null,"kp":[]},{"i":43666,"as":"研究报道了在低温气相条件下，氟、氯、溴卤素离子结合于基于双环酰胺的穴状分子笼内的红外光谱与结构分析。结合红外-紫外双共振技术与第一性原理计算发现，1·F-络合物被指认为含有六个NH···F-和三个芳香族CH···F-氢键的9配位D3对称结构。卤素离子的尺寸变化触发了分子笼从手性D3到三棱柱的构型改变。","scd":null,"kp":[]},{"i":43667,"as":"为解决零价铁(ZVI)材料因铁循环受阻而效率降低的问题，研究通过接枝邻苯二酚羟基改性ZVI(TA-ZVI)，在亥姆霍兹外平面重塑了双齿氢键网络。该网络增加了弱结合水比例，提高了界面极化弛豫，降低了质子耦合电子转移(PCET)动力学屏障，促进了活性氢(H*)的生成、传输与利用，从而加速了界面反应动力学。","scd":null,"kp":[]},{"i":43668,"as":"研究使用路易斯碱性异硫脲催化剂，实现了铵叶立德带有杂芳基取代基的不对称Sommelet-Hauser重排反应。该催化方法通过脱芳构化和重排机制，合成了一系列具有高对映选择性（对映体比率高达98:2）的非天然α-杂环基α-氨基酸衍生物，突破了以往依赖化学计量手性辅助基团的局限。","scd":null,"kp":[]},{"i":43669,"as":"研究采用紫外-红外双共振激发方案，在具有231个振动模式的低温气相质子化五肽离子[YGGYL+H]+中，实现了对两个酪氨酸发色团O-H键的位点与模式选择性光解离。通过激光驱动穿过圆锥交叉点的隧穿机制，利用相隔324 cm-1的紫外吸收差异，实现了对特定酪氨酸1ππ*态的位点专属激发与化学键断裂。","scd":null,"kp":[]},{"i":43670,"as":"研究团队开发了具有红外带隙的核/壳结构HgCdTe/HgCdSe量子点。该量子点通过CdTe/CdSe量子点的汞阳离子交换法制备，其电荷载流子波函数由结构尺寸及汞镉的径向分布控制。通过该方法，汞可选择性地集中在核心或外壳，甚至完全耗尽镉生成HgTe/HgSe量子点。不同的合金化状态能够改变量子点的能带位置，拓展了其在红外光电子领域的应用潜力。","scd":null,"kp":[]},{"i":43671,"as":"为抑制在多种癌症中起关键作用的hOAT酶，研究人员设计并合成了hOAT时间依赖性抑制剂(1S,3R,5R)-3-氨基-6,6-二氟双环[3.1.0]己烷-1-羧酸。该分子的设计基于δ-去质子化和环应变介导的失活机制，能够通过应变释放驱动的开环反应实现对hOAT的失活。结构与机制研究证实了该抑制剂的失活机制，为肝细胞癌等癌症的机制靶向治疗提供了新方法。","scd":null,"kp":[]},{"i":43672,"as":"研究报道了罕见[5-5-6-7]四环二萜类化合物venezuelaene A的首例不对称全合成。该分子具有高应变的反式稠合双环结构和六个连续的手性中心。合成策略包括：使用TEMPO+BF4–介导的氧化Nazarov环化构建关键季碳中心；利用Stoltz脱羧烯丙基化高非对映选择性地引入相邻季碳中心；通过关键的分子内碳原子转移解决同系化与立体化学控制难题；最后利用烯-炔-烯级联复分解反应高效构建复杂多环系统。","scd":null,"kp":[]},{"i":43673,"as":"研究提出了一种利用临床超声驱动N-氧化物还原脱氧的策略，实现了时空可控的肿瘤前体药物激活。该平台利用核黄素四丁酸酯/NADPH氧化还原中继系统，在1 MHz、2.0 W/cm²的温和超声条件下，通过单电子转移和氢原子转移高效断裂N-O键。密度泛函理论计算证实该声化学还原过程的各基态步骤均具有负吉布斯自由能变，在热力学上高度可行。","scd":null,"kp":[]},{"i":43674,"as":"研究通过分析一氧化碳分子在Ag(100)表面外延生长的超薄MgO薄膜上的扩散机制，证实了表面声子能够通过振动-声子耦合主动诱导分子扩散。利用扫描隧道显微镜的动态光谱学和密度泛函理论计算，研究揭示了基底声子对吸附质行为的直接影响。这一发现补充了传统的电子、热和光致分子激发路径，对深入理解表面基本化学过程具有重要意义。","scd":null,"kp":[]},{"i":43675,"as":"针对传统有机余辉化学发光成像中存在的底物消耗不可逆和能量传递效率低等问题，研究开发了一种独立高效的吡啶酮支架作为通用余辉发光平台。2-吡啶酮作为稳定且不消耗的底物，有效防止了底物耗尽和发射蓝移；同时通过共价键与能量中继单元连接，确保了高效的能量传递。该设计成功克服了传统多组分混合系统的固有缺陷，大幅提升了高对比度生物医学成像的性能。","scd":null,"kp":[]},{"i":43676,"as":"为解决水系锌碘电池中I+水解和氧化还原动力学迟缓的问题，研究人员引入1-乙基溴化吡啶作为电解液添加剂，设计了水系锌-双卤素（碘-溴）电池。该设计利用卤素间化合物内部的电子推拉效应，实现了包含四电子路径（I-/I2Br-/IBr2-）和随后的两电子路径的可逆六电子转换反应。该机制显著提升了电池容量和长期循环稳定性，原位X射线吸收光谱等表征手段验证了该转化路径。","scd":null,"kp":[]},{"i":43677,"as":"研究实现了一种由钯催化不对称分子内内烯烃远程氢胺化反应。该反应通过连续的烯烃氨钯化、钯迁移和末端烷基钯中间体还原步骤进行，以良好的收率和高对映选择性构建了哌啶酮、吡咯烷酮和噁唑烷-2-酮等手性含氮杂环骨架。机制研究证实，氨钯化反应的立体化学结果和可逆性强依赖于溶剂的选择，为复杂含氮杂环化合物的合成提供了稳健的方法。","scd":null,"kp":[]},{"i":43678,"as":"研究开发了一种由铜催化的对映选择性烯丙基模拟羟基化反应新路径。该方法通过不对称烯丙基模拟亚硝基醛加成反应，随后进行铜介导的N-O键断裂，突破了传统反应在区域选择性、对映选择性和氧供体氧化反应活性方面的限制。该催化体系统一且高效，能够兼容多种烷基底物与官能团，为合成对映体富集的γ-羟基-α,β-(E)-不饱和羰基化合物骨架提供了通用方案。","scd":null,"kp":[]},{"i":43679,"as":"研究利用闪速焦耳加热这种非平衡合成策略，开发出一种富含缺陷的双功能LD-VO-CoO/Co3O4@C异质结催化剂。该催化剂含有大量氧空位和明显的晶格畸变，将硝酸根电还原与PET塑料回收进行耦合，实现了高选择性的甲酸铵成对电合成。在测试中，该催化剂的氨产率高达78.94 mg h⁻¹ cm⁻²，法拉第效率为97.14%，且在300小时内保持优异稳定性，超越了现有的单金属钴基催化剂。","scd":null,"kp":[]},{"i":43680,"as":"研究提出了一种“生产者脱碳贡献”量化框架，重新评估了中国光伏制造企业在全球能源转型中的减排作用。该研究打破了将碳排放归咎于制造商而将减排益处归于发电端的传统核算方式。分析显示，中国光伏制造商贡献了中国光伏总减排量的31.4%至73.8%，以及全球的27.9%至45.4%。此外，研究还界定了光伏减排效益抵消其制造碳排放的“战略时间点”，凸显了上游生产商在全球脱碳中的关键贡献。","scd":null,"kp":[]},{"i":43681,"as":"为验证地震预测系统的科学有效性，研究团队对2007至2018年间运行的27个地震预测模型进行了前瞻性评估。该项目针对加州地区生成了51,625次次日Mw≥3.95的地震活动预测。使用社区认可的统计方法，对这些模型针对597次实际地震事件的预测能力进行了全面基准测试。结果显示，约95%的两步和时间依赖型模型在长期前景观测中展现出一致性，证明了当前业务化地震预测模型预测技能的可靠性。","scd":null,"kp":[]},{"i":43682,"as":"为解决液态金属纳米粒子在制备和应用中极易被氧化和脱合金化的难题，研究提出了一种使用天然配体植酸（PA）的绿色稳定策略。植酸分子上的六个强给电子磷酸基团提供六个锚定位点，与镓离子（Ga3+）发生多齿络合，在纳米粒子表面形成坚固的化学钝化层。通过调节植酸浓度，能够精确控制钝化膜厚度和PA络合液态金属纳米粒子的大小，显著提升了液态金属材料的抗氧化性能。","scd":null,"kp":[]},{"i":43683,"as":"研究发现1,3,4-噻二唑-N-氧化物（TNO）杂环支架在生物介质中具备高稳定性，且能与双环[6.1.0]壬-4-炔类高张力炔烃发生前所未有的双重加成反应。利用这一独特的反应活性，研究人员实现了在每个连接位点上特异性地附着两个探针分子。该技术突破了增加药物载荷会损害蛋白质靶向特性的限制，为精准医学中构建具有高抗体载药量的蛋白质生物偶联物提供了全新且高效的途径。","scd":null,"kp":[]},{"i":43684,"as":"","scd":null,"kp":[]},{"i":43685,"as":"研究报道了 unusual 大戟科二萜化合物 curcusone I 的首例不对称全合成，确证了其此前经计算修正的分子结构。合成路线通过Rh催化含硒[2,3]-σ重排级联反应和由添加剂控制的SmI2介导环化，高效且非对映选择性地构建了常见的[5-7-6]三环核心骨架。此外，利用独特的跨环5-endo-trig氧杂-Michael加成反应成功构建了其氧杂双环[3.2.1]辛烷框架，最终高立体选择性地安装了分子中的全部八个手性中心。","scd":null,"kp":[]},{"i":43686,"as":"研究表明，地球系统的变化在大气二氧化碳浓度下降后仍会长期持续。研究审视了全球海洋酸化的演变，重点指出即使在全球实现负排放的情景下，北极海域也将是全球缓解海洋酸化最晚的区域。","scd":null,"kp":[]},{"i":43687,"as":"","scd":null,"kp":[]},{"i":43688,"as":"","scd":null,"kp":[]},{"i":43689,"as":"","scd":null,"kp":[]},{"i":43690,"as":"","scd":null,"kp":[]},{"i":43691,"as":"","scd":null,"kp":[]},{"i":43692,"as":"","scd":null,"kp":[]},{"i":43693,"as":"为统计近期袭击亚洲和欧洲等地区的致命热浪所造成的死亡人数，科学家们正采用两种截然不同的方法来估算热浪对人类造成的实际生命伤亡代价。","scd":null,"kp":[]},{"i":43694,"as":"研究通过测量下落液滴撞击表面时引发的形变，深入探究了“滴水穿石”的物理力学过程，这些新数据为量化水滴侵蚀坚硬物质的力学能力提供了科学见解。","scd":null,"kp":[]},{"i":43695,"as":"研究指出，在美洲狮等大型猫科动物频繁活动的区域巡逻，可以有效减少鹿群在公路上的出没，从而显著降低车辆与鹿群发生严重相撞事故的风险，起到了变相的驾驶员“守护神”作用。","scd":null,"kp":[]},{"i":43696,"as":"研究团队推出了名为WeatherNext Cyclones (WN-C)的人工智能天气模型，用于全球热带气旋的业务化预报。该模型结合全球分析数据和历史气旋数据库进行训练，可生成预测未来15天的全球天气和气旋大集合预报。针对2023至2025年气旋的评估显示，WN-C在路径、强度和风圈半径预测上，比现有的顶尖业务化模型平均提前了一天或更多的预警时间，其准确度提升幅度相当于过往多年的研究进展。","scd":null,"kp":[]},{"i":43697,"as":"土壤微生物组蕴含支撑养分循环等生态系统服务的遗传资源。研究人员基于1609个土壤宏基因组样本，绘制了全球土壤微生物遗传资源的热点分布图，为制定切实可行的保护目标提供了科学依据。","scd":null,"kp":[]},{"i":43698,"as":"土壤病毒、微生物与动物之间的相互作用构成了统一的生物环，控制微生物残体并调节土壤碳储存。该研究提出了一种由病毒介导的微生物碳泵理论，为解释全球变化下的土壤碳汇机制提供了新框架。","scd":null,"kp":[]},{"i":43699,"as":"由液滴界面双分子层分隔的致密乳液能够模拟软组织。该技术实现了仿生合成组织的高通量生产与打印，为合成生物学和生物材料领域提供了新的制造方法。","scd":null,"kp":[]},{"i":43700,"as":"树木的水分传导特性决定了山地树种在气候变暖下的分布范围迁移。对气候敏感的物种会向更高海拔追踪变暖趋势，而具有抗逆性的物种则会向低海拔扩张。","scd":null,"kp":[]},{"i":43701,"as":"在Mn(Bi,Sb)2Te4合金中施加磁场会引发同时的磁性转变和拓扑相变。这一现象在红外波段产生了异常强烈的圆二色性效应，为拓扑量子态研究提供了新方向。","scd":null,"kp":[]},{"i":43702,"as":"一种设计简单的磁悬浮传感器能够在环境温度下测量磁场。该装置具备高灵敏度，可探测极微弱的大脑活动，在生物物理学研究中可替代复杂的传统设备，并具备搜寻暗物质的潜力。","scd":null,"kp":[]},{"i":43703,"as":"在烹饪使淀粉易于消化之前，水果和蜂蜜中的糖分提供了大脑所需的首选燃料葡萄糖。模型表明，在400万年的人类进化史中，糖分提供了超过25%的饮食能量，满足了大脑发育和繁殖的基础葡萄糖需求。脑容量的扩大与碳水化合物食物的摄入密切相关。","scd":null,"kp":[]},{"i":43704,"as":"一位作家通过列举极端的环境破坏案例，对工业资源开采造成的地球生态牺牲土地进行了严厉控诉和批判。","scd":null,"kp":[]},{"i":43705,"as":"两位出版业内部人士将近期提升研究获取权限的各项举措视为引发的问题，而非科学出版领域的积极进步。","scd":null,"kp":[]},{"i":43706,"as":"燃油车是美国大多数家庭最大的二氧化碳排放源。研究评估了在生命周期结束前报废正常运转的燃油车并替换为电动车的气候效益。结果显示，在包括报废新车在内的大多数场景下，这种“报废替换”策略均能实现一致的温室气体减排。","scd":null,"kp":[]},{"i":43707,"as":"研究开发了一种抗磁稳定悬浮磁性磁力计，通过光学检测悬浮磁体的运动，在室温下实现了每平方根赫兹32飞特斯拉的磁场测量灵敏度，可媲美超导量子干涉器件和原子磁力计，适用于生物、化学及基础物理领域的精密测量。","scd":null,"kp":[]},{"i":43708,"as":"蜗牛通过在分泌的粘液中加入VI型胶原蛋白和无定形碳酸钙（ACC）来制造具有多种功能的材料。ACC在湿润粘液中作为交联离子源，在干燥粘液中作为矿物前体。钙元素的加入使得蜗牛粘液能够实现润滑、粘附、保护和防御等截然不同的功能。","scd":null,"kp":[]},{"i":43709,"as":"2010至2023年期间，西伯利亚生长季的甲烷排放量增加了12.0±1.9 Tg（每年5%）。气候变暖导致东西伯利亚干旱引发火灾，促使火灾相关甲烷排放增加；而西西伯利亚变湿则增强了产甲烷作用。这揭示了由变暖和海陆气相互作用引发的气候-碳反馈机制。","scd":null,"kp":[]},{"i":43710,"as":"通过对灵长类化石和现生物种的虚拟脑内模研究，发现新皮层的扩张与视神经孔面积的增加同步发生。额叶遵循异速生长规律缓慢演化，而非前额皮层区域则在类人猿中发生快速扩增。化石证据表明，视觉感官输入在灵长类新皮层的模块化演化中发挥了关键作用。","scd":null,"kp":[]},{"i":43711,"as":"研究结合细胞合成货物运输测定与AlphaFold2引导的诱变技术，在线粒体适配蛋白（TRAK）中发现了一种调节螺旋，该螺旋介导驱动蛋白和动力蛋白之间的运输切换。压力激酶对该螺旋的磷酸化作用改变了运输方向，解释了两种相似的TRAK异构体将线粒体运送至相反方向的机制。","scd":null,"kp":[]},{"i":43712,"as":"研究发现地震声学数据可用于分析飓风边界层（HBL）湍流。通过结合大涡模拟和弹性变形建模，验证了HBL湍流在次声压和地震位移中的贡献。连续的次声压可作为10米风速的替代指标，其压力谱的惯性子区可估算湍流耗散率。","scd":null,"kp":[]},{"i":43713,"as":"","scd":null,"kp":[]},{"i":43714,"as":"真菌物种耳念珠菌能够抑制宿主的抗真菌免疫防御机制，从而在宿主皮肤上建立有利于自身生存和定植的微生态环境。","scd":null,"kp":[]},{"i":43715,"as":"基于灵长类头骨的虚拟模型研究，支持了视觉系统的发展在灵长类大脑容量演化过程中发挥了重要影响的假说。","scd":null,"kp":[]},{"i":43716,"as":"通过地震仪观测网络，研究人员成功测量了飓风“艾萨克”登陆期间引发的大气湍流，证实可以通过监听风暴震动地球的信号来研究极端天气。","scd":null,"kp":[]},{"i":43717,"as":"利用人工智能生成功能性病毒基因组的技术引发了紧迫的生物安全和生物安保问题，凸显了在基因组合成与设计领域加强监管和风险评估的必要性。","scd":null,"kp":[]},{"i":43718,"as":"重掺杂、高度补偿的外延氮化钪（ScN）薄膜在室温附近展现出超过-124 mV/K的塞贝克系数，突破了传统晶体的热电势极限。带电杂质的随机分布引发了电子能带扭曲和渗流传输。在超薄膜中，Coulomb势的Rytova-Keldysh修正进一步放大了势能波动。结果揭示了热电势与电导率之间的幂律比例关系。","scd":null,"kp":[]},{"i":43719,"as":"","scd":null,"kp":[]},{"i":43720,"as":"","scd":null,"kp":[]},{"i":43721,"as":"在当前地缘政治环境下，人工智能（AI）对经济增长、科研和国家安全至关重要。印度将主权置于AI战略核心。为实现真正的AI主权，印度需超越芯片、数据中心和大语言模型等基础设施，重点关注上方的应用层，即能够完成现实世界工作的AI代理等软件和工具。成功实施将为其他国家提供实现AI主权的模板。","scd":null,"kp":[]},{"i":43722,"as":"","scd":null,"kp":[]},{"i":43723,"as":"报告指出，在5月15日官方正式宣布疫情爆发之前，刚果（金）某矿业城镇已被恐惧笼罩，并已发生数百人因埃博拉病毒致死的事件，该病毒在雷达监测之下已隐秘传播了数月。","scd":null,"kp":[]},{"i":43724,"as":"NASA的PUNCH任务由四颗卫星组成，旨在提升太空天气预报能力。该卫星编队展现了破纪录的预测能力，能够有效预测太阳爆炸物到达地球的时间。","scd":null,"kp":[]},{"i":43725,"as":"科学家通过对野牛的DNA进行基因测序与分析，在其中发现了揭示该动物过去历史演化的重要线索，同时这些基因数据也为未来如何保护和保障野牛种群的安全提供了关键方法。","scd":null,"kp":[]},{"i":43726,"as":"针对高风险病原体的“功能获得性”研究的禁令范围正在进一步扩大。针对生物学研究的这些新监管规则在科学界内获得了毁誉参半的评价与反馈。","scd":null,"kp":[]},{"i":43727,"as":"重新构想人工智能（AI）的概念和衡量标准需要建立新的测试评估方法。未来的新型图灵测试应以多样性、合作性和系统性为核心指导原则，从而更准确地评估AI领域的进步与发展。","scd":null,"kp":[]},{"i":43728,"as":"每周服用一次的HIV口服药研发取得了接近成功的进展。然而，在一项大型临床试验中，研究人员期望HIV疫苗能够激发出的强效抗体未能有效预防HIV感染，这一结果给HIV疫苗研究带来了新的疑问与挑战。","scd":null,"kp":[]},{"i":43729,"as":"全球性的冰河时期变化或海洋环境的剧变，可能解释了地球历史早期大气中氧气含量在经历初步上升后出现神秘停滞的原因。这些环境因素最终促发了大气中氧气的急剧激增。","scd":null,"kp":[]},{"i":43730,"as":"Kagome晶格材料因能带拓扑、自旋轨道耦合、磁性和电子关联的相互作用而产生奇异量子现象。研究结合μ子自旋谱学和能带计算，在ScIr2手性晶体中发现了非常规超导性的证据。母体化合物发生从立方相到菱方相的结构转变，尽管硅（Si）取代抑制了结构相变，但超导配对特性依然存在。","scd":null,"kp":[]},{"i":43731,"as":"研究将苯并二噻吩二酮单元引入PCE10骨架，开发了两种具有更深能级的窄带隙三元聚合物给体PS1和PS2。PS2表现出适当的分子堆积和结晶度，以及与受体PY-IT良好的混溶性。利用窄带隙聚合物给体和受体的波长选择性，该研究有效平衡了全聚合物半透明有机太阳能电池的光吸收与透光率，同时提升了器件的电压和稳定性。","scd":null,"kp":[]},{"i":43732,"as":"非辐射能量损失限制了有机太阳能电池（OSCs）的效率提升。研究基于理论计算，开发了一系列以苯并咔唑为核心、苯并[b]噻吩为功能基团的新型自组装界面层（SAI）材料（BT-nBZCz）。研究系统考察了其对非辐射损失的影响，其中引入BT-4BZCz的二元OSCs实现了显著提高的光电转换效率。","scd":null,"kp":[]},{"i":43733,"as":"研究引入光散射显微镜，实现了对单个钴酸锂（LCO）颗粒相变路径的实时光学可视化。通过解码H1、H2和H1-3相的光学特征，追踪了电池运行中的相界演变。未掺杂LCO在高压循环中表现出渐进的动力学失稳；而铝掺杂有效抑制了这种动力学失稳，实现了动力学均质化。","scd":null,"kp":[]},{"i":43734,"as":"CLIP1-LTK癌基因融合不仅依赖激酶活性，还依赖CLIP1介导的多聚化非催化功能。现有抑制剂仅针对激酶，无法消除其支架功能。研究利用深度学习模型预测三元复合物并结合基于结构的分子优化，开发了首类靶向降解CLIP1-LTK融合蛋白的PROTAC分子DCL05，实现癌细胞内靶蛋白的完全清除。","scd":null,"kp":[]},{"i":43735,"as":"一项针对359名低信任度男性的高功率预注册研究表明，催产素（OT）对信任行为具有因果效应。在完全匿名的信任博弈中，施用OT使信任行为显著增加了约15%。该结果在控制人格特征的回归模型中保持一致，结合此前的样本数据进行汇总分析，进一步证实了OT可显著提升低特质信任人群的信任度。","scd":null,"kp":[]},{"i":43736,"as":"果蝇中的保幼激素（JH）通过bHLH-PAS蛋白MET或其旁系同源物GCE与TAI结合形成转录活性的异二聚体受体（JHR）。研究阐明了JHR复合物激活的机制，证实GCE的PAS-A结构域在JHR信号传导中发挥关键作用，且PAS-A结构域中带有电荷的氨基酸残基在昆虫中具有高度保守性。","scd":null,"kp":[]},{"i":43737,"as":"鼠伤寒沙门氏菌（S Tm）引发的肠道炎症会在肠腔中导致柠檬酸盐的大量积累。柠檬酸盐在致病过程中发挥双重作用：作为厌氧发酵底物支持细菌生长，并作为信号激活其毒力。该机制使得S Tm能够利用宿主的炎症反应衍生物来促进自身的增殖和肠道定植。","scd":null,"kp":[]},{"i":43738,"as":"研究基于掺杂磁性颗粒的液晶弹性体（LCE）开发了微型机器人。磁性颗粒的光热效应与5CB增塑剂使机器人在陆地和水下均具有快速光热响应。在陆地环境中，光磁双场耦合策略提升了机器人的越障能力并实现全向跳跃；在水下环境中，机器人利用频率调节实现多模态移动，适应复杂环境。","scd":null,"kp":[]},{"i":43739,"as":"DNA跨损伤合成（TLS）是一条易错修复途径。研究发现，Y家族TLS聚合酶ι（Pol ι）在表达野生型和TLS聚合酶敲除（POLH、POLK、POLI）的人类TK6和RPE-1细胞系中发挥作用。全基因组测序结果表明，聚合酶ι在吸烟模型以及铂类化疗引起的SBS31突变特征中，直接促进了C>T的碱基替换。","scd":null,"kp":[]},{"i":43740,"as":"一种关于内隐偏见变化的理论指出，文化信息曝光度的变化决定了偏见的演变，且其变化速度因地理位置而异。基于14年间1400万美国居民内隐偏见测试数据的分析证实了其反直觉的预测：与较小的城市相比，内隐偏见在大城市中的变化速度更慢，且一次性的干预措施在大城市中的效果也较弱。","scd":null,"kp":[]},{"i":43741,"as":"研究人员利用小鼠荧光谱系追踪、单细胞转录组学和双链测序技术，确定了化学诱导性皮肤肿瘤的细胞起源。结果显示，这些肿瘤主要起源于位于毛囊上部的Lgr6+和/或Lrig1+干细胞，极少数源于Lgr5+和Krt19+的毛囊隆突细胞。其中，Lgr6+干细胞在二甲基苯并蒽（DMBA）引发下启动了肿瘤的形成。","scd":null,"kp":[]},{"i":43742,"as":"","scd":null,"kp":[]},{"i":43743,"as":"研究团队首次利用基因组语言模型成功实现了完整噬菌体基因组的生成式设计。以噬菌体ΦX174为模板，实验生成了具备特定宿主趋向性的存活噬菌体，共获得16种具有不同适应度特征的变体。冷冻电镜证实生成的噬菌体使用了进化上较远的DNA包装蛋白。此外，由生成噬菌体组成的鸡尾酒能够快速克服对ΦX174产生抗性的大肠杆菌。","scd":null,"kp":[]},{"i":43744,"as":"研究报道了一种在有机化学中直接从单官能团C(sp3)–X合成邻位双取代化合物的激活模式。该方法通过光氧化还原触发的氢原子转移（HAT）和自旋中心转移（SCS）过程，直接生成烯烃自由基阳离子中间体。计算表明，电子离域和氢键溶剂网络促进了协同的[HAT+SCS]机制。该催化平台实现了亲电反应性在不同碳原子之间的转移，允许使用两种亲核试剂构建1,2-双官能团化产物。","scd":null,"kp":[]},{"i":43745,"as":"研究利用大规模Neuropixels记录技术探究了自由行为大鼠的大脑导航回路。结果证实，网格细胞和位置细胞群体中的Theta节律扫描及方向信号能够被快速且动态地调制。这些扫描信号在追踪移动目标、静止时的定向反应以及向后移动时发生反转，且这种动态调整无需预先学习目标位置的空间信息。","scd":null,"kp":[]},{"i":43746,"as":"金黄色葡萄球菌的一种基于脂质的免疫逃逸机制被揭示。该细菌的油酸水合酶（OhyA）能够将宿主脂肪酸转化为羟基化脂质，这些脂质会拮抗由双链RNA激活的TLR3–TRIF–IRF7先天免疫信号通路。这种机制帮助金黄色葡萄球菌在细胞内持续存活，从而逃避宿主免疫防御和抗生素攻击。","scd":null,"kp":[]},{"i":43747,"as":"研究对比了小鼠皮肤 colonization，揭示了多重耐药真菌耳念珠菌（Candida auris）在皮肤上的持久存活机制。与白色念珠菌引发3/17型清除性免疫反应不同，耳念珠菌表现出更强的皮肤持久性、毛囊趋向性和直接毛发结合能力。耳念珠菌通过暴露几丁质，触发由1型干扰素-γ（IFNγ）驱动的针对毛囊的免疫反应，从而实现其在皮肤上的长期定植。","scd":null,"kp":[]},{"i":43748,"as":"研究探讨了2型糖尿病中胰岛淀粉样多肽（IAPP）聚集产生蛋白毒性的时间窗口。通过结合时间分辨的β细胞功能测定与生物物理学测量，对多种扰动和序列变体进行了22组独立实验。结果表明，迟滞时间跨度超过450倍，最大毒性发生在迟滞期，且随着纤维的积累而下降。β细胞功能障碍的持续时间与迟滞时间呈线性比例关系。","scd":null,"kp":[]},{"i":43749,"as":"本文使用p35-i3哈密顿量研究了位于镍-78和锡-100之间、拥有50个中子的同中子异位素的电磁性质。这些原子核为质子在0f5/2, 1p3/2, 1p1/2, 0g9/2模型空间内的核壳层模型提供了基准测试。","scd":null,"kp":[]},{"i":43750,"as":"研究测量了每核子6 MeV能量下的1H(11Li, 9Li)3H双中子转移反应，获得了向9Li基态以及2.69 MeV和4.30 MeV激发态跃迁的微分截面。实验首次观测到了向4.30 MeV (5/2-)激发态的跃迁，该研究有助于理解原子核结构与核子相互作用。","scd":null,"kp":[]},{"i":43751,"as":"研究引入了一种基于贝叶斯启发的模型平均框架，用于量化罕见同位素产生截面的预测不确定性。该框架将基于12个核质量表的磨蚀-剥落计算结合为一个统计加权预测。利用氪-78和氙-124的实验数据确定了计算可靠性，并将趋势转移至钼-92和钐-144弹核上。该方法提供了带有不确定性估计的预测截面，为初级束流选择和产额估计提供了更可靠的依据。","scd":null,"kp":[]},{"i":43752,"as":"研究探讨了在多核子转移反应中产生近100Sn的未知贫中子同位素。远离β稳定线的贫中子同位素的性质对于探索质子滴线位置和壳演化至关重要，而靠近双幻核100Sn附近的原子核为探索核结构性质提供了重要途径。","scd":null,"kp":[]},{"i":43753,"as":"天合光能旗下专注光伏建筑一体化（BIPV）的子公司天合绿建完成由吴江创投投资的天使+轮融资。天合绿建主营BIPV产品、光伏声屏障及储能技术等业务。近期，天合光能自主研发的3.1㎡钙钛矿/晶硅叠层组件峰值功率达907W，全面积效率达29.2%，刷新全球叠层组件功率世界纪录。公司已将钙钛矿/晶硅叠层电池技术引入场景光伏一体化方案，实现品牌战略从BIPV升级至场景光伏一体化。","scd":null,"kp":[]},{"i":43754,"as":"拉普拉斯拟定向增发募集资金总额不超过22.01亿元，重点加码TOPCon、XBC、钙钛矿等光伏及半导体高端装备研发。其中约12.5亿元投入光伏及半导体项目。资金将聚焦高效光伏电池制造核心工艺，开展热制程、镀膜、EPD及Poly层激光减薄等现有核心设备的迭代研发，并加大智能化投入，以进一步巩固其在光伏设备市场的竞争优势。","scd":null,"kp":[]},{"i":43755,"as":"浙江润海光能凭借P型异质结（HJT）技术的低成本、高可靠性和可量产优势，正推进太空光伏量产化。P型硅衬底的少数载流子对辐照缺陷敏感度低，结合本征非晶硅钝化层，具备优异的抗辐照性能。为满足太空应用对比功率的极致要求，团队攻关了50～70μm超薄硅片异质结制备工艺，优化了PECVD沉积应力匹配并开发了细栅电极新设计，有效攻克了薄片翘曲和碎片率高的量产痛点。","scd":null,"kp":[]},{"i":43756,"as":"晶科能源旗下核心控股子公司海宁晶科成功完成20亿元增资扩股，引入兴银、中邮、招银三家金融资产投资公司作为战略投资者。海宁晶科定位为N型高效光伏电池与组件研发制造平台，专注TOPCon技术路线并兼顾钙钛矿叠层前沿技术。公司作为晶科能源全球产能扩张与技术创新的核心载体，承担量产高效化、技术前沿化和制造智能化战略使命。","scd":null,"kp":[]},{"i":43757,"as":"2026年国际太空光伏与钙钛矿论坛将于8月6-7日在江苏无锡召开。当前商业航天爆发式增长正驱动柔性太阳翼需求。技术方面，平米级单结钙钛矿组件效率已超22%，叠层电池实验室效率突破35%。柔性钙钛矿/晶硅叠层电池效率达33.6%，全尺寸硅片达29.8%，经43000次弯折仍保留97%初始效率。2026年我国成功完成产业化柔性太阳翼在轨验证，翼展14m，初期功率超5000W，各项指标达国际领先。","scd":null,"kp":[]},{"i":43758,"as":"前专业厨师麦克·基恩参与“人类饮食计划”，进行了一项极端饮食实验。原计划在一个月内从格陵兰岛滑雪320千米，期间仅以一只逐渐腐烂的生海豹肉（包含发酵的眼球）为食，以探究发酵海豹肉的营养变化及对人体的生理影响。受格陵兰岛海冰加速融化影响，实验计划被迫临时更改，基恩将留在库洛尔苏阿克村进行后续实验。","scd":null,"kp":[]},{"i":43759,"as":"《自然》发表的针对约50万成年人的大规模分析揭示了睡眠延缓衰老的“甜蜜点”。通过检测20多种生物衰老“时钟”，发现每天睡眠6-8小时的人群过早死亡和疾病风险较低，多睡或少睡均与衰老加速相关。这一发现表明，睡眠时长与全身衰老之间存在U形曲线关系，改善睡眠时间或是降低衰老相关疾病的可行路径。","scd":null,"kp":[]},{"i":43760,"as":"澳大利亚能源市场委员会将推出能源零售套餐新规草案，旨在彻底简化家庭用户的选择流程。现行复杂的账单计费框架包含需求费、出口费和分时电价等繁多名目。新规要求AGL和Origin等电力零售商自行消化定价中的复杂成本，将其打包成简单明了的套餐，使消费者比价和选购电力套餐“像在超市买牛奶一样简单”。","scd":null,"kp":[]},{"i":43761,"as":"粤东海上风电001项目最新建设期定为2026至2028年。该项目位于广东揭阳海域，总投资约194.4亿元，装机总容量1700MW。最新方案拟安装122台14MW风机，配套建设3座500kV海上升压站，采用3回500kV送出海缆将电能输送至惠来县陆上集控中心。500kV高电压等级海底电缆为目前国内海风最高水平之一，可显著降低远距离输电损耗。项目目前处于建设前期准备阶段。","scd":null,"kp":[]},{"i":43762,"as":"本文系统研究了国家治理现代化与社会主义市场经济体制完善的协同路径。研究指出，有效市场与有为政府的有机结合是推动高质量发展的关键。当前在产权保护、要素市场化配置等方面成效显著，但仍面临市场准入壁垒、新兴领域监管滞后等挑战。未来需通过完善产权制度、构建全国统一大市场、推动科技金融融合及加强数字化治理等举措，促进两者协同发展，保障中国式现代化。","scd":null,"kp":[]},{"i":43763,"as":"美国对华技术出口管制正从零散限制向体系化、长期结构性限制演变，其核心目的是延缓技术扩散速度以保持自身领先。该管制体系由核心设备、软件、人才与流动三层架构组成。半导体是核心战场，2022年10月美国实施新规，对14纳米以下制程设备以及英伟达、AMD等公司的高端AI训练GPU（如A100/H100）实施严格的出口许可要求，全面放慢中企技术迭代速度。","scd":null,"kp":[]},{"i":43764,"as":"2025年7月，美国政府发布《赢得竞赛：美国AI行动计划》，标志着其AI政策重心从“风险治理”转向“竞争优先”与去监管。该计划旨在争夺全球技术主导权，给全球AI治理格局带来冲击。面对此转向带来的竞争压力，我国应在顶层设计、基础设施、创新生态、治理机制和国际合作五个核心方面发力完善AI战略，以提升自身的产业竞争力与应对能力。","scd":null,"kp":[]},{"i":43765,"as":"美国空军部提出加速数字化转型必需的五类共同要素：领导力与采纳文化、资金与激励机制、软件与数据标准、硬件与安全信息技术，以及度量指标。研究指出，数字化转型的阻力往往并非技术能力不足，而是组织抵制变革、资源投入有限及知识产权保护等“人”的因素。领导者需通过提出愿景及运用结构化的变革管理策略，营造拥抱数字化方法的企业环境。","scd":null,"kp":[]},{"i":43766,"as":"报告指出美军对自主武器系统的传统定义仅聚焦无人机等硬件平台，已严重滞后。报告提出自主武器是一套包含目标分配与决策智能软件的完整体系，并据此将自主作战划分为平台层与编排层。结合俄乌实战经验，报告剖析了美军无人系统建设的结构性短板，强调自主作战软件在实战中的核心调度价值，并提出五项落地原则与机构实施方案以完善体系建设。","scd":null,"kp":[]},{"i":43767,"as":"俄乌冲突中，无人地面车辆（UGV）的应用正在改写战场规则。乌军大规模部署UGV执行高危险后勤补给任务，运送弹药和医疗物资，据研究证实此举使乌军伤亡人数减少了30%。乌军还成立了全球首个负责相关领域的独立军事部门。美军正派员赴乌研究其整合无人平台进行攻防作战的前沿战术。UGV的实战应用有效维持了战略阵地并大幅降低人员风险。","scd":null,"kp":[]},{"i":43768,"as":"2025年全球防空反导火力装备正面临高超声速目标与低成本无人机集群的严峻突防挑战。美国、俄罗斯、欧洲和以色列等重点国家正加速传统装备改进、新质装备研发与前沿技术探索。防空反导系统呈现出多域融合、智能化和高端化演进趋势，以应对现代战争中“高速对抗”与“成本制胜”的现实需求。发展集群防御与智能化拦截成为全球空天防御的核心方向。","scd":null,"kp":[]},{"i":43769,"as":"美军提出“精确规模化”概念，认为未来战争胜负取决于承受损失、快速补充并大规模扩量的能力。传统依赖少量昂贵精锐平台的“以质换量”策略正面临失效。由软件和自主性赋能的低成本、可损耗系统正在重塑战斗力生成模式。例如单机成本约3.5万美元的LUCAS无人机，正为美军提供低成本、可快速扩充的作战能力，技术正成为加速规模化生产的催化剂。","scd":null,"kp":[]},{"i":43770,"as":"研究探讨了CeO₂–BaO复合氧化物作为PCFC/SOFC电池Ni基阳极抗积碳重整层的潜力。CeO₂提供储放氧与甲烷活化能力，BaO提供碱性调控与抑碳作用。实验制备了三种配比的样品，1050℃烧结后的XRD结果显示各组样品均保留了CeO₂和BaO两相立方结构，未形成单一固溶相，并伴有BaCO₃副相产生。该复合层为碳氢燃料电池的抗积碳工程提供了新思路。","scd":null,"kp":[]},{"i":43771,"as":"对AI企业Anthropic 1680名工程师的履历分析显示，该公司在18个月内实现了工程团队的极速扩张。其真正渴求并大规模雇佣的并非理论研究员，而是具备大规模生产系统落地能力的“构建者”和基础设施工程师。数据显示其工程团队半数人员任职不足一年，扩张速度极快。这表明头部AI公司在产业化落地阶段，极其看重基础设施建设与工程实战经验。","scd":null,"kp":[]},{"i":43772,"as":"谷歌云AI总监Addy Osmani提出“循环工程”概念，认为这将取代提示词成为与AI编程智能体协作的主流方式。循环工程是指设计一套递归式系统，设定意图后由AI自动循环迭代指令直至任务完成。该模式包含五个核心组件，Claude Code等工具已具备相应能力。不过，该模式目前面临Token预算成本与生成代码质量保证的双重挑战。","scd":null,"kp":[]},{"i":43773,"as":"复旦与腾讯提出Baton框架，首创语义蓝图指引机制，解决复杂音视频生成中的音画不同步与逻辑错位问题。现有模型多采用全局语义向量，难以处理复杂多阶段的时序对应关系。Baton通过引入语义蓝图，能够精确拆解并指导多角色交互、时序动作与声音的对应关系，实现对长程复杂场景“谁在发生”、“何时发生”的精准逻辑同步，大幅提升生成质量。","scd":null,"kp":[]},{"i":43774,"as":"得益于新能源汽车普及，中国石油消费达峰加快。5月份新能源乘用车批发渗透率首次突破60%达61.1%，零售渗透率达62.9%创历史新高；燃油车零售占比降至37.1%。电动化替代超预期加速了燃油车边缘化，同时导致汽柴油销量及原油进口量出现下滑趋势。高油价与产品迭代共同推动了乘用车市场重心的根本性转移。","scd":null,"kp":[]},{"i":43775,"as":"面对电力短缺，全球多国正积极推进核电站延寿计划。英国拟投资8亿英镑将塞兹韦尔B核电站寿命延长至2055年；美国90余座运行核电站中80余座获批延寿至60年，部分正审查延至80年。科技巨头如亚马逊与Meta甚至签署长期核电购电协议以支撑核电站更新执照。核电正从“退役”转向“续命”，成为保障能源安全的重要基荷电源。","scd":null,"kp":[]},{"i":43776,"as":"加州大学圣地亚哥分校与谷歌合作，将废弃老旧Pixel手机回收改造成低成本数据中心。测试显示，25至50台旧手机算力相当于一台双路服务器级CPU，改造成本仅为传统方案零头。此外，中国11部门联合发文推动新能源重卡应用，明确到2030年新能源重卡保有量突破160万辆，占总量20%，并配套建设约3000个充换电站和3万公里零碳运输通道。","scd":null,"kp":[]},{"i":43777,"as":"国家发改委等五部门发文开展重点行业节能降碳改造攻坚行动。2026年起将利用3年时间，对钢铁、电解铝、水泥、炼油等9大高耗能行业进行全面改造。目标是到2028年底，重点行业能效标杆水平产能比例提高20个百分点，煤电提高15个百分点，低效产能基本清零，实现节能量超1亿吨标准煤，减排二氧化碳2亿吨以上。","scd":null,"kp":[]},{"i":43778,"as":"锂电负极材料龙头企业中科电气宣布终止甘眉、兰州新区及摩洛哥三大投资项目，原计划投资总额约103亿元。官方公告称项目实施条件发生客观变化，仅进行了前期筹备。中科电气决定集中资源推进泸州及阿曼的一体化项目。此次大规模投资终止是企业顺应行业周期、降低投资风险并主动优化产能与资源配置的理性经营决策。","scd":null,"kp":[]},{"i":43779,"as":"高温质子交换膜燃料电池(HT-PEMFC)运行温度为150-200°C，但其核心膜电极中的磷酸会强烈覆盖铂(Pt)催化剂表面，抑制氧还原反应(ORR)。研究对比1M磷酸与高氯酸环境发现，磷酸导致催化剂可用电化学表面积下降20-40%，ORR比活性衰减十倍。主导因素是磷酸吸附物的覆盖度。仅靠合金化或调整碳载体无法消除该惩罚，设计需兼顾催化剂表面与酸性离子环境。","scd":null,"kp":[]},{"i":43780,"as":"中核集团宣布我国科学家首次成功实现丰度超99.99%的硅-28同位素自主量产，打破国外垄断。天然硅中的硅-29具有核自旋会干扰量子相干性，高纯硅-28是硅基量子芯片不可或缺的核心底层材料。此次自主量产补齐了万亿级量子产业链的最底层基石，解决了核心材料受限问题，标志着我国在硅基半导体量子计算材料制备领域达到国际先进水平。","scd":null,"kp":[]},{"i":43781,"as":"谷歌拒绝参与美国政府20亿美元的量子计算资金计划，原因是政府附加的严苛审计、合规审查与里程碑考核条件阻碍了研发速度。谷歌强调其研发模式高度敏捷，而政府考核节点与僵化的指标体系不匹配其快速迭代、甚至推翻重来的实验需求。当前量子计算正处于技术跨越关键期，政府资助附加的“速度限制”成为谷歌放弃巨额资金的核心原因。","scd":null,"kp":[]},{"i":43782,"as":"苏黎世联邦理工学院团队在《Nature Materials》发表研究，成功利用名为NPCbot的磁控细胞机器人修复小鼠受损脊髓。该微型机器人由包裹着磁电纳米粒子（钴铁氧体核心与钛酸钡外壳）的神经祖细胞构成，可通过磁场引导精准移动至深层损伤区域。实验表明，脊髓完全横断的小鼠在接受NPCbot治疗约4周后，恢复明显的后肢步进运动功能。该技术解决了传统细胞移植面临的滞留不足、存活率低及分化不可控等问题。","scd":null,"kp":[]},{"i":43783,"as":"《中华人民共和国矿产资源法实施条例》单独设立矿山生态修复专属篇章，明确了矿区“边开采、边修复”和“分区开采、分期修复”的实操路径，并以法定形式固化矿山企业的复垦主体责任。同时，《条例》细化了矿业用地取得方式，有效解决了长期制约矿山生态修复落地的“矿合法、地不合法”用地瓶颈，构建起开发与修复并行的法治化管理体系。","scd":null,"kp":[]},{"i":43784,"as":"碳酸锂期货结束近一个月的下跌行情，主力合约LC2609周内累计上涨8.22%，站稳17万元/吨关口。本轮反弹的核心驱动力来自需求侧的结构性变化：2026年全球储能需求预计高速增长，电芯产能趋于饱和；新能源汽车销量回暖，带动磷酸铁锂排产环比增长。此外，AI数据中心的高能耗也催生了对配套储能及高品质碳酸锂的新需求。","scd":null,"kp":[]},{"i":43785,"as":"西班牙一项基于5年小时级电力市场数据的研究指出，在新能源高比例并网系统中，大量风光电量通过实物PPA（长期双边合约）锁定并退出日前市场定价后，反而会抬升现货电价。这一现象打破了“新能源增加必然压低电价”的传统优序效应认知。研究证实，当低成本绿电不直接参与市场出清时，最终电价仍由供需关系、燃料成本及市场结构等综合因素决定。","scd":null,"kp":[]},{"i":43786,"as":"过去五年，OpenAI和Anthropic在未上市状态下，通过多轮内部售股为员工和投资者套现约140亿美元。其中，OpenAI在过去五年组织了至少8轮售股，总额超90亿美元，单次最高套现造就约75名员工人均入账2亿元人民币。这种售股机制主要为了应对美国股权税制中股票归属即需按市价交税的压力，帮助员工解决高昂的税单问题。","scd":null,"kp":[]},{"i":43787,"as":"美国政府以国家安全和“越狱”为由，对Anthropic最强AI模型Claude Fable 5和Mythos 5实施全球禁用的出口管制。这是历史上首次直接针对AI模型本身的出口管制，而非硬件芯片。由于Anthropic声称其他主流模型也存在类似越狱风险，此次禁令波及竞争对手OpenAI，并导致GPT-5.6的发布计划被迫延迟。","scd":null,"kp":[]},{"i":43788,"as":"第十一届全国储能科学与技术大会暨2026年碳未来论坛定于2026年8月5日至8日在鄂尔多斯市召开。大会主题为“风光无限背景下的储能新机遇”，设置特邀报告、青年科学家论坛及产学研交流闭门会等环节。会议议题全面覆盖先进锂离子电池、固态电池、物理储能（压缩空气、飞轮等）、燃料电池与氢能、AI与储能、碳材料等多个前沿科技领域。","scd":null,"kp":[]},{"i":43789,"as":"锂离子电容器兼具高能量与高功率密度，但负极在循环中因形成SEI膜和不可逆嵌锂会造成大量活性锂损耗。预锂化是补偿锂损失的关键技术，但深度预锂化会引发“不可逆锂”生成与SEI加速失效。当前直接接触、电化学、化学及正极预锂化四种技术路径在解决“高补锂量与界面稳定性”矛盾时均存在固有局限，未来需从热力学源头规避及层级界面设计寻求突破。","scd":null,"kp":[]},{"i":43790,"as":"武汉理工大学麦立强团队提出一种多金属离子（Ni、Cu、Ti）轨道工程策略，以解决磷酸锰铁锂（LMFP）正极材料存在的导电性差和姜-泰勒畸变严重问题。通过强化异质原子与宿主晶格间的轨道杂化，窄化带隙，有效抑制了Mn³⁺的轨道简并。优化后的材料本征电导率与离子扩散系数提升一个数量级，锰溶解减少48.4%，半电池1C循环1000圈容量保持率达92.3%。","scd":null,"kp":[]},{"i":43791,"as":"北京大学夏定国与武汉纺织大学李惠团队提出通过表面重构调控阴离子氧化还原轨道，提升富锂锰基层状氧化物正极的循环稳定性。通过在表面重构层的特定位点引入镍离子，诱导缺电子O 2p轨道平行排列，抑制了不稳定的O-O二聚体形成和氧气释放。该工程化正极实现了325 mAh g⁻¹的高可逆容量，并在1C下300次循环后保持90%的容量。","scd":null,"kp":[]},{"i":43792,"as":"近期全球核聚变行业发生多项重大融资事件。美国核聚变公司Helion Energy完成4.65亿美元G轮融资，投后估值达155亿美元，累计融资超15亿美元，OpenAI创始人Sam Altman持有约三分之一股权。中国核聚变企业星能玄光完成5亿元A系列融资，由金浦投资、蚂蚁集团等领投。这标志着商业核聚变领域正持续获得重磅资本支持。","scd":null,"kp":[]},{"i":43793,"as":"腾讯Robotics X等联合发布开源端到端具身智能模型HyVLA-0.5。该模型基于自研亚毫米级高精度指套式UMI数据采集软硬件，构建超10000小时人类示教数据，使监督训练完全摆脱了繁重的遥操作数据需求。模型在RoboTwin 2.0仿真基准中成功率超90%，并系统性引入流匹配VLA强化后训练，利用失败数据将真实机器人任务成功率提升至接近100%。","scd":null,"kp":[]},{"i":43794,"as":"摩尔线程发布并开源了面向GPU底层算子生成的专用大模型MusaCoder-27B-RL。在AI生成GPU内核的硬核基准KernelBench上，该模型超越Claude Opus等国内外大模型取得第一。MusaCoder能自动将PyTorch代码转换为CUDA与MUSA内核，成为业内首个完全基于国产GPU算力底座完成全链路训练与验证的开源代码大模型。","scd":null,"kp":[]},{"i":43795,"as":"研究者首次提出“知识密集型视频生成”（KIVI）任务，要求模型生成事实准确且具实用指导价值的视频。研究团队构建了包含1080条提示词的KIVI-Bench评测集，并在7款主流视频生成模型上进行测试。评估揭示了当前模型在处理知识场景时普遍存在实体误描、操作错误、组件错位三类系统性短板，指明了视频生成在专业领域应用中的技术差距。","scd":null,"kp":[]},{"i":43796,"as":"6月12日，华能金坛2×350兆瓦盐穴压缩空气储能发电二期项目透平机冲转定速一次成功。机组转速平稳升至3000转/分并持续稳定运行17分钟，全程工况平稳可控。作为发电机组核心设备，透平机顺利完成冲转定速标志着该项目安装调试的关键节点顺利达成，为后续机组的正式并网投运奠定了坚实基础。","scd":null,"kp":[]},{"i":43797,"as":"深能锡林郭勒西乌珠穆沁旗电网侧压缩空气储能项目地面电站工程EPC总承包结果公布，中国能源建设集团江苏省电力建设第一工程有限公司中标，中标金额约为42.93亿元人民币。该项目标志着我国在电网侧大容量压缩空气储能长时储能领域的工程化建设又迈出实质性一步。","scd":null,"kp":[]},{"i":43798,"as":"国家发改委等五部门联合发布《关于开展重点行业节能降碳改造攻坚三年行动的通知》。文件明确以钢铁、煤电等9个行业为重点，利用3年时间全面实施节能降碳改造。在煤电领域，文件具体要求推动300MW（30万千瓦）以上现役煤电机组实施节能降碳改造，并明确提出推动煤电加装储能，实现煤电与新能源的融合发展。","scd":null,"kp":[]},{"i":43799,"as":"西安热工研究院科研项目高温相变储热一体化装备设备招标公示中标候选人，山东豪迈机械制造有限公司以165万元预中标。该装备要求总有效储热容量不低于1MWh，总充放热功率均不低于1MW，储热效率不低于95%。设备将用于华能海口电厂模块化相变蓄热装置耦合工业管网辅助燃煤机组综合调频技术的工程示范。","scd":null,"kp":[]},{"i":43800,"as":"在AI & Society Forum 2026论坛上，业内专家指出，尽管AI在加速靶点发现和药物研发方面展现出潜力，但AI在医疗实际应用中仍处极早期阶段。原因在于：大模型难以处理真实问诊中千差万别的不确定性输入；且AI无法作为责任主体为无法回滚的医疗决策后果负责。目前的AI是加速药物研发的超级工具，但依然无法替代人类医生进行干预和最终决策。","scd":null,"kp":[]},{"i":43801,"as":"腾讯研究院与腾讯新闻较真平台联合发起一项关于青少年信息素养的研究，旨在探讨生成式AI普及背景下，青少年对网络真假信息的辨别能力与短板。研究团队公开招募青少年、家长及教育从业者进行深度访谈，重点了解这一代青少年在复杂信息环境中的判断逻辑，所有访谈内容将仅用于学术研究。","scd":null,"kp":[]},{"i":43802,"as":"国家发展改革委等部门联合印发《关于开展重点行业节能降碳改造攻坚三年行动的通知》。《通知》明确了到2028年底的主要目标，聚焦钢铁、电解铝、水泥、平板玻璃、炼油、乙烯、合成氨、甲醇、煤电9个重点行业部署具体改造任务，并通过资金支持、价格引导等政策保障实施，以支撑碳达峰目标，推进行业绿色低碳发展。","scd":null,"kp":[]},{"i":43803,"as":"专家解读《重点行业节能降碳改造攻坚三年行动计划》，指出计划聚焦炼油、乙烯、合成氨、甲醇等9个重点行业，利用3年时间全面实施改造。2025年上述4个石化化工行业能耗与碳排放分别占行业总量的42%和53%，节能潜力大。核心改造方向包括核心装置先进控制、蒸汽系统优化、高效催化剂应用、电气化升级及绿氢耦合等，并配套推进先进装备研发。","scd":null,"kp":[]},{"i":43804,"as":"上海市发布全国首个地方“碳排放双控”考核通知，启动2025年度重点单位碳排放总量和强度双控目标评价考核，并下达2026年考核目标。2025年上海市综合能耗5000吨标准煤及以上重点用能单位共930家，另外有11家直接温室气体排放超13000吨二氧化碳当量的单位纳入管理，要求各单位报送能源利用状况与温室气体排放报告。","scd":null,"kp":[]},{"i":43805,"as":"联泓新科旗下联泓格润的全球首套5万吨级二氧化碳基生物可降解聚碳酸亚丙酯（PPC）装置成功投产。该装置以二氧化碳和环氧丙烷为原料，采用与中国科学院长春应用化学研究所联合开发的第四代多核锌系催化剂及超临界聚合工业化技术。项目历时四年完成从小试到万吨级的放大，克服了催化剂效率、高黏度物料输送等工程化难题，正式进入量产阶段。","scd":null,"kp":[]},{"i":43806,"as":"蚂蚁集团正测试近二十年来最彻底改版的AI版支付宝，内部代号“宝计划”。新版本采用以对话驱动的全新交互模式，用户可一键切换进入，上线后默认仍保持原版，产品计划每月迭代两次。该项目由支付宝事业群总裁李俊挂帅，定位为蚂蚁最高保密级项目。相比于微信在应用内嵌入助手，支付宝的AI化改造路线更为激进，旨在重塑超10亿用户的App体验。","scd":null,"kp":[]},{"i":43807,"as":"国家发改委等部门印发通知，加快钢铁、电解铝、水泥等重点行业热泵等设备更新升级。钢铁行业重点推动高炉等装置改造及氢冶金应用，加快淘汰1200立方米以下高炉等落后设备；电解铝行业推广500kA及以上大型电解槽等先进技术，淘汰300kA以下预焙阳极铝电解槽；水泥行业重点开展六级预热器及窑炉富氧燃烧改造，淘汰60万吨/年以下水泥粉磨站。","scd":null,"kp":[]},{"i":43808,"as":"SK海力士作为AI时代的核心存储供应商，面临HBM暴利、领先者困境和单一市场依赖的结构性挑战。尽管高带宽内存（HBM）需求爆发带来了巨大收益，但这也迫使其必须保持极高的技术与资本投入。为了维持市场地位，SK海力士必须在极短的周期内迭代技术路线图，同时承受产能扩张、客户议价权转移及地缘供应链重塑带来的巨大压力。","scd":null,"kp":[]},{"i":43809,"as":"","scd":null,"kp":[]},{"i":43810,"as":"在2026年欧洲电池展上，卫蓝新能源发布410Wh/kg和480Wh/kg两款半固态电芯。其中410Wh/kg型号采用硅碳负极，计划第三季度量产；480Wh/kg旗舰产品支持5C放电，已完成开发。巴斯夫则推出面向硫化物体系固态电池的专用聚异丁烯（PIB）粘结剂Oppanol N PLUS，应用于固态电池的电极与电解质制造中。","scd":null,"kp":[]},{"i":43811,"as":"电动飞机开发商Helios Horizon完成首次搭载全固态电池的载人试飞，验证了机体重量分布和系统运行。测试机最大起飞重量600公斤，最高飞行速度96公里/小时。采用自研集成电池包，使用商业化410Wh/kg电芯，容量约14.8kWh。目前全固态电池造价约为锂聚合物电池的3-4倍，公司计划未来开展更高空测试，并预计2至3年内推进商业认证。","scd":null,"kp":[]},{"i":43812,"as":"《求是》杂志发表习近平总书记重要文章《一体推进教育科技人才发展》。文章强调教育、科技、人才是全面建设社会主义现代化国家的基础支撑。要求坚持教育优先发展、科技自立自强、人才引领驱动，统筹推进三者体制机制一体改革。强化高水平研究型大学在基础研究中的作用，优化国家科研机构与科技领军企业布局，构建支持全面创新体制机制。","scd":null,"kp":[]},{"i":43813,"as":"通用汽车与Peak Energy合作开发电网储能用钠离子电池；宁德时代EnerD+系列获全国锂电池首张国家级碳足迹标识认证证书；全球首套百吨级光电催化合成氨工业示范项目在陕西榆林成功中试，突破传统哈伯法工艺高碳排瓶颈；孟加拉国宣布锂电池、储能系统进口关税降至0%。此外，ISO发布了金融机构净零转型规划标准。","scd":null,"kp":[]},{"i":43814,"as":"国家能源局印发通知组织开展地热能高质量开发利用试点工作。试点目标是在“十五五”期间建成技术先进、管理规范的规模化地热能项目，重点聚焦中深层地热能规模化利用，提升城市供热比例，优先替代天然气供暖，探索长距离输热商业模式；推广“取热不取水”井下换热技术，验证不同地质条件下的适配性，并以此形成可复制的典型路线与运营模式。","scd":null,"kp":[]},{"i":43815,"as":"欧盟“地平线欧洲”启动海水直接电解制氢项目SWEETHY，获约400万欧元资助。该项目基于阴离子交换膜水电解槽技术，使用天然海水运行并耦合可再生能源。计划在意大利墨西拿使用地中海海水开展2000小时验证，实现约20克氢/小时的产氢量，性能衰减率控制在1%/100h以下。项目还将开展技术经济分析及副产物综合利用研究。","scd":null,"kp":[]},{"i":43816,"as":"水电水利规划设计总院报告显示，截至2025年底，中国可再生能源制氢累计建成产能达25万吨/年，同比增长50%。2025年碱性电解槽系统造价降至1000元/kW，同比下降16.7%；PEM电解槽造价降至4500元/kW，同比下降25%。在电价降至0.13元/kWh的优势场景下，绿氢生产成本有望下降至14元/千克。","scd":null,"kp":[]},{"i":43817,"as":"芬兰瓦锡兰集团在西班牙完成全球首个100%纯氢发动机电网级验证。核心设备瓦锡雅31H2发动机稳定向西班牙国家电网供电，证明大规模氢燃料发电可替代化石能源提供零碳可调度电力。该发动机隶属全球最高效的多燃料四冲程发动机平台之一，利用绿氢在可再生能源低谷期调峰。项目仍处于验证阶段，具体效率与长期稳定性数据尚未公开。","scd":null,"kp":[]},{"i":43818,"as":"纤纳光电持有316件专利申请，技术布局高度集中于半导体器件（H01L）与有机半导体器件（H10K）领域，核心研发双核为颜步一与姚冀众。专利支撑涵盖薄膜沉积、涂布技术及光伏系统应用。企业通过大规模发明人匿名化策略保护核心工艺人员，技术路线涵盖多维钙钛矿材料与新型器件结构，正从实验室逐步向大型光伏电站、BIPV等场景落地。","scd":null,"kp":[]},{"i":43819,"as":"研究人员利用视觉语言模型（VLM）训练协作型机器人识别面部表情及互动场景中的人类情绪。40名志愿者参与的实验结果表明，具备情绪感知能力的机器人在人机互动中能调整自身行为，但整体情绪识别能力仍存在明显局限。该研究证实，除提升机器人的肢体运动性能外，结合环境信息的情绪感知是优化人机协同工作的重要方向。","scd":null,"kp":[]},{"i":43820,"as":"第26届IEEE纳米技术国际会议（IEEE NANO 2026）定于7月5日至8日在中国南京举行。大会邀请了来自普林斯顿大学、香港中文大学、多伦多大学等高校的学者作为主讲嘉宾。会议涵盖了纳米技术领域的多项前沿研究，目前会议注册与酒店预定通道已面向全球学者与行业专家开启。","scd":null,"kp":[]},{"i":43821,"as":"受美国政府指令影响，Anthropic暂停向所有外籍人员开放其最新发布的Fable 5与Mythos 5人工智能模型。此前，Anthropic刚与印度IT服务商TCS达成企业级AI推广合作。印度作为前沿AI企业仅次于美国的第二大市场，此次事件引发其国内对长期依赖美国大模型技术风险的激烈讨论，焦点在于是否应加快打造本土AI技术。","scd":null,"kp":[]},{"i":43822,"as":"AI企业Anthropic向用户发送隐私政策更新邮件，宣布自7月8日起，出于加强安全的原因，可能要求用户进行实名身份和年龄验证。隐私政策更新明确，随着Claude具备多步骤任务执行能力并可接入Google Drive等第三方应用，用户数据、对话内容、操作指令及上传文件将能够在Anthropic服务器与第三方应用之间流动处理。","scd":null,"kp":[]},{"i":43823,"as":"Anthropic发布最强旗舰模型Fable 5，仅上线四天即被全球下线，成为AI史上最短命旗舰。其最大投资方亚马逊发现该模型存在安全防护可被绕过的风险并上报白宫。因Anthropic CEO拒绝修漏洞或下架，美国商务部下达出口管制令强制其下线。图灵奖得主Yann LeCun指出这是Anthropic过度强调AI安全反遭管制的自食其果。","scd":null,"kp":[]},{"i":43824,"as":"北京大学Narwhal-Lab开源了Narwhal AI Code Risks项目，以解决AI生成代码难以察觉的安全隐患问题。该项目系统整理了AI生成代码的真实事件、早期信号和典型风险路径。AI生成的代码即便语法正确且通过测试，依然存在引入虚假包名、开放过宽权限、暴露数据库及引发数据泄露等致命风险。该项目旨在帮助开发者提前识别并避免此类风险。","scd":null,"kp":[]},{"i":43825,"as":"江苏赛瑞克新材料CEO郭能博士指出，明星生物基单体FDCA下游需求明确，已广泛应用于啤酒瓶、香水包装及锂电池隔膜涂覆等领域，市场规模达数万亿。当前行业面临的真正瓶颈并非市场销售，而是缺乏在大化工逻辑下实现规模化、低成本制造的能力。解决FDCA的高效量产是推动其大规模商业化的核心关键。","scd":null,"kp":[]},{"i":43826,"as":"中科院长春应化所明军团队设计了一种兼具本征阻燃和高压宽温特性的新型氟代酯电解液（TMF-LBF）。该电解液以乙酸甲酯为主溶剂，双(2,2,2-三氟乙基)碳酸酯与氟代碳酸乙烯酯为共溶剂，并采用双锂盐协同。该设计通过调控溶剂分子间相互作用，解决了锂金属电池在高电压（>4.3V）和宽温域下的枝晶生长与热失控问题，在4.5V高压下表现出优异的电化学性能。","scd":null,"kp":[]},{"i":43827,"as":"大湾区大学钱坤等研究团队提出全新电解液设计描述符——离子协同极化指数（SPI），打破了低温水系锌离子电池设计中“构型熵越高低温性能越好”的传统认知。SPI指标通过平衡阳离子扰动与阴离子极化能力，实现了对溶剂化结构与相变行为的精准调控。基于此理论开发的高SPI电解液在-136.67℃下仍保持非晶态，并在-60℃实现2.4 mS cm⁻¹的高离子电导率。","scd":null,"kp":[]},{"i":43828,"as":"安徽工业大学与复旦大学联合提出基于双氢键相互作用的电解液设计策略，解决了醚类电解液氧化稳定性差的问题。通过在传统醚类电解液中添加微量LiBH4，构筑了双氢键电解液（DHBE）。该策略有效屏蔽了溶剂分子的活性氢位点，将醚类电解液的氧化稳定性提升至5.54V，同时保持超过16 mS cm⁻¹的高室温离子电导率。基于该电解液的Li-NCM811电池在400次循环后容量保持率达87%。","scd":null,"kp":[]},{"i":43829,"as":"北京化工大学联合青岛黑猫新材料研究院，通过分子工程策略开发出一种高性能树脂衍生无定形碳钠离子电池负极材料。该工作将软碳纳米核引入酚醛树脂前驱体中，成功构筑了连通可及孔道、扩展层间距及延长碳纳米片的结构。这种协同优化突破了高倍率下平台容量衰减的瓶颈，有效降低了Na+低电位迁移能垒，为硬碳和软碳复合材料的储钠性能提升提供了新方案。","scd":null,"kp":[]},{"i":43830,"as":"中国科学技术大学章根强团队提出“相工程+位点选择性取代”策略，成功设计出新型高熵层状氧化物钠离子电池正极材料（P2/O3-Na8M）。该材料构建了P2/O3双相异质结构，引入Na位Zn取代及过渡金属层Cu/Mg协同调控。Zn2+发挥支柱效应抑制不可逆相变，Cu增强TM-O共价键，Mg减弱Jahn-Teller畸变。该正极在1.8-4.4V宽电压窗口下实现150 mAh g⁻¹的高容量，显著提升了空气稳定性和循环寿命。","scd":null,"kp":[]},{"i":43831,"as":"北京理工大学骆相宜团队提出一种主动界面溶剂化架构，解决了水系锌离子电池负极枝晶生长和析氢腐蚀等问题。研究将β-环糊精限域于聚多巴胺框架中，在锌表面构筑了Zn@PDA-β-CD复合界面。该界面能协同调控氢键网络、降低水活性并促进Zn²⁺均匀沉积。测试表明，该复合锌负极在对称电池中实现了超过5000小时的稳定循环，在Zn//Cu电池中平均库仑效率高达99.67%。","scd":null,"kp":[]},{"i":43832,"as":"研究系统阐述了应用场景在低空经济发展中的核心驱动作用。应用场景不仅是低空技术（如无人机、eVTOL）产业化落地的空间载体，更是连接技术迭代、市场需求、产业生态和制度创新的关键转化机制。研究建议将场景培育置于低空经济政策的核心位置，构建分级分类的场景体系，并完善配套基础设施、数字平台与市场化运营机制，以推动低空经济高质量协同发展。","scd":null,"kp":[]},{"i":43833,"as":"国际可再生能源署（IRENA）总干事弗朗西斯科·拉·卡梅拉在水规总院《中国可再生能源发展报告2025年度》发布会上发表视频致辞。他指出，2025年全球新增可再生能源装机692吉瓦，创历史新高，中国在其中占比超60%，在新增装机、电动汽车、储能部署和电网投资方面发挥了全球引领作用。IRENA正与水规总院深化联合研究，将中国经验推广至全球能源转型。","scd":null,"kp":[]},{"i":43834,"as":"针对编程Agent评测中SWE-bench无法横向比较的问题，基元律动联合清华、北大等机构开源了首个独立测量harness的基准。当前评测结果混淆了底层大模型能力、harness设计与任务集三个变量，同一模型更换harness分数差异可达二十个百分点。该开源基准旨在剥离模型能力与工程包装，客观测量并对比通用Agent在软件工程任务中的真实代码调用能力。","scd":null,"kp":[]},{"i":43835,"as":"Anthropic研究员Vivek Nair分享了关于如何成为优秀AI研究者的见解。他指出，真正的研究能力源于选题、文献阅读、写作和加速实验循环等一系列可刻意训练的基础技能，而非盲目追逐热点。研究者应主动寻找并聚焦于领域内的核心重要问题，摆脱单纯模仿研究表象的习惯，通过扎实的方法论训练提升实质性的科研创新能力。","scd":null,"kp":[]},{"i":43836,"as":"《Nature Sustainability》研究指出，退役动力电池回收的效率不仅取决于工艺，更取决于空间布局。研究预测2020-2030年中国退役动力电池总量将达16.67-19.99百万吨，且热点分布随时间和区域动态迁移。为提高低碳回收效率，必须基于退役电池的空间流向、城市电网排放因子及化学体系，优化正规回收产能的选址与布局，而非仅局限于回收技术本身的升级。","scd":null,"kp":[]},{"i":43837,"as":"研究通过引入氧官能化ketjenblack作为电子桥，强化了铜酞菁分子与碳基底电极之间的共轭耦合（CuPc-OKB），成功解决了异相分子催化中界面电子传输不畅的难题。该策略有效促进了*ketyl中间体形成并推动其对苯甲醛的亲核进攻，实现C-C偶联。CuPc-OKB体系生成hydrobenzoin的速率达0.62 mmol h⁻¹ cm⁻²，并在硝基苯偶联等多电子电还原反应中展现出优异的底物立体选择性和广泛的普适性。","scd":null,"kp":[]},{"i":43838,"as":"研究对现有的台风风暴潮大气波浪边界层模型进行了重大改进，全面引入了波浪破碎对能量消散及大气边界层动量传递的物理机制。升级后的模型计算出的风应力系数在深水与浅水海域均与实测数据高度吻合。将此模型与海洋波动和环流模型动态耦合后，大幅提升了对珠江口海域台风风暴潮和风浪的模拟精度，为沿海灾害预警系统提供了更准确的核心技术支撑。","scd":null,"kp":[]},{"i":43839,"as":"华能金坛盐穴压缩空气储能项目透平机组顺利完成冲转定速作业，机组转速平稳升至3000转/分并稳定运行17分钟，实现一次冲转成功。这标志着该核心发电设备的安装与调试质量达到严苛标准，顺利通过了工况平稳可控的全面检验。此关键节点的达成，为整个盐穴压缩空气储能项目的后续并网投运及高质量投产奠定了坚实基础。","scd":null,"kp":[]},{"i":43840,"as":"“能储一号”山东泰安350MW压缩空气储能创新示范项目倒送电试验一次性圆满成功，标志着项目正式迈入大型压缩机及系统调试的全新阶段。此次倒送电全面检验了升压站、主变压器、配电及厂用电系统等全套电气设备的安装质量与运行性能。作为全球在建单机功率最大的非补燃压缩空气储能项目，该里程碑节点的达成对后续单体调试及按期并网发电具有决定性保障作用。","scd":null,"kp":[]},{"i":43841,"as":"水电水利规划总院发布报告指出，中国300MW级压缩空气储能项目建设造价约为0.55-0.7万元/kW，且660MW级技术已取得关键进展。数据显示，2025年全国可再生能源发电装机达23.37亿kW，风光总装机历史性超越火电。新型储能呈集中式、大型化趋势，累计装机达1.36亿kW，其中10万kW及以上大型项目装机占比高达72%。","scd":null,"kp":[]},{"i":43842,"as":"Hagag Europe与Airengy宣布投资约5500万欧元，在罗马尼亚建设一座总储能容量达5GWh的盐穴压缩空气储能工厂。该项目采用Airengy专有的流体压缩气体长时“AirBattery”技术，计划分两期建设，最终实现25MW的放电容量。其中一期工程将新增约200MWh容量，预计整个项目的商业运营将于2028年初正式启动。","scd":null,"kp":[]},{"i":43843,"as":"山东省政府参事调研组赴芜湖围绕“企业主导的产学研融通创新”开展专题调研，实地考察华赛能源。调研组详细了解该企业在压缩空气储能与风光制氢领域的产学研合作、创新联合体建设及成果转化情况。华赛能源作为提供压缩空气储能与风光制氢系统解决方案的高科技企业，持续投入研发并深化产学研合作，以提升核心技术能力。","scd":null,"kp":[]},{"i":43844,"as":"山东肥城100MW/400MWh超临界二氧化碳高温热力电池储能示范项目的工程勘察中标候选人正式公示。该项目标志着大规模超临界二氧化碳高温热力电池储能技术进入实质性工程勘察与前期建设准备阶段。","scd":null,"kp":[]},{"i":43845,"as":"深能锡林郭勒西乌珠穆沁旗电网侧压缩空气储能项目地面电站工程EPC总承包中标结果正式公告。这标志着该电网侧压缩空气储能项目即将全面进入工程交付与建设实施阶段。","scd":null,"kp":[]},{"i":43846,"as":"6月13日，湖南安化抽水蓄能项目2号施工支洞顺利进洞，项目正式进入洞室施工阶段。该电站装机规模居华中第一、全国第三，其C2标段主要承担引水系统施工。2号支洞全长521米，承担4条引水主洞中平段及上竖井施工任务。项目投产后预计年发电量达26.1亿千瓦时，每年可减排二氧化碳约204万吨，将有效缓解湖南电网调峰需求。","scd":null,"kp":[]},{"i":43847,"as":"Gartner发布《2026年中型企业技术采用路线图》，梳理了50项新兴技术的部署节奏与价值风险判断。2026年中型企业技术发展聚焦六大关键方向：AI驱动自动化、云原生平台与安全云、网络安全网格、可组合式ERP、边缘计算以及可持续IT。该路线图旨在帮助CIO和IT负责人在不确定性中平衡技术投资的价值与风险，制定清晰的技术布局路径。","scd":null,"kp":[]},{"i":43848,"as":"全国冶金焦化在产总产能约5.70亿吨，独立焦化厂产能占比约64%，整体产能呈现有序收缩态势。产能高度集中于山西、河北、内蒙古、山东四省，占全国总产能一半以上。行业技术升级趋势明确：4.3米及以下小焦炉被加速淘汰，在产占比已不足6.5%；6米及以上大型焦炉成为主流，产能占比接近60%；干熄焦技术正加速普及，推进行业产能整合与大型化发展。","scd":null,"kp":[]},{"i":43849,"as":"阿根廷观测数据显示，南极半岛6月初出现15.4摄氏度的异常高温，比正常水平高出20多摄氏度，创下历史同期新高。埃斯佩兰萨科考站6月平均最高气温原为零下6.2摄氏度。马兰比奥和圣马丁科考站最高气温也分别达到11.8摄氏度和9.4摄氏度。由于气温持续高于零度，科考站区域失去积雪，对极地生态系统产生不利影响。","scd":null,"kp":[]},{"i":43850,"as":"意大利造纸企业Fedrigoni集团与纤维基特种材料公司Ahlstrom同生物甲烷生产企业签署长期供应协议。通过使用生物甲烷替代化石天然气，可满足其制造工厂约40%的天然气需求，并实现30%至50%的规模化碳减排。该可再生天然气已率先在特伦蒂诺的Varone工厂投入使用，以降低化石燃料地缘政治波动风险。","scd":null,"kp":[]},{"i":43851,"as":"Anthropic原定于6月13日举办Claude Fable 5开发者日，但Fable 5模型突遭禁令封禁。官方紧急调整，使用Opus 4.8模型替代。在黑客松现场，开发者基于Opus 4.8展示了多项技术成果，包括并行实时多语言同声传译工具DogeHouse Babel，以及基于残存图纸与文献的古建筑3D重建项目Tekton。","scd":null,"kp":[]},{"i":43852,"as":"在2026年美国大学毕业季演讲中，人工智能话题遭到强烈抵制。前谷歌CEO埃里克·施密特在亚利桑那大学提及AI时遭遇嘘声；哈佛毕业生对反对AI的言论欢呼支持。6月14日，谷歌CEO皮查伊在斯坦福毕业典礼演讲中全程回避AI话题，仅以自身姓氏开了一句玩笑。其演讲以个人经历为主，强调以“选择乐观”的视角看待事物。","scd":null,"kp":[]},{"i":43853,"as":"新智元启动All in ASI（人工超级智能）招聘计划，招募ASI架构师与ASI主笔，坐标北京上地，年薪均为50-70万元。ASI架构师需具备丰富AI Coding经验，熟练使用Claude Code等工具，负责将前沿模型能力封装为可落地的Agent与工具，并独立完成智能体架构设计与全流程交付。","scd":null,"kp":[]},{"i":43854,"as":"研究团队发现带电氮化硼纳米管（BNNT）具有反常超快离子传输特性。使用孔密度高达10^7 pores cm-2的宏观垂直排列纳米管膜测试发现，3纳米和12纳米的带电BNNT展现出超快阳离子选择性扩散，扩散速度超过菲克扩散31倍；且锂离子相对于钾离子和钠离子表现出反常的优先增强传输速率。该发现为锂回收和渗透能收集提供了新方法。","scd":null,"kp":[]},{"i":43855,"as":"中国科学院青岛生物能源与过程研究所崔光磊、董杉木团队开发出一种基于锂键原位形成的准固态凝胶电解质（LGE）。该电解质通过添加LiBF4诱导自组装形成稳定三维网络，在20°C下保持21.78 mS cm⁻¹的高离子电导率，有效抑制Li-SOCl2电池中AlCl3等腐蚀性中间体向锂阳极的迁移。配合100微米薄锂阳极，电池在5 mA cm-2下实现6 mAh cm-2高面积容量并稳定循环60次。","scd":null,"kp":[]},{"i":43856,"as":"韩国研究团队在JACS发表展望，阐述了自组装单分子层（SAM）在钙钛矿和有机太阳能电池中作为空穴传输层的设计与应用机制。SAM由锚定基团、连接单元和末端基团组成，通过调控功函数、缺陷钝化及结晶程度提升器件性能。基于SAM的钙钛矿电池实现了26.72%的认证效率，有机太阳能电池效率超过20%，有效降低了材料消耗。","scd":null,"kp":[]},{"i":43857,"as":"2026年6月15日，高等教育评价机构软科发布“2026软科中国大学专业排名”。该排名覆盖838个专业，采用学校条件、学科支撑、专业生源、专业就业、专业条件5个指标类别和27项指标，对1200多所高校的6万多个专业点进行评价。在电气工程及其自动化专业排名中，西安交通大学位列第一，清华大学位列第二。","scd":null,"kp":[]},{"i":43858,"as":"工信部就《光伏产品分级分类 第1部分：光伏组件》等6项行业标准公开征求意见。新标准将光伏组件划分为1级、2级、3级三个等级，综合评价总分≥80分才能获评1级。评分体系包含可靠性（40%）、发电性能（40%）和绿色属性（20%）三大维度，并在热循环、雪载、冰雹等关键测试场景进行分级设限。该标准旨在重塑光伏产业质量秩序，淘汰落后产能。","scd":null,"kp":[]},{"i":43859,"as":"挪威船级社（DNV）发布《2026年能源转型展望：氢能2060》报告指出，到2060年全球清洁氢需求将增长约100倍，每年减少超20亿吨碳排放，累计投资规模达3.2万亿美元。中国将贡献未来全球新增氢气生产和消费的35%。预计到2030年，全球将新增约1000万吨/年的可再生能源电解制氢产能，其中约一半位于欧洲和中国。","scd":null,"kp":[]},{"i":43860,"as":"全球碳管理企业LanzaTech宣布在比利时根特北海港建设欧洲首座商业化规模的乙醇制航煤（ATJ）可持续航空燃料（SAF）工厂。项目总投资约5亿欧元，预计年产7.9万吨SAF和9000吨可再生柴油。该工厂由FLITE联盟推进并获欧盟支持，生产的SAF完全符合国际民航组织CORSIA标准及欧盟ReFuelEU法规，目前已进入环境评估阶段。","scd":null,"kp":[]},{"i":43861,"as":"00后创业者陈源培联合创办灵初智能，聚焦机器人世界模型与具身大脑研发。该公司探索从人类操作数据出发训练机器人模型的路线，旨在让机器人理解物理世界并完成长程操作任务。陈源培曾在北京大学参与高自由度双手灵巧操作强化学习研究，并在斯坦福大学参与利用人类数据训练机器人双臂操作的研究。灵初智能目前已累计融资超20亿元。","scd":null,"kp":[]},{"i":43862,"as":"清华大学联合多机构在《自然·机器智能》发表研究成果，提出名为UniCM的AI气候预测统一模型。该模型基于Transformer架构，包含负责海洋大气基础物理数据的Globalformer分支和负责气候模式的Modeformer分支。UniCM将厄尔尼诺-南方涛动（ENSO）的有效预测时效延长至19个月，并能同时解析太平洋、印度洋和大西洋多个关键气候模式之间的跨洋远程联动影响。","scd":null,"kp":[]},{"i":43863,"as":"NASA选定美国初创公司Lunar Outpost提出的“飞马”方案作为新一代月球车。月球车需应对月球南极近367度的极端温差及腐蚀性月尘等恶劣环境挑战。2025年下半年，NASA曾向直觉机器、Lunar Outpost和Astrolab三家公司授予初步设计合同，原计划三选一。2026年初“阿尔忒弥斯2号”成功发射等因素促使月球车竞争格局洗牌，打破了仅资助一家公司的原定预算计划。","scd":null,"kp":[]},{"i":43864,"as":"涡喷、涡扇、涡桨和涡轴四种航空发动机均基于燃气涡轮原理工作，核心流程为吸气、压缩、燃烧、驱动涡轮和喷气。涡喷发动机是最早成熟的机型，高空高速性能好，但低速油耗极高。涡扇发动机在涡喷核心机前加装大风扇，吸入空气分为内涵道燃烧和外涵道直接排出两部分，以此提升推进效率。四种发动机的根本差异在于对燃烧产生能量的具体分配方式不同，从而满足不同飞行器的设计需求。","scd":null,"kp":[]},{"i":43865,"as":"全球仅有5款五代隐身战斗机服役，设计标准以F-22的隐身、超音速巡航、超机动和超态势感知的“4S”标准为核心。中国歼-20是全球尺寸最大的五代机，装配国产涡扇-15发动机、氮化镓有源相控阵雷达等设备。双座型的歼-20S是全球首款双座隐身战机，后座飞行员专门负责指挥“忠诚僚机”无人机群，其航电和武器系统大幅升级。","scd":null,"kp":[]},{"i":43866,"as":"汽车由约3万个零件构成，制造逻辑呈“零件-合件-组合件-总成”金字塔结构。从使用性质划分，汽车零件分为跑行至一定期限必须更换的消耗件，如轮胎、火花塞、滤芯等。此外还有易损件等分类。车主在日常维修和养护车辆时，需基于不同零件的属性与损坏周期，在原厂件、品牌件、副厂件中进行合理选择。","scd":null,"kp":[]},{"i":43867,"as":"电镀工艺通过在金属零件表面附着金属膜实现防锈、耐磨等功能。主流三大工艺各有特点：镀锌成本最低，利用锌的活泼性优先腐蚀以保护底层铁；镀镍形成致密屏障，兼具防腐、耐磨、导电和外观优势，常配合化学镀处理复杂内孔；镀铬分装饰铬与硬铬，装饰铬极薄且光亮，硬铬镀层硬度达HV800-1000以上，具备极高耐磨性和自润滑性，常用于液压杆等工业部件。","scd":null,"kp":[]},{"i":43868,"as":"谷歌与美国航空签署了航空业与企业用户间最大规模的3500万加仑可持续航空燃料（SAF）协议，预计减少近30万吨二氧化碳当量排放。谷歌通过购买减排属性降低碳足迹，美国航空负责燃料采购使用，该合作推动美航与生产商Valero达成长期采购协议。SAF可使航空碳排放降低80%，此协议创造了由企业客户提供资金、航企提供减排场景的新融资模式，标志着航空碳减排向源头真实减排转变。","scd":null,"kp":[]},{"i":43869,"as":"上海碳生万物科技有限公司完成A轮融资，资金将主要用于宁夏千吨级直接空气碳捕集（DAC）及电制可持续航空燃料（e-SAF）中试线建设。该中试项目总投资1亿元，包含DAC、电解水、电还原CO2及费托-加氢制SAF单元，设计年产833.5吨SAF，副产石脑油和柴油。目前项目核心技术指标已达国际先进水平，处于环境影响报告书公众参与公示阶段。","scd":null,"kp":[]},{"i":43870,"as":"广西自贸区川桂临港新能源有限公司30万吨/年生物质液体燃料项目已进入施工准备阶段。项目总投资约8.4亿元，占地130亩，以废弃动植物油脂为原料，采用二段法加氢工艺生产生物柴油和生物航煤（SAF）。近日，项目施工总承包监理服务由四川省城市建设工程咨询集团有限公司以451.02万元中标，监理范围涵盖全阶段的质量、进度、安全等全过程控制。","scd":null,"kp":[]},{"i":43871,"as":"全国首个规模最大的“光氢储一体化”项目在江苏如东建成。该项目占地4388亩，光伏总装机400兆瓦，年均上网电量约4.68亿千瓦时。项目配套建设1500标方/小时制氢站和60兆瓦/120兆瓦时电化学储能电站，年产高纯绿氢482吨。项目首创滩涂生态治理光伏模式，每年可减排二氧化碳超30万吨。此外，中国石油兆瓦级制氢项目近期也获得备案。","scd":null,"kp":[]},{"i":43872,"as":"巴西IT公司推出的开源大模型Rio 3.5在多项基准测试中取得SOTA性能，但被证实为套壳缝合模型。经Nex-AGI团队分析，Rio 3.5底层由60%的Nex N2 Pro模型和40%的阿里Qwen 3.5模型通过模型合并技术拼凑而成。在移除特定系统提示词后，该模型有79%的概率自称为Nex，且权重张量数据证实其所有网络层均为0.6/0.4的固定混合比例。","scd":null,"kp":[]},{"i":43873,"as":"微软CEO纳德拉发文指出，AI正在改变企业竞争底层逻辑，未来经济将包含“人力资本”与“Token资本”。AI模型能将人类专业知识商品化，导致各行业价值向少数吞噬一切的AI系统让渡。他呼吁决不能让少数AI系统攫取所有经济回报，同时强调没有生态系统的技术前沿是不稳定的。此举引发了业界对AI巨头垄断经济收益的担忧。","scd":null,"kp":[]},{"i":43874,"as":"","scd":null,"kp":[]},{"i":43875,"as":"现代汽车联合波士顿动力，将在2026年世界杯期间部署定制版Spot四足机器人用于现场安保。投入的四台Spot机器人配备热成像、360度视觉与多传感器系统，能自主上下楼梯，执行全天候巡逻与异常检测。机器人承担高频重复巡查，人类安保人员负责威胁响应。这种人机协同模式将安保体系升级为移动传感器网络，并建立了分层安保体系。","scd":null,"kp":[]},{"i":43876,"as":"西门子能源目前手握高达1540亿欧元订单创历史新高，AI数据中心对电力稳定的需求促使燃气轮机业务成为其最强劲的增长引擎。与此形成对比，其风电子公司Siemens Gamesa面临结构性危机，欧洲海上风电产业链遭遇瓶颈，预计欧盟到2030年将面临约40GW的海上风电装机缺口，其中德国市场有16GW项目面临延期风险。","scd":null,"kp":[]},{"i":43877,"as":"《ES&T》刊发的研究提出了一种在不确定性下规划可持续电力系统的方法。研究以加拿大育空地区为案例，将社会、生态、成本和排放等目标转化为容量扩张模型约束，并采用蒙特卡罗模拟评估策略风险。研究发现，电力低碳规划不能过度约束，过度严格的限制反而会推高系统成本和对紧急柴油机的依赖。在偏远地区，保留技术灵活性是更为稳健的规划路径。","scd":null,"kp":[]},{"i":43878,"as":"青骐骥作为并列最大供货商，已开始向中石化中天合创风光制氢一体化项目交付电解槽。该项目是中石化继新疆库车后的全球第二个大规模绿氢项目，对电解槽的单机能耗、负荷响应和全生命周期稳定性提出了严苛指标。青骐骥依托全链条自主研发制造能力，保障了产品品质和快速交付。","scd":null,"kp":[]},{"i":43879,"as":"武汉睿事达新材料在武汉建成湖北省首条千吨级氧化物固态电解质规模化产线。该产线由华中科技大学团队技术支撑，攻克了连续化制备、一致性控制等行业难题，产品离子电导率等关键指标达行业先进水平。产线的建成标志着固态电池核心材料从实验室走向工业化量产，产品可广泛适配新能源汽车及航空航天等高端应用。","scd":null,"kp":[]},{"i":43880,"as":"水规总院报告显示，2025年全国可再生能源发电装机达23.37亿千瓦，占总装机60.1%，风光装机历史性超过火电。报告同期指出，当前300MW级压缩空气储能项目造价在0.55至0.7万元/kW之间。此外，660MW级压缩空气储能技术已取得关键进展，进一步推动了长时储能领域的技术迭代。","scd":null,"kp":[]},{"i":43881,"as":"中国石化在世界地热大会上展示了地热产业成果。截至5月底，其累计建成地热供暖能力达1.36亿平方米，覆盖12省市70余城，惠及超120万户。中国石化构建了“雄县模式”等开发样板，被国际机构列入全球推广名录。其深层地热重点实验室已投入运行，我国首个“热电氦”集成项目也在陕西关中盆地落地。","scd":null,"kp":[]},{"i":43882,"as":"江苏锂凰科技有限公司拟投资5000万元，建设年产240吨高比能固态电池硅碳新材料生产中试项目。该项目位于扬州化学工业园区，将购置CVD沉积炉等生产设备。上海锂凰核心产品为高比能固态电池材料，具备高能量密度和长循环寿命，目前广泛应用于新能源汽车、飞行器及人形机器人等领域。","scd":null,"kp":[]},{"i":43883,"as":"中国科学院大连化物所团队提出面向无堆叠压力全固态微电池的“结构可编程固态电解质”新概念。该研究通过介观拓扑、梯度异质结构等几何设计，内化外部堆叠压力，重构界面应力分布，解决了零压力下固-固界面易失稳的问题。此设计同时优化了离子传输路径，为新一代安全、高效微型储能器件提供了新方案。","scd":null,"kp":[]},{"i":43884,"as":"科研人员提出Ni驱动的一步还原-置换策略，在氮掺杂碳纳米管上规模化制备Pt单原子位点催化剂（NCNT-Ni/Pt）。该催化剂具有N2-Pt-Cl2初始配位结构，在HER过程中Pt-Cl键动态演化以调控反应动力学。在10 mA cm⁻²下过电位仅7.78 ± 0.86 mV，Pt负载量低至6 μg cm⁻²。在PEM水电解器中实现1.63 V@1 A cm⁻²，衰减率仅3.3 μV h⁻¹并连续运行4500小时，耦合光伏系统的太阳能制氢效率达16.06%。","scd":null,"kp":[]},{"i":43885,"as":"研究人员开发出MOF衍生的非贵金属Ni@FeCo核壳催化剂，用于碱性水电解。金属Ni核提供导电与结构支撑，Fe/Co富集壳层在运行中转化为活性尖晶石氧化物。该催化剂在RDE中1.57 V vs RHE下达10 mA cm⁻²；用于AEMWE时，在2.18 V下达10 A cm⁻²，并在1.8 V恒压下稳定运行超1700小时。原位表征证实运行中Fe、Co被氧化，Ni保持金属态，形成金属核与氧化物壳结构。","scd":null,"kp":[]},{"i":43886,"as":"具身智能企业大晓机器人在2026年上半年完成多轮融资，累计金额达数亿美元，投资方包括达晨财智、深创投、上海科创基金等多家机构，成为该领域最快达到独角兽估值的公司。同时，该公司自主研发的开悟世界模型Kairos在RoboTwin 2.0、LIBERO-Plus、WorldModelBench Robot、DreamGen四大全球具身智能基准测试中均位列第一。该模型参数量为4B。","scd":null,"kp":[]},{"i":43887,"as":"OpenRouter上线Fusion新功能，将同一问题分发给一组模型，再由裁判模型融合生成最终答案。在深度研究测试基准DRACO中，由Gemini 3 Flash、Kimi K2.6、DeepSeek V4 Pro组成的高性价比开源模型预算组获得了64.7%的得分，超越了单独运行得分为60.0%的GPT模型。融合配置的整体表现优于单一模型，且成本仅为前沿大模型的一半左右。","scd":null,"kp":[]},{"i":43888,"as":"一项研究盘点了2000至2021年中国329个城市的碳排放数据。22年间全国城市碳排放总量从3729.3百万吨增至12122.5百万吨，增长2.25倍。2012年前后成为增速拐点，2010年前年均增速为9.2%，此后降至2.7%。高排放城市主要集中在东北工业区、东部沿海城市群和川渝地区，上海、唐山、苏州、重庆和天津为典型代表。约90%的城市22年间排放增量在50百万吨以下。","scd":null,"kp":[]},{"i":43889,"as":"美国能源部正式发布《聚变科学与技术路线图》终版，核心目标是在2030年代中后期交付美国聚变示范电站。该路线图由800多名公私领域专家参与制定，以“建设-创新-成长”三大驱动力为框架：“建设”聚焦关键基础设施与材料缺口；“创新”依托高性能计算和AI推动研发；“成长”侧重公私合作、供应链、人才培养和商业化路径。该文件由新设立的聚变办公室负责实施。","scd":null,"kp":[]},{"i":43890,"as":"2026年6月9日，美国田纳西州《第0400-20-14章核聚变》规章正式生效，使其成为美国首个拥有独立州级核聚变装置监管框架的州。该规章由田纳西州环境与保护部下属放射卫生司执行。基于美国核管制委员会将聚变装置归入副产物材料许可体系的决定，田纳西州作为协议州，为州内的聚变装置、工艺及相关活动确立了具体的注册与许可监管标准。","scd":null,"kp":[]},{"i":43891,"as":"微管束除雾器是适用于煤化工、电力、冶金等行业的新一代高效除尘除雾设备。其工作原理是通过导流叶片使烟气旋转，利用离心力捕获微粒形成液膜。由于径向距离大幅减小，微粒更易触及管壁，从而提升除尘除雾效率。该设备具有抗污堵、易清洗、阻力小和结构强度高等特点。实际应用中仅需安装单层即可满足较低排放要求，兼具占地小、运行成本低的优势。","scd":null,"kp":[]},{"i":43892,"as":"当前碱性电解槽制氢改性聚四氟乙烯（PTFE）垫片主要有两种制造工艺。模压烧结工艺通过模具压制和高温烧结成型，材料致密且综合性能优异，适合复杂形状和标准化大批量生产，但模具初始投入高、柔性差。整体压实加逐片切割工艺则是先将材料压制成大尺寸型材，再用CNC或冲压加工成单片，灵活性强，适合小批量、多品种和非标定制，研发试制成本低。","scd":null,"kp":[]},{"i":43893,"as":"针对欧盟《清洁能源一揽子计划》征求意见，法国工业界提交立场文件，强调核能不应与可再生能源对立。法国能源联合会指出，核电提供全天候、可预测的低碳基荷电力，是系统脱碳基石；可再生能源则在分布式等场景具独特优势。核电的可调度性能够平抑电价波动，在可再生能源出力不足时填补缺口，避免对化石能源的回弹依赖，二者协同是能源系统的最优解。","scd":null,"kp":[]},{"i":43894,"as":"法国光伏国家研讨会就光伏与新一代核能的经济性进行辩论。测算显示，尽管现有折旧核电边际成本约70欧元/兆瓦时，但新一代核电（如EPR2）造价高昂。弗拉芒维尔3号EPR机组实际造价已达原预算5至6倍，使其平准化度电成本明显高于当前光伏加储能系统。面对电力缺口，法国行业共识是核电与太阳能不应被视为对手，两者协同才能经济、安全地填补未来电力供应缺口。","scd":null,"kp":[]},{"i":43895,"as":"宁夏永利300MW/600MWh储能工程于2026年6月10日并网投运，是国内单体规模最大的光伏配储项目。工程配套300万千瓦光伏基地，分三座100MW/200MWh电站建设。系统采用构网型控制策略，具备一次调频、虚拟惯量和黑启动等电网支撑能力，实行每日两充两放。该项目年均可消纳光伏电量超4.5亿千瓦时，年减排二氧化碳约37.5万吨。","scd":null,"kp":[]},{"i":43896,"as":"","scd":null,"kp":[]},{"i":43897,"as":"绿电算力工厂产业链复杂，涵盖新能源开发、储能、散热、算力硬件等十余个环节。GCTA（绿电算力联盟）的核心价值在于将传统的“线性采购”升级为“网络化协同”。该组织通过制定统一的技术标准与接口规范实现各模块无缝对接以降低协同成本，并基于共同投资、共担风险、共享收益的原则深度绑定联盟成员，解决传统模式信息不对称和利益不协同的问题。","scd":null,"kp":[]},{"i":43898,"as":"腾讯研究院AI速递指出：1. Anthropic的Fable 5模型因被曝“秘密降智”且遭美国政府以国家安全为由发函出口管制，上线四天后全球下线。2. OpenAI收购云执行公司Ona，为其智能体提供基础设施，其Codex周活突破500万，年内增长400%。3. 李飞飞联合创立的World Labs发布三篇空间智能论文，核心思路是借助成熟的2D生成模型来降低3D内容生成的技术门槛。","scd":null,"kp":[]},{"i":43899,"as":"天合光能自主研发的高效钙钛矿/晶体硅叠层光伏组件成功获得海外高端分布式市场首单签约，订单落地于新西兰。此次交付的标准化工业组件基于900+W世界纪录级叠层技术体系，完全适配户用光伏规范。相比主流晶硅组件，该叠层组件可使系统BOS综合成本降低15%~20%，凭借优异的温度系数与弱光性能，同面积组件发电量提升20%~30%，实现了从实验室到商业落地的跨越。","scd":null,"kp":[]},{"i":43900,"as":"炎和科技与云遥宇航签署卫星太阳翼战略合作协议，共同推进钙钛矿太阳翼规模化应用。云遥宇航是国内商业气象卫星领军企业，已建成由47颗卫星组成的商业掩星探测气象星座。炎和科技在钙钛矿太空光伏领域具备成熟经验，其“星辰”“星云”系列产品在光电转化效率、功质比和可靠性上表现突出。双方将构建“技术-验证-落地-市场”闭环，加速太空光伏商业化。","scd":null,"kp":[]},{"i":43901,"as":"光因科技与深燃研究院签署协议，围绕钙钛矿材料研发、组件实证及太空光伏等方向合作。深燃研究院依托国资体系为新技术提供应用与验证场景。光因科技专注钙钛矿产业化，已20次刷新电池效率世界纪录：单结效率27.87%、全钙钛矿叠层效率31.55%、0.72平米商用组件全面积效率20.7%（功率149W），且已贯通徐州200MW量产线。","scd":null,"kp":[]},{"i":43902,"as":"晶科能源宣布其自主研发的N型TOPCon钙钛矿叠层电池转换效率经认证突破34.82%，刷新了自身保持的34.76%同类电池纪录。这是该公司第33次打破电池效率和组件功率世界纪录。此次效率提升得益于双层复合钝化接触结构、多维界面钝化、梯度结晶动力学调控及光学耦合增强等多项核心技术创新，标志着其在钙钛矿叠层技术产业化进程中取得关键突破。","scd":null,"kp":[]},{"i":43903,"as":"逸飞激光在华中钙钛矿论坛上展出了其全工序激光装备矩阵，重点锚定钙钛矿产业化的关键节点。通过提供覆盖多道工序的激光加工设备，逸飞激光旨在解决钙钛矿电池从实验室研发向大规模工业化量产转化过程中的制造技术难题。","scd":null,"kp":[]},{"i":43904,"as":"文章强调综合国力竞争的核心在于人才，指出必须一体推进教育、科技和人才发展。面对我国重大科研项目中领军人才结构性不足的矛盾，提出要改革完善人才发展机制，建立灵活的人才管理机制，深化教育改革，推进素质教育。目标是造就规模宏大、结构合理的高水平创新人才队伍，大力培养世界级科学家、科技领军人才、卓越工程师和高水平创新团队。","scd":null,"kp":[]},{"i":43905,"as":"中共中央组织部发文强调以体制机制改革激发人才创新创造活力。文章指出，深化人才发展体制机制改革是破除束缚人才发展障碍、增强人才活力的关键。我国面临科技人才总量大但结构性不足、领军人才严重不足的矛盾。必须破除人才培养、使用、评价等方面的体制机制障碍和“四唯”现象，将制度优势转化为人才与科技竞争优势，从而为一体推进教育科技人才发展提供制度支撑。","scd":null,"kp":[]},{"i":43906,"as":"中国科学院院长侯建国阐述教育科技人才一体发展的实践要求。他指出，教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑。必须通过深化改革打破条块分割，打通体制机制堵点，形成三者相互支撑的良性循环。战略目标设定为到2035年同步建成教育强国、科技强国、人才强国，党中央已通过一系列统筹部署和重大改革发展举措，为教育科技人才一体发展绘就了明确的路线图与任务表。","scd":null,"kp":[]},{"i":43907,"as":"本文强调一体推进教育科技人才发展对支撑中国式现代化的重要战略意义。教育、科技、人才三者互为支撑，必须有机结合统筹推进以产生倍增效应。近年来，我国在量子科技、核聚变、人工智能等前沿领域取得重大创新成果。根本原因在于党中央将教育发展、科技创新、人才培养摆在治国理政突出位置，推动三者有效联动与良性循环，形成统一步伐，从而为中国式现代化提供强有力的支撑。","scd":null,"kp":[]},{"i":43908,"as":"文章探讨高水平研究型大学如何一体推进教育科技人才发展。大学作为拔尖创新人才培养主阵地和重大科技突破策源地，需破除体制壁垒，系统性重塑治理、资源配置与评价激励逻辑。长期以来，大学内部教学、科研与人才工作边界固化导致资源分散。通过整体协同与系统性重构，打通教育科技人才工作机制，能够实现相互贯通与循环支撑，最终达成“1+1+1>3”的聚变效应。","scd":null,"kp":[]},{"i":43909,"as":"美国核决策体系具有集中与制衡相结合、快速反应能力及多层安全保障三大核心特点。总统拥有核打击最终决定权，同时受国防部长否决权与国会等多重机制制衡。体系依托专用加密通信网络，力求在15分钟内完成从探测威胁到部队执行的跨部门极速闭环。为防误发或篡改，身份验证采用生物识别与动态密钥，指令传输运用量子加密，执行阶段严格实行双人双钥规则。","scd":null,"kp":[]},{"i":43910,"as":"美国无人机打击行动在选民中支持率较高，受欢迎程度显著优于有人驾驶飞机攻击。皮尤民调显示58%的受访者支持利用无人机打击极端分子，共和党人支持率达74%。在管控规则方面，美国总统对无人机袭击拥有极大控制权。9/11事件后，美国国会通过《授权使用军事力量打击恐怖分子法案》，极大扩大了总统的军事权力，允许对恐怖分子使用所有必要和适当的武力。","scd":null,"kp":[]},{"i":43911,"as":"美国正通过马六甲防务合作计划（MDCP）在马六甲海峡构建“安全网、威慑网与杀伤网”三重网概念。该架构依托无人空中与水下无人机平台，建立共享海上态势感知系统。安全网利用无人艇与传感器网格全天候提供持续性ISR以维持海事秩序；威慑网则利用同一基础设施记录异常活动，生成证据链以消除灰色地带的模糊性，从而根据权限与交战规则同时服务于安全、威慑与实战功能。","scd":null,"kp":[]},{"i":43912,"as":"受电费账单攀升和数据中心建设狂热影响，美国电力行业正面临广泛的不信任与愤怒。调查显示超75%的美国人认为家庭能源成本过高，64%的受访者将成本上涨归咎于公用事业公司盈利动机。核心矛盾在于投资者拥有的公用事业公司（IOUs）的商业模式，该监管机制鼓励资本支出以获取回报，直接导致企业忽视挖掘现有电网潜力，且伴随高额行政开支与高管薪酬，最终引发行业规则重塑的政治风暴。","scd":null,"kp":[]},{"i":43913,"as":"","scd":null,"kp":[]},{"i":43914,"as":"星海图在全球开发者大会上公布具身智能模型、本体与数据进展，其G0.5大模型处于全球第一梯队，自研人形机器人Kengo亮相，并启动百万小时真实数据计划。国内具身智能行业正呈现清晰分层：宇树科技侧重本体硬件与量产工程；智元强调全链路软硬件垂直整合；星海图则以整机为载体获取真实场景数据反馈，旨在实现模型闭环。行业竞争正从单台产品比拼转向数据与生态的较量。","scd":null,"kp":[]},{"i":43915,"as":"SpaceX宣布通过全股权交易收购AI编程工具Cursor母公司Anysphere，交易估值达600亿美元。此次收购旨在加速SpaceX在企业级AI市场的布局。Cursor将成为SpaceX全资子公司，股东将获 SpaceX A类股份，交易预计于2026年第三季度完成。在上市取得高市值与充足流动性后，SpaceX正式行使此前获得的期权，实现算力与股权的深度绑定，成功截胡Cursor的独立融资。","scd":null,"kp":[]},{"i":43916,"as":"中国多所高校研究人员在TMLR发表综述，系统回顾了时间点过程(TPPs)的最新进展。文章全面探讨了贝叶斯TPP、神经TPP、基于大语言模型的TPP、训练方法及应用场景，并分析了该算法在不规则时间事件数据建模领域所面临的开放性挑战。","scd":null,"kp":[]},{"i":43917,"as":"德国研究表明，Wi-Fi信号能够成为隐蔽的监控工具，即使手机关机或处于飞行模式也能识别人体一举一动。自Wi-Fi 5时代普及的波束成形技术是主要风险源头。人体富含水分子会对无线电波产生吸收和反射，当人穿过Wi-Fi覆盖区域时会引起独特的信号波纹变化。通过机器学习分析这些无线电波的传播变化，能够隔墙构建周围环境和人员的活动图像，实现精准追踪。","scd":null,"kp":[]},{"i":43918,"as":"北航团队联合研发了一款重量不足1公斤的可穿戴机器人，旨在改善脊髓性肌萎缩症（SMA）儿童的神经肌肉功能。该设备为患儿提供持续的定制化抗阻力训练。临床数据显示，6名6-10岁无法行走的患儿在使用该设备6周后，股四头肌体积增加约20%，屈膝力量提升超两倍，且能从更低坐姿角度站起。该设备的可穿戴特性极其适宜家庭使用，有效促进了患儿的神经肌肉协同恢复。","scd":null,"kp":[]},{"i":43919,"as":"全球最大电池制造商宁德时代（CATL）宣布其Naxtra钠离子电池已转入GWh级工业化生产，标志着全球钠离子电池商业化重大里程碑。首批产品将应用于长安汽车商业化钠离子电动汽车，未来续航目标达600公里。供应链成熟后，钠离子电池有望占据30%-40%的市场份额，预计今年底成本将与锂离子电池持平。目前CATL已签署60GWh供应合同并投资50亿元扩建产能。同时，通用汽车也宣布联手初创企业Peak Energy开发钠离子电池系统，正式进军工业级储能市场。","scd":null,"kp":[]},{"i":43920,"as":"韩国科学技术院研究团队提出了一种基于光子频率梳参考的太赫兹（THz）法布里-珀罗干涉测量技术，成功实现锂离子电池电极纳米级厚度测量。传统X射线、超声波和光学激光方法在测速、分辨率或穿透能力上存在局限，而该技术融合了光频梳可溯源至国际单位制的高精度及太赫兹对导电材料的穿透能力。这一突破填补了现有无损检测技术的不足，为电池高精度制造和质量控制提供了全新手段，有效预防热失控风险。","scd":null,"kp":[]},{"i":43921,"as":"美国波多黎各大学与康奈尔大学联合团队通过调控电解液溶剂化结构，成功打破传统能斯特方程热力学限制，开发出高电压金属基水系浓差电池。研究通过高浓度电解液提升正极电位并利用络合剂降低负极电位，实现了0.7V的锌-锌浓差电池，电压提升超20倍。该工作原理还能与多种锌离子正极匹配，使水系锌离子电池工作电压达到2.2V至2.5V，为突破传统浓差电池低电压瓶颈提供了新思路。","scd":null,"kp":[]},{"i":43922,"as":"哈尔滨工业大学联合斯德哥尔摩大学等机构提出在锂金属阳极表面构建疏溶剂分子层，实现锂金属电池超快充。该技术通过排斥溶剂分子促进界面去溶剂化，诱导形成致密富LiF固体电解质界面（SEI）。在强溶剂化碳酸盐电解质中，该策略保持了高体相离子电导率，即使在6 mA cm-2超高电流密度或100 mAh cm-2超高面容量下，仍能保持球形锂沉积形态，实现了无枝晶的超快充性能。","scd":null,"kp":[]},{"i":43923,"as":"清华大学联合香港大学团队深入研究少负极水系锌电池失效机制，识别出电偶腐蚀是关键衰退路径。在有限锌过量下，沉积锌与暴露集流体间的自发电偶耦合约占不可逆锌损失的78%。为此，团队构建了由电绝缘聚合物基体和高介电常数金属氟化物组成的杂化钝化层。该层产生的介电极化效应能均匀化电场，促进致密锌沉积，有效抑制电偶腐蚀，极大提升了水系锌电池的循环寿命与日历老化稳定性。","scd":null,"kp":[]},{"i":43924,"as":"广东工业大学研究团队提出拓扑结构调控策略，通过熔盐辅助骨架重排制备出高结晶度有序C3N4拓扑网络（CN-MS-2），以解决锂硫电池动力学瓶颈。该材料提出“预集成锂”机制，利用有序吡啶氮位点重构锂离子溶剂化壳，显著降低脱溶剂化能垒。其分级多孔长程有序拓扑网络为锂离子提供连续快速传质通道，同步实现了锂离子脱溶剂化调控与多硫化物高效转化，为高比能锂硫电池研发提供了新思路。","scd":null,"kp":[]},{"i":43925,"as":"西北工业大学物理科学与技术学院储能电池原位光学诊断与智能感知团队面向海内外公开招聘博士后研究人员。团队负责人刘甫教授长期致力于先进储能电池原位光纤传感与多场耦合演化机制研究。课题组具备完善的原位光纤传感与多模态诊断平台，科研经费充足，且与法国国家科研中心等国际机构保持长期合作，能够为博士后提供优良的科研环境与广阔的国际交流机会。","scd":null,"kp":[]},{"i":43926,"as":"美国能源部（DOE）与北达科他大学能源与环境研究中心续签合作协议，未来五年投入2500万美元用于开发化石能源和地热能资源。研究重点包括：非常规储层提高采收率及产出水利用；煤炭先进利用与稀土元素共采；地热资源表征及油气设施改造发电；提升电网效率与可靠性；先进碳捕集及CO2高值化利用。旨在消除能源转型技术障碍，强化本土资源利用与能源基础设施韧性。","scd":null,"kp":[]},{"i":43927,"as":"宁波大学针对深度空气分级W火焰锅炉难以兼顾低氮与高效燃尽的问题，开展了低挥发分无烟煤再燃试验。通过设置10%至20%五种再燃燃料比例工况发现，随着比例增加，燃烧强度先增强后减弱，NOx排放和飞灰含碳量先降后升。当再燃比例为15%时综合性能最佳，NOx排放降至521 mg/m3，飞灰含碳量为4.8%。该技术有效提升了锅炉的低氮燃烧与燃尽性能。","scd":null,"kp":[]},{"i":43928,"as":"全球首个超临界二氧化碳余热发电项目“超碳一号”示范工程全面建成。该项目由中核集团中国核动力研究设计院等联合打造，包含两台15兆瓦机组，总装机容量达30兆瓦。首台机组自2025年12月投运以来稳定运行超5个月，各项性能指标达设计标准。第二台机组已顺利并网发电。项目的建成证明了超临界二氧化碳余热发电技术的先进性、系统可靠性与运行灵活性。","scd":null,"kp":[]},{"i":43929,"as":"","scd":null,"kp":[]},{"i":43930,"as":"欧盟碳边境调节机制（CBAM）于2026年1月1日进入全面实施阶段，目前覆盖钢铁、铝、水泥等六大类产品。2026年第一季度CBAM官方证书价格定为75.36欧元/吨二氧化碳当量，2027年起正式清缴碳成本。当地时间2026年6月12日，欧盟理事会达成一致，同意将碳关税范围扩大至近400种新的钢铁产品。这释放了明确的政策信号，出口企业面临的碳合规压力与成本将进一步增加。","scd":null,"kp":[]},{"i":43931,"as":"今年前5个月，国内新能源重卡销量达10.3万辆，同比增长68%，市场渗透率首次突破30%。新能源重卡逆势爆发主要受经济账驱动，单车每年最高可节省14万元运营成本，8年生命周期可创造近50万元超额利润。国家十一部门联合印发《推动新能源重卡规模化应用实施方案》，提出到2030年新能源重卡渗透率达40%、保有量突破160万辆的目标，产业迎来规模化发展。","scd":null,"kp":[]},{"i":43932,"as":"据2025年第二季度调查，美国电网变压器设备短缺加剧，标准电力变压器平均交货周期达128周，发电机升压变压器达144周，特殊订单甚至需四年。设备可用性已取代资金和审批成为工业项目的首要制约。此外，光伏企业国晟科技因未及时披露超5100万元的诉讼信息，被北京证监局采取出具警示函的监管措施，董事长及总经理等高管被记入诚信档案。","scd":null,"kp":[]},{"i":43933,"as":"随着AI成本不断攀升，硅谷科技巨头开始限制员工内部AI Token使用。Meta员工曾在30天内消耗60.2万亿个token，成本约9亿美元（折合人民币约65亿元），但未产出实在价值。Meta计划于2027年推行以预算和配额为核心的词元管理机制。此前亚马逊也已停止其内部用于跟踪员工Token消耗情况的榜单。企业已从盲目追求Token消耗转向注重AI实际产出与成本控制。","scd":null,"kp":[]},{"i":43934,"as":"特朗普政府已主动撤回针对禁止美国开发风力发电项目行政命令的上诉申请，确认18个州胜诉。此前该行政命令无限期冻结了风能项目联邦审批，影响了约106个风电项目，涉及超470亿美元投资，原计划提供近30吉瓦电力。马萨诸塞州地方法院曾裁定该禁令违法且超出总统权限，要求恢复联邦机构对海上风电项目的正常审批流程，目前审批流程已回归正常。","scd":null,"kp":[]},{"i":43935,"as":"研究团队通过Au(III)邻苯二酚前体的一电子氧化，获得了可分离的Au(III)半醌络合物并建立了稳定的EDA复合体系。EPR和XANES等表征证实氧化发生在配体而非金属中心。在530nm可见光驱动下，该体系展示了单电子转移能力，成功实现了氮杂氮正离子的偶联。在温和条件下，反应20分钟转化率达65%，C2位选择性芳基化最高分离收率约84%，具有广泛的官能团兼容性。","scd":null,"kp":[]},{"i":43936,"as":"海南正构建一、二次能源协调发展的新型能源体系。截至2025年底，海南全省电力装机约2480万千瓦，可再生能源装机占比约54%；原油产量达100.84万吨，天然气产量57.34亿立方米。昌江核电一期稳定运行，二期及小型堆示范工程加快推进。煤炭占一次能源消费比重降至约20%。海南目标到2025年将能源自给率提升至24%，为自由贸易港提供安全、绿色、经济的能源供应保障。","scd":null,"kp":[]},{"i":43937,"as":"字节跳动旗下豆包应用每天有2亿多用户，但日收入不足百万元，而日均算力消耗成本达数千万元。字节跳动计划将2026年资本开支上调至超2000亿元。因AI高昂的运行成本，字节正将AI资源重心从面向大众的免费产品转向面向企业的付费服务。相比之下，Anthropic凭借Claude Code在半年内实现10亿美元年化收入，证明了企业级AI服务的盈利能力。","scd":null,"kp":[]},{"i":43938,"as":"山西定襄县启动第二污水处理厂绿色低碳标杆化建设项目，总投资约1.7亿元。项目建设规模为日处理污水1.5万立方米，将新建AAO生化池、深度处理车间等设施。项目重点配套建设智慧水务、精准曝气、厂区分布式光伏发电及污水源热泵供热系统。此外，还将新建配套进厂污水管道及生态补水管道，招标工作预计于2026年7月开展。","scd":null,"kp":[]},{"i":43939,"as":"软科发布“2026中国大学专业排名”，北京大学、清华大学和哈尔滨工业大学位列A+专业数前三。在地矿类专业中，中国地质大学（武汉）、中国矿业大学等传统强校在地质工程、采矿工程等专业稳居榜首。综合性高校中，中国科学技术大学获得地球化学、安全工程等专业第一；南京大学连续三年占据地质学榜首；武汉大学在测绘类专业全面领先。","scd":null,"kp":[]},{"i":43940,"as":"三峡水运新通道工程正式开工，这是“十五五”首个国家重大标志性工程。建成后三峡和葛洲坝枢纽将形成四线船闸格局，大幅提升长江通航能力。南矿集团作为重要设备供应商参建，为项目提供全面的砂石骨料系统解决方案，涵盖JC颚式破碎机、圆锥破碎机、高压对辊制砂机等核心装备。相较于30年前仅提供单一筛分设备，该企业已成功转型为覆盖破碎、筛分、制砂全工艺流程的系统服务商。","scd":null,"kp":[]},{"i":43941,"as":"2026年第四届中国长时储能大会将升级为展览会，并由能源央企国家队联合主办。大会主办方推出专属福利，液流电池企业付费参会满四人即赠送9平方米标准展台。此举旨在战略扶持液流电池产业，帮助其在长时储能大市场中精准对接电网、发电集团等项目资方与EPC资源，抱团提升行业话语权，应对初始投资偏高及锂电长时化挤压的挑战。","scd":null,"kp":[]},{"i":43942,"as":"由哈电锅炉承揽的苏尼特左旗100MW/400MWh压缩空气储能示范项目取得重要进展。项目核心设备——容积3200m³的高温水球罐与容积2800m³的低温水球罐一次性顺利通过水压试验。这是哈电锅炉首台球罐项目。该新型压缩空气储能项目不依赖化石燃料，投运后将有效提升新能源消纳能力，减少温室气体排放，为内蒙古能源绿色转型提供新动能。","scd":null,"kp":[]},{"i":43943,"as":"山东肥城100MW/400MWh超临界二氧化碳高温热力电池储能示范项目工程勘察中标候选人于6月12日公示。招标范围涵盖工程勘察、后续配合设计、施工服务及配合竣工验收等全流程内容。这标志着该超临界二氧化碳高温热力电池储能项目的前期工程勘察工作即将正式展开，推进项目实质性落地。","scd":null,"kp":[]},{"i":43944,"as":"云南省投资促进局发布第二批省级重点招商项目，其中包括峨山县年产3GW/12GWh全钒液流电池全产业链生产线项目。该项目将依托云南丰富的钒资源及绿色能源基础，打造集核心材料、电堆制造于一体的全产业链生产线。2026年5月，峨山县政府已与上海猷鑫能源科技公司就该全钒液流电池生产线项目的落地进行了洽谈。","scd":null,"kp":[]},{"i":43945,"as":"","scd":null,"kp":[]},{"i":43946,"as":"麻省理工学院团队开发出一种双模式太空推进系统，小型卫星可利用单一燃料箱同时为化学推进器和电推进器提供动力。该系统采用环保型ASCENT推进剂，兼具快速机动与高效长距离飞行能力。相关论文已发表于《Journal of Propulsion and Power》。NASA计划于今年11月发射立方体卫星进行该系统的首次在轨验证，有望使低成本小型卫星执行深空探测及火星任务。","scd":null,"kp":[]},{"i":43947,"as":"英国初创公司Ignota Labs收购了停止运营的生物技术公司Kronos Bio的全部临床资产，计划利用自研的AI平台SAFEPATH诊断药物失败的根本原因。该平台通过分析分子结构、蛋白质结合、临床不良反应等多模态数据，寻找跨层级关联。Ignota Labs将对失败药物分子结构进行定向修改以解决肝毒性、心脏毒性等安全性问题，使其重新进入临床，实现药物复活。","scd":null,"kp":[]},{"i":43948,"as":"麻省理工学院（MIT）与伍兹霍尔海洋研究所（WHOI）联合开发了名为Sonar-MASt3R的水下测绘系统。该系统将声呐传感器的声学数据与光学摄像头的视觉图像融合，解决了水下机器人作业时因泥沙搅动导致视野浑浊的问题，可在低能见度的浑浊水域中实时生成精细的三维地图。该技术已入选ICRA最佳论文候选名单，核心应用于水下未爆弹药清除等场景，显著提升水下作业效率与安全性。","scd":null,"kp":[]},{"i":43949,"as":"中广核格尔木350兆瓦光热示范项目在青海格尔木正式开工建设，总投资50亿元。该项目是全球单机储热容量最大、镜场面积最大的光热电站，年发电量约10亿千瓦时，储能时长达15小时。项目采用熔盐塔槽结合技术路线，应用了中广核自主研发的全球开口最大（8.6米）光热熔盐槽式集热器成套装备，核心技术实现100%自主可控。建成后每年等效节约标煤32万吨、减排二氧化碳86万吨。","scd":null,"kp":[]},{"i":43950,"as":"国家发展改革委等5部门发布《关于开展重点行业节能降碳改造攻坚三年行动的通知》。通知明确自2026年起，以钢铁、电解铝、煤电等9个行业为重点实施节能降碳改造。针对煤电行业，通知要求推动具备条件的30万千瓦（300MW）以上现役煤电机组通过耦合新能源、掺烧生物质、加装储能储热设施等方式实施低碳化改造，目标为改造后度电碳排放降低10%-20%，力争降低20%以上。","scd":null,"kp":[]},{"i":43951,"as":"碳捕集与封存协会（CCSA）联合50个行业利益相关方发布公开信，敦促欧盟委员会和英国政府为跨境碳捕集、利用与封存（CCUS）项目提供明确的监管规则。公开信呼吁双方在下一届欧盟-英国峰会前完成排放交易体系（ETS）链接谈判，指出目前监管透明度的缺失导致跨境CO2运输和封存的法律认可未定，已减缓相关基础设施项目的开发与投资决策。签署方要求政策制定者提供清晰的ETS链接实施路线图。","scd":null,"kp":[]},{"i":43952,"as":"碱性水电解槽本体的短时极限爬坡速率普遍可达5%额定负荷/秒，但在实际风光制氢项目中，分布式控制系统（DCS）通常将负荷调节速率限制在2%/秒。工程限制的核心原因在于后端气液分离、纯化及压缩储存装置缺乏瞬时过载缓冲能力，速率过高会引发碱雾夹带和系统超压。同时，频繁的功率快速波动会加剧槽内气液扰动、产生热应力损伤并导致电极催化层剥落，大幅缩短电解槽的使用寿命。","scd":null,"kp":[]},{"i":43953,"as":"国务院新闻办公室发布《国家人权行动计划（2026—2030年）》，重点推动工商业与人权结合，鼓励企业在国内外经营中尊重和保护人权。该计划为企业应对以欧盟《企业可持续发展尽责指令》（CSDDD）为代表的海外强制性合规要求提供了制度性参照。文件强调海内外合规体系协同，明确要求企业对供应链上下游的潜在人权影响承担责任，并积极参与国际规则制定，以适应全球市场的人权尽职调查准入要求。","scd":null,"kp":[]},{"i":43954,"as":"NASA加州埃姆斯研究中心的科研人员发表论文指出，全新的球面巡天望远镜（SPHEREx）在观测中受到严重的人造卫星光轨干扰。在去年5月至9月期间拍摄的图像中，有73.3%至少出现了一条卫星留下的光轨污染，单次曝光平均拍到2.18条卫星轨迹。由于SPHEREx需长时间曝光且覆盖大片天区，其搭载的自动化斜坡采样防宇宙射线算法被高亮度商用卫星直接激活，导致中心强光数据被抹除且残留平行亮线，目前缺乏有效的消除手段。","scd":null,"kp":[]},{"i":43955,"as":"IEEE Open Journal of Vehicular Technology发表了由奥胡斯大学等多所机构联合撰写的专题文章，全面探讨了下一代非地面网络（NTN）中无人机（UAV）与物理层安全的必要性。论文系统介绍了非地面网络无线通信物理层安全的最新研究进展，详细分析了无人机安全在当前阶段面临的潜在挑战与开放性研究问题，为移动无线电和陆地交通领域的电气与电子工程研究提供了理论基础和未来研究方向。","scd":null,"kp":[]},{"i":43956,"as":"近期AI及相关科技企业正掀起一股首次公开募股（IPO）热潮。SpaceX近期完成上市，创下史上规模最大IPO。科技媒体指出，SpaceX的上市不仅吸纳了大量二级市场资金，还在试探上市公司治理中单一创始人掌控的边界。受此资本热潮传导效应影响，OpenAI与Anthropic等竞争对手预计也将登陆资本市场。此外，许多初创企业正试图通过效仿SpaceX带火的“轨道数据中心”等新概念，在此次融资浪潮中吸引投资。","scd":null,"kp":[]},{"i":43957,"as":"腾讯研究院发布的深度报告指出，当前企业面临AI投资回报困境。美国国家经济研究局（NBER）等实证数据显示，高达95%的企业看不到AI投资回报，仅6%实现显著利润提升，80%的AI投入未见效果。尽管全球AI资本支出已超万亿美元，话语体系中充斥着转型焦虑，但数据表明AI实际商业应用尚处早期。研究构建了包含17个变量的分析框架，旨在为决策者提供评估AI时代企业组织变革边界、构建竞争优势的认知方法论。","scd":null,"kp":[]},{"i":43958,"as":"天合光能自主研发的工业标准尺寸（3.1㎡）钙钛矿/晶硅叠层组件，经TÜV SÜD认证，峰值功率达到907W，全面积转换效率达29.2%，成功刷新全球叠层组件功率世界纪录。该组件基于210mm大尺寸硅片打造，贴合现有产线标准，并通过优化狭缝涂布与蒸汽辅助结晶工艺提升了薄膜均匀性。同时，天合光能旗下BIPV板块子公司天合绿建顺利完成天使+轮融资，推出TEG彩色光电玻璃Ultra，实现从技术突破到场景落地的转化。","scd":null,"kp":[]},{"i":43959,"as":"科力远控股子公司拟投资4.4亿元在河北省保定市建设100MW/400MWh混合独立储能电站试点项目。该项目包含90MW/360MWh磷酸铁锂电池储能系统和10MW/40MWh固态电池储能系统，建设周期预计8个月。项目旨在缓解区域电网调峰压力，通过容量电价、峰谷套利及辅助服务等多元模式获取收益。科力远正将新型储能确立为核心增长方向，目前公司在山东、河北等地储备的储能项目规模已超过15GWh。","scd":null,"kp":[]},{"i":43960,"as":"国内大模型企业DeepSeek完成首次外部融资，募资额超500亿元人民币，估值超3380亿元，创下国内AI行业最大规模融资记录。为确保CEO梁文锋的绝对控制权，融资采用有限合伙结构：外部投资者资金投入梁文锋管理的有限合伙企业且不享有投票权，所有股份锁定五年。梁文锋个人出资200亿元，腾讯投资100亿元，宁德时代投资50亿元。唯一例外是国家人工智能产业投资基金直接投资10亿元并享有投票权且不受锁定期限制。","scd":null,"kp":[]},{"i":43961,"as":"新加坡国立大学研究团队提出了XtraGPT模型，重新定义了AI在学术写作中的角色。XtraGPT不主张直接从零生成论文，而是定位为上下文感知、可控的学术论文修改协作工具。与仅能润色文字的通用大语言模型不同，该模型旨在帮助作者在已有初稿的基础上，根据学术共同体的标准对论文进行更严谨的逻辑、一致性修改与完善。该研究及相关开源模型（XtraGPT-14B）已被ACL 2026顶会接收。","scd":null,"kp":[]},{"i":43962,"as":"上海人工智能实验室发布了开源框架AgentDoG 1.5，专门面向AI Agent的安全诊断与在线干预。随着AI Agent从单纯的聊天助手转变为接管具体工作的执行单元，安全风险已从单纯的内容合规演变为完整执行过程中的行为诊断问题。风险可能隐藏在工具调用、环境反馈或长期记忆中。AgentDoG 1.5将安全监测模式从“检查输出内容”转变为“检查完整执行轨迹”，实现了轻量化、可扩展的Agent执行过程风险归因与在线护栏干预。","scd":null,"kp":[]},{"i":43963,"as":"Energy Dome与美国盐河项目公司（SRP）达成合作，计划在美国亚利桑那州建设一套19MW/190MWh的二氧化碳长时储能系统。该项目具备10小时储能时长，选址于Coronado发电站，采用20年容量租赁模式。Energy Dome负责投资与运营，SRP负责电网调度。谷歌通过成本分摊机制为该项目提供资金支持，以推动非锂长时储能技术的规模化验证与推广，深化在新型电网侧储能领域的合作。","scd":null,"kp":[]},{"i":43964,"as":"随着全球氢能需求激增与淡水资源短缺，海水制氢正成为重要发展趋势。利用海上风电和光伏绿电进行海水淡化后电解或直接电解海水，能有效解决水资源瓶颈和深远海电力传输损耗问题。国家能源集团、中石化、谢和平院士团队及东方电气等国内多家机构与企业在该领域连续取得重大技术突破，成功产出首批绿色甲醇。国内海水制氢产业化在即，并有望结合海上氨醇技术与长时储能催生全新万亿级海上能源岛市场。","scd":null,"kp":[]},{"i":43965,"as":"安思卓成功中标中煤平朔采煤沉陷区60万千瓦离网式可再生能源制氢一期项目（绿氢耦合煤化工部分）。该项目采用离网光伏制氢模式，直接为煤化工生产供应绿氢。安思卓将为该项目提供4台1200Nm³/h电解槽、1套4800Nm³/h气液分离与纯化系统，并配套部署“4对1”柔性制氢系统解决方案。该项目的落地验证了安思卓电解槽在大型离网、波动工况下的系统集成与适配能力。","scd":null,"kp":[]},{"i":43966,"as":"","scd":null,"kp":[]},{"i":43967,"as":"ACS Catalysis发表的研究表明，通过手性相互作用诱导氮掺杂Co3O4定向暴露高活性的(111)晶面，可显著提升天然海水析氧反应（OER）的性能。该材料（N-L-Co3O4）利用自旋选择效应和晶面取向调控电子结构，在增强OH-吸附的同时降低了Cl-吸附，有效抑制了氯氧化副反应和氯离子腐蚀。在1.0 M KOH中，该材料在500 mA cm-2工业级电流密度下稳定运行近500小时。在天然海水中，其在1.70 V下的电流密度达到商业RuO2的4.3倍。","scd":null,"kp":[]},{"i":43968,"as":"美国初创公司Endurance Energy完成5400万美元A轮融资，由Founders Fund领投。公司专注于开发海底火山型地热能技术，已在深海火山系统完成4次原型部署，最大深度达3300米，最高耐受热液温度386℃。本轮融资将用于从原型验证转向完整百千瓦级系统开发，扩大海上作业能力。公司计划今年秋季在胡安·德富卡洋中脊部署100千瓦发电机，并与汤加政府签署协议探索岛国海底地热资源商业化应用。","scd":null,"kp":[]},{"i":43969,"as":"中国人文社会科学期刊评价图书馆、情报与档案学专家委员会换届与期刊建设研讨会顺利召开。会议由中国社会科学评价研究院与《现代情报》等相关机构参与组织。","scd":null,"kp":[]},{"i":43970,"as":"浙江大学研究团队发表关于金属硒化物在超级电容器中应用的综述。金属硒化物具备高本征电导率、可调多层级结构及丰富氧化还原活性位点，是极具潜力的新兴电极材料。文章总结了其物理化学性质、热液法与化学气相沉积等合成技术，以及包含双电层电容和赝电容行为的储能机制。详细介绍了单/双金属硒化物的电化学性能，并提出复合改性、形貌工程和界面工程等性能提升策略。尽管具备能量密度优势，该材料仍面临体积膨胀、活性物质溶解及成本高的挑战。","scd":null,"kp":[]},{"i":43971,"as":"锂离子电池嵌锂动力学测试方法在学术界存在长达45年的争议。争议核心在于不同文献采用的测试与分析方法存在差异，难以获取嵌脱锂反应真实的电流-过电位关联规律。嵌储型材料在充放电时伴随组分变化、氧化还原电位偏移、反应活性面积改变及化学电容特性，导致测试只能在瞬态下进行。此外，区分不同动力学模型必须依赖高过电位区间的非线性特征，但电位偏移在此区间产生的测量误差达到峰值。现有各类测量方案均存在固有缺陷，无法完全还原嵌脱锂反应本征的电荷转移动力学规律。","scd":null,"kp":[]},{"i":43972,"as":"北京理工大学与北京工业大学联合团队提出一种电流间歇弛豫法（脉冲电流工作模式），以提升单晶高镍锂电正极（SC-NCM）性能。该策略无需化学改性，通过引入周期性弛豫区间动态调控锂离子输运与晶体结构演变。测试表明，优化后的脉冲电流使材料首次放电容量提升10.6%，300次循环容量保持率显著优于恒流模式。机理分析证实，该方法有效缓解了锂离子浓差极化、抑制岩盐相生成并降低局部应力，稳定了关键相变过程。该策略在-20℃低温、4.6V高电压及安时级软包电池等工况下均表现良好。","scd":null,"kp":[]},{"i":43973,"as":"近期中央政治局会议与国务院常务会议明确要求加强水网、新型电网、算力网、新一代通信网、城市地下管网、物流网等规划建设，正式将上述“六张网”纳入国家顶层部署范畴。","scd":null,"kp":[]},{"i":43974,"as":"发表于《PNAS》的研究结合GAINS空气污染与健康效应模型和WILIAM系统动力学综合评估模型，重新评估了欧盟能源价格上涨背景下的能源转型战略。研究指出，短期依赖煤炭或生物质替代天然气虽能缓解缺口，但会带来健康与经济代价。长期来看，在能源高价背景下，加速可再生能源和电气化转型更具成本有效性。结论强调，危机时期不应回退至化石能源，而应利用价格信号推动结构性转型。","scd":null,"kp":[]},{"i":43975,"as":"发表于《Nature Sustainability》的研究建立了包含全球555,960座水库的高分辨率清单，重新评估了泥沙淤积对全球水库库容的损耗。研究表明，全球水库平均每十年损失约7.3%的库容，每年因淤积损失的蓄水空间约36.1立方公里。被遗漏的小水库因多位于侵蚀强、干旱及农业高度依赖区，加剧了整体损耗风险。中东、美国西南部、中国北方等干旱半干旱区淤积速度最快。在28个国家，水库每十年损失的库容超过10%。","scd":null,"kp":[]},{"i":43976,"as":"工信部与国务院国资委联合印发通知，启动2026年度人形机器人与具身智能实景实训专项行动。行动坚持应用牵引，面向工业、特种、服务等领域重点场景，推进实景实训空间建设、创新应用联合体培育与作业技能攻关。目标是至2026年底凝练百个以上高价值应用场景，形成万台级规模落地能力。同时支持联合体参与标准化技术委员会工作，强化关键标准贯标落地，标志着我国人形机器人产业正式从技术研发迈入规模化应用阶段。","scd":null,"kp":[]},{"i":43977,"as":"龙源电力江苏盐城大丰H20#海上风电项目正式获得核准批复，转入建设阶段。项目离岸距离约79公里，规划装机规模40.7万千瓦，拟安装37台单机容量11.0兆瓦风电机组，总投资约46.14亿元。项目配套新建一座220千伏海上升压站，核心创新在于采用“风渔融合”模式，在风电场中部建设海洋牧场，实现清洁电力生产与海洋渔业养殖集约化立体开发，构建“发电—养殖—生态修复”的良性循环。","scd":null,"kp":[]},{"i":43978,"as":"SpaceX首次公开募股（IPO）最终合计融资约857亿美元，市值约2.1万亿美元。公司以每股135美元的发行价筹得750亿美元，创下历史最大单笔IPO纪录。上市首日股价大涨19%，盘后进一步上涨。资金将主要用于“星舰”系列火箭研发与商业化运营、扩展星链卫星互联网服务、建设轨道数据中心，并与特斯拉和英特尔在得州合作建设芯片工厂。此外，最新研究数据表明“Z世代”（95后与00后）的单身比例显著高于同龄时期的千禧一代。","scd":null,"kp":[]},{"i":43979,"as":"为应对AI数据中心引发的电力需求激增，美国能源部宣布投入最高3.5亿美元用于新建、改造及重新启用煤电厂，提供约3565兆瓦基荷电力，并追加1.75亿美元用于六座运行电厂的设备现代化。这轮煤电现代化重构的核心集中在涡轮机械与热力系统，包括蒸汽轮机转子更换、发电机翻修、锅炉与热效率系统改造，以及SCR催化剂更新等环保排放系统升级，以提升机组燃料利用效率与整体可靠性。","scd":null,"kp":[]},{"i":43980,"as":"有报道称爆款AR手游《宝可梦Go》开发商Niantic利用玩家上传的300亿张实景环境图像和空间数据，与涉及军工国防场景的合作方Vantor共同训练可用于无人机导航的人工智能系统。对此，拥有该数据的Niantic Spatial与Vantor均发表声明予以否认，明确表示共享游戏数据不在双方合作协议范围内，Vantor未使用且无法访问相关数据集。《宝可梦Go》中的位置扫描功能为可选活动，且已随游戏业务出售从游戏中移除。但Niantic多年来积累的现实世界图像和空间数据仍保留在Niantic Spatial手中。","scd":null,"kp":[]},{"i":43981,"as":"当前全球抗衰药物规模化研发面临进展缓慢的瓶颈，实验验证的抗衰老化合物仅约1000种。为突破这一实验科学试错漫长的局限，多机构联合研究团队在《Ageing Research Reviews》发表综述，系统定义了由AI视觉推理、自动化机器人平台以及高通量体内筛选（HTS）构成的抗衰药物研发新范式——“自动驾驶”管线。该研发体系旨在将抗衰药物研发转变为一门高效、精准的工程学。","scd":null,"kp":[]},{"i":43982,"as":"《中国能源大数据报告（2026）》指出，中国能源低碳转型取得里程碑进展，电力系统从“增量替代”迈向“存量替代”新阶段。数据显示，2025年非化石能源装机占比首次超越煤电，风电与太阳能合计装机成为第一大电源。能源消费结构持续优化，煤炭消费比重降至52.7%，清洁能源消费比重升至29.6%。在GDP突破140万亿元的背景下，我国实现万元GDP能耗同比下降3.2%、碳排放同比下降3.9%的双重提升。","scd":null,"kp":[]},{"i":43983,"as":"“算电协同”于2026年被写入国家工作报告。我国东部算力需求旺盛但绿电匮乏，西部“沙戈荒”地区风光资源丰富但消纳能力滞后，空间错位亟待双向资源匹配。截至2025年末，我国智能算力规模超1590EFLOPS，电力成本占AI数据中心运营成本60%以上。算电协同通过让算力负荷跟随绿色电力的供给节奏运作，推动AI数据中心向电力系统柔性调节资源转变，实现从“电支撑算”到“算优化电”的系统性跨越。","scd":null,"kp":[]},{"i":43984,"as":"国际能源研究中心陈俊儒探讨了新型电力系统下构网型储能的需求与配置问题。","scd":null,"kp":[]},{"i":43985,"as":"美国政府正试图通过出口管制收紧外籍研究人员参与最先进AI模型开发的权利。此前Anthropic收到禁令，不仅封杀了外部用户，也将其内部的非美国籍员工排除在接触前沿模型之外。硅谷AI产业有66%的科技从业者海外出生，出生于斯洛洛伐克的AI专家Andrej Karpathy入职Anthropic不到一个月，即面临因非美国公民身份被公司最强模型拒之门外的处境。整个AI行业正与政府博弈以保住外籍研究员的参与资格。","scd":null,"kp":[]},{"i":43986,"as":"因被指存在严重的“越狱”风险，美国商务部对Anthropic旗下Fable 5和Mythos 5两款顶级大模型下达出口管制令，Anthropic被迫在90分钟内切断全球访问。随后，Anthropic派遣AI安全领域资深专家团队前往华盛顿与政府进行生死谈判，百位顶尖专家联名上书。但最终谈判宣告破裂，出口管制未能解除，这两款全球最强大的模型继续处于全网封杀停服状态。","scd":null,"kp":[]},{"i":43987,"as":"","scd":null,"kp":[]},{"i":43988,"as":"国家发展改革委等5部门联合印发通知，决定开展钢铁、电解铝、水泥、煤电等重点行业节能降碳改造攻坚三年行动。通知明确要求，推动30万千瓦以上现役煤电机组通过耦合新能源、加装储能储热等方式实施低碳化改造。此举旨在加快重点行业绿色低碳转型，支撑实现碳达峰碳中和目标，同时扩大有效投资与促进产业提质升级。","scd":null,"kp":[]},{"i":43989,"as":"江西洲铁独立储能示范项目预计6月底建成并网投运。该项目总投资3.59亿元，是江西省首个“飞轮+锂电”混合储能示范工程。整体规划规模为100MW/162.5MWh，采用20MW飞轮储能系统与80MW锂电储能系统精准搭配。项目创新采用“飞轮抢速、锂电稳频”协同运行策略，利用飞轮毫秒级响应、长寿命及锂电容量优势实现互补增效，破解单一储能技术应用短板。","scd":null,"kp":[]},{"i":43990,"as":"据中国能源研究会储能专委会数据，中国一季度新增电力储能装机10.9GW（27.1GWh），同比增长41%。新型储能占据几乎全部新增容量。储能市场结构发生显著转变，独立储能成为新增主力，一季度投运8.7GW/23.0GWh，功率同比增长174%，占新增功率装机的83%。相比之下，新能源配储和用户侧储能装机均出现下降。电网侧和发电侧新型储能新增装机占比达到95%。","scd":null,"kp":[]},{"i":43991,"as":"百穰新能源在第七届“高新杯”颁奖典礼上荣获“十大上市潜力企业”奖。公司深耕二氧化碳储能技术，成功打造了芜湖海螺10MW/80MWh和华电木垒100MW/1000MWh等二氧化碳储能示范项目。在技术研发方面，百穰新能源已累计获得100余项授权专利，其中发明专利占比超70%，多项核心技术获得美、欧、加等多国专利授权。","scd":null,"kp":[]},{"i":43992,"as":"广西桂冠山东公司潍坊滨海200MW/400MWh复合储能电站一期（101MW/200MWh）的飞轮系统采购中标结果正式公示。","scd":null,"kp":[]},{"i":43993,"as":"辽水新能抚顺100MW/400MWh压缩空气储能与飞轮储能组合项目的建设监理服务中标结果正式公告。","scd":null,"kp":[]},{"i":43994,"as":"6月15日，世界最高混凝土面板堆石坝电站——华电金上拉哇水电站大坝二期面板浇筑完成。该电站最大坝高242.5米，总装机容量200万千瓦。项目团队集成应用低热低碱水泥、VF防裂剂与玄武岩纤维三元防裂体系，将混凝土内外温差控制在20摄氏度以内，各项浇筑指标均优于设计标准，目前正全力冲刺下闸蓄水目标。","scd":null,"kp":[]},{"i":43995,"as":"由国际地热标准委员会（IGSC）编制的《地热术语》在2026年世界地热大会上正式发布，这是全球地热行业首个统一术语标准。该标准收录了207条核心术语，涵盖勘查、钻完井、供暖、发电等8大类，整合了多国术语体系，消除了国际交流翻译歧义，为跨国技术交流和投融资提供了通用规范。","scd":null,"kp":[]},{"i":43996,"as":"国际可再生能源署（IRENA）发布报告指出，全球能源转型已进入以电气化、可再生能源和淘汰化石燃料为核心的新阶段。修订后的1.5°C情景预计，到2035年电力消费在全球能源消费中的占比将升至35%，2050年超50%，且新增需求主要由可再生能源满足。同时，化石燃料占比将从目前的80%降至2050年的20%或更低。","scd":null,"kp":[]},{"i":43997,"as":"中性原子量子计算公司QuEra宣布将于2028年推出名为Libra的容错量子计算机。该系统属于Megaquop级，设计指标包含超256个纠错逻辑量子比特，逻辑错误率目标为10⁻⁶，可执行超100万次可靠逻辑量子操作。Libra将集成至AWS云端，首批应用锚定量子化学、高能物理模拟和新材料计算领域。","scd":null,"kp":[]},{"i":43998,"as":"Gartner指出2026年企业AI智能体将加速落地，但应用成熟度存在显著差异。当前多数AI智能体仍处于大模型增强工作流阶段，尚未达到真正的自主智能体标准。企业在推进落地时，需结合智能体能力与运行环境制定差异化策略，并优先投入建设长期核心资产而非追逐短期技术。","scd":null,"kp":[]},{"i":43999,"as":"南京大学谭海仁教授团队在全钙钛矿叠层太阳能电池领域取得突破，其研发的叠层电池世界纪录效率9次被“Solar cell efficiency tables”收录，相关最新成果发表于《Nature》。谭海仁教授获国家杰青资助，并创立“仁烁光能”，已建立全球首条大面积全钙钛矿叠层电池研发线及150MW量产线，积极推进产业化。","scd":null,"kp":[]}]);